/* Ví dụ & cách dùng cho từ vựng: window.VOCAB_EXAMPLES[词] = {en, exs:[{use,ex,py,vi,en}]} */
window.VOCAB_EXAMPLES = {"羡慕":{"en":"to envy; to admire","exs":[{"use":"羡慕 + người / điều gì đó.","ex":"很多人都羡慕他的生活。","py":"Hěn duō rén dōu xiànmù tā de shēnghuó.","vi":"Nhiều người ngưỡng mộ cuộc sống của anh ấy.","en":"Many people envy his lifestyle."},{"use":"羡慕 + người + 能/有 + việc gì: ngưỡng mộ ai có thể làm gì.","ex":"我很羡慕你能去国外留学。","py":"Wǒ hěn xiànmù nǐ néng qù guówài liúxué.","vi":"Tôi rất ngưỡng mộ bạn có thể đi du học nước ngoài.","en":"I really envy that you can study abroad."},{"use":"羡慕 + người + 的 + danh từ: ao ước thứ người khác có.","ex":"她羡慕姐姐的好成绩。","py":"Tā xiànmù jiějie de hǎo chéngjì.","vi":"Cô ấy ao ước điểm số tốt của chị gái.","en":"She envies her older sister's good grades."},{"use":"让人羡慕: làm người khác ao ước (dạng tính từ hóa).","ex":"这份工作让人羡慕。","py":"Zhè fèn gōngzuò ràng rén xiànmù.","vi":"Công việc này khiến người ta ao ước.","en":"This job makes people envious."}]},"浪漫":{"en":"romantic","exs":[{"use":"Miêu tả tình cảm, không khí hoặc con người.","ex":"这个晚上过得很浪漫。","py":"Zhège wǎnshang guò de hěn làngmàn.","vi":"Buổi tối này trôi qua thật lãng mạn.","en":"This evening was very romantic."},{"use":"Dùng để miêu tả tính cách hoặc bầu không khí.","ex":"这是一个浪漫的故事。","py":"Zhè shì yí gè làngmàn de gùshi.","vi":"Đây là một câu chuyện lãng mạn.","en":"This is a romantic story."},{"use":"浪漫的 + danh từ (惊喜, 约会...): bổ nghĩa cho danh từ.","ex":"他给妻子准备了一个浪漫的惊喜。","py":"Tā gěi qīzi zhǔnbèi le yí gè làngmàn de jīngxǐ.","vi":"Anh ấy chuẩn bị cho vợ một bất ngờ lãng mạn.","en":"He prepared a romantic surprise for his wife."},{"use":"是一个很浪漫的人: miêu tả tính cách con người.","ex":"她是一个很浪漫的人，喜欢送花。","py":"Tā shì yí gè hěn làngmàn de rén, xǐhuan sòng huā.","vi":"Cô ấy là người rất lãng mạn, thích tặng hoa.","en":"She is a very romantic person who loves giving flowers."}]},"爱情":{"en":"love (romantic); romance","exs":[{"use":"Chỉ tình yêu giữa nam và nữ.","ex":"他们的爱情故事很感人。","py":"Tāmen de àiqíng gùshi hěn gǎnrén.","vi":"Câu chuyện tình yêu của họ rất cảm động.","en":"Their love story is very touching."},{"use":"爱情 làm chủ ngữ: nói về tình yêu nói chung.","ex":"爱情需要两个人一起努力。","py":"Àiqíng xūyào liǎng gè rén yìqǐ nǔlì.","vi":"Tình yêu cần hai người cùng nỗ lực.","en":"Love takes effort from both people."},{"use":"爱情 + 电影 / 小说: làm định ngữ cho danh từ.","ex":"我喜欢看爱情电影。","py":"Wǒ xǐhuan kàn àiqíng diànyǐng.","vi":"Tôi thích xem phim tình cảm.","en":"I like watching romance movies."},{"use":"把爱情看得…: dùng với 把 và bổ ngữ trạng thái.","ex":"年轻人常常把爱情看得很重要。","py":"Niánqīngrén chángcháng bǎ àiqíng kàn de hěn zhòngyào.","vi":"Người trẻ thường coi tình yêu rất quan trọng.","en":"Young people often see love as very important."}]},"加班":{"en":"to work overtime","exs":[{"use":"Động từ ly hợp: 加班 / 加了两个小时的班.","ex":"他今天要加班到很晚。","py":"Tā jīntiān yào jiābān dào hěn wǎn.","vi":"Hôm nay anh ấy phải làm thêm đến rất muộn.","en":"He has to work overtime until very late today."},{"use":"加班 làm vị ngữ, nói về tình trạng thường xuyên.","ex":"最近公司很忙，我们天天加班。","py":"Zuìjìn gōngsī hěn máng, wǒmen tiāntiān jiābān.","vi":"Gần đây công ty rất bận, ngày nào chúng tôi cũng làm thêm giờ.","en":"The company has been busy lately, so we work overtime every day."},{"use":"Bổ ngữ thời lượng đặt sau: 加班 + 加了 + số giờ.","ex":"昨天我加班加了三个小时。","py":"Zuótiān wǒ jiābān jiā le sān gè xiǎoshí.","vi":"Hôm qua tôi làm thêm ba tiếng.","en":"I worked three hours of overtime yesterday."},{"use":"别 + 加班 + …: lời khuyên, nhắc nhở.","ex":"别加班太晚，要注意身体。","py":"Bié jiābān tài wǎn, yào zhùyì shēntǐ.","vi":"Đừng làm thêm quá muộn, phải chú ý sức khỏe.","en":"Don't work overtime too late; take care of your health."}]},"感动":{"en":"to move (emotionally); moved, touched","exs":[{"use":"让 / 使 + người + 感动.","ex":"这件事让我很感动。","py":"Zhè jiàn shì ràng wǒ hěn gǎndòng.","vi":"Chuyện này khiến tôi rất cảm động.","en":"This made me feel very moved."},{"use":"Động từ có tân ngữ: 感动 + người (nghĩa: làm ai cảm động).","ex":"他的话感动了所有人。","py":"Tā de huà gǎndòng le suǒyǒu rén.","vi":"Lời nói của anh ấy làm mọi người cảm động.","en":"His words moved everyone."},{"use":"V + 得 (bổ ngữ trạng thái): 感动得 + kết quả.","ex":"看完这部电影，我感动得哭了。","py":"Kànwán zhè bù diànyǐng, wǒ gǎndòng de kū le.","vi":"Xem xong bộ phim này, tôi cảm động đến khóc.","en":"After watching this movie, I was so moved that I cried."},{"use":"Tính từ: 很感动 làm vị ngữ, chỉ cảm xúc.","ex":"她很感动，半天说不出话来。","py":"Tā hěn gǎndòng, bàntiān shuō bu chū huà lái.","vi":"Cô ấy rất cảm động, mãi không nói nên lời.","en":"She was so touched that she couldn't speak for a while."}]},"简单":{"en":"simple; easy","exs":[{"use":"Chỉ việc hoặc cách làm không phức tạp.","ex":"这个问题很简单。","py":"Zhège wèntí hěn jiǎndān.","vi":"Vấn đề này rất đơn giản.","en":"This question is very simple."},{"use":"简单 làm vị ngữ, nói về cách làm / công thức.","ex":"这道菜做法很简单，你也会做。","py":"Zhè dào cài zuòfǎ hěn jiǎndān, nǐ yě huì zuò.","vi":"Món này cách làm rất đơn giản, bạn cũng làm được.","en":"This dish is easy to make; you can cook it too."},{"use":"简单地 + động từ: làm trạng ngữ, nghĩa \"một cách sơ lược\".","ex":"她简单地介绍了一下自己。","py":"Tā jiǎndān de jièshào le yíxià zìjǐ.","vi":"Cô ấy giới thiệu sơ qua về bản thân.","en":"She briefly introduced herself."},{"use":"简单的 + danh từ: nói về lối sống, đồ vật không rườm rà.","ex":"我只想过简单的生活。","py":"Wǒ zhǐ xiǎng guò jiǎndān de shēnghuó.","vi":"Tôi chỉ muốn sống một cuộc sống giản dị.","en":"I just want to live a simple life."}]},"幸福":{"en":"happy; happiness","exs":[{"use":"Có thể làm tính từ hoặc danh từ.","ex":"他们过着幸福的生活。","py":"Tāmen guòzhe xìngfú de shēnghuó.","vi":"Họ sống một cuộc sống hạnh phúc.","en":"They are living a happy life."},{"use":"Tính từ: 觉得 + 很幸福.","ex":"有家人在身边，我觉得很幸福。","py":"Yǒu jiārén zài shēnbiān, wǒ juéde hěn xìngfú.","vi":"Có gia đình bên cạnh, tôi cảm thấy rất hạnh phúc.","en":"With my family by my side, I feel very happy."},{"use":"Danh từ làm chủ ngữ: 幸福 + 不一定 / 是 ...","ex":"幸福不一定要有很多钱。","py":"Xìngfú bù yídìng yào yǒu hěn duō qián.","vi":"Hạnh phúc không nhất thiết phải có nhiều tiền.","en":"Happiness doesn't necessarily require a lot of money."},{"use":"Lời chúc: 祝 + người + 幸福.","ex":"祝你们永远幸福！","py":"Zhù nǐmen yǒngyuǎn xìngfú!","vi":"Chúc hai bạn mãi mãi hạnh phúc!","en":"I wish you both happiness forever!"}]},"结婚":{"en":"to get married","exs":[{"use":"Động từ ly hợp: 结婚 / 结了婚, không đi kèm tân ngữ trực tiếp.","ex":"他们打算明年结婚。","py":"Tāmen dǎsuàn míngnián jiéhūn.","vi":"Họ dự định sang năm kết hôn.","en":"They plan to get married next year."},{"use":"Cấu trúc 是…的 nhấn mạnh thời gian kết hôn.","ex":"他们是去年结婚的。","py":"Tāmen shì qùnián jiéhūn de.","vi":"Họ kết hôn hồi năm ngoái.","en":"They got married last year."},{"use":"跟 / 和 + người + 结婚: kết hôn với ai (không nói 结婚她).","ex":"她想和相爱的人结婚。","py":"Tā xiǎng hé xiāng'ài de rén jiéhūn.","vi":"Cô ấy muốn kết hôn với người mình yêu.","en":"She wants to marry someone she loves."},{"use":"结婚 + khoảng thời gian + 了: đã cưới được bao lâu.","ex":"他们结婚十年了，感情还是很好。","py":"Tāmen jiéhūn shí nián le, gǎnqíng háishi hěn hǎo.","vi":"Họ cưới nhau mười năm rồi mà tình cảm vẫn rất tốt.","en":"They've been married for ten years and are still very close."}]},"自然":{"en":"natural; naturally; nature","exs":[{"use":"Trong bài: 很自然地 + động từ.","ex":"他说话很自然。","py":"Tā shuōhuà hěn zìrán.","vi":"Anh ấy nói chuyện rất tự nhiên.","en":"He speaks very naturally."},{"use":"Chỉ thế giới tự nhiên.","ex":"大自然很美。","py":"Dà zìrán hěn měi.","vi":"Thiên nhiên rất đẹp.","en":"Nature is very beautiful."},{"use":"Tính từ: 自然 + 一点儿, nghĩa tự nhiên, không gượng gạo.","ex":"在朋友面前，你不用紧张，自然一点儿。","py":"Zài péngyou miànqián, nǐ búyòng jǐnzhāng, zìrán yìdiǎnr.","vi":"Trước mặt bạn bè, bạn không cần căng thẳng, cứ tự nhiên một chút.","en":"You don't need to be nervous around friends; just be natural."},{"use":"Danh từ: 大自然, thường đi với 亲近 / 保护.","ex":"我周末喜欢去郊外亲近大自然。","py":"Wǒ zhōumò xǐhuan qù jiāowài qīnjìn dà zìrán.","vi":"Cuối tuần tôi thích ra ngoại ô gần gũi với thiên nhiên.","en":"On weekends I like going to the countryside to be close to nature."},{"use":"Phó từ: 自然 + 就 / 会, nghĩa \"tự khắc, đương nhiên\".","ex":"多练习，自然就会说好了。","py":"Duō liànxí, zìrán jiù huì shuō hǎo le.","vi":"Luyện tập nhiều, tự nhiên sẽ nói tốt thôi.","en":"With more practice, you'll naturally speak well."}]},"共同":{"en":"common; shared; jointly","exs":[{"use":"共同 + 的 + danh từ / 共同 + động từ.","ex":"我们有共同的爱好。","py":"Wǒmen yǒu gòngtóng de àihào.","vi":"Chúng tôi có sở thích chung.","en":"We share a common hobby."},{"use":"共同的 + danh từ: chung; 共同 + động từ: cùng nhau làm gì. Ví dụ: 共同努力。","ex":"我们有一个共同的目标。","py":"Wǒmen yǒu yí gè gòngtóng de mùbiāo.","vi":"Chúng tôi có một mục tiêu chung.","en":"We have a common goal."},{"use":"Phó từ: 共同 + động từ, nghĩa \"cùng nhau\".","ex":"大家共同努力，终于完成了任务。","py":"Dàjiā gòngtóng nǔlì, zhōngyú wánchéng le rènwu.","vi":"Mọi người cùng nhau nỗ lực, cuối cùng đã hoàn thành nhiệm vụ.","en":"Everyone worked together and finally completed the task."},{"use":"共同 + 照顾 / 生活 / 面对...: cùng chia sẻ trách nhiệm.","ex":"夫妻两个人共同照顾孩子。","py":"Fūqī liǎng gè rén gòngtóng zhàogù háizi.","vi":"Hai vợ chồng cùng nhau chăm sóc con.","en":"The couple take care of their child together."},{"use":"Cụm cố định: 共同语言 (tiếng nói chung).","ex":"我和他没有共同语言。","py":"Wǒ hé tā méiyǒu gòngtóng yǔyán.","vi":"Tôi và anh ấy không có tiếng nói chung.","en":"He and I have nothing in common to talk about."}]},"性格":{"en":"personality; character; temperament","exs":[{"use":"性格 + tính từ.","ex":"她的性格很开朗。","py":"Tā de xìnggé hěn kāilǎng.","vi":"Tính cách cô ấy rất cởi mở.","en":"She has a very cheerful personality."},{"use":"Chủ ngữ + 性格 + 不一样: so sánh tính cách.","ex":"我们俩性格不一样，但是是好朋友。","py":"Wǒmen liǎ xìnggé bù yíyàng, dànshì shì hǎo péngyou.","vi":"Hai chúng tôi tính cách khác nhau nhưng là bạn tốt.","en":"We have different personalities, but we're good friends."},{"use":"性格 + 内向 / 外向: mô tả kiểu tính cách.","ex":"他性格内向，不太爱说话。","py":"Tā xìnggé nèixiàng, bú tài ài shuōhuà.","vi":"Anh ấy tính cách hướng nội, không hay nói chuyện.","en":"He is introverted and doesn't talk much."},{"use":"A 比 B 更重要: dùng 性格 làm chủ ngữ trong câu so sánh.","ex":"找对象时，性格比外表更重要。","py":"Zhǎo duìxiàng shí, xìnggé bǐ wàibiǎo gèng zhòngyào.","vi":"Khi tìm người yêu, tính cách quan trọng hơn ngoại hình.","en":"When looking for a partner, personality matters more than looks."}]},"吸引":{"en":"to attract; to appeal to","exs":[{"use":"吸引 + người / sự chú ý.","ex":"这本书吸引了很多读者。","py":"Zhè běn shū xīyǐn le hěn duō dúzhě.","vi":"Cuốn sách này thu hút rất nhiều độc giả.","en":"This book attracted a lot of readers."},{"use":"吸引 + người / sự chú ý.","ex":"打折活动吸引了很多顾客。","py":"Dǎzhé huódòng xīyǐn le hěn duō gùkè.","vi":"Chương trình giảm giá thu hút rất nhiều khách hàng.","en":"The sale attracted lots of customers."},{"use":"吸引人: tính chất hấp dẫn, cuốn hút người khác.","ex":"她的笑容很吸引人。","py":"Tā de xiàoróng hěn xīyǐn rén.","vi":"Nụ cười của cô ấy rất cuốn hút.","en":"Her smile is very attractive."},{"use":"V + 着: kéo dài, thu hút liên tục.","ex":"这个城市吸引着世界各地的游客。","py":"Zhège chéngshì xīyǐnzhe shìjiè gèdì de yóukè.","vi":"Thành phố này thu hút du khách từ khắp nơi trên thế giới.","en":"This city attracts tourists from all over the world."},{"use":"被 + A + 吸引(住): bị cái gì cuốn hút.","ex":"我被这部电影吸引住了。","py":"Wǒ bèi zhè bù diànyǐng xīyǐn zhù le.","vi":"Tôi bị bộ phim này cuốn hút.","en":"I was captivated by this movie."}]},"丈夫":{"en":"husband","exs":[{"use":"Cách gọi trang trọng của 'chồng'; khẩu ngữ hay nói 老公.","ex":"她的丈夫是医生。","py":"Tā de zhàngfu shì yīshēng.","vi":"Chồng cô ấy là bác sĩ.","en":"Her husband is a doctor."},{"use":"我 / 她 + 丈夫: nói về chồng của mình hoặc người khác.","ex":"我丈夫每天开车送孩子上学。","py":"Wǒ zhàngfu měi tiān kāichē sòng háizi shàngxué.","vi":"Chồng tôi mỗi ngày lái xe đưa con đi học.","en":"My husband drives our child to school every day."},{"use":"和 + 丈夫 + 一起 + V: cùng chồng làm gì.","ex":"她和丈夫一起开了一家小饭馆。","py":"Tā hé zhàngfu yìqǐ kāi le yì jiā xiǎo fànguǎn.","vi":"Cô ấy cùng chồng mở một quán ăn nhỏ.","en":"She and her husband opened a small restaurant together."},{"use":"丈夫 làm chủ ngữ trong câu kể.","ex":"她丈夫出差了，下周才回来。","py":"Tā zhàngfu chūchāi le, xià zhōu cái huílái.","vi":"Chồng cô ấy đi công tác rồi, tuần sau mới về.","en":"Her husband is away on a business trip and won't be back until next week."}]},"幽默":{"en":"humorous; humor","exs":[{"use":"Miêu tả người hoặc cách nói chuyện.","ex":"他说话很幽默。","py":"Tā shuōhuà hěn yōumò.","vi":"Anh ấy nói chuyện rất hài hước.","en":"He speaks in a very humorous way."},{"use":"幽默的 + danh từ (người, nghề...).","ex":"他是一个很幽默的老师。","py":"Tā shì yí gè hěn yōumò de lǎoshī.","vi":"Anh ấy là một thầy giáo rất hài hước.","en":"He is a very funny teacher."},{"use":"幽默的人: dùng như chủ ngữ, nói chung chung.","ex":"幽默的人总是很受欢迎。","py":"Yōumò de rén zǒngshì hěn shòu huānyíng.","vi":"Người hài hước luôn được yêu mến.","en":"Humorous people are always popular."},{"use":"幽默的 + 笑话 / 故事: bổ nghĩa cho nội dung.","ex":"他讲了一个幽默的笑话，大家都笑了。","py":"Tā jiǎng le yí gè yōumò de xiàohua, dàjiā dōu xiào le.","vi":"Anh ấy kể một câu chuyện cười hài hước, ai cũng cười.","en":"He told a funny joke and everybody laughed."},{"use":"有幽默感: danh từ 幽默感 (khiếu hài hước).","ex":"她很有幽默感。","py":"Tā hěn yǒu yōumògǎn.","vi":"Cô ấy rất có khiếu hài hước.","en":"She has a great sense of humor."}]},"普通":{"en":"ordinary; common; average","exs":[{"use":"普通 + 的 + danh từ.","ex":"这是一件很普通的事。","py":"Zhè shì yí jiàn hěn pǔtōng de shì.","vi":"Đây là một chuyện rất bình thường.","en":"This is a very ordinary matter."},{"use":"普通的 + người / nghề nghiệp.","ex":"我只是一个普通的上班族。","py":"Wǒ zhǐshì yí gè pǔtōng de shàngbānzú.","vi":"Tôi chỉ là một nhân viên văn phòng bình thường.","en":"I'm just an ordinary office worker."},{"use":"普通话: tiếng phổ thông (Trung Quốc).","ex":"请用普通话再说一遍。","py":"Qǐng yòng pǔtōnghuà zài shuō yí biàn.","vi":"Xin hãy nói lại bằng tiếng phổ thông.","en":"Please say it again in Mandarin."},{"use":"普通 làm vị ngữ, hàm ý không nổi bật.","ex":"这家饭店的菜很普通，不太好吃。","py":"Zhè jiā fàndiàn de cài hěn pǔtōng, bú tài hǎochī.","vi":"Món ăn nhà hàng này rất bình thường, không ngon lắm.","en":"The food at this restaurant is pretty average and not very tasty."}]},"难过":{"en":"sad; upset; (colloquial) uncomfortable","exs":[{"use":"Chỉ tâm trạng buồn, đau lòng.","ex":"听到这个消息，我很难过。","py":"Tīngdào zhège xiāoxi, wǒ hěn nánguò.","vi":"Nghe tin này, tôi rất buồn.","en":"I was very sad to hear this news."},{"use":"难过得 + kết quả (bổ ngữ trạng thái).","ex":"朋友离开的时候，她难过得哭了。","py":"Péngyou líkāi de shíhou, tā nánguò de kū le.","vi":"Lúc bạn rời đi, cô ấy buồn đến khóc.","en":"When her friend left, she was so sad that she cried."},{"use":"别 + 难过: lời an ủi.","ex":"你别难过，一切都会好起来的。","py":"Nǐ bié nánguò, yíqiè dōu huì hǎo qǐlái de.","vi":"Bạn đừng buồn, mọi chuyện rồi sẽ tốt lên.","en":"Don't be sad; everything will get better."},{"use":"Nghĩa 2 (khẩu ngữ): khó chịu về thể xác.","ex":"嗓子疼得难过，我一口饭也吃不下。","py":"Sǎngzi téng de nánguò, wǒ yì kǒu fàn yě chī bú xià.","vi":"Họng đau khó chịu quá, tôi không nuốt nổi một miếng cơm.","en":"My throat hurts so badly that I can't eat a bite."}]},"脾气":{"en":"temper; disposition","exs":[{"use":"Thường dùng: 脾气好 / 脾气不好 / 发脾气.","ex":"他的脾气很好。","py":"Tā de píqi hěn hǎo.","vi":"Tính khí của anh ấy rất tốt.","en":"He has a good temper."},{"use":"脾气好 / 脾气不好 / 发脾气.","ex":"她脾气不好，容易生气。","py":"Tā píqi bù hǎo, róngyì shēngqì.","vi":"Cô ấy tính khí không tốt, dễ nổi giận.","en":"She has a bad temper and gets angry easily."},{"use":"发脾气: cụm cố định, nghĩa nổi nóng; đi với 对 + người.","ex":"别对孩子发脾气。","py":"Bié duì háizi fā píqi.","vi":"Đừng nổi nóng với con.","en":"Don't lose your temper with the child."},{"use":"脾气大: tính nóng, hay cáu.","ex":"他脾气大，同事都有点儿怕他。","py":"Tā píqi dà, tóngshì dōu yǒudiǎnr pà tā.","vi":"Anh ấy nóng tính, đồng nghiệp đều hơi ngại.","en":"He has a short temper, and his colleagues are a bit afraid of him."},{"use":"坏脾气: định ngữ + 脾气.","ex":"你得改改你的坏脾气。","py":"Nǐ děi gǎigai nǐ de huài píqi.","vi":"Bạn phải sửa cái tính xấu của mình đi.","en":"You need to work on your bad temper."}]},"几乎":{"en":"almost; nearly; practically","exs":[{"use":"Đứng trước động từ hoặc 每 / 都.","ex":"我几乎每天都跑步。","py":"Wǒ jīhū měi tiān dōu pǎobù.","vi":"Hầu như ngày nào tôi cũng chạy bộ.","en":"I run almost every day."},{"use":"几乎 + 忘 / 没 + ...: suýt nữa, gần như (việc không mong muốn).","ex":"我几乎忘了今天是她的生日。","py":"Wǒ jīhū wàng le jīntiān shì tā de shēngrì.","vi":"Tôi suýt nữa quên hôm nay là sinh nhật cô ấy.","en":"I almost forgot that today is her birthday."},{"use":"几乎 + 没有: gần như không có.","ex":"这里几乎没有人说英语。","py":"Zhèlǐ jīhū méiyǒu rén shuō Yīngyǔ.","vi":"Ở đây hầu như không ai nói tiếng Anh.","en":"Almost nobody here speaks English."},{"use":"几乎 + động từ + 满 / 完: gần như đầy / hết.","ex":"教室里几乎坐满了人。","py":"Jiàoshì lǐ jīhū zuò mǎn le rén.","vi":"Trong lớp học hầu như đã ngồi kín người.","en":"The classroom is almost full."}]},"特别":{"en":"especially; very; special","exs":[{"use":"特别 + tính từ = rất ...; làm tính từ: 很特别.","ex":"这里的风景特别美。","py":"Zhèlǐ de fēngjǐng tèbié měi.","vi":"Phong cảnh ở đây đặc biệt đẹp.","en":"The scenery here is especially beautiful."},{"use":"Tính từ: 特别的 + danh từ (khác thường).","ex":"他是一个很特别的人。","py":"Tā shì yí gè hěn tèbié de rén.","vi":"Anh ấy là một người rất đặc biệt.","en":"He is a very special person."},{"use":"特别 + động từ tâm lý (喜欢, 想...): rất.","ex":"我特别喜欢吃辣的菜。","py":"Wǒ tèbié xǐhuan chī là de cài.","vi":"Tôi đặc biệt thích ăn món cay.","en":"I especially love spicy food."},{"use":"特别是 ...: đặc biệt là (nêu ví dụ tiêu biểu).","ex":"我喜欢水果，特别是苹果。","py":"Wǒ xǐhuan shuǐguǒ, tèbié shì píngguǒ.","vi":"Tôi thích hoa quả, đặc biệt là táo.","en":"I like fruit, especially apples."}]},"原因":{"en":"reason; cause","exs":[{"use":"原因 + 是 ...; 主要原因 = nguyên nhân chính.","ex":"你知道原因吗？","py":"Nǐ zhīdào yuányīn ma?","vi":"Bạn có biết nguyên nhân không?","en":"Do you know the reason?"},{"use":"主要原因 = nguyên nhân chính.","ex":"迟到的原因是堵车。","py":"Chídào de yuányīn shì dǔchē.","vi":"Nguyên nhân đi muộn là do tắc đường.","en":"The reason for being late was a traffic jam."},{"use":"原因有很多: nói có nhiều nguyên nhân.","ex":"这次比赛输了，原因有很多。","py":"Zhè cì bǐsài shū le, yuányīn yǒu hěn duō.","vi":"Trận đấu lần này thua, nguyên nhân có rất nhiều.","en":"We lost this match for many reasons."},{"use":"因为这个原因: cụm nối nêu lý do.","ex":"因为这个原因，他决定换工作。","py":"Yīnwèi zhège yuányīn, tā juédìng huàn gōngzuò.","vi":"Vì lý do này, anh ấy quyết định đổi việc.","en":"For this reason, he decided to change jobs."}]},"重要":{"en":"important","exs":[{"use":"Dùng: 很重要 / 最重要.","ex":"健康比什么都重要。","py":"Jiànkāng bǐ shénme dōu zhòngyào.","vi":"Sức khỏe quan trọng hơn mọi thứ.","en":"Health is more important than anything."},{"use":"Thường dùng: 对…很重要 / 重要的 + danh từ.","ex":"这是一个很重要的决定。","py":"Zhè shì yí gè hěn zhòngyào de juédìng.","vi":"Đây là một quyết định rất quan trọng.","en":"This is a very important decision."},{"use":"非常重要 làm vị ngữ, nhấn mạnh mức độ.","ex":"这次会议非常重要，不能迟到。","py":"Zhè cì huìyì fēicháng zhòngyào, bù néng chídào.","vi":"Cuộc họp lần này rất quan trọng, không được đến muộn.","en":"This meeting is very important, so don't be late."},{"use":"对 + A + 重要: quan trọng đối với ai / cái gì.","ex":"睡觉对身体很重要。","py":"Shuìjiào duì shēntǐ hěn zhòngyào.","vi":"Ngủ rất quan trọng đối với cơ thể.","en":"Sleep is very important for the body."}]},"很多":{"en":"many; a lot of; much","exs":[{"use":"很多 + danh từ (người): rất nhiều ...","ex":"很多人喜欢在周末逛街。","py":"Hěn duō rén xǐhuan zài zhōumò guàngjiē.","vi":"Rất nhiều người thích đi dạo phố vào cuối tuần.","en":"Many people like to go shopping on weekends."},{"use":"有 + 很多 + danh từ: có nhiều (không cần 的).","ex":"桌子上有很多水果。","py":"Zhuōzi shang yǒu hěn duō shuǐguǒ.","vi":"Trên bàn có rất nhiều hoa quả.","en":"There is a lot of fruit on the table."},{"use":"V + 过 + 很多 + danh từ: đã từng ... nhiều.","ex":"他去过很多国家。","py":"Tā qù guo hěn duō guójiā.","vi":"Anh ấy đã đi qua rất nhiều nước.","en":"He has been to many countries."},{"use":"Tính từ + 了 + 很多: bổ ngữ chỉ mức độ chênh lệch lớn.","ex":"这个城市比以前干净了很多。","py":"Zhège chéngshì bǐ yǐqián gānjìng le hěn duō.","vi":"Thành phố này sạch hơn trước rất nhiều.","en":"This city is much cleaner than before."}]},"女孩子":{"en":"girl; young woman","exs":[{"use":"Cách nói thân mật về bé gái/cô gái.","ex":"那个女孩子很开朗。","py":"Nàge nǚ háizi hěn kāilǎng.","vi":"Cô gái đó rất vui vẻ.","en":"That girl is very cheerful."},{"use":"有 + số lượng + 女孩子: đếm số bé gái / cô gái.","ex":"她们家有两个女孩子。","py":"Tāmen jiā yǒu liǎng gè nǚ háizi.","vi":"Nhà họ có hai bé gái.","en":"They have two girls in their family."},{"use":"女孩子 chỉ phái nữ nói chung, trong lời khuyên.","ex":"女孩子晚上一个人出门要小心。","py":"Nǚ háizi wǎnshang yí gè rén chūmén yào xiǎoxīn.","vi":"Con gái buổi tối đi ra ngoài một mình phải cẩn thận.","en":"Girls should be careful going out alone at night."},{"use":"很多 + 女孩子: nói về xu hướng của nhóm.","ex":"现在很多女孩子喜欢运动。","py":"Xiànzài hěn duō nǚ háizi xǐhuan yùndòng.","vi":"Bây giờ nhiều cô gái thích thể thao.","en":"Many girls like sports nowadays."}]},"什么":{"en":"what; (any)thing","exs":[{"use":"Đại từ nghi vấn, dùng để hỏi sự vật, việc hoặc nội dung.","ex":"你想吃什么？","py":"Nǐ xiǎng chī shénme?","vi":"Bạn muốn ăn gì?","en":"What do you want to eat?"},{"use":"什么 + danh từ: hỏi loại / nội dung cụ thể.","ex":"你在看什么书？","py":"Nǐ zài kàn shénme shū?","vi":"Bạn đang đọc sách gì vậy?","en":"What book are you reading?"},{"use":"是什么意思: hỏi nghĩa của từ, câu.","ex":"这是什么意思？","py":"Zhè shì shénme yìsi?","vi":"Cái này nghĩa là gì?","en":"What does this mean?"},{"use":"什么 + 都 / 也 + phủ định: nghĩa \"không ... gì cả\" (đại từ phiếm chỉ).","ex":"我什么都不想做。","py":"Wǒ shénme dōu bù xiǎng zuò.","vi":"Tôi chẳng muốn làm gì cả.","en":"I don't feel like doing anything."}]},"年轻人":{"en":"young person; young people","exs":[{"use":"Chỉ nhóm người trẻ tuổi, đứng sau 的 hoặc làm chủ ngữ.","ex":"现在的年轻人喜欢网上购物。","py":"Xiànzài de niánqīngrén xǐhuan wǎngshàng gòuwù.","vi":"Người trẻ bây giờ thích mua sắm trực tuyến.","en":"Young people today like shopping online."},{"use":"年轻人 làm chủ ngữ trong câu khuyên nhủ.","ex":"年轻人应该多学习新东西。","py":"Niánqīngrén yīnggāi duō xué xīn dōngxi.","vi":"Người trẻ nên học thêm nhiều điều mới.","en":"Young people should learn more new things."},{"use":"有 + 很多 + 年轻人: nói về thành phần người trong nơi chốn.","ex":"这家公司有很多年轻人。","py":"Zhè jiā gōngsī yǒu hěn duō niánqīngrén.","vi":"Công ty này có rất nhiều người trẻ.","en":"This company has a lot of young people."}]},"想要":{"en":"to want; to would like to have","exs":[{"use":"想要 + danh từ: muốn có thứ gì (lịch sự, nhẹ nhàng hơn 要).","ex":"我想要一杯热咖啡。","py":"Wǒ xiǎng yào yì bēi rè kāfēi.","vi":"Tôi muốn một cốc cà phê nóng.","en":"I would like a cup of hot coffee."},{"use":"想要 + số lượng + danh từ: nói về món đồ mong muốn.","ex":"孩子想要一个新书包。","py":"Háizi xiǎng yào yí gè xīn shūbāo.","vi":"Đứa trẻ muốn có một chiếc cặp mới.","en":"The child wants a new schoolbag."},{"use":"想要 + 什么: dùng trong câu hỏi.","ex":"你想要什么生日礼物？","py":"Nǐ xiǎng yào shénme shēngrì lǐwù?","vi":"Bạn muốn quà sinh nhật gì?","en":"What birthday gift do you want?"},{"use":"自己 + 想要 + 什么: nói về mong muốn thực sự của bản thân.","ex":"她不知道自己真正想要什么。","py":"Tā bù zhīdào zìjǐ zhēnzhèng xiǎng yào shénme.","vi":"Cô ấy không biết thật sự mình muốn gì.","en":"She doesn't know what she really wants."}]},"月亮":{"en":"moon","exs":[{"use":"月亮 làm định ngữ chỉ hình dáng: 又大又圆.","ex":"今天晚上的月亮又大又圆。","py":"Jīntiān wǎnshang de yuèliang yòu dà yòu yuán.","vi":"Mặt trăng tối nay vừa to vừa tròn.","en":"The moon is big and round tonight."},{"use":"月亮 làm chủ ngữ với 出来了.","ex":"月亮出来了，我们去散步吧。","py":"Yuèliang chūlái le, wǒmen qù sànbù ba.","vi":"Trăng lên rồi, chúng ta đi dạo đi.","en":"The moon is out; let's go for a walk."},{"use":"看月亮: hoạt động ngắm trăng (Tết Trung thu).","ex":"中秋节的时候，一家人一起看月亮。","py":"Zhōngqiū Jié de shíhou, yì jiārén yìqǐ kàn yuèliang.","vi":"Vào Tết Trung thu, cả nhà cùng ngắm trăng.","en":"During the Mid-Autumn Festival, the whole family watches the moon together."}]},"星星":{"en":"star","exs":[{"use":"有 + 很多 + 星星: nói về nhiều sao trên trời.","ex":"晚上天空中有很多星星。","py":"Wǎnshang tiānkōng zhōng yǒu hěn duō xīngxing.","vi":"Buổi tối trên bầu trời có rất nhiều ngôi sao.","en":"There are many stars in the sky at night."},{"use":"数星星: cụm quen thuộc, đếm sao.","ex":"孩子们躺在草地上数星星。","py":"Háizimen tǎng zài cǎodì shang shǔ xīngxing.","vi":"Bọn trẻ nằm trên bãi cỏ đếm sao.","en":"The children lie on the grass counting stars."},{"use":"看不到 + 星星: bổ ngữ khả năng phủ định.","ex":"今天下雨，看不到星星。","py":"Jīntiān xià yǔ, kàn bú dào xīngxing.","vi":"Hôm nay trời mưa, không nhìn thấy sao.","en":"It's raining today, so we can't see the stars."}]},"中年人":{"en":"middle-aged person","exs":[{"use":"Chỉ người khoảng 40-60 tuổi.","ex":"中年人上有老下有小，压力很大。","py":"Zhōngniánrén shàng yǒu lǎo xià yǒu xiǎo, yālì hěn dà.","vi":"Người trung niên trên có già dưới có trẻ, áp lực rất lớn.","en":"Middle-aged people support both elders and children, so they are under great pressure."},{"use":"对 + 中年人 + 来说: đối với người trung niên mà nói.","ex":"对中年人来说，健康最重要。","py":"Duì zhōngniánrén lái shuō, jiànkāng zuì zhòngyào.","vi":"Đối với người trung niên, sức khỏe là quan trọng nhất.","en":"For middle-aged people, health is the most important thing."},{"use":"Lượng từ 位 + 中年人: cách nói lịch sự khi chỉ một người.","ex":"那位中年人是我们的新经理。","py":"Nà wèi zhōngniánrén shì wǒmen de xīn jīnglǐ.","vi":"Người đàn ông trung niên kia là giám đốc mới của chúng tôi.","en":"That middle-aged man is our new manager."},{"use":"有 + 很多 + 中年人: nói về nhóm người ở một nơi.","ex":"这家健身房有很多中年人。","py":"Zhè jiā jiànshēnfáng yǒu hěn duō zhōngniánrén.","vi":"Phòng tập này có rất nhiều người trung niên.","en":"This gym has many middle-aged people."}]},"即使":{"en":"even if; even though","exs":[{"use":"即使 … 也 …: cho dù ... cũng ...","ex":"即使下雨，我们也要去。","py":"Jíshǐ xià yǔ, wǒmen yě yào qù.","vi":"Cho dù trời mưa, chúng tôi cũng phải đi.","en":"Even if it rains, we still have to go."},{"use":"即使 + tính từ / trạng thái, 也 + hành động.","ex":"即使很累，他也坚持跑完了。","py":"Jíshǐ hěn lèi, tā yě jiānchí pǎowán le.","vi":"Dù rất mệt, anh ấy vẫn kiên trì chạy xong.","en":"Even though he was tired, he persisted and finished the run."},{"use":"即使 + giả thiết trái với sự thật, 我也 ...","ex":"即使你不说，我也知道。","py":"Jíshǐ nǐ bù shuō, wǒ yě zhīdào.","vi":"Cho dù bạn không nói, tôi cũng biết.","en":"Even if you don't say it, I know."},{"use":"即使 … 再 + tính từ, 也 …: dù ... đến mấy cũng ...","ex":"即使工作再忙，也要照顾好身体。","py":"Jíshǐ gōngzuò zài máng, yě yào zhàogù hǎo shēntǐ.","vi":"Dù công việc có bận đến mấy cũng phải chăm sóc tốt cho sức khỏe.","en":"No matter how busy work is, you must take care of your health."}]},"晚上":{"en":"evening; night","exs":[{"use":"晚上 + động từ: trạng ngữ chỉ thời gian, đứng trước động từ.","ex":"我晚上十点睡觉。","py":"Wǒ wǎnshang shí diǎn shuìjiào.","vi":"Tôi mười giờ tối đi ngủ.","en":"I go to bed at ten at night."},{"use":"今天晚上 / 明天晚上: kết hợp với từ chỉ ngày.","ex":"今天晚上你有空吗？","py":"Jīntiān wǎnshang nǐ yǒu kòng ma?","vi":"Tối nay bạn có rảnh không?","en":"Are you free tonight?"},{"use":"昨天晚上: nói về việc đã xảy ra.","ex":"昨天晚上我看了一部电影。","py":"Zuótiān wǎnshang wǒ kàn le yí bù diànyǐng.","vi":"Tối qua tôi đã xem một bộ phim.","en":"I watched a movie last night."},{"use":"每天晚上: thói quen lặp lại.","ex":"他每天晚上都去公园跑步。","py":"Tā měi tiān wǎnshang dōu qù gōngyuán pǎobù.","vi":"Mỗi tối anh ấy đều ra công viên chạy bộ.","en":"He goes jogging in the park every evening."},{"use":"晚上好: lời chào buổi tối.","ex":"晚上好！欢迎光临。","py":"Wǎnshang hǎo! Huānyíng guānglín.","vi":"Chào buổi tối! Chào mừng quý khách.","en":"Good evening! Welcome."}]},"零点":{"en":"midnight; zero o'clock; (decimal) zero point","exs":[{"use":"Chỉ 0 giờ, tức 12 giờ đêm.","ex":"他昨晚工作到零点才睡。","py":"Tā zuówǎn gōngzuò dào língdiǎn cái shuì.","vi":"Tối qua anh ấy làm việc đến 0 giờ mới ngủ.","en":"He worked until midnight last night before going to sleep."},{"use":"零点 + động từ: giờ của sự việc.","ex":"飞机零点起飞，我们得早点儿去机场。","py":"Fēijī língdiǎn qǐfēi, wǒmen děi zǎodiǎnr qù jīchǎng.","vi":"Máy bay cất cánh lúc 0 giờ, chúng ta phải đến sân bay sớm.","en":"The flight takes off at midnight, so we need to get to the airport early."},{"use":"零点 + số phút: 0 giờ mấy phút.","ex":"现在是零点十分，你怎么还不睡？","py":"Xiànzài shì língdiǎn shí fēn, nǐ zěnme hái bú shuì?","vi":"Bây giờ đã 0 giờ 10 phút, sao bạn còn chưa ngủ?","en":"It's ten past midnight; why aren't you asleep yet?"},{"use":"Nghĩa 2: dấu phẩy thập phân, 零点五 = 0,5.","ex":"这杯水只有零点五升。","py":"Zhè bēi shuǐ zhǐyǒu líng diǎn wǔ shēng.","vi":"Cốc nước này chỉ có 0,5 lít.","en":"This glass of water is only 0.5 liters."}]},"到家":{"en":"to arrive home; to get home","exs":[{"use":"到家 + 以后 / 之后: sau khi về đến nhà.","ex":"我到家以后给你打电话。","py":"Wǒ dào jiā yǐhòu gěi nǐ dǎ diànhuà.","vi":"Tôi về đến nhà rồi sẽ gọi điện cho bạn.","en":"I'll call you after I get home."},{"use":"Thời gian + 才 + 到家: về đến nhà muộn.","ex":"今天路上堵车，十点才到家。","py":"Jīntiān lùshang dǔchē, shí diǎn cái dào jiā.","vi":"Hôm nay tắc đường, mười giờ mới về đến nhà.","en":"There was a traffic jam today, so I didn't get home until ten."},{"use":"到家了吗: câu hỏi hỏi thăm.","ex":"到家了吗？路上还顺利吗？","py":"Dào jiā le ma? Lùshang hái shùnlì ma?","vi":"Về đến nhà chưa? Trên đường có thuận lợi không?","en":"Are you home yet? Was the trip smooth?"},{"use":"一 … 就 …: vừa về đến nhà là ...","ex":"孩子一到家就开始写作业。","py":"Háizi yí dào jiā jiù kāishǐ xiě zuòyè.","vi":"Đứa trẻ vừa về đến nhà là bắt đầu làm bài tập.","en":"As soon as the child gets home, he starts his homework."},{"use":"还没 + 到家: chưa về đến nhà.","ex":"我还没到家，你们先吃吧。","py":"Wǒ hái méi dào jiā, nǐmen xiān chī ba.","vi":"Tôi chưa về đến nhà, các bạn ăn trước đi.","en":"I'm not home yet, so go ahead and eat."}]},"自己":{"en":"oneself; self; own","exs":[{"use":"Đại từ phản thân, chỉ chính người được nhắc đến.","ex":"你要相信自己。","py":"Nǐ yào xiāngxìn zìjǐ.","vi":"Bạn phải tin vào bản thân mình.","en":"You have to believe in yourself."},{"use":"自己 + động từ: nhấn mạnh tự mình làm.","ex":"我自己做饭，不用麻烦你。","py":"Wǒ zìjǐ zuòfàn, bú yòng máfan nǐ.","vi":"Tôi tự nấu cơm, không cần làm phiền bạn.","en":"I'll cook for myself, so there's no need to trouble you."},{"use":"自己的 + danh từ: của chính mình.","ex":"他把自己的房间打扫得很干净。","py":"Tā bǎ zìjǐ de fángjiān dǎsǎo de hěn gānjìng.","vi":"Anh ấy dọn phòng của mình rất sạch sẽ.","en":"He cleaned his own room until it was spotless."},{"use":"可以 + 自己 + V: có thể tự làm.","ex":"孩子已经可以自己穿衣服了。","py":"Háizi yǐjīng kěyǐ zìjǐ chuān yīfu le.","vi":"Đứa trẻ đã có thể tự mặc quần áo.","en":"The child can already dress himself."},{"use":"照顾自己: cụm quen thuộc, tân ngữ phản thân.","ex":"你一个人在外面，要学会照顾自己。","py":"Nǐ yí gè rén zài wàimian, yào xuéhuì zhàogù zìjǐ.","vi":"Bạn ở ngoài một mình, phải học cách tự chăm sóc bản thân.","en":"Living on your own, you need to learn to take care of yourself."}]},"家里":{"en":"at home; in the house; (one's) family","exs":[{"use":"Nơi chốn: 家里 + có / ở, chỉ trong nhà.","ex":"家里有三口人。","py":"Jiālǐ yǒu sān kǒu rén.","vi":"Nhà có ba người.","en":"There are three people in my family."},{"use":"在 + 家里 + V: ở trong nhà làm gì.","ex":"周末我喜欢待在家里看书。","py":"Zhōumò wǒ xǐhuan dāi zài jiālǐ kàn shū.","vi":"Cuối tuần tôi thích ở nhà đọc sách.","en":"On weekends I like staying home to read."},{"use":"你家里 + 有 + 什么人: hỏi về các thành viên gia đình.","ex":"你家里有什么人？","py":"Nǐ jiālǐ yǒu shénme rén?","vi":"Nhà bạn có những ai?","en":"Who is in your family?"},{"use":"家里 chỉ gia đình, người nhà (ngoài nghĩa nơi chốn).","ex":"我给家里打了个电话。","py":"Wǒ gěi jiālǐ dǎ le ge diànhuà.","vi":"Tôi gọi điện về cho gia đình.","en":"I called my family at home."}]},"老年人":{"en":"elderly person; the elderly","exs":[{"use":"老年人 làm chủ ngữ, nói về nhóm người cao tuổi.","ex":"老年人需要多运动。","py":"Lǎoniánrén xūyào duō yùndòng.","vi":"Người cao tuổi cần vận động nhiều.","en":"Elderly people need more exercise."},{"use":"给 + 老年人 + 让座: nhường chỗ cho người già.","ex":"公交车上要给老年人让座。","py":"Gōngjiāochē shang yào gěi lǎoniánrén ràngzuò.","vi":"Trên xe buýt phải nhường chỗ cho người cao tuổi.","en":"You should give up your seat to the elderly on the bus."},{"use":"住着 + 很多 + 老年人: mô tả cộng đồng.","ex":"这个小区住着很多老年人。","py":"Zhège xiǎoqū zhùzhe hěn duō lǎoniánrén.","vi":"Khu dân cư này có rất nhiều người cao tuổi sống.","en":"Many elderly people live in this neighborhood."},{"use":"老年人 + 也可以 + V: nói về khả năng của người già.","ex":"老年人也可以学用手机。","py":"Lǎoniánrén yě kěyǐ xué yòng shǒujī.","vi":"Người cao tuổi cũng có thể học dùng điện thoại.","en":"Elderly people can learn to use smartphones too."}]},"其实":{"en":"actually; in fact","exs":[{"use":"其实 đứng đầu vế sau, nói ngược với vế trước.","ex":"他看起来很凶，其实人很好。","py":"Tā kàn qǐlái hěn xiōng, qíshí rén hěn hǎo.","vi":"Anh ấy trông dữ vậy nhưng thật ra rất tốt.","en":"He looks fierce, but actually he's a nice person."},{"use":"其实 + 我 + 也 + ...: mở đầu câu để nói sự thật.","ex":"其实我也不知道答案。","py":"Qíshí wǒ yě bù zhīdào dá'àn.","vi":"Thật ra tôi cũng không biết đáp án.","en":"Actually, I don't know the answer either."},{"use":"Chủ ngữ + 其实 + vị ngữ: đứng sau chủ ngữ.","ex":"这道题其实不难。","py":"Zhè dào tí qíshí bù nán.","vi":"Câu này thật ra không khó.","en":"This question isn't actually hard."},{"use":"以为 …，其实 …: tưởng là ..., thật ra là ...","ex":"大家以为他是中国人，其实他是日本人。","py":"Dàjiā yǐwéi tā shì Zhōngguó rén, qíshí tā shì Rìběn rén.","vi":"Mọi người tưởng anh ấy là người Trung Quốc, thật ra anh ấy là người Nhật.","en":"Everyone thought he was Chinese, but he's actually Japanese."}]},"就像":{"en":"just like; to be like","exs":[{"use":"就像 + A + 一样: giống như A.","ex":"她笑起来就像一朵花。","py":"Tā xiào qǐlái jiù xiàng yì duǒ huā.","vi":"Cô ấy cười lên trông như một đóa hoa.","en":"When she smiles, she looks like a flower."},{"use":"就像 + danh từ: so sánh hình ảnh.","ex":"我们在一起就像一家人。","py":"Wǒmen zài yìqǐ jiù xiàng yì jiārén.","vi":"Chúng tôi ở bên nhau như một gia đình.","en":"When we're together, it feels like a family."},{"use":"就像 … 一样 + tính từ: so sánh mức độ.","ex":"这里的冬天就像春天一样暖和。","py":"Zhèlǐ de dōngtiān jiù xiàng chūntiān yíyàng nuǎnhuo.","vi":"Mùa đông ở đây ấm như mùa xuân.","en":"Winter here is as warm as spring."},{"use":"对 + A + 就像 + 对 + B + 一样: đối xử với A như với B.","ex":"他对我就像对亲弟弟一样。","py":"Tā duì wǒ jiù xiàng duì qīn dìdi yíyàng.","vi":"Anh ấy đối xử với tôi như em ruột.","en":"He treats me just like his own younger brother."}]},"那样":{"en":"like that; that way; so","exs":[{"use":"那样 + động từ: làm trạng ngữ, nghĩa \"như thế\".","ex":"不要那样说话，他会难过的。","py":"Bú yào nàyàng shuōhuà, tā huì nánguò de.","vi":"Đừng nói như vậy, anh ấy sẽ buồn đấy.","en":"Don't talk like that; he'll be upset."},{"use":"像 + A + 那样 + V: giống A như thế.","ex":"我也想像他那样会弹钢琴。","py":"Wǒ yě xiǎng xiàng tā nàyàng huì tán gāngqín.","vi":"Tôi cũng muốn biết chơi piano như anh ấy.","en":"I also want to play the piano like him."},{"use":"Vị ngữ: 不是 + ... + 那样.","ex":"事情不是你想的那样。","py":"Shìqing bú shì nǐ xiǎng de nàyàng.","vi":"Sự việc không phải như bạn nghĩ.","en":"It's not the way you think."},{"use":"别 + 那样 + V: ngăn cản cách làm.","ex":"别那样看着我，我会不好意思的。","py":"Bié nàyàng kànzhe wǒ, wǒ huì bù hǎoyìsi de.","vi":"Đừng nhìn tôi như thế, tôi sẽ ngại đấy.","en":"Don't look at me like that; it makes me shy."}]},"想到":{"en":"to think of; to realize; to expect","exs":[{"use":"没想到 + ...: không ngờ tới.","ex":"我没想到会在这里遇见你。","py":"Wǒ méi xiǎngdào huì zài zhèlǐ yùjiàn nǐ.","vi":"Tôi không ngờ lại gặp bạn ở đây.","en":"I didn't expect to run into you here."},{"use":"一想到 … 就 …: hễ nghĩ đến ... là ...","ex":"一想到明天要考试，我就紧张。","py":"Yì xiǎngdào míngtiān yào kǎoshì, wǒ jiù jǐnzhāng.","vi":"Cứ nghĩ đến ngày mai phải thi là tôi lo lắng.","en":"Whenever I think about tomorrow's exam, I get nervous."},{"use":"想到 + 办法 / 主意: nghĩ ra cách.","ex":"你想到好办法了吗？","py":"Nǐ xiǎngdào hǎo bànfǎ le ma?","vi":"Bạn nghĩ ra cách hay chưa?","en":"Have you thought of a good solution?"},{"use":"想到了 + sự việc: nghĩ tới điều gì.","ex":"她想到了小时候的事，笑了起来。","py":"Tā xiǎngdào le xiǎoshíhou de shì, xiào le qǐlái.","vi":"Cô ấy nghĩ đến chuyện hồi nhỏ rồi bật cười.","en":"She thought of something from her childhood and started to laugh."}]},"就是":{"en":"exactly; precisely; just (is); only (but)","exs":[{"use":"A 就是 B: A chính là B.","ex":"他就是我常说的那位老师。","py":"Tā jiùshì wǒ cháng shuō de nà wèi lǎoshī.","vi":"Anh ấy chính là người thầy mà tôi hay nhắc.","en":"He is the teacher I often talk about."},{"use":"最 … 的 + 就是 + B: điều ... nhất chính là B.","ex":"我最喜欢的运动就是游泳。","py":"Wǒ zuì xǐhuan de yùndòng jiùshì yóuyǒng.","vi":"Môn thể thao tôi thích nhất chính là bơi lội.","en":"My favorite sport is swimming."},{"use":"…，就是 + khuyết điểm: nhưng mà, chỉ là ...","ex":"这家店东西不贵，就是有点儿远。","py":"Zhè jiā diàn dōngxi bú guì, jiùshì yǒudiǎnr yuǎn.","vi":"Cửa hàng này đồ không đắt, chỉ là hơi xa.","en":"The items in this shop aren't expensive; it's just a bit far."},{"use":"就是 + 不 / 要 + V: nhấn mạnh thái độ cứng đầu.","ex":"我劝了他很多次，他就是不听。","py":"Wǒ quàn le tā hěn duō cì, tā jiùshì bù tīng.","vi":"Tôi khuyên anh ấy nhiều lần, anh ấy cứ nhất định không nghe.","en":"I advised him many times, but he just wouldn't listen."}]},"一起":{"en":"together","exs":[{"use":"Phó từ: 一起 + động từ.","ex":"周末我们一起去爬山吧。","py":"Zhōumò wǒmen yìqǐ qù páshān ba.","vi":"Cuối tuần chúng ta cùng đi leo núi nhé.","en":"Let's go hiking together this weekend."},{"use":"和 / 跟 + người + 一起 + V: cùng ai làm gì.","ex":"我想和你一起学汉语。","py":"Wǒ xiǎng hé nǐ yìqǐ xué Hànyǔ.","vi":"Tôi muốn cùng bạn học tiếng Trung.","en":"I want to study Chinese with you."},{"use":"在一起: ở bên nhau; cũng chỉ quan hệ yêu đương.","ex":"他们在一起很多年了。","py":"Tāmen zài yìqǐ hěn duō nián le.","vi":"Họ ở bên nhau nhiều năm rồi.","en":"They've been together for many years."},{"use":"一起 + V + 吧: lời rủ rê.","ex":"我们一起吃饭吧。","py":"Wǒmen yìqǐ chīfàn ba.","vi":"Chúng ta cùng ăn cơm nhé.","en":"Let's have a meal together."}]},"慢慢":{"en":"slowly; gradually","exs":[{"use":"慢慢 + động từ: làm chậm rãi.","ex":"你慢慢说，我听得懂。","py":"Nǐ mànmàn shuō, wǒ tīng de dǒng.","vi":"Bạn cứ nói từ từ, tôi nghe hiểu.","en":"Speak slowly; I can understand you."},{"use":"慢慢 + biến hóa (变冷, 变好...): dần dần thay đổi.","ex":"天气慢慢变冷了。","py":"Tiānqì mànmàn biàn lěng le.","vi":"Thời tiết dần dần lạnh đi.","en":"The weather is gradually getting colder."},{"use":"慢慢来: cụm cố định, nghĩa \"cứ từ từ\".","ex":"慢慢来，别着急。","py":"Mànmàn lái, bié zháojí.","vi":"Cứ từ từ, đừng vội.","en":"Take your time; don't rush."},{"use":"慢慢 + 长大 / 习惯: quá trình theo thời gian.","ex":"孩子慢慢长大了。","py":"Háizi mànmàn zhǎngdà le.","vi":"Đứa trẻ dần dần lớn lên.","en":"The child is gradually growing up."}]},"我们":{"en":"we; us","exs":[{"use":"我们 làm chủ ngữ.","ex":"我们是同班同学。","py":"Wǒmen shì tóngbān tóngxué.","vi":"Chúng tôi là bạn cùng lớp.","en":"We are classmates."},{"use":"我们 + động từ + 吧: đề nghị cùng làm (bao gồm người nghe).","ex":"我们明天去逛街吧。","py":"Wǒmen míngtiān qù guàngjiē ba.","vi":"Ngày mai chúng ta đi dạo phố nhé.","en":"Let's go shopping tomorrow."},{"use":"对 + 我们 + 很好: làm tân ngữ sau giới từ.","ex":"老师对我们很好。","py":"Lǎoshī duì wǒmen hěn hǎo.","vi":"Thầy giáo rất tốt với chúng tôi.","en":"The teacher is very kind to us."},{"use":"我们的 + danh từ: sở hữu.","ex":"这是我们的家。","py":"Zhè shì wǒmen de jiā.","vi":"Đây là nhà của chúng tôi.","en":"This is our home."}]},"生活":{"en":"life; to live","exs":[{"use":"Có thể là danh từ hoặc động từ.","ex":"我的生活很简单。","py":"Wǒ de shēnghuó hěn jiǎndān.","vi":"Cuộc sống của tôi rất đơn giản.","en":"My life is very simple."},{"use":"Động từ: 在 + nơi chốn + 生活 + thời gian.","ex":"他一个人在北京生活了五年。","py":"Tā yí gè rén zài Běijīng shēnghuó le wǔ nián.","vi":"Anh ấy một mình sống ở Bắc Kinh năm năm.","en":"He has lived in Beijing on his own for five years."},{"use":"Danh từ: 我们的生活 làm tân ngữ / chủ ngữ.","ex":"网上购物让我们的生活更方便。","py":"Wǎngshàng gòuwù ràng wǒmen de shēnghuó gèng fāngbiàn.","vi":"Mua sắm trực tuyến làm cuộc sống của chúng ta thuận tiện hơn.","en":"Online shopping makes our lives more convenient."},{"use":"生活习惯 / 生活水平: từ ghép thường gặp.","ex":"他的生活习惯很好，每天早睡早起。","py":"Tā de shēnghuó xíguàn hěn hǎo, měi tiān zǎo shuì zǎo qǐ.","vi":"Thói quen sinh hoạt của anh ấy rất tốt, ngày nào cũng ngủ sớm dậy sớm.","en":"He has good living habits and goes to bed and gets up early every day."}]},"有时候":{"en":"sometimes","exs":[{"use":"有时候 … 有时候 …: lúc thì ... lúc thì ...","ex":"我有时候坐地铁，有时候骑自行车。","py":"Wǒ yǒu shíhou zuò dìtiě, yǒu shíhou qí zìxíngchē.","vi":"Có lúc tôi đi tàu điện ngầm, có lúc đi xe đạp.","en":"Sometimes I take the subway and sometimes I ride a bike."},{"use":"有时候 đứng đầu câu: trạng ngữ chỉ tần suất.","ex":"有时候我也会觉得很累。","py":"Yǒu shíhou wǒ yě huì juéde hěn lèi.","vi":"Có lúc tôi cũng cảm thấy rất mệt.","en":"Sometimes I get tired too."},{"use":"Chủ ngữ + 有时候 + 会 + V: thỉnh thoảng sẽ ...","ex":"他有时候会忘记带钥匙。","py":"Tā yǒu shíhou huì wàngjì dài yàoshi.","vi":"Thỉnh thoảng anh ấy quên mang chìa khóa.","en":"He sometimes forgets to bring his keys."}]},"说到":{"en":"speaking of; when it comes to","exs":[{"use":"说到 + chủ đề, …: nói đến ... thì ...","ex":"说到旅游，我最想去云南。","py":"Shuō dào lǚyóu, wǒ zuì xiǎng qù Yúnnán.","vi":"Nói đến du lịch, tôi muốn đi Vân Nam nhất.","en":"Speaking of travel, I most want to go to Yunnan."},{"use":"说到这里: cụm chuyển ý trong lúc trò chuyện.","ex":"说到这里，我想起一件事。","py":"Shuō dào zhèlǐ, wǒ xiǎngqǐ yí jiàn shì.","vi":"Nói đến đây, tôi chợt nhớ ra một chuyện.","en":"Speaking of this, I just remembered something."},{"use":"说到做到: thành ngữ, nói được làm được.","ex":"他说到做到，从不骗人。","py":"Tā shuō dào zuò dào, cóng bú piàn rén.","vi":"Anh ấy nói được làm được, chưa bao giờ lừa ai.","en":"He keeps his word and never lies to people."},{"use":"说到 + 唱歌 / 做饭 ...: nêu một lĩnh vực để bình luận.","ex":"说到唱歌，她唱得最好。","py":"Shuō dào chànggē, tā chàng de zuì hǎo.","vi":"Nói đến ca hát thì cô ấy hát hay nhất.","en":"When it comes to singing, she sings the best."}]},"人们":{"en":"people; everyone","exs":[{"use":"Chỉ con người nói chung; không dùng cho một số lượng người xác định.","ex":"现在人们很重视环境保护。","py":"Xiànzài rénmen hěn zhòngshì huánjìng bǎohù.","vi":"Hiện nay mọi người rất coi trọng việc bảo vệ môi trường.","en":"People nowadays attach great importance to environmental protection."},{"use":"人们都说 …: người ta đều nói ...","ex":"人们都说北京的秋天最美。","py":"Rénmen dōu shuō Běijīng de qiūtiān zuì měi.","vi":"Mọi người đều nói mùa thu Bắc Kinh đẹp nhất.","en":"People all say autumn in Beijing is the most beautiful."},{"use":"Thời gian + 人们 + V: nói về phong tục.","ex":"过年的时候，人们喜欢吃饺子。","py":"Guònián de shíhou, rénmen xǐhuan chī jiǎozi.","vi":"Dịp Tết, mọi người thích ăn sủi cảo.","en":"During the New Year, people like to eat dumplings."},{"use":"人们的 + danh từ: sở hữu chung.","ex":"人们的生活水平越来越高。","py":"Rénmen de shēnghuó shuǐpíng yuè lái yuè gāo.","vi":"Mức sống của mọi người ngày càng cao.","en":"People's living standards are getting higher and higher."}]},"想起":{"en":"to recall; to think of; to remember","exs":[{"use":"想起 + sự việc / người: chợt nhớ ra.","ex":"看到这张照片，我想起了小时候。","py":"Kàndào zhè zhāng zhàopiàn, wǒ xiǎngqǐ le xiǎoshíhou.","vi":"Nhìn tấm ảnh này, tôi nhớ lại thời thơ ấu.","en":"Seeing this photo reminded me of my childhood."},{"use":"想起来: bổ ngữ xu hướng, chợt nhớ ra.","ex":"我突然想起来还没关门。","py":"Wǒ tūrán xiǎng qǐlái hái méi guān mén.","vi":"Tôi chợt nhớ ra là chưa đóng cửa.","en":"I suddenly remembered I hadn't closed the door."},{"use":"让 + người + 想起 + ...: khiến ai nhớ đến.","ex":"这首歌让我想起了我的大学时代。","py":"Zhè shǒu gē ràng wǒ xiǎngqǐ le wǒ de dàxué shídài.","vi":"Bài hát này khiến tôi nhớ đến thời đại học.","en":"This song reminds me of my college days."},{"use":"我想起来了: trả lời khi đã nhớ ra.","ex":"我想起来了，钥匙在包里。","py":"Wǒ xiǎng qǐlái le, yàoshi zài bāo lǐ.","vi":"Tôi nhớ ra rồi, chìa khóa ở trong túi.","en":"I remember now: the keys are in the bag."}]},"不仅":{"en":"not only","exs":[{"use":"不仅 … 而且 / 还 / 也 …: không chỉ ... mà còn ...","ex":"他不仅会唱歌，而且会跳舞。","py":"Tā bùjǐn huì chàng gē, érqiě huì tiàowǔ.","vi":"Anh ấy không chỉ biết hát mà còn biết nhảy.","en":"He can not only sing but also dance."},{"use":"不仅 + tính từ, 而且 + tính từ.","ex":"这家店不仅便宜，而且很干净。","py":"Zhè jiā diàn bùjǐn piányi, érqiě hěn gānjìng.","vi":"Cửa hàng này không những rẻ mà còn rất sạch.","en":"This shop is not only cheap but also very clean."},{"use":"不仅 + chủ ngữ A, B 也 …: hai chủ ngữ khác nhau.","ex":"不仅孩子喜欢，大人也喜欢。","py":"Bùjǐn háizi xǐhuan, dàrén yě xǐhuan.","vi":"Không chỉ trẻ con thích, người lớn cũng thích.","en":"Not only children like it; adults do too."},{"use":"不仅是 … 还是 …: không chỉ là ... mà còn là ...","ex":"她不仅是我的老师，还是我的朋友。","py":"Tā bùjǐn shì wǒ de lǎoshī, hái shì wǒ de péngyou.","vi":"Cô ấy không chỉ là thầy giáo mà còn là bạn của tôi.","en":"She is not only my teacher but also my friend."}]},"需要":{"en":"to need; to require","exs":[{"use":"需要 + danh từ: cần cái gì.","ex":"我需要你的帮助。","py":"Wǒ xūyào nǐ de bāngzhù.","vi":"Tôi cần sự giúp đỡ của bạn.","en":"I need your help."},{"use":"需要 + động từ: cần phải làm gì.","ex":"你需要多休息。","py":"Nǐ xūyào duō xiūxi.","vi":"Bạn cần nghỉ ngơi nhiều hơn.","en":"You need to rest more."},{"use":"Sự việc + 需要 + 什么: hỏi điều kiện cần thiết.","ex":"办签证需要什么材料？","py":"Bàn qiānzhèng xūyào shénme cáiliào?","vi":"Làm visa cần những giấy tờ gì?","en":"What documents are needed to apply for a visa?"},{"use":"不需要 + V: không cần phải.","ex":"不需要买票，这里是免费的。","py":"Bù xūyào mǎi piào, zhèlǐ shì miǎnfèi de.","vi":"Không cần mua vé, ở đây miễn phí.","en":"There's no need to buy a ticket; it's free here."}]},"互相":{"en":"each other; mutually","exs":[{"use":"互相 + động từ: làm cho nhau, lẫn nhau.","ex":"朋友之间要互相帮助。","py":"Péngyou zhījiān yào hùxiāng bāngzhù.","vi":"Bạn bè với nhau phải giúp đỡ lẫn nhau.","en":"Friends should help each other."},{"use":"互相 + 学习 / 进步: cùng nhau tiến bộ.","ex":"我们互相学习，一起进步。","py":"Wǒmen hùxiāng xuéxí, yìqǐ jìnbù.","vi":"Chúng tôi học hỏi lẫn nhau, cùng nhau tiến bộ.","en":"We learn from each other and improve together."},{"use":"互相 + 不 + V: phủ định, chưa từng ... với nhau.","ex":"他们互相不认识。","py":"Tāmen hùxiāng bú rènshi.","vi":"Họ không quen biết nhau.","en":"They don't know each other."},{"use":"互相 + 理解 / 尊重: cách nói về quan hệ.","ex":"夫妻应该互相理解。","py":"Fūqī yīnggāi hùxiāng lǐjiě.","vi":"Vợ chồng nên thông cảm cho nhau.","en":"Husbands and wives should understand each other."}]},"事情":{"en":"matter; thing; affair","exs":[{"use":"这件事情: lượng từ 件 + 事情.","ex":"这件事情很复杂。","py":"Zhè jiàn shìqing hěn fùzá.","vi":"Việc này rất phức tạp.","en":"This matter is very complicated."},{"use":"有 + 很多 + 事情 + 要 + V: có nhiều việc phải làm.","ex":"今天有很多事情要做。","py":"Jīntiān yǒu hěn duō shìqing yào zuò.","vi":"Hôm nay có nhiều việc phải làm.","en":"There are many things to do today."},{"use":"事情 làm chủ ngữ với 会 + V: sự việc sẽ ...","ex":"你别担心，事情会解决的。","py":"Nǐ bié dānxīn, shìqing huì jiějué de.","vi":"Bạn đừng lo, việc này sẽ giải quyết được.","en":"Don't worry; the matter will be resolved."},{"use":"发生 + 什么事情: hỏi chuyện gì xảy ra.","ex":"发生什么事情了？","py":"Fāshēng shénme shìqing le?","vi":"Đã xảy ra chuyện gì vậy?","en":"What happened?"}]},"嘴里":{"en":"in the mouth","exs":[{"use":"嘴里 + có / 吃 ...: trong miệng có gì.","ex":"嘴里有东西的时候不要说话。","py":"Zuǐlǐ yǒu dōngxi de shíhou bú yào shuōhuà.","vi":"Khi trong miệng có đồ ăn thì đừng nói chuyện.","en":"Don't talk when you have food in your mouth."},{"use":"嘴里 + 含着 + danh từ: ngậm gì trong miệng.","ex":"她嘴里含着一块糖。","py":"Tā zuǐlǐ hánzhe yí kuài táng.","vi":"Cô ấy ngậm một viên kẹo trong miệng.","en":"She has a piece of candy in her mouth."},{"use":"放到嘴里: bổ ngữ xu hướng, cho vào miệng.","ex":"这个糖放到嘴里很甜。","py":"Zhège táng fàng dào zuǐlǐ hěn tián.","vi":"Viên kẹo này cho vào miệng rất ngọt.","en":"This candy tastes very sweet in your mouth."},{"use":"嘴里 + 说着 + lời nói: miệng nói gì.","ex":"他嘴里一直说着“对不起”。","py":"Tā zuǐlǐ yìzhí shuōzhe “duìbuqǐ”.","vi":"Miệng anh ấy cứ liên tục nói “xin lỗi”.","en":"He kept saying \"sorry.\""}]},"变得":{"en":"to become; to turn into","exs":[{"use":"变得 + tính từ: trở nên ...","ex":"天气变得越来越冷。","py":"Tiānqì biàn de yuè lái yuè lěng.","vi":"Thời tiết trở nên ngày càng lạnh.","en":"The weather is getting colder and colder."},{"use":"变得 + 很 + tính từ: miêu tả sự thay đổi tính cách.","ex":"他最近变得很安静。","py":"Tā zuìjìn biàn de hěn ānjìng.","vi":"Gần đây anh ấy trở nên rất trầm lặng.","en":"He has become very quiet lately."},{"use":"变得 + 越来越 + tính từ: ngày càng.","ex":"这座城市变得越来越漂亮。","py":"Zhè zuò chéngshì biàn de yuè lái yuè piàoliang.","vi":"Thành phố này ngày càng đẹp.","en":"This city is becoming more and more beautiful."},{"use":"经过 … 变得 + tính từ + 了: kết quả sau quá trình.","ex":"经过努力，他的汉语变得流利了。","py":"Jīngguò nǔlì, tā de Hànyǔ biàn de liúlì le.","vi":"Sau nỗ lực, tiếng Trung của anh ấy đã trở nên trôi chảy.","en":"After hard work, his Chinese has become fluent."}]},"有意思":{"en":"interesting; fun","exs":[{"use":"有意思 làm vị ngữ: thú vị.","ex":"这本小说很有意思。","py":"Zhè běn xiǎoshuō hěn yǒu yìsi.","vi":"Cuốn tiểu thuyết này rất thú vị.","en":"This novel is very interesting."},{"use":"有意思吗: dạng nghi vấn.","ex":"你觉得这个游戏有意思吗？","py":"Nǐ juéde zhège yóuxì yǒu yìsi ma?","vi":"Bạn thấy trò chơi này có thú vị không?","en":"Do you think this game is fun?"},{"use":"V + 起来 / 学 + 有意思: hoạt động thú vị.","ex":"学汉字很有意思。","py":"Xué Hànzì hěn yǒu yìsi.","vi":"Học chữ Hán rất thú vị.","en":"Learning Chinese characters is very interesting."},{"use":"有意思的 + 人 / 事: bổ nghĩa cho danh từ.","ex":"他是个有意思的人，跟他聊天很开心。","py":"Tā shì ge yǒu yìsi de rén, gēn tā liáotiān hěn kāixīn.","vi":"Anh ấy là người thú vị, trò chuyện với anh ấy rất vui.","en":"He is an interesting person, and chatting with him is fun."}]},"时候":{"en":"time; moment; when","exs":[{"use":"Thời gian + 的时候: khi ...","ex":"我吃饭的时候不看手机。","py":"Wǒ chīfàn de shíhou bú kàn shǒujī.","vi":"Khi ăn cơm tôi không xem điện thoại.","en":"I don't look at my phone when I eat."},{"use":"小时候: hồi còn nhỏ.","ex":"小时候我住在农村。","py":"Xiǎoshíhou wǒ zhù zài nóngcūn.","vi":"Hồi nhỏ tôi sống ở nông thôn.","en":"When I was little, I lived in the countryside."},{"use":"什么时候: hỏi thời điểm.","ex":"你什么时候下班？","py":"Nǐ shénme shíhou xiàbān?","vi":"Mấy giờ bạn tan làm?","en":"When do you get off work?"},{"use":"是 … 的时候了: đã đến lúc ...","ex":"现在是休息的时候了。","py":"Xiànzài shì xiūxi de shíhou le.","vi":"Bây giờ đã đến lúc nghỉ ngơi rồi.","en":"It's time to take a rest now."}]},"总是":{"en":"always; all the time","exs":[{"use":"总是 + động từ: luôn luôn làm gì (thói quen).","ex":"他总是第一个到教室。","py":"Tā zǒngshì dì yī gè dào jiàoshì.","vi":"Anh ấy luôn là người đến lớp đầu tiên.","en":"He is always the first to arrive at the classroom."},{"use":"总是 + 担心 / 想: thường xuyên lo nghĩ.","ex":"妈妈总是担心我吃不饱。","py":"Māma zǒngshì dānxīn wǒ chī bù bǎo.","vi":"Mẹ luôn lo con ăn không no.","en":"Mom always worries that I don't eat enough."},{"use":"为什么 + 总是 …: trách móc, hỏi vì sao lúc nào cũng ...","ex":"你为什么总是迟到？","py":"Nǐ wèishénme zǒngshì chídào?","vi":"Sao bạn lúc nào cũng đến muộn?","en":"Why are you always late?"},{"use":"总是 + V + 着: trạng thái kéo dài.","ex":"她总是笑着跟别人说话。","py":"Tā zǒngshì xiàozhe gēn biérén shuōhuà.","vi":"Cô ấy luôn tươi cười khi nói chuyện với người khác.","en":"She always talks to others with a smile."}]},"办法":{"en":"method; way; means","exs":[{"use":"想办法 = tìm cách.","ex":"我想到了一个办法。","py":"Wǒ xiǎngdào le yí gè bànfǎ.","vi":"Tôi nghĩ ra một cách.","en":"I thought of a way."},{"use":"没有办法 + V: không có cách nào để ...","ex":"这个问题没有办法解决。","py":"Zhège wèntí méiyǒu bànfǎ jiějué.","vi":"Vấn đề này không có cách nào giải quyết.","en":"There's no way to solve this problem."},{"use":"想办法: cụm cố định, tìm cách.","ex":"我们一起想办法吧。","py":"Wǒmen yìqǐ xiǎng bànfǎ ba.","vi":"Chúng ta cùng nghĩ cách nhé.","en":"Let's figure out a way together."},{"use":"有 + 什么 + 好办法: hỏi cách hay.","ex":"你有什么好办法吗？","py":"Nǐ yǒu shénme hǎo bànfǎ ma?","vi":"Bạn có cách nào hay không?","en":"Do you have any good ideas?"}]},"高兴":{"en":"happy; glad; pleased","exs":[{"use":"高兴 làm vị ngữ: 很高兴.","ex":"见到你我很高兴。","py":"Jiàndào nǐ wǒ hěn gāoxìng.","vi":"Gặp bạn tôi rất vui.","en":"I'm very happy to see you."},{"use":"高兴得 + kết quả (bổ ngữ trạng thái).","ex":"她高兴得跳了起来。","py":"Tā gāoxìng de tiào le qǐlái.","vi":"Cô ấy vui đến mức nhảy cẫng lên.","en":"She was so happy that she jumped up."},{"use":"很高兴 + động từ: vui khi làm gì.","ex":"我很高兴认识你。","py":"Wǒ hěn gāoxìng rènshi nǐ.","vi":"Tôi rất vui được làm quen với bạn.","en":"I'm very glad to meet you."},{"use":"高兴地 + động từ: làm trạng ngữ.","ex":"他高兴地告诉我们这个好消息。","py":"Tā gāoxìng de gàosù wǒmen zhège hǎo xiāoxi.","vi":"Anh ấy vui vẻ báo cho chúng tôi tin tốt này.","en":"He happily told us this good news."}]},"而且":{"en":"and also; moreover; but also; furthermore","exs":[{"use":"Nối hai tính từ/phân câu cùng hướng: A，而且 B (hơn nữa)","ex":"这家餐厅的菜很好吃，而且很便宜。","py":"Zhè jiā cāntīng de cài hěn hǎochī, érqiě hěn piányi.","vi":"Món ăn của nhà hàng này rất ngon, mà còn rất rẻ.","en":"The food at this restaurant is delicious, and it is also cheap."},{"use":"Cấu trúc 不但…而且… (không những… mà còn…)","ex":"他不但会说英语，而且说得很流利。","py":"Tā búdàn huì shuō Yīngyǔ, érqiě shuō de hěn liúlì.","vi":"Anh ấy không những biết nói tiếng Anh mà còn nói rất lưu loát.","en":"He can not only speak English, but also speaks it very fluently."},{"use":"Nối hai phân câu, thường đi với 还 để nhấn mạnh thêm","ex":"今天天气很冷，而且还下着大雨。","py":"Jīntiān tiānqì hěn lěng, érqiě hái xiàzhe dàyǔ.","vi":"Hôm nay trời rất lạnh, hơn nữa còn mưa rất to.","en":"It is very cold today, and it is also pouring rain."}]},"不错":{"en":"not bad; pretty good; quite good","exs":[{"use":"Làm vị ngữ: chủ ngữ + 不错 (khen mức khá tốt)","ex":"这家饭店的菜味道不错。","py":"Zhè jiā fàndiàn de cài wèidao búcuò.","vi":"Món ăn của quán này có vị khá ngon.","en":"The food at this restaurant tastes pretty good."},{"use":"V + 得 + 不错: đánh giá khả năng, kết quả","ex":"你的汉语说得不错。","py":"Nǐ de Hànyǔ shuō de búcuò.","vi":"Tiếng Hán của bạn nói khá tốt đấy.","en":"You speak Chinese quite well."},{"use":"Dùng với 一直 để nói trạng thái tốt duy trì","ex":"他的成绩一直不错。","py":"Tā de chéngjì yìzhí búcuò.","vi":"Thành tích của cậu ấy luôn khá tốt.","en":"His grades have always been pretty good."},{"use":"Dùng để tán thành một ý kiến: 这个…不错","ex":"这个主意不错，我们就这么办吧。","py":"Zhège zhǔyi búcuò, wǒmen jiù zhème bàn ba.","vi":"Ý kiến này hay đấy, chúng ta cứ làm như vậy đi.","en":"That's a good idea. Let's do it that way."}]},"为什么":{"en":"why; what for","exs":[{"use":"Hỏi nguyên nhân: 为什么 + động từ/tính từ","ex":"你为什么没来上课？","py":"Nǐ wèishénme méi lái shàngkè?","vi":"Sao bạn không đến lớp?","en":"Why didn't you come to class?"},{"use":"Đặt trước vị ngữ hoặc đứng đầu câu để hỏi lý do","ex":"他为什么不高兴？","py":"Tā wèishénme bù gāoxìng?","vi":"Tại sao anh ấy không vui?","en":"Why is he unhappy?"},{"use":"Làm tân ngữ trong câu hỏi gián tiếp: 不知道为什么…","ex":"我不知道为什么今天特别累。","py":"Wǒ bù zhīdào wèishénme jīntiān tèbié lèi.","vi":"Tôi không biết tại sao hôm nay mệt đặc biệt.","en":"I don't know why I'm especially tired today."}]},"听说":{"en":"to hear (that); it is said that; reportedly","exs":[{"use":"听说 + mệnh đề: nghe nói rằng…","ex":"听说明天会下雨。","py":"Tīngshuō míngtiān huì xià yǔ.","vi":"Nghe nói ngày mai sẽ mưa.","en":"I hear it's going to rain tomorrow."},{"use":"Đặt đầu câu dẫn tin nghe được từ người khác","ex":"听说他要去国外工作。","py":"Tīngshuō tā yào qù guówài gōngzuò.","vi":"Nghe nói anh ấy sắp ra nước ngoài làm việc.","en":"I heard he is going to work abroad."},{"use":"听说过: đã từng nghe nói về (người/nơi chốn)","ex":"我听说过这个地方，但是没去过。","py":"Wǒ tīngshuō guo zhège dìfang, dànshì méi qù guo.","vi":"Tôi từng nghe nói về nơi này nhưng chưa đến.","en":"I've heard of this place, but I've never been there."},{"use":"Dùng để xác nhận tin đồn trong câu hỏi","ex":"听说你搬家了，是真的吗？","py":"Tīngshuō nǐ bānjiā le, shì zhēn de ma?","vi":"Nghe nói bạn chuyển nhà rồi, có thật không?","en":"I heard you moved. Is it true?"}]},"男朋友":{"en":"boyfriend","exs":[{"use":"Danh từ: 她的男朋友 (bạn trai của cô ấy)","ex":"她的男朋友是一名医生。","py":"Tā de nánpéngyou shì yì míng yīshēng.","vi":"Bạn trai của cô ấy là bác sĩ.","en":"Her boyfriend is a doctor."},{"use":"和 + 男朋友 + V: làm gì cùng bạn trai","ex":"周末我要和男朋友去看电影。","py":"Zhōumò wǒ yào hé nánpéngyou qù kàn diànyǐng.","vi":"Cuối tuần tôi sẽ đi xem phim với bạn trai.","en":"I'm going to the movies with my boyfriend this weekend."},{"use":"有/没有 + 男朋友: hỏi tình trạng yêu đương","ex":"你有男朋友吗？","py":"Nǐ yǒu nánpéngyou ma?","vi":"Bạn có bạn trai chưa?","en":"Do you have a boyfriend?"},{"use":"给 + 男朋友 + V: làm gì cho bạn trai","ex":"她给男朋友买了一件礼物。","py":"Tā gěi nánpéngyou mǎi le yí jiàn lǐwù.","vi":"Cô ấy mua cho bạn trai một món quà.","en":"She bought a gift for her boyfriend."}]},"学校":{"en":"school","exs":[{"use":"Danh từ chỉ nơi chốn: 我们学校","ex":"我们学校离地铁站很近。","py":"Wǒmen xuéxiào lí dìtiězhàn hěn jìn.","vi":"Trường chúng tôi cách ga tàu điện ngầm rất gần.","en":"Our school is very close to the subway station."},{"use":"去/到 + 学校: đến trường","ex":"他每天骑自行车去学校。","py":"Tā měitiān qí zìxíngchē qù xuéxiào.","vi":"Mỗi ngày cậu ấy đạp xe đến trường.","en":"He rides his bike to school every day."},{"use":"学校里: bên trong trường","ex":"学校里有一个很大的图书馆。","py":"Xuéxiào lǐ yǒu yí gè hěn dà de túshūguǎn.","vi":"Trong trường có một thư viện rất lớn.","en":"There is a very big library in the school."},{"use":"学校附近: khu vực gần trường","ex":"学校附近有很多小饭馆。","py":"Xuéxiào fùjìn yǒu hěn duō xiǎo fànguǎn.","vi":"Gần trường có rất nhiều quán ăn nhỏ.","en":"There are many small restaurants near the school."}]},"同学":{"en":"classmate; schoolmate","exs":[{"use":"Danh từ: 大学同学 (bạn học đại học)","ex":"他是我的大学同学。","py":"Tā shì wǒ de dàxué tóngxué.","vi":"Anh ấy là bạn học đại học của tôi.","en":"He is my university classmate."},{"use":"同学们: cách thầy cô gọi học sinh","ex":"同学们，请打开书。","py":"Tóngxuémen, qǐng dǎkāi shū.","vi":"Các em học sinh, mời mở sách ra.","en":"Class, please open your books."},{"use":"和 + 同学 + 一起 + V","ex":"我和同学一起复习功课。","py":"Wǒ hé tóngxué yìqǐ fùxí gōngkè.","vi":"Tôi ôn bài cùng bạn học.","en":"I review my lessons together with my classmates."},{"use":"Kết hợp: 小学/中学/大学 + 同学","ex":"昨天我遇到了一位小学同学。","py":"Zuótiān wǒ yùdào le yí wèi xiǎoxué tóngxué.","vi":"Hôm qua tôi gặp một người bạn học hồi tiểu học.","en":"Yesterday I ran into a former primary school classmate."}]},"新闻":{"en":"news","exs":[{"use":"看/听 + 新闻: xem/nghe tin tức","ex":"我每天晚上看新闻。","py":"Wǒ měitiān wǎnshang kàn xīnwén.","vi":"Tối nào tôi cũng xem tin tức.","en":"I watch the news every evening."},{"use":"Lượng từ 条: 一条新闻","ex":"这条新闻是真的吗？","py":"Zhè tiáo xīnwén shì zhēn de ma?","vi":"Tin này có thật không?","en":"Is this news story true?"},{"use":"Làm định ngữ: 新闻记者 (phóng viên)","ex":"他是一名新闻记者。","py":"Tā shì yì míng xīnwén jìzhě.","vi":"Anh ấy là một phóng viên.","en":"He is a news reporter."},{"use":"Chỉ nguồn tin: 网上的新闻","ex":"网上的新闻有时候不太可靠。","py":"Wǎngshàng de xīnwén yǒushíhou bú tài kěkào.","vi":"Tin tức trên mạng đôi khi không đáng tin lắm.","en":"News online is sometimes not very reliable."}]},"法律":{"en":"law; legislation","exs":[{"use":"遵守 + 法律: tuân thủ pháp luật","ex":"每个人都应该遵守法律。","py":"Měi gè rén dōu yīnggāi zūnshǒu fǎlǜ.","vi":"Mỗi người đều nên tuân thủ pháp luật.","en":"Everyone should obey the law."},{"use":"学习 + 法律: học luật (ngành học)","ex":"他在大学学习法律。","py":"Tā zài dàxué xuéxí fǎlǜ.","vi":"Anh ấy học luật ở đại học.","en":"He studies law at university."},{"use":"Cụm cố định: 法律面前人人平等","ex":"法律面前人人平等。","py":"Fǎlǜ miànqián rénrén píngděng.","vi":"Trước pháp luật mọi người đều bình đẳng.","en":"Everyone is equal before the law."},{"use":"Lượng từ 部: một bộ luật","ex":"这是一部新的法律。","py":"Zhè shì yí bù xīn de fǎlǜ.","vi":"Đây là một bộ luật mới.","en":"This is a new law."}]},"怎么":{"en":"how; why; what (is wrong)","exs":[{"use":"Hỏi cách thức: 怎么 + động từ","ex":"这个字怎么读？","py":"Zhège zì zěnme dú?","vi":"Chữ này đọc thế nào?","en":"How do you pronounce this character?"},{"use":"Hỏi nguyên nhân, mang sắc thái ngạc nhiên","ex":"你怎么还没睡？","py":"Nǐ zěnme hái méi shuì?","vi":"Sao bạn vẫn chưa ngủ?","en":"How come you're still not asleep?"},{"use":"怎么了: có chuyện gì vậy?","ex":"你怎么了？哪儿不舒服吗？","py":"Nǐ zěnme le? Nǎr bù shūfu ma?","vi":"Bạn sao vậy? Khó chịu ở đâu à?","en":"What's wrong? Are you feeling unwell?"},{"use":"怎么也 + V (không thể nào…)","ex":"这道题我怎么也做不出来。","py":"Zhè dào tí wǒ zěnme yě zuò bù chūlái.","vi":"Bài này tôi thế nào cũng không làm ra.","en":"No matter what I do, I can't solve this problem."},{"use":"不怎么 + adj: không … lắm","ex":"这家店的菜不怎么好吃。","py":"Zhè jiā diàn de cài bù zěnme hǎochī.","vi":"Món ăn của quán này không ngon lắm.","en":"The food at this restaurant isn't very good."}]},"认识":{"en":"to know; to recognize; to be acquainted with; understanding; awareness","exs":[{"use":"Động từ: 认识 + người (quen biết)","ex":"很高兴认识你。","py":"Hěn gāoxìng rènshi nǐ.","vi":"Rất vui được quen biết bạn.","en":"Nice to meet you."},{"use":"Động từ: 认识 + chữ/vật (nhận biết)","ex":"我不认识这个字。","py":"Wǒ bú rènshi zhège zì.","vi":"Tôi không biết chữ này.","en":"I don't recognize this character."},{"use":"Danh từ: 有了…认识 (cách hiểu, nhận thức)","ex":"他对这个问题有了新的认识。","py":"Tā duì zhège wèntí yǒu le xīn de rènshi.","vi":"Anh ấy có nhận thức mới về vấn đề này.","en":"He has gained a new understanding of this issue."},{"use":"是…认识的: nhấn mạnh nơi/cách quen nhau","ex":"我们是在北京认识的。","py":"Wǒmen shì zài Běijīng rènshi de.","vi":"Chúng tôi quen nhau ở Bắc Kinh.","en":"We met in Beijing."}]},"足球比赛":{"en":"football (soccer) match","exs":[{"use":"Danh từ ghép: 足球 + 比赛","ex":"昨天的足球比赛非常精彩。","py":"Zuótiān de zúqiú bǐsài fēicháng jīngcǎi.","vi":"Trận bóng đá hôm qua rất hấp dẫn.","en":"Yesterday's football match was very exciting."},{"use":"看 + 足球比赛: xem trận đấu","ex":"我们明天去看足球比赛。","py":"Wǒmen míngtiān qù kàn zúqiú bǐsài.","vi":"Ngày mai chúng tôi đi xem bóng đá.","en":"We are going to watch a football match tomorrow."},{"use":"Làm chủ ngữ, kết hợp với 改到 (dời lịch)","ex":"足球比赛因为下雨改到下周了。","py":"Zúqiú bǐsài yīnwèi xià yǔ gǎi dào xià zhōu le.","vi":"Trận bóng đá bị dời sang tuần sau vì mưa.","en":"The football match was postponed to next week because of the rain."}]},"他们":{"en":"they; them","exs":[{"use":"Đại từ làm chủ ngữ","ex":"他们都是我的好朋友。","py":"Tāmen dōu shì wǒ de hǎo péngyou.","vi":"Họ đều là bạn tốt của tôi.","en":"They are all my good friends."},{"use":"Làm tân ngữ","ex":"我昨天见到了他们。","py":"Wǒ zuótiān jiàndào le tāmen.","vi":"Hôm qua tôi đã gặp họ.","en":"I met them yesterday."},{"use":"他们 + 的 + danh từ: sở hữu","ex":"他们的房子又大又漂亮。","py":"Tāmen de fángzi yòu dà yòu piàoliang.","vi":"Nhà của họ vừa to vừa đẹp.","en":"Their house is big and beautiful."},{"use":"他们俩: hai người họ","ex":"他们俩是同一个公司的。","py":"Tāmen liǎ shì tóng yí gè gōngsī de.","vi":"Hai người họ cùng một công ty.","en":"The two of them work at the same company."}]},"比赛":{"en":"match; competition; to compete","exs":[{"use":"Danh từ: 参加 + 比赛","ex":"你参加这次比赛吗？","py":"Nǐ cānjiā zhè cì bǐsài ma?","vi":"Bạn có tham gia cuộc thi lần này không?","en":"Are you taking part in this competition?"},{"use":"Động từ: 和/跟 + người + 比赛 + môn","ex":"我们和三班比赛篮球。","py":"Wǒmen hé sān bān bǐsài lánqiú.","vi":"Chúng tôi thi đấu bóng rổ với lớp ba.","en":"We are playing a basketball match against Class 3."},{"use":"Làm chủ ngữ: 比赛开始了","ex":"比赛开始了。","py":"Bǐsài kāishǐ le.","vi":"Trận đấu bắt đầu rồi.","en":"The match has started."},{"use":"在比赛中: trong cuộc thi; 得第一名","ex":"他在比赛中得了第一名。","py":"Tā zài bǐsài zhōng dé le dì yī míng.","vi":"Anh ấy giành giải nhất trong cuộc thi.","en":"He won first place in the competition."}]},"踢进":{"en":"to kick (the ball) in; to score by kicking","exs":[{"use":"把 + 球 + 踢进 + 球门","ex":"他一脚把球踢进了球门。","py":"Tā yì jiǎo bǎ qiú tījìn le qiúmén.","vi":"Anh ấy một cú đá đưa bóng vào khung thành.","en":"He kicked the ball into the goal with one shot."},{"use":"踢进 + số lượng + 个球: ghi bao nhiêu bàn","ex":"小王在比赛中踢进了两个球。","py":"Xiǎo Wáng zài bǐsài zhōng tījìn le liǎng gè qiú.","vi":"Tiểu Vương đã ghi hai bàn trong trận đấu.","en":"Xiao Wang scored two goals in the match."},{"use":"Câu giả thiết: 如果能踢进…","ex":"如果能踢进这个球，我们就赢了。","py":"Rúguǒ néng tījìn zhège qiú, wǒmen jiù yíng le.","vi":"Nếu đá vào được quả này thì chúng ta thắng.","en":"If we can score this one, we win."},{"use":"踢进 + 了 + 最后一球","ex":"他踢进了最后一球。","py":"Tā tījìn le zuìhòu yì qiú.","vi":"Anh ấy đã ghi bàn ở quả cuối cùng.","en":"He scored the final goal."}]},"印象":{"en":"impression","exs":[{"use":"给…留下印象; 对…印象好","ex":"这个城市给我的印象很好。","py":"Zhège chéngshì gěi wǒ de yìnxiàng hěn hǎo.","vi":"Thành phố này để lại cho tôi ấn tượng rất tốt.","en":"This city made a very good impression on me."},{"use":"给 + người + 留下 + 印象 (để lại ấn tượng)","ex":"他给我留下了很深的印象。","py":"Tā gěi wǒ liúxià le hěn shēn de yìnxiàng.","vi":"Anh ấy để lại trong tôi ấn tượng rất sâu sắc.","en":"He left a deep impression on me."},{"use":"对 + sự vật + 的印象: ấn tượng về…","ex":"我对这家公司的印象不错。","py":"Wǒ duì zhè jiā gōngsī de yìnxiàng búcuò.","vi":"Tôi có ấn tượng khá tốt về công ty này.","en":"I have a pretty good impression of this company."},{"use":"第一印象: ấn tượng đầu tiên","ex":"第一印象很重要。","py":"Dì yī yìnxiàng hěn zhòngyào.","vi":"Ấn tượng đầu tiên rất quan trọng.","en":"First impressions are very important."},{"use":"没有印象: không nhớ/không có ấn tượng","ex":"我对那个人没有印象了。","py":"Wǒ duì nàge rén méiyǒu yìnxiàng le.","vi":"Tôi không còn ấn tượng gì về người đó.","en":"I no longer remember that person."}]},"后来":{"en":"afterwards; later; after that","exs":[{"use":"Chỉ trình tự quá khứ: 先…，后来…","ex":"他先去了上海，后来又去了广州。","py":"Tā xiān qù le Shànghǎi, hòulái yòu qù le Guǎngzhōu.","vi":"Anh ấy đi Thượng Hải trước, sau đó lại đi Quảng Châu.","en":"He went to Shanghai first, and later to Guangzhou."},{"use":"Chỉ sự thay đổi: 以前…，后来…","ex":"我们以前是邻居，后来他搬走了。","py":"Wǒmen yǐqián shì línjū, hòulái tā bānzǒu le.","vi":"Trước đây chúng tôi là hàng xóm, về sau anh ấy chuyển đi.","en":"We used to be neighbors, but later he moved away."},{"use":"后来呢？/ 后来怎么样了？ hỏi diễn biến tiếp theo","ex":"你说的那件事，后来怎么样了？","py":"Nǐ shuō de nà jiàn shì, hòulái zěnmeyàng le?","vi":"Chuyện bạn nói đó, sau này thế nào rồi?","en":"What happened with that matter you mentioned afterwards?"},{"use":"一开始…，后来…: lúc đầu… về sau…","ex":"他一开始不喜欢这里，后来慢慢习惯了。","py":"Tā yì kāishǐ bù xǐhuan zhèlǐ, hòulái mànmàn xíguàn le.","vi":"Lúc đầu anh ấy không thích nơi này, sau dần quen.","en":"At first he didn't like it here, but later he gradually got used to it."}]},"熟悉":{"en":"familiar; to be familiar with","exs":[{"use":"对 + nơi/người + 很熟悉","ex":"我对这个城市很熟悉。","py":"Wǒ duì zhège chéngshì hěn shúxī.","vi":"Tôi rất quen thuộc với thành phố này.","en":"I am very familiar with this city."},{"use":"熟悉 + tình hình/nội dung (động từ)","ex":"他很熟悉这里的情况。","py":"Tā hěn shúxī zhèlǐ de qíngkuàng.","vi":"Anh ấy rất rành tình hình ở đây.","en":"He knows the situation here very well."},{"use":"Làm vị ngữ: 听着/看着…很熟悉","ex":"我听着这个声音很熟悉。","py":"Wǒ tīng zhe zhège shēngyīn hěn shúxī.","vi":"Nghe giọng nói này tôi thấy rất quen.","en":"This voice sounds very familiar to me."},{"use":"还不太熟悉: chưa quen lắm","ex":"刚到公司，我还不太熟悉工作。","py":"Gāng dào gōngsī, wǒ hái bú tài shúxī gōngzuò.","vi":"Mới vào công ty, tôi vẫn chưa quen việc lắm.","en":"I just joined the company and I'm not yet very familiar with the work."}]},"喜欢":{"en":"to like; to be fond of","exs":[{"use":"喜欢 + danh từ / động từ.","ex":"我喜欢蓝色。","py":"Wǒ xǐhuan lánsè.","vi":"Tôi thích màu xanh lam.","en":"I like blue."},{"use":"喜欢 + V: thích làm việc gì","ex":"我喜欢在周末去爬山。","py":"Wǒ xǐhuan zài zhōumò qù páshān.","vi":"Tôi thích đi leo núi vào cuối tuần.","en":"I like to go hiking on weekends."},{"use":"喜欢 + người: có cảm tình/thích ai","ex":"孩子们都很喜欢她。","py":"Háizimen dōu hěn xǐhuan tā.","vi":"Bọn trẻ đều rất thích cô ấy.","en":"All the children like her."},{"use":"不喜欢 + V: phủ định","ex":"他不喜欢吃辣的。","py":"Tā bù xǐhuan chī là de.","vi":"Anh ấy không thích ăn cay.","en":"He doesn't like spicy food."},{"use":"喜欢上: bắt đầu thích (kết quả)","ex":"她很快就喜欢上了这座城市。","py":"Tā hěn kuài jiù xǐhuan shàng le zhè zuò chéngshì.","vi":"Cô ấy nhanh chóng yêu thích thành phố này.","en":"She soon grew fond of this city."}]},"足球":{"en":"football; soccer","exs":[{"use":"Chơi bóng đá: 踢足球","ex":"我弟弟喜欢踢足球。","py":"Wǒ dìdi xǐhuan tī zúqiú.","vi":"Em trai tôi thích đá bóng.","en":"My younger brother likes playing football."},{"use":"Làm chủ ngữ để nói về môn thể thao","ex":"足球是世界上最受欢迎的运动。","py":"Zúqiú shì shìjiè shàng zuì shòu huānyíng de yùndòng.","vi":"Bóng đá là môn thể thao được yêu thích nhất thế giới.","en":"Football is the most popular sport in the world."},{"use":"Danh từ chỉ quả bóng: 一个足球","ex":"他买了一个新足球。","py":"Tā mǎi le yí gè xīn zúqiú.","vi":"Anh ấy mua một quả bóng đá mới.","en":"He bought a new football."},{"use":"足球队: đội bóng đá","ex":"我们学校有一支足球队。","py":"Wǒmen xuéxiào yǒu yì zhī zúqiúduì.","vi":"Trường chúng tôi có một đội bóng đá.","en":"Our school has a football team."}]},"李老师":{"en":"Teacher Li; Mr./Ms. Li (teacher)","exs":[{"use":"Họ + 老师: cách xưng hô tôn trọng","ex":"李老师是我们的汉语老师。","py":"Lǐ lǎoshī shì wǒmen de Hànyǔ lǎoshī.","vi":"Thầy/Cô Lý là giáo viên tiếng Hán của chúng tôi.","en":"Teacher Li is our Chinese teacher."},{"use":"Gọi trực tiếp thầy cô khi hỏi","ex":"李老师，我有一个问题想问您。","py":"Lǐ lǎoshī, wǒ yǒu yí gè wèntí xiǎng wèn nín.","vi":"Thầy/Cô Lý, em có một câu hỏi muốn hỏi ạ.","en":"Teacher Li, I have a question I'd like to ask you."},{"use":"Làm chủ ngữ trong câu kể","ex":"今天李老师请假了。","py":"Jīntiān Lǐ lǎoshī qǐngjià le.","vi":"Hôm nay thầy/cô Lý xin nghỉ.","en":"Teacher Li is on leave today."},{"use":"Dùng trong lời cảm ơn","ex":"谢谢李老师的帮助。","py":"Xièxie Lǐ lǎoshī de bāngzhù.","vi":"Cảm ơn sự giúp đỡ của thầy/cô Lý.","en":"Thank you, Teacher Li, for your help."}]},"下个月":{"en":"next month","exs":[{"use":"Từ chỉ thời gian đặt trước động từ","ex":"我下个月去旅行。","py":"Wǒ xià gè yuè qù lǚxíng.","vi":"Tháng sau tôi đi du lịch.","en":"I'm going on a trip next month."},{"use":"Thời gian đứng đầu câu làm trạng ngữ","ex":"下个月我们公司有一个会议。","py":"Xià gè yuè wǒmen gōngsī yǒu yí gè huìyì.","vi":"Tháng sau công ty chúng tôi có một cuộc họp.","en":"Next month our company has a meeting."},{"use":"Đi với 开始/结婚… chỉ sự việc sắp tới","ex":"他下个月结婚。","py":"Tā xià gè yuè jiéhūn.","vi":"Tháng sau anh ấy kết hôn.","en":"He is getting married next month."},{"use":"下个月才 + V: mãi đến tháng sau mới…","ex":"房租要下个月才交。","py":"Fángzū yào xià gè yuè cái jiāo.","vi":"Tiền thuê nhà đến tháng sau mới nộp.","en":"The rent isn't due until next month."}]},"开玩笑":{"en":"to joke; to make fun of; to kid","exs":[{"use":"别…了: yêu cầu đừng đùa","ex":"别开玩笑了，我不信。","py":"Bié kāi wánxiào le, wǒ bú xìn.","vi":"Đừng đùa nữa, tôi không tin đâu.","en":"Stop joking, I don't believe it."},{"use":"爱 + 开玩笑: hay đùa","ex":"他很爱开玩笑。","py":"Tā hěn ài kāi wánxiào.","vi":"Anh ấy rất hay đùa.","en":"He loves to joke around."},{"use":"只是…: chỉ là nói đùa","ex":"我只是开玩笑，你别生气。","py":"Wǒ zhǐshì kāi wánxiào, nǐ bié shēngqì.","vi":"Tôi chỉ đùa thôi, bạn đừng giận.","en":"I'm just kidding. Don't be angry."},{"use":"你不是在…吧？ hỏi lại, không tin","ex":"你不是在开玩笑吧？","py":"Nǐ bú shì zài kāi wánxiào ba?","vi":"Bạn không phải đang đùa đấy chứ?","en":"You're not joking, are you?"},{"use":"拿 + người + 开玩笑: lấy ai ra đùa","ex":"你别拿我开玩笑。","py":"Nǐ bié ná wǒ kāi wánxiào.","vi":"Bạn đừng lấy tôi ra đùa.","en":"Don't make fun of me."}]},"虽然":{"en":"although; though","exs":[{"use":"虽然…但是…: tuy… nhưng…","ex":"虽然天气很冷，但是我们还是去爬山了。","py":"Suīrán tiānqì hěn lěng, dànshì wǒmen háishi qù páshān le.","vi":"Tuy trời rất lạnh nhưng chúng tôi vẫn đi leo núi.","en":"Although it was cold, we still went hiking."},{"use":"虽然…可是…: dùng 可是 thay 但是","ex":"虽然他年纪小，可是懂很多事情。","py":"Suīrán tā niánjì xiǎo, kěshì dǒng hěn duō shìqing.","vi":"Tuy cậu ấy còn nhỏ nhưng hiểu biết nhiều chuyện.","en":"Although he is young, he understands a lot of things."},{"use":"虽然 đứng sau chủ ngữ","ex":"这个房间虽然不大，但是很干净。","py":"Zhège fángjiān suīrán bú dà, dànshì hěn gānjìng.","vi":"Căn phòng này tuy không lớn nhưng rất sạch.","en":"Although this room is not big, it is very clean."},{"use":"Có thể lược 但是, dùng 还是/却 ở vế sau","ex":"虽然很忙，他每天还是坚持运动。","py":"Suīrán hěn máng, tā měitiān háishi jiānchí yùndòng.","vi":"Tuy rất bận nhưng ngày nào anh ấy cũng kiên trì tập thể dục.","en":"Although he is busy, he still sticks to exercising every day."}]},"时间":{"en":"time; period of time; point in time","exs":[{"use":"没有 + 时间: không có thời gian","ex":"我现在没有时间。","py":"Wǒ xiànzài méiyǒu shíjiān.","vi":"Bây giờ tôi không có thời gian.","en":"I don't have time right now."},{"use":"Khoảng thời gian: 多长时间","ex":"你每天花多长时间学汉语？","py":"Nǐ měitiān huā duō cháng shíjiān xué Hànyǔ?","vi":"Mỗi ngày bạn dành bao lâu để học tiếng Hán?","en":"How much time do you spend studying Chinese every day?"},{"use":"Thời điểm: …的时间是…","ex":"开会的时间是下午三点。","py":"Kāihuì de shíjiān shì xiàwǔ sān diǎn.","vi":"Thời gian họp là ba giờ chiều.","en":"The meeting time is three o'clock in the afternoon."},{"use":"Làm chủ ngữ: 时间过得真快","ex":"时间过得真快。","py":"Shíjiān guò de zhēn kuài.","vi":"Thời gian trôi qua thật nhanh.","en":"Time really flies."}]},"从来":{"en":"always; all along; never (with negation)","exs":[{"use":"从来 + 没/没有 + V + 过: chưa bao giờ","ex":"我从来没去过国外。","py":"Wǒ cónglái méi qù guo guówài.","vi":"Tôi chưa từng ra nước ngoài.","en":"I have never been abroad."},{"use":"从来 + 不 + V: không bao giờ (thói quen)","ex":"他从来不喝咖啡。","py":"Tā cónglái bù hē kāfēi.","vi":"Anh ấy chưa bao giờ uống cà phê.","en":"He never drinks coffee."},{"use":"从来都 + adj: lúc nào cũng, từ trước đến nay","ex":"她从来都很守时。","py":"Tā cónglái dōu hěn shǒushí.","vi":"Cô ấy từ trước đến nay luôn đúng giờ.","en":"She has always been punctual."},{"use":"从来没见过 + …: chưa từng thấy","ex":"我从来没见过这么大的雪。","py":"Wǒ cónglái méi jiàn guo zhème dà de xuě.","vi":"Tôi chưa từng thấy tuyết nào lớn như vậy.","en":"I have never seen such heavy snow."}]},"这么":{"en":"so; such; this way; like this","exs":[{"use":"这么 + tính từ: đến mức như thế","ex":"今天怎么这么热？","py":"Jīntiān zěnme zhème rè?","vi":"Sao hôm nay nóng thế này?","en":"Why is it so hot today?"},{"use":"这么 + động từ: làm theo cách này","ex":"这个字应该这么写。","py":"Zhège zì yīnggāi zhème xiě.","vi":"Chữ này nên viết như thế này.","en":"This character should be written like this."},{"use":"没想到会这么 + adj: không ngờ lại…như vậy","ex":"我没想到会这么难。","py":"Wǒ méi xiǎngdào huì zhème nán.","vi":"Tôi không ngờ lại khó đến vậy.","en":"I didn't expect it to be this difficult."},{"use":"这么多: nhiều như vậy","ex":"你为什么买这么多东西？","py":"Nǐ wèishénme mǎi zhème duō dōngxi?","vi":"Sao bạn mua nhiều đồ như vậy?","en":"Why did you buy so many things?"}]},"快乐":{"en":"happy; joyful; happiness","exs":[{"use":"Chúc: 祝你快乐。 Có thể làm tính từ hoặc danh từ.","ex":"祝你快乐。","py":"Zhù nǐ kuàilè.","vi":"Chúc bạn vui vẻ.","en":"Wishing you happiness."},{"use":"Cụm chúc mừng: 生日快乐","ex":"祝你生日快乐！","py":"Zhù nǐ shēngrì kuàilè!","vi":"Chúc bạn sinh nhật vui vẻ!","en":"Happy birthday to you!"},{"use":"V + 得 + 很快乐: sống vui vẻ","ex":"他们过得很快乐。","py":"Tāmen guò de hěn kuàilè.","vi":"Họ sống rất vui vẻ.","en":"They live very happily."},{"use":"快乐的 + danh từ: định ngữ","ex":"我有一个快乐的童年。","py":"Wǒ yǒu yí gè kuàilè de tóngnián.","vi":"Tôi có một tuổi thơ vui vẻ.","en":"I had a happy childhood."},{"use":"新年快乐: lời chúc năm mới","ex":"新年快乐，祝大家身体健康！","py":"Xīnnián kuàilè, zhù dàjiā shēntǐ jiànkāng!","vi":"Chúc mừng năm mới, chúc mọi người mạnh khỏe!","en":"Happy New Year, and wishing everyone good health!"}]},"最好":{"en":"had better; best; it would be best","exs":[{"use":"Phó từ: 最好 + V (tốt nhất là…)","ex":"你最好早点儿睡。","py":"Nǐ zuìhǎo zǎodiǎnr shuì.","vi":"Tốt nhất là bạn nên ngủ sớm một chút.","en":"You had better go to bed a bit earlier."},{"use":"最好 + đi khám/làm gì khi gặp vấn đề","ex":"你感冒了，最好去医院看看。","py":"Nǐ gǎnmào le, zuìhǎo qù yīyuàn kànkan.","vi":"Bạn bị cảm rồi, tốt nhất nên đến bệnh viện khám.","en":"You've caught a cold, so you'd better see a doctor."},{"use":"Tính từ: 最好的 + danh từ (tốt nhất)","ex":"他是我最好的朋友。","py":"Tā shì wǒ zuìhǎo de péngyou.","vi":"Anh ấy là người bạn tốt nhất của tôi.","en":"He is my best friend."},{"use":"最好的办法: cách tốt nhất","ex":"这是最好的办法。","py":"Zhè shì zuìhǎo de bànfǎ.","vi":"Đây là cách tốt nhất.","en":"This is the best way."},{"use":"最好别 + V: tốt nhất đừng","ex":"下雨天最好别出门。","py":"Xià yǔ tiān zuìhǎo bié chūmén.","vi":"Ngày mưa tốt nhất đừng ra ngoài.","en":"It's best not to go out on rainy days."}]},"兴趣":{"en":"interest; hobby","exs":[{"use":"对 + sự vật + 有兴趣 / 感兴趣.","ex":"他对音乐很有兴趣。","py":"Tā duì yīnyuè hěn yǒu xìngqù.","vi":"Anh ấy rất có hứng thú với âm nhạc.","en":"He is very interested in music."},{"use":"对…感兴趣: hứng thú với…","ex":"我对中国历史很感兴趣。","py":"Wǒ duì Zhōngguó lìshǐ hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với lịch sử Trung Quốc.","en":"I am very interested in Chinese history."},{"use":"有兴趣 + V: có hứng thú làm gì","ex":"你有兴趣一起去爬山吗？","py":"Nǐ yǒu xìngqù yìqǐ qù páshān ma?","vi":"Bạn có hứng thú đi leo núi cùng không?","en":"Are you interested in going hiking together?"},{"use":"对…一点儿兴趣也没有: hoàn toàn không hứng thú","ex":"他对做饭一点儿兴趣也没有。","py":"Tā duì zuòfàn yìdiǎnr xìngqù yě méiyǒu.","vi":"Anh ấy chẳng có chút hứng thú nào với việc nấu ăn.","en":"He has no interest in cooking at all."},{"use":"Nghĩa sở thích; 培养兴趣: bồi dưỡng hứng thú","ex":"父母应该培养孩子读书的兴趣。","py":"Fùmǔ yīnggāi péiyǎng háizi dúshū de xìngqù.","vi":"Cha mẹ nên bồi dưỡng hứng thú đọc sách cho con.","en":"Parents should cultivate their children's interest in reading."}]},"爱好":{"en":"hobby; interest; to be fond of","exs":[{"use":"兴趣爱好 = sở thích.","ex":"我的爱好是看书。","py":"Wǒ de àihào shì kàn shū.","vi":"Sở thích của tôi là đọc sách.","en":"My hobby is reading."},{"use":"Danh từ: 有什么爱好 (hỏi sở thích)","ex":"你有什么爱好？","py":"Nǐ yǒu shénme àihào?","vi":"Bạn có sở thích gì?","en":"What are your hobbies?"},{"use":"Động từ: 爱好 + danh từ (ham thích)","ex":"他爱好音乐，也爱好画画。","py":"Tā àihào yīnyuè, yě àihào huàhuà.","vi":"Anh ấy yêu thích âm nhạc, cũng thích vẽ tranh.","en":"He loves music and also enjoys drawing."},{"use":"业余爱好: sở thích lúc rảnh","ex":"我的业余爱好是游泳。","py":"Wǒ de yèyú àihào shì yóuyǒng.","vi":"Sở thích lúc rảnh của tôi là bơi lội.","en":"My spare-time hobby is swimming."},{"use":"共同的爱好: sở thích chung","ex":"他们有共同的爱好，所以常常在一起聊天。","py":"Tāmen yǒu gòngtóng de àihào, suǒyǐ chángcháng zài yìqǐ liáotiān.","vi":"Họ có chung sở thích nên thường ngồi trò chuyện với nhau.","en":"They share a common hobby, so they often chat together."}]},"经常":{"en":"often; frequently","exs":[{"use":"经常 + V: thường xuyên làm gì","ex":"他经常去图书馆学习。","py":"Tā jīngcháng qù túshūguǎn xuéxí.","vi":"Anh ấy thường xuyên đến thư viện học.","en":"He often goes to the library to study."},{"use":"不经常 + V: không thường xuyên","ex":"我不经常看电视。","py":"Wǒ bù jīngcháng kàn diànshì.","vi":"Tôi không thường xem ti vi.","en":"I don't watch TV very often."},{"use":"应该经常 + V: lời khuyên","ex":"你应该经常给父母打电话。","py":"Nǐ yīnggāi jīngcháng gěi fùmǔ dǎ diànhuà.","vi":"Bạn nên thường xuyên gọi điện cho bố mẹ.","en":"You should call your parents often."},{"use":"经常 + 一起 + V","ex":"我们经常一起吃午饭。","py":"Wǒmen jīngcháng yìqǐ chī wǔfàn.","vi":"Chúng tôi thường ăn trưa cùng nhau.","en":"We often have lunch together."}]},"打球":{"en":"to play ball (basketball, tennis, etc.)","exs":[{"use":"去打球: đi chơi bóng","ex":"我们下午去打球吧。","py":"Wǒmen xiàwǔ qù dǎqiú ba.","vi":"Chiều nay chúng ta đi chơi bóng nhé.","en":"Let's go play ball this afternoon."},{"use":"Chỉ thói quen sau giờ học","ex":"他每天放学后都打球。","py":"Tā měitiān fàngxué hòu dōu dǎqiú.","vi":"Mỗi ngày tan học cậu ấy đều chơi bóng.","en":"He plays ball every day after school."},{"use":"和 + người + 打球: chơi bóng cùng ai","ex":"他喜欢和朋友打球。","py":"Tā xǐhuan hé péngyou dǎqiú.","vi":"Anh ấy thích chơi bóng cùng bạn bè.","en":"He likes playing ball with friends."},{"use":"不能打球: không thể chơi bóng (do bị thương)","ex":"爸爸受伤了，不能打球了。","py":"Bàba shòushāng le, bù néng dǎqiú le.","vi":"Bố bị thương rồi, không thể chơi bóng nữa.","en":"Dad is injured and can't play ball anymore."}]},"唱歌":{"en":"to sing","exs":[{"use":"会唱歌: biết hát","ex":"她很会唱歌。","py":"Tā hěn huì chànggē.","vi":"Cô ấy hát rất hay.","en":"She is a very good singer."},{"use":"去唱歌: rủ nhau đi hát","ex":"晚上我们一起去唱歌吧。","py":"Wǒmen yìqǐ qù chànggē ba.","vi":"Tối nay chúng ta cùng đi hát nhé.","en":"Let's go sing together tonight."},{"use":"一边…一边…: vừa làm vừa hát","ex":"他一边洗澡一边唱歌。","py":"Tā yìbiān xǐzǎo yìbiān chànggē.","vi":"Anh ấy vừa tắm vừa hát.","en":"He sings while taking a shower."},{"use":"唱歌 + V得 + adj: hát như thế nào","ex":"她唱歌唱得很好听。","py":"Tā chànggē chàng de hěn hǎotīng.","vi":"Cô ấy hát rất hay.","en":"She sings beautifully."}]},"做菜":{"en":"to cook; to prepare dishes","exs":[{"use":"Chủ ngữ + 做菜 + adj: nấu ăn (ngon)","ex":"妈妈做菜很好吃。","py":"Māma zuòcài hěn hǎochī.","vi":"Mẹ nấu ăn rất ngon.","en":"Mom's cooking is delicious."},{"use":"喜欢 + 做菜: thích nấu ăn","ex":"我周末喜欢在家做菜。","py":"Wǒ zhōumò xǐhuan zài jiā zuòcài.","vi":"Cuối tuần tôi thích ở nhà nấu ăn.","en":"I like cooking at home on weekends."},{"use":"会做菜 (biết nấu ăn); hỏi khả năng","ex":"你会做菜吗？","py":"Nǐ huì zuòcài ma?","vi":"Bạn biết nấu ăn không?","en":"Can you cook?"},{"use":"不但会…而且…: kết hợp liên từ","ex":"他不但会做菜，而且做得很好。","py":"Tā búdàn huì zuòcài, érqiě zuò de hěn hǎo.","vi":"Anh ấy không những biết nấu ăn mà còn nấu rất ngon.","en":"He can not only cook, but also cooks very well."}]},"看来":{"en":"it seems; it looks as if; apparently","exs":[{"use":"Đứng đầu câu: 看来 + mệnh đề (xem ra)","ex":"看来今天要下雨。","py":"Kànlái jīntiān yào xià yǔ.","vi":"Xem ra hôm nay sắp mưa.","en":"It looks like it is going to rain today."},{"use":"Suy đoán về thái độ của người khác","ex":"看来他不想去。","py":"Kànlái tā bù xiǎng qù.","vi":"Xem ra anh ấy không muốn đi.","en":"It seems he doesn't want to go."},{"use":"看来 + dấu phẩy + kết luận","ex":"看来，你已经准备好了。","py":"Kànlái, nǐ yǐjīng zhǔnbèi hǎo le.","vi":"Xem ra bạn đã chuẩn bị xong rồi.","en":"It seems you are already prepared."},{"use":"Suy luận từ hoàn cảnh rồi đưa ra quyết định","ex":"天这么黑，看来我们得打车回家了。","py":"Tiān zhème hēi, kànlái wǒmen děi dǎchē huíjiā le.","vi":"Trời tối thế này, xem ra chúng ta phải đi taxi về nhà rồi.","en":"It's so dark; it looks like we'll have to take a taxi home."}]},"找到":{"en":"to find; to locate; to have found","exs":[{"use":"找到 + 了 + vật: tìm thấy","ex":"我终于找到了我的手机。","py":"Wǒ zhōngyú zhǎodào le wǒ de shǒujī.","vi":"Cuối cùng tôi cũng tìm thấy điện thoại.","en":"I finally found my phone."},{"use":"找到 + 工作: tìm được việc","ex":"你找到工作了吗？","py":"Nǐ zhǎodào gōngzuò le ma?","vi":"Bạn tìm được việc làm chưa?","en":"Have you found a job yet?"},{"use":"没找到: phủ định bằng 没","ex":"我没找到那家书店。","py":"Wǒ méi zhǎodào nà jiā shūdiàn.","vi":"Tôi không tìm thấy hiệu sách đó.","en":"I couldn't find that bookstore."},{"use":"在…找到: tìm thấy ở đâu","ex":"他在网上找到了便宜的机票。","py":"Tā zài wǎngshàng zhǎodào le piányi de jīpiào.","vi":"Anh ấy tìm được vé máy bay rẻ trên mạng.","en":"He found cheap flight tickets online."}]},"适合":{"en":"to suit; to fit; suitable for","exs":[{"use":"适合 + người / hoàn cảnh.","ex":"这件衣服很适合你。","py":"Zhè jiàn yīfu hěn shìhé nǐ.","vi":"Chiếc áo này rất hợp với bạn.","en":"This piece of clothing suits you very well."},{"use":"适合 + người/hoàn cảnh.","ex":"这份工作很适合你。","py":"Zhè fèn gōngzuò hěn shìhé nǐ.","vi":"Công việc này rất hợp với bạn.","en":"This job is a great fit for you."},{"use":"适合 + V: thích hợp để làm gì","ex":"这双鞋适合走路。","py":"Zhè shuāng xié shìhé zǒulù.","vi":"Đôi giày này thích hợp để đi bộ.","en":"These shoes are suitable for walking."},{"use":"适合 + nhóm người + V","ex":"这个电影适合全家人一起看。","py":"Zhège diànyǐng shìhé quán jiārén yìqǐ kàn.","vi":"Bộ phim này thích hợp cả nhà cùng xem.","en":"This movie is suitable for the whole family to watch together."},{"use":"不适合 + người; 适合的 + danh từ","ex":"他还没找到适合的房子。","py":"Tā hái méi zhǎodào shìhé de fángzi.","vi":"Anh ấy vẫn chưa tìm được căn nhà phù hợp.","en":"He hasn't found a suitable house yet."}]},"老师":{"en":"teacher","exs":[{"use":"Danh từ: 汉语老师","ex":"他是我的汉语老师。","py":"Tā shì wǒ de Hànyǔ lǎoshī.","vi":"Thầy ấy là giáo viên tiếng Hán của tôi.","en":"He is my Chinese teacher."},{"use":"Xưng hô trực tiếp: 老师，…","ex":"老师，请再说一遍。","py":"Lǎoshī, qǐng zài shuō yí biàn.","vi":"Thưa thầy/cô, xin hãy nói lại một lần nữa.","en":"Teacher, please say it once more."},{"use":"Chỉ nghề nghiệp: 小学老师","ex":"我妈妈是小学老师。","py":"Wǒ māma shì xiǎoxué lǎoshī.","vi":"Mẹ tôi là giáo viên tiểu học.","en":"My mother is a primary school teacher."},{"use":"老师 + 让 + người + V","ex":"老师让我们先预习生词。","py":"Lǎoshī ràng wǒmen xiān yùxí shēngcí.","vi":"Thầy cô bảo chúng tôi xem trước từ mới.","en":"The teacher asked us to preview the new words first."}]},"妻子":{"en":"wife","exs":[{"use":"Danh từ: 他的妻子 (vợ của anh ấy)","ex":"他的妻子是一位护士。","py":"Tā de qīzi shì yí wèi hùshi.","vi":"Vợ anh ấy là một y tá.","en":"His wife is a nurse."},{"use":"和妻子结婚: kết hôn với vợ","ex":"他和妻子结婚十年了。","py":"Tā hé qīzi jiéhūn shí nián le.","vi":"Anh ấy kết hôn với vợ đã mười năm.","en":"He has been married to his wife for ten years."},{"use":"爱 + 妻子: yêu vợ","ex":"他很爱他的妻子。","py":"Tā hěn ài tā de qīzi.","vi":"Anh ấy rất yêu vợ mình.","en":"He loves his wife very much."},{"use":"Làm chủ ngữ trong câu kể","ex":"妻子生病了，他请假在家照顾她。","py":"Qīzi shēngbìng le, tā qǐngjià zài jiā zhàogù tā.","vi":"Vợ bị ốm, anh ấy xin nghỉ ở nhà chăm sóc cô ấy.","en":"His wife got sick, so he took leave to take care of her at home."}]},"多年":{"en":"many years; for years","exs":[{"use":"多年 + 的 + danh từ: …nhiều năm","ex":"我们是多年的好朋友。","py":"Wǒmen shì duōnián de hǎo péngyou.","vi":"Chúng tôi là bạn tốt nhiều năm rồi.","en":"We have been good friends for many years."},{"use":"V + 多年 + 了: làm việc gì nhiều năm","ex":"他在这里工作多年了。","py":"Tā zài zhèlǐ gōngzuò duōnián le.","vi":"Anh ấy làm việc ở đây nhiều năm rồi.","en":"He has worked here for many years."},{"use":"多年来: suốt nhiều năm qua","ex":"多年来，他一直坚持锻炼身体。","py":"Duōnián lái, tā yìzhí jiānchí duànliàn shēntǐ.","vi":"Nhiều năm qua anh ấy luôn kiên trì rèn luyện sức khỏe.","en":"For many years, he has kept exercising."},{"use":"…多年后: sau nhiều năm","ex":"分别多年后，他们又见面了。","py":"Fēnbié duōnián hòu, tāmen yòu jiànmiàn le.","vi":"Sau nhiều năm xa cách, họ lại gặp nhau.","en":"After many years apart, they met again."}]},"一直":{"en":"continuously; all along; straight","exs":[{"use":"一直 + V: liên tục, suốt","ex":"这几天一直下雨。","py":"Zhè jǐ tiān yìzhí xià yǔ.","vi":"Mấy hôm nay mưa suốt.","en":"It has been raining all these days."},{"use":"一直 + 往 + hướng + 走: đi thẳng","ex":"一直往前走，就能看到银行。","py":"Yìzhí wǎng qián zǒu, jiù néng kàndào yínháng.","vi":"Cứ đi thẳng về phía trước là thấy ngân hàng.","en":"Go straight ahead and you'll see the bank."},{"use":"一直 + 没 + V: suốt mà vẫn chưa","ex":"他一直没回我的信息。","py":"Tā yìzhí méi huí wǒ de xìnxī.","vi":"Anh ấy vẫn chưa trả lời tin nhắn của tôi.","en":"He still hasn't replied to my message."},{"use":"从…一直…到…: kéo dài từ… đến…","ex":"我从早上一直工作到晚上。","py":"Wǒ cóng zǎoshang yìzhí gōngzuò dào wǎnshang.","vi":"Tôi làm việc từ sáng đến tối.","en":"I worked from morning until night."},{"use":"一直想: luôn muốn","ex":"我一直想去西藏旅行。","py":"Wǒ yìzhí xiǎng qù Xīzàng lǚxíng.","vi":"Tôi luôn muốn đi du lịch Tây Tạng.","en":"I have always wanted to travel to Tibet."}]},"觉得":{"en":"to feel; to think; to consider","exs":[{"use":"觉得 + tính từ/câu: cảm thấy, cho rằng thế nào. Ví dụ: 觉得很累、觉得他说得对。","ex":"我觉得这个方法很好。","py":"Wǒ juéde zhège fāngfǎ hěn hǎo.","vi":"Tôi thấy phương pháp này rất tốt.","en":"I think this method is very good."},{"use":"觉得 + (有点儿) + adj: cảm giác cơ thể","ex":"我觉得有点儿累。","py":"Wǒ juéde yǒudiǎnr lèi.","vi":"Tôi cảm thấy hơi mệt.","en":"I feel a bit tired."},{"use":"Hỏi ý kiến: 你觉得…怎么样？","ex":"你觉得这件衣服怎么样？","py":"Nǐ juéde zhè jiàn yīfu zěnmeyàng?","vi":"Bạn thấy chiếc áo này thế nào?","en":"What do you think of this piece of clothing?"},{"use":"觉得 + chủ ngữ + vị ngữ: cho rằng","ex":"大家都觉得他说得对。","py":"Dàjiā dōu juéde tā shuō de duì.","vi":"Mọi người đều cho rằng anh ấy nói đúng.","en":"Everyone thinks he is right."}]},"新鲜":{"en":"fresh; new and interesting; novel","exs":[{"use":"Tươi (thực phẩm): 很新鲜","ex":"这些水果很新鲜。","py":"Zhèxiē shuǐguǒ hěn xīnxiān.","vi":"Những loại trái cây này rất tươi.","en":"These fruits are very fresh."},{"use":"Tươi mát (không khí)","ex":"早上公园里的空气特别新鲜。","py":"Zǎoshang gōngyuán lǐ de kōngqì tèbié xīnxiān.","vi":"Không khí trong công viên buổi sáng đặc biệt trong lành.","en":"The air in the park is especially fresh in the morning."},{"use":"Mới lạ: 对…来说很新鲜","ex":"这里的一切对我来说都很新鲜。","py":"Zhèlǐ de yíqiè duì wǒ lái shuō dōu hěn xīnxiān.","vi":"Mọi thứ ở đây đối với tôi đều rất mới lạ.","en":"Everything here is novel to me."},{"use":"觉得新鲜: thấy mới mẻ","ex":"孩子们对什么都觉得新鲜。","py":"Háizimen duì shénme dōu juéde xīnxiān.","vi":"Bọn trẻ thấy cái gì cũng mới lạ.","en":"Children find everything new and interesting."},{"use":"新鲜的 + danh từ (làm định ngữ)","ex":"海鲜要吃新鲜的。","py":"Hǎixiān yào chī xīnxiān de.","vi":"Hải sản phải ăn đồ tươi.","en":"Seafood should be eaten fresh."}]},"说不完":{"en":"cannot finish saying; endless (to talk about)","exs":[{"use":"有说不完的话: có nói mãi không hết","ex":"我们有说不完的话。","py":"Wǒmen yǒu shuō bu wán de huà.","vi":"Chúng tôi có nói mãi không hết chuyện.","en":"We have endless things to talk about."},{"use":"Bổ ngữ khả năng phủ định 说不完 (V + 不 + 完)","ex":"这个故事太长了，一天也说不完。","py":"Zhège gùshi tài cháng le, yì tiān yě shuō bu wán.","vi":"Câu chuyện này quá dài, một ngày cũng không kể hết.","en":"This story is so long that one day isn't enough to tell it."},{"use":"一…就有说不完的话: hễ gặp là…","ex":"他一见到朋友，就有说不完的话。","py":"Tā yí jiàndào péngyou, jiù yǒu shuō bu wán de huà.","vi":"Hễ gặp bạn là anh ấy nói mãi không hết chuyện.","en":"As soon as he sees his friends, he has endless things to say."},{"use":"Chỉ nội dung quá nhiều để kể","ex":"关于旅行的故事，他三天三夜也说不完。","py":"Guānyú lǚxíng de gùshi, tā sān tiān sān yè yě shuō bu wán.","vi":"Chuyện về những chuyến du lịch, anh ấy kể ba ngày ba đêm cũng không hết.","en":"He could talk about his travel stories for three days and nights and never finish."}]},"但是":{"en":"but; however","exs":[{"use":"Liên từ biểu thị sự chuyển ý hoặc đối lập.","ex":"他很累，但是还在学习。","py":"Tā hěn lèi, dànshì hái zài xuéxí.","vi":"Anh ấy rất mệt nhưng vẫn đang học.","en":"He is very tired, but he is still studying."},{"use":"Nối hai phân câu trái ngược","ex":"这个手机很好，但是太贵了。","py":"Zhège shǒujī hěn hǎo, dànshì tài guì le.","vi":"Chiếc điện thoại này rất tốt nhưng đắt quá.","en":"This phone is good, but it's too expensive."},{"use":"虽然…但是…","ex":"虽然我很想去，但是没有时间。","py":"Suīrán wǒ hěn xiǎng qù, dànshì méiyǒu shíjiān.","vi":"Tuy tôi rất muốn đi nhưng không có thời gian.","en":"Although I really want to go, I don't have time."},{"use":"Chuyển ý nhẹ, đứng đầu vế sau","ex":"他说得很快，但是我听懂了。","py":"Tā shuō de hěn kuài, dànshì wǒ tīngdǒng le.","vi":"Anh ấy nói rất nhanh nhưng tôi vẫn nghe hiểu.","en":"He spoke very fast, but I understood."}]},"现在":{"en":"now; at present; nowadays","exs":[{"use":"Dùng ở đầu câu hoặc trước động từ để chỉ thời điểm hiện tại.","ex":"现在我明白了。","py":"Xiànzài wǒ míngbai le.","vi":"Bây giờ tôi hiểu rồi.","en":"Now I understand."},{"use":"Hỏi giờ: 现在几点了？","ex":"现在几点了？","py":"Xiànzài jǐ diǎn le?","vi":"Bây giờ mấy giờ rồi?","en":"What time is it now?"},{"use":"Đặt sau chủ ngữ làm trạng ngữ","ex":"他现在在北京工作。","py":"Tā xiànzài zài Běijīng gōngzuò.","vi":"Hiện giờ anh ấy làm việc ở Bắc Kinh.","en":"He is working in Beijing now."},{"use":"现在的 + danh từ: …ngày nay","ex":"现在的年轻人喜欢网上购物。","py":"Xiànzài de niánqīngrén xǐhuan wǎngshàng gòuwù.","vi":"Giới trẻ ngày nay thích mua sắm trực tuyến.","en":"Young people nowadays like shopping online."},{"use":"现在就 + V: làm ngay bây giờ","ex":"我现在就去。","py":"Wǒ xiànzài jiù qù.","vi":"Tôi đi ngay bây giờ.","en":"I'm going right now."}]},"只有":{"en":"only; only if (with 才)","exs":[{"use":"只有…才…: chỉ có… mới… (điều kiện duy nhất)","ex":"只有多练习，才能说好汉语。","py":"Zhǐyǒu duō liànxí, cái néng shuō hǎo Hànyǔ.","vi":"Chỉ có luyện tập nhiều mới nói giỏi tiếng Hán.","en":"Only by practicing a lot can you speak Chinese well."},{"use":"只有 + số lượng: chỉ có bấy nhiêu","ex":"教室里只有三个人。","py":"Jiàoshì lǐ zhǐyǒu sān gè rén.","vi":"Trong lớp học chỉ có ba người.","en":"There are only three people in the classroom."},{"use":"我只有一个…: chỉ có một","ex":"我只有一个哥哥。","py":"Wǒ zhǐyǒu yí gè gēge.","vi":"Tôi chỉ có một người anh trai.","en":"I have only one older brother."},{"use":"只有 + người + V: chỉ có ai","ex":"只有你知道这件事。","py":"Zhǐyǒu nǐ zhīdào zhè jiàn shì.","vi":"Chỉ có bạn biết chuyện này.","en":"Only you know about this."}]},"新鲜感":{"en":"sense of novelty; freshness (feeling of newness)","exs":[{"use":"对…没有新鲜感: không còn thấy mới lạ","ex":"时间长了，对工作就没有新鲜感了。","py":"Shíjiān cháng le, duì gōngzuò jiù méiyǒu xīnxiāngǎn le.","vi":"Lâu ngày thì không còn thấy công việc mới mẻ nữa.","en":"After a while, the work no longer feels fresh."},{"use":"带来 + 新鲜感: mang lại cảm giác mới mẻ","ex":"旅行能带来新鲜感。","py":"Lǚxíng néng dàilái xīnxiāngǎn.","vi":"Du lịch có thể mang lại cảm giác mới mẻ.","en":"Traveling can bring a sense of novelty."},{"use":"失去 + 新鲜感: mất cảm giác mới lạ","ex":"孩子对新玩具很快就失去了新鲜感。","py":"Háizi duì xīn wánjù hěn kuài jiù shīqù le xīnxiāngǎn.","vi":"Trẻ con nhanh chóng hết thấy đồ chơi mới còn mới lạ.","en":"Children quickly lose their sense of novelty about new toys."},{"use":"Nói về quan hệ lâu dài mất đi cảm giác mới","ex":"他们在一起久了，慢慢没了新鲜感。","py":"Tāmen zài yìqǐ jiǔ le, mànmàn méi le xīnxiāngǎn.","vi":"Ở bên nhau lâu, dần dần họ không còn cảm giác mới mẻ.","en":"After being together for a long time, the novelty gradually faded."}]},"不够":{"en":"not enough; insufficient","exs":[{"use":"N + 不够: không đủ (tiền, thời gian…)","ex":"我带的钱不够。","py":"Wǒ dài de qián búgòu.","vi":"Số tiền tôi mang theo không đủ.","en":"The money I brought isn't enough."},{"use":"不够 + adj: chưa đủ (mức độ)","ex":"这个房间不够大。","py":"Zhège fángjiān búgòu dà.","vi":"Căn phòng này chưa đủ rộng.","en":"This room isn't big enough."},{"use":"不够用: không đủ dùng","ex":"今天的时间不够用。","py":"Jīntiān de shíjiān búgòu yòng.","vi":"Thời gian hôm nay không đủ dùng.","en":"There isn't enough time today."},{"use":"还不够: vẫn chưa đủ (nỗ lực…)","ex":"你的努力还不够。","py":"Nǐ de nǔlì hái búgòu.","vi":"Sự nỗ lực của bạn vẫn chưa đủ.","en":"Your effort is still not enough."},{"use":"不够 + người + V: không đủ cho ai làm gì","ex":"这些饭不够我们十个人吃。","py":"Zhèxiē fàn búgòu wǒmen shí gè rén chī.","vi":"Chỗ cơm này không đủ cho mười người chúng tôi ăn.","en":"This food isn't enough for the ten of us."}]},"看到":{"en":"to see; to catch sight of","exs":[{"use":"看到 + 了 + người/vật: nhìn thấy","ex":"我在街上看到了老同学。","py":"Wǒ zài jiē shàng kàndào le lǎo tóngxué.","vi":"Tôi nhìn thấy bạn học cũ trên phố.","en":"I saw an old classmate on the street."},{"use":"Dạng nghi vấn: 看到…了吗？","ex":"你看到我的眼镜了吗？","py":"Nǐ kàndào wǒ de yǎnjìng le ma?","vi":"Bạn có thấy kính của tôi không?","en":"Have you seen my glasses?"},{"use":"看到 + mệnh đề: thấy ai đang làm gì","ex":"我看到他在门口等你。","py":"Wǒ kàndào tā zài ménkǒu děng nǐ.","vi":"Tôi thấy anh ấy đang đợi bạn ở cửa.","en":"I saw him waiting for you at the door."},{"use":"看到…，想起…: thấy… thì nhớ lại…","ex":"看到这张照片，我想起了小时候。","py":"Kàndào zhè zhāng zhàopiàn, wǒ xiǎngqǐ le xiǎoshíhou.","vi":"Nhìn thấy bức ảnh này, tôi nhớ lại thời thơ ấu.","en":"Seeing this photo, I remembered my childhood."}]},"缺点":{"en":"shortcoming; weakness; drawback; flaw","exs":[{"use":"Trái nghĩa: 优点 (ưu điểm).","ex":"每个人都有缺点。","py":"Měi gè rén dōu yǒu quēdiǎn.","vi":"Ai cũng có khuyết điểm.","en":"Everyone has flaws."},{"use":"Làm chủ ngữ: …的缺点是…","ex":"他最大的缺点是太马虎。","py":"Tā zuì dà de quēdiǎn shì tài mǎhu.","vi":"Khuyết điểm lớn nhất của anh ấy là quá cẩu thả.","en":"His biggest flaw is being too careless."},{"use":"Nhược điểm của đồ vật","ex":"这个手机的缺点是电池不耐用。","py":"Zhège shǒujī de quēdiǎn shì diànchí bú nàiyòng.","vi":"Nhược điểm của chiếc điện thoại này là pin không bền.","en":"The drawback of this phone is that the battery doesn't last."},{"use":"接受缺点: chấp nhận khuyết điểm","ex":"我们要学会接受自己的缺点。","py":"Wǒmen yào xuéhuì jiēshòu zìjǐ de quēdiǎn.","vi":"Chúng ta phải học cách chấp nhận khuyết điểm của bản thân.","en":"We need to learn to accept our own flaws."},{"use":"优点和缺点: đi cặp với 优点","ex":"每个方法都有优点和缺点。","py":"Měi gè fāngfǎ dōu yǒu yōudiǎn hé quēdiǎn.","vi":"Phương pháp nào cũng có ưu điểm và khuyết điểm.","en":"Every method has its advantages and disadvantages."}]},"问题":{"en":"question; problem; issue","exs":[{"use":"Câu hỏi: 问一个问题","ex":"老师，我可以问一个问题吗？","py":"Lǎoshī, wǒ kěyǐ wèn yí gè wèntí ma?","vi":"Thưa thầy, em có thể hỏi một câu được không ạ?","en":"Teacher, may I ask a question?"},{"use":"Trục trặc: 出问题","ex":"电脑出问题了。","py":"Diànnǎo chū wèntí le.","vi":"Máy tính bị trục trặc rồi.","en":"There's something wrong with the computer."},{"use":"没问题: không vấn đề gì","ex":"这件事交给我，没问题。","py":"Zhè jiàn shì jiāogěi wǒ, méi wèntí.","vi":"Việc này giao cho tôi, không vấn đề gì.","en":"Leave this to me, no problem."},{"use":"Đề/câu hỏi cần trả lời","ex":"最后一个问题我不会回答。","py":"Zuìhòu yí gè wèntí wǒ bú huì huídá.","vi":"Câu hỏi cuối cùng tôi không biết trả lời.","en":"I can't answer the last question."},{"use":"Vấn đề xã hội: 环境问题","ex":"环境问题越来越重要。","py":"Huánjìng wèntí yuè lái yuè zhòngyào.","vi":"Vấn đề môi trường ngày càng quan trọng.","en":"Environmental issues are becoming more and more important."}]},"接受":{"en":"to accept; to receive","exs":[{"use":"接受 + ý kiến/đề nghị","ex":"我接受你的建议。","py":"Wǒ jiēshòu nǐ de jiànyì.","vi":"Tôi chấp nhận đề nghị của bạn.","en":"I accept your suggestion."},{"use":"接受 + lời mời","ex":"他接受了我们的邀请。","py":"Tā jiēshòu le wǒmen de yāoqǐng.","vi":"Anh ấy đã nhận lời mời của chúng tôi.","en":"He accepted our invitation."},{"use":"接受 + 教育/采访: tiếp nhận (giáo dục…)","ex":"她在北京接受了很好的教育。","py":"Tā zài Běijīng jiēshòu le hěn hǎo de jiàoyù.","vi":"Cô ấy được tiếp nhận nền giáo dục rất tốt ở Bắc Kinh.","en":"She received a very good education in Beijing."},{"use":"让…很难接受: khó chấp nhận","ex":"这个结果让我很难接受。","py":"Zhège jiéguǒ ràng wǒ hěn nán jiēshòu.","vi":"Kết quả này khiến tôi rất khó chấp nhận.","en":"This result is hard for me to accept."}]},"丰富":{"en":"rich; abundant; plentiful; to enrich","exs":[{"use":"Làm tính từ: 经验丰富; làm động từ: 丰富 + sự vật.","ex":"读书可以丰富我们的知识。","py":"Dúshū kěyǐ fēngfù wǒmen de zhīshi.","vi":"Đọc sách có thể làm phong phú kiến thức của chúng ta.","en":"Reading can enrich our knowledge."},{"use":"丰富 + kinh nghiệm / kiến thức.","ex":"他的经验很丰富。","py":"Tā de jīngyàn hěn fēngfù.","vi":"Kinh nghiệm của anh ấy rất phong phú.","en":"He has rich experience."},{"use":"丰富 + kiến thức/cuộc sống.","ex":"旅行能丰富生活。","py":"Lǚxíng néng fēngfù shēnghuó.","vi":"Du lịch có thể làm phong phú cuộc sống.","en":"Traveling can enrich life."},{"use":"Động từ: 丰富 + 经历 (làm giàu trải nghiệm)","ex":"旅行能丰富我们的经历。","py":"Lǚxíng néng fēngfù wǒmen de jīnglì.","vi":"Du lịch làm phong phú trải nghiệm của chúng ta.","en":"Travel can enrich our experiences."},{"use":"Tính từ: 物产丰富 (sản vật dồi dào)","ex":"这里的物产非常丰富。","py":"Zhèlǐ de wùchǎn fēicháng fēngfù.","vi":"Sản vật ở đây vô cùng phong phú.","en":"This place is extremely rich in natural products."},{"use":"Tính từ: 生活丰富 (cuộc sống đa dạng)","ex":"他的业余生活很丰富。","py":"Tā de yèyú shēnghuó hěn fēngfù.","vi":"Cuộc sống ngoài giờ của anh ấy rất phong phú.","en":"His life outside work is very rich and varied."}]},"离开":{"en":"to leave; to depart from; to be away from","exs":[{"use":"离开 + nơi chốn / người.","ex":"他昨天已经离开北京了。","py":"Tā zuótiān yǐjīng líkāi Běijīng le.","vi":"Hôm qua anh ấy đã rời Bắc Kinh rồi.","en":"He already left Beijing yesterday."},{"use":"离开 + công ty/nơi làm việc","ex":"我打算明年离开这家公司。","py":"Wǒ dǎsuàn míngnián líkāi zhè jiā gōngsī.","vi":"Tôi định sang năm rời công ty này.","en":"I plan to leave this company next year."},{"use":"离开 + người thân","ex":"孩子不想离开妈妈。","py":"Háizi bù xiǎng líkāi māma.","vi":"Đứa bé không muốn rời xa mẹ.","en":"The child doesn't want to leave his mother."},{"use":"Phương tiện rời đi: 就要离开了","ex":"火车五分钟后就要离开了。","py":"Huǒchē wǔ fēnzhōng hòu jiù yào líkāi le.","vi":"Năm phút nữa tàu sẽ rời bến.","en":"The train will leave in five minutes."},{"use":"不能离开 + N: không thể thiếu","ex":"人不能离开空气和水。","py":"Rén bù néng líkāi kōngqì hé shuǐ.","vi":"Con người không thể thiếu không khí và nước.","en":"People cannot live without air and water."}]},"无聊":{"en":"boring; bored; dull","exs":[{"use":"Miêu tả cảm giác hoặc sự việc nhàm chán.","ex":"一个人在家很无聊。","py":"Yí gè rén zài jiā hěn wúliáo.","vi":"Ở nhà một mình rất chán.","en":"It is boring to be home alone."},{"use":"Miêu tả sự việc: 太…了","ex":"这部电影太无聊了。","py":"Zhè bù diànyǐng tài wúliáo le.","vi":"Bộ phim này chán quá.","en":"This movie is too boring."},{"use":"觉得 + 无聊: cảm thấy chán","ex":"周末没事做，我觉得很无聊。","py":"Zhōumò méi shì zuò, wǒ juéde hěn wúliáo.","vi":"Cuối tuần không có gì làm, tôi thấy rất chán.","en":"I have nothing to do on the weekend, and I feel very bored."},{"use":"无聊的 + danh từ: nhảm nhí, vô vị","ex":"别说这些无聊的话了。","py":"Bié shuō zhèxiē wúliáo de huà le.","vi":"Đừng nói những lời vô vị này nữa.","en":"Stop saying such pointless things."},{"use":"又…又…无聊: vừa dài vừa chán","ex":"这个会议开得又长又无聊。","py":"Zhège huìyì kāi de yòu cháng yòu wúliáo.","vi":"Cuộc họp này vừa dài vừa chán.","en":"This meeting was both long and boring."}]},"讨厌":{"en":"to dislike; to hate; annoying","exs":[{"use":"讨厌 + người / việc.","ex":"我讨厌等人。","py":"Wǒ tǎoyàn děng rén.","vi":"Tôi ghét phải chờ người khác.","en":"I hate waiting for people."},{"use":"Động từ: 讨厌 + thời tiết/sự vật","ex":"我很讨厌下雨天。","py":"Wǒ hěn tǎoyàn xià yǔ tiān.","vi":"Tôi rất ghét ngày mưa.","en":"I really dislike rainy days."},{"use":"Tính từ: 真讨厌！ (đáng ghét)","ex":"这只蚊子真讨厌！","py":"Zhè zhī wénzi zhēn tǎoyàn!","vi":"Con muỗi này đáng ghét thật!","en":"This mosquito is so annoying!"},{"use":"讨厌 + 的 + người: kiểu người bị ghét","ex":"他讨厌说谎的人。","py":"Tā tǎoyàn shuōhuǎng de rén.","vi":"Anh ấy ghét người nói dối.","en":"He dislikes people who lie."},{"use":"让人讨厌: khiến người ta khó chịu","ex":"他总是迟到，真让人讨厌。","py":"Tā zǒngshì chídào, zhēn ràng rén tǎoyàn.","vi":"Anh ta lúc nào cũng đến muộn, thật đáng ghét.","en":"He is always late, which is really annoying."}]},"生气":{"en":"to get angry; angry","exs":[{"use":"Động từ ly hợp: 生气 / 生我的气.","ex":"别生气，慢慢说。","py":"Bié shēngqì, mànmàn shuō.","vi":"Đừng giận, cứ nói từ từ.","en":"Don't be angry; speak slowly."},{"use":"为…生气: tức giận vì…","ex":"他为一点小事就生气。","py":"Tā wèi yìdiǎn xiǎoshì jiù shēngqì.","vi":"Anh ấy vì chút chuyện nhỏ mà đã nổi giận.","en":"He gets angry over the smallest things."},{"use":"很 + 生气: rất tức giận (vị ngữ)","ex":"妈妈看到成绩单很生气。","py":"Māma kàndào chéngjìdān hěn shēngqì.","vi":"Mẹ nhìn thấy bảng điểm thì rất tức giận.","en":"Mom was very angry when she saw the report card."},{"use":"生气 + 地 + V: giận dữ làm gì","ex":"他生气地走了。","py":"Tā shēngqì de zǒu le.","vi":"Anh ấy giận dữ bỏ đi.","en":"He left angrily."},{"use":"V + 错话 → 生气了: kết quả","ex":"我说错话了，他生气了。","py":"Wǒ shuō cuò huà le, tā shēngqì le.","vi":"Tôi lỡ lời nên anh ấy giận rồi.","en":"I said the wrong thing and he got angry."}]},"周围":{"en":"surroundings; around; vicinity","exs":[{"use":"周围 + 的 + danh từ / nơi chốn + 周围.","ex":"学校周围有很多商店。","py":"Xuéxiào zhōuwéi yǒu hěn duō shāngdiàn.","vi":"Xung quanh trường có rất nhiều cửa hàng.","en":"There are many shops around the school."},{"use":"周围的 + 人: những người xung quanh","ex":"周围的人都很友好。","py":"Zhōuwéi de rén dōu hěn yǒuhǎo.","vi":"Những người xung quanh đều rất thân thiện.","en":"The people around here are all friendly."},{"use":"Làm tân ngữ: 看看周围","ex":"他看了看周围，没有一个人。","py":"Tā kàn le kàn zhōuwéi, méiyǒu yí gè rén.","vi":"Anh ấy nhìn quanh, không có một ai.","en":"He looked around and there was no one."},{"use":"Nơi chốn + 周围 + V","ex":"房子周围种着很多花。","py":"Fángzi zhōuwéi zhòng zhe hěn duō huā.","vi":"Xung quanh ngôi nhà trồng rất nhiều hoa.","en":"Many flowers are planted around the house."}]},"交流":{"en":"to exchange; to communicate; interaction","exs":[{"use":"交流 + ý kiến / kinh nghiệm; 和…交流.","ex":"我们经常交流学习方法。","py":"Wǒmen jīngcháng jiāoliú xuéxí fāngfǎ.","vi":"Chúng tôi thường trao đổi phương pháp học.","en":"We often exchange study methods."},{"use":"Động từ: 和 + người + 交流, trao đổi trực tiếp với ai.","ex":"我想和外国朋友交流一下。","py":"Wǒ xiǎng hé wàiguó péngyou jiāoliú yíxià.","vi":"Tôi muốn trao đổi một chút với bạn người nước ngoài.","en":"I'd like to chat with my foreign friends for a bit."},{"use":"Làm danh từ: 文化交流 (giao lưu văn hóa).","ex":"文化交流让两国人民互相了解。","py":"Wénhuà jiāoliú ràng liǎng guó rénmín hùxiāng liǎojiě.","vi":"Giao lưu văn hóa giúp nhân dân hai nước hiểu nhau hơn.","en":"Cultural exchange helps the people of the two countries understand each other."},{"use":"Chỉ việc giao tiếp, trao đổi bằng ngôn ngữ; 交流 + 有点儿困难.","ex":"他汉语说得不好，交流有点儿困难。","py":"Tā Hànyǔ shuō de bù hǎo, jiāoliú yǒudiǎnr kùnnan.","vi":"Anh ấy nói tiếng Trung chưa tốt nên giao tiếp hơi khó khăn.","en":"His Chinese isn't good, so communicating is a bit difficult."}]},"了解":{"en":"to understand; to know well; to find out","exs":[{"use":"了解 + người / tình hình.","ex":"我想多了解你的想法。","py":"Wǒ xiǎng duō liǎojiě nǐ de xiǎngfǎ.","vi":"Tôi muốn hiểu thêm suy nghĩ của bạn.","en":"I'd like to understand your thinking better."},{"use":"Nghĩa tìm hiểu: 了解一下 + sự việc.","ex":"去中国以前，我先了解了一下那里的天气。","py":"Qù Zhōngguó yǐqián, wǒ xiān liǎojiě le yíxià nàlǐ de tiānqì.","vi":"Trước khi đến Trung Quốc, tôi tìm hiểu trước thời tiết ở đó.","en":"Before going to China, I first looked into the weather there."},{"use":"Câu hỏi: 了解 + nơi chốn / tổ chức, nghĩa là biết rõ.","ex":"你了解这家公司吗？","py":"Nǐ liǎojiě zhè jiā gōngsī ma?","vi":"Bạn có hiểu rõ công ty này không?","en":"Do you know this company well?"},{"use":"Làm danh từ: 对…的了解 (sự hiểu biết về …).","ex":"我对他的了解不多。","py":"Wǒ duì tā de liǎojiě bù duō.","vi":"Tôi không hiểu biết nhiều về anh ấy.","en":"I don't know much about him."}]},"习惯":{"en":"habit; to be used to; to get accustomed to","exs":[{"use":"Danh từ: 习惯 + động từ / danh từ.","ex":"早起已经成了他的习惯。","py":"Zǎoqǐ yǐjīng chéng le tā de xíguàn.","vi":"Dậy sớm đã trở thành thói quen của anh ấy.","en":"Getting up early has become his habit."},{"use":"Động từ: 习惯 + sự việc (quen với); 不习惯 là chưa quen.","ex":"我还不习惯这里的生活。","py":"Wǒ hái bù xíguàn zhèlǐ de shēnghuó.","vi":"Tôi vẫn chưa quen với cuộc sống ở đây.","en":"I'm not yet used to life here."},{"use":"Danh từ: 有…的习惯 (có thói quen …).","ex":"他有早上喝咖啡的习惯。","py":"Tā yǒu zǎoshang hē kāfēi de xíguàn.","vi":"Anh ấy có thói quen uống cà phê vào buổi sáng.","en":"He has a habit of drinking coffee in the morning."},{"use":"Động từ + 了: đã quen, đã thích nghi.","ex":"孩子们慢慢习惯了新学校。","py":"Háizimen mànmàn xíguàn le xīn xuéxiào.","vi":"Bọn trẻ dần dần đã quen với trường mới.","en":"The children gradually got used to the new school."}]},"必须":{"en":"must; have to; must (be)","exs":[{"use":"Đặt trước động từ; phủ định dùng 不必 / 不用.","ex":"你必须按时完成作业。","py":"Nǐ bìxū ànshí wánchéng zuòyè.","vi":"Bạn nhất định phải làm xong bài tập đúng hạn.","en":"You must finish your homework on time."},{"use":"必须 + 先 + động từ: bắt buộc phải làm trước một bước.","ex":"到医院后你必须先挂号。","py":"Dào yīyuàn hòu nǐ bìxū xiān guàhào.","vi":"Đến bệnh viện bạn phải đăng ký khám trước.","en":"After arriving at the hospital, you have to register first."},{"use":"Nhấn mạnh việc cấp bách: 必须 + 马上 + động từ.","ex":"这件事必须马上告诉经理。","py":"Zhè jiàn shì bìxū mǎshàng gàosu jīnglǐ.","vi":"Việc này phải báo ngay cho giám đốc.","en":"This must be reported to the manager right away."},{"use":"Quy định, luật lệ: ngữ cảnh bắt buộc.","ex":"开车必须系安全带。","py":"Kāichē bìxū jì ānquándài.","vi":"Lái xe bắt buộc phải thắt dây an toàn.","en":"You must wear a seat belt when driving."}]},"真正":{"en":"real; true; genuine; truly; really","exs":[{"use":"真正 + 的 + danh từ.","ex":"他是我真正的朋友。","py":"Tā shì wǒ zhēnzhèng de péngyou.","vi":"Anh ấy là người bạn thực sự của tôi.","en":"He is my real friend."},{"use":"Thường đứng trước danh từ để nhấn mạnh tính xác thực.","ex":"真正的朋友会帮助你。","py":"Zhēnzhèng de péngyou huì bāngzhù nǐ.","vi":"Người bạn thật sự sẽ giúp đỡ bạn.","en":"A true friend will help you."},{"use":"Phó từ: 真正 + động từ, nghĩa là thật sự (làm gì).","ex":"他真正喜欢的是音乐。","py":"Tā zhēnzhèng xǐhuan de shì yīnyuè.","vi":"Điều anh ấy thật sự thích là âm nhạc.","en":"What he truly likes is music."},{"use":"Cấu trúc 才真正 + động từ: đến lúc đó mới thật sự.","ex":"这次旅行我才真正了解了这座城市。","py":"Zhè cì lǚxíng wǒ cái zhēnzhèng liǎojiě le zhè zuò chéngshì.","vi":"Qua chuyến đi này tôi mới thật sự hiểu thành phố này.","en":"It was only on this trip that I truly got to know this city."},{"use":"Trong câu hỏi: 真正 + động từ + 的 + danh từ.","ex":"你真正想做的工作是什么？","py":"Nǐ zhēnzhèng xiǎng zuò de gōngzuò shì shénme?","vi":"Công việc bạn thật sự muốn làm là gì?","en":"What job do you really want to do?"}]},"理解":{"en":"to understand; to comprehend; understanding","exs":[{"use":"Nhấn vào sự thấu hiểu, đồng cảm.","ex":"我理解你的心情。","py":"Wǒ lǐjiě nǐ de xīnqíng.","vi":"Tôi hiểu tâm trạng của bạn.","en":"I understand how you feel."},{"use":"Động từ: hiểu nghĩa, nội dung; 很难理解 là rất khó hiểu.","ex":"这个句子的意思很难理解。","py":"Zhège jùzi de yìsi hěn nán lǐjiě.","vi":"Ý nghĩa của câu này rất khó hiểu.","en":"The meaning of this sentence is hard to understand."},{"use":"Làm danh từ: 你的理解 (sự thông cảm, sự hiểu).","ex":"谢谢你的理解和支持。","py":"Xièxie nǐ de lǐjiě hé zhīchí.","vi":"Cảm ơn sự thông cảm và ủng hộ của bạn.","en":"Thank you for your understanding and support."},{"use":"不理解 + mệnh đề: không hiểu, không thông cảm được.","ex":"父母不理解我为什么要去国外工作。","py":"Fùmǔ bù lǐjiě wǒ wèishénme yào qù guówài gōngzuò.","vi":"Bố mẹ không hiểu vì sao tôi muốn ra nước ngoài làm việc.","en":"My parents don't understand why I want to work abroad."}]},"镜子":{"en":"mirror","exs":[{"use":"Thường dùng: 照镜子.","ex":"她每天照镜子。","py":"Tā měi tiān zhào jìngzi.","vi":"Ngày nào cô ấy cũng soi gương.","en":"She looks in the mirror every day."},{"use":"Lượng từ của gương là 面: 一面镜子.","ex":"墙上挂着一面大镜子。","py":"Qiáng shàng guà zhe yí miàn dà jìngzi.","vi":"Trên tường treo một chiếc gương lớn.","en":"A big mirror hangs on the wall."},{"use":"在镜子前: trước gương.","ex":"出门前我在镜子前整理了一下头发。","py":"Chūmén qián wǒ zài jìngzi qián zhěnglǐ le yíxià tóufa.","vi":"Trước khi ra khỏi nhà tôi chỉnh lại tóc trước gương.","en":"Before leaving home I fixed my hair in front of the mirror."},{"use":"Câu bị động 被: 镜子被打破了.","ex":"这面镜子被打破了。","py":"Zhè miàn jìngzi bèi dǎpò le.","vi":"Chiếc gương này bị vỡ rồi.","en":"This mirror got broken."}]},"困难":{"en":"difficulty; hardship; difficult; hard up","exs":[{"use":"遇到困难 = gặp khó khăn.","ex":"遇到困难时要想办法。","py":"Yùdào kùnnan shí yào xiǎng bànfǎ.","vi":"Khi gặp khó khăn phải tìm cách.","en":"When you run into difficulties, find a way."},{"use":"遇到困难 = gặp khó khăn.","ex":"工作中有很多困难。","py":"Gōngzuò zhōng yǒu hěn duō kùnnan.","vi":"Trong công việc có rất nhiều khó khăn.","en":"There are a lot of difficulties at work."},{"use":"Tính từ: 生活困难 = đời sống khó khăn, thiếu thốn.","ex":"他家的生活很困难，但他学习很努力。","py":"Tā jiā de shēnghuó hěn kùnnan, dàn tā xuéxí hěn nǔlì.","vi":"Cuộc sống nhà anh ấy rất khó khăn nhưng anh ấy học rất chăm chỉ.","en":"His family is hard up, but he studies very hard."},{"use":"有困难: gặp khó khăn, cần giúp đỡ.","ex":"如果有困难，随时给我打电话。","py":"Rúguǒ yǒu kùnnan, suíshí gěi wǒ dǎ diànhuà.","vi":"Nếu có khó khăn, cứ gọi điện cho tôi bất cứ lúc nào.","en":"If you have any trouble, call me anytime."}]},"及时":{"en":"timely; in time; promptly","exs":[{"use":"及时 + động từ.","ex":"谢谢你及时帮助我。","py":"Xièxie nǐ jíshí bāngzhù wǒ.","vi":"Cảm ơn bạn đã giúp tôi kịp thời.","en":"Thank you for helping me in time."},{"use":"Tính từ làm vị ngữ: 很及时 = rất đúng lúc.","ex":"这场雨下得很及时。","py":"Zhè chǎng yǔ xià de hěn jíshí.","vi":"Trận mưa này đến thật đúng lúc.","en":"This rain came at just the right time."},{"use":"要及时 + động từ: cần làm ngay, không chậm trễ.","ex":"生病了要及时去医院。","py":"Shēngbìng le yào jíshí qù yīyuàn.","vi":"Bị bệnh thì phải đến bệnh viện kịp thời.","en":"When you're sick you should go to the hospital promptly."},{"use":"Phó từ chỉ kịp lúc: 及时 + 赶到 / 到达.","ex":"他及时赶到了机场。","py":"Tā jíshí gǎndào le jīchǎng.","vi":"Anh ấy đã kịp chạy đến sân bay.","en":"He got to the airport in time."}]},"帮助":{"en":"to help; help; assistance","exs":[{"use":"帮助 + người; 给…帮助.","ex":"他常常帮助同学。","py":"Tā chángcháng bāngzhù tóngxué.","vi":"Anh ấy thường giúp đỡ bạn học.","en":"He often helps his classmates."},{"use":"Danh từ: 给 + người + 帮助 / 很大的帮助.","ex":"老师给了我很大的帮助。","py":"Lǎoshī gěi le wǒ hěn dà de bāngzhù.","vi":"Thầy giáo đã giúp đỡ tôi rất nhiều.","en":"The teacher gave me a lot of help."},{"use":"对…有帮助: có ích cho …","ex":"多听多说对学汉语很有帮助。","py":"Duō tīng duō shuō duì xué Hànyǔ hěn yǒu bāngzhù.","vi":"Nghe nhiều nói nhiều rất có ích cho việc học tiếng Trung.","en":"Listening and speaking a lot is very helpful for learning Chinese."},{"use":"Động từ trong câu điều kiện: 需要帮助的话.","ex":"需要帮助的话，请告诉我。","py":"Xūyào bāngzhù de huà, qǐng gàosu wǒ.","vi":"Nếu cần giúp đỡ thì hãy nói với tôi.","en":"If you need help, please tell me."}]},"陪":{"en":"to accompany; to keep company","exs":[{"use":"陪 + người + động từ.","ex":"周末我陪妈妈去买东西。","py":"Zhōumò wǒ péi māma qù mǎi dōngxi.","vi":"Cuối tuần tôi đi mua đồ cùng mẹ.","en":"On the weekend I go shopping with my mom."},{"use":"Câu hỏi: 谁陪你…?","ex":"谁陪你去医院？","py":"Shéi péi nǐ qù yīyuàn?","vi":"Ai đi bệnh viện cùng bạn?","en":"Who is going to the hospital with you?"},{"use":"陪 + người + làm việc gì đó (ở bên cạnh).","ex":"他每天晚上陪孩子写作业。","py":"Tā měi tiān wǎnshang péi háizi xiě zuòyè.","vi":"Mỗi tối anh ấy ngồi cùng con làm bài tập.","en":"Every evening he sits with his child while the child does homework."},{"use":"陪我聊天: ở bên trò chuyện cùng tôi.","ex":"谢谢你陪我聊天。","py":"Xièxie nǐ péi wǒ liáotiān.","vi":"Cảm ơn bạn đã ở bên trò chuyện với tôi.","en":"Thanks for keeping me company and chatting."}]},"每个人":{"en":"everyone; each person","exs":[{"use":"Dùng để nói về từng người trong một nhóm.","ex":"每个人都需要休息。","py":"Měi ge rén dōu xūyào xiūxi.","vi":"Mỗi người đều cần nghỉ ngơi.","en":"Everyone needs rest."},{"use":"每个人 + 都 + động từ: ai cũng …","ex":"我们班每个人都会说一点儿汉语。","py":"Wǒmen bān měi ge rén dōu huì shuō yìdiǎnr Hànyǔ.","vi":"Mỗi người trong lớp chúng tôi đều biết nói một chút tiếng Trung.","en":"Everyone in our class can speak a little Chinese."},{"use":"每个人的 + danh từ: của mỗi người.","ex":"每个人的爱好都不一样。","py":"Měi ge rén de àihào dōu bù yíyàng.","vi":"Sở thích của mỗi người đều khác nhau.","en":"Everyone's hobbies are different."},{"use":"Làm tân ngữ sau 给: 给每个人 …","ex":"公司给每个人发了一份礼物。","py":"Gōngsī gěi měi ge rén fā le yí fèn lǐwù.","vi":"Công ty phát cho mỗi người một phần quà.","en":"The company gave everyone a gift."}]},"朋友":{"en":"friend","exs":[{"use":"Làm danh từ: 最好的朋友 = bạn thân nhất.","ex":"他是我最好的朋友。","py":"Tā shì wǒ zuì hǎo de péngyou.","vi":"Anh ấy là người bạn thân nhất của tôi.","en":"He is my best friend."},{"use":"有 + 很多 + 朋友; 外国朋友 = bạn nước ngoài.","ex":"我有很多外国朋友。","py":"Wǒ yǒu hěn duō wàiguó péngyou.","vi":"Tôi có rất nhiều bạn người nước ngoài.","en":"I have a lot of foreign friends."},{"use":"朋友们: số nhiều, dùng làm chủ ngữ.","ex":"朋友们周末一起去爬山。","py":"Péngyoumen zhōumò yìqǐ qù páshān.","vi":"Cuối tuần các bạn cùng nhau đi leo núi.","en":"On the weekend, my friends go hiking together."},{"use":"在…的帮助下: nhờ sự giúp đỡ của …","ex":"在朋友的帮助下，我找到了工作。","py":"Zài péngyou de bāngzhù xià, wǒ zhǎodào le gōngzuò.","vi":"Nhờ bạn bè giúp đỡ, tôi đã tìm được việc làm.","en":"With my friend's help, I found a job."}]},"可以":{"en":"can; may; be allowed to; passable","exs":[{"use":"Xin phép / hỏi có được phép không: 可以…吗?","ex":"这里可以拍照吗？","py":"Zhèlǐ kěyǐ pāizhào ma?","vi":"Ở đây có được chụp ảnh không?","en":"May I take photos here?"},{"use":"可以 + động từ: cho phép, đồng ý.","ex":"你可以用我的手机。","py":"Nǐ kěyǐ yòng wǒ de shǒujī.","vi":"Bạn có thể dùng điện thoại của tôi.","en":"You can use my phone."},{"use":"Chỉ khả năng, điều kiện cho phép.","ex":"明天我可以早点儿来。","py":"Míngtiān wǒ kěyǐ zǎodiǎnr lái.","vi":"Ngày mai tôi có thể đến sớm một chút.","en":"I can come a bit earlier tomorrow."},{"use":"Phủ định: 不可以 = không được phép.","ex":"这里不可以抽烟。","py":"Zhèlǐ bù kěyǐ chōuyān.","vi":"Ở đây không được hút thuốc.","en":"Smoking is not allowed here."},{"use":"Dùng như tính từ làm vị ngữ: được, tạm được.","ex":"这个办法可以。","py":"Zhège bànfǎ kěyǐ.","vi":"Cách này được đấy.","en":"This method will do."}]},"一定":{"en":"definitely; certainly; must; certain (degree)","exs":[{"use":"Đặt trước động từ để nhấn mạnh yêu cầu hoặc sự chắc chắn.","ex":"你一定要注意安全。","py":"Nǐ yídìng yào zhùyì ānquán.","vi":"Bạn nhất định phải chú ý an toàn.","en":"You must be careful and stay safe."},{"use":"一定 + 会…: chắc chắn sẽ …","ex":"明天他一定会来的。","py":"Míngtiān tā yídìng huì lái de.","vi":"Ngày mai anh ấy chắc chắn sẽ đến.","en":"He will definitely come tomorrow."},{"use":"不一定: chưa chắc, không nhất thiết.","ex":"你不一定要买贵的。","py":"Nǐ bù yídìng yào mǎi guì de.","vi":"Bạn không nhất thiết phải mua đồ đắt.","en":"You don't necessarily have to buy an expensive one."},{"use":"一定的 + danh từ: nhất định, ở một mức độ nào đó.","ex":"学汉语需要一定的时间。","py":"Xué Hànyǔ xūyào yídìng de shíjiān.","vi":"Học tiếng Trung cần một khoảng thời gian nhất định.","en":"Learning Chinese takes a certain amount of time."}]},"非常":{"en":"very; extremely; extraordinarily","exs":[{"use":"非常 + tính từ.","ex":"今天的天气非常好。","py":"Jīntiān de tiānqì fēicháng hǎo.","vi":"Thời tiết hôm nay vô cùng tốt.","en":"The weather is extremely nice today."},{"use":"非常 + động từ tâm lý (喜欢, 感谢…).","ex":"我非常喜欢这个城市。","py":"Wǒ fēicháng xǐhuan zhège chéngshì.","vi":"Tôi vô cùng thích thành phố này.","en":"I like this city very much."},{"use":"V + 得 + 非常 + adj.","ex":"他跑得非常快。","py":"Tā pǎo de fēicháng kuài.","vi":"Anh ấy chạy rất nhanh.","en":"He runs extremely fast."},{"use":"非常 + tính từ khen món ăn, sự vật.","ex":"这道菜非常好吃，我还想再吃一点儿。","py":"Zhè dào cài fēicháng hǎochī, wǒ hái xiǎng zài chī yìdiǎnr.","vi":"Món này rất ngon, tôi còn muốn ăn thêm chút nữa.","en":"This dish is delicious; I'd like to eat a little more."}]},"那么":{"en":"then; in that case; so; such; that (degree)","exs":[{"use":"Dùng để nối câu, chuyển sang kết quả hoặc câu hỏi tiếp theo.","ex":"那么，我们开始吧。","py":"Nàme, wǒmen kāishǐ ba.","vi":"Vậy thì, chúng ta bắt đầu nhé.","en":"Well then, let's begin."},{"use":"那么 + tính từ: chỉ mức độ (như vậy, đến thế).","ex":"他说得那么快，我没听清楚。","py":"Tā shuō de nàme kuài, wǒ méi tīng qīngchu.","vi":"Anh ấy nói nhanh quá, tôi nghe không rõ.","en":"He spoke so fast that I couldn't hear clearly."},{"use":"Trong so sánh: 没有…那么 + adj.","ex":"这个房间没有那个那么大。","py":"Zhège fángjiān méiyǒu nàge nàme dà.","vi":"Phòng này không lớn bằng phòng kia.","en":"This room isn't as big as that one."},{"use":"别那么 + adj/động từ: đừng … đến thế.","ex":"你别那么着急。","py":"Nǐ bié nàme zháojí.","vi":"Bạn đừng vội vàng như thế.","en":"Don't be so anxious."},{"use":"如果…，那么…: nếu … thì …","ex":"如果你不想去，那么我们在家看电影吧。","py":"Rúguǒ nǐ bù xiǎng qù, nàme wǒmen zài jiā kàn diànyǐng ba.","vi":"Nếu bạn không muốn đi thì chúng ta ở nhà xem phim nhé.","en":"If you don't want to go, then let's watch a movie at home."}]},"怎样":{"en":"how; what (kind of); in what way","exs":[{"use":"Hỏi ý kiến, đánh giá: 怎样?","ex":"你觉得这个办法怎样？","py":"Nǐ juéde zhège bànfǎ zěnyàng?","vi":"Bạn thấy cách này thế nào?","en":"What do you think of this method?"},{"use":"怎样 + động từ: hỏi cách thức.","ex":"请告诉我怎样去火车站。","py":"Qǐng gàosu wǒ zěnyàng qù huǒchēzhàn.","vi":"Xin hãy cho tôi biết đi đến ga tàu như thế nào.","en":"Please tell me how to get to the train station."},{"use":"想怎样 + động từ: muốn làm theo cách nào.","ex":"你想怎样过周末？","py":"Nǐ xiǎng zěnyàng guò zhōumò?","vi":"Bạn muốn trải qua cuối tuần như thế nào?","en":"How would you like to spend the weekend?"},{"use":"不管…怎样: dù … thế nào đi nữa.","ex":"不管天气怎样，我们都去跑步。","py":"Bùguǎn tiānqì zěnyàng, wǒmen dōu qù pǎobù.","vi":"Dù thời tiết ra sao, chúng tôi vẫn đi chạy bộ.","en":"No matter what the weather is like, we go running."}]},"当然":{"en":"of course; certainly; naturally","exs":[{"use":"Trả lời khẳng định: 当然可以.","ex":"你能来帮我吗？当然可以。","py":"Nǐ néng lái bāng wǒ ma? Dāngrán kěyǐ.","vi":"Bạn có thể đến giúp tôi không? Đương nhiên là được.","en":"Can you come help me? Of course."},{"use":"当然 + động từ/tính từ: hiển nhiên là, lẽ dĩ nhiên.","ex":"他是老师，当然懂这个问题。","py":"Tā shì lǎoshī, dāngrán dǒng zhège wèntí.","vi":"Anh ấy là giáo viên nên đương nhiên hiểu vấn đề này.","en":"He's a teacher, so of course he understands this problem."},{"use":"Nhấn mạnh ý muốn: 我当然想….","ex":"我当然想去中国旅游。","py":"Wǒ dāngrán xiǎng qù Zhōngguó lǚyóu.","vi":"Tôi đương nhiên muốn đi du lịch Trung Quốc.","en":"Of course I want to travel to China."},{"use":"当然的 + danh từ / 是当然的: lẽ đương nhiên.","ex":"这是当然的事，不用谢。","py":"Zhè shì dāngrán de shì, búyòng xiè.","vi":"Đây là chuyện đương nhiên, không cần cảm ơn.","en":"That's only natural, no need to thank me."}]},"因为":{"en":"because; since; because of","exs":[{"use":"因为 + nguyên nhân，(所以) + kết quả.","ex":"因为下雨，我们没去公园。","py":"Yīnwèi xià yǔ, wǒmen méi qù gōngyuán.","vi":"Vì trời mưa nên chúng tôi không đi công viên.","en":"Because it rained, we didn't go to the park."},{"use":"Đặt ở vế sau để giải thích: 结果，因为 + lý do.","ex":"他迟到了，因为路上堵车。","py":"Tā chídào le, yīnwèi lùshang dǔchē.","vi":"Anh ấy đến muộn vì đường bị kẹt xe.","en":"He was late because of a traffic jam."},{"use":"因为…，所以…: cặp quan hệ nhân quả.","ex":"因为工作很忙，所以我很少回家。","py":"Yīnwèi gōngzuò hěn máng, suǒyǐ wǒ hěn shǎo huí jiā.","vi":"Vì công việc bận nên tôi rất ít khi về nhà.","en":"Because work is busy, I rarely go home."},{"use":"是因为…: chính là vì …","ex":"我喜欢这里，是因为人们很热情。","py":"Wǒ xǐhuan zhèlǐ, shì yīnwèi rénmen hěn rèqíng.","vi":"Tôi thích nơi này là vì mọi người rất nhiệt tình.","en":"I like it here because the people are so friendly."}]},"没有":{"en":"not have; there is not; have not; not as ... as","exs":[{"use":"Động từ: 没有 + danh từ (không có).","ex":"我没有哥哥，只有一个妹妹。","py":"Wǒ méiyǒu gēge, zhǐyǒu yí ge mèimei.","vi":"Tôi không có anh trai, chỉ có một em gái.","en":"I don't have an older brother, only a younger sister."},{"use":"Nơi chốn + 没有 + người/vật: không có.","ex":"教室里没有人。","py":"Jiàoshì lǐ méiyǒu rén.","vi":"Trong phòng học không có ai.","en":"There is nobody in the classroom."},{"use":"没有 + động từ (+ 过): phủ định hành động đã xảy ra / từng trải qua.","ex":"我没有去过北京。","py":"Wǒ méiyǒu qù guo Běijīng.","vi":"Tôi chưa từng đến Bắc Kinh.","en":"I have never been to Beijing."},{"use":"So sánh phủ định: A 没有 B + adj.","ex":"我的汉语没有他好。","py":"Wǒ de Hànyǔ méiyǒu tā hǎo.","vi":"Tiếng Trung của tôi không giỏi bằng anh ấy.","en":"My Chinese isn't as good as his."}]},"容易":{"en":"easy; easily; likely to","exs":[{"use":"容易 + động từ: dễ làm gì; 不容易: không dễ. Ví dụ: 容易忘记、容易生病。","ex":"这个问题不容易回答。","py":"Zhège wèntí bù róngyì huídá.","vi":"Câu hỏi này không dễ trả lời.","en":"This question isn't easy to answer."},{"use":"容易 + 生病 / 感冒: dễ bị (điều không tốt).","ex":"天气冷，孩子容易生病。","py":"Tiānqì lěng, háizi róngyì shēngbìng.","vi":"Trời lạnh, trẻ con dễ bị ốm.","en":"When it's cold, children get sick easily."},{"use":"Tính từ làm vị ngữ: 很容易 = rất dễ.","ex":"这道题很容易，我一分钟就做完了。","py":"Zhè dào tí hěn róngyì, wǒ yì fēnzhōng jiù zuòwán le.","vi":"Bài này rất dễ, tôi làm xong trong một phút.","en":"This problem is very easy; I finished it in a minute."},{"use":"容易 + tính từ/tâm trạng: dễ (hay) …","ex":"他容易紧张，所以考试前睡不好。","py":"Tā róngyì jǐnzhāng, suǒyǐ kǎoshì qián shuì bù hǎo.","vi":"Anh ấy dễ căng thẳng nên trước kỳ thi ngủ không ngon.","en":"He gets nervous easily, so he sleeps badly before exams."}]},"如果":{"en":"if; in case; supposing","exs":[{"use":"Dùng mở đầu mệnh đề điều kiện; thường đi với 就 ở vế sau.","ex":"如果你有时间，就来找我吧。","py":"Rúguǒ nǐ yǒu shíjiān, jiù lái zhǎo wǒ ba.","vi":"Nếu bạn có thời gian thì đến tìm tôi nhé.","en":"If you have time, come and find me."},{"use":"如果…就…: kết quả của giả thiết.","ex":"如果明天下雨，我们就不去爬山了。","py":"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù páshān le.","vi":"Nếu ngày mai mưa thì chúng ta không đi leo núi nữa.","en":"If it rains tomorrow, we won't go hiking."},{"use":"Có thể đặt sau chủ ngữ: 主语 + 如果….","ex":"你如果不舒服，就早点回家休息。","py":"Nǐ rúguǒ bù shūfu, jiù zǎodiǎn huí jiā xiūxi.","vi":"Nếu bạn khó chịu trong người thì về nhà nghỉ sớm đi.","en":"If you're not feeling well, go home and rest early."},{"use":"如果我是你: giả thiết đặt mình vào vị trí người khác.","ex":"如果我是你，我会去试试。","py":"Rúguǒ wǒ shì nǐ, wǒ huì qù shìshi.","vi":"Nếu tôi là bạn, tôi sẽ đi thử.","en":"If I were you, I'd give it a try."}]},"或者":{"en":"or; either...or...; perhaps","exs":[{"use":"或者 nối hai lựa chọn trong câu trần thuật.","ex":"你可以坐地铁或者坐公共汽车。","py":"Nǐ kěyǐ zuò dìtiě huòzhě zuò gōnggòng qìchē.","vi":"Bạn có thể đi tàu điện ngầm hoặc xe buýt.","en":"You can take the subway or the bus."},{"use":"A 或者 B trong kế hoạch, dự định.","ex":"周末我想看电影或者去逛街。","py":"Zhōumò wǒ xiǎng kàn diànyǐng huòzhě qù guàngjiē.","vi":"Cuối tuần tôi muốn xem phim hoặc đi dạo phố.","en":"On the weekend I want to watch a movie or go shopping."},{"use":"Nối hai mốc thời gian: 明天或者后天.","ex":"明天或者后天，我给你打电话。","py":"Míngtiān huòzhě hòutiān, wǒ gěi nǐ dǎ diànhuà.","vi":"Ngày mai hoặc ngày kia tôi sẽ gọi điện cho bạn.","en":"I'll call you tomorrow or the day after."},{"use":"或者…，或者…: hoặc là … hoặc là …","ex":"或者你来我家，或者我去你家，都可以。","py":"Huòzhě nǐ lái wǒ jiā, huòzhě wǒ qù nǐ jiā, dōu kěyǐ.","vi":"Hoặc bạn đến nhà tôi, hoặc tôi đến nhà bạn, đều được.","en":"Either you come to my place or I go to yours; both are fine."}]},"成为":{"en":"to become; to turn into","exs":[{"use":"成为 + danh từ (nghề nghiệp, thân phận).","ex":"他想成为一名医生。","py":"Tā xiǎng chéngwéi yì míng yīshēng.","vi":"Anh ấy muốn trở thành một bác sĩ.","en":"He wants to become a doctor."},{"use":"已经成为 + (tính từ) + danh từ.","ex":"我们已经成为很好的朋友。","py":"Wǒmen yǐjīng chéngwéi hěn hǎo de péngyou.","vi":"Chúng tôi đã trở thành những người bạn rất tốt.","en":"We have already become good friends."},{"use":"Chủ ngữ là sự vật/xu hướng: A 成为 B.","ex":"网上购物成为了很多人的习惯。","py":"Wǎngshàng gòuwù chéngwéi le hěn duō rén de xíguàn.","vi":"Mua sắm trực tuyến đã trở thành thói quen của nhiều người.","en":"Online shopping has become a habit for many people."},{"use":"经过努力 + 成为: kết quả sau quá trình cố gắng.","ex":"经过努力，她成为了公司的经理。","py":"Jīngguò nǔlì, tā chéngwéi le gōngsī de jīnglǐ.","vi":"Sau nỗ lực, cô ấy đã trở thành giám đốc của công ty.","en":"After hard work, she became the company's manager."}]},"一生":{"en":"whole life; lifetime","exs":[{"use":"Làm trạng ngữ: 一生都 + động từ (cả đời).","ex":"他一生都在教书。","py":"Tā yìshēng dōu zài jiāoshū.","vi":"Cả đời ông ấy đều làm nghề dạy học.","en":"He spent his whole life teaching."},{"use":"一生中: trong cả cuộc đời.","ex":"结婚是一生中很重要的事。","py":"Jiéhūn shì yìshēng zhōng hěn zhòngyào de shì.","vi":"Kết hôn là chuyện rất quan trọng trong đời người.","en":"Marriage is a very important event in one's life."},{"use":"Lời chúc: 祝/希望 + 你一生平安.","ex":"我希望你一生平安。","py":"Wǒ xīwàng nǐ yìshēng píng'ān.","vi":"Tôi mong bạn bình an cả đời.","en":"I hope you stay safe and well all your life."},{"use":"Làm chủ ngữ: 某人的一生.","ex":"爷爷的一生很不容易。","py":"Yéye de yìshēng hěn bù róngyì.","vi":"Cuộc đời của ông nội không hề dễ dàng.","en":"Grandpa's life was not easy."}]},"不同":{"en":"different; not the same","exs":[{"use":"不同的 + danh từ.","ex":"每个人的想法不同。","py":"Měi ge rén de xiǎngfǎ bùtóng.","vi":"Suy nghĩ của mỗi người khác nhau.","en":"Everyone's ideas are different."},{"use":"Tính từ làm vị ngữ: 很不同 = rất khác nhau.","ex":"两个城市的天气很不同。","py":"Liǎng ge chéngshì de tiānqì hěn bùtóng.","vi":"Thời tiết của hai thành phố rất khác nhau.","en":"The weather in the two cities is very different."},{"use":"不同的 + người + có + 不同的 + vật: mỗi người một khác.","ex":"不同的人有不同的爱好。","py":"Bùtóng de rén yǒu bùtóng de àihào.","vi":"Mỗi người khác nhau có sở thích khác nhau.","en":"Different people have different hobbies."},{"use":"A 和 B 不同: A khác B.","ex":"这件衣服和那件的颜色不同。","py":"Zhè jiàn yīfu hé nà jiàn de yánsè bùtóng.","vi":"Màu của chiếc áo này khác với chiếc kia.","en":"This shirt is a different color from that one."}]},"有些":{"en":"some; somewhat","exs":[{"use":"有些 + danh từ…，有些…: có người … có người …","ex":"有些人喜欢早起，有些人喜欢晚睡。","py":"Yǒuxiē rén xǐhuan zǎo qǐ, yǒuxiē rén xǐhuan wǎn shuì.","vi":"Có người thích dậy sớm, có người thích ngủ muộn.","en":"Some people like to get up early, others like to stay up late."},{"use":"Phó từ: 有些 + tính từ (hơi, khá), thường mang sắc thái không tốt.","ex":"这些菜有些太辣了。","py":"Zhèxiē cài yǒuxiē tài là le.","vi":"Những món này hơi cay quá.","en":"These dishes are a bit too spicy."},{"use":"有些 + danh từ chỉ một phần trong tổng thể.","ex":"教室里有些同学在看书。","py":"Jiàoshì lǐ yǒuxiē tóngxué zài kànshū.","vi":"Trong lớp có một số bạn đang đọc sách.","en":"Some students in the classroom are reading."},{"use":"有些 + 冷/热/累: hơi lạnh, nóng, mệt.","ex":"今天有些冷，多穿点儿衣服。","py":"Jīntiān yǒuxiē lěng, duō chuān diǎnr yīfu.","vi":"Hôm nay hơi lạnh, mặc thêm áo vào.","en":"It's a bit cold today; wear more clothes."}]},"应该":{"en":"should; ought to; must be","exs":[{"use":"Đặt trước động từ để đưa lời khuyên.","ex":"你应该早点休息。","py":"Nǐ yīnggāi zǎodiǎn xiūxi.","vi":"Bạn nên nghỉ sớm.","en":"You should rest earlier."},{"use":"Nghĩa nên: 应该 + 多 + động từ.","ex":"孩子应该多运动。","py":"Háizi yīnggāi duō yùndòng.","vi":"Trẻ em nên vận động nhiều.","en":"Kids should exercise more."},{"use":"Nghĩa suy đoán: chắc là, hẳn là.","ex":"他现在应该到家了。","py":"Tā xiànzài yīnggāi dào jiā le.","vi":"Bây giờ chắc anh ấy đã về đến nhà rồi.","en":"He should be home by now."},{"use":"Phủ định: 不应该 = không nên.","ex":"你不应该这样说话。","py":"Nǐ bù yīnggāi zhèyàng shuōhuà.","vi":"Bạn không nên nói chuyện như vậy.","en":"You shouldn't talk like that."}]},"遇到":{"en":"to meet; to run into; to encounter","exs":[{"use":"遇到 + người / việc / khó khăn.","ex":"遇到问题别着急。","py":"Yùdào wèntí bié zháojí.","vi":"Gặp vấn đề đừng vội.","en":"Don't panic when you run into a problem."},{"use":"遇到 + người: tình cờ gặp.","ex":"昨天我在街上遇到了老同学。","py":"Zuótiān wǒ zài jiē shàng yùdào le lǎo tóngxué.","vi":"Hôm qua tôi tình cờ gặp bạn học cũ trên phố.","en":"Yesterday I ran into an old classmate on the street."},{"use":"遇到 + nhiều người / sự việc trong chuyến đi.","ex":"旅行时遇到了很多热情的人。","py":"Lǚxíng shí yùdào le hěn duō rèqíng de rén.","vi":"Khi đi du lịch tôi đã gặp rất nhiều người nhiệt tình.","en":"I met a lot of friendly people while traveling."},{"use":"如果遇到困难: kết hợp cố định 遇到困难.","ex":"如果遇到困难，可以找我。","py":"Rúguǒ yùdào kùnnan, kěyǐ zhǎo wǒ.","vi":"Nếu gặp khó khăn thì có thể tìm tôi.","en":"If you run into difficulties, you can come to me."}]},"身边":{"en":"by one's side; around oneself; nearby","exs":[{"use":"在 + 人 + 身边: ở bên cạnh ai.","ex":"他不在我身边。","py":"Tā bú zài wǒ shēnbiān.","vi":"Anh ấy không ở bên cạnh tôi.","en":"He isn't by my side."},{"use":"身边的 + danh từ: những người/vật xung quanh mình.","ex":"我身边的朋友都很喜欢运动。","py":"Wǒ shēnbiān de péngyou dōu hěn xǐhuan yùndòng.","vi":"Bạn bè xung quanh tôi đều rất thích vận động.","en":"The friends around me all love sports."},{"use":"一直在…身边: luôn ở bên cạnh.","ex":"孩子睡觉的时候，妈妈一直在他身边。","py":"Háizi shuìjiào de shíhou, māma yìzhí zài tā shēnbiān.","vi":"Lúc con ngủ, mẹ luôn ở bên cạnh con.","en":"While the child slept, his mother stayed by his side."},{"use":"把 + vật + 放在身边: để vật ở gần người.","ex":"请把手机放在身边。","py":"Qǐng bǎ shǒujī fàng zài shēnbiān.","vi":"Hãy để điện thoại ở bên cạnh bạn.","en":"Please keep your phone with you."}]},"感到":{"en":"to feel; to sense","exs":[{"use":"感到 + tính từ chỉ cảm xúc.","ex":"听到这个消息，我感到很高兴。","py":"Tīngdào zhège xiāoxi, wǒ gǎndào hěn gāoxìng.","vi":"Nghe tin này, tôi cảm thấy rất vui.","en":"I felt very happy to hear this news."},{"use":"感到 + 有点儿 + tính từ.","ex":"刚到新公司，他感到有点儿紧张。","py":"Gāng dào xīn gōngsī, tā gǎndào yǒudiǎnr jǐnzhāng.","vi":"Vừa vào công ty mới, anh ấy cảm thấy hơi căng thẳng.","en":"Having just joined the new company, he feels a bit nervous."},{"use":"感到 + cảm giác cơ thể.","ex":"我感到身体不太舒服。","py":"Wǒ gǎndào shēntǐ bú tài shūfu.","vi":"Tôi cảm thấy trong người không khỏe lắm.","en":"I feel a bit unwell."},{"use":"看到…，感到…: nhìn thấy … nên cảm thấy …","ex":"看到孩子的进步，妈妈感到很骄傲。","py":"Kàndào háizi de jìnbù, māma gǎndào hěn jiāo'ào.","vi":"Nhìn thấy sự tiến bộ của con, mẹ cảm thấy rất tự hào.","en":"Seeing her child's progress, the mother felt very proud."}]},"中国":{"en":"China","exs":[{"use":"Tên nước, làm tân ngữ: 去 + 中国.","ex":"我去过两次中国。","py":"Wǒ qù guo liǎng cì Zhōngguó.","vi":"Tôi đã đến Trung Quốc hai lần.","en":"I have been to China twice."},{"use":"Làm chủ ngữ để nói về đất nước.","ex":"中国很大，各地的天气不一样。","py":"Zhōngguó hěn dà, gè dì de tiānqì bù yíyàng.","vi":"Trung Quốc rất rộng, thời tiết mỗi nơi không giống nhau.","en":"China is huge, and the weather differs from place to place."},{"use":"在中国 + động từ: ở Trung Quốc làm gì.","ex":"他在中国学了三年汉语。","py":"Tā zài Zhōngguó xué le sān nián Hànyǔ.","vi":"Anh ấy đã học tiếng Trung ba năm ở Trung Quốc.","en":"He studied Chinese in China for three years."},{"use":"中国 + danh từ (中国菜, 中国人…): thuộc Trung Quốc.","ex":"中国菜我都爱吃。","py":"Zhōngguó cài wǒ dōu ài chī.","vi":"Món Trung Quốc món nào tôi cũng thích ăn.","en":"I love all kinds of Chinese food."}]},"适应":{"en":"to adapt; to adjust to; to get used to","exs":[{"use":"适应 + hoàn cảnh / công việc mới.","ex":"我还在适应新的工作。","py":"Wǒ hái zài shìyìng xīn de gōngzuò.","vi":"Tôi vẫn đang thích ứng với công việc mới.","en":"I'm still adjusting to my new job."},{"use":"不适应: chưa thích nghi được.","ex":"刚来的时候不适应这里的天气。","py":"Gāng lái de shíhou bú shìyìng zhèlǐ de tiānqì.","vi":"Lúc mới đến tôi không thích nghi được với thời tiết ở đây.","en":"When I first came, I couldn't adapt to the weather here."},{"use":"适应了: đã thích nghi (nhanh).","ex":"孩子很快就适应了新学校。","py":"Háizi hěn kuài jiù shìyìng le xīn xuéxiào.","vi":"Đứa trẻ nhanh chóng thích nghi với trường mới.","en":"The child quickly adapted to the new school."},{"use":"需要一段时间来适应.","ex":"你需要一段时间来适应。","py":"Nǐ xūyào yí duàn shíjiān lái shìyìng.","vi":"Bạn cần một khoảng thời gian để thích nghi.","en":"You need some time to adjust."}]},"这儿":{"en":"here","exs":[{"use":"Đại từ chỉ nơi chốn: 在这儿 + động từ.","ex":"你在这儿等我一下。","py":"Nǐ zài zhèr děng wǒ yíxià.","vi":"Bạn chờ tôi một chút ở đây nhé.","en":"Wait for me here for a moment."},{"use":"这儿 làm chủ ngữ: 这儿离…很近.","ex":"这儿离火车站很近。","py":"Zhèr lí huǒchēzhàn hěn jìn.","vi":"Chỗ này rất gần ga tàu.","en":"It's very close to the train station here."},{"use":"到这儿来: đến chỗ này.","ex":"请到这儿来。","py":"Qǐng dào zhèr lái.","vi":"Mời đến chỗ này.","en":"Please come over here."},{"use":"这儿的 + danh từ: … ở đây.","ex":"这儿的东西不贵。","py":"Zhèr de dōngxi bú guì.","vi":"Đồ ở đây không đắt.","en":"Things here aren't expensive."}]},"马克":{"en":"Mark (a personal name)","exs":[{"use":"Tên người nước ngoài (Mark), làm chủ ngữ.","ex":"马克是我的同学。","py":"Mǎkè shì wǒ de tóngxué.","vi":"Mark là bạn học của tôi.","en":"Mark is my classmate."},{"use":"马克 + 来自 + nước: Mark đến từ …","ex":"马克来自美国，在北京学汉语。","py":"Mǎkè láizì Měiguó, zài Běijīng xué Hànyǔ.","vi":"Mark đến từ Mỹ, đang học tiếng Trung ở Bắc Kinh.","en":"Mark is from the US and studies Chinese in Beijing."},{"use":"和马克一起: cùng với Mark.","ex":"我和马克一起去图书馆。","py":"Wǒ hé Mǎkè yìqǐ qù túshūguǎn.","vi":"Tôi và Mark cùng đi thư viện.","en":"Mark and I are going to the library together."},{"use":"马克的 + danh từ: của Mark.","ex":"马克的汉语说得越来越好。","py":"Mǎkè de Hànyǔ shuō de yuè lái yuè hǎo.","vi":"Tiếng Trung của Mark nói ngày càng tốt.","en":"Mark's Chinese is getting better and better."}]},"开始":{"en":"to begin; to start; beginning","exs":[{"use":"Động từ: 开始 + động từ/danh từ.","ex":"现在开始上课。","py":"Xiànzài kāishǐ shàngkè.","vi":"Bây giờ bắt đầu vào học.","en":"Class begins now."},{"use":"Chủ ngữ + 点 + 开始: bắt đầu lúc mấy giờ.","ex":"电影八点开始。","py":"Diànyǐng bā diǎn kāishǐ.","vi":"Phim bắt đầu lúc tám giờ.","en":"The movie starts at eight."},{"use":"从…开始: bắt đầu từ …","ex":"我从去年开始学游泳。","py":"Wǒ cóng qùnián kāishǐ xué yóuyǒng.","vi":"Tôi bắt đầu học bơi từ năm ngoái.","en":"I started learning to swim last year."},{"use":"一开始…，后来…: lúc đầu …, sau đó …","ex":"一开始我听不懂，后来慢慢习惯了。","py":"Yì kāishǐ wǒ tīng bu dǒng, hòulái mànmàn xíguàn le.","vi":"Lúc đầu tôi nghe không hiểu, sau dần dần quen.","en":"At first I couldn't understand, but later I gradually got used to it."},{"use":"Làm danh từ: 一个好的开始.","ex":"这是一个好的开始。","py":"Zhè shì yí ge hǎo de kāishǐ.","vi":"Đây là một khởi đầu tốt.","en":"This is a good start."}]},"有点儿":{"en":"a little; somewhat; a bit","exs":[{"use":"有点儿 + tính từ (thường nghĩa không như ý): hơi …","ex":"今天有点儿冷。","py":"Jīntiān yǒudiǎnr lěng.","vi":"Hôm nay hơi lạnh.","en":"It's a bit cold today."},{"use":"Nhận xét món ăn: 有点儿 + 咸/辣/甜.","ex":"这个菜有点儿咸。","py":"Zhège cài yǒudiǎnr xián.","vi":"Món này hơi mặn.","en":"This dish is a little salty."},{"use":"Nói về cảm giác bản thân: 我有点儿累.","ex":"我有点儿累，想早点睡觉。","py":"Wǒ yǒudiǎnr lèi, xiǎng zǎodiǎn shuìjiào.","vi":"Tôi hơi mệt, muốn đi ngủ sớm.","en":"I'm a little tired and want to go to bed early."},{"use":"有点儿 + 不 + tính từ: hơi không …","ex":"他今天有点儿不高兴。","py":"Tā jīntiān yǒudiǎnr bù gāoxìng.","vi":"Hôm nay anh ấy hơi không vui.","en":"He is a bit unhappy today."}]},"最近":{"en":"recently; lately; nearest","exs":[{"use":"Phó từ chỉ thời gian, hỏi thăm: 最近 + tính từ?","ex":"你最近忙不忙？","py":"Nǐ zuìjìn máng bu máng?","vi":"Dạo này bạn có bận không?","en":"Have you been busy lately?"},{"use":"最近 + 在 + động từ: dạo này đang …","ex":"我最近在学做中国菜。","py":"Wǒ zuìjìn zài xué zuò Zhōngguó cài.","vi":"Dạo này tôi đang học nấu món Trung Quốc.","en":"Lately I've been learning to cook Chinese food."},{"use":"最近 làm trạng ngữ đầu câu.","ex":"最近天气变冷了。","py":"Zuìjìn tiānqì biàn lěng le.","vi":"Gần đây trời trở lạnh rồi.","en":"It has gotten colder recently."},{"use":"Nghĩa 2 (tính từ, khoảng cách): gần nhất.","ex":"离这儿最近的地铁站在哪儿？","py":"Lí zhèr zuìjìn de dìtiězhàn zài nǎr?","vi":"Ga tàu điện ngầm gần đây nhất ở đâu?","en":"Where is the nearest subway station?"}]},"讲讲":{"en":"to tell; to talk about (a bit)","exs":[{"use":"Động từ lặp (V讲讲): kể thử một chút; 给 + người + 讲讲.","ex":"请你给我们讲讲你的旅行。","py":"Qǐng nǐ gěi wǒmen jiǎngjiǎng nǐ de lǚxíng.","vi":"Mời bạn kể cho chúng tôi nghe về chuyến đi của bạn.","en":"Please tell us about your trip."},{"use":"能…讲讲…吗: nhờ giải thích.","ex":"你能讲讲这个词的用法吗？","py":"Nǐ néng jiǎngjiǎng zhège cí de yòngfǎ ma?","vi":"Bạn có thể giải thích cách dùng của từ này không?","en":"Could you explain how this word is used?"},{"use":"让 + người + 讲讲: yêu cầu ai chia sẻ.","ex":"老师想让他讲讲自己的学习经验。","py":"Lǎoshī xiǎng ràng tā jiǎngjiǎng zìjǐ de xuéxí jīngyàn.","vi":"Thầy giáo muốn anh ấy chia sẻ kinh nghiệm học tập của mình.","en":"The teacher wants him to talk about his own study experience."},{"use":"讲讲故事: kể chuyện.","ex":"晚上我给孩子讲讲故事。","py":"Wǎnshang wǒ gěi háizi jiǎngjiǎng gùshi.","vi":"Buổi tối tôi kể chuyện cho con nghe.","en":"In the evening I tell my child a story."}]},"图书馆":{"en":"library","exs":[{"use":"去图书馆 + động từ.","ex":"我常常去图书馆看书。","py":"Wǒ chángcháng qù túshūguǎn kànshū.","vi":"Tôi thường đến thư viện đọc sách.","en":"I often go to the library to read."},{"use":"Địa điểm, giờ mở cửa.","ex":"学校的图书馆星期天也开门。","py":"Xuéxiào de túshūguǎn xīngqītiān yě kāimén.","vi":"Thư viện của trường Chủ nhật cũng mở cửa.","en":"The school library is open on Sundays too."},{"use":"图书馆里: bên trong thư viện, quy định.","ex":"图书馆里很安静，不能大声说话。","py":"Túshūguǎn lǐ hěn ānjìng, bù néng dàshēng shuōhuà.","vi":"Trong thư viện rất yên tĩnh, không được nói to.","en":"It's quiet in the library; you can't talk loudly."},{"use":"从图书馆借: mượn từ thư viện.","ex":"这本书是我从图书馆借的。","py":"Zhè běn shū shì wǒ cóng túshūguǎn jiè de.","vi":"Cuốn sách này là tôi mượn từ thư viện.","en":"I borrowed this book from the library."}]},"平时":{"en":"usually; ordinarily; normal times","exs":[{"use":"Dùng để nói thói quen hoặc tình trạng thường ngày.","ex":"我平时晚上十点睡觉。","py":"Wǒ píngshí wǎnshang shí diǎn shuìjiào.","vi":"Bình thường tôi ngủ lúc 10 giờ tối.","en":"I usually go to bed at ten at night."},{"use":"平时 + 很少 + động từ: bình thường rất ít …","ex":"他平时很少看电视。","py":"Tā píngshí hěn shǎo kàn diànshì.","vi":"Bình thường anh ấy rất ít xem ti vi.","en":"He rarely watches TV normally."},{"use":"平时…，周末…: đối chiếu ngày thường và cuối tuần.","ex":"平时工作很忙，周末才有时间休息。","py":"Píngshí gōngzuò hěn máng, zhōumò cái yǒu shíjiān xiūxi.","vi":"Ngày thường công việc rất bận, cuối tuần mới có thời gian nghỉ ngơi.","en":"I'm busy at work on regular days and only have time to rest on weekends."},{"use":"Làm danh từ: 比平时 (so với bình thường).","ex":"今天人比平时多了很多。","py":"Jīntiān rén bǐ píngshí duō le hěn duō.","vi":"Hôm nay người đông hơn bình thường rất nhiều.","en":"There are many more people today than usual."}]},"常常":{"en":"often; frequently","exs":[{"use":"常常 + động từ (đặt trước động từ).","ex":"他常常迟到。","py":"Tā chángcháng chídào.","vi":"Anh ấy thường xuyên đến muộn.","en":"He is often late."},{"use":"常常 + 一起 + động từ.","ex":"我们常常一起吃午饭。","py":"Wǒmen chángcháng yìqǐ chī wǔfàn.","vi":"Chúng tôi thường cùng nhau ăn trưa.","en":"We often have lunch together."},{"use":"常常 + 给…打电话: hay gọi điện cho ai.","ex":"妈妈常常给我打电话。","py":"Māma chángcháng gěi wǒ dǎ diànhuà.","vi":"Mẹ thường gọi điện cho tôi.","en":"My mom often calls me."},{"use":"Phủ định: 不常常 = không thường.","ex":"我不常常去那家店。","py":"Wǒ bù chángcháng qù nà jiā diàn.","vi":"Tôi không thường đến cửa hàng đó.","en":"I don't go to that shop often."}]},"看书":{"en":"to read (a book); to study","exs":[{"use":"Động từ ly hợp: 看书 (đọc sách).","ex":"他喜欢晚上在家看书。","py":"Tā xǐhuan wǎnshang zài jiā kànshū.","vi":"Anh ấy thích đọc sách ở nhà vào buổi tối.","en":"He likes reading at home in the evenings."},{"use":"睡觉前看书: thói quen đọc sách.","ex":"我每天睡觉前都看书。","py":"Wǒ měi tiān shuìjiào qián dōu kànshū.","vi":"Mỗi ngày trước khi ngủ tôi đều đọc sách.","en":"I read every day before bed."},{"use":"在 + nơi chốn + 看书.","ex":"孩子在房间里看书，请别吵他。","py":"Háizi zài fángjiān lǐ kànshū, qǐng bié chǎo tā.","vi":"Đứa trẻ đang đọc sách trong phòng, xin đừng làm ồn nó.","en":"The child is reading in the room; please don't disturb him."},{"use":"去 + nơi + 看书: đi đâu đó để đọc sách.","ex":"周末我们去咖啡馆看书。","py":"Zhōumò wǒmen qù kāfēiguǎn kànshū.","vi":"Cuối tuần chúng tôi đến quán cà phê đọc sách.","en":"On weekends we go to a café to read."}]},"逛街":{"en":"to go window-shopping; to stroll along the street","exs":[{"use":"去逛街 / 和…逛街: đi dạo phố cùng ai.","ex":"周末我常和朋友去逛街。","py":"Zhōumò wǒ cháng hé péngyou qù guàngjiē.","vi":"Cuối tuần tôi thường đi dạo phố với bạn.","en":"On weekends I often go window-shopping with friends."},{"use":"逛街 + động từ: dạo phố để làm gì.","ex":"她最喜欢逛街买衣服。","py":"Tā zuì xǐhuan guàngjiē mǎi yīfu.","vi":"Cô ấy thích nhất là đi dạo phố mua quần áo.","en":"She loves to stroll the shops and buy clothes."},{"use":"Lặp động từ chỉ thời lượng: 逛街逛了…","ex":"我们逛街逛了三个小时。","py":"Wǒmen guàngjiē guàng le sān ge xiǎoshí.","vi":"Chúng tôi đi dạo phố suốt ba tiếng đồng hồ.","en":"We spent three hours shopping around."},{"use":"Lời rủ rê: 一起去逛街吧.","ex":"下午你有空吗？一起去逛街吧。","py":"Xiàwǔ nǐ yǒu kòng ma? Yìqǐ qù guàngjiē ba.","vi":"Chiều nay bạn rảnh không? Cùng đi dạo phố nhé.","en":"Are you free this afternoon? Let's go shopping together."}]},"踢足球":{"en":"to play football (soccer)","exs":[{"use":"Cụm cố định: 踢 + 足球 (đá bóng).","ex":"我们每个星期六都踢足球。","py":"Wǒmen měi ge xīngqīliù dōu tī zúqiú.","vi":"Thứ Bảy nào chúng tôi cũng đá bóng.","en":"We play soccer every Saturday."},{"use":"喜欢踢足球: sở thích.","ex":"他喜欢踢足球，不太喜欢游泳。","py":"Tā xǐhuan tī zúqiú, bú tài xǐhuan yóuyǒng.","vi":"Anh ấy thích đá bóng, không thích bơi lắm.","en":"He likes playing soccer and doesn't like swimming much."},{"use":"去 + nơi + 踢足球.","ex":"下午我要和同学去操场踢足球。","py":"Xiàwǔ wǒ yào hé tóngxué qù cāochǎng tī zúqiú.","vi":"Chiều nay tôi đi sân vận động đá bóng với bạn học.","en":"This afternoon I'm going to the playground to play soccer with classmates."},{"use":"会 + 踢足球: biết đá bóng.","ex":"你会踢足球吗？","py":"Nǐ huì tī zúqiú ma?","vi":"Bạn có biết đá bóng không?","en":"Can you play soccer?"}]},"一些":{"en":"some; a few; a little","exs":[{"use":"一些 + danh từ: một vài, một số.","ex":"我买了一些水果。","py":"Wǒ mǎi le yìxiē shuǐguǒ.","vi":"Tôi đã mua một ít trái cây.","en":"I bought some fruit."},{"use":"一些 + danh từ trừu tượng (时间, 帮助…).","ex":"请再给我一些时间。","py":"Qǐng zài gěi wǒ yìxiē shíjiān.","vi":"Xin cho tôi thêm một chút thời gian.","en":"Please give me a little more time."},{"use":"一些 + 很好的 + danh từ.","ex":"他提出了一些很好的建议。","py":"Tā tíchū le yìxiē hěn hǎo de jiànyì.","vi":"Anh ấy đã đưa ra một vài đề xuất rất hay.","en":"He made some very good suggestions."},{"use":"Tính từ + 了 + 一些: … hơn một chút.","ex":"天气好了一些。","py":"Tiānqì hǎo le yìxiē.","vi":"Thời tiết đã tốt hơn một chút.","en":"The weather has gotten a bit better."}]},"短信":{"en":"text message; SMS","exs":[{"use":"Lượng từ 条: 发一条短信.","ex":"我给他发了一条短信。","py":"Wǒ gěi tā fā le yì tiáo duǎnxìn.","vi":"Tôi đã gửi cho anh ấy một tin nhắn.","en":"I sent him a text message."},{"use":"收到短信: nhận được tin nhắn.","ex":"你收到我的短信了吗？","py":"Nǐ shōudào wǒ de duǎnxìn le ma?","vi":"Bạn đã nhận được tin nhắn của tôi chưa?","en":"Did you get my text message?"},{"use":"回短信: trả lời tin nhắn.","ex":"我还没回他的短信。","py":"Wǒ hái méi huí tā de duǎnxìn.","vi":"Tôi vẫn chưa trả lời tin nhắn của anh ấy.","en":"I haven't replied to his text yet."},{"use":"用短信 + động từ: dùng tin nhắn để …","ex":"他用短信告诉我会议改时间了。","py":"Tā yòng duǎnxìn gàosu wǒ huìyì gǎi shíjiān le.","vi":"Anh ấy nhắn tin báo tôi cuộc họp đổi giờ rồi.","en":"He texted me that the meeting time had changed."}]},"真不错":{"en":"really good; pretty nice","exs":[{"use":"真不错: lời khen, nhận xét tích cực.","ex":"这家饭馆的菜真不错！","py":"Zhè jiā fànguǎn de cài zhēn búcuò!","vi":"Món ở quán này thật không tồi!","en":"The food at this restaurant is really good!"},{"use":"Khen khả năng: V得真不错.","ex":"你的汉语说得真不错！","py":"Nǐ de Hànyǔ shuō de zhēn búcuò!","vi":"Tiếng Trung của bạn nói thật không tồi!","en":"Your Chinese is really good!"},{"use":"Khen ý tưởng, đề nghị.","ex":"这个主意真不错，我们就这样做吧。","py":"Zhège zhǔyi zhēn búcuò, wǒmen jiù zhèyàng zuò ba.","vi":"Ý này thật hay, chúng ta cứ làm như vậy nhé.","en":"This idea is really good; let's do it this way."},{"use":"Khen đồ vật: 用起来真不错.","ex":"新买的手机真不错，用起来很方便。","py":"Xīn mǎi de shǒujī zhēn búcuò, yòng qǐlái hěn fāngbiàn.","vi":"Chiếc điện thoại mới mua thật tốt, dùng rất tiện.","en":"The new phone is really nice and convenient to use."}]},"下次":{"en":"next time","exs":[{"use":"Làm trạng ngữ đầu câu: 下次 + hứa hẹn.","ex":"下次我请你吃饭。","py":"Xiàcì wǒ qǐng nǐ chīfàn.","vi":"Lần sau tôi mời bạn ăn cơm.","en":"Next time I'll treat you to a meal."},{"use":"下次再…: để lần sau hãy …","ex":"下次再来玩儿吧。","py":"Xiàcì zài lái wánr ba.","vi":"Lần sau lại đến chơi nhé.","en":"Come visit again next time."},{"use":"这次…，下次…: đối chiếu lần này và lần sau.","ex":"这次没时间，下次一定去。","py":"Zhè cì méi shíjiān, xiàcì yídìng qù.","vi":"Lần này không có thời gian, lần sau nhất định đi.","en":"I have no time this time, but I'll definitely go next time."},{"use":"下次别…: lần sau đừng …","ex":"下次别忘了带伞。","py":"Xiàcì bié wàng le dài sǎn.","vi":"Lần sau đừng quên mang ô.","en":"Don't forget your umbrella next time."}]},"介绍":{"en":"to introduce; to recommend; introduction","exs":[{"use":"介绍一下 + người/việc: giới thiệu một chút.","ex":"让我来介绍一下，这是我的同事。","py":"Ràng wǒ lái jièshào yíxià, zhè shì wǒ de tóngshì.","vi":"Để tôi giới thiệu một chút, đây là đồng nghiệp của tôi.","en":"Let me introduce you; this is my colleague."},{"use":"给 + người + 介绍 + vật: giới thiệu, gợi ý cho ai.","ex":"他给我们介绍了一家好饭馆。","py":"Tā gěi wǒmen jièshào le yì jiā hǎo fànguǎn.","vi":"Anh ấy đã giới thiệu cho chúng tôi một quán ăn ngon.","en":"He recommended a good restaurant to us."},{"use":"介绍一下自己: tự giới thiệu.","ex":"请你介绍一下自己。","py":"Qǐng nǐ jièshào yíxià zìjǐ.","vi":"Mời bạn giới thiệu bản thân một chút.","en":"Please introduce yourself."},{"use":"介绍 + người + 认识 + người: giới thiệu cho quen biết.","ex":"朋友介绍我认识了他。","py":"Péngyou jièshào wǒ rènshi le tā.","vi":"Bạn bè đã giới thiệu để tôi quen biết anh ấy.","en":"A friend introduced me to him."}]},"下午":{"en":"afternoon","exs":[{"use":"Chỉ thời gian trong ngày, làm trạng ngữ.","ex":"下午我有一节汉语课。","py":"Xiàwǔ wǒ yǒu yì jié Hànyǔ kè.","vi":"Buổi chiều tôi có một tiết tiếng Trung.","en":"I have a Chinese class in the afternoon."},{"use":"Ngày + 下午 + giờ: hẹn giờ cụ thể.","ex":"明天下午三点开会。","py":"Míngtiān xiàwǔ sān diǎn kāihuì.","vi":"Ba giờ chiều mai họp.","en":"The meeting is at three tomorrow afternoon."},{"use":"昨天下午: chiều hôm qua.","ex":"昨天下午下了一场大雨。","py":"Zuótiān xiàwǔ xià le yì chǎng dà yǔ.","vi":"Chiều hôm qua có một trận mưa lớn.","en":"There was a heavy rain yesterday afternoon."},{"use":"Lời rủ rê: 今天下午…好吗?","ex":"今天下午我们去公园玩儿，好吗？","py":"Jīntiān xiàwǔ wǒmen qù gōngyuán wánr, hǎo ma?","vi":"Chiều nay chúng ta đi công viên chơi nhé?","en":"Shall we go to the park this afternoon?"}]},"正好":{"en":"just right; just in time; happen to; exactly","exs":[{"use":"Phó từ: 来得正好 = đến vừa đúng lúc.","ex":"你来得正好，我们刚要吃饭。","py":"Nǐ lái de zhènghǎo, wǒmen gāng yào chīfàn.","vi":"Bạn đến đúng lúc, chúng tôi vừa định ăn cơm.","en":"You came just in time; we were about to eat."},{"use":"Tính từ làm vị ngữ: vừa vặn.","ex":"这件衣服我穿正好。","py":"Zhè jiàn yīfu wǒ chuān zhènghǎo.","vi":"Chiếc áo này tôi mặc vừa khít.","en":"This shirt fits me just right."},{"use":"正好 + động từ: vừa hay, tình cờ đúng lúc.","ex":"我正好有空，可以陪你去。","py":"Wǒ zhènghǎo yǒu kòng, kěyǐ péi nǐ qù.","vi":"Tôi vừa hay rảnh, có thể đi cùng bạn.","en":"I happen to be free, so I can go with you."},{"use":"正好 đặt đầu câu chỉ sự trùng hợp.","ex":"正好在路上遇到他，我就把书给他了。","py":"Zhènghǎo zài lù shàng yùdào tā, wǒ jiù bǎ shū gěi tā le.","vi":"Vừa hay gặp anh ấy trên đường nên tôi đưa luôn quyển sách cho anh ấy.","en":"I happened to meet him on the road, so I gave him the book."}]},"星期天":{"en":"Sunday","exs":[{"use":"Chỉ thời gian: 星期天 + động từ.","ex":"星期天我一般在家休息。","py":"Xīngqītiān wǒ yìbān zài jiā xiūxi.","vi":"Chủ nhật tôi thường nghỉ ngơi ở nhà.","en":"I usually rest at home on Sundays."},{"use":"这个星期天: Chủ nhật tuần này; hỏi dự định.","ex":"这个星期天你有什么打算？","py":"Zhège xīngqītiān nǐ yǒu shénme dǎsuàn?","vi":"Chủ nhật này bạn có dự định gì?","en":"What are your plans this Sunday?"},{"use":"Câu hỏi về lịch mở cửa.","ex":"超市星期天开门吗？","py":"Chāoshì xīngqītiān kāimén ma?","vi":"Siêu thị Chủ nhật có mở cửa không?","en":"Is the supermarket open on Sundays?"},{"use":"上个星期天: Chủ nhật tuần trước.","ex":"上个星期天我们去爬山了。","py":"Shàng ge xīngqītiān wǒmen qù páshān le.","vi":"Chủ nhật tuần trước chúng tôi đã đi leo núi.","en":"Last Sunday we went hiking."}]},"同学聚会":{"en":"class reunion; classmates' gathering","exs":[{"use":"Một + lượng từ 次 + 同学聚会: một buổi họp lớp.","ex":"下个月有一次同学聚会。","py":"Xià ge yuè yǒu yí cì tóngxué jùhuì.","vi":"Tháng sau có một buổi họp lớp.","en":"There's a class reunion next month."},{"use":"参加同学聚会: tham dự họp lớp.","ex":"你去参加同学聚会吗？","py":"Nǐ qù cānjiā tóngxué jùhuì ma?","vi":"Bạn có đi dự buổi họp lớp không?","en":"Are you going to the class reunion?"},{"use":"在同学聚会上: tại buổi họp lớp.","ex":"在同学聚会上，大家聊了很多过去的事。","py":"Zài tóngxué jùhuì shàng, dàjiā liáo le hěn duō guòqù de shì.","vi":"Tại buổi họp lớp, mọi người đã kể nhiều chuyện ngày xưa.","en":"At the reunion, everyone talked about a lot of old times."},{"use":"办同学聚会: tổ chức họp lớp.","ex":"我们打算在饭店办一次同学聚会。","py":"Wǒmen dǎsuàn zài fàndiàn bàn yí cì tóngxué jùhuì.","vi":"Chúng tôi dự định tổ chức một buổi họp lớp ở nhà hàng.","en":"We plan to hold a class reunion at a restaurant."}]},"小林":{"en":"Xiao Lin (a personal name)","exs":[{"use":"Tên người, tiền tố 小 + họ: cách gọi thân mật.","ex":"小林是我的大学同学。","py":"Xiǎolín shì wǒ de dàxué tóngxué.","vi":"Tiểu Lâm là bạn đại học của tôi.","en":"Xiao Lin is my college classmate."},{"use":"Làm chủ ngữ chỉ người đang nói đến.","ex":"小林明天要去北京出差。","py":"Xiǎolín míngtiān yào qù Běijīng chūchāi.","vi":"Ngày mai Tiểu Lâm đi công tác ở Bắc Kinh.","en":"Xiao Lin is going on a business trip to Beijing tomorrow."},{"use":"Làm tân ngữ trong câu hỏi: 认识小林吗?","ex":"你认识小林吗？","py":"Nǐ rènshi Xiǎolín ma?","vi":"Bạn có quen Tiểu Lâm không?","en":"Do you know Xiao Lin?"},{"use":"给小林: làm đối tượng nhận của hành động.","ex":"我给小林发了一条短信。","py":"Wǒ gěi Xiǎolín fā le yì tiáo duǎnxìn.","vi":"Tôi đã nhắn cho Tiểu Lâm một tin.","en":"I sent Xiao Lin a text message."}]},"班里":{"en":"in the class","exs":[{"use":"班里 + 有 + số lượng: trong lớp có …","ex":"我们班里有二十个学生。","py":"Wǒmen bān lǐ yǒu èrshí ge xuésheng.","vi":"Lớp chúng tôi có hai mươi học sinh.","en":"There are twenty students in our class."},{"use":"班里的 + danh từ: … trong lớp.","ex":"班里的同学都很热情。","py":"Bān lǐ de tóngxué dōu hěn rèqíng.","vi":"Các bạn trong lớp đều rất nhiệt tình.","en":"The classmates in our class are all friendly."},{"use":"班里最…的人: so sánh nhất trong lớp.","ex":"他是班里年纪最大的人。","py":"Tā shì bān lǐ niánjì zuì dà de rén.","vi":"Anh ấy là người lớn tuổi nhất trong lớp.","en":"He is the oldest person in the class."},{"use":"班里 làm trạng ngữ nơi chốn đầu câu.","ex":"班里最近来了一位新老师。","py":"Bān lǐ zuìjìn lái le yí wèi xīn lǎoshī.","vi":"Gần đây lớp có thêm một giáo viên mới.","en":"A new teacher has joined the class recently."}]},"联系":{"en":"to contact; to get in touch; connection","exs":[{"use":"和 + người + 联系: liên lạc với ai.","ex":"到北京以后请和我联系。","py":"Dào Běijīng yǐhòu qǐng hé wǒ liánxì.","vi":"Đến Bắc Kinh rồi nhớ liên lạc với tôi nhé.","en":"Please get in touch with me after you arrive in Beijing."},{"use":"没有联系: đã lâu không liên lạc.","ex":"我们很久没有联系了。","py":"Wǒmen hěn jiǔ méiyǒu liánxì le.","vi":"Chúng tôi đã lâu không liên lạc.","en":"We haven't been in touch for a long time."},{"use":"打电话联系 + người: liên lạc bằng điện thoại.","ex":"有事可以打电话联系我。","py":"Yǒu shì kěyǐ dǎ diànhuà liánxì wǒ.","vi":"Có việc thì có thể gọi điện liên lạc với tôi.","en":"If anything comes up, you can call me."},{"use":"Danh từ: 有联系 / 联系 giữa hai sự việc.","ex":"这两件事有什么联系？","py":"Zhè liǎng jiàn shì yǒu shénme liánxì?","vi":"Hai việc này có liên quan gì với nhau?","en":"What's the connection between these two things?"}]},"多少":{"en":"how many; how much; more or less","exs":[{"use":"Dùng để hỏi số lượng; trong 不管有多少 là 'dù có bao nhiêu'.","ex":"这里有多少人？","py":"Zhèlǐ yǒu duōshao rén?","vi":"Ở đây có bao nhiêu người?","en":"How many people are here?"},{"use":"多少钱: hỏi giá.","ex":"这件衣服多少钱？","py":"Zhè jiàn yīfu duōshao qián?","vi":"Chiếc áo này bao nhiêu tiền?","en":"How much is this piece of clothing?"},{"use":"不管有多少…，都…: dù có bao nhiêu … cũng …","ex":"不管有多少困难，我们都要完成。","py":"Bùguǎn yǒu duōshao kùnnan, wǒmen dōu yào wánchéng.","vi":"Dù có bao nhiêu khó khăn, chúng ta cũng phải hoàn thành.","en":"No matter how many difficulties there are, we must finish."},{"use":"Đại từ nghi vấn dùng phiếm chỉ: 多少…就…多少.","ex":"你想吃多少就吃多少。","py":"Nǐ xiǎng chī duōshao jiù chī duōshao.","vi":"Bạn muốn ăn bao nhiêu thì ăn bấy nhiêu.","en":"Eat as much as you want."},{"use":"Phó từ: 多少 + động từ = ít nhiều.","ex":"这些药多少有点用。","py":"Zhèxiē yào duōshao yǒu diǎn yòng.","vi":"Những thuốc này ít nhiều cũng có tác dụng.","en":"These medicines are of some use, more or less."}]},"差不多":{"en":"almost; nearly; about the same","exs":[{"use":"Tính từ làm vị ngữ: A 和 B 差不多 / A, B 差不多.","ex":"我们俩年纪差不多。","py":"Wǒmen liǎ niánjì chàbuduō.","vi":"Hai chúng tôi tuổi tác xêm xêm nhau.","en":"The two of us are about the same age."},{"use":"差不多 + động từ + 了: gần như đã …","ex":"作业差不多写完了。","py":"Zuòyè chàbuduō xiě wán le.","vi":"Bài tập gần như làm xong rồi.","en":"I've almost finished my homework."},{"use":"差不多 + số lượng/thời gian: khoảng.","ex":"现在差不多十二点了，我们去吃饭吧。","py":"Xiànzài chàbuduō shí'èr diǎn le, wǒmen qù chīfàn ba.","vi":"Bây giờ gần mười hai giờ rồi, chúng ta đi ăn thôi.","en":"It's almost twelve o'clock; let's go eat."},{"use":"Chỉ hai vật không khác nhau nhiều.","ex":"这两件衣服差不多，你喜欢哪件？","py":"Zhè liǎng jiàn yīfu chàbuduō, nǐ xǐhuan nǎ jiàn?","vi":"Hai chiếc áo này gần giống nhau, bạn thích chiếc nào?","en":"These two shirts are about the same; which one do you like?"}]},"一半儿":{"en":"half; one half","exs":[{"use":"Làm tân ngữ: một nửa của đồ vật hoặc việc.","ex":"我吃了一半儿，剩下的明天再吃。","py":"Wǒ chīle yíbànr, shèngxià de míngtiān zài chī.","vi":"Tôi ăn một nửa rồi, phần còn lại mai ăn tiếp.","en":"I ate half of it; I'll eat the rest tomorrow."},{"use":"一人一半儿: mỗi người một nửa.","ex":"这个西瓜我们一人一半儿。","py":"Zhège xīguā wǒmen yì rén yíbànr.","vi":"Quả dưa hấu này mỗi người chúng ta một nửa.","en":"Let's each have half of this watermelon."},{"use":"只…了一半儿: mới làm được một nửa.","ex":"作业只写了一半儿，我就困了。","py":"Zuòyè zhǐ xiěle yíbànr, wǒ jiù kùn le.","vi":"Bài tập mới viết được một nửa là tôi đã buồn ngủ.","en":"I had only done half of my homework when I got sleepy."},{"use":"一半儿 + 的 + danh từ: làm định ngữ.","ex":"一半儿的学生都通过了考试。","py":"Yíbànr de xuésheng dōu tōngguòle kǎoshì.","vi":"Một nửa số học sinh đã thi đậu.","en":"Half of the students passed the exam."}]},"专门":{"en":"specially; specifically; specialized","exs":[{"use":"专门 + V: đặc biệt, cố ý làm việc gì.","ex":"我专门来看你，你却不在家。","py":"Wǒ zhuānmén lái kàn nǐ, nǐ què bú zài jiā.","vi":"Tôi đặc biệt đến thăm bạn, vậy mà bạn lại không ở nhà.","en":"I came specially to see you, but you weren't home."},{"use":"专门 + V: chuyên làm một việc nào đó.","ex":"他专门研究汉语语法。","py":"Tā zhuānmén yánjiū Hànyǔ yǔfǎ.","vi":"Anh ấy chuyên nghiên cứu ngữ pháp tiếng Hán.","en":"He specializes in studying Chinese grammar."},{"use":"专门为…: dành riêng cho ai.","ex":"这是专门为孩子准备的礼物。","py":"Zhè shì zhuānmén wèi háizi zhǔnbèi de lǐwù.","vi":"Đây là món quà được chuẩn bị riêng cho trẻ em.","en":"This is a gift prepared especially for the children."},{"use":"专门的 + danh từ: làm định ngữ, nghĩa 'chuyên môn'.","ex":"他在这方面有专门的知识。","py":"Tā zài zhè fāngmiàn yǒu zhuānmén de zhīshi.","vi":"Anh ấy có kiến thức chuyên môn về mặt này.","en":"He has specialized knowledge in this area."}]},"国外":{"en":"abroad; overseas; foreign countries","exs":[{"use":"Làm trạng ngữ nơi chốn: 在国外 + V.","ex":"他的哥哥在国外工作。","py":"Tā de gēge zài guówài gōngzuò.","vi":"Anh trai của anh ấy làm việc ở nước ngoài.","en":"His older brother works abroad."},{"use":"去国外 + V: đi nước ngoài làm gì.","ex":"我暑假想去国外旅游。","py":"Wǒ shǔjià xiǎng qù guówài lǚyóu.","vi":"Kỳ nghỉ hè tôi muốn ra nước ngoài du lịch.","en":"I want to travel abroad during the summer vacation."},{"use":"国外 đối lập với 国内; 国外的 + n làm định ngữ.","ex":"国外的生活和国内很不一样。","py":"Guówài de shēnghuó hé guónèi hěn bù yíyàng.","vi":"Cuộc sống ở nước ngoài rất khác với trong nước.","en":"Life abroad is very different from life at home."}]},"回来":{"en":"to come back; to return","exs":[{"use":"Động từ thường: về lại chỗ người nói đang ở.","ex":"你几点回来？","py":"Nǐ jǐ diǎn huílái?","vi":"Mấy giờ bạn về?","en":"What time will you be back?"},{"use":"从…回来: từ đâu trở về.","ex":"他刚从国外回来。","py":"Tā gāng cóng guówài huílái.","vi":"Anh ấy vừa từ nước ngoài về.","en":"He just came back from abroad."},{"use":"V + 回来: bổ ngữ xu hướng, mang vật về.","ex":"妈妈买回来很多水果。","py":"Māma mǎi huílai hěn duō shuǐguǒ.","vi":"Mẹ mua về rất nhiều trái cây.","en":"Mom bought a lot of fruit and brought it home."},{"use":"还没回来: chưa về.","ex":"爸爸还没回来，我们先吃吧。","py":"Bàba hái méi huílái, wǒmen xiān chī ba.","vi":"Bố vẫn chưa về, chúng ta ăn trước đi.","en":"Dad isn't back yet, so let's eat first."}]},"毕业":{"en":"to graduate","exs":[{"use":"Động từ li hợp: 大学毕业 = tốt nghiệp đại học.","ex":"我明年大学毕业。","py":"Wǒ míngnián dàxué bìyè.","vi":"Sang năm tôi tốt nghiệp đại học.","en":"I graduate from university next year."},{"use":"毕业以后: sau khi tốt nghiệp.","ex":"他毕业以后想找一份好工作。","py":"Tā bìyè yǐhòu xiǎng zhǎo yí fèn hǎo gōngzuò.","vi":"Sau khi tốt nghiệp anh ấy muốn tìm một công việc tốt.","en":"After graduating he wants to find a good job."},{"use":"是…的: nhấn mạnh trường đã tốt nghiệp.","ex":"你是哪所大学毕业的？","py":"Nǐ shì nǎ suǒ dàxué bìyè de?","vi":"Bạn tốt nghiệp trường đại học nào?","en":"Which university did you graduate from?"},{"use":"毕业 + thời lượng (li hợp): đã tốt nghiệp bao lâu.","ex":"他已经毕业两年了。","py":"Tā yǐjīng bìyè liǎng nián le.","vi":"Anh ấy đã tốt nghiệp được hai năm rồi.","en":"He graduated two years ago."}]},"大家":{"en":"everyone; everybody; all","exs":[{"use":"Dùng để chào hỏi một nhóm người.","ex":"大家好！我是新同学。","py":"Dàjiā hǎo! Wǒ shì xīn tóngxué.","vi":"Chào mọi người! Mình là bạn học mới.","en":"Hello everyone! I'm a new classmate."},{"use":"请大家 + V: lời đề nghị lịch sự với cả nhóm.","ex":"请大家安静一下。","py":"Qǐng dàjiā ānjìng yíxià.","vi":"Xin mọi người yên lặng một chút.","en":"Everyone, please be quiet for a moment."},{"use":"大家 + 都: mọi người đều.","ex":"这件事大家都知道。","py":"Zhè jiàn shì dàjiā dōu zhīdào.","vi":"Chuyện này mọi người đều biết.","en":"Everybody knows about this."},{"use":"给大家 + V: làm gì cho mọi người.","ex":"我给大家介绍一下我的同事。","py":"Wǒ gěi dàjiā jièshào yíxià wǒ de tóngshì.","vi":"Tôi xin giới thiệu với mọi người đồng nghiệp của tôi.","en":"Let me introduce my colleague to everyone."}]},"今天":{"en":"today","exs":[{"use":"Danh từ chỉ thời gian, đứng trước vị ngữ.","ex":"今天天气真好。","py":"Jīntiān tiānqì zhēn hǎo.","vi":"Hôm nay thời tiết thật đẹp.","en":"The weather is really nice today."},{"use":"今天 + 是 + ngày/thứ.","ex":"今天是星期五。","py":"Jīntiān shì xīngqīwǔ.","vi":"Hôm nay là thứ Sáu.","en":"Today is Friday."},{"use":"今天 + buổi trong ngày: chỉ thời điểm cụ thể.","ex":"我今天晚上有课。","py":"Wǒ jīntiān wǎnshang yǒu kè.","vi":"Tối nay tôi có tiết học.","en":"I have class this evening."},{"use":"今天的 + n: làm định ngữ.","ex":"今天的作业你做完了吗？","py":"Jīntiān de zuòyè nǐ zuòwán le ma?","vi":"Bài tập hôm nay bạn làm xong chưa?","en":"Have you finished today's homework?"}]},"早上":{"en":"morning; early morning","exs":[{"use":"早上 + giờ + V: chỉ thời điểm buổi sáng.","ex":"我每天早上六点起床。","py":"Wǒ měi tiān zǎoshang liù diǎn qǐchuáng.","vi":"Mỗi sáng tôi thức dậy lúc sáu giờ.","en":"I get up at six every morning."},{"use":"早上好: câu chào buổi sáng.","ex":"早上好！你吃早饭了吗？","py":"Zǎoshang hǎo! Nǐ chī zǎofàn le ma?","vi":"Chào buổi sáng! Bạn ăn sáng chưa?","en":"Good morning! Have you had breakfast?"},{"use":"今天早上: sáng nay (chỉ một sự việc đã xảy ra).","ex":"今天早上下了一场大雨。","py":"Jīntiān zǎoshang xiàle yì chǎng dà yǔ.","vi":"Sáng nay trời mưa một trận lớn.","en":"There was a heavy rain this morning."}]},"地铁站":{"en":"subway station; metro station","exs":[{"use":"Làm chủ ngữ; 离…很近: cách … rất gần.","ex":"地铁站离我家很近。","py":"Dìtiězhàn lí wǒ jiā hěn jìn.","vi":"Ga tàu điện ngầm cách nhà tôi rất gần.","en":"The subway station is very close to my home."},{"use":"在地铁站 + 门口: địa điểm hẹn gặp.","ex":"我们在地铁站门口见面吧。","py":"Wǒmen zài dìtiězhàn ménkǒu jiànmiàn ba.","vi":"Chúng ta gặp nhau ở cửa ga tàu điện ngầm nhé.","en":"Let's meet at the entrance of the subway station."},{"use":"Hỏi đường: 最近的 + 地铁站 + 在哪儿。","ex":"请问，最近的地铁站在哪儿？","py":"Qǐngwèn, zuìjìn de dìtiězhàn zài nǎr?","vi":"Xin hỏi, ga tàu điện ngầm gần nhất ở đâu?","en":"Excuse me, where is the nearest subway station?"}]},"上海":{"en":"Shanghai","exs":[{"use":"Địa danh; 去过 + địa danh: đã từng đến.","ex":"我去年去过上海。","py":"Wǒ qùnián qùguo Shànghǎi.","vi":"Năm ngoái tôi đã từng đến Thượng Hải.","en":"I visited Shanghai last year."},{"use":"……之一: một trong những…","ex":"上海是中国最大的城市之一。","py":"Shànghǎi shì Zhōngguó zuì dà de chéngshì zhī yī.","vi":"Thượng Hải là một trong những thành phố lớn nhất Trung Quốc.","en":"Shanghai is one of the largest cities in China."},{"use":"从…到…: từ … đến …; chỉ khoảng cách và thời gian di chuyển.","ex":"从北京到上海坐高铁要四个多小时。","py":"Cóng Běijīng dào Shànghǎi zuò gāotiě yào sì ge duō xiǎoshí.","vi":"Từ Bắc Kinh đến Thượng Hải đi tàu cao tốc mất hơn bốn tiếng.","en":"It takes more than four hours to go from Beijing to Shanghai by high-speed train."}]},"工作":{"en":"work; job; to work","exs":[{"use":"Động từ: 在…工作 = làm việc ở đâu.","ex":"我在一家公司工作。","py":"Wǒ zài yì jiā gōngsī gōngzuò.","vi":"Tôi làm việc ở một công ty.","en":"I work at a company."},{"use":"Danh từ: công việc; 他的工作 làm chủ ngữ.","ex":"他的工作很忙。","py":"Tā de gōngzuò hěn máng.","vi":"Công việc của anh ấy rất bận.","en":"His job is very busy."},{"use":"找工作 / 找到工作: tìm việc.","ex":"你找到工作了吗？","py":"Nǐ zhǎodào gōngzuò le ma?","vi":"Bạn tìm được việc chưa?","en":"Have you found a job yet?"},{"use":"Động từ + thời lượng: làm việc bao lâu.","ex":"他每天工作八个小时。","py":"Tā měi tiān gōngzuò bā ge xiǎoshí.","vi":"Mỗi ngày anh ấy làm việc tám tiếng.","en":"He works eight hours a day."}]},"旅游":{"en":"to travel; to tour; tourism","exs":[{"use":"Động từ: 去旅游 = đi du lịch.","ex":"我喜欢和朋友一起去旅游。","py":"Wǒ xǐhuan hé péngyou yìqǐ qù lǚyóu.","vi":"Tôi thích đi du lịch cùng bạn bè.","en":"I like traveling with friends."},{"use":"去 + địa điểm + 旅游: đi du lịch ở đâu.","ex":"暑假我们打算去云南旅游。","py":"Shǔjià wǒmen dǎsuàn qù Yúnnán lǚyóu.","vi":"Kỳ nghỉ hè chúng tôi dự định đi du lịch Vân Nam.","en":"We plan to travel to Yunnan this summer."},{"use":"旅游 làm định ngữ: 旅游城市 = thành phố du lịch.","ex":"这是一个有名的旅游城市。","py":"Zhè shì yí gè yǒumíng de lǚyóu chéngshì.","vi":"Đây là một thành phố du lịch nổi tiếng.","en":"This is a famous tourist city."}]},"麻烦":{"en":"to trouble; troublesome; trouble","exs":[{"use":"麻烦 + người + V: nhờ vả lịch sự.","ex":"麻烦你帮我拿一下行李。","py":"Máfan nǐ bāng wǒ ná yíxià xíngli.","vi":"Phiền bạn giúp tôi xách hành lý một chút.","en":"Could you please help me carry my luggage?"},{"use":"Danh từ: 添麻烦 = gây phiền phức.","ex":"对不起，给您添麻烦了。","py":"Duìbuqǐ, gěi nín tiān máfan le.","vi":"Xin lỗi, đã làm phiền ngài.","en":"Sorry to have troubled you."},{"use":"Tính từ: phiền phức, rắc rối.","ex":"办这个手续太麻烦了。","py":"Bàn zhège shǒuxù tài máfan le.","vi":"Làm thủ tục này phiền phức quá.","en":"This procedure is too much trouble."},{"use":"Động từ: 不想麻烦别人 = không muốn làm phiền người khác.","ex":"我不想麻烦别人。","py":"Wǒ bù xiǎng máfan biérén.","vi":"Tôi không muốn làm phiền người khác.","en":"I don't want to bother other people."}]},"一下":{"en":"a bit; once; for a moment","exs":[{"use":"V + 一下: làm thử một chút, nhẹ nhàng, lịch sự.","ex":"请等一下。","py":"Qǐng děng yíxià.","vi":"Xin đợi một chút.","en":"Please wait a moment."},{"use":"介绍一下: giới thiệu một chút (câu quen thuộc).","ex":"我来介绍一下，这是我的同事。","py":"Wǒ lái jièshào yíxià, zhè shì wǒ de tóngshì.","vi":"Để tôi giới thiệu một chút, đây là đồng nghiệp của tôi.","en":"Let me introduce you: this is my colleague."},{"use":"V + 一下: mời thử làm gì.","ex":"你尝一下这个菜怎么样？","py":"Nǐ cháng yíxià zhège cài zěnmeyàng?","vi":"Bạn nếm thử món này xem sao?","en":"Why don't you try this dish?"},{"use":"Động lượng từ: một lần (hành động ngắn).","ex":"他轻轻地敲了一下门。","py":"Tā qīngqīng de qiāole yíxià mén.","vi":"Anh ấy gõ nhẹ vào cửa một cái.","en":"He knocked on the door gently once."}]},"参加":{"en":"to take part in; to join; to attend","exs":[{"use":"参加 + hội nghị/hoạt động: tham dự.","ex":"你参加明天的会议吗？","py":"Nǐ cānjiā míngtiān de huìyì ma?","vi":"Ngày mai bạn có tham dự cuộc họp không?","en":"Are you attending tomorrow's meeting?"},{"use":"参加 + cuộc thi: dự thi.","ex":"我想参加汉语比赛。","py":"Wǒ xiǎng cānjiā Hànyǔ bǐsài.","vi":"Tôi muốn tham gia cuộc thi tiếng Hán.","en":"I want to take part in the Chinese competition."},{"use":"没有参加: phủ định, không tham dự.","ex":"他没有参加朋友的婚礼。","py":"Tā méiyǒu cānjiā péngyou de hūnlǐ.","vi":"Anh ấy không tham dự lễ cưới của bạn.","en":"He didn't attend his friend's wedding."}]},"聚会":{"en":"party; get-together; to get together","exs":[{"use":"Danh từ: 有一个聚会 = có một buổi họp mặt.","ex":"周末我们有一个朋友聚会。","py":"Zhōumò wǒmen yǒu yí gè péngyou jùhuì.","vi":"Cuối tuần chúng tôi có một buổi họp mặt bạn bè.","en":"We have a get-together with friends this weekend."},{"use":"参加聚会 / 生日聚会: dự tiệc.","ex":"你来参加我的生日聚会吧。","py":"Nǐ lái cānjiā wǒ de shēngrì jùhuì ba.","vi":"Bạn đến dự tiệc sinh nhật của tôi nhé.","en":"Come to my birthday party."},{"use":"Động từ: tụ họp; + số lần.","ex":"同学们每年都聚会一次。","py":"Tóngxuémen měi nián dōu jùhuì yí cì.","vi":"Các bạn học mỗi năm đều họp mặt một lần.","en":"The classmates get together once every year."}]},"门口":{"en":"doorway; entrance; gate","exs":[{"use":"在…门口: ở cửa của nơi nào.","ex":"我在学校门口等你。","py":"Wǒ zài xuéxiào ménkǒu děng nǐ.","vi":"Tôi đợi bạn ở cổng trường.","en":"I'll wait for you at the school gate."},{"use":"门口 + 有 + n: ở cửa có cái gì.","ex":"门口有一只小狗。","py":"Ménkǒu yǒu yì zhī xiǎo gǒu.","vi":"Ở cửa có một chú chó con.","en":"There is a little dog at the door."},{"use":"站在门口: đứng ở cửa.","ex":"他站在门口，不知道该不该进去。","py":"Tā zhàn zài ménkǒu, bù zhīdào gāi bu gāi jìnqù.","vi":"Anh ấy đứng ở cửa, không biết có nên vào hay không.","en":"He stood at the door, not knowing whether to go in."}]},"饭店":{"en":"restaurant; hotel","exs":[{"use":"Nghĩa 1: nhà hàng, quán ăn.","ex":"这家饭店的菜很好吃。","py":"Zhè jiā fàndiàn de cài hěn hǎochī.","vi":"Món ăn của nhà hàng này rất ngon.","en":"The food at this restaurant is delicious."},{"use":"Nghĩa 2: khách sạn (đặc biệt trong tên riêng).","ex":"我们在饭店订了一个房间。","py":"Wǒmen zài fàndiàn dìngle yí gè fángjiān.","vi":"Chúng tôi đã đặt một phòng ở khách sạn.","en":"We booked a room at the hotel."},{"use":"在…饭店 + 举行: tổ chức ở nhà hàng/khách sạn lớn.","ex":"他们的婚礼在一家大饭店举行。","py":"Tāmen de hūnlǐ zài yì jiā dà fàndiàn jǔxíng.","vi":"Lễ cưới của họ được tổ chức ở một khách sạn lớn.","en":"Their wedding was held at a big hotel."}]},"迟到":{"en":"to be late; to arrive late","exs":[{"use":"迟到了: đã đến muộn (động từ li hợp).","ex":"对不起，我迟到了。","py":"Duìbuqǐ, wǒ chídào le.","vi":"Xin lỗi, tôi đến muộn.","en":"Sorry, I'm late."},{"use":"迟到 + thời lượng: muộn bao lâu.","ex":"今天路上堵车，所以我迟到了二十分钟。","py":"Jīntiān lùshang dǔchē, suǒyǐ wǒ chídàole èrshí fēnzhōng.","vi":"Hôm nay trên đường kẹt xe nên tôi đến muộn hai mươi phút.","en":"There was a traffic jam today, so I was twenty minutes late."},{"use":"别迟到: lời dặn đừng đến muộn.","ex":"明天别迟到，会议八点开始。","py":"Míngtiān bié chídào, huìyì bā diǎn kāishǐ.","vi":"Ngày mai đừng đến muộn, cuộc họp bắt đầu lúc tám giờ.","en":"Don't be late tomorrow; the meeting starts at eight."}]},"放心":{"en":"to set one's mind at rest; to rest assured","exs":[{"use":"你放心: câu trấn an người khác.","ex":"你放心，我会照顾好他的。","py":"Nǐ fàngxīn, wǒ huì zhàogù hǎo tā de.","vi":"Bạn yên tâm, tôi sẽ chăm sóc tốt cho anh ấy.","en":"Don't worry, I'll take good care of him."},{"use":"不放心: không yên tâm (不 đọc bú trước thanh 4).","ex":"孩子一个人出门，妈妈不放心。","py":"Háizi yí gè rén chūmén, māma bú fàngxīn.","vi":"Con đi ra ngoài một mình, mẹ không yên tâm.","en":"Mom isn't at ease with the child going out alone."},{"use":"很放心: rất yên tâm (tin tưởng giao việc).","ex":"这件事交给他，我很放心。","py":"Zhè jiàn shì jiāo gěi tā, wǒ hěn fàngxīn.","vi":"Việc này giao cho anh ấy, tôi rất yên tâm.","en":"I feel completely at ease leaving this to him."}]},"照片":{"en":"photo; picture","exs":[{"use":"Lượng từ 张: 一张照片; 在…照的 = chụp ở đâu.","ex":"这张照片是在上海照的。","py":"Zhè zhāng zhàopiàn shì zài Shànghǎi zhào de.","vi":"Bức ảnh này được chụp ở Thượng Hải.","en":"This photo was taken in Shanghai."},{"use":"看照片: xem ảnh; 旧照片 = ảnh cũ.","ex":"我喜欢看旧照片。","py":"Wǒ xǐhuan kàn jiù zhàopiàn.","vi":"Tôi thích xem ảnh cũ.","en":"I like looking at old photos."},{"use":"把 + 照片 + V: câu chữ 把.","ex":"请把照片发给我。","py":"Qǐng bǎ zhàopiàn fā gěi wǒ.","vi":"Hãy gửi ảnh cho tôi.","en":"Please send the photos to me."}]},"年轻":{"en":"young","exs":[{"use":"Vị ngữ tính từ: 看起来很年轻.","ex":"她看起来很年轻。","py":"Tā kàn qǐlái hěn niánqīng.","vi":"Cô ấy trông rất trẻ.","en":"She looks very young."},{"use":"年轻人: người trẻ.","ex":"年轻人应该多学习新东西。","py":"Niánqīng rén yīnggāi duō xuéxí xīn dōngxi.","vi":"Người trẻ nên học hỏi nhiều điều mới.","en":"Young people should learn more new things."},{"use":"年轻的时候: hồi còn trẻ.","ex":"我年轻的时候喜欢旅游。","py":"Wǒ niánqīng de shíhou xǐhuan lǚyóu.","vi":"Hồi còn trẻ tôi thích đi du lịch.","en":"I loved traveling when I was young."}]},"大学":{"en":"university; college","exs":[{"use":"上大学: học đại học.","ex":"他在北京上大学。","py":"Tā zài Běijīng shàng dàxué.","vi":"Anh ấy học đại học ở Bắc Kinh.","en":"He studies at a university in Beijing."},{"use":"我们大学: trường đại học của chúng tôi.","ex":"我们大学离市中心不远。","py":"Wǒmen dàxué lí shì zhōngxīn bù yuǎn.","vi":"Trường đại học của chúng tôi cách trung tâm thành phố không xa.","en":"Our university isn't far from the city center."},{"use":"大学毕业后: sau khi tốt nghiệp đại học.","ex":"大学毕业后她去了国外。","py":"Dàxué bìyè hòu tā qùle guówài.","vi":"Sau khi tốt nghiệp đại học, cô ấy ra nước ngoài.","en":"After graduating from university she went abroad."}]},"过去":{"en":"past; to go over; to pass","exs":[{"use":"Làm danh từ chỉ thời gian đã qua; cũng có thể là động từ 'đi qua'.","ex":"过去的事情就让它过去吧。","py":"Guòqù de shìqing jiù ràng tā guòqù ba.","vi":"Chuyện đã qua thì hãy để nó qua đi.","en":"Let the past be the past."},{"use":"过去 + mệnh đề: trước đây (đối lập với 现在).","ex":"过去他不喜欢运动，现在天天跑步。","py":"Guòqù tā bù xǐhuan yùndòng, xiànzài tiāntiān pǎobù.","vi":"Trước đây anh ấy không thích thể thao, bây giờ ngày nào cũng chạy bộ.","en":"He didn't like sports in the past, but now he runs every day."},{"use":"Động từ: đi qua, sang phía bên kia (xa người nói).","ex":"他从我身边走过去了。","py":"Tā cóng wǒ shēnbiān zǒu guòqù le.","vi":"Anh ấy đi ngang qua bên cạnh tôi.","en":"He walked past me."},{"use":"Động từ: thời gian trôi qua.","ex":"夏天很快就过去了。","py":"Xiàtiān hěn kuài jiù guòqù le.","vi":"Mùa hè nhanh chóng trôi qua.","en":"Summer passed very quickly."}]},"日子":{"en":"day; days; life","exs":[{"use":"Nghĩa: cuộc sống, những ngày tháng.","ex":"最近的日子过得很快乐。","py":"Zuìjìn de rìzi guò de hěn kuàilè.","vi":"Dạo này tôi sống rất vui vẻ.","en":"I've been having a happy time lately."},{"use":"Nghĩa: ngày (dịp) đặc biệt: 好日子.","ex":"今天是个好日子，他们结婚了。","py":"Jīntiān shì ge hǎo rìzi, tāmen jiéhūn le.","vi":"Hôm nay là ngày đẹp, họ làm đám cưới.","en":"Today is a lucky day; they got married."},{"use":"日子 làm chủ ngữ: 越来越好 = ngày càng tốt hơn.","ex":"我们的日子越来越好了。","py":"Wǒmen de rìzi yuè lái yuè hǎo le.","vi":"Cuộc sống của chúng ta ngày càng tốt hơn.","en":"Our lives are getting better and better."}]},"好像":{"en":"to seem; to be like; as if","exs":[{"use":"好像 + mệnh đề: hình như, suy đoán.","ex":"他好像生病了。","py":"Tā hǎoxiàng shēngbìng le.","vi":"Hình như anh ấy bị bệnh rồi.","en":"He seems to be sick."},{"use":"好像 + V + 过: hình như đã từng.","ex":"这个字我好像见过。","py":"Zhège zì wǒ hǎoxiàng jiànguo.","vi":"Chữ này hình như tôi đã từng thấy.","en":"I feel like I've seen this character before."},{"use":"好像…一样: giống như…","ex":"她高兴得好像孩子一样。","py":"Tā gāoxìng de hǎoxiàng háizi yíyàng.","vi":"Cô ấy vui như một đứa trẻ.","en":"She is as happy as a child."},{"use":"好像 + hiện tượng thời tiết: có vẻ như.","ex":"外面好像下雨了。","py":"Wàimiàn hǎoxiàng xià yǔ le.","vi":"Bên ngoài hình như trời mưa rồi.","en":"It seems to be raining outside."}]},"重新":{"en":"anew; again; afresh","exs":[{"use":"重新 + V: làm lại từ đầu.","ex":"我想重新开始。","py":"Wǒ xiǎng chóngxīn kāishǐ.","vi":"Tôi muốn bắt đầu lại.","en":"I want to start over."},{"use":"重新 + V + 一遍: làm lại một lượt.","ex":"文件丢了，我只好重新写一遍。","py":"Wénjiàn diū le, wǒ zhǐhǎo chóngxīn xiě yí biàn.","vi":"Tài liệu bị mất, tôi đành viết lại một lượt.","en":"The file was lost, so I had to write it again."},{"use":"重新 + V + 了 + n: lại tìm/làm cái khác.","ex":"他重新找了一份工作。","py":"Tā chóngxīn zhǎole yí fèn gōngzuò.","vi":"Anh ấy lại tìm một công việc mới.","en":"He found himself another job."}]},"回到":{"en":"to return to; to go back to","exs":[{"use":"回到 + nơi chốn: trở về đến đâu.","ex":"他下午三点回到了公司。","py":"Tā xiàwǔ sān diǎn huídàole gōngsī.","vi":"Ba giờ chiều anh ấy đã trở về công ty.","en":"He got back to the office at three in the afternoon."},{"use":"什么时候能回到…: hỏi bao giờ về tới.","ex":"我们什么时候能回到家？","py":"Wǒmen shénme shíhou néng huídào jiā?","vi":"Khi nào chúng ta mới về tới nhà?","en":"When will we get home?"},{"use":"Nghĩa bóng: quay lại chủ đề, vấn đề.","ex":"说了半天，又回到了原来的问题。","py":"Shuōle bàntiān, yòu huídàole yuánlái de wèntí.","vi":"Nói mãi rồi lại quay về vấn đề ban đầu.","en":"After talking for ages, we came back to the original problem."}]},"校园":{"en":"campus; school grounds","exs":[{"use":"Làm chủ ngữ miêu tả khuôn viên trường.","ex":"我们的校园很大，也很漂亮。","py":"Wǒmen de xiàoyuán hěn dà, yě hěn piàoliang.","vi":"Khuôn viên trường chúng tôi vừa rộng vừa đẹp.","en":"Our campus is big and beautiful."},{"use":"在校园里 + V: ở trong khuôn viên trường.","ex":"他喜欢在校园里散步。","py":"Tā xǐhuan zài xiàoyuán lǐ sànbù.","vi":"Anh ấy thích đi dạo trong khuôn viên trường.","en":"He likes to take walks on campus."},{"use":"校园生活: cuộc sống học đường.","ex":"我很喜欢快乐的校园生活。","py":"Wǒ hěn xǐhuan kuàilè de xiàoyuán shēnghuó.","vi":"Tôi rất thích cuộc sống học đường vui vẻ.","en":"I really enjoy the happy campus life."}]},"旁边":{"en":"beside; next to; side","exs":[{"use":"A 在 B 旁边: A ở cạnh B.","ex":"银行在超市旁边。","py":"Yínháng zài chāoshì pángbiān.","vi":"Ngân hàng ở cạnh siêu thị.","en":"The bank is next to the supermarket."},{"use":"旁边 + V着 + n: bên cạnh có ai ngồi/đứng.","ex":"我旁边坐着一位老人。","py":"Wǒ pángbiān zuòzhe yí wèi lǎorén.","vi":"Bên cạnh tôi có một cụ già đang ngồi.","en":"An old man is sitting beside me."},{"use":"旁边的 + n: làm định ngữ.","ex":"请问，旁边的座位有人吗？","py":"Qǐngwèn, pángbiān de zuòwèi yǒu rén ma?","vi":"Xin hỏi, chỗ ngồi bên cạnh có người ngồi chưa?","en":"Excuse me, is the seat next to you taken?"}]},"尽管":{"en":"although; even though; feel free to","exs":[{"use":"尽管…但是 / 还是…","ex":"尽管很累，他还是坚持工作。","py":"Jǐnguǎn hěn lèi, tā háishi jiānchí gōngzuò.","vi":"Mặc dù rất mệt, anh ấy vẫn kiên trì làm việc.","en":"Although he was tired, he still kept working."},{"use":"尽管…却…: tuy… nhưng (kết quả trái mong đợi).","ex":"尽管他很努力，成绩却不太理想。","py":"Jǐnguǎn tā hěn nǔlì, chéngjì què bú tài lǐxiǎng.","vi":"Tuy anh ấy rất nỗ lực nhưng thành tích lại không lý tưởng lắm.","en":"Although he works hard, his grades aren't very good."},{"use":"尽管 + 还是: dù thời tiết xấu vẫn làm.","ex":"尽管天气不好，我们还是去爬山了。","py":"Jǐnguǎn tiānqì bù hǎo, wǒmen háishi qù páshān le.","vi":"Dù thời tiết không tốt, chúng tôi vẫn đi leo núi.","en":"Even though the weather was bad, we still went hiking."},{"use":"Phó từ: 尽管 + V = cứ việc, đừng ngại.","ex":"有问题尽管问，不要客气。","py":"Yǒu wèntí jǐnguǎn wèn, búyào kèqi.","vi":"Có vấn đề gì cứ hỏi, đừng khách sáo.","en":"If you have questions, go ahead and ask; don't be shy."}]},"已经":{"en":"already","exs":[{"use":"已经 + V + 过/了: đã làm xong.","ex":"我已经吃过饭了。","py":"Wǒ yǐjīng chīguo fàn le.","vi":"Tôi đã ăn cơm rồi.","en":"I have already eaten."},{"use":"已经 + giờ + 了: đã đến giờ nào.","ex":"现在已经十点了，快睡觉吧。","py":"Xiànzài yǐjīng shí diǎn le, kuài shuìjiào ba.","vi":"Bây giờ đã mười giờ rồi, mau đi ngủ đi.","en":"It's already ten o'clock; go to bed."},{"use":"已经不…了: không còn… nữa.","ex":"他已经不住在这儿了。","py":"Tā yǐjīng bú zhù zài zhèr le.","vi":"Anh ấy không còn sống ở đây nữa.","en":"He doesn't live here anymore."}]},"还是":{"en":"or; still; had better","exs":[{"use":"Liên từ: A 还是 B, dùng trong câu hỏi lựa chọn.","ex":"你喝茶还是喝咖啡？","py":"Nǐ hē chá háishi hē kāfēi?","vi":"Bạn uống trà hay uống cà phê?","en":"Would you like tea or coffee?"},{"use":"是 A 还是 B: hỏi chọn một trong hai.","ex":"你是学生还是老师？","py":"Nǐ shì xuésheng háishi lǎoshī?","vi":"Bạn là học sinh hay là giáo viên?","en":"Are you a student or a teacher?"},{"use":"还是 + V + 吧: nên… thì hơn (đưa ra lời khuyên).","ex":"外面太冷了，你还是穿厚一点儿吧。","py":"Wàimiàn tài lěng le, nǐ háishi chuān hòu yìdiǎnr ba.","vi":"Bên ngoài lạnh quá, bạn mặc dày một chút thì hơn.","en":"It's too cold outside; you'd better wear something thicker."},{"use":"Phó từ: vẫn, vẫn như cũ.","ex":"十年了，他还是那么年轻。","py":"Shí nián le, tā háishi nàme niánqīng.","vi":"Mười năm rồi, anh ấy vẫn trẻ như vậy.","en":"Ten years on, he is still as young as ever."}]},"每次":{"en":"every time; each time","exs":[{"use":"每次 + V, 都 + V: lần nào cũng.","ex":"每次见面，他都带来一份小礼物。","py":"Měicì jiànmiàn, tā dōu dàilái yí fèn xiǎo lǐwù.","vi":"Mỗi lần gặp, anh ấy đều mang đến một món quà nhỏ.","en":"Every time we meet, he brings a small gift."},{"use":"Chủ ngữ + 每次 + V + 都 + …","ex":"我每次去那家店都买咖啡。","py":"Wǒ měicì qù nà jiā diàn dōu mǎi kāfēi.","vi":"Mỗi lần đến tiệm đó tôi đều mua cà phê.","en":"Every time I go to that shop, I buy coffee."},{"use":"每次 + sự kiện + 前/后: mỗi lần trước/sau khi.","ex":"每次考试前，我都很紧张。","py":"Měicì kǎoshì qián, wǒ dōu hěn jǐnzhāng.","vi":"Mỗi lần trước kỳ thi, tôi đều rất hồi hộp.","en":"I get nervous before every exam."}]},"南方":{"en":"south; the south; southern China","exs":[{"use":"南方人: người miền Nam; đối lập với 北方.","ex":"他是南方人，不太习惯北方的冬天。","py":"Tā shì nánfāng rén, bú tài xíguàn běifāng de dōngtiān.","vi":"Anh ấy là người miền Nam, không quen lắm với mùa đông miền Bắc.","en":"He is from the south and isn't used to northern winters."},{"use":"南方的 + n: làm định ngữ.","ex":"南方的夏天又热又湿。","py":"Nánfāng de xiàtiān yòu rè yòu shī.","vi":"Mùa hè ở miền Nam vừa nóng vừa ẩm.","en":"Summers in the south are hot and humid."},{"use":"去南方 + V: đi về phương Nam.","ex":"冬天很多北方人喜欢去南方旅游。","py":"Dōngtiān hěn duō běifāng rén xǐhuan qù nánfāng lǚyóu.","vi":"Mùa đông nhiều người miền Bắc thích đi du lịch miền Nam.","en":"In winter many northerners like to travel to the south."}]},"一会儿":{"en":"a little while; a moment; shortly","exs":[{"use":"V + 一会儿: làm trong một lúc ngắn.","ex":"你等我一会儿。","py":"Nǐ děng wǒ yíhuìr.","vi":"Bạn đợi tôi một lát.","en":"Wait for me for a moment."},{"use":"一会儿 + 就 + V: lát nữa sẽ…","ex":"我一会儿就回来。","py":"Wǒ yíhuìr jiù huílái.","vi":"Lát nữa tôi sẽ về ngay.","en":"I'll be back in a moment."},{"use":"V + 了 + 一会儿: đã làm một lúc (quá khứ).","ex":"他看了一会儿电视就去睡觉了。","py":"Tā kànle yíhuìr diànshì jiù qù shuìjiào le.","vi":"Anh ấy xem tivi một lúc rồi đi ngủ.","en":"He watched TV for a while and then went to bed."},{"use":"一会儿…一会儿…: lúc thì… lúc thì…","ex":"一会儿下雨，一会儿出太阳。","py":"Yíhuìr xià yǔ, yíhuìr chū tàiyáng.","vi":"Lúc thì mưa, lúc thì có nắng.","en":"One moment it rains, the next the sun comes out."}]},"电话":{"en":"telephone; phone call","exs":[{"use":"打电话: gọi điện; 给…打电话.","ex":"我给妈妈打了一个电话。","py":"Wǒ gěi māma dǎle yí gè diànhuà.","vi":"Tôi đã gọi điện cho mẹ.","en":"I made a phone call to my mom."},{"use":"电话号码: số điện thoại.","ex":"你的电话号码是多少？","py":"Nǐ de diànhuà hàomǎ shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?","en":"What is your phone number?"},{"use":"电话响了 / 接电话: chuông reo / nghe máy.","ex":"电话响了，你快去接。","py":"Diànhuà xiǎng le, nǐ kuài qù jiē.","vi":"Điện thoại reo rồi, bạn mau đi nghe đi.","en":"The phone is ringing; go answer it."},{"use":"在电话里 + V: nói trong điện thoại.","ex":"他在电话里说他会晚点到。","py":"Tā zài diànhuà lǐ shuō tā huì wǎn diǎn dào.","vi":"Anh ấy nói qua điện thoại là sẽ đến muộn một chút.","en":"He said on the phone that he would be a bit late."}]},"知道":{"en":"to know; to be aware of","exs":[{"use":"不知道 + từ nghi vấn: không biết…","ex":"我不知道他住在哪儿。","py":"Wǒ bù zhīdào tā zhù zài nǎr.","vi":"Tôi không biết anh ấy sống ở đâu.","en":"I don't know where he lives."},{"use":"知道 + 吗: hỏi có biết không.","ex":"你知道这家饭店怎么走吗？","py":"Nǐ zhīdào zhè jiā fàndiàn zěnme zǒu ma?","vi":"Bạn có biết đi đến nhà hàng này thế nào không?","en":"Do you know how to get to this restaurant?"},{"use":"谁都知道: ai cũng biết.","ex":"谁都知道健康很重要。","py":"Shéi dōu zhīdào jiànkāng hěn zhòngyào.","vi":"Ai cũng biết sức khỏe rất quan trọng.","en":"Everybody knows health is important."},{"use":"知道了: tôi hiểu rồi, đã biết.","ex":"我知道了，谢谢你。","py":"Wǒ zhīdào le, xièxie nǐ.","vi":"Tôi biết rồi, cảm ơn bạn.","en":"Got it, thank you."}]},"友谊":{"en":"friendship","exs":[{"use":"Làm chủ ngữ: 友谊 + 有 + thời gian.","ex":"我们的友谊已经有十年了。","py":"Wǒmen de yǒuyì yǐjīng yǒu shí nián le.","vi":"Tình bạn của chúng tôi đã mười năm rồi.","en":"Our friendship goes back ten years."},{"use":"建立友谊: xây dựng tình bạn.","ex":"他们在学校里建立了深厚的友谊。","py":"Tāmen zài xuéxiào lǐ jiànlìle shēnhòu de yǒuyì.","vi":"Họ đã xây dựng tình bạn sâu đậm ở trường.","en":"They built a deep friendship at school."},{"use":"So sánh: A 比 B 更 + adj.","ex":"友谊比金钱更重要。","py":"Yǒuyì bǐ jīnqián gèng zhòngyào.","vi":"Tình bạn quan trọng hơn tiền bạc.","en":"Friendship is more important than money."},{"use":"为…干杯: nâng ly chúc mừng.","ex":"为我们的友谊干杯！","py":"Wèi wǒmen de yǒuyì gānbēi!","vi":"Nâng ly vì tình bạn của chúng ta!","en":"Cheers to our friendship!"}]},"多么":{"en":"how; what; however","exs":[{"use":"Dùng trong câu cảm thán để nhấn mạnh mức độ.","ex":"健康是多么重要啊！","py":"Jiànkāng shì duōme zhòngyào a!","vi":"Sức khỏe quan trọng biết bao!","en":"How important health is!"},{"use":"多么 + adj + 啊: cảm thán về cảnh vật.","ex":"这里的风景多么美啊！","py":"Zhèlǐ de fēngjǐng duōme měi a!","vi":"Phong cảnh ở đây đẹp biết bao!","en":"How beautiful the scenery is here!"},{"use":"多么 + động từ tâm lý: biết bao.","ex":"你不知道我多么想家。","py":"Nǐ bù zhīdào wǒ duōme xiǎng jiā.","vi":"Bạn không biết tôi nhớ nhà đến nhường nào.","en":"You don't know how much I miss home."},{"use":"不管多么…都…: dù … đến đâu cũng …","ex":"不管多么忙，他每天都锻炼。","py":"Bùguǎn duōme máng, tā měi tiān dōu duànliàn.","vi":"Dù bận đến mấy, ngày nào anh ấy cũng tập thể dục.","en":"No matter how busy he is, he exercises every day."}]},"面试":{"en":"interview; to interview","exs":[{"use":"Danh từ: 有一个面试; 参加面试 = tham gia phỏng vấn.","ex":"明天我有一个面试。","py":"Míngtiān wǒ yǒu yí gè miànshì.","vi":"Ngày mai tôi có một buổi phỏng vấn.","en":"I have an interview tomorrow."},{"use":"Động từ: đi phỏng vấn ở công ty nào.","ex":"我下周去那家公司面试。","py":"Wǒ xià zhōu qù nà jiā gōngsī miànshì.","vi":"Tuần sau tôi đến công ty đó phỏng vấn.","en":"I'm going to that company for an interview next week."},{"use":"面试的时候: khi phỏng vấn.","ex":"面试的时候不要紧张。","py":"Miànshì de shíhou búyào jǐnzhāng.","vi":"Khi phỏng vấn đừng căng thẳng.","en":"Don't be nervous during the interview."},{"use":"面试通过: phỏng vấn đạt.","ex":"他面试通过了，下个月开始上班。","py":"Tā miànshì tōngguò le, xià gè yuè kāishǐ shàngbān.","vi":"Anh ấy đã qua phỏng vấn, tháng sau bắt đầu đi làm.","en":"He passed the interview and starts work next month."}]},"经理":{"en":"manager; director","exs":[{"use":"Có thể đứng sau họ: 马经理.","ex":"经理正在开会。","py":"Jīnglǐ zhèngzài kāihuì.","vi":"Giám đốc đang họp.","en":"The manager is in a meeting."},{"use":"Họ + 经理: cách xưng hô.","ex":"王经理，这是您要的文件。","py":"Wáng jīnglǐ, zhè shì nín yào de wénjiàn.","vi":"Giám đốc Vương, đây là tài liệu ngài cần.","en":"Manager Wang, here is the document you wanted."},{"use":"Chức vụ + 经理: 销售经理 = giám đốc kinh doanh.","ex":"他是我们公司的销售经理。","py":"Tā shì wǒmen gōngsī de xiāoshòu jīnglǐ.","vi":"Anh ấy là giám đốc kinh doanh của công ty chúng tôi.","en":"He is our company's sales manager."},{"use":"经理的 + n: làm định ngữ.","ex":"我要先问问经理的意见。","py":"Wǒ yào xiān wènwen jīnglǐ de yìjiàn.","vi":"Tôi phải hỏi ý kiến của giám đốc trước.","en":"I need to ask the manager's opinion first."}]},"通知":{"en":"to notify; notice; notification","exs":[{"use":"通知 + người + việc.","ex":"学校通知我们明天放假。","py":"Xuéxiào tōngzhī wǒmen míngtiān fàngjià.","vi":"Nhà trường thông báo ngày mai chúng tôi được nghỉ.","en":"The school notified us that we have a day off tomorrow."},{"use":"Danh từ: 面试通知 = giấy mời phỏng vấn.","ex":"我收到了面试通知。","py":"Wǒ shōudàole miànshì tōngzhī.","vi":"Tôi đã nhận được thông báo phỏng vấn.","en":"I received the interview notice."},{"use":"通知一下 + người: báo cho ai biết.","ex":"开会时间改了，请你通知一下大家。","py":"Kāihuì shíjiān gǎi le, qǐng nǐ tōngzhī yíxià dàjiā.","vi":"Giờ họp đã đổi, nhờ bạn báo cho mọi người biết.","en":"The meeting time has changed; please let everyone know."},{"use":"Danh từ: 发通知 / 新通知.","ex":"学校发了一个新通知。","py":"Xuéxiào fāle yí gè xīn tōngzhī.","vi":"Nhà trường đã đưa ra một thông báo mới.","en":"The school issued a new notice."}]},"顺利":{"en":"smooth; smoothly; successful","exs":[{"use":"Thường dùng trong lời chúc: 一切顺利.","ex":"祝你工作顺利。","py":"Zhù nǐ gōngzuò shùnlì.","vi":"Chúc bạn công việc thuận lợi.","en":"Wishing you success at work."},{"use":"Vị ngữ: 很顺利.","ex":"这次旅行很顺利。","py":"Zhè cì lǚxíng hěn shùnlì.","vi":"Chuyến du lịch lần này rất suôn sẻ.","en":"The trip went very smoothly."},{"use":"顺利地 + V: làm trạng ngữ.","ex":"他顺利地通过了面试。","py":"Tā shùnlì de tōngguòle miànshì.","vi":"Anh ấy đã vượt qua phỏng vấn một cách thuận lợi.","en":"He passed the interview smoothly."},{"use":"V + 得很顺利: bổ ngữ trạng thái.","ex":"手术进行得很顺利。","py":"Shǒushù jìnxíng de hěn shùnlì.","vi":"Ca phẫu thuật diễn ra rất thuận lợi.","en":"The operation went very well."}]},"注意":{"en":"to pay attention to; to be careful; to notice","exs":[{"use":"注意 + sự việc.","ex":"过马路要注意安全。","py":"Guò mǎlù yào zhùyì ānquán.","vi":"Qua đường phải chú ý an toàn.","en":"Be careful about safety when crossing the road."},{"use":"Thường dùng: 注意 + động từ / danh từ; 注意安全.","ex":"请注意听老师说。","py":"Qǐng zhùyì tīng lǎoshī shuō.","vi":"Hãy chú ý nghe thầy giáo nói.","en":"Please pay attention to what the teacher says."},{"use":"注意身体: giữ gìn sức khỏe.","ex":"天气冷了，大家要注意身体。","py":"Tiānqì lěng le, dàjiā yào zhùyì shēntǐ.","vi":"Trời lạnh rồi, mọi người nhớ giữ gìn sức khỏe.","en":"It's getting cold; everyone take care of your health."},{"use":"注意到: nhận ra, để ý thấy.","ex":"我没注意到他已经走了。","py":"Wǒ méi zhùyì dào tā yǐjīng zǒu le.","vi":"Tôi không để ý là anh ấy đã đi rồi.","en":"I didn't notice that he had already left."}]},"首先":{"en":"first; first of all","exs":[{"use":"Dùng mở đầu liệt kê: 首先…其次…最后…","ex":"首先，我想感谢大家。","py":"Shǒuxiān, wǒ xiǎng gǎnxiè dàjiā.","vi":"Trước hết, tôi muốn cảm ơn mọi người.","en":"First of all, I'd like to thank everyone."},{"use":"Đi với 其次、最后.","ex":"首先，我们看看原因。","py":"Shǒuxiān, wǒmen kànkan yuányīn.","vi":"Trước hết, chúng ta hãy xem nguyên nhân.","en":"First, let's look at the cause."},{"use":"首先 + 要 + V: bước đầu tiên trong cách làm.","ex":"做这道菜，首先要把肉洗干净。","py":"Zuò zhè dào cài, shǒuxiān yào bǎ ròu xǐ gānjìng.","vi":"Làm món này, trước hết phải rửa sạch thịt.","en":"To make this dish, first wash the meat clean."},{"use":"首先 + 要 + V: ưu tiên việc đầu tiên.","ex":"到了新城市，首先要找房子。","py":"Dàole xīn chéngshì, shǒuxiān yào zhǎo fángzi.","vi":"Đến thành phố mới, việc đầu tiên là tìm nhà.","en":"When you arrive in a new city, first you need to find a place to live."}]},"正式":{"en":"formal; official; officially","exs":[{"use":"正式 + danh từ / 很正式.","ex":"这是一个很正式的会议。","py":"Zhè shì yí gè hěn zhèngshì de huìyì.","vi":"Đây là một cuộc họp rất trang trọng.","en":"This is a very formal meeting."},{"use":"Phó từ: 正式 + V = chính thức làm gì.","ex":"新同事下个星期正式上班。","py":"Xīn tóngshì xià gè xīngqī zhèngshì shàngbān.","vi":"Đồng nghiệp mới tuần sau chính thức đi làm.","en":"The new colleague officially starts work next week."},{"use":"V + 得 + 正式: ăn mặc trang trọng.","ex":"参加面试要穿得正式一点儿。","py":"Cānjiā miànshì yào chuān de zhèngshì yìdiǎnr.","vi":"Đi phỏng vấn nên ăn mặc trang trọng một chút.","en":"You should dress more formally for an interview."},{"use":"还没有正式 + V: chưa chính thức.","ex":"这个决定还没有正式通知我们。","py":"Zhège juédìng hái méiyǒu zhèngshì tōngzhī wǒmen.","vi":"Quyết định này vẫn chưa được thông báo chính thức cho chúng tôi.","en":"This decision hasn't been officially announced to us yet."}]},"认真":{"en":"serious; earnest; conscientious","exs":[{"use":"认真 + động từ / 认真地 + động từ.","ex":"他学习很认真。","py":"Tā xuéxí hěn rènzhēn.","vi":"Anh ấy học hành rất nghiêm túc.","en":"He studies very seriously."},{"use":"要认真 + V: phải nghiêm túc làm gì.","ex":"我们要认真学习。","py":"Wǒmen yào rènzhēn xuéxí.","vi":"Chúng ta phải học nghiêm túc.","en":"We must study conscientiously."},{"use":"做事认真: tính cách làm việc cẩn thận.","ex":"他做事一向很认真。","py":"Tā zuòshì yíxiàng hěn rènzhēn.","vi":"Anh ấy làm việc lúc nào cũng rất nghiêm túc.","en":"He has always been serious about his work."},{"use":"认真地 + V: làm trạng ngữ.","ex":"请你认真地想一想。","py":"Qǐng nǐ rènzhēn de xiǎng yi xiǎng.","vi":"Mời bạn suy nghĩ cho nghiêm túc.","en":"Please think about it seriously."},{"use":"是认真的: nói/làm thật chứ không đùa.","ex":"我不是开玩笑，我是认真的。","py":"Wǒ bú shì kāiwánxiào, wǒ shì rènzhēn de.","vi":"Tôi không đùa đâu, tôi nói thật đấy.","en":"I'm not joking; I'm serious."}]},"其次":{"en":"next; secondly; second","exs":[{"use":"Đi sau 首先 khi liệt kê ý.","ex":"其次，我们要注意时间。","py":"Qícì, wǒmen yào zhùyì shíjiān.","vi":"Thứ đến, chúng ta cần chú ý thời gian.","en":"Next, we need to pay attention to time."},{"use":"Liệt kê ý thứ hai.","ex":"其次，要注意安全。","py":"Qícì, yào zhùyì ānquán.","vi":"Thứ hai, cần chú ý an toàn.","en":"Second, we need to be careful about safety."},{"use":"首先…，其次…: cặp liệt kê.","ex":"学好汉语，首先要多说，其次要多听。","py":"Xuéhǎo Hànyǔ, shǒuxiān yào duō shuō, qícì yào duō tīng.","vi":"Muốn học giỏi tiếng Hán, trước hết phải nói nhiều, tiếp đến phải nghe nhiều.","en":"To learn Chinese well, first speak a lot, and second listen a lot."},{"use":"其次是…: xếp sau về mức độ quan trọng.","ex":"这家店最大的优点是便宜，其次是服务好。","py":"Zhè jiā diàn zuì dà de yōudiǎn shì piányi, qícì shì fúwù hǎo.","vi":"Ưu điểm lớn nhất của tiệm này là rẻ, kế đến là phục vụ tốt.","en":"This shop's biggest advantage is low prices, followed by good service."}]},"应聘":{"en":"to apply for a job","exs":[{"use":"应聘 + vị trí / công ty.","ex":"她去一家公司应聘。","py":"Tā qù yì jiā gōngsī yìngpìn.","vi":"Cô ấy đến một công ty để ứng tuyển.","en":"She went to a company to apply for a job."},{"use":"应聘 + một công việc cụ thể.","ex":"我打算应聘一份老师的工作。","py":"Wǒ dǎsuàn yìngpìn yí fèn lǎoshī de gōngzuò.","vi":"Tôi định ứng tuyển vào một công việc giáo viên.","en":"I plan to apply for a teaching job."},{"use":"来应聘: đến ứng tuyển.","ex":"今天有三十多个人来应聘。","py":"Jīntiān yǒu sānshí duō gè rén lái yìngpìn.","vi":"Hôm nay có hơn ba mươi người đến ứng tuyển.","en":"More than thirty people came to apply today."},{"use":"应聘时: khi ứng tuyển; 简历 = sơ yếu lý lịch.","ex":"应聘时要带上你的简历。","py":"Yìngpìn shí yào dàishang nǐ de jiǎnlì.","vi":"Khi ứng tuyển nhớ mang theo sơ yếu lý lịch của bạn.","en":"Bring your résumé when you apply."}]},"紧张":{"en":"nervous; tense; busy; in short supply","exs":[{"use":"Chỉ tâm trạng: hồi hộp, lo lắng.","ex":"考试前我有点儿紧张。","py":"Kǎoshì qián wǒ yǒudiǎnr jǐnzhāng.","vi":"Trước kỳ thi tôi hơi hồi hộp.","en":"I'm a bit nervous before the exam."},{"use":"Chỉ công việc dồn dập, bận rộn.","ex":"最近工作很紧张。","py":"Zuìjìn gōngzuò hěn jǐnzhāng.","vi":"Dạo này công việc rất bận rộn.","en":"Work has been very hectic lately."},{"use":"大家都很紧张: mọi người đều căng thẳng.","ex":"比赛马上开始了，大家都很紧张。","py":"Bǐsài mǎshàng kāishǐ le, dàjiā dōu hěn jǐnzhāng.","vi":"Cuộc thi sắp bắt đầu, mọi người đều rất căng thẳng.","en":"The match is about to start and everyone is nervous."},{"use":"别紧张: lời an ủi.","ex":"别紧张，慢慢说。","py":"Bié jǐnzhāng, màn man shuō.","vi":"Đừng căng thẳng, cứ nói từ từ.","en":"Don't be nervous; take your time."},{"use":"时间紧张: thời gian eo hẹp.","ex":"这个月时间很紧张，我们得加班。","py":"Zhège yuè shíjiān hěn jǐnzhāng, wǒmen děi jiābān.","vi":"Tháng này thời gian rất gấp, chúng ta phải tăng ca.","en":"Time is tight this month, so we have to work overtime."}]},"声音":{"en":"sound; voice; noise","exs":[{"use":"声音大 / 声音小.","ex":"请把声音放小一点儿。","py":"Qǐng bǎ shēngyīn fàng xiǎo yìdiǎnr.","vi":"Xin hạ âm lượng nhỏ một chút.","en":"Please turn the volume down a bit."},{"use":"Nghĩa: âm thanh: 听到…的声音.","ex":"我听到外面有奇怪的声音。","py":"Wǒ tīngdào wàimiàn yǒu qíguài de shēngyīn.","vi":"Tôi nghe thấy bên ngoài có tiếng động lạ.","en":"I heard a strange noise outside."},{"use":"Nghĩa: giọng nói: 声音好听.","ex":"她的声音很好听，唱歌也很好。","py":"Tā de shēngyīn hěn hǎotīng, chànggē yě hěn hǎo.","vi":"Giọng cô ấy rất hay, hát cũng rất giỏi.","en":"Her voice is lovely, and she sings well too."},{"use":"声音太小: nói nhỏ quá, nghe không rõ.","ex":"你说话的声音太小了，我听不清楚。","py":"Nǐ shuōhuà de shēngyīn tài xiǎo le, wǒ tīng bu qīngchu.","vi":"Giọng bạn nhỏ quá, tôi nghe không rõ.","en":"Your voice is too quiet; I can't hear you clearly."}]},"能力":{"en":"ability; capability; competence","exs":[{"use":"有能力 + động từ.","ex":"他的工作能力很强。","py":"Tā de gōngzuò nénglì hěn qiáng.","vi":"Năng lực làm việc của anh ấy rất mạnh.","en":"His work ability is very strong."},{"use":"有能力 + V: có khả năng làm gì.","ex":"我相信他有能力做好这份工作。","py":"Wǒ xiāngxìn tā yǒu nénglì zuòhǎo zhè fèn gōngzuò.","vi":"Tôi tin anh ấy có khả năng làm tốt công việc này.","en":"I believe he is capable of doing this job well."},{"use":"提高…能力: nâng cao năng lực.","ex":"多练习可以提高你的说话能力。","py":"Duō liànxí kěyǐ tígāo nǐ de shuōhuà nénglì.","vi":"Luyện tập nhiều có thể nâng cao khả năng nói của bạn.","en":"More practice can improve your speaking ability."},{"use":"能力很强: giỏi giang.","ex":"这个年轻人能力很强，大家都喜欢他。","py":"Zhège niánqīng rén nénglì hěn qiáng, dàjiā dōu xǐhuan tā.","vi":"Chàng trai trẻ này rất có năng lực, ai cũng quý anh ấy.","en":"This young man is very capable and everyone likes him."}]},"诚实":{"en":"honest","exs":[{"use":"Miêu tả phẩm chất con người.","ex":"做人要诚实。","py":"Zuò rén yào chéngshí.","vi":"Làm người phải thành thật.","en":"One should be honest."},{"use":"诚实的 + danh từ.","ex":"他是个诚实的人。","py":"Tā shì ge chéngshí de rén.","vi":"Anh ấy là một người thành thật.","en":"He is an honest person."},{"use":"学会诚实: giáo dục trẻ thành thật.","ex":"孩子应该从小学会诚实。","py":"Háizi yīnggāi cóngxiǎo xuéhuì chéngshí.","vi":"Trẻ em nên học tính thành thật từ nhỏ.","en":"Children should learn honesty from an early age."},{"use":"很诚实, 从来不…: miêu tả tính cách.","ex":"他很诚实，从来不骗人。","py":"Tā hěn chéngshí, cónglái bú piàn rén.","vi":"Anh ấy rất thành thật, chưa bao giờ lừa người.","en":"He is very honest and never lies to people."},{"use":"诚实地 + V: làm trạng ngữ.","ex":"请你诚实地回答我的问题。","py":"Qǐng nǐ chéngshí de huídá wǒ de wèntí.","vi":"Xin bạn trả lời câu hỏi của tôi một cách thành thật.","en":"Please answer my question honestly."}]},"影响":{"en":"to influence; to affect; influence; effect","exs":[{"use":"影响 + người / sự việc; 对…有影响.","ex":"天气会影响心情。","py":"Tiānqì huì yǐngxiǎng xīnqíng.","vi":"Thời tiết có thể ảnh hưởng tâm trạng.","en":"The weather can affect your mood."},{"use":"影响 + người / sự việc.","ex":"天气影响心情。","py":"Tiānqì yǐngxiǎng xīnqíng.","vi":"Thời tiết ảnh hưởng tâm trạng.","en":"Weather affects mood."},{"use":"Động từ: 睡得不好会影响工作.","ex":"睡得不好会影响工作。","py":"Shuì de bù hǎo huì yǐngxiǎng gōngzuò.","vi":"Ngủ không ngon sẽ ảnh hưởng đến công việc.","en":"Not sleeping well will affect your work."},{"use":"Danh từ: 对…的影响 + 很大.","ex":"父母对孩子的影响很大。","py":"Fùmǔ duì háizi de yǐngxiǎng hěn dà.","vi":"Cha mẹ có ảnh hưởng rất lớn đối với con cái.","en":"Parents have a great influence on their children."},{"use":"没有什么影响: không có ảnh hưởng gì.","ex":"这件事对我没有什么影响。","py":"Zhè jiàn shì duì wǒ méiyǒu shénme yǐngxiǎng.","vi":"Chuyện này không ảnh hưởng gì đến tôi.","en":"This matter has no effect on me."}]},"判断":{"en":"to judge; to determine; judgment","exs":[{"use":"判断 + sự việc.","ex":"你要自己判断对不对。","py":"Nǐ yào zìjǐ pànduàn duì bu duì.","vi":"Bạn phải tự phán đoán đúng hay không.","en":"You have to judge for yourself whether it is right."},{"use":"自己判断 / 作出判断.","ex":"你要自己判断。","py":"Nǐ yào zìjǐ pànduàn.","vi":"Bạn phải tự phán đoán.","en":"You have to decide for yourself."},{"use":"从…判断: dựa vào … để phán đoán.","ex":"从他的表情，我判断他不太高兴。","py":"Cóng tā de biǎoqíng, wǒ pànduàn tā bú tài gāoxìng.","vi":"Nhìn nét mặt anh ấy, tôi đoán anh ấy không vui lắm.","en":"From his expression, I judged that he wasn't very happy."},{"use":"Danh từ: 你的判断.","ex":"你的判断是对的。","py":"Nǐ de pànduàn shì duì de.","vi":"Phán đoán của bạn là đúng.","en":"Your judgment is correct."},{"use":"很难判断 + từ nghi vấn.","ex":"很难判断哪个办法更好。","py":"Hěn nán pànduàn nǎge bànfǎ gèng hǎo.","vi":"Rất khó phán đoán cách nào tốt hơn.","en":"It's hard to judge which method is better."}]},"同事":{"en":"colleague; coworker","exs":[{"use":"Người làm cùng công ty.","ex":"我和同事一起吃午饭。","py":"Wǒ hé tóngshì yìqǐ chī wǔfàn.","vi":"Tôi ăn trưa cùng đồng nghiệp.","en":"I have lunch with my colleagues."},{"use":"是同事，也是朋友.","ex":"我们是同事，也是好朋友。","py":"Wǒmen shì tóngshì, yě shì hǎo péngyou.","vi":"Chúng tôi là đồng nghiệp, cũng là bạn tốt.","en":"We are colleagues and also good friends."},{"use":"新来的同事: đồng nghiệp mới.","ex":"新来的同事很热情。","py":"Xīn lái de tóngshì hěn rèqíng.","vi":"Đồng nghiệp mới đến rất nhiệt tình.","en":"The newly arrived colleague is very friendly."},{"use":"同事们: số nhiều chỉ nhóm đồng nghiệp.","ex":"下班后，同事们一起去吃饭了。","py":"Xiàbān hòu, tóngshìmen yìqǐ qù chīfàn le.","vi":"Sau giờ làm, các đồng nghiệp cùng nhau đi ăn.","en":"After work, the colleagues went to eat together."}]},"顾客":{"en":"customer; client","exs":[{"use":"Người mua hàng, dùng dịch vụ.","ex":"顾客对服务很满意。","py":"Gùkè duì fúwù hěn mǎnyì.","vi":"Khách hàng rất hài lòng với dịch vụ.","en":"The customers are very satisfied with the service."},{"use":"Lời chào của cửa hàng.","ex":"顾客朋友们，欢迎光临。","py":"Gùkè péngyoumen, huānyíng guānglín.","vi":"Quý khách hàng, xin chào mừng đã ghé thăm.","en":"Dear customers, welcome."},{"use":"顾客越来越多: lượng khách tăng.","ex":"这家店的顾客越来越多。","py":"Zhè jiā diàn de gùkè yuè lái yuè duō.","vi":"Khách của tiệm này ngày càng đông.","en":"This shop has more and more customers."},{"use":"帮顾客 + V: phục vụ khách.","ex":"服务员正在帮顾客找座位。","py":"Fúwùyuán zhèngzài bāng gùkè zhǎo zuòwèi.","vi":"Nhân viên phục vụ đang giúp khách tìm chỗ ngồi.","en":"The waiter is helping the customer find a seat."},{"use":"顾客可以…: quyền lợi của khách.","ex":"顾客可以在一周内退货。","py":"Gùkè kěyǐ zài yì zhōu nèi tuìhuò.","vi":"Khách hàng có thể trả hàng trong vòng một tuần.","en":"Customers can return goods within a week."}]},"准时":{"en":"punctual; on time","exs":[{"use":"准时 + động từ.","ex":"请大家准时到。","py":"Qǐng dàjiā zhǔnshí dào.","vi":"Mời mọi người đến đúng giờ.","en":"Please everyone arrive on time."},{"use":"准时 + 到站/起飞: đúng giờ.","ex":"火车准时到站了。","py":"Huǒchē zhǔnshí dào zhàn le.","vi":"Tàu hỏa đã đến ga đúng giờ.","en":"The train arrived at the station on time."},{"use":"Tính từ: 很准时的人 = người đúng giờ.","ex":"他是个很准时的人。","py":"Tā shì ge hěn zhǔnshí de rén.","vi":"Anh ấy là người rất đúng giờ.","en":"He is a very punctual person."},{"use":"没能准时 + V: không kịp giờ.","ex":"飞机没能准时起飞。","py":"Fēijī méi néng zhǔnshí qǐfēi.","vi":"Máy bay đã không cất cánh đúng giờ.","en":"The plane failed to take off on time."}]},"约会":{"en":"appointment; date; to date","exs":[{"use":"Có thể là cuộc hẹn nói chung hoặc hẹn hò.","ex":"他今晚有个约会。","py":"Tā jīnwǎn yǒu gè yuēhuì.","vi":"Tối nay anh ấy có một cuộc hẹn.","en":"He has a date tonight."},{"use":"Động từ: hẹn hò.","ex":"他们常常周末一起约会。","py":"Tāmen chángcháng zhōumò yìqǐ yuēhuì.","vi":"Họ thường hẹn hò cùng nhau vào cuối tuần.","en":"They often go on dates together at weekends."},{"use":"跟…有个约会: có hẹn với ai.","ex":"明天我跟朋友有个约会，不能去了。","py":"Míngtiān wǒ gēn péngyou yǒu ge yuēhuì, bù néng qù le.","vi":"Ngày mai tôi có hẹn với bạn nên không đi được.","en":"I have an appointment with a friend tomorrow, so I can't go."},{"use":"约会的时候: khi hẹn hò.","ex":"约会的时候，他送给她一束花。","py":"Yuēhuì de shíhou, tā sòng gěi tā yí shù huā.","vi":"Khi hẹn hò, anh ấy tặng cô ấy một bó hoa.","en":"On their date, he gave her a bunch of flowers."}]},"改变":{"en":"to change; to alter","exs":[{"use":"改变 + sự vật / tình hình.","ex":"他的看法改变了。","py":"Tā de kànfǎ gǎibiàn le.","vi":"Cách nhìn của anh ấy đã thay đổi.","en":"His view has changed."},{"use":"改变 + sự vật / tình hình.","ex":"我们不能改变过去。","py":"Wǒmen bù néng gǎibiàn guòqù.","vi":"Chúng ta không thể thay đổi quá khứ.","en":"We cannot change the past."},{"use":"Cụm cố định 改变主意: đổi ý.","ex":"他改变了主意，不想去了。","py":"Tā gǎibiàn le zhǔyi, bù xiǎng qù le.","vi":"Anh ấy đã đổi ý, không muốn đi nữa.","en":"He changed his mind and no longer wants to go."},{"use":"改变 + 得 + tính từ: mức độ thay đổi.","ex":"这个城市的样子改变得很快。","py":"Zhège chéngshì de yàngzi gǎibiàn de hěn kuài.","vi":"Diện mạo của thành phố này thay đổi rất nhanh.","en":"The look of this city is changing very fast."}]},"相信":{"en":"to believe; to trust","exs":[{"use":"相信 + người / mệnh đề.","ex":"我相信你能做好。","py":"Wǒ xiāngxìn nǐ néng zuòhǎo.","vi":"Tôi tin bạn có thể làm tốt.","en":"I believe you can do it well."},{"use":"相信 + đại từ phản thân: tin vào chính mình.","ex":"你要相信自己。","py":"Nǐ yào xiāngxìn zìjǐ.","vi":"Bạn phải tin vào chính mình.","en":"You must believe in yourself."},{"use":"Dạng phủ định: 不相信 + lời nói / người.","ex":"我不相信他说的话。","py":"Wǒ bù xiāngxìn tā shuō de huà.","vi":"Tôi không tin những lời anh ta nói.","en":"I don't believe what he said."},{"use":"相信 + mệnh đề (tin rằng...).","ex":"很多人相信这个消息是真的。","py":"Hěn duō rén xiāngxìn zhège xiāoxi shì zhēn de.","vi":"Nhiều người tin rằng tin tức này là thật.","en":"Many people believe this news is true."}]},"明天":{"en":"tomorrow","exs":[{"use":"Danh từ chỉ thời gian, đứng trước vị ngữ làm trạng ngữ.","ex":"明天是周末，我们去爬山吧。","py":"Míngtiān shì zhōumò, wǒmen qù pá shān ba.","vi":"Ngày mai là cuối tuần, chúng ta đi leo núi nhé.","en":"Tomorrow is the weekend, let's go hiking."},{"use":"Đứng sau chủ ngữ, kết hợp với các từ chỉ thời gian khác.","ex":"我明天上午有一个会议。","py":"Wǒ míngtiān shàngwǔ yǒu yí gè huìyì.","vi":"Sáng mai tôi có một cuộc họp.","en":"I have a meeting tomorrow morning."},{"use":"明天 + 的 + danh từ: làm định ngữ.","ex":"明天的天气怎么样？","py":"Míngtiān de tiānqì zěnmeyàng?","vi":"Thời tiết ngày mai thế nào?","en":"What will the weather be like tomorrow?"},{"use":"Câu chào tạm biệt: 明天见.","ex":"明天见，路上小心！","py":"Míngtiān jiàn, lùshang xiǎoxīn!","vi":"Mai gặp nhé, đi đường cẩn thận!","en":"See you tomorrow, be careful on the road!"}]},"上班":{"en":"to go to work; to be at work","exs":[{"use":"Động từ ly hợp (V + O), thường đi với giờ giấc.","ex":"我每天八点上班。","py":"Wǒ měitiān bā diǎn shàng bān.","vi":"Mỗi ngày tôi đi làm lúc tám giờ.","en":"I go to work at eight every day."},{"use":"去上班: đi làm (chỉ hành động đi đến chỗ làm).","ex":"你怎么去上班？","py":"Nǐ zěnme qù shàng bān?","vi":"Bạn đi làm bằng gì?","en":"How do you get to work?"},{"use":"Dạng phủ định/khả năng: 不用上班 = không phải đi làm.","ex":"他今天不用上班，在家休息。","py":"Tā jīntiān bú yòng shàng bān, zài jiā xiūxi.","vi":"Hôm nay anh ấy không phải đi làm, nghỉ ở nhà.","en":"He doesn't have to work today and is resting at home."},{"use":"Thường đi với 离…近/远 nói về khoảng cách đi làm.","ex":"他住得离公司很近，走路就能上班。","py":"Tā zhù de lí gōngsī hěn jìn, zǒulù jiù néng shàng bān.","vi":"Anh ấy ở gần công ty, đi bộ là có thể đến chỗ làm.","en":"He lives close to the company and can walk to work."}]},"没想到":{"en":"did not expect; unexpectedly","exs":[{"use":"没想到 + mệnh đề: bày tỏ sự bất ngờ.","ex":"没想到你也来了！","py":"Méi xiǎngdào nǐ yě lái le!","vi":"Không ngờ bạn cũng đến!","en":"I didn't expect you to come too!"},{"use":"没想到 + mệnh đề với 这么/那么 + adj.","ex":"没想到这家饭店这么便宜。","py":"Méi xiǎngdào zhè jiā fàndiàn zhème piányi.","vi":"Không ngờ nhà hàng này rẻ đến vậy.","en":"I didn't expect this restaurant to be so cheap."},{"use":"我没想到…会…: không nghĩ là sẽ...","ex":"我没想到考试会这么难。","py":"Wǒ méi xiǎngdào kǎoshì huì zhème nán.","vi":"Tôi không ngờ kỳ thi lại khó như thế.","en":"I never thought the exam would be this hard."},{"use":"没想到 ở đầu vế sau, nêu kết quả trái dự đoán.","ex":"本来想早点儿到，没想到路上堵车了。","py":"Běnlái xiǎng zǎodiǎnr dào, méi xiǎngdào lùshang dǔ chē le.","vi":"Vốn định đến sớm, không ngờ trên đường lại kẹt xe.","en":"I meant to arrive early, but unexpectedly got stuck in traffic."}]},"衣服":{"en":"clothes; clothing","exs":[{"use":"Lượng từ thường dùng: 件.","ex":"这件衣服很漂亮。","py":"Zhè jiàn yīfu hěn piàoliang.","vi":"Bộ quần áo này rất đẹp.","en":"This piece of clothing is very pretty."},{"use":"买衣服: mua quần áo; lượng từ 件.","ex":"我想去商店买几件新衣服。","py":"Wǒ xiǎng qù shāngdiàn mǎi jǐ jiàn xīn yīfu.","vi":"Tôi muốn đi cửa hàng mua mấy bộ quần áo mới.","en":"I want to go to the store and buy a few new clothes."},{"use":"穿衣服: mặc quần áo.","ex":"天冷了，多穿点儿衣服。","py":"Tiān lěng le, duō chuān diǎnr yīfu.","vi":"Trời lạnh rồi, mặc thêm quần áo vào.","en":"It's getting cold, put on more clothes."},{"use":"Làm chủ ngữ, đi với 都 và kết quả bổ ngữ.","ex":"这些衣服都洗干净了。","py":"Zhèxiē yīfu dōu xǐ gānjìng le.","vi":"Những bộ quần áo này đều đã giặt sạch rồi.","en":"These clothes have all been washed clean."}]},"留下":{"en":"to leave behind; to stay; to keep","exs":[{"use":"留下 + vật: để lại đồ vật.","ex":"他给我留下了一张纸条。","py":"Tā gěi wǒ liú xià le yì zhāng zhǐtiáo.","vi":"Anh ấy để lại cho tôi một tờ giấy nhắn.","en":"He left me a note."},{"use":"请留下 + thông tin: yêu cầu để lại.","ex":"请留下你的电话号码。","py":"Qǐng liú xià nǐ de diànhuà hàomǎ.","vi":"Xin hãy để lại số điện thoại của bạn.","en":"Please leave your phone number."},{"use":"Nghĩa 2: ở lại (không rời đi).","ex":"今天晚上你留下吃饭吧。","py":"Jīntiān wǎnshang nǐ liú xià chī fàn ba.","vi":"Tối nay bạn ở lại ăn cơm nhé.","en":"Stay for dinner tonight."},{"use":"留下印象: để lại ấn tượng.","ex":"这次旅行给我留下了很好的印象。","py":"Zhè cì lǚxíng gěi wǒ liú xià le hěn hǎo de yìnxiàng.","vi":"Chuyến du lịch này để lại cho tôi ấn tượng rất tốt.","en":"This trip left me with a very good impression."}]},"不要":{"en":"do not (imperative); don't want","exs":[{"use":"不要 + động từ: đừng làm gì (cấm đoán, khuyên).","ex":"不要在这里抽烟。","py":"Búyào zài zhèlǐ chōu yān.","vi":"Đừng hút thuốc ở đây.","en":"Don't smoke here."},{"use":"不要 + 忘了: nhắc nhở.","ex":"不要忘了带手机。","py":"Búyào wàng le dài shǒujī.","vi":"Đừng quên mang điện thoại.","en":"Don't forget to bring your phone."},{"use":"Nghĩa 2: không cần / không muốn (+ danh từ).","ex":"我不要这个，我要那个。","py":"Wǒ búyào zhège, wǒ yào nàge.","vi":"Tôi không lấy cái này, tôi lấy cái kia.","en":"I don't want this one, I want that one."},{"use":"不要太 + adj: đừng quá...","ex":"你不要太担心。","py":"Nǐ búyào tài dānxīn.","vi":"Bạn đừng lo lắng quá.","en":"Don't worry too much."}]},"回答":{"en":"to answer; to reply; answer","exs":[{"use":"回答 + 问题: trả lời câu hỏi.","ex":"请回答我的问题。","py":"Qǐng huídá wǒ de wèntí.","vi":"Xin hãy trả lời câu hỏi của tôi.","en":"Please answer my question."},{"use":"V + 得 + adj: đánh giá cách trả lời.","ex":"老师问他，他回答得很好。","py":"Lǎoshī wèn tā, tā huídá de hěn hǎo.","vi":"Thầy giáo hỏi, cậu ấy trả lời rất tốt.","en":"The teacher asked him and he answered very well."},{"use":"不知道怎么回答: không biết trả lời thế nào.","ex":"这个问题我不知道怎么回答。","py":"Zhège wèntí wǒ bù zhīdào zěnme huídá.","vi":"Câu hỏi này tôi không biết trả lời thế nào.","en":"I don't know how to answer this question."},{"use":"Làm danh từ: câu trả lời.","ex":"你的回答让我很满意。","py":"Nǐ de huídá ràng wǒ hěn mǎnyì.","vi":"Câu trả lời của bạn khiến tôi rất hài lòng.","en":"Your answer satisfied me very much."}]},"第一":{"en":"first; number one","exs":[{"use":"第一 + lượng từ + danh từ: lần/lượt đầu tiên.","ex":"第一次来中国，我很紧张。","py":"Dì-yī cì lái Zhōngguó, wǒ hěn jǐnzhāng.","vi":"Lần đầu đến Trung Quốc, tôi rất hồi hộp.","en":"It's my first time in China and I'm very nervous."},{"use":"Làm danh từ: hạng nhất.","ex":"他在班里考了第一。","py":"Tā zài bān lǐ kǎo le dì-yī.","vi":"Cậu ấy thi đứng nhất lớp.","en":"He ranked first in his class."},{"use":"Cụm cố định: X + 第一 = X là trên hết.","ex":"安全第一，开车别太快。","py":"Ānquán dì-yī, kāichē bié tài kuài.","vi":"An toàn là trên hết, lái xe đừng nhanh quá.","en":"Safety first, don't drive too fast."},{"use":"第一 + 天/个 + danh từ: ngày/cái đầu tiên.","ex":"这是我第一天上班。","py":"Zhè shì wǒ dì-yī tiān shàng bān.","vi":"Đây là ngày đi làm đầu tiên của tôi.","en":"This is my first day at work."}]},"见面":{"en":"to meet; to see each other","exs":[{"use":"Động từ ly hợp, không mang tân ngữ trực tiếp.","ex":"我们明天下午见面吧。","py":"Wǒmen míngtiān xiàwǔ jiàn miàn ba.","vi":"Chiều mai chúng ta gặp nhau nhé.","en":"Let's meet tomorrow afternoon."},{"use":"跟 + người + 见面: gặp ai đó.","ex":"我想跟你见面谈一谈。","py":"Wǒ xiǎng gēn nǐ jiàn miàn tán yi tán.","vi":"Tôi muốn gặp bạn để nói chuyện.","en":"I'd like to meet you and have a talk."},{"use":"没见面: chưa gặp (dùng 没 phủ định).","ex":"我们好久没见面了。","py":"Wǒmen hǎojiǔ méi jiàn miàn le.","vi":"Chúng ta lâu rồi không gặp nhau.","en":"We haven't seen each other for a long time."},{"use":"见面以后: sau khi gặp mặt.","ex":"见面以后我再告诉你。","py":"Jiàn miàn yǐhòu wǒ zài gàosu nǐ.","vi":"Gặp mặt rồi tôi sẽ nói với bạn.","en":"I'll tell you after we meet."}]},"别人":{"en":"other people; others","exs":[{"use":"别人 làm tân ngữ: người khác.","ex":"不要总是看别人的缺点。","py":"Búyào zǒngshì kàn biérén de quēdiǎn.","vi":"Đừng lúc nào cũng nhìn vào khuyết điểm của người khác.","en":"Don't always look at other people's faults."},{"use":"别人 làm chủ ngữ, đối lập với 我.","ex":"别人都走了，只有我还在这里。","py":"Biérén dōu zǒu le, zhǐyǒu wǒ hái zài zhèlǐ.","vi":"Người khác đều đi cả rồi, chỉ có tôi còn ở đây.","en":"Everyone else has left; only I am still here."},{"use":"帮助别人: giúp đỡ người khác.","ex":"我们要学会帮助别人。","py":"Wǒmen yào xuéhuì bāngzhù biérén.","vi":"Chúng ta phải học cách giúp đỡ người khác.","en":"We should learn to help others."},{"use":"Cấu trúc 是别人…的: do người khác...","ex":"这本书是别人送给我的。","py":"Zhè běn shū shì biérén sòng gěi wǒ de.","vi":"Cuốn sách này là người khác tặng tôi.","en":"This book was given to me by someone else."}]},"以后":{"en":"later; after; in the future","exs":[{"use":"以后 đứng đầu câu: về sau, từ nay.","ex":"以后我每天早点儿睡觉。","py":"Yǐhòu wǒ měitiān zǎodiǎnr shuìjiào.","vi":"Từ nay tôi sẽ đi ngủ sớm hơn mỗi ngày.","en":"From now on I'll go to bed earlier every day."},{"use":"Động từ + 以后: sau khi làm gì.","ex":"下班以后我们一起去吃饭吧。","py":"Xià bān yǐhòu wǒmen yìqǐ qù chī fàn ba.","vi":"Sau khi tan làm chúng ta cùng đi ăn nhé.","en":"Let's go eat together after work."},{"use":"Khoảng thời gian + 以后: sau bao lâu.","ex":"三年以后，他回国了。","py":"Sān nián yǐhòu, tā huí guó le.","vi":"Ba năm sau, anh ấy về nước.","en":"Three years later, he returned to his home country."},{"use":"以后 + 的 + danh từ: làm định ngữ.","ex":"以后的事以后再说。","py":"Yǐhòu de shì yǐhòu zàishuō.","vi":"Chuyện sau này thì để sau hãy nói.","en":"We'll deal with future matters later."}]},"感觉":{"en":"feeling; sense; to feel","exs":[{"use":"Động từ: 感觉 + adj / mệnh đề (cảm thấy).","ex":"我感觉有点儿累。","py":"Wǒ gǎnjué yǒudiǎnr lèi.","vi":"Tôi cảm thấy hơi mệt.","en":"I feel a bit tired."},{"use":"感觉 + mệnh đề: cho rằng, thấy rằng.","ex":"我感觉他今天不太高兴。","py":"Wǒ gǎnjué tā jīntiān bú tài gāoxìng.","vi":"Tôi cảm thấy hôm nay anh ấy không vui lắm.","en":"I get the feeling he isn't very happy today."},{"use":"Hỏi ý kiến: 感觉怎么样?","ex":"你感觉这个主意怎么样？","py":"Nǐ gǎnjué zhège zhǔyi zěnmeyàng?","vi":"Bạn thấy ý kiến này thế nào?","en":"What do you think of this idea?"},{"use":"Danh từ: 的 + 感觉.","ex":"回到家的感觉真好。","py":"Huídào jiā de gǎnjué zhēn hǎo.","vi":"Cảm giác về đến nhà thật tuyệt.","en":"It feels so good to be back home."}]},"所以":{"en":"so; therefore","exs":[{"use":"Dùng ở vế kết quả; vế trước thường nêu nguyên nhân.","ex":"今天下雨，所以我没出门。","py":"Jīntiān xià yǔ, suǒyǐ wǒ méi chū mén.","vi":"Hôm nay trời mưa, vì vậy tôi không ra ngoài.","en":"It rained today, so I didn't go out."},{"use":"Cấu trúc 因为…所以…","ex":"因为路上堵车，所以我迟到了。","py":"Yīnwèi lùshang dǔ chē, suǒyǐ wǒ chídào le.","vi":"Vì trên đường kẹt xe nên tôi đến muộn.","en":"Because of the traffic jam, I was late."},{"use":"Bỏ 因为, chỉ dùng 所以 ở vế sau.","ex":"我不太舒服，所以想早点儿回家。","py":"Wǒ bú tài shūfu, suǒyǐ xiǎng zǎodiǎnr huí jiā.","vi":"Tôi không khỏe lắm nên muốn về nhà sớm.","en":"I don't feel well, so I want to go home early."},{"use":"所以 nối kết quả của lý do đã nêu.","ex":"他学习很努力，所以成绩一直很好。","py":"Tā xuéxí hěn nǔlì, suǒyǐ chéngjì yìzhí hěn hǎo.","vi":"Anh ấy học rất chăm nên thành tích luôn tốt.","en":"He studies hard, so his grades have always been good."}]},"可能":{"en":"maybe; possibly; possible; possibility","exs":[{"use":"Phó từ: 可能 + động từ (có lẽ).","ex":"他可能还在开会。","py":"Tā kěnéng hái zài kāihuì.","vi":"Có lẽ anh ấy vẫn đang họp.","en":"He may still be in a meeting."},{"use":"可能 + 会: dự đoán điều sắp xảy ra.","ex":"明天可能会下雨。","py":"Míngtiān kěnéng huì xià yǔ.","vi":"Ngày mai có thể sẽ mưa.","en":"It may rain tomorrow."},{"use":"Tính từ: 不太可能 = không có khả năng.","ex":"这件事不太可能。","py":"Zhè jiàn shì bú tài kěnéng.","vi":"Chuyện này không có mấy khả năng.","en":"This is unlikely."},{"use":"Danh từ: 有…的可能 (khả năng).","ex":"我们还有成功的可能。","py":"Wǒmen hái yǒu chénggōng de kěnéng.","vi":"Chúng ta vẫn còn khả năng thành công.","en":"We still have a chance of success."}]},"东西":{"en":"thing; stuff; object","exs":[{"use":"Chỉ đồ vật nói chung; 买东西: mua đồ.","ex":"我去超市买点儿东西。","py":"Wǒ qù chāoshì mǎi diǎnr dōngxi.","vi":"Tôi đi siêu thị mua ít đồ.","en":"I'm going to the supermarket to buy a few things."},{"use":"东西 làm trung tâm ngữ cho định ngữ.","ex":"桌子上的东西是谁的？","py":"Zhuōzi shàng de dōngxi shì shéi de?","vi":"Đồ trên bàn là của ai vậy?","en":"Whose things are on the table?"},{"use":"吃东西 / 什么东西: đồ ăn, thứ gì.","ex":"你喜欢吃什么东西？","py":"Nǐ xǐhuan chī shénme dōngxi?","vi":"Bạn thích ăn món gì?","en":"What kind of food do you like to eat?"},{"use":"带东西: mang theo đồ đạc.","ex":"出门别忘了带东西。","py":"Chū mén bié wàng le dài dōngxi.","vi":"Ra khỏi nhà đừng quên mang đồ.","en":"Don't forget to take your things when you go out."}]},"这样":{"en":"like this; this way; so","exs":[{"use":"这样 + động từ: làm như thế này.","ex":"这样做不太好。","py":"Zhèyàng zuò bú tài hǎo.","vi":"Làm như vậy không tốt lắm.","en":"It's not good to do it this way."},{"use":"Làm vị ngữ: 总是这样 = lúc nào cũng thế.","ex":"他总是这样，从来不着急。","py":"Tā zǒngshì zhèyàng, cónglái bù zháojí.","vi":"Anh ấy lúc nào cũng vậy, chưa bao giờ vội.","en":"He's always like this and never in a hurry."},{"use":"这样吧: đưa ra đề nghị, cách giải quyết.","ex":"这样吧，我们明天再讨论。","py":"Zhèyàng ba, wǒmen míngtiān zài tǎolùn.","vi":"Thế này nhé, ngày mai chúng ta bàn tiếp.","en":"Tell you what, let's discuss it tomorrow."},{"use":"这样的 + danh từ: loại như thế này.","ex":"这样的人很少见。","py":"Zhèyàng de rén hěn shǎojiàn.","vi":"Người như thế này rất hiếm gặp.","en":"People like this are rare."}]},"不管":{"en":"no matter (what / how); regardless of","exs":[{"use":"Thường dùng với 都 / 也: 不管…都/也…","ex":"不管多忙，我都会吃早餐。","py":"Bùguǎn duō máng, wǒ dōu huì chī zǎocān.","vi":"Dù bận thế nào, tôi cũng sẽ ăn sáng.","en":"No matter how busy I am, I always eat breakfast."},{"use":"不管 + từ nghi vấn (怎么样/什么/谁) + 都…","ex":"不管天气怎么样，我们都要去。","py":"Bùguǎn tiānqì zěnmeyàng, wǒmen dōu yào qù.","vi":"Bất kể thời tiết thế nào, chúng tôi cũng đi.","en":"No matter what the weather is like, we're going."},{"use":"不管 + A不A (câu hỏi chính phản) + 都…","ex":"不管你同不同意，我都会去。","py":"Bùguǎn nǐ tóng bu tóngyì, wǒ dōu huì qù.","vi":"Dù bạn đồng ý hay không, tôi vẫn sẽ đi.","en":"Whether you agree or not, I will go."},{"use":"不管 + 谁: bất kể ai.","ex":"不管谁来，我都欢迎。","py":"Bùguǎn shéi lái, wǒ dōu huānyíng.","vi":"Bất kể ai đến, tôi cũng hoan nghênh.","en":"Whoever comes, I welcome them."}]},"上课":{"en":"to attend class; to teach a class","exs":[{"use":"Động từ ly hợp, đi với giờ học.","ex":"我们八点上课。","py":"Wǒmen bā diǎn shàng kè.","vi":"Chúng tôi vào học lúc tám giờ.","en":"Our class starts at eight."},{"use":"给 + người + 上课: dạy học cho ai.","ex":"老师正在给学生上课。","py":"Lǎoshī zhèngzài gěi xuésheng shàng kè.","vi":"Thầy giáo đang giảng bài cho học sinh.","en":"The teacher is teaching the students."},{"use":"不上课: không có tiết, nghỉ học.","ex":"今天下雨，学校不上课。","py":"Jīntiān xià yǔ, xuéxiào bú shàng kè.","vi":"Hôm nay mưa nên trường nghỉ học.","en":"School is closed today because of the rain."},{"use":"上课的时候: trong giờ học.","ex":"上课的时候请关手机。","py":"Shàng kè de shíhou qǐng guān shǒujī.","vi":"Trong giờ học xin hãy tắt điện thoại.","en":"Please turn off your phone during class."}]},"上午":{"en":"morning; forenoon","exs":[{"use":"Danh từ chỉ thời gian, đứng trước/sau chủ ngữ.","ex":"我上午有课，下午没有。","py":"Wǒ shàngwǔ yǒu kè, xiàwǔ méiyǒu.","vi":"Buổi sáng tôi có tiết, buổi chiều thì không.","en":"I have class in the morning but not in the afternoon."},{"use":"上午 + giờ cụ thể.","ex":"明天上午九点开会。","py":"Míngtiān shàngwǔ jiǔ diǎn kāihuì.","vi":"Chín giờ sáng mai họp.","en":"The meeting is at nine tomorrow morning."},{"use":"每天上午: thói quen hằng ngày.","ex":"他每天上午都去公园锻炼。","py":"Tā měitiān shàngwǔ dōu qù gōngyuán duànliàn.","vi":"Mỗi buổi sáng anh ấy đều ra công viên tập thể dục.","en":"He exercises in the park every morning."},{"use":"Lời chào: 上午好.","ex":"上午好，请问您找谁？","py":"Shàngwǔ hǎo, qǐngwèn nín zhǎo shéi?","vi":"Chào buổi sáng, xin hỏi ông tìm ai ạ?","en":"Good morning, who are you looking for?"}]},"小雨":{"en":"Xiaoyu (a given name); light rain","exs":[{"use":"Tên người (dùng như danh từ riêng làm chủ ngữ).","ex":"小雨是我最好的朋友。","py":"Xiǎoyǔ shì wǒ zuì hǎo de péngyou.","vi":"Tiểu Vũ là bạn thân nhất của tôi.","en":"Xiaoyu is my best friend."},{"use":"Gọi tên trực tiếp trong hội thoại.","ex":"小雨，你周末有空吗？","py":"Xiǎoyǔ, nǐ zhōumò yǒu kòng ma?","vi":"Tiểu Vũ, cuối tuần bạn có rảnh không?","en":"Xiaoyu, are you free this weekend?"},{"use":"Tên người làm chủ ngữ trong câu kể.","ex":"小雨跟她妈妈去超市了。","py":"Xiǎoyǔ gēn tā māma qù chāoshì le.","vi":"Tiểu Vũ đi siêu thị với mẹ rồi.","en":"Xiaoyu went to the supermarket with her mom."},{"use":"Nghĩa 2: mưa nhỏ (xiǎo + yǔ); 下小雨 = mưa nhỏ.","ex":"外面下着小雨，你带伞了吗？","py":"Wàimiàn xià zhe xiǎoyǔ, nǐ dài sǎn le ma?","vi":"Bên ngoài đang mưa nhỏ, bạn có mang ô không?","en":"It's drizzling outside; did you bring an umbrella?"}]},"信心":{"en":"confidence; faith","exs":[{"use":"对…有信心: có lòng tin vào...","ex":"我对这次考试很有信心。","py":"Wǒ duì zhè cì kǎoshì hěn yǒu xìnxīn.","vi":"Tôi rất tự tin về kỳ thi lần này.","en":"I'm very confident about this exam."},{"use":"失去信心: mất niềm tin.","ex":"别失去信心，再试一次。","py":"Bié shīqù xìnxīn, zài shì yí cì.","vi":"Đừng mất niềm tin, thử lại lần nữa.","en":"Don't lose heart, try once more."},{"use":"给(某人)信心: tiếp thêm sức mạnh, niềm tin.","ex":"你的话给了我很大的信心。","py":"Nǐ de huà gěi le wǒ hěn dà de xìnxīn.","vi":"Lời của bạn đã cho tôi rất nhiều niềm tin.","en":"Your words gave me great confidence."},{"use":"充满信心: tràn đầy tự tin.","ex":"他对自己的工作充满信心。","py":"Tā duì zìjǐ de gōngzuò chōngmǎn xìnxīn.","vi":"Anh ấy tràn đầy tự tin về công việc của mình.","en":"He is full of confidence in his work."}]},"体育馆":{"en":"gymnasium; sports hall","exs":[{"use":"在体育馆 + động từ: nơi diễn ra hoạt động thể thao.","ex":"体育馆里有很多人在打篮球。","py":"Tǐyùguǎn lǐ yǒu hěn duō rén zài dǎ lánqiú.","vi":"Trong nhà thi đấu có rất nhiều người đang chơi bóng rổ.","en":"Many people are playing basketball in the gym."},{"use":"Chỉ công trình: 新建了一个体育馆.","ex":"我们学校新建了一个体育馆。","py":"Wǒmen xuéxiào xīn jiàn le yí gè tǐyùguǎn.","vi":"Trường chúng tôi mới xây một nhà thi đấu.","en":"Our school built a new gymnasium."},{"use":"Địa điểm hẹn gặp.","ex":"明天下午我在体育馆等你。","py":"Míngtiān xiàwǔ wǒ zài tǐyùguǎn děng nǐ.","vi":"Chiều mai tôi đợi bạn ở nhà thi đấu.","en":"I'll wait for you at the gym tomorrow afternoon."},{"use":"Nói về sức chứa của công trình.","ex":"这个体育馆可以坐一万个人。","py":"Zhège tǐyùguǎn kěyǐ zuò yí wàn gè rén.","vi":"Nhà thi đấu này có thể chứa mười nghìn người.","en":"This stadium can seat ten thousand people."}]},"招聘会":{"en":"job fair; recruitment fair","exs":[{"use":"举办招聘会: tổ chức hội chợ việc làm.","ex":"学校下周举办招聘会。","py":"Xuéxiào xià zhōu jǔbàn zhāopìnhuì.","vi":"Tuần sau trường tổ chức hội chợ việc làm.","en":"The school is holding a job fair next week."},{"use":"参加招聘会: tham dự hội chợ việc làm.","ex":"我带着简历去参加招聘会。","py":"Wǒ dàizhe jiǎnlì qù cānjiā zhāopìnhuì.","vi":"Tôi mang theo hồ sơ xin việc đi dự hội chợ việc làm.","en":"I took my résumé to the job fair."},{"use":"招聘会上: tại hội chợ việc làm.","ex":"招聘会上有很多公司在找人。","py":"Zhāopìnhuì shàng yǒu hěn duō gōngsī zài zhǎo rén.","vi":"Ở hội chợ việc làm có rất nhiều công ty đang tìm người.","en":"Many companies are looking for people at the job fair."}]},"决定":{"en":"to decide; decision","exs":[{"use":"决定 + động từ / 做决定.","ex":"我决定明天去北京。","py":"Wǒ juédìng míngtiān qù Běijīng.","vi":"Tôi quyết định ngày mai đi Bắc Kinh.","en":"I've decided to go to Beijing tomorrow."},{"use":"Danh từ: 一个…的决定.","ex":"这是一个很难的决定。","py":"Zhè shì yí gè hěn nán de juédìng.","vi":"Đây là một quyết định rất khó.","en":"This is a very difficult decision."},{"use":"Chủ ngữ là tổ chức: 公司决定…","ex":"公司决定给大家放三天假。","py":"Gōngsī juédìng gěi dàjiā fàng sān tiān jià.","vi":"Công ty quyết định cho mọi người nghỉ ba ngày.","en":"The company decided to give everyone three days off."},{"use":"由 + người + 决定: do ai quyết định.","ex":"去不去由你决定。","py":"Qù bu qù yóu nǐ juédìng.","vi":"Đi hay không do bạn quyết định.","en":"Whether to go is up to you."}]},"提供":{"en":"to provide; to supply; to offer","exs":[{"use":"提供 + danh từ (dịch vụ, đồ dùng).","ex":"这家酒店提供免费早餐。","py":"Zhè jiā jiǔdiàn tígōng miǎnfèi zǎocān.","vi":"Khách sạn này cung cấp bữa sáng miễn phí.","en":"This hotel provides free breakfast."},{"use":"为 + người + 提供 + danh từ.","ex":"公司为员工提供住的地方。","py":"Gōngsī wèi yuángōng tígōng zhù de dìfang.","vi":"Công ty cung cấp chỗ ở cho nhân viên.","en":"The company provides housing for its employees."},{"use":"Yêu cầu cung cấp thông tin.","ex":"请提供你的名字和电话。","py":"Qǐng tígōng nǐ de míngzi hé diànhuà.","vi":"Xin cung cấp tên và số điện thoại của bạn.","en":"Please provide your name and phone number."},{"use":"提供 + 信息/帮助.","ex":"他能提供很多有用的信息。","py":"Tā néng tígōng hěn duō yǒuyòng de xìnxī.","vi":"Anh ấy có thể cung cấp nhiều thông tin hữu ích.","en":"He can provide a lot of useful information."}]},"机会":{"en":"opportunity; chance","exs":[{"use":"一个…的机会: cơ hội.","ex":"这是一个很好的机会。","py":"Zhè shì yí gè hěn hǎo de jīhuì.","vi":"Đây là một cơ hội rất tốt.","en":"This is a very good opportunity."},{"use":"有机会 + động từ: nếu có dịp.","ex":"我想有机会去中国学习。","py":"Wǒ xiǎng yǒu jīhuì qù Zhōngguó xuéxí.","vi":"Tôi muốn có cơ hội đến Trung Quốc học tập.","en":"I hope to have a chance to study in China."},{"use":"给(某人)机会: cho ai cơ hội.","ex":"请再给我一次机会。","py":"Qǐng zài gěi wǒ yí cì jīhuì.","vi":"Xin hãy cho tôi thêm một cơ hội.","en":"Please give me one more chance."},{"use":"错过机会: bỏ lỡ cơ hội.","ex":"别错过这个机会。","py":"Bié cuòguò zhège jīhuì.","vi":"Đừng bỏ lỡ cơ hội này.","en":"Don't miss this opportunity."}]},"招聘":{"en":"to recruit; to hire; recruitment","exs":[{"use":"招聘 + người: tuyển dụng nhân viên.","ex":"公司正在招聘新员工。","py":"Gōngsī zhèngzài zhāopìn xīn yuángōng.","vi":"Công ty đang tuyển nhân viên mới.","en":"The company is recruiting new employees."},{"use":"Làm định ngữ: 招聘信息.","ex":"我在网上看到了一条招聘信息。","py":"Wǒ zài wǎngshàng kàndào le yì tiáo zhāopìn xìnxī.","vi":"Tôi thấy một tin tuyển dụng trên mạng.","en":"I saw a job posting online."},{"use":"招聘 + số lượng + chức danh.","ex":"他们招聘了三个翻译。","py":"Tāmen zhāopìn le sān gè fānyì.","vi":"Họ đã tuyển ba phiên dịch viên.","en":"They hired three translators."},{"use":"招聘 + 的 + 条件: điều kiện tuyển dụng.","ex":"这次招聘的条件是什么？","py":"Zhè cì zhāopìn de tiáojiàn shì shénme?","vi":"Điều kiện của đợt tuyển dụng lần này là gì?","en":"What are the requirements for this recruitment?"}]},"负责":{"en":"to be responsible for; to be in charge of; responsible","exs":[{"use":"负责 + công việc / dự án: phụ trách.","ex":"他负责这个项目。","py":"Tā fùzé zhège xiàngmù.","vi":"Anh ấy phụ trách dự án này.","en":"He is in charge of this project."},{"use":"对…负责: chịu trách nhiệm về...","ex":"你要对自己的话负责。","py":"Nǐ yào duì zìjǐ de huà fùzé.","vi":"Bạn phải chịu trách nhiệm về lời nói của mình.","en":"You must take responsibility for your own words."},{"use":"Tính từ: 很负责 = có trách nhiệm.","ex":"她工作很负责。","py":"Tā gōngzuò hěn fùzé.","vi":"Cô ấy làm việc rất có trách nhiệm.","en":"She is very responsible at work."},{"use":"谁负责 + động từ: ai đảm nhiệm việc gì.","ex":"谁负责买票？","py":"Shéi fùzé mǎi piào?","vi":"Ai phụ trách mua vé?","en":"Who is in charge of buying the tickets?"}]},"本来":{"en":"originally; at first; should have","exs":[{"use":"本来 + muốn làm gì, nhưng sau đó thay đổi.","ex":"我本来想去，可是太忙了。","py":"Wǒ běnlái xiǎng qù, kěshì tài máng le.","vi":"Tôi vốn định đi, nhưng bận quá.","en":"I originally wanted to go, but I was too busy."},{"use":"本来就: vốn dĩ đã như vậy.","ex":"他本来就不喜欢吃辣的。","py":"Tā běnlái jiù bù xǐhuan chī là de.","vi":"Anh ấy vốn đã không thích ăn cay.","en":"He never liked spicy food in the first place."},{"use":"本来 = lẽ ra, đáng lẽ (là trách nhiệm của ai).","ex":"这本来是你的工作。","py":"Zhè běnlái shì nǐ de gōngzuò.","vi":"Việc này vốn là công việc của bạn.","en":"This was supposed to be your job."},{"use":"本来 + adj, nhưng (被…) đã đổi khác.","ex":"这件事本来很简单，被他弄复杂了。","py":"Zhè jiàn shì běnlái hěn jiǎndān, bèi tā nòng fùzá le.","vi":"Chuyện này vốn rất đơn giản, bị anh ta làm phức tạp lên.","en":"This was originally simple, but he made it complicated."}]},"突然":{"en":"suddenly; sudden","exs":[{"use":"Phó từ: 突然 + động từ.","ex":"天气突然变冷了。","py":"Tiānqì tūrán biàn lěng le.","vi":"Thời tiết đột nhiên trở lạnh.","en":"The weather suddenly turned cold."},{"use":"突然想起来: chợt nhớ ra.","ex":"他突然想起来今天是妈妈的生日。","py":"Tā tūrán xiǎng qǐlái jīntiān shì māma de shēngrì.","vi":"Anh ấy chợt nhớ ra hôm nay là sinh nhật mẹ.","en":"He suddenly remembered that today is his mom's birthday."},{"use":"Tính từ: 太突然了.","ex":"这件事太突然了。","py":"Zhè jiàn shì tài tūrán le.","vi":"Chuyện này đột ngột quá.","en":"This is too sudden."},{"use":"V + 得 + 很突然: xảy ra bất ngờ.","ex":"这个消息来得很突然。","py":"Zhège xiāoxi lái de hěn tūrán.","vi":"Tin này đến rất đột ngột.","en":"This news came very suddenly."}]},"生病":{"en":"to get sick; to fall ill","exs":[{"use":"Dùng với 了 khi nói một lần bị ốm cụ thể.","ex":"他昨天生病了，没去上班。","py":"Tā zuótiān shēng bìng le, méi qù shàng bān.","vi":"Hôm qua anh ấy bị ốm nên không đi làm.","en":"He was sick yesterday and didn't go to work."},{"use":"生病了: nhiều người cùng bị bệnh (do thời tiết...).","ex":"天气变冷，很多人生病了。","py":"Tiānqì biàn lěng, hěn duō rén shēng bìng le.","vi":"Trời trở lạnh, nhiều người bị ốm.","en":"The weather turned cold and many people got sick."},{"use":"Chủ ngữ là người thân; kèm mệnh đề cảm xúc.","ex":"孩子生病了，妈妈很担心。","py":"Háizi shēng bìng le, māma hěn dānxīn.","vi":"Con bị ốm, mẹ rất lo lắng.","en":"The child is sick and his mother is very worried."},{"use":"生病 + khoảng thời gian + 了: đã ốm bao lâu.","ex":"她生病三天了，今天才好。","py":"Tā shēng bìng sān tiān le, jīntiān cái hǎo.","vi":"Cô ấy ốm ba ngày, hôm nay mới khỏi.","en":"She was ill for three days and only recovered today."}]},"住院":{"en":"to be hospitalized; to stay in hospital","exs":[{"use":"Động từ ly hợp: 住院 = nằm viện.","ex":"奶奶生病住院了。","py":"Nǎinai shēng bìng zhùyuàn le.","vi":"Bà nội bị bệnh phải nằm viện.","en":"Grandma got sick and was hospitalized."},{"use":"住院 + khoảng thời gian.","ex":"他已经住院一个星期了。","py":"Tā yǐjīng zhùyuàn yí gè xīngqī le.","vi":"Anh ấy đã nằm viện một tuần rồi.","en":"He has been in the hospital for a week."},{"use":"需要住院 + động từ: cần nhập viện để...","ex":"医生说你需要住院检查。","py":"Yīshēng shuō nǐ xūyào zhùyuàn jiǎnchá.","vi":"Bác sĩ nói bạn cần nhập viện để kiểm tra.","en":"The doctor says you need to be admitted for tests."},{"use":"住院的时候: trong thời gian nằm viện.","ex":"住院的时候，朋友来看我。","py":"Zhùyuàn de shíhou, péngyou lái kàn wǒ.","vi":"Lúc nằm viện, bạn bè đến thăm tôi.","en":"My friends came to see me while I was in the hospital."}]},"交给":{"en":"to hand over to; to entrust to","exs":[{"use":"交给 + người: đưa/nộp cho ai.","ex":"请把作业交给老师。","py":"Qǐng bǎ zuòyè jiāogěi lǎoshī.","vi":"Xin hãy nộp bài tập cho thầy giáo.","en":"Please hand your homework in to the teacher."},{"use":"交给我吧: giao cho tôi (đảm nhận việc).","ex":"这件事就交给我吧。","py":"Zhè jiàn shì jiù jiāogěi wǒ ba.","vi":"Việc này cứ giao cho tôi.","en":"Leave this to me."},{"use":"把 + vật + 交给 + người.","ex":"他把钥匙交给了我。","py":"Tā bǎ yàoshi jiāogěi le wǒ.","vi":"Anh ấy đưa chìa khóa cho tôi.","en":"He handed the key to me."},{"use":"Giao nhiệm vụ trong công việc.","ex":"经理把新项目交给了小王。","py":"Jīnglǐ bǎ xīn xiàngmù jiāogěi le Xiǎo Wáng.","vi":"Giám đốc giao dự án mới cho Tiểu Vương.","en":"The manager assigned the new project to Xiao Wang."}]},"一共":{"en":"altogether; in total","exs":[{"use":"Hỏi tổng số: 一共 + 多少.","ex":"这些一共多少钱？","py":"Zhèxiē yígòng duōshao qián?","vi":"Những thứ này tổng cộng bao nhiêu tiền?","en":"How much is it altogether?"},{"use":"一共 + có/là + số lượng.","ex":"我们班一共有三十个学生。","py":"Wǒmen bān yígòng yǒu sānshí gè xuésheng.","vi":"Lớp chúng tôi có tổng cộng ba mươi học sinh.","en":"There are thirty students in our class in total."},{"use":"一共 + động từ + số lượng.","ex":"我们一共去了五个城市。","py":"Wǒmen yígòng qù le wǔ gè chéngshì.","vi":"Chúng tôi đã đi tổng cộng năm thành phố.","en":"We visited five cities in total."},{"use":"一共 + số từ + lượng từ (khi tính tiền).","ex":"一共三百块，可以刷卡吗？","py":"Yígòng sānbǎi kuài, kěyǐ shuā kǎ ma?","vi":"Tổng cộng ba trăm đồng, có thể quẹt thẻ không?","en":"That's 300 yuan altogether; can I pay by card?"}]},"经过":{"en":"to pass through; to go through; process","exs":[{"use":"经过 + địa điểm: đi ngang qua.","ex":"我回家要经过一个公园。","py":"Wǒ huí jiā yào jīngguò yí gè gōngyuán.","vi":"Về nhà tôi phải đi ngang qua một công viên.","en":"I have to pass a park on my way home."},{"use":"经过 + sự nỗ lực/quá trình, + kết quả.","ex":"经过努力，他通过了考试。","py":"Jīngguò nǔlì, tā tōngguò le kǎoshì.","vi":"Nhờ nỗ lực, anh ấy đã thi đỗ.","en":"After hard work, he passed the exam."},{"use":"经过 + sự việc: sau khi trải qua.","ex":"经过这件事，我明白了很多。","py":"Jīngguò zhè jiàn shì, wǒ míngbai le hěn duō.","vi":"Sau chuyện này, tôi hiểu ra rất nhiều.","en":"After this incident, I understood a lot."},{"use":"Danh từ: 事情的经过 = diễn biến sự việc.","ex":"请你说一下事情的经过。","py":"Qǐng nǐ shuō yíxià shìqing de jīngguò.","vi":"Xin bạn kể lại diễn biến sự việc.","en":"Please tell me how it all happened."}]},"笔试":{"en":"written test; written examination","exs":[{"use":"Làm chủ ngữ, đi với giờ giấc.","ex":"笔试在上午九点开始。","py":"Bǐshì zài shàngwǔ jiǔ diǎn kāishǐ.","vi":"Thi viết bắt đầu lúc chín giờ sáng.","en":"The written test starts at nine in the morning."},{"use":"通过笔试: qua vòng thi viết; thường đi với 面试.","ex":"他通过了笔试，下周面试。","py":"Tā tōngguò le bǐshì, xià zhōu miànshì.","vi":"Anh ấy đã qua vòng thi viết, tuần sau phỏng vấn.","en":"He passed the written test and has an interview next week."},{"use":"Cấu trúc: 笔试有…部分.","ex":"这次笔试有三个部分。","py":"Zhè cì bǐshì yǒu sān gè bùfen.","vi":"Bài thi viết lần này có ba phần.","en":"This written test has three parts."},{"use":"So sánh 笔试 với 面试 bằng 比.","ex":"你觉得笔试比面试难吗？","py":"Nǐ juéde bǐshì bǐ miànshì nán ma?","vi":"Bạn thấy thi viết khó hơn phỏng vấn không?","en":"Do you think the written test is harder than the interview?"}]},"材料":{"en":"material; materials; data; documents","exs":[{"use":"Nghĩa: hồ sơ, giấy tờ cần chuẩn bị.","ex":"请准备好所有的材料。","py":"Qǐng zhǔnbèi hǎo suǒyǒu de cáiliào.","vi":"Xin hãy chuẩn bị đầy đủ tất cả hồ sơ.","en":"Please get all the documents ready."},{"use":"Nghĩa: vật liệu để chế tạo.","ex":"这座桥是用特殊材料做的。","py":"Zhè zuò qiáo shì yòng tèshū cáiliào zuò de.","vi":"Cây cầu này được làm bằng vật liệu đặc biệt.","en":"This bridge is made of a special material."},{"use":"Nghĩa: tư liệu để viết/nghiên cứu.","ex":"我在图书馆找写论文的材料。","py":"Wǒ zài túshūguǎn zhǎo xiě lùnwén de cáiliào.","vi":"Tôi tìm tài liệu viết luận văn ở thư viện.","en":"I'm looking for material for my paper in the library."},{"use":"交材料: nộp hồ sơ.","ex":"报名需要交哪些材料？","py":"Bàomíng xūyào jiāo nǎxiē cáiliào?","vi":"Đăng ký cần nộp những hồ sơ gì?","en":"What documents are required for registration?"}]},"比较":{"en":"fairly; relatively; rather; to compare","exs":[{"use":"比较 + tính từ: khá/tương đối…","ex":"这件衣服比较适合你。","py":"Zhè jiàn yīfu bǐjiào shìhé nǐ.","vi":"Bộ quần áo này khá hợp với bạn.","en":"This piece of clothing suits you quite well."},{"use":"Phó từ + adj: mức độ vừa phải.","ex":"今天比较冷，多穿点儿。","py":"Jīntiān bǐjiào lěng, duō chuān diǎnr.","vi":"Hôm nay khá lạnh, mặc thêm chút.","en":"It's rather cold today, dress warmly."},{"use":"Động từ: 比较一下 = so sánh thử.","ex":"买东西前，我喜欢比较一下价格。","py":"Mǎi dōngxi qián, wǒ xǐhuan bǐjiào yíxià jiàgé.","vi":"Trước khi mua đồ, tôi thích so sánh giá một chút.","en":"Before buying things, I like to compare prices."},{"use":"比较起来: so sánh với nhau thì…","ex":"这两个手机比较起来，这个更便宜。","py":"Zhè liǎng gè shǒujī bǐjiào qǐlái, zhège gèng piányi.","vi":"So sánh hai chiếc điện thoại này thì cái này rẻ hơn.","en":"Comparing these two phones, this one is cheaper."}]},"符合":{"en":"to conform to; to match; to meet","exs":[{"use":"符合 + điều kiện / tiêu chuẩn.","ex":"他符合这个工作的条件。","py":"Tā fúhé zhège gōngzuò de tiáojiàn.","vi":"Anh ấy đáp ứng điều kiện của công việc này.","en":"He meets the requirements for this job."},{"use":"不符合 + sự thật.","ex":"这个说法不符合事实。","py":"Zhège shuōfǎ bù fúhé shìshí.","vi":"Cách nói này không phù hợp với sự thật.","en":"This claim doesn't match the facts."},{"use":"符合 + khẩu vị / sở thích.","ex":"这家饭店的菜符合我的口味。","py":"Zhè jiā fàndiàn de cài fúhé wǒ de kǒuwèi.","vi":"Món ăn của nhà hàng này hợp khẩu vị tôi.","en":"The food at this restaurant suits my taste."},{"use":"必须符合 + yêu cầu / quy định.","ex":"产品必须符合安全要求。","py":"Chǎnpǐn bìxū fúhé ānquán yāoqiú.","vi":"Sản phẩm phải đáp ứng yêu cầu an toàn.","en":"Products must meet safety requirements."}]},"要求":{"en":"to require; to demand; requirement","exs":[{"use":"Động từ: 要求 + người + động từ.","ex":"老师要求我们每天写日记。","py":"Lǎoshī yāoqiú wǒmen měitiān xiě rìjì.","vi":"Thầy giáo yêu cầu chúng tôi viết nhật ký mỗi ngày.","en":"The teacher requires us to write a diary every day."},{"use":"Danh từ: 对…的要求.","ex":"公司对员工的要求很高。","py":"Gōngsī duì yuángōng de yāoqiú hěn gāo.","vi":"Công ty có yêu cầu rất cao đối với nhân viên.","en":"The company has high demands of its employees."},{"use":"提出要求: đưa ra yêu cầu.","ex":"他提出了一个很小的要求。","py":"Tā tíchū le yí gè hěn xiǎo de yāoqiú.","vi":"Anh ấy đưa ra một yêu cầu rất nhỏ.","en":"He made a very small request."},{"use":"Danh từ làm chủ ngữ + 太高.","ex":"这个要求太高了，我做不到。","py":"Zhège yāoqiú tài gāo le, wǒ zuò bú dào.","vi":"Yêu cầu này cao quá, tôi không làm được.","en":"This requirement is too high; I can't do it."}]},"办公室":{"en":"office","exs":[{"use":"Nơi làm việc trong cơ quan.","ex":"他在办公室工作。","py":"Tā zài bàngōngshì gōngzuò.","vi":"Anh ấy làm việc ở văn phòng.","en":"He works in the office."},{"use":"在办公室 + động từ: chỉ nơi chốn.","ex":"经理在办公室等你。","py":"Jīnglǐ zài bàngōngshì děng nǐ.","vi":"Giám đốc đang đợi bạn ở văn phòng.","en":"The manager is waiting for you in the office."},{"use":"办公室 + vị trí tòa nhà.","ex":"我们的办公室在五楼。","py":"Wǒmen de bàngōngshì zài wǔ lóu.","vi":"Văn phòng của chúng tôi ở tầng năm.","en":"Our office is on the fifth floor."},{"use":"走进办公室: đi vào văn phòng.","ex":"他走进办公室，打开了电脑。","py":"Tā zǒujìn bàngōngshì, dǎkāi le diànnǎo.","vi":"Anh ấy bước vào văn phòng và bật máy tính.","en":"He walked into the office and turned on the computer."}]},"马上":{"en":"immediately; at once; right away","exs":[{"use":"马上 + động từ: ngay lập tức.","ex":"请等一下，我马上来。","py":"Qǐng děng yíxià, wǒ mǎshàng lái.","vi":"Xin đợi một chút, tôi đến ngay.","en":"Please wait a moment, I'll be right there."},{"use":"马上就要…了: sắp sửa.","ex":"电影马上就要开始了。","py":"Diànyǐng mǎshàng jiù yào kāishǐ le.","vi":"Bộ phim sắp bắt đầu rồi.","en":"The movie is about to start."},{"use":"Lời đề nghị làm gấp.","ex":"你马上给他回电话吧。","py":"Nǐ mǎshàng gěi tā huí diànhuà ba.","vi":"Bạn gọi lại cho anh ấy ngay đi.","en":"Call him back right away."},{"use":"Dặn dò: 到了马上…","ex":"到了马上给我发信息。","py":"Dào le mǎshàng gěi wǒ fā xìnxī.","vi":"Đến nơi thì nhắn tin cho tôi ngay.","en":"Message me as soon as you arrive."}]},"好久不见":{"en":"long time no see","exs":[{"use":"Câu chào khi gặp lại người lâu không gặp.","ex":"好久不见，你最近怎么样？","py":"Hǎojiǔ bú jiàn, nǐ zuìjìn zěnmeyàng?","vi":"Lâu rồi không gặp, dạo này bạn thế nào?","en":"Long time no see, how have you been?"},{"use":"Kèm lời nhận xét sau khi chào.","ex":"好久不见，你还是那么年轻！","py":"Hǎojiǔ bú jiàn, nǐ háishi nàme niánqīng!","vi":"Lâu rồi không gặp, bạn vẫn trẻ như xưa!","en":"Long time no see, you still look so young!"},{"use":"Dùng như vị ngữ + 了: lâu rồi chưa gặp.","ex":"我们好久不见了，一起吃顿饭吧。","py":"Wǒmen hǎojiǔ bú jiàn le, yìqǐ chī dùn fàn ba.","vi":"Chúng ta lâu không gặp rồi, cùng ăn bữa cơm nhé.","en":"We haven't seen each other in ages; let's have a meal together."}]},"律师":{"en":"lawyer; attorney","exs":[{"use":"Chỉ nghề nghiệp: 一名律师.","ex":"我哥哥是一名律师。","py":"Wǒ gēge shì yì míng lǜshī.","vi":"Anh trai tôi là một luật sư.","en":"My older brother is a lawyer."},{"use":"请律师: thuê luật sư.","ex":"你可以请律师帮你看看合同。","py":"Nǐ kěyǐ qǐng lǜshī bāng nǐ kànkan hétong.","vi":"Bạn có thể thuê luật sư xem giúp hợp đồng.","en":"You can hire a lawyer to look over the contract."},{"use":"当律师: làm luật sư (nói về nghề nghiệp mong muốn).","ex":"她想当律师，所以学习法律。","py":"Tā xiǎng dāng lǜshī, suǒyǐ xuéxí fǎlǜ.","vi":"Cô ấy muốn làm luật sư nên học luật.","en":"She wants to be a lawyer, so she studies law."}]},"满意":{"en":"satisfied; pleased","exs":[{"use":"对…满意: hài lòng với...","ex":"我对这份工作很满意。","py":"Wǒ duì zhè fèn gōngzuò hěn mǎnyì.","vi":"Tôi rất hài lòng với công việc này.","en":"I'm very satisfied with this job."},{"use":"Chủ ngữ là khách hàng: 对…非常满意.","ex":"客人对服务非常满意。","py":"Kèrén duì fúwù fēicháng mǎnyì.","vi":"Khách hàng rất hài lòng với dịch vụ.","en":"The guests are very pleased with the service."},{"use":"Câu hỏi: 满意吗?","ex":"这个答案你满意吗？","py":"Zhège dáàn nǐ mǎnyì ma?","vi":"Bạn có hài lòng với đáp án này không?","en":"Are you satisfied with this answer?"},{"use":"让 + người + 满意: khiến ai hài lòng.","ex":"他的成绩让爸爸很满意。","py":"Tā de chéngjì ràng bàba hěn mǎnyì.","vi":"Thành tích của cậu ấy khiến bố rất hài lòng.","en":"His grades made his dad very pleased."}]},"专业":{"en":"major; specialty; professional","exs":[{"use":"Danh từ: chuyên ngành học.","ex":"我的专业是经济。","py":"Wǒ de zhuānyè shì jīngjì.","vi":"Chuyên ngành của tôi là kinh tế.","en":"My major is economics."},{"use":"Hỏi chuyên ngành: 学的是什么专业.","ex":"你大学学的是什么专业？","py":"Nǐ dàxué xué de shì shénme zhuānyè?","vi":"Bạn học chuyên ngành gì ở đại học?","en":"What did you major in at university?"},{"use":"Tính từ: 很专业 = rất chuyên nghiệp.","ex":"这位医生非常专业。","py":"Zhè wèi yīshēng fēicháng zhuānyè.","vi":"Vị bác sĩ này rất chuyên nghiệp.","en":"This doctor is very professional."},{"use":"专业 + 的 + danh từ: làm định ngữ.","ex":"他是专业的翻译。","py":"Tā shì zhuānyè de fānyì.","vi":"Anh ấy là phiên dịch viên chuyên nghiệp.","en":"He is a professional translator."},{"use":"专业知识 = kiến thức chuyên môn.","ex":"做这份工作需要专业知识。","py":"Zuò zhè fèn gōngzuò xūyào zhuānyè zhīshi.","vi":"Làm công việc này cần có kiến thức chuyên môn.","en":"This job requires professional knowledge."}]},"另外":{"en":"besides; in addition; another; other","exs":[{"use":"Dùng để bổ sung thông tin mới.","ex":"另外，我还有一个问题。","py":"Lìngwài, wǒ hái yǒu yí gè wèntí.","vi":"Ngoài ra, tôi còn một câu hỏi.","en":"In addition, I have another question."},{"use":"Nối câu: ..., 另外还… (ngoài ra còn).","ex":"我买了苹果，另外还买了一些香蕉。","py":"Wǒ mǎi le píngguǒ, lìngwài hái mǎi le yìxiē xiāngjiāo.","vi":"Tôi mua táo, ngoài ra còn mua một ít chuối.","en":"I bought apples, and some bananas as well."},{"use":"另外 + (一)+ lượng từ + danh từ: một cái khác.","ex":"这个不行，我们换另外一个吧。","py":"Zhège bù xíng, wǒmen huàn lìngwài yí gè ba.","vi":"Cái này không được, chúng ta đổi sang cái khác nhé.","en":"This one won't work; let's switch to another one."},{"use":"另外 mở đầu câu để chuyển sang thông báo khác.","ex":"另外，明天的会改到下午了。","py":"Lìngwài, míngtiān de huì gǎi dào xiàwǔ le.","vi":"Ngoài ra, cuộc họp ngày mai đã dời sang chiều.","en":"Also, tomorrow's meeting has been moved to the afternoon."}]},"收入":{"en":"income; revenue","exs":[{"use":"收入高 / 收入低.","ex":"他的收入比以前高了。","py":"Tā de shōurù bǐ yǐqián gāo le.","vi":"Thu nhập của anh ấy cao hơn trước.","en":"His income is higher than before."},{"use":"Mỗi tháng + 的 + 收入.","ex":"他每个月的收入不太稳定。","py":"Tā měi gè yuè de shōurù bú tài wěndìng.","vi":"Thu nhập hằng tháng của anh ấy không ổn định lắm.","en":"His monthly income isn't very stable."},{"use":"Hỏi về thu nhập của công việc.","ex":"这份工作的收入怎么样？","py":"Zhè fèn gōngzuò de shōurù zěnmeyàng?","vi":"Thu nhập của công việc này thế nào?","en":"How is the pay for this job?"},{"use":"收入 + 靠/来自: nguồn thu nhập.","ex":"家里的收入主要靠爸爸的工作。","py":"Jiāli de shōurù zhǔyào kào bàba de gōngzuò.","vi":"Thu nhập của gia đình chủ yếu nhờ công việc của bố.","en":"The family's income mainly depends on Dad's job."}]},"咱们":{"en":"we; us (including the listener)","exs":[{"use":"Rủ rê, đề nghị: 咱们 + động từ + 吧.","ex":"咱们一起去吧！","py":"Zánmen yìqǐ qù ba!","vi":"Chúng ta cùng đi nhé!","en":"Let's go together!"},{"use":"Hỏi bàn bạc: 咱们 + ở đâu / khi nào.","ex":"咱们明天在哪儿见面？","py":"Zánmen míngtiān zài nǎr jiàn miàn?","vi":"Ngày mai chúng ta gặp nhau ở đâu?","en":"Where shall we meet tomorrow?"},{"use":"咱们 gồm cả người nghe, khẩu ngữ miền Bắc.","ex":"时间不早了，咱们回家吧。","py":"Shíjiān bù zǎo le, zánmen huí jiā ba.","vi":"Muộn rồi, chúng ta về nhà thôi.","en":"It's getting late, let's go home."},{"use":"咱们 + danh từ: thể hiện sự thân thiết.","ex":"咱们班的同学都很友好。","py":"Zánmen bān de tóngxué dōu hěn yǒuhǎo.","vi":"Các bạn trong lớp chúng ta đều rất thân thiện.","en":"Everyone in our class is very friendly."}]},"北京":{"en":"Beijing","exs":[{"use":"Tên thành phố làm tân ngữ: 去北京.","ex":"我明年想去北京旅游。","py":"Wǒ míngnián xiǎng qù Běijīng lǚyóu.","vi":"Sang năm tôi muốn đi Bắc Kinh du lịch.","en":"I want to travel to Beijing next year."},{"use":"北京 + 的 + danh từ: làm định ngữ.","ex":"北京的冬天很冷。","py":"Běijīng de dōngtiān hěn lěng.","vi":"Mùa đông ở Bắc Kinh rất lạnh.","en":"Winter in Beijing is very cold."},{"use":"Giới thiệu: 北京是中国的首都.","ex":"北京是中国的首都。","py":"Běijīng shì Zhōngguó de shǒudū.","vi":"Bắc Kinh là thủ đô của Trung Quốc.","en":"Beijing is the capital of China."},{"use":"从…到北京: đi đến Bắc Kinh.","ex":"从上海到北京坐高铁要几个小时？","py":"Cóng Shànghǎi dào Běijīng zuò gāotiě yào jǐ gè xiǎoshí?","vi":"Từ Thượng Hải đến Bắc Kinh đi tàu cao tốc mất mấy tiếng?","en":"How many hours does it take to go from Shanghai to Beijing by high-speed train?"}]},"安排":{"en":"to arrange; to plan; arrangement","exs":[{"use":"安排 + người + động từ: sắp xếp ai làm gì.","ex":"经理安排我去出差。","py":"Jīnglǐ ānpái wǒ qù chūchāi.","vi":"Giám đốc sắp xếp cho tôi đi công tác.","en":"The manager arranged for me to go on a business trip."},{"use":"安排好 + thời gian / việc: sắp xếp xong.","ex":"你把时间安排好了吗？","py":"Nǐ bǎ shíjiān ānpái hǎo le ma?","vi":"Bạn đã sắp xếp xong thời gian chưa?","en":"Have you arranged your time?"},{"use":"Danh từ: 有什么安排 = có kế hoạch gì.","ex":"这个周末你有什么安排？","py":"Zhège zhōumò nǐ yǒu shénme ānpái?","vi":"Cuối tuần này bạn có kế hoạch gì không?","en":"What are your plans this weekend?"},{"use":"听…的安排: nghe theo sự sắp xếp.","ex":"我们听公司的安排。","py":"Wǒmen tīng gōngsī de ānpái.","vi":"Chúng tôi nghe theo sự sắp xếp của công ty.","en":"We follow the company's arrangements."}]},"见见面":{"en":"to meet up (a casual meeting)","exs":[{"use":"Dạng lặp của 见面, mang sắc thái nhẹ nhàng: gặp nhau chút.","ex":"我们找个时间见见面吧。","py":"Wǒmen zhǎo gè shíjiān jiànjiànmiàn ba.","vi":"Chúng ta tìm lúc nào đó gặp nhau nhé.","en":"Let's find a time to meet up."},{"use":"跟 + người + 见见面.","ex":"老朋友好久没见，想跟他见见面。","py":"Lǎo péngyou hǎojiǔ méi jiàn, xiǎng gēn tā jiànjiànmiàn.","vi":"Lâu rồi không gặp bạn cũ, muốn gặp anh ấy một chút.","en":"I haven't seen my old friend in a long time and want to meet him."},{"use":"Rủ cả nhóm gặp gỡ trò chuyện.","ex":"周末有空的话，大家见见面聊聊。","py":"Zhōumò yǒu kòng dehuà, dàjiā jiànjiànmiàn liáoliao.","vi":"Nếu cuối tuần rảnh, mọi người gặp nhau trò chuyện nhé.","en":"If you're free this weekend, let's all get together and chat."}]},"按照":{"en":"according to; in accordance with","exs":[{"use":"按照 + kế hoạch / quy định + động từ.","ex":"请按照说明书使用。","py":"Qǐng ànzhào shuōmíngshū shǐyòng.","vi":"Xin hãy sử dụng theo hướng dẫn.","en":"Please use it according to the instructions."},{"use":"按照计划: theo kế hoạch (đứng đầu câu).","ex":"按照计划，我们下周出发。","py":"Ànzhào jìhuà, wǒmen xià zhōu chūfā.","vi":"Theo kế hoạch, tuần sau chúng ta xuất phát.","en":"According to the plan, we leave next week."},{"use":"按照 + yêu cầu của ai.","ex":"请按照老师的要求完成作业。","py":"Qǐng ànzhào lǎoshī de yāoqiú wánchéng zuòyè.","vi":"Xin hãy làm bài tập theo yêu cầu của thầy giáo.","en":"Please finish your homework according to the teacher's requirements."},{"use":"按照 + ý nghĩ của bản thân.","ex":"他按照自己的想法做了决定。","py":"Tā ànzhào zìjǐ de xiǎngfǎ zuò le juédìng.","vi":"Anh ấy quyết định theo suy nghĩ của riêng mình.","en":"He made the decision based on his own ideas."}]},"计划":{"en":"plan; to plan","exs":[{"use":"Danh từ: 有一个…计划.","ex":"我们有一个旅行计划。","py":"Wǒmen yǒu yí gè lǚxíng jìhuà.","vi":"Chúng tôi có một kế hoạch đi du lịch.","en":"We have a travel plan."},{"use":"Động từ: 计划 + động từ (dự định).","ex":"我计划明年去国外学习。","py":"Wǒ jìhuà míngnián qù guówài xuéxí.","vi":"Tôi dự định sang năm ra nước ngoài học.","en":"I plan to study abroad next year."},{"use":"学习计划: kế hoạch học tập.","ex":"你有什么学习计划？","py":"Nǐ yǒu shénme xuéxí jìhuà?","vi":"Bạn có kế hoạch học tập gì?","en":"What is your study plan?"},{"use":"Danh từ làm chủ ngữ.","ex":"这个计划需要很多钱。","py":"Zhège jìhuà xūyào hěn duō qián.","vi":"Kế hoạch này cần rất nhiều tiền.","en":"This plan needs a lot of money."}]},"完成":{"en":"to complete; to finish; to accomplish","exs":[{"use":"完成 + nhiệm vụ / công việc.","ex":"他已经完成了作业。","py":"Tā yǐjīng wánchéng le zuòyè.","vi":"Anh ấy đã làm xong bài tập.","en":"He has already finished his homework."},{"use":"在…前完成: hoàn thành trước thời hạn.","ex":"请在周五前完成报告。","py":"Qǐng zài zhōuwǔ qián wánchéng bàogào.","vi":"Xin hoàn thành báo cáo trước thứ Sáu.","en":"Please finish the report before Friday."},{"use":"很难完成: khó hoàn thành.","ex":"这个任务很难完成。","py":"Zhège rènwu hěn nán wánchéng.","vi":"Nhiệm vụ này rất khó hoàn thành.","en":"This task is hard to complete."},{"use":"完成以后: sau khi hoàn thành.","ex":"完成以后，你可以休息。","py":"Wánchéng yǐhòu, nǐ kěyǐ xiūxi.","vi":"Hoàn thành xong, bạn có thể nghỉ ngơi.","en":"Once it's done, you can rest."}]},"解决":{"en":"to solve; to resolve; to settle","exs":[{"use":"解决 + vấn đề / khó khăn.","ex":"这个问题很快就解决了。","py":"Zhège wèntí hěn kuài jiù jiějué le.","vi":"Vấn đề này đã được giải quyết rất nhanh.","en":"This problem was solved very quickly."},{"use":"想办法解决: tìm cách giải quyết.","ex":"我们得想办法解决这个困难。","py":"Wǒmen děi xiǎng bànfǎ jiějué zhège kùnnan.","vi":"Chúng ta phải tìm cách giải quyết khó khăn này.","en":"We have to find a way to solve this difficulty."},{"use":"还没有解决: chưa được giải quyết.","ex":"这件事还没有解决。","py":"Zhè jiàn shì hái méiyǒu jiějué.","vi":"Chuyện này vẫn chưa được giải quyết.","en":"This matter hasn't been resolved yet."},{"use":"一起解决: cùng nhau giải quyết.","ex":"有问题就说出来，大家一起解决。","py":"Yǒu wèntí jiù shuō chūlái, dàjiā yìqǐ jiějué.","vi":"Có vấn đề thì cứ nói ra, mọi người cùng giải quyết.","en":"If there's a problem, speak up and we'll solve it together."}]},"感谢":{"en":"to thank; thanks; gratitude","exs":[{"use":"感谢 + người / 感谢…的 + danh từ.","ex":"非常感谢你的帮助。","py":"Fēicháng gǎnxiè nǐ de bāngzhù.","vi":"Vô cùng cảm ơn sự giúp đỡ của bạn.","en":"Thank you very much for your help."},{"use":"感谢 + người + động từ: cảm ơn vì đã làm gì.","ex":"感谢大家今天来参加。","py":"Gǎnxiè dàjiā jīntiān lái cānjiā.","vi":"Cảm ơn mọi người hôm nay đã đến tham dự.","en":"Thank you all for coming today."},{"use":"要感谢 + người: muốn cảm ơn.","ex":"我要感谢我的父母。","py":"Wǒ yào gǎnxiè wǒ de fùmǔ.","vi":"Tôi muốn cảm ơn bố mẹ mình.","en":"I want to thank my parents."},{"use":"Danh từ: 接受感谢.","ex":"请接受我们的感谢。","py":"Qǐng jiēshòu wǒmen de gǎnxiè.","vi":"Xin hãy nhận lời cảm ơn của chúng tôi.","en":"Please accept our thanks."}]},"奖金":{"en":"bonus; cash award","exs":[{"use":"发奖金 = phát tiền thưởng.","ex":"公司年底会发奖金。","py":"Gōngsī niándǐ huì fā jiǎngjīn.","vi":"Cuối năm công ty sẽ phát tiền thưởng.","en":"The company pays bonuses at the end of the year."},{"use":"拿到奖金: nhận được tiền thưởng.","ex":"他这个月拿到了两千元奖金。","py":"Tā zhège yuè nádào le liǎng qiān yuán jiǎngjīn.","vi":"Tháng này anh ấy nhận được hai nghìn tệ tiền thưởng.","en":"He received a 2,000 yuan bonus this month."},{"use":"有奖金: có thưởng.","ex":"工作做得好的人会有奖金。","py":"Gōngzuò zuò de hǎo de rén huì yǒu jiǎngjīn.","vi":"Người làm việc tốt sẽ có tiền thưởng.","en":"People who do good work will get a bonus."},{"use":"Tiền thưởng của cuộc thi.","ex":"比赛的奖金是一万元。","py":"Bǐsài de jiǎngjīn shì yí wàn yuán.","vi":"Tiền thưởng của cuộc thi là mười nghìn tệ.","en":"The prize money for the competition is 10,000 yuan."}]},"成绩":{"en":"grades; results; achievement","exs":[{"use":"取得好成绩 = đạt thành tích tốt.","ex":"他的学习成绩很好。","py":"Tā de xuéxí chéngjì hěn hǎo.","vi":"Kết quả học tập của anh ấy rất tốt.","en":"His academic grades are very good."},{"use":"Điểm số / kết quả thi: 成绩 + 公布 / 出来.","ex":"这次考试的成绩什么时候公布？","py":"Zhè cì kǎoshì de chéngjì shénme shíhou gōngbù?","vi":"Khi nào thì công bố điểm thi lần này?","en":"When will the results of this exam be announced?"},{"use":"Thành tích nói chung (trong công việc): 取得……成绩.","ex":"他在工作上取得了很大的成绩。","py":"Tā zài gōngzuò shang qǔdé le hěn dà de chéngjì.","vi":"Anh ấy đã đạt được thành tích lớn trong công việc.","en":"He has achieved great results in his work."},{"use":"成绩 + 进步 / 提高: điểm số tiến bộ.","ex":"老师说我的成绩进步了。","py":"Lǎoshī shuō wǒ de chéngjì jìnbù le.","vi":"Thầy giáo nói điểm của tôi đã tiến bộ.","en":"The teacher said my grades have improved."}]},"赚钱":{"en":"to make money; to earn money","exs":[{"use":"Động từ ly hợp: 赚钱 / 赚了很多钱.","ex":"他想早点儿赚钱。","py":"Tā xiǎng zǎodiǎnr zhuànqián.","vi":"Anh ấy muốn sớm kiếm được tiền.","en":"He wants to start earning money soon."},{"use":"靠 + cách thức + 赚钱: kiếm tiền bằng cách nào.","ex":"他靠网上卖东西赚钱。","py":"Tā kào wǎngshàng mài dōngxi zhuànqián.","vi":"Anh ấy kiếm tiền nhờ bán hàng trên mạng.","en":"He makes money by selling things online."},{"use":"为了 + 多赚钱: mục đích kiếm thêm tiền.","ex":"他每天工作到很晚，就是为了多赚钱。","py":"Tā měitiān gōngzuò dào hěn wǎn, jiùshì wèile duō zhuànqián.","vi":"Ngày nào anh ấy cũng làm việc đến khuya, chỉ để kiếm được nhiều tiền hơn.","en":"He works late every day just to earn more money."},{"use":"赚钱 + (不) 容易: dùng làm chủ ngữ trong câu.","ex":"现在赚钱不容易。","py":"Xiànzài zhuànqián bù róngyì.","vi":"Bây giờ kiếm tiền không dễ.","en":"It isn't easy to make money these days."},{"use":"不一定能 + 赚钱: không chắc kiếm được tiền.","ex":"做生意不一定能赚钱。","py":"Zuò shēngyi bù yídìng néng zhuànqián.","vi":"Làm ăn chưa chắc đã kiếm được tiền.","en":"Doing business doesn't necessarily make money."}]},"工资":{"en":"salary; wages; pay","exs":[{"use":"发工资 = phát lương.","ex":"他的工资不高。","py":"Tā de gōngzī bù gāo.","vi":"Lương của anh ấy không cao.","en":"His salary is not high."},{"use":"发工资: phát lương; 工资 làm tân ngữ.","ex":"这个月的工资已经发了。","py":"Zhège yuè de gōngzī yǐjīng fā le.","vi":"Lương tháng này đã được phát rồi.","en":"This month's salary has already been paid."},{"use":"用……的工资 + V: dùng tiền lương vào việc gì.","ex":"我打算用第一个月的工资给妈妈买礼物。","py":"Wǒ dǎsuàn yòng dì-yī gè yuè de gōngzī gěi māma mǎi lǐwù.","vi":"Tôi định dùng lương tháng đầu tiên để mua quà cho mẹ.","en":"I plan to use my first month's salary to buy a gift for my mom."},{"use":"提高工资: tăng lương.","ex":"公司决定给大家提高工资。","py":"Gōngsī juédìng gěi dàjiā tígāo gōngzī.","vi":"Công ty quyết định tăng lương cho mọi người.","en":"The company decided to raise everyone's salary."}]},"经验":{"en":"experience; know-how","exs":[{"use":"有经验 / 缺少经验.","ex":"他有丰富的工作经验。","py":"Tā yǒu fēngfù de gōngzuò jīngyàn.","vi":"Anh ấy có kinh nghiệm làm việc phong phú.","en":"He has rich work experience."},{"use":"没有 + 方面 + 的经验: chưa có kinh nghiệm về mặt nào.","ex":"我没有这方面的经验。","py":"Wǒ méiyǒu zhè fāngmiàn de jīngyàn.","vi":"Tôi không có kinh nghiệm về mặt này.","en":"I have no experience in this area."},{"use":"Định ngữ + 的 + 经验: kinh nghiệm có được từ việc gì.","ex":"他在国外留学的经验对工作很有帮助。","py":"Tā zài guówài liúxué de jīngyàn duì gōngzuò hěn yǒu bāngzhù.","vi":"Kinh nghiệm du học nước ngoài của anh ấy rất hữu ích cho công việc.","en":"His experience of studying abroad is very helpful for his work."},{"use":"讲 / 分享 + 经验: chia sẻ kinh nghiệm.","ex":"请你给我们讲讲学习汉语的经验。","py":"Qǐng nǐ gěi wǒmen jiǎngjiang xuéxí Hànyǔ de jīngyàn.","vi":"Mời bạn kể cho chúng tôi nghe kinh nghiệm học tiếng Hán.","en":"Please tell us about your experience of learning Chinese."}]},"积累":{"en":"to accumulate; to build up; accumulation","exs":[{"use":"积累 + kinh nghiệm / kiến thức.","ex":"我们要积累生活经验。","py":"Wǒmen yào jīlěi shēnghuó jīngyàn.","vi":"Chúng ta cần tích lũy kinh nghiệm sống.","en":"We need to accumulate life experience."},{"use":"Động từ: 慢慢积累 + từ vựng (tích lũy dần).","ex":"他每天背十个词，慢慢积累了很多词汇。","py":"Tā měitiān bèi shí gè cí, mànmàn jīlěi le hěn duō cíhuì.","vi":"Mỗi ngày anh ấy học thuộc mười từ, dần dần tích lũy được rất nhiều vốn từ.","en":"He memorizes ten words a day and has gradually built up a large vocabulary."},{"use":"一点一点地积累: tích lũy từng chút một (tiền bạc, của cải).","ex":"钱要一点一点地积累。","py":"Qián yào yìdiǎn yìdiǎn de jīlěi.","vi":"Tiền phải tích lũy từng chút một.","en":"Money has to be saved up little by little."},{"use":"Làm danh từ: 多年的积累 = sự tích lũy nhiều năm.","ex":"多年的积累让他成了这方面的专家。","py":"Duō nián de jīlěi ràng tā chéng le zhè fāngmiàn de zhuānjiā.","vi":"Sự tích lũy nhiều năm đã giúp anh ấy trở thành chuyên gia trong lĩnh vực này.","en":"Years of accumulated effort made him an expert in this field."}]},"不得不":{"en":"have to; cannot but; be forced to","exs":[{"use":"不得不 + động từ.","ex":"下雨了，我们不得不回家。","py":"Xià yǔ le, wǒmen bùdébù huí jiā.","vi":"Trời mưa rồi, chúng tôi đành phải về nhà.","en":"It started raining, so we had to go home."},{"use":"Vì lý do sức khỏe nên buộc phải: 不得不 + 请假.","ex":"因为身体不舒服，他不得不请假。","py":"Yīnwèi shēntǐ bù shūfu, tā bùdébù qǐngjià.","vi":"Vì người không khỏe nên anh ấy đành phải xin nghỉ.","en":"Because he felt unwell, he had to take leave."},{"use":"Hoàn cảnh bất đắc dĩ: 不得不 + 走路.","ex":"车坏了，我们不得不走路去公司。","py":"Chē huài le, wǒmen bùdébù zǒulù qù gōngsī.","vi":"Xe hỏng rồi, chúng tôi đành phải đi bộ đến công ty.","en":"The car broke down, so we had to walk to the office."},{"use":"为了……，不得不……: vì mục đích nào đó mà buộc phải hy sinh.","ex":"为了照顾孩子，她不得不辞掉工作。","py":"Wèile zhàogù háizi, tā bùdébù cídiào gōngzuò.","vi":"Để chăm sóc con, cô ấy đành phải nghỉ việc.","en":"To take care of her child, she had no choice but to quit her job."}]},"甚至":{"en":"even; even to the point of","exs":[{"use":"Nhấn mạnh mức độ cao hơn.","ex":"他忙得甚至忘了吃饭。","py":"Tā máng de shènzhì wàng le chīfàn.","vi":"Anh ấy bận đến mức thậm chí quên ăn cơm.","en":"He was so busy that he even forgot to eat."},{"use":"甚至 + động từ: thậm chí còn làm việc gì (mức tăng dần).","ex":"他很喜欢中国文化，甚至开始学写毛笔字。","py":"Tā hěn xǐhuan Zhōngguó wénhuà, shènzhì kāishǐ xué xiě máobǐzì.","vi":"Anh ấy rất thích văn hóa Trung Quốc, thậm chí còn bắt đầu học viết bút lông.","en":"He loves Chinese culture and has even started learning calligraphy."},{"use":"Cấu trúc 甚至连……都……: đến cả … cũng …","ex":"这个问题太简单了，甚至连孩子都会。","py":"Zhège wèntí tài jiǎndān le, shènzhì lián háizi dōu huì.","vi":"Câu hỏi này quá đơn giản, thậm chí đến trẻ con cũng biết làm.","en":"This question is so easy that even a child can do it."},{"use":"甚至 + 没 / 不: nhấn mạnh mức độ tiêu cực.","ex":"他工作太忙，一个星期甚至没回过家。","py":"Tā gōngzuò tài máng, yí gè xīngqī shènzhì méi huí guo jiā.","vi":"Anh ấy bận quá, thậm chí cả tuần không về nhà lần nào.","en":"He is so busy that he hasn't even been home in a week."}]},"责任心":{"en":"sense of responsibility; conscientiousness","exs":[{"use":"有责任心 / 没有责任心.","ex":"做这份工作要有责任心。","py":"Zuò zhè fèn gōngzuò yào yǒu zérènxīn.","vi":"Làm công việc này phải có tinh thần trách nhiệm.","en":"You need a sense of responsibility to do this job."},{"use":"很有责任心: có tinh thần trách nhiệm cao (khen).","ex":"老师说这个孩子很有责任心。","py":"Lǎoshī shuō zhège háizi hěn yǒu zérènxīn.","vi":"Cô giáo nói đứa trẻ này rất có tinh thần trách nhiệm.","en":"The teacher said this child is very responsible."},{"use":"没有责任心: thiếu trách nhiệm (phê bình).","ex":"他做事没有责任心，大家都不放心。","py":"Tā zuòshì méiyǒu zérènxīn, dàjiā dōu bú fàngxīn.","vi":"Anh ấy làm việc thiếu trách nhiệm nên ai cũng không yên tâm.","en":"He is irresponsible at work, so no one feels at ease."},{"use":"多一点儿责任心: mong có thêm tinh thần trách nhiệm.","ex":"经理希望新同事能多一点儿责任心。","py":"Jīnglǐ xīwàng xīn tóngshì néng duō yìdiǎnr zérènxīn.","vi":"Giám đốc hy vọng đồng nghiệp mới có thể có trách nhiệm hơn một chút.","en":"The manager hopes the new colleagues will show a bit more responsibility."}]},"按时":{"en":"on time; on schedule","exs":[{"use":"按时 + động từ.","ex":"请按时交作业。","py":"Qǐng ànshí jiāo zuòyè.","vi":"Xin nộp bài tập đúng hạn.","en":"Please hand in your homework on time."},{"use":"按时 + 上班: đi làm đúng giờ; thường đi với 从来不迟到.","ex":"他每天按时上班，从来不迟到。","py":"Tā měitiān ànshí shàngbān, cónglái bù chídào.","vi":"Ngày nào anh ấy cũng đi làm đúng giờ, chưa bao giờ đến muộn.","en":"He goes to work on time every day and is never late."},{"use":"按时吃药: uống thuốc đúng giờ.","ex":"药要按时吃，病才会好得快。","py":"Yào yào ànshí chī, bìng cái huì hǎo de kuài.","vi":"Phải uống thuốc đúng giờ thì bệnh mới mau khỏi.","en":"Take your medicine on time and you'll recover faster."},{"use":"不能按时 + V: không thể làm đúng giờ.","ex":"如果不能按时到，请提前给我打电话。","py":"Rúguǒ bù néng ànshí dào, qǐng tíqián gěi wǒ dǎ diànhuà.","vi":"Nếu không thể đến đúng giờ, xin hãy gọi điện trước cho tôi.","en":"If you can't arrive on time, please call me in advance."}]},"成功":{"en":"to succeed; successful; success","exs":[{"use":"成功地 + động từ (làm trạng ngữ).","ex":"他成功地完成了任务。","py":"Tā chénggōng de wánchéng le rènwu.","vi":"Anh ấy đã hoàn thành nhiệm vụ một cách thành công.","en":"He successfully completed the task."},{"use":"Làm vị ngữ: 成功了 = đã thành công.","ex":"这次实验终于成功了。","py":"Zhè cì shíyàn zhōngyú chénggōng le.","vi":"Thí nghiệm lần này cuối cùng đã thành công.","en":"The experiment finally succeeded this time."},{"use":"Làm danh từ (chủ ngữ): 成功 = sự thành công.","ex":"成功需要努力和耐心。","py":"Chénggōng xūyào nǔlì hé nàixīn.","vi":"Thành công cần có nỗ lực và sự kiên nhẫn.","en":"Success requires effort and patience."},{"use":"Làm tính từ định ngữ: 成功的 + danh từ.","ex":"他是一位成功的商人。","py":"Tā shì yí wèi chénggōng de shāngrén.","vi":"Ông ấy là một thương nhân thành đạt.","en":"He is a successful businessman."},{"use":"Lời chúc: 祝你……成功！","ex":"祝你考试成功！","py":"Zhù nǐ kǎoshì chénggōng!","vi":"Chúc bạn thi đạt kết quả tốt!","en":"Wishing you success in your exam!"}]},"今年":{"en":"this year","exs":[{"use":"Danh từ chỉ thời gian, đứng trước hoặc sau chủ ngữ.","ex":"今年夏天特别热。","py":"Jīnnián xiàtiān tèbié rè.","vi":"Mùa hè năm nay đặc biệt nóng.","en":"This summer is especially hot."},{"use":"Hỏi tuổi: 你今年多大了？","ex":"你今年多大了？","py":"Nǐ jīnnián duō dà le?","vi":"Năm nay bạn bao nhiêu tuổi rồi?","en":"How old are you this year?"},{"use":"今年 + 打算 / 想: kế hoạch trong năm nay.","ex":"我今年打算去中国旅游。","py":"Wǒ jīnnián dǎsuàn qù Zhōngguó lǚyóu.","vi":"Năm nay tôi định đi du lịch Trung Quốc.","en":"I plan to travel to China this year."},{"use":"今年的 + danh từ; so sánh với 去年.","ex":"今年的生意比去年好。","py":"Jīnnián de shēngyi bǐ qùnián hǎo.","vi":"Việc làm ăn năm nay tốt hơn năm ngoái.","en":"Business this year is better than last year."}]},"中间":{"en":"middle; between; in the midst of","exs":[{"use":"Nơi chốn: ……中间 = ở giữa.","ex":"桌子中间放着一瓶花。","py":"Zhuōzi zhōngjiān fàngzhe yì píng huā.","vi":"Giữa bàn đặt một bình hoa.","en":"There is a vase of flowers in the middle of the table."},{"use":"A 和 B 中间: ở giữa A và B.","ex":"我坐在小王和小李中间。","py":"Wǒ zuò zài Xiǎo Wáng hé Xiǎo Lǐ zhōngjiān.","vi":"Tôi ngồi giữa Tiểu Vương và Tiểu Lý.","en":"I sit between Xiao Wang and Xiao Li."},{"use":"Thời gian: 会议中间 = giữa chừng buổi họp.","ex":"会议中间，他接了一个电话。","py":"Huìyì zhōngjiān, tā jiē le yí gè diànhuà.","vi":"Giữa buổi họp, anh ấy nhận một cuộc điện thoại.","en":"In the middle of the meeting, he took a phone call."},{"use":"Chỉ vị trí trung tâm của một khu vực.","ex":"学校就在两个公园的中间。","py":"Xuéxiào jiù zài liǎng gè gōngyuán de zhōngjiān.","vi":"Trường học nằm ngay giữa hai công viên.","en":"The school is right between the two parks."}]},"努力":{"en":"to try hard; to make an effort; effort","exs":[{"use":"Động từ: 努力 + V (cố gắng làm gì).","ex":"只要努力学习，你一定能通过考试。","py":"Zhǐyào nǔlì xuéxí, nǐ yídìng néng tōngguò kǎoshì.","vi":"Chỉ cần nỗ lực học tập, bạn nhất định sẽ thi đỗ.","en":"As long as you study hard, you will surely pass the exam."},{"use":"Làm vị ngữ / tính từ: 很努力.","ex":"他一直很努力，所以进步很快。","py":"Tā yìzhí hěn nǔlì, suǒyǐ jìnbù hěn kuài.","vi":"Anh ấy luôn rất chăm chỉ nên tiến bộ rất nhanh.","en":"He has always worked hard, so he improves quickly."},{"use":"Làm danh từ: 经过……的努力.","ex":"经过大家的努力，我们完成了任务。","py":"Jīngguò dàjiā de nǔlì, wǒmen wánchéng le rènwu.","vi":"Nhờ nỗ lực của mọi người, chúng tôi đã hoàn thành nhiệm vụ.","en":"Through everyone's efforts, we completed the task."},{"use":"Quyết tâm: 会努力 + V + 的.","ex":"我会努力做好这份工作的。","py":"Wǒ huì nǔlì zuòhǎo zhè fèn gōngzuò de.","vi":"Tôi sẽ cố gắng làm tốt công việc này.","en":"I will do my best to do this job well."}]},"告诉":{"en":"to tell; to let know","exs":[{"use":"告诉 + người + nội dung (hai tân ngữ).","ex":"请告诉我你的电话号码。","py":"Qǐng gàosu wǒ nǐ de diànhuà hàomǎ.","vi":"Xin hãy cho tôi biết số điện thoại của bạn.","en":"Please tell me your phone number."},{"use":"告诉 + người + mệnh đề.","ex":"他告诉我明天不用来上班。","py":"Tā gàosu wǒ míngtiān búyòng lái shàngbān.","vi":"Anh ấy bảo tôi ngày mai không cần đi làm.","en":"He told me I don't need to come to work tomorrow."},{"use":"别 / 不要 + 告诉 + người: đừng nói cho ai.","ex":"这件事别告诉别人。","py":"Zhè jiàn shì bié gàosu biérén.","vi":"Chuyện này đừng nói với người khác.","en":"Don't tell anyone about this."},{"use":"一……就告诉你: có tin là báo ngay.","ex":"有消息我马上告诉你。","py":"Yǒu xiāoxi wǒ mǎshàng gàosu nǐ.","vi":"Có tin tức tôi sẽ báo cho bạn ngay.","en":"I'll let you know as soon as I hear anything."}]},"消息":{"en":"news; information; message","exs":[{"use":"好消息 / 坏消息: tin tốt / tin xấu.","ex":"你听到那个好消息了吗？","py":"Nǐ tīngdào nàge hǎo xiāoxi le ma?","vi":"Bạn đã nghe tin tốt đó chưa?","en":"Have you heard the good news?"},{"use":"没有消息: chưa có tin tức.","ex":"他到现在还没有消息。","py":"Tā dào xiànzài hái méiyǒu xiāoxi.","vi":"Đến giờ vẫn chưa có tin tức gì của anh ấy.","en":"There has been no news from him so far."},{"use":"从……看到 / 听到消息: biết tin từ nguồn nào.","ex":"我是从报纸上看到这个消息的。","py":"Wǒ shì cóng bàozhǐ shang kàndào zhège xiāoxi de.","vi":"Tôi đọc được tin này trên báo.","en":"I saw this news in the newspaper."},{"use":"发消息: nhắn tin (qua điện thoại / ứng dụng).","ex":"到了以后给我发个消息。","py":"Dào le yǐhòu gěi wǒ fā ge xiāoxi.","vi":"Đến nơi rồi thì nhắn cho tôi một tin nhé.","en":"Send me a message when you arrive."}]},"公司":{"en":"company; firm","exs":[{"use":"在 + 公司 + 工作: làm việc ở công ty.","ex":"我在一家贸易公司工作。","py":"Wǒ zài yì jiā màoyì gōngsī gōngzuò.","vi":"Tôi làm việc ở một công ty thương mại.","en":"I work at a trading company."},{"use":"公司 + 离 + địa điểm: khoảng cách đến công ty.","ex":"公司离我家不远，坐地铁二十分钟就到。","py":"Gōngsī lí wǒ jiā bù yuǎn, zuò dìtiě èrshí fēnzhōng jiù dào.","vi":"Công ty cách nhà tôi không xa, đi tàu điện ngầm hai mươi phút là đến.","en":"The company isn't far from my home; it takes twenty minutes by subway."},{"use":"Lượng từ của 公司: 家.","ex":"这家公司有三百多名员工。","py":"Zhè jiā gōngsī yǒu sānbǎi duō míng yuángōng.","vi":"Công ty này có hơn ba trăm nhân viên.","en":"This company has more than 300 employees."},{"use":"公司 làm chủ ngữ của quyết định.","ex":"公司决定下个月开一家新店。","py":"Gōngsī juédìng xià gè yuè kāi yì jiā xīn diàn.","vi":"Công ty quyết định tháng sau mở thêm một cửa hàng mới.","en":"The company has decided to open a new store next month."}]},"希望":{"en":"to hope; to wish; hope","exs":[{"use":"Thường dùng: 希望 + mệnh đề / 希望 + động từ.","ex":"我希望明天是好天气。","py":"Wǒ xīwàng míngtiān shì hǎo tiānqì.","vi":"Tôi hy vọng ngày mai thời tiết đẹp.","en":"I hope the weather will be nice tomorrow."},{"use":"希望 + người + V: mong ai đó làm gì.","ex":"我希望你能来参加我的生日聚会。","py":"Wǒ xīwàng nǐ néng lái cānjiā wǒ de shēngrì jùhuì.","vi":"Tôi hy vọng bạn có thể đến dự tiệc sinh nhật của tôi.","en":"I hope you can come to my birthday party."},{"use":"希望 + V (cùng chủ ngữ): mong muốn bản thân.","ex":"他希望当一名医生。","py":"Tā xīwàng dāng yì míng yīshēng.","vi":"Anh ấy mong muốn trở thành bác sĩ.","en":"He hopes to become a doctor."},{"use":"Làm danh từ: 放弃 / 有 / 充满 + 希望.","ex":"我们不要放弃希望。","py":"Wǒmen búyào fàngqì xīwàng.","vi":"Chúng ta đừng từ bỏ hy vọng.","en":"Let's not give up hope."}]},"明年":{"en":"next year","exs":[{"use":"Danh từ chỉ thời gian: 明年 + động từ.","ex":"明年我打算去北京学汉语。","py":"Míngnián wǒ dǎsuàn qù Běijīng xué Hànyǔ.","vi":"Sang năm tôi định đến Bắc Kinh học tiếng Hán.","en":"Next year I plan to go to Beijing to study Chinese."},{"use":"明年就要……了: sang năm sắp …","ex":"他明年就要毕业了。","py":"Tā míngnián jiù yào bìyè le.","vi":"Sang năm anh ấy sắp tốt nghiệp rồi.","en":"He will graduate next year."},{"use":"明年 + mùa / tháng: thời điểm cụ thể của năm sau.","ex":"我们明年春天结婚。","py":"Wǒmen míngnián chūntiān jiéhūn.","vi":"Mùa xuân năm sau chúng tôi kết hôn.","en":"We are getting married next spring."}]},"眼睛":{"en":"eye(s)","exs":[{"use":"Danh từ chỉ mắt.","ex":"让眼睛休息一下。","py":"Ràng yǎnjing xiūxi yíxià.","vi":"Hãy để mắt nghỉ một chút.","en":"Let your eyes rest for a moment."},{"use":"Miêu tả ngoại hình: 眼睛 + 又……又……","ex":"她的眼睛又大又亮。","py":"Tā de yǎnjing yòu dà yòu liàng.","vi":"Đôi mắt cô ấy vừa to vừa sáng.","en":"Her eyes are big and bright."},{"use":"Sức khỏe: 眼睛 + 累 / 疼 / 红.","ex":"看了一天电脑，我的眼睛很累。","py":"Kàn le yì tiān diànnǎo, wǒ de yǎnjing hěn lèi.","vi":"Nhìn máy tính cả ngày nên mắt tôi rất mỏi.","en":"After looking at a computer all day, my eyes are very tired."},{"use":"Cụm động từ: 闭上 / 睁开 + 眼睛.","ex":"他闭上眼睛想了一会儿。","py":"Tā bìshàng yǎnjing xiǎng le yíhuìr.","vi":"Anh ấy nhắm mắt suy nghĩ một lát.","en":"He closed his eyes and thought for a while."}]},"学习":{"en":"to study; to learn; study","exs":[{"use":"学习 + môn học: học môn gì.","ex":"我每天晚上学习汉语一个小时。","py":"Wǒ měitiān wǎnshang xuéxí Hànyǔ yí gè xiǎoshí.","vi":"Mỗi tối tôi học tiếng Hán một tiếng.","en":"I study Chinese for an hour every evening."},{"use":"Làm vị ngữ: 学习 + 很认真 / 努力.","ex":"他学习非常努力，老师经常表扬他。","py":"Tā xuéxí fēicháng nǔlì, lǎoshī jīngcháng biǎoyáng tā.","vi":"Anh ấy học tập rất chăm chỉ, thầy cô thường khen anh ấy.","en":"He studies very hard, and his teacher often praises him."},{"use":"Làm danh từ (chủ ngữ): 学习 là một việc …","ex":"学习是一件快乐的事。","py":"Xuéxí shì yí jiàn kuàilè de shì.","vi":"Học tập là một việc vui vẻ.","en":"Learning is a joyful thing."},{"use":"向 + người + 学习: học hỏi từ ai.","ex":"我们要向他学习。","py":"Wǒmen yào xiàng tā xuéxí.","vi":"Chúng ta phải học hỏi anh ấy.","en":"We should learn from him."}]},"方法":{"en":"method; way; approach","exs":[{"use":"好方法 / 学习方法: phương pháp tốt / phương pháp học.","ex":"学外语有很多好方法。","py":"Xué wàiyǔ yǒu hěn duō hǎo fāngfǎ.","vi":"Học ngoại ngữ có rất nhiều phương pháp hay.","en":"There are many good methods for learning a foreign language."},{"use":"方法不对 / 换方法: sai cách, đổi cách.","ex":"你的方法不对，换一个试试。","py":"Nǐ de fāngfǎ bú duì, huàn yí gè shìshi.","vi":"Cách của bạn không đúng, thử đổi cách khác xem.","en":"Your method is wrong; try a different one."},{"use":"V + 的 + 方法: phương pháp để làm gì.","ex":"老师教给我们一个记生词的方法。","py":"Lǎoshī jiāo gěi wǒmen yí gè jì shēngcí de fāngfǎ.","vi":"Thầy giáo dạy chúng tôi một cách ghi nhớ từ mới.","en":"The teacher taught us a way to memorize new words."},{"use":"想方法: nghĩ cách, tìm cách.","ex":"我们得想个方法解决这个问题。","py":"Wǒmen děi xiǎng ge fāngfǎ jiějué zhège wèntí.","vi":"Chúng ta phải nghĩ cách giải quyết vấn đề này.","en":"We have to think of a way to solve this problem."}]},"知识":{"en":"knowledge","exs":[{"use":"学到 / 学习 + 知识.","ex":"读书可以让我们学到很多知识。","py":"Dúshū kěyǐ ràng wǒmen xuédào hěn duō zhīshi.","vi":"Đọc sách giúp chúng ta học được rất nhiều kiến thức.","en":"Reading lets us gain a lot of knowledge."},{"use":"Lĩnh vực + 知识: kiến thức về lĩnh vực nào.","ex":"他的历史知识很丰富。","py":"Tā de lìshǐ zhīshi hěn fēngfù.","vi":"Kiến thức lịch sử của anh ấy rất phong phú.","en":"His knowledge of history is very rich."},{"use":"健康知识: kiến thức về sức khỏe; 知识 làm tân ngữ của 介绍.","ex":"这本书介绍了很多健康知识。","py":"Zhè běn shū jièshào le hěn duō jiànkāng zhīshi.","vi":"Cuốn sách này giới thiệu nhiều kiến thức về sức khỏe.","en":"This book introduces a lot of health knowledge."},{"use":"知识 + 就是力量 / 越多越好: nhấn mạnh giá trị tri thức.","ex":"知识越多，机会也越多。","py":"Zhīshi yuè duō, jīhuì yě yuè duō.","vi":"Kiến thức càng nhiều thì cơ hội cũng càng nhiều.","en":"The more knowledge you have, the more opportunities you get."}]},"愿意":{"en":"to be willing; to want to","exs":[{"use":"愿意 + động từ: sẵn lòng làm gì.","ex":"我愿意帮你搬家。","py":"Wǒ yuànyì bāng nǐ bānjiā.","vi":"Tôi sẵn lòng giúp bạn chuyển nhà.","en":"I'm willing to help you move."},{"use":"Câu hỏi: 你愿意……吗？","ex":"你愿意和我一起去旅游吗？","py":"Nǐ yuànyì hé wǒ yìqǐ qù lǚyóu ma?","vi":"Bạn có muốn đi du lịch cùng tôi không?","en":"Would you like to travel with me?"},{"use":"不愿意: không muốn, không bằng lòng.","ex":"他不愿意离开家乡。","py":"Tā bú yuànyì líkāi jiāxiāng.","vi":"Anh ấy không muốn rời quê hương.","en":"He is unwilling to leave his hometown."},{"use":"很愿意 / 非常愿意: rất sẵn lòng (đáp lời mời).","ex":"能和你合作，我非常愿意。","py":"Néng hé nǐ hézuò, wǒ fēicháng yuànyì.","vi":"Được hợp tác với bạn, tôi rất sẵn lòng.","en":"I'd be very happy to work with you."}]},"别提":{"en":"don't mention it; no need to say; (别提多……了) extremely","exs":[{"use":"别提了: đừng nhắc nữa (than phiền, chán nản).","ex":"别提了，今天堵车堵了两个小时。","py":"Biétí le, jīntiān dǔchē dǔ le liǎng gè xiǎoshí.","vi":"Đừng nhắc nữa, hôm nay kẹt xe mất hai tiếng đồng hồ.","en":"Don't even mention it; I was stuck in traffic for two hours today."},{"use":"别提多……了: vô cùng …, không gì bằng.","ex":"听说要放假，大家别提多高兴了。","py":"Tīngshuō yào fàngjià, dàjiā biétí duō gāoxìng le.","vi":"Nghe nói sắp được nghỉ, mọi người vui không tả xiết.","en":"Hearing that vacation is coming, everyone was happy beyond words."},{"use":"别提 + việc: đừng nhắc đến việc gì (không muốn nói lại).","ex":"那件事你就别提了，大家都不想再说。","py":"Nà jiàn shì nǐ jiù biétí le, dàjiā dōu bù xiǎng zài shuō.","vi":"Chuyện đó bạn đừng nhắc nữa, ai cũng không muốn nói thêm.","en":"Don't bring that up again; nobody wants to talk about it."}]},"以为":{"en":"to think (mistakenly); to assume","exs":[{"use":"以为 + mệnh đề: tưởng rằng (thực tế không phải).","ex":"我以为今天是星期五，原来是星期四。","py":"Wǒ yǐwéi jīntiān shì xīngqīwǔ, yuánlái shì xīngqīsì.","vi":"Tôi cứ tưởng hôm nay là thứ Sáu, hóa ra là thứ Năm.","en":"I thought today was Friday, but it turns out to be Thursday."},{"use":"还以为……呢: cứ tưởng …","ex":"我还以为你不来了呢。","py":"Wǒ hái yǐwéi nǐ bù lái le ne.","vi":"Tôi còn tưởng bạn không đến nữa chứ.","en":"I thought you weren't coming."},{"use":"大家都以为: mọi người đều cho rằng (nhưng sai).","ex":"大家都以为他是中国人。","py":"Dàjiā dōu yǐwéi tā shì Zhōngguó rén.","vi":"Mọi người đều tưởng anh ấy là người Trung Quốc.","en":"Everyone assumed he was Chinese."},{"use":"Phân biệt với 认为: 以为 hàm ý phán đoán sai.","ex":"你别以为这件事很容易。","py":"Nǐ bié yǐwéi zhè jiàn shì hěn róngyì.","vi":"Bạn đừng tưởng việc này dễ dàng.","en":"Don't think this is easy."}]},"以前":{"en":"before; in the past; formerly","exs":[{"use":"以前 + câu: ngày trước thì …","ex":"以前我不喜欢喝咖啡，现在每天都喝。","py":"Yǐqián wǒ bù xǐhuan hē kāfēi, xiànzài měitiān dōu hē.","vi":"Trước đây tôi không thích uống cà phê, bây giờ ngày nào cũng uống.","en":"I didn't like coffee before, but now I drink it every day."},{"use":"V + 以前: trước khi làm gì.","ex":"来中国以前，我没学过汉语。","py":"Lái Zhōngguó yǐqián, wǒ méi xué guo Hànyǔ.","vi":"Trước khi đến Trung Quốc, tôi chưa từng học tiếng Hán.","en":"Before coming to China, I had never studied Chinese."},{"use":"Chỉ quá khứ: 这里以前是……","ex":"这里以前是一个小村子。","py":"Zhèlǐ yǐqián shì yí gè xiǎo cūnzi.","vi":"Nơi này trước đây là một ngôi làng nhỏ.","en":"This place used to be a small village."},{"use":"Khoảng thời gian + 以前: cách đây …","ex":"三年以前，他还是个学生。","py":"Sān nián yǐqián, tā hái shì ge xuésheng.","vi":"Ba năm trước, anh ấy vẫn còn là học sinh.","en":"Three years ago, he was still a student."}]},"上次":{"en":"last time; the previous occasion","exs":[{"use":"上次 + 的 / 动词: lần trước đã …","ex":"上次你说的那家餐厅在哪儿？","py":"Shàngcì nǐ shuō de nà jiā cāntīng zài nǎr?","vi":"Nhà hàng lần trước bạn nói nằm ở đâu vậy?","en":"Where is that restaurant you mentioned last time?"},{"use":"上次 làm chủ ngữ: 上次……是……的事.","ex":"上次见面是去年夏天的事了。","py":"Shàngcì jiànmiàn shì qùnián xiàtiān de shì le.","vi":"Lần gặp trước là chuyện của mùa hè năm ngoái rồi.","en":"The last time we met was last summer."},{"use":"上次 + 的 + danh từ: cảm ơn việc lần trước.","ex":"谢谢你上次的帮助。","py":"Xièxie nǐ shàngcì de bāngzhù.","vi":"Cảm ơn sự giúp đỡ của bạn lần trước.","en":"Thank you for your help last time."},{"use":"Đối lập 上次 – 这次 – 下次.","ex":"上次我迟到了，这次一定早点儿来。","py":"Shàngcì wǒ chídào le, zhè cì yídìng zǎodiǎnr lái.","vi":"Lần trước tôi đến muộn, lần này nhất định sẽ đến sớm.","en":"I was late last time; this time I'll definitely come earlier."}]},"完全":{"en":"completely; entirely; totally","exs":[{"use":"完全 + tính từ / động từ: hoàn toàn.","ex":"你说得完全对。","py":"Nǐ shuō de wánquán duì.","vi":"Bạn nói hoàn toàn đúng.","en":"What you said is completely right."},{"use":"完全 + 同意 / 理解: hoàn toàn đồng ý, thấu hiểu.","ex":"我完全同意你的看法。","py":"Wǒ wánquán tóngyì nǐ de kànfǎ.","vi":"Tôi hoàn toàn đồng ý với quan điểm của bạn.","en":"I completely agree with your view."},{"use":"完全 + 不 / 没: hoàn toàn không (phủ định mạnh).","ex":"他完全不知道这件事。","py":"Tā wánquán bù zhīdào zhè jiàn shì.","vi":"Anh ấy hoàn toàn không biết chuyện này.","en":"He knows nothing at all about this."},{"use":"V + 完全: khỏi hẳn / xong hoàn toàn (bổ ngữ kết quả đặt trước 好).","ex":"我的病已经完全好了。","py":"Wǒ de bìng yǐjīng wánquán hǎo le.","vi":"Bệnh của tôi đã khỏi hẳn rồi.","en":"I have fully recovered from my illness."}]},"明白":{"en":"to understand; clear; obvious","exs":[{"use":"Động từ: 明白 = hiểu ra.","ex":"老师讲了两遍，我才明白。","py":"Lǎoshī jiǎng le liǎng biàn, wǒ cái míngbai.","vi":"Thầy giảng hai lượt tôi mới hiểu.","en":"The teacher explained it twice before I understood."},{"use":"明白 + tân ngữ / mệnh đề; câu hỏi 明白吗.","ex":"你明白我的意思吗？","py":"Nǐ míngbai wǒ de yìsi ma?","vi":"Bạn có hiểu ý tôi không?","en":"Do you understand what I mean?"},{"use":"Tính từ / bổ ngữ kết quả: 说明白 = nói cho rõ.","ex":"请你把话说明白一点儿。","py":"Qǐng nǐ bǎ huà shuō míngbai yìdiǎnr.","vi":"Xin bạn hãy nói cho rõ ràng hơn một chút.","en":"Please make yourself a bit clearer."},{"use":"没想明白 / 想明白: nghĩ cho thông.","ex":"这个问题我还没想明白。","py":"Zhège wèntí wǒ hái méi xiǎng míngbai.","vi":"Vấn đề này tôi vẫn chưa nghĩ thông.","en":"I still haven't figured this problem out."}]},"这份":{"en":"this (copy/portion/job)","exs":[{"use":"这份 + 工作: công việc này.","ex":"这份工作很适合你。","py":"Zhè fèn gōngzuò hěn shìhé nǐ.","vi":"Công việc này rất hợp với bạn.","en":"This job suits you very well."},{"use":"这份 + 文件 / 材料: văn kiện này (份 là lượng từ cho tài liệu).","ex":"请把这份文件交给经理。","py":"Qǐng bǎ zhè fèn wénjiàn jiāo gěi jīnglǐ.","vi":"Xin hãy đưa tập tài liệu này cho giám đốc.","en":"Please hand this document to the manager."},{"use":"这份 + 报纸: tờ báo này (lượng từ cho báo).","ex":"这份报纸是今天的。","py":"Zhè fèn bàozhǐ shì jīntiān de.","vi":"Tờ báo này là của hôm nay.","en":"This newspaper is today's."},{"use":"这份 + 礼物 / 心意: món quà, tấm lòng này.","ex":"这份礼物是朋友送我的。","py":"Zhè fèn lǐwù shì péngyou sòng wǒ de.","vi":"Món quà này là bạn tặng tôi.","en":"This gift was given to me by a friend."}]},"做好":{"en":"to do well; to finish doing; to get ready","exs":[{"use":"做好 + việc: làm tốt việc gì.","ex":"我一定会做好这件事。","py":"Wǒ yídìng huì zuòhǎo zhè jiàn shì.","vi":"Tôi nhất định sẽ làm tốt việc này.","en":"I will definitely get this done well."},{"use":"做好 = làm xong (nấu xong): bổ ngữ kết quả 好.","ex":"晚饭已经做好了，快来吃吧。","py":"Wǎnfàn yǐjīng zuòhǎo le, kuài lái chī ba.","vi":"Cơm tối đã nấu xong rồi, mau đến ăn đi.","en":"Dinner is ready; come and eat."},{"use":"做好准备: chuẩn bị sẵn sàng.","ex":"出发以前，请做好准备。","py":"Chūfā yǐqián, qǐng zuòhǎo zhǔnbèi.","vi":"Trước khi xuất phát, xin hãy chuẩn bị cho xong.","en":"Please get ready before we set off."},{"use":"做好 + 本职工作: làm tròn bổn phận.","ex":"每个人都应该做好自己的工作。","py":"Měi gè rén dōu yīnggāi zuòhǎo zìjǐ de gōngzuò.","vi":"Mỗi người đều nên làm tốt công việc của mình.","en":"Everyone should do their own job well."}]},"王经理":{"en":"Manager Wang","exs":[{"use":"Họ + 经理: cách gọi chức danh (Giám đốc Vương).","ex":"王经理正在开会，请您稍等。","py":"Wáng jīnglǐ zhèngzài kāihuì, qǐng nín shāo děng.","vi":"Giám đốc Vương đang họp, xin ông chờ một chút.","en":"Manager Wang is in a meeting; please wait a moment."},{"use":"请 + 王经理 + V: mời giám đốc Vương làm gì.","ex":"我想请王经理看一下这份报告。","py":"Wǒ xiǎng qǐng Wáng jīnglǐ kàn yíxià zhè fèn bàogào.","vi":"Tôi muốn nhờ giám đốc Vương xem qua bản báo cáo này.","en":"I'd like to ask Manager Wang to take a look at this report."},{"use":"王经理 làm chủ ngữ, nhận xét tính cách.","ex":"王经理对工作要求很严格。","py":"Wáng jīnglǐ duì gōngzuò yāoqiú hěn yángé.","vi":"Giám đốc Vương yêu cầu rất nghiêm khắc trong công việc.","en":"Manager Wang is very strict about work."},{"use":"Dùng để xưng hô trực tiếp.","ex":"王经理，这是您要的材料。","py":"Wáng jīnglǐ, zhè shì nín yào de cáiliào.","vi":"Giám đốc Vương, đây là tài liệu ông cần.","en":"Manager Wang, here are the materials you asked for."}]},"调查":{"en":"to investigate; to survey; investigation; survey","exs":[{"use":"调查 + vấn đề/đối tượng.","ex":"公司正在调查这个问题。","py":"Gōngsī zhèngzài diàochá zhège wèntí.","vi":"Công ty đang điều tra vấn đề này.","en":"The company is investigating this issue."},{"use":"Động từ: 调查 + nguyên nhân (điều tra).","ex":"警察正在调查这起事故的原因。","py":"Jǐngchá zhèngzài diàochá zhè qǐ shìgù de yuányīn.","vi":"Cảnh sát đang điều tra nguyên nhân của vụ tai nạn này.","en":"The police are investigating the cause of this accident."},{"use":"Danh từ: 做一次调查 (khảo sát).","ex":"我们做了一次关于网购的调查。","py":"Wǒmen zuò le yí cì guānyú wǎnggòu de diàochá.","vi":"Chúng tôi đã làm một cuộc khảo sát về mua sắm trực tuyến.","en":"We carried out a survey about online shopping."},{"use":"根据调查: theo kết quả khảo sát.","ex":"根据调查，大部分年轻人喜欢手机支付。","py":"Gēnjù diàochá, dàbùfen niánqīngrén xǐhuan shǒujī zhīfù.","vi":"Theo khảo sát, phần lớn người trẻ thích thanh toán bằng điện thoại.","en":"According to the survey, most young people prefer mobile payment."}]},"多长时间":{"en":"how long; how much time","exs":[{"use":"Hỏi khoảng thời gian: 要 + 多长时间.","ex":"从你家到公司要多长时间？","py":"Cóng nǐ jiā dào gōngsī yào duō cháng shíjiān?","vi":"Từ nhà bạn đến công ty mất bao lâu?","en":"How long does it take from your home to the company?"},{"use":"V + 了 + 多长时间: đã làm bao lâu.","ex":"你学汉语学了多长时间？","py":"Nǐ xué Hànyǔ xué le duō cháng shíjiān?","vi":"Bạn học tiếng Hán được bao lâu rồi?","en":"How long have you been studying Chinese?"},{"use":"Hỏi thời lượng của sự kiện.","ex":"这个会议要开多长时间？","py":"Zhège huìyì yào kāi duō cháng shíjiān?","vi":"Cuộc họp này sẽ họp trong bao lâu?","en":"How long will this meeting last?"},{"use":"过了多长时间: đã qua bao lâu.","ex":"你等了多长时间，他才来？","py":"Nǐ děng le duō cháng shíjiān, tā cái lái?","vi":"Bạn đợi bao lâu thì anh ấy mới đến?","en":"How long did you wait before he came?"}]},"原来":{"en":"so it turns out; originally; original","exs":[{"use":"Phát hiện sự thật: 原来 = hóa ra.","ex":"原来是你，我还以为是小王呢。","py":"Yuánlái shì nǐ, wǒ hái yǐwéi shì Xiǎo Wáng ne.","vi":"Hóa ra là bạn, tôi còn tưởng là Tiểu Vương.","en":"So it's you; I thought it was Xiao Wang."},{"use":"Phó từ: vốn dĩ, ban đầu (trước khi thay đổi).","ex":"他原来住在上海，后来搬到了北京。","py":"Tā yuánlái zhù zài Shànghǎi, hòulái bān dào le Běijīng.","vi":"Anh ấy vốn ở Thượng Hải, sau đó chuyển đến Bắc Kinh.","en":"He originally lived in Shanghai and later moved to Beijing."},{"use":"Tính từ: 原来的 + danh từ = cái ban đầu.","ex":"原来的办法不好用，我们换一个吧。","py":"Yuánlái de bànfǎ bù hǎo yòng, wǒmen huàn yí gè ba.","vi":"Cách ban đầu không hiệu quả, chúng ta đổi cách khác đi.","en":"The original method doesn't work well; let's change it."},{"use":"找了半天，原来……: tìm mãi, hóa ra …","ex":"我找了半天，原来手机在包里。","py":"Wǒ zhǎo le bàntiān, yuánlái shǒujī zài bāo li.","vi":"Tôi tìm mãi, hóa ra điện thoại ở trong túi.","en":"I searched for ages, and it turns out my phone was in the bag."}]},"提前完成":{"en":"to complete ahead of schedule","exs":[{"use":"提前完成 + nhiệm vụ / kế hoạch: hoàn thành trước thời hạn.","ex":"我们提前完成了这个月的任务。","py":"Wǒmen tíqián wánchéng le zhège yuè de rènwu.","vi":"Chúng tôi đã hoàn thành nhiệm vụ tháng này trước thời hạn.","en":"We completed this month's task ahead of schedule."},{"use":"希望 / 想 + 提前完成: mong hoàn thành sớm.","ex":"他加班工作，希望能提前完成计划。","py":"Tā jiābān gōngzuò, xīwàng néng tíqián wánchéng jìhuà.","vi":"Anh ấy tăng ca, hy vọng có thể hoàn thành kế hoạch sớm hơn dự kiến.","en":"He works overtime, hoping to finish the plan ahead of schedule."},{"use":"可以 + 提前完成: có thể hoàn thành sớm; dùng khi không nêu tân ngữ.","ex":"如果大家努力，一定可以提前完成。","py":"Rúguǒ dàjiā nǔlì, yídìng kěyǐ tíqián wánchéng.","vi":"Nếu mọi người cố gắng, nhất định có thể hoàn thành trước thời hạn.","en":"If everyone works hard, we can definitely finish early."}]},"周末":{"en":"weekend","exs":[{"use":"周末 + câu hỏi kế hoạch: 有什么打算？","ex":"周末你有什么打算？","py":"Zhōumò nǐ yǒu shénme dǎsuàn?","vi":"Cuối tuần bạn có dự định gì?","en":"What are your plans for the weekend?"},{"use":"周末 làm trạng ngữ thời gian, đứng trước động từ.","ex":"我们周末一起去爬山吧。","py":"Wǒmen zhōumò yìqǐ qù páshān ba.","vi":"Cuối tuần chúng ta cùng đi leo núi nhé.","en":"Let's go hiking together this weekend."},{"use":"这个周末: cuối tuần này.","ex":"这个周末我要在家休息。","py":"Zhège zhōumò wǒ yào zài jiā xiūxi.","vi":"Cuối tuần này tôi muốn ở nhà nghỉ ngơi.","en":"This weekend I want to rest at home."},{"use":"周末 + 常常: thói quen vào cuối tuần.","ex":"他周末常常加班。","py":"Tā zhōumò chángcháng jiābān.","vi":"Cuối tuần anh ấy thường phải tăng ca.","en":"He often works overtime on weekends."}]},"保证":{"en":"to guarantee; to ensure; guarantee; assurance","exs":[{"use":"保证 + mệnh đề: cam đoan sẽ làm gì.","ex":"我保证明天一定把书还给你。","py":"Wǒ bǎozhèng míngtiān yídìng bǎ shū huán gěi nǐ.","vi":"Tôi bảo đảm ngày mai nhất định trả sách cho bạn.","en":"I promise I'll return the book to you tomorrow."},{"use":"保证 + danh từ: bảo đảm điều gì (chất lượng...).","ex":"公司保证产品的质量。","py":"Gōngsī bǎozhèng chǎnpǐn de zhìliàng.","vi":"Công ty bảo đảm chất lượng sản phẩm.","en":"The company guarantees the quality of its products."},{"use":"才能 + 保证……: có như vậy mới bảo đảm được.","ex":"多运动才能保证身体健康。","py":"Duō yùndòng cái néng bǎozhèng shēntǐ jiànkāng.","vi":"Vận động nhiều mới bảo đảm được sức khỏe.","en":"You can only stay healthy by exercising more."},{"use":"Làm danh từ: 给……一个保证 / 做出保证.","ex":"他给了我一个保证。","py":"Tā gěi le wǒ yí gè bǎozhèng.","vi":"Anh ấy đã cho tôi một lời bảo đảm.","en":"He gave me his assurance."}]},"身体":{"en":"body; health","exs":[{"use":"Thường kết hợp: 身体健康, 锻炼身体.","ex":"你要照顾好自己的身体。","py":"Nǐ yào zhàogù hǎo zìjǐ de shēntǐ.","vi":"Bạn phải chăm sóc tốt cơ thể của mình.","en":"You must take good care of your health."},{"use":"身体很好 / 不好: chỉ tình trạng sức khỏe.","ex":"爷爷的身体很好，每天都去散步。","py":"Yéye de shēntǐ hěn hǎo, měitiān dōu qù sànbù.","vi":"Sức khỏe của ông nội rất tốt, ngày nào ông cũng đi dạo.","en":"Grandpa is in good health and takes a walk every day."},{"use":"身体不舒服: người không khỏe.","ex":"我今天身体不舒服，想请假。","py":"Wǒ jīntiān shēntǐ bù shūfu, xiǎng qǐngjià.","vi":"Hôm nay tôi thấy trong người không khỏe, muốn xin nghỉ.","en":"I don't feel well today and want to take leave."},{"use":"锻炼身体: rèn luyện thân thể.","ex":"多锻炼身体，对健康有好处。","py":"Duō duànliàn shēntǐ, duì jiànkāng yǒu hǎochù.","vi":"Rèn luyện cơ thể nhiều thì có lợi cho sức khỏe.","en":"Exercising more is good for your health."}]},"当天":{"en":"the same day; that very day","exs":[{"use":"当天 + động từ: ngay trong ngày hôm đó.","ex":"机票当天就卖完了。","py":"Jīpiào dàngtiān jiù mài wán le.","vi":"Vé máy bay bán hết ngay trong ngày hôm đó.","en":"The plane tickets sold out that very day."},{"use":"当天 + 吃完 / 用完: phải dùng hết trong ngày.","ex":"这些水果要当天吃完，不然会坏。","py":"Zhèxiē shuǐguǒ yào dàngtiān chī wán, bùrán huì huài.","vi":"Số trái cây này phải ăn hết trong ngày, nếu không sẽ hỏng.","en":"These fruits must be eaten the same day, or they will go bad."},{"use":"当天的 + danh từ + 当天 + V: việc nào làm xong trong ngày.","ex":"当天的工作当天完成。","py":"Dàngtiān de gōngzuò dàngtiān wánchéng.","vi":"Việc của ngày nào làm xong trong ngày đó.","en":"Finish each day's work on the same day."},{"use":"当天来回: đi về trong ngày.","ex":"从这里去那个城市，可以当天来回。","py":"Cóng zhèlǐ qù nàge chéngshì, kěyǐ dàngtiān láihuí.","vi":"Từ đây đến thành phố đó có thể đi về trong ngày.","en":"You can go to that city and back in a single day."}]},"笔记本":{"en":"notebook; laptop","exs":[{"use":"Trong bài chỉ quyển sổ; còn có nghĩa laptop.","ex":"我买了一个新笔记本。","py":"Wǒ mǎi le yí gè xīn bǐjìběn.","vi":"Tôi đã mua một cuốn sổ mới.","en":"I bought a new notebook."},{"use":"Nghĩa 1: sổ ghi chép dùng để ghi bài.","ex":"上课时我用笔记本记老师讲的内容。","py":"Shàngkè shí wǒ yòng bǐjìběn jì lǎoshī jiǎng de nèiróng.","vi":"Khi học, tôi dùng sổ để ghi lại nội dung thầy giảng.","en":"In class I use a notebook to write down what the teacher says."},{"use":"Nghĩa 2: 笔记本电脑 = máy tính xách tay.","ex":"他的笔记本电脑坏了，正在修。","py":"Tā de bǐjìběn diànnǎo huài le, zhèngzài xiū.","vi":"Máy tính xách tay của anh ấy hỏng rồi, đang sửa.","en":"His laptop is broken and being repaired."},{"use":"Nghĩa 2: nói tắt 笔记本 = laptop (lượng từ 台).","ex":"我想买一台轻一点儿的笔记本。","py":"Wǒ xiǎng mǎi yì tái qīng yìdiǎnr de bǐjìběn.","vi":"Tôi muốn mua một chiếc laptop nhẹ hơn một chút.","en":"I want to buy a lighter laptop."}]},"提醒":{"en":"to remind; to warn; reminder","exs":[{"use":"提醒 + người + việc.","ex":"请提醒我明天开会。","py":"Qǐng tíxǐng wǒ míngtiān kāihuì.","vi":"Xin hãy nhắc tôi ngày mai họp.","en":"Please remind me about tomorrow's meeting."},{"use":"谢谢你提醒我: cảm ơn đã nhắc.","ex":"谢谢你提醒我，我差点儿忘了。","py":"Xièxie nǐ tíxǐng wǒ, wǒ chàdiǎnr wàng le.","vi":"Cảm ơn bạn đã nhắc tôi, suýt nữa tôi quên mất.","en":"Thanks for reminding me; I almost forgot."},{"use":"Chủ ngữ là vật: 手机提醒我……","ex":"手机会提醒我按时吃药。","py":"Shǒujī huì tíxǐng wǒ ànshí chī yào.","vi":"Điện thoại sẽ nhắc tôi uống thuốc đúng giờ.","en":"My phone reminds me to take my medicine on time."},{"use":"提醒 = cảnh báo, dặn dò: 提醒 + người + 不要……","ex":"医生提醒他不要吃太咸的东西。","py":"Yīshēng tíxǐng tā bú yào chī tài xián de dōngxi.","vi":"Bác sĩ dặn anh ấy đừng ăn đồ quá mặn.","en":"The doctor warned him not to eat food that is too salty."},{"use":"Làm danh từ: 一个小提醒.","ex":"这只是一个小提醒，别忘了带护照。","py":"Zhè zhǐshì yí gè xiǎo tíxǐng, bié wàng le dài hùzhào.","vi":"Đây chỉ là một lời nhắc nhỏ, đừng quên mang hộ chiếu.","en":"This is just a small reminder: don't forget your passport."}]},"手忙脚乱":{"en":"in a flurry; flustered; rushed off one's feet","exs":[{"use":"手忙脚乱地 + V: làm việc trong trạng thái cuống cuồng.","ex":"客人突然来了，我手忙脚乱地准备饭菜。","py":"Kèrén tūrán lái le, wǒ shǒumángjiǎoluàn de zhǔnbèi fàncài.","vi":"Khách đến đột ngột, tôi luống cuống chuẩn bị cơm nước.","en":"Guests arrived suddenly, and I scrambled to prepare the meal."},{"use":"忙得手忙脚乱: bận đến mức rối tay rối chân.","ex":"第一天上班，他忙得手忙脚乱。","py":"Dì-yī tiān shàngbān, tā máng de shǒumángjiǎoluàn.","vi":"Ngày đầu đi làm, anh ấy bận đến luống cuống chân tay.","en":"On his first day at work he was rushed off his feet."},{"use":"会 + 手忙脚乱: dễ rối loạn; thường dùng để khuyên.","ex":"别着急，不然会手忙脚乱的。","py":"Bié zháojí, bùrán huì shǒumángjiǎoluàn de.","vi":"Đừng vội, không thì sẽ rối tay rối chân đấy.","en":"Don't rush, or you'll get flustered."}]},"生意":{"en":"business; trade","exs":[{"use":"生意好 / 不好: việc buôn bán thuận lợi hay không.","ex":"他在市中心开了一家小店，生意很好。","py":"Tā zài shì zhōngxīn kāi le yì jiā xiǎo diàn, shēngyi hěn hǎo.","vi":"Anh ấy mở một cửa hàng nhỏ ở trung tâm thành phố, buôn bán rất tốt.","en":"He opened a small shop downtown and business is great."},{"use":"生意 + 不好做: làm ăn khó khăn.","ex":"最近生意不好做。","py":"Zuìjìn shēngyi bù hǎo zuò.","vi":"Dạo này làm ăn khó khăn.","en":"Business has been hard lately."},{"use":"Lượng từ 笔: 一笔生意 = một thương vụ.","ex":"这笔生意我们一定要谈成。","py":"Zhè bǐ shēngyi wǒmen yídìng yào tán chéng.","vi":"Thương vụ này chúng ta nhất định phải chốt được.","en":"We must close this deal."},{"use":"谈生意: bàn chuyện làm ăn.","ex":"他今天要去上海和客户谈生意。","py":"Tā jīntiān yào qù Shànghǎi hé kèhù tán shēngyi.","vi":"Hôm nay anh ấy đến Thượng Hải bàn chuyện làm ăn với khách hàng.","en":"He is going to Shanghai today to discuss business with a client."}]},"终于":{"en":"finally; at last","exs":[{"use":"终于 + động từ: cuối cùng cũng, sau thời gian chờ đợi.","ex":"等了三个小时，车终于来了。","py":"Děng le sān gè xiǎoshí, chē zhōngyú lái le.","vi":"Chờ ba tiếng đồng hồ, cuối cùng xe cũng đến.","en":"After waiting three hours, the bus finally came."},{"use":"终于 + V + 了: thể hiện niềm vui khi đạt được.","ex":"我终于通过了汉语考试！","py":"Wǒ zhōngyú tōngguò le Hànyǔ kǎoshì!","vi":"Cuối cùng tôi cũng thi đỗ kỳ thi tiếng Hán!","en":"I finally passed the Chinese exam!"},{"use":"经过……，终于……: trải qua nỗ lực mới đạt được.","ex":"经过多年努力，他终于实现了自己的梦想。","py":"Jīngguò duō nián nǔlì, tā zhōngyú shíxiàn le zìjǐ de mèngxiǎng.","vi":"Sau nhiều năm cố gắng, cuối cùng anh ấy đã thực hiện được ước mơ của mình.","en":"After years of effort, he finally realized his dream."},{"use":"终于 đứng trước chủ ngữ hoặc sau chủ ngữ.","ex":"天气终于暖和起来了。","py":"Tiānqì zhōngyú nuǎnhuo qǐlai le.","vi":"Thời tiết cuối cùng cũng ấm lên rồi.","en":"The weather has finally warmed up."}]},"越来越":{"en":"more and more; increasingly","exs":[{"use":"越来越 + tính từ: càng ngày càng (thay đổi theo thời gian).","ex":"天气越来越冷了，记得多穿衣服。","py":"Tiānqì yuèláiyuè lěng le, jìde duō chuān yīfu.","vi":"Thời tiết càng ngày càng lạnh, nhớ mặc thêm áo.","en":"It's getting colder and colder; remember to wear more clothes."},{"use":"V + 得 + 越来越 + adj: bổ ngữ trạng thái.","ex":"他的汉语说得越来越好。","py":"Tā de Hànyǔ shuō de yuèláiyuè hǎo.","vi":"Tiếng Hán của anh ấy nói càng ngày càng tốt.","en":"His spoken Chinese is getting better and better."},{"use":"越来越 + 多 / 少: số lượng tăng giảm dần.","ex":"来这里旅游的人越来越多。","py":"Lái zhèlǐ lǚyóu de rén yuèláiyuè duō.","vi":"Người đến đây du lịch ngày càng nhiều.","en":"More and more people come here to travel."},{"use":"越来越 + động từ tâm lý: 喜欢 / 习惯.","ex":"我越来越喜欢这个城市了。","py":"Wǒ yuèláiyuè xǐhuan zhège chéngshì le.","vi":"Tôi càng ngày càng thích thành phố này.","en":"I like this city more and more."}]},"做生意":{"en":"to do business; to trade","exs":[{"use":"想 + 做生意: có ý định kinh doanh.","ex":"他想辞职回老家做生意。","py":"Tā xiǎng cízhí huí lǎojiā zuò shēngyi.","vi":"Anh ấy muốn nghỉ việc về quê làm ăn buôn bán.","en":"He wants to quit and go back to his hometown to start a business."},{"use":"做生意 làm chủ ngữ: nói về nguyên tắc.","ex":"做生意要讲信用。","py":"Zuò shēngyi yào jiǎng xìnyòng.","vi":"Làm ăn phải giữ chữ tín.","en":"Doing business requires integrity."},{"use":"都 + 做生意: cả nhà làm nghề buôn bán.","ex":"他们家几代人都做生意。","py":"Tāmen jiā jǐ dài rén dōu zuò shēngyi.","vi":"Mấy đời nhà họ đều làm nghề buôn bán.","en":"Several generations of their family have been in business."},{"use":"跟 + người + 做生意: làm ăn với ai.","ex":"我不太愿意跟朋友做生意。","py":"Wǒ bú tài yuànyì gēn péngyou zuò shēngyi.","vi":"Tôi không muốn làm ăn với bạn bè lắm.","en":"I'm not very keen on doing business with friends."}]},"发现":{"en":"to discover; to find out; to realize; discovery","exs":[{"use":"发现 + sự vật / vấn đề.","ex":"我发现了一个问题。","py":"Wǒ fāxiàn le yí gè wèntí.","vi":"Tôi phát hiện một vấn đề.","en":"I found a problem."},{"use":"发现 + mệnh đề: nhận ra rằng …","ex":"我发现他今天心情不太好。","py":"Wǒ fāxiàn tā jīntiān xīnqíng bú tài hǎo.","vi":"Tôi nhận thấy hôm nay tâm trạng anh ấy không tốt lắm.","en":"I noticed he is not in a very good mood today."},{"use":"……才发现……: đến khi … mới phát hiện ra.","ex":"回到家我才发现钥匙不见了。","py":"Huídào jiā wǒ cái fāxiàn yàoshi bú jiàn le.","vi":"Về đến nhà tôi mới phát hiện chìa khóa không thấy đâu.","en":"I didn't realize until I got home that my keys were missing."},{"use":"Phát hiện khoa học: 发现了一种新的……","ex":"科学家发现了一种新的药。","py":"Kēxuéjiā fāxiàn le yì zhǒng xīn de yào.","vi":"Các nhà khoa học đã phát hiện một loại thuốc mới.","en":"Scientists have discovered a new kind of medicine."},{"use":"Làm danh từ: 一个重要的发现.","ex":"这是一个重要的发现。","py":"Zhè shì yí gè zhòngyào de fāxiàn.","vi":"Đây là một phát hiện quan trọng.","en":"This is an important discovery."}]},"慢慢来":{"en":"take it slowly; take your time","exs":[{"use":"Khuyên người khác đừng vội: 要慢慢来.","ex":"不要着急，学汉语要慢慢来。","py":"Búyào zháojí, xué Hànyǔ yào mànmàn lái.","vi":"Đừng vội, học tiếng Hán phải từ từ.","en":"Don't worry; learning Chinese takes time."},{"use":"Câu nói thân mật: 你慢慢来.","ex":"你慢慢来，我在这儿等你。","py":"Nǐ mànmàn lái, wǒ zài zhèr děng nǐ.","vi":"Bạn cứ từ từ, tôi đợi bạn ở đây.","en":"Take your time; I'll wait for you here."},{"use":"……，慢慢来就好: cứ làm dần dần là được.","ex":"事情一件一件做，慢慢来就好。","py":"Shìqing yí jiàn yí jiàn zuò, mànmàn lái jiù hǎo.","vi":"Việc cứ làm từng việc một, cứ từ từ là được.","en":"Do things one at a time; just take it slowly."}]},"万事开头难":{"en":"the first step is always the hardest; every beginning is hard","exs":[{"use":"Thành ngữ / tục ngữ: động viên khi mới bắt đầu.","ex":"万事开头难，坚持下去就会好的。","py":"Wànshì kāitóu nán, jiānchí xiàqu jiù huì hǎo de.","vi":"Vạn sự khởi đầu nan, kiên trì thì sẽ tốt lên thôi.","en":"Every beginning is hard; if you keep going it will get better."},{"use":"Dùng với 嘛 để giải thích sự khó khăn ban đầu.","ex":"刚开始学游泳很不容易，万事开头难嘛。","py":"Gāng kāishǐ xué yóuyǒng hěn bù róngyì, wànshì kāitóu nán ma.","vi":"Mới học bơi không dễ đâu, vạn sự khởi đầu nan mà.","en":"Learning to swim is hard at first; the first step is always the hardest."},{"use":"俗话说“……”: như tục ngữ nói.","ex":"别担心，俗话说“万事开头难”，过几天就习惯了。","py":"Bié dānxīn, súhuà shuō “wànshì kāitóu nán”, guò jǐ tiān jiù xíguàn le.","vi":"Đừng lo, tục ngữ nói “vạn sự khởi đầu nan”, vài ngày nữa sẽ quen thôi.","en":"Don't worry; as the saying goes, “every beginning is hard”, and you'll get used to it in a few days."}]},"一切":{"en":"all; everything","exs":[{"use":"一切 làm chủ ngữ: mọi thứ.","ex":"一切都会好起来的。","py":"Yíqiè dōu huì hǎo qǐlai de.","vi":"Mọi chuyện rồi sẽ tốt lên thôi.","en":"Everything will get better."},{"use":"Làm tân ngữ: 为我做的一切.","ex":"谢谢你为我做的一切。","py":"Xièxie nǐ wèi wǒ zuò de yíqiè.","vi":"Cảm ơn bạn vì tất cả những gì bạn đã làm cho tôi.","en":"Thank you for everything you've done for me."},{"use":"把 + 一切 + V: đem mọi thứ …","ex":"他把一切都告诉了妈妈。","py":"Tā bǎ yíqiè dōu gàosu le māma.","vi":"Anh ấy đã kể mọi chuyện cho mẹ nghe.","en":"He told his mom everything."},{"use":"一切 + danh từ: mọi …","ex":"一切困难我们都能克服。","py":"Yíqiè kùnnan wǒmen dōu néng kèfú.","vi":"Mọi khó khăn chúng ta đều có thể vượt qua.","en":"We can overcome all difficulties."}]},"考虑":{"en":"to consider; to think over","exs":[{"use":"考虑 + vấn đề / 考虑一下.","ex":"这件事我要再考虑一下。","py":"Zhè jiàn shì wǒ yào zài kǎolǜ yíxià.","vi":"Việc này tôi phải cân nhắc thêm.","en":"I need to think this over some more."},{"use":"考虑一下 + tân ngữ: xin cân nhắc.","ex":"你可以考虑一下我的建议。","py":"Nǐ kěyǐ kǎolǜ yíxià wǒ de jiànyì.","vi":"Bạn có thể cân nhắc đề xuất của tôi.","en":"You may want to consider my suggestion."},{"use":"Lặp động từ: 考虑考虑 = suy nghĩ thêm.","ex":"买房子的事，我们还要考虑考虑。","py":"Mǎi fángzi de shì, wǒmen hái yào kǎolǜ kǎolǜ.","vi":"Chuyện mua nhà, chúng tôi còn phải suy nghĩ thêm.","en":"As for buying a house, we still need to think about it."},{"use":"为 + người + 考虑: nghĩ cho ai.","ex":"做决定的时候，要多为别人考虑。","py":"Zuò juédìng de shíhou, yào duō wèi biérén kǎolǜ.","vi":"Khi đưa ra quyết định, cần nghĩ cho người khác nhiều hơn.","en":"When making decisions, think more about others."},{"use":"正在考虑 + 要不要……: đang cân nhắc có nên …","ex":"我正在考虑要不要换工作。","py":"Wǒ zhèngzài kǎolǜ yào bu yào huàn gōngzuò.","vi":"Tôi đang cân nhắc có nên đổi việc hay không.","en":"I'm considering whether to change jobs."}]},"价格":{"en":"price","exs":[{"use":"价格高 / 价格低.","ex":"这件衣服价格不高。","py":"Zhè jiàn yīfu jiàgé bù gāo.","vi":"Chiếc áo này giá không cao.","en":"The price of this garment is not high."},{"use":"价格 + 差不多: giá tương đương.","ex":"这两个价格差不多。","py":"Zhè liǎng gè jiàgé chàbuduō.","vi":"Hai mức giá này gần bằng nhau.","en":"These two prices are about the same."},{"use":"So sánh: A 的价格比 B 便宜 / 贵.","ex":"这家店的价格比别的店便宜一点儿。","py":"Zhè jiā diàn de jiàgé bǐ bié de diàn piányi yìdiǎnr.","vi":"Giá của cửa hàng này rẻ hơn các cửa hàng khác một chút.","en":"This shop's prices are a bit cheaper than other shops."},{"use":"价格 + 受……影响: giá cả chịu ảnh hưởng.","ex":"商品的价格会受季节影响。","py":"Shāngpǐn de jiàgé huì shòu jìjié yǐngxiǎng.","vi":"Giá cả hàng hóa sẽ chịu ảnh hưởng của mùa vụ.","en":"The price of goods is affected by the season."}]},"标准":{"en":"standard; criterion; standard (of pronunciation, etc.)","exs":[{"use":"Làm danh từ: 选……的标准 = tiêu chuẩn chọn …","ex":"你选朋友的标准是什么？","py":"Nǐ xuǎn péngyou de biāozhǔn shì shénme?","vi":"Tiêu chuẩn chọn bạn của bạn là gì?","en":"What are your standards for choosing friends?"},{"use":"Làm tính từ: 发音很标准, 很标准.","ex":"他的普通话非常标准。","py":"Tā de pǔtōnghuà fēicháng biāozhǔn.","vi":"Tiếng phổ thông của anh ấy rất chuẩn.","en":"His Mandarin is very standard."},{"use":"Danh từ: 招聘 / 评价 + 标准.","ex":"公司的招聘标准很高。","py":"Gōngsī de zhāopìn biāozhǔn hěn gāo.","vi":"Tiêu chuẩn tuyển dụng của công ty rất cao.","en":"The company's hiring standards are very high."},{"use":"符合 / 达到 + 标准: đạt tiêu chuẩn.","ex":"这个杯子的大小不符合标准。","py":"Zhège bēizi de dàxiǎo bù fúhé biāozhǔn.","vi":"Kích thước chiếc cốc này không đạt tiêu chuẩn.","en":"The size of this cup does not meet the standard."}]},"质量":{"en":"quality","exs":[{"use":"质量好 / 质量差.","ex":"这个产品质量很好。","py":"Zhège chǎnpǐn zhìliàng hěn hǎo.","vi":"Sản phẩm này chất lượng rất tốt.","en":"This product is of very good quality."},{"use":"质量 làm chủ ngữ: 质量最重要.","ex":"东西的质量最重要。","py":"Dōngxi de zhìliàng zuì zhòngyào.","vi":"Chất lượng của hàng hóa là quan trọng nhất.","en":"The quality of goods is the most important thing."},{"use":"重视 + 质量: coi trọng chất lượng.","ex":"这家工厂非常重视产品质量。","py":"Zhè jiā gōngchǎng fēicháng zhòngshì chǎnpǐn zhìliàng.","vi":"Nhà máy này rất coi trọng chất lượng sản phẩm.","en":"This factory places great importance on product quality."},{"use":"睡眠质量: chất lượng giấc ngủ (không chỉ hàng hóa).","ex":"睡眠质量不好会影响工作。","py":"Shuìmián zhìliàng bù hǎo huì yǐngxiǎng gōngzuò.","vi":"Chất lượng giấc ngủ kém sẽ ảnh hưởng đến công việc.","en":"Poor sleep quality will affect your work."},{"use":"质量 + 有保证: chất lượng được đảm bảo.","ex":"虽然价格高一点儿，但质量有保证。","py":"Suīrán jiàgé gāo yìdiǎnr, dàn zhìliàng yǒu bǎozhèng.","vi":"Tuy giá cao hơn một chút nhưng chất lượng được đảm bảo.","en":"Although the price is a bit higher, the quality is guaranteed."}]},"样子":{"en":"appearance; look; shape; manner","exs":[{"use":"Chỉ hình dáng bên ngoài.","ex":"这个包的样子很好看。","py":"Zhège bāo de yàngzi hěn hǎokàn.","vi":"Kiểu dáng của chiếc túi này rất đẹp.","en":"This bag looks very nice."},{"use":"Thường dùng: 什么样子？; ……的样子; 看起来……的样子。","ex":"这个地方以前是什么样子？","py":"Zhège dìfang yǐqián shì shénme yàngzi?","vi":"Nơi này trước đây trông như thế nào?","en":"What did this place look like before?"},{"use":"看他……的样子: nhìn bộ dạng … của anh ấy.","ex":"看他着急的样子，我也有点儿担心。","py":"Kàn tā zháojí de yàngzi, wǒ yě yǒudiǎnr dānxīn.","vi":"Nhìn bộ dạng sốt ruột của anh ấy, tôi cũng hơi lo.","en":"Seeing how anxious he looked, I got a bit worried too."},{"use":"学着 + người + 的样子: bắt chước dáng vẻ ai.","ex":"妹妹学着妈妈的样子做饭。","py":"Mèimei xuézhe māma de yàngzi zuòfàn.","vi":"Em gái bắt chước dáng vẻ của mẹ để nấu cơm.","en":"My little sister cooks, imitating the way Mom does it."},{"use":"看起来 + adj + 的样子: trông có vẻ …","ex":"他看起来很累的样子。","py":"Tā kànqǐlai hěn lèi de yàngzi.","vi":"Trông anh ấy có vẻ rất mệt.","en":"He looks very tired."}]},"流行":{"en":"popular; fashionable; to be in vogue; to spread (disease)","exs":[{"use":"很流行 / 不流行.","ex":"今年流行这种颜色。","py":"Jīnnián liúxíng zhè zhǒng yánsè.","vi":"Năm nay đang thịnh hành màu này.","en":"This color is in fashion this year."},{"use":"在 + nhóm người + 中 + 流行: thịnh hành trong nhóm nào.","ex":"这种发型在年轻人中很流行。","py":"Zhè zhǒng fàxíng zài niánqīngrén zhōng hěn liúxíng.","vi":"Kiểu tóc này rất thịnh hành trong giới trẻ.","en":"This hairstyle is very popular among young people."},{"use":"Nghĩa lan truyền (bệnh tật): 感冒流行.","ex":"冬天是感冒流行的季节。","py":"Dōngtiān shì gǎnmào liúxíng de jìjié.","vi":"Mùa đông là mùa cảm cúm lây lan.","en":"Winter is the season when colds spread."},{"use":"流行 + danh từ: 流行音乐 (nhạc pop).","ex":"我喜欢听流行音乐。","py":"Wǒ xǐhuan tīng liúxíng yīnyuè.","vi":"Tôi thích nghe nhạc pop.","en":"I like listening to pop music."},{"use":"特别流行: rất thịnh hành (bài hát, trào lưu).","ex":"这首歌现在特别流行。","py":"Zhè shǒu gē xiànzài tèbié liúxíng.","vi":"Bài hát này bây giờ cực kỳ thịnh hành.","en":"This song is especially popular right now."}]},"年龄":{"en":"age","exs":[{"use":"年龄大 / 年龄小.","ex":"他的年龄比我大。","py":"Tā de niánlíng bǐ wǒ dà.","vi":"Tuổi của anh ấy lớn hơn tôi.","en":"He is older than me."},{"use":"写上年龄: điền tuổi vào biểu mẫu.","ex":"请在表格里写上你的年龄。","py":"Qǐng zài biǎogé li xiěshàng nǐ de niánlíng.","vi":"Xin hãy điền tuổi của bạn vào bảng.","en":"Please write your age on the form."},{"use":"告诉别人年龄: chuyện tế nhị về tuổi.","ex":"她不愿意告诉别人自己的年龄。","py":"Tā bú yuànyì gàosu biérén zìjǐ de niánlíng.","vi":"Cô ấy không muốn nói cho người khác biết tuổi của mình.","en":"She doesn't want to tell others her age."},{"use":"没有年龄的限制: không giới hạn tuổi.","ex":"学习外语没有年龄的限制。","py":"Xuéxí wàiyǔ méiyǒu niánlíng de xiànzhì.","vi":"Học ngoại ngữ không bị giới hạn bởi tuổi tác.","en":"There is no age limit for learning a foreign language."},{"use":"各个年龄: mọi lứa tuổi.","ex":"这个游戏适合各个年龄的孩子。","py":"Zhège yóuxì shìhé gè gè niánlíng de háizi.","vi":"Trò chơi này phù hợp với trẻ em ở mọi lứa tuổi.","en":"This game is suitable for children of all ages."}]},"打折":{"en":"to give a discount; to be on sale","exs":[{"use":"打八折 = giảm còn 80%.","ex":"这家商店正在打折。","py":"Zhè jiā shāngdiàn zhèngzài dǎzhé.","vi":"Cửa hàng này đang giảm giá.","en":"This store is having a sale."},{"use":"全部打折: giảm giá toàn bộ.","ex":"书店今天全部打折。","py":"Shūdiàn jīntiān quánbù dǎzhé.","vi":"Hôm nay hiệu sách giảm giá toàn bộ.","en":"The bookstore has everything on sale today."},{"use":"Hỏi về giảm giá: 可以打折吗？","ex":"现在买还可以打折吗？","py":"Xiànzài mǎi hái kěyǐ dǎzhé ma?","vi":"Bây giờ mua còn được giảm giá không?","en":"Can I still get a discount if I buy now?"},{"use":"给 + người + 打折: giảm giá cho ai.","ex":"如果你多买几件，老板会给你打折。","py":"Rúguǒ nǐ duō mǎi jǐ jiàn, lǎobǎn huì gěi nǐ dǎzhé.","vi":"Nếu bạn mua nhiều vài món, ông chủ sẽ giảm giá cho bạn.","en":"If you buy several items, the owner will give you a discount."},{"use":"Thời gian + 打折: đợt khuyến mãi.","ex":"这个周末所有鞋子都打折，快去看看吧。","py":"Zhège zhōumò suǒyǒu xiézi dōu dǎzhé, kuài qù kànkan ba.","vi":"Cuối tuần này tất cả giày đều giảm giá, mau đi xem đi.","en":"All shoes are on sale this weekend, so go take a look."}]},"便宜":{"en":"cheap; inexpensive; (小便宜) advantage","exs":[{"use":"Trái nghĩa: 贵.","ex":"这里的水果很便宜。","py":"Zhèlǐ de shuǐguǒ hěn piányi.","vi":"Hoa quả ở đây rất rẻ.","en":"The fruit here is very cheap."},{"use":"So sánh: A 比 B 便宜 + số tiền.","ex":"这件衣服比那件便宜五十块。","py":"Zhè jiàn yīfu bǐ nà jiàn piányi wǔshí kuài.","vi":"Chiếc áo này rẻ hơn chiếc kia năm mươi đồng.","en":"This garment is 50 yuan cheaper than that one."},{"use":"Mặc cả: 便宜一点儿 = rẻ hơn chút.","ex":"能不能便宜一点儿？","py":"Néng bu néng piányi yìdiǎnr?","vi":"Có thể rẻ hơn một chút được không?","en":"Can you make it a little cheaper?"},{"use":"Tục ngữ: 便宜没好货.","ex":"便宜没好货，买东西不能只看价格。","py":"Piányi méi hǎo huò, mǎi dōngxi bù néng zhǐ kàn jiàgé.","vi":"Của rẻ là của ôi, mua đồ không thể chỉ nhìn vào giá.","en":"You get what you pay for; don't judge only by price when shopping."},{"use":"占便宜: lợi dụng, hưởng lợi từ người khác.","ex":"他总想占别人的便宜。","py":"Tā zǒng xiǎng zhàn biérén de piányi.","vi":"Anh ta lúc nào cũng muốn lợi dụng người khác.","en":"He always wants to take advantage of others."}]},"浪费":{"en":"to waste; wasteful","exs":[{"use":"浪费 + thời gian / tiền bạc.","ex":"不要浪费时间。","py":"Búyào làngfèi shíjiān.","vi":"Đừng lãng phí thời gian.","en":"Don't waste time."},{"use":"Dùng như tính từ: 太浪费了 = quá lãng phí.","ex":"这么好的东西扔了，太浪费了。","py":"Zhème hǎo de dōngxi rēng le, tài làngfèi le.","vi":"Món đồ tốt thế này mà vứt đi thì lãng phí quá.","en":"It's such a waste to throw away something this good."},{"use":"浪费 + 粮食 (lương thực, đồ ăn).","ex":"我们不应该浪费粮食，吃多少点多少。","py":"Wǒmen bù yīnggāi làngfèi liángshi, chī duōshao diǎn duōshao.","vi":"Chúng ta không nên lãng phí lương thực, ăn bao nhiêu thì gọi bấy nhiêu.","en":"We shouldn't waste food; order only as much as you can eat."},{"use":"浪费 + điện / nước (tài nguyên).","ex":"离开房间的时候请关灯，不要浪费电。","py":"Líkāi fángjiān de shíhou qǐng guān dēng, búyào làngfèi diàn.","vi":"Khi rời phòng xin hãy tắt đèn, đừng lãng phí điện.","en":"Please turn off the light when you leave the room; don't waste electricity."}]},"购物":{"en":"to shop; shopping","exs":[{"use":"网上购物 = mua sắm trực tuyến.","ex":"周末我们去商场购物。","py":"Zhōumò wǒmen qù shāngchǎng gòuwù.","vi":"Cuối tuần chúng tôi đi trung tâm thương mại mua sắm.","en":"We go shopping at the mall on weekends."},{"use":"Động từ ly hợp: 和 + người + 一起购物.","ex":"她喜欢和朋友一起购物。","py":"Tā xǐhuan hé péngyou yìqǐ gòuwù.","vi":"Cô ấy thích đi mua sắm cùng bạn bè.","en":"She likes shopping with friends."},{"use":"购物 + danh từ: 购物中心 = trung tâm mua sắm.","ex":"这个购物中心新开了很多店。","py":"Zhège gòuwù zhōngxīn xīn kāi le hěn duō diàn.","vi":"Trung tâm mua sắm này mới mở rất nhiều cửa hàng.","en":"Many new stores have opened in this shopping center."},{"use":"在网上购物 = mua sắm trên mạng.","ex":"现在很多人习惯在网上购物。","py":"Xiànzài hěn duō rén xíguàn zài wǎngshàng gòuwù.","vi":"Bây giờ nhiều người quen mua sắm trên mạng.","en":"Nowadays many people are used to shopping online."}]},"尤其":{"en":"especially; particularly","exs":[{"use":"尤其 + 是 + danh từ / tính từ.","ex":"我喜欢水果，尤其是苹果。","py":"Wǒ xǐhuan shuǐguǒ, yóuqí shì píngguǒ.","vi":"Tôi thích hoa quả, đặc biệt là táo.","en":"I like fruit, especially apples."},{"use":"尤其 + động từ/tính từ.","ex":"我尤其喜欢中文。","py":"Wǒ yóuqí xǐhuan Zhōngwén.","vi":"Tôi đặc biệt thích tiếng Trung.","en":"I especially like Chinese."},{"use":"Nhấn mạnh thời điểm: 尤其是 + thời gian.","ex":"北京的冬天很冷，尤其是晚上。","py":"Běijīng de dōngtiān hěn lěng, yóuqí shì wǎnshang.","vi":"Mùa đông ở Bắc Kinh rất lạnh, nhất là vào buổi tối.","en":"Winters in Beijing are cold, especially at night."},{"use":"Nhấn mạnh đối tượng: 尤其是 + danh từ.","ex":"他对历史感兴趣，尤其是中国历史。","py":"Tā duì lìshǐ gǎn xìngqù, yóuqí shì Zhōngguó lìshǐ.","vi":"Anh ấy hứng thú với lịch sử, đặc biệt là lịch sử Trung Quốc.","en":"He is interested in history, especially Chinese history."}]},"家具":{"en":"furniture","exs":[{"use":"Danh từ chỉ đồ nội thất nói chung.","ex":"我们新买了一些家具。","py":"Wǒmen xīn mǎi le yìxiē jiājù.","vi":"Chúng tôi vừa mua một ít đồ nội thất mới.","en":"We just bought some new furniture."},{"use":"Làm định ngữ: 家具店 / 家具 + tính từ.","ex":"这家店的家具又便宜又好看。","py":"Zhè jiā diàn de jiājù yòu piányi yòu hǎokàn.","vi":"Đồ nội thất của cửa hàng này vừa rẻ vừa đẹp.","en":"The furniture in this store is both cheap and nice-looking."},{"use":"Lượng từ: 一件家具 (từng món nội thất).","ex":"这件家具是爷爷留下来的。","py":"Zhè jiàn jiājù shì yéye liú xiàlai de.","vi":"Món nội thất này là ông nội để lại.","en":"This piece of furniture was left by my grandfather."},{"use":"家具 làm tân ngữ trong ngữ cảnh chuyển nhà.","ex":"搬家的时候，旧家具都送给朋友了。","py":"Bānjiā de shíhou, jiù jiājù dōu sòng gěi péngyou le.","vi":"Lúc chuyển nhà, đồ nội thất cũ đều đem tặng bạn bè.","en":"When we moved, we gave all the old furniture to friends."}]},"主要":{"en":"main; major; chiefly; mainly","exs":[{"use":"主要 + 的 + danh từ (tính từ).","ex":"这是主要的问题。","py":"Zhè shì zhǔyào de wèntí.","vi":"Đây là vấn đề chính.","en":"This is the main problem."},{"use":"Phó từ: 主要 + động từ (chủ yếu là).","ex":"我们公司主要卖手机和电脑。","py":"Wǒmen gōngsī zhǔyào mài shǒujī hé diànnǎo.","vi":"Công ty chúng tôi chủ yếu bán điện thoại và máy tính.","en":"Our company mainly sells phones and computers."},{"use":"主要 + 原因 / 目的 (không cần 的).","ex":"迟到的主要原因是路上堵车。","py":"Chídào de zhǔyào yuányīn shì lùshang dǔchē.","vi":"Nguyên nhân chính khiến đi muộn là tắc đường.","en":"The main reason for being late was the traffic jam."},{"use":"主要 + 想/是: nói về mục đích chính.","ex":"这次旅行，我主要想去看看海。","py":"Zhè cì lǚxíng, wǒ zhǔyào xiǎng qù kànkan hǎi.","vi":"Chuyến đi này, tôi chủ yếu muốn đi ngắm biển.","en":"On this trip, I mainly want to go see the sea."}]},"购买":{"en":"to buy; to purchase","exs":[{"use":"Trang trọng hơn 买.","ex":"我在网上购买了一本书。","py":"Wǒ zài wǎngshàng gòumǎi le yì běn shū.","vi":"Tôi đã mua một cuốn sách trên mạng.","en":"I bought a book online."},{"use":"购买 + 票 (vé).","ex":"你可以在网上购买火车票。","py":"Nǐ kěyǐ zài wǎngshàng gòumǎi huǒchēpiào.","vi":"Bạn có thể mua vé tàu hỏa trên mạng.","en":"You can buy train tickets online."},{"use":"购买前 / 购买后: hay gặp trong thông báo, hướng dẫn.","ex":"购买前请先看看说明书。","py":"Gòumǎi qián qǐng xiān kànkan shuōmíngshū.","vi":"Trước khi mua xin hãy xem hướng dẫn sử dụng.","en":"Please read the instructions before purchasing."},{"use":"购买 + vật có giá trị lớn (nhà, xe).","ex":"他们打算购买一套新房子。","py":"Tāmen dǎsuàn gòumǎi yí tào xīn fángzi.","vi":"Họ định mua một căn nhà mới.","en":"They plan to buy a new house."}]},"寄":{"en":"to send (by mail); to mail; to post","exs":[{"use":"寄 + đồ vật + 给 + người.","ex":"我给妈妈寄了一个包裹。","py":"Wǒ gěi māma jì le yí gè bāoguǒ.","vi":"Tôi đã gửi cho mẹ một gói hàng.","en":"I sent my mom a package."},{"use":"寄信 = gửi thư; 给 + người + 寄 + 信.","ex":"我每个月都给爷爷寄一封信。","py":"Wǒ měi gè yuè dōu gěi yéye jì yì fēng xìn.","vi":"Tháng nào tôi cũng gửi cho ông nội một lá thư.","en":"I send my grandfather a letter every month."},{"use":"寄到 + địa điểm: gửi tới đâu.","ex":"这个包裹寄到上海要三天。","py":"Zhège bāoguǒ jì dào Shànghǎi yào sān tiān.","vi":"Gói hàng này gửi đến Thượng Hải mất ba ngày.","en":"It takes three days for this package to reach Shanghai."},{"use":"把 + vật + 寄回…: gửi về.","ex":"我想把这些书寄回国。","py":"Wǒ xiǎng bǎ zhèxiē shū jì huí guó.","vi":"Tôi muốn gửi những cuốn sách này về nước.","en":"I want to mail these books back to my home country."}]},"方便":{"en":"convenient; to make things convenient; (to be) free/available","exs":[{"use":"很方便 / 不方便.","ex":"坐地铁很方便。","py":"Zuò dìtiě hěn fāngbiàn.","vi":"Đi tàu điện ngầm rất tiện.","en":"Taking the subway is very convenient."},{"use":"方便 = tiện / rảnh (về thời gian, hoàn cảnh); dùng để hỏi lịch sự.","ex":"你明天下午方便吗？我想去你家。","py":"Nǐ míngtiān xiàwǔ fāngbiàn ma? Wǒ xiǎng qù nǐ jiā.","vi":"Chiều mai bạn có tiện không? Tôi muốn đến nhà bạn.","en":"Is tomorrow afternoon convenient for you? I'd like to come to your place."},{"use":"Động từ: 方便 + 了 + người (làm cho thuận tiện).","ex":"这条新路方便了附近的人。","py":"Zhè tiáo xīn lù fāngbiàn le fùjìn de rén.","vi":"Con đường mới này đem lại sự thuận tiện cho người dân quanh đây.","en":"This new road has made life easier for the people nearby."},{"use":"方便面 = mì ăn liền.","ex":"加班太晚，我只好吃了一碗方便面。","py":"Jiābān tài wǎn, wǒ zhǐhǎo chī le yì wǎn fāngbiànmiàn.","vi":"Tăng ca quá muộn, tôi đành ăn một bát mì ăn liền.","en":"I worked overtime so late that I had to eat a bowl of instant noodles."},{"use":"为了方便 + người: để tiện cho ai.","ex":"为了方便大家，商店一直开到晚上十二点。","py":"Wèile fāngbiàn dàjiā, shāngdiàn yìzhí kāi dào wǎnshang shí'èr diǎn.","vi":"Để thuận tiện cho mọi người, cửa hàng mở cửa đến mười hai giờ đêm.","en":"To make things convenient for everyone, the store stays open until midnight."}]},"舒服":{"en":"comfortable; cozy; feeling well","exs":[{"use":"Dùng cho cảm giác cơ thể hoặc tâm trạng.","ex":"这双鞋穿着很舒服。","py":"Zhè shuāng xié chuānzhe hěn shūfu.","vi":"Đôi giày này đi rất thoải mái.","en":"These shoes are very comfortable to wear."},{"use":"Dùng cho cảm giác cơ thể hoặc tâm trạng.","ex":"这个房间很舒服。","py":"Zhège fángjiān hěn shūfu.","vi":"Căn phòng này rất dễ chịu.","en":"This room is very comfortable."},{"use":"不舒服 = khó chịu, không khỏe (nói về cơ thể).","ex":"我今天头疼，有点儿不舒服。","py":"Wǒ jīntiān tóu téng, yǒudiǎnr bù shūfu.","vi":"Hôm nay tôi đau đầu, thấy hơi khó chịu trong người.","en":"I have a headache today and don't feel very well."},{"use":"Cấu trúc V + 得 + 舒服: mô tả mức độ thoải mái.","ex":"昨晚我睡得很舒服。","py":"Zuówǎn wǒ shuì de hěn shūfu.","vi":"Tối qua tôi ngủ rất ngon giấc.","en":"I slept very comfortably last night."},{"use":"舒服 + 极了 / 真舒服: cảm thán.","ex":"躺在沙发上看电视真舒服。","py":"Tǎng zài shāfā shang kàn diànshì zhēn shūfu.","vi":"Nằm trên ghế sô-pha xem ti vi thật là dễ chịu.","en":"It feels so nice to lie on the sofa and watch TV."}]},"好看":{"en":"good-looking; pretty; nice to look at; interesting (of films, books)","exs":[{"use":"Nghĩa 1: đẹp, dễ nhìn (người, đồ vật).","ex":"这件衣服真好看。","py":"Zhè jiàn yīfu zhēn hǎokàn.","vi":"Chiếc áo này đẹp thật.","en":"This piece of clothing is really nice."},{"use":"Nghĩa 2: hay, đáng xem (phim, sách).","ex":"这部电影很好看，你一定要去看。","py":"Zhè bù diànyǐng hěn hǎokàn, nǐ yídìng yào qù kàn.","vi":"Bộ phim này rất hay, bạn nhất định phải đi xem.","en":"This movie is really good; you must go see it."},{"use":"Đi sau động từ 起来 / 笑起来 + 好看.","ex":"她笑起来很好看。","py":"Tā xiào qǐlai hěn hǎokàn.","vi":"Cô ấy cười lên trông rất đẹp.","en":"She looks lovely when she smiles."},{"use":"So sánh: A 比 B + 更好看.","ex":"红色的比蓝色的更好看。","py":"Hóngsè de bǐ lánsè de gèng hǎokàn.","vi":"Cái màu đỏ đẹp hơn cái màu xanh lam.","en":"The red one looks better than the blue one."}]},"来说":{"en":"as for; speaking of; from the point of view of (对……来说)","exs":[{"use":"对 + người + 来说: đối với ai mà nói.","ex":"对我来说，学汉字比说汉语难。","py":"Duì wǒ láishuō, xué Hànzì bǐ shuō Hànyǔ nán.","vi":"Đối với tôi, học chữ Hán khó hơn nói tiếng Trung.","en":"For me, learning characters is harder than speaking Chinese."},{"use":"对 + nhóm người + 来说.","ex":"对学生来说，时间非常重要。","py":"Duì xuésheng láishuō, shíjiān fēicháng zhòngyào.","vi":"Đối với học sinh mà nói, thời gian vô cùng quan trọng.","en":"For students, time is extremely important."},{"use":"一般来说 = nói chung.","ex":"一般来说，周末商场的人比较多。","py":"Yìbān láishuō, zhōumò shāngchǎng de rén bǐjiào duō.","vi":"Nói chung, cuối tuần ở trung tâm thương mại khá đông người.","en":"Generally speaking, malls are more crowded on weekends."},{"use":"从 + khía cạnh + 来说: xét về mặt nào đó.","ex":"从价格来说，这家比那家便宜。","py":"Cóng jiàgé láishuō, zhè jiā bǐ nà jiā piányi.","vi":"Xét về giá cả thì nhà này rẻ hơn nhà kia.","en":"In terms of price, this one is cheaper than that one."}]},"那些":{"en":"those","exs":[{"use":"那些 + danh từ (số nhiều, xa người nói).","ex":"那些书都是我的。","py":"Nàxiē shū dōu shì wǒ de.","vi":"Những cuốn sách kia đều là của tôi.","en":"Those books are all mine."},{"use":"Đứng một mình làm đại từ; đối lập với 这些.","ex":"我不要这些，我要那些。","py":"Wǒ bú yào zhèxiē, wǒ yào nàxiē.","vi":"Tôi không lấy những cái này, tôi lấy những cái kia.","en":"I don't want these; I want those."},{"use":"那些 + mệnh đề + 的 + danh từ.","ex":"那些穿红衣服的孩子是我的学生。","py":"Nàxiē chuān hóng yīfu de háizi shì wǒ de xuésheng.","vi":"Những đứa trẻ mặc áo đỏ kia là học trò của tôi.","en":"Those children in red clothes are my students."},{"use":"那些 + từ chỉ thời gian: những ... ấy (hồi tưởng).","ex":"那些年我们一起在北京工作。","py":"Nàxiē nián wǒmen yìqǐ zài Běijīng gōngzuò.","vi":"Những năm ấy chúng tôi cùng làm việc ở Bắc Kinh.","en":"In those years we worked together in Beijing."}]},"花钱":{"en":"to spend money; costly","exs":[{"use":"花钱 + động từ: bỏ tiền ra làm gì.","ex":"我不想花钱买没用的东西。","py":"Wǒ bù xiǎng huāqián mǎi méi yòng de dōngxi.","vi":"Tôi không muốn bỏ tiền mua những thứ vô dụng.","en":"I don't want to spend money on useless things."},{"use":"很花钱 = tốn tiền (dùng như tính từ).","ex":"去国外旅游很花钱。","py":"Qù guówài lǚyóu hěn huāqián.","vi":"Đi du lịch nước ngoài rất tốn tiền.","en":"Traveling abroad costs a lot of money."},{"use":"别乱花钱: đừng tiêu tiền bừa bãi.","ex":"你别乱花钱，要学会存钱。","py":"Nǐ bié luàn huāqián, yào xuéhuì cún qián.","vi":"Bạn đừng tiêu tiền lung tung, phải học cách tiết kiệm.","en":"Don't spend money carelessly; learn to save."},{"use":"花钱的地方: những khoản cần chi tiêu.","ex":"孩子上大学，花钱的地方越来越多。","py":"Háizi shàng dàxué, huāqián de dìfang yuè lái yuè duō.","vi":"Con vào đại học, những chỗ cần tiêu tiền ngày càng nhiều.","en":"With the kids in college, there are more and more things to spend money on."}]},"网上":{"en":"online; on the internet","exs":[{"use":"在网上 + động từ: làm gì trên mạng.","ex":"我常常在网上买衣服。","py":"Wǒ chángcháng zài wǎngshàng mǎi yīfu.","vi":"Tôi thường mua quần áo trên mạng.","en":"I often buy clothes online."},{"use":"在网上可以查到…: tra cứu trên mạng.","ex":"你在网上可以查到这个词的意思。","py":"Nǐ zài wǎngshàng kěyǐ chá dào zhège cí de yìsi.","vi":"Bạn có thể tra nghĩa của từ này trên mạng.","en":"You can look up the meaning of this word online."},{"use":"网上 + 的 + danh từ: thông tin, nội dung trên mạng.","ex":"网上的信息不一定都是真的。","py":"Wǎngshàng de xìnxī bù yídìng dōu shì zhēn de.","vi":"Thông tin trên mạng chưa chắc đều là thật.","en":"Not all information on the internet is true."},{"use":"在网上 + 聊天 / 上课.","ex":"我和朋友在网上聊天。","py":"Wǒ hé péngyou zài wǎngshàng liáotiān.","vi":"Tôi trò chuyện với bạn bè trên mạng.","en":"I chat with friends online."}]},"上网":{"en":"to go online; to surf the internet","exs":[{"use":"上网 + động từ: lên mạng để làm gì (động từ ly hợp).","ex":"我每天晚上上网看新闻。","py":"Wǒ měitiān wǎnshang shàngwǎng kàn xīnwén.","vi":"Mỗi tối tôi lên mạng đọc tin tức.","en":"I go online to read the news every evening."},{"use":"Dùng trong câu hỏi về dịch vụ.","ex":"这里可以免费上网吗？","py":"Zhèlǐ kěyǐ miǎnfèi shàngwǎng ma?","vi":"Ở đây có thể lên mạng miễn phí không?","en":"Can I get online for free here?"},{"use":"没办法上网 = không thể vào mạng.","ex":"手机没有信号，我没办法上网。","py":"Shǒujī méiyǒu xìnhào, wǒ méi bànfǎ shàngwǎng.","vi":"Điện thoại không có sóng, tôi không thể lên mạng.","en":"My phone has no signal, so I can't get online."},{"use":"不能 + 上网 + 太久: hạn chế thời gian lên mạng.","ex":"孩子不能上网太久。","py":"Háizi bù néng shàngwǎng tài jiǔ.","vi":"Trẻ con không được lên mạng quá lâu.","en":"Kids shouldn't be online for too long."}]},"手机":{"en":"mobile phone; cell phone","exs":[{"use":"手机 làm chủ ngữ; 方便了 = làm cho thuận tiện.","ex":"手机方便了我们的生活。","py":"Shǒujī fāngbiàn le wǒmen de shēnghuó.","vi":"Điện thoại làm cuộc sống của chúng ta thuận tiện hơn.","en":"Mobile phones have made our lives more convenient."},{"use":"没电了 = hết pin.","ex":"我的手机没电了。","py":"Wǒ de shǒujī méi diàn le.","vi":"Điện thoại của tôi hết pin rồi.","en":"My phone is out of battery."},{"use":"手机号码 = số điện thoại di động.","ex":"你的手机号码是多少？","py":"Nǐ de shǒujī hàomǎ shì duōshao?","vi":"Số điện thoại di động của bạn là bao nhiêu?","en":"What is your mobile phone number?"},{"use":"Lượng từ: 部 / 个.","ex":"他买了一部新手机。","py":"Tā mǎi le yí bù xīn shǒujī.","vi":"Anh ấy mua một chiếc điện thoại mới.","en":"He bought a new phone."}]},"能够":{"en":"to be able to; can; capable of","exs":[{"use":"Đặt trước động từ.","ex":"我能够帮助你。","py":"Wǒ nénggòu bāngzhù nǐ.","vi":"Tôi có thể giúp bạn.","en":"I can help you."},{"use":"只有……才能够……: chỉ khi … mới có thể.","ex":"只有努力学习，才能够考出好成绩。","py":"Zhǐyǒu nǔlì xuéxí, cái nénggòu kǎo chū hǎo chéngjì.","vi":"Chỉ có học hành chăm chỉ mới có thể thi được điểm tốt.","en":"Only by studying hard can you get good grades."},{"use":"Câu hỏi: 能够 + động từ + 吗?","ex":"你明天能够准时到吗？","py":"Nǐ míngtiān nénggòu zhǔnshí dào ma?","vi":"Ngày mai bạn có thể đến đúng giờ không?","en":"Can you arrive on time tomorrow?"},{"use":"Phủ định: 不能够 = không thể (do hoàn cảnh).","ex":"他生病了，不能够来上班。","py":"Tā shēngbìng le, bù nénggòu lái shàngbān.","vi":"Anh ấy bị ốm, không thể đi làm.","en":"He is sick and can't come to work."},{"use":"能够 + động từ: khả năng của sự vật (văn viết).","ex":"这个办法能够节约很多时间。","py":"Zhège bànfǎ nénggòu jiéyuē hěn duō shíjiān.","vi":"Cách này có thể tiết kiệm rất nhiều thời gian.","en":"This method can save a lot of time."}]},"受到":{"en":"to receive; to be subjected to; to get (praise, influence, etc.)","exs":[{"use":"受到 + 欢迎: được hoan nghênh.","ex":"这本书受到了大家的欢迎。","py":"Zhè běn shū shòudào le dàjiā de huānyíng.","vi":"Cuốn sách này được mọi người hoan nghênh.","en":"This book has been welcomed by everyone."},{"use":"受到 + 影响: chịu ảnh hưởng.","ex":"孩子很容易受到父母的影响。","py":"Háizi hěn róngyì shòudào fùmǔ de yǐngxiǎng.","vi":"Trẻ con rất dễ chịu ảnh hưởng của cha mẹ.","en":"Children are easily influenced by their parents."},{"use":"受到 + 批评: bị phê bình.","ex":"他因为迟到受到了老师的批评。","py":"Tā yīnwèi chídào shòudào le lǎoshī de pīpíng.","vi":"Anh ấy bị thầy giáo phê bình vì đi muộn.","en":"He was criticized by the teacher for being late."},{"use":"受到 + 帮助: nhận được sự giúp đỡ.","ex":"来中国后，我受到了很多人的帮助。","py":"Lái Zhōngguó hòu, wǒ shòudào le hěn duō rén de bāngzhù.","vi":"Sau khi đến Trung Quốc, tôi nhận được sự giúp đỡ của rất nhiều người.","en":"After coming to China, I received help from many people."}]},"喜爱":{"en":"to like; to be fond of; love (n.)","exs":[{"use":"Động từ: 喜爱 + danh từ / hoạt động.","ex":"我从小就喜爱音乐。","py":"Wǒ cóngxiǎo jiù xǐ'ài yīnyuè.","vi":"Từ nhỏ tôi đã yêu thích âm nhạc.","en":"I have loved music since I was a child."},{"use":"深受……喜爱: được ... yêu mến sâu sắc (danh từ).","ex":"这个故事深受孩子们的喜爱。","py":"Zhège gùshi shēn shòu háizimen de xǐ'ài.","vi":"Câu chuyện này rất được trẻ em yêu thích.","en":"This story is deeply loved by children."},{"use":"喜爱 + V + 名词: thích làm việc gì.","ex":"她喜爱养花，家里种了很多花。","py":"Tā xǐ'ài yǎng huā, jiālǐ zhòng le hěn duō huā.","vi":"Cô ấy thích trồng hoa, trong nhà trồng rất nhiều hoa.","en":"She loves growing flowers and has many at home."},{"use":"受 + người + 喜爱: được ai yêu thích.","ex":"这种水果很受年轻人喜爱。","py":"Zhè zhǒng shuǐguǒ hěn shòu niánqīngrén xǐ'ài.","vi":"Loại trái cây này rất được giới trẻ ưa chuộng.","en":"This kind of fruit is very popular with young people."}]},"商店":{"en":"shop; store","exs":[{"use":"Địa điểm: 这条街上有……商店.","ex":"这条街上有很多商店。","py":"Zhè tiáo jiē shang yǒu hěn duō shāngdiàn.","vi":"Trên con phố này có rất nhiều cửa hàng.","en":"There are many shops on this street."},{"use":"Hỏi giờ: 商店 + 几点 + 关门?","ex":"商店几点关门？","py":"Shāngdiàn jǐ diǎn guānmén?","vi":"Cửa hàng mấy giờ đóng cửa?","en":"What time does the store close?"},{"use":"去商店 + V: đi cửa hàng làm gì.","ex":"我去商店给孩子买了一双鞋。","py":"Wǒ qù shāngdiàn gěi háizi mǎi le yì shuāng xié.","vi":"Tôi đến cửa hàng mua cho con một đôi giày.","en":"I went to the store and bought a pair of shoes for my child."},{"use":"Lượng từ: 家.","ex":"学校旁边新开了一家小商店。","py":"Xuéxiào pángbiān xīn kāi le yì jiā xiǎo shāngdiàn.","vi":"Cạnh trường mới mở một cửa hàng nhỏ.","en":"A small shop has opened next to the school."}]},"任何":{"en":"any; whatever; no matter what","exs":[{"use":"任何 + danh từ + 都: bất cứ ... đều.","ex":"任何人都可以参加这次活动。","py":"Rènhé rén dōu kěyǐ cānjiā zhè cì huódòng.","vi":"Bất kỳ ai cũng có thể tham gia hoạt động lần này.","en":"Anyone can take part in this event."},{"use":"没有 + 任何 + danh từ: không có bất kỳ ... nào.","ex":"我没有任何问题。","py":"Wǒ méiyǒu rènhé wèntí.","vi":"Tôi không có bất kỳ vấn đề nào.","en":"I don't have any questions."},{"use":"无论 + 遇到 + 任何 + N, 都…","ex":"无论遇到任何困难，我们都不会放弃。","py":"Wúlùn yùdào rènhé kùnnan, wǒmen dōu bú huì fàngqì.","vi":"Dù gặp bất cứ khó khăn nào, chúng tôi cũng không bỏ cuộc.","en":"No matter what difficulties we meet, we won't give up."},{"use":"在任何时候 = vào bất cứ lúc nào.","ex":"在任何时候，诚实都很重要。","py":"Zài rènhé shíhou, chéngshí dōu hěn zhòngyào.","vi":"Vào bất cứ lúc nào, sự trung thực đều rất quan trọng.","en":"At any time, honesty is important."}]},"卖家":{"en":"seller; vendor","exs":[{"use":"卖家 làm chủ ngữ trong mua bán online.","ex":"卖家说明天就把衣服寄出来。","py":"Màijiā shuō míngtiān jiù bǎ yīfu jì chūlai.","vi":"Người bán nói ngày mai sẽ gửi quần áo đi.","en":"The seller said they'll ship the clothes tomorrow."},{"use":"问问卖家: hỏi người bán trước khi mua.","ex":"在网上买东西以前，最好先问问卖家。","py":"Zài wǎngshàng mǎi dōngxi yǐqián, zuìhǎo xiān wènwen màijiā.","vi":"Trước khi mua đồ trên mạng, tốt nhất nên hỏi người bán trước.","en":"Before buying online, it's best to ask the seller first."},{"use":"Đánh giá người bán: 这个卖家 + 的 + 服务.","ex":"这个卖家的服务很好，我给了他五星。","py":"Zhège màijiā de fúwù hěn hǎo, wǒ gěi le tā wǔ xīng.","vi":"Người bán này phục vụ rất tốt, tôi đã cho anh ấy năm sao.","en":"This seller has great service, so I gave him five stars."},{"use":"Đối lập với 买家 (người mua).","ex":"买家想便宜一点儿，卖家不同意。","py":"Mǎijiā xiǎng piányi yìdiǎnr, màijiā bù tóngyì.","vi":"Người mua muốn rẻ hơn một chút, người bán không đồng ý.","en":"The buyer wanted a lower price, but the seller didn't agree."}]},"售货员":{"en":"salesperson; shop assistant","exs":[{"use":"售货员 làm chủ ngữ: nhân viên cho biết thông tin.","ex":"售货员告诉我这件衣服可以打折。","py":"Shòuhuòyuán gàosu wǒ zhè jiàn yīfu kěyǐ dǎzhé.","vi":"Nhân viên bán hàng nói với tôi chiếc áo này có thể giảm giá.","en":"The salesperson told me this piece of clothing can be discounted."},{"use":"在……做售货员: làm nhân viên bán hàng ở đâu.","ex":"她在商场做售货员。","py":"Tā zài shāngchǎng zuò shòuhuòyuán.","vi":"Cô ấy làm nhân viên bán hàng ở trung tâm thương mại.","en":"She works as a salesperson at the mall."},{"use":"问售货员: hỏi nhân viên khi mua sắm.","ex":"我想问一下售货员，这个有大号的吗？","py":"Wǒ xiǎng wèn yíxià shòuhuòyuán, zhège yǒu dàhào de ma?","vi":"Tôi muốn hỏi nhân viên bán hàng xem cái này có size lớn không.","en":"I'd like to ask the salesperson whether this comes in a large size."},{"use":"Lượng từ lịch sự: 位.","ex":"那位售货员很热情。","py":"Nà wèi shòuhuòyuán hěn rèqíng.","vi":"Nhân viên bán hàng đó rất nhiệt tình.","en":"That salesperson is very friendly."}]},"小姐":{"en":"Miss; young lady","exs":[{"use":"Gọi người phụ nữ trẻ một cách lịch sự (trong nhà hàng, cửa hàng).","ex":"小姐，请问洗手间在哪儿？","py":"Xiǎojiě, qǐngwèn xǐshǒujiān zài nǎr?","vi":"Chị ơi, xin hỏi nhà vệ sinh ở đâu ạ?","en":"Excuse me, miss, where is the restroom?"},{"use":"Họ + 小姐: cô ... (xưng hô).","ex":"王小姐今天不在办公室。","py":"Wáng xiǎojiě jīntiān bú zài bàngōngshì.","vi":"Cô Vương hôm nay không có ở văn phòng.","en":"Miss Wang is not in the office today."},{"use":"Lượng từ lịch sự: 位 + 小姐.","ex":"那位小姐是我们公司的新同事。","py":"Nà wèi xiǎojiě shì wǒmen gōngsī de xīn tóngshì.","vi":"Cô gái kia là đồng nghiệp mới của công ty chúng tôi.","en":"That young lady is a new colleague at our company."},{"use":"这位小姐: cách gọi người lạ lịch sự.","ex":"这位小姐，你的东西忘拿了。","py":"Zhè wèi xiǎojiě, nǐ de dōngxi wàng ná le.","vi":"Cô ơi, cô quên đồ rồi.","en":"Miss, you forgot your things."}]},"沙发":{"en":"sofa; couch","exs":[{"use":"Đồ nội thất trong phòng khách.","ex":"客厅里有一个红色的沙发。","py":"Kètīng lǐ yǒu yí gè hóngsè de shāfā.","vi":"Trong phòng khách có một chiếc sô-pha màu đỏ.","en":"There is a red sofa in the living room."},{"use":"躺在 / 坐在沙发上.","ex":"他累了，一回家就躺在沙发上。","py":"Tā lèi le, yì huí jiā jiù tǎng zài shāfā shang.","vi":"Anh ấy mệt, vừa về nhà là nằm ngay xuống sô-pha.","en":"He was tired and lay on the sofa as soon as he got home."},{"use":"Lượng từ: 套 (bộ), 张, 个.","ex":"这套沙发又大又软，坐着很舒服。","py":"Zhè tào shāfā yòu dà yòu ruǎn, zuòzhe hěn shūfu.","vi":"Bộ sô-pha này vừa to vừa mềm, ngồi rất thoải mái.","en":"This sofa set is big and soft, and very comfortable to sit on."},{"use":"沙发下面 / 沙发旁边: chỉ vị trí.","ex":"小猫喜欢睡在沙发下面。","py":"Xiǎo māo xǐhuan shuì zài shāfā xiàmian.","vi":"Con mèo con thích ngủ dưới gầm sô-pha.","en":"The kitten likes to sleep under the sofa."}]},"正在":{"en":"in the middle of (doing something); currently","exs":[{"use":"正在 + động từ: đang diễn ra.","ex":"我正在看书，别吵我。","py":"Wǒ zhèngzài kàn shū, bié chǎo wǒ.","vi":"Tôi đang đọc sách, đừng làm ồn.","en":"I'm reading; don't bother me."},{"use":"正在 + 开会 / 工作: việc đang tiến hành.","ex":"他正在开会，不能接电话。","py":"Tā zhèngzài kāihuì, bù néng jiē diànhuà.","vi":"Anh ấy đang họp, không nghe điện thoại được.","en":"He is in a meeting and can't take calls."},{"use":"正在 + 下雨: hiện tượng đang xảy ra.","ex":"外面正在下雨。","py":"Wàimiàn zhèngzài xià yǔ.","vi":"Bên ngoài trời đang mưa.","en":"It is raining outside."},{"use":"正在……呢: thêm 呢 ở cuối câu.","ex":"你来的时候，我正在做饭呢。","py":"Nǐ lái de shíhou, wǒ zhèngzài zuò fàn ne.","vi":"Lúc bạn đến, tôi đang nấu cơm.","en":"I was cooking when you came."},{"use":"正在 + động từ hai âm tiết: thảo luận, chuẩn bị…","ex":"他们正在讨论这个问题。","py":"Tāmen zhèngzài tǎolùn zhège wèntí.","vi":"Họ đang thảo luận vấn đề này.","en":"They are discussing this issue."}]},"肯定":{"en":"certainly; definitely; to affirm; sure","exs":[{"use":"Phó từ: 肯定 + động từ (chắc chắn).","ex":"他肯定知道答案。","py":"Tā kěndìng zhīdào dá'àn.","vi":"Anh ấy chắc chắn biết đáp án.","en":"He definitely knows the answer."},{"use":"肯定 + 会: dự đoán chắc chắn.","ex":"明天肯定会下雨，带上雨伞吧。","py":"Míngtiān kěndìng huì xià yǔ, dàishang yǔsǎn ba.","vi":"Ngày mai chắc chắn sẽ mưa, mang theo ô đi.","en":"It will definitely rain tomorrow, so take an umbrella."},{"use":"Động từ: khẳng định, công nhận.","ex":"老师肯定了他的进步。","py":"Lǎoshī kěndìng le tā de jìnbù.","vi":"Thầy giáo ghi nhận sự tiến bộ của cậu ấy.","en":"The teacher affirmed his progress."},{"use":"Tính từ: 不太肯定 = không chắc lắm.","ex":"我不太肯定他来不来。","py":"Wǒ bú tài kěndìng tā lái bu lái.","vi":"Tôi không chắc là anh ấy có đến hay không.","en":"I'm not sure whether he's coming."},{"use":"肯定 + 是: suy đoán chắc chắn về nguyên nhân.","ex":"肯定是他拿走了我的书。","py":"Kěndìng shì tā ná zǒu le wǒ de shū.","vi":"Chắc chắn là anh ta đã lấy sách của tôi.","en":"It must be him who took my book."}]},"这种":{"en":"this kind of; this type","exs":[{"use":"这种 + danh từ (không cần lượng từ).","ex":"这种水果又甜又便宜。","py":"Zhè zhǒng shuǐguǒ yòu tián yòu piányi.","vi":"Loại trái cây này vừa ngọt vừa rẻ.","en":"This kind of fruit is sweet and cheap."},{"use":"不喜欢 + 这种 + danh từ.","ex":"我不喜欢这种颜色。","py":"Wǒ bù xǐhuan zhè zhǒng yánsè.","vi":"Tôi không thích màu kiểu này.","en":"I don't like this kind of color."},{"use":"这种 + 天气 / 事情: loại tình huống này.","ex":"这种天气最适合出去玩。","py":"Zhè zhǒng tiānqì zuì shìhé chūqù wánr.","vi":"Thời tiết kiểu này là thích hợp nhất để đi chơi.","en":"This kind of weather is perfect for going out."},{"use":"Đại từ đứng một mình, đối lập với 那种.","ex":"我要这种，不要那种。","py":"Wǒ yào zhè zhǒng, bú yào nà zhǒng.","vi":"Tôi lấy loại này, không lấy loại kia.","en":"I want this kind, not that kind."},{"use":"这种 + 事情 + 经历: nói về kinh nghiệm.","ex":"这种事情我以前没遇到过。","py":"Zhè zhǒng shìqing wǒ yǐqián méi yùdào guo.","vi":"Chuyện kiểu này trước đây tôi chưa từng gặp.","en":"I've never come across this kind of thing before."}]},"颜色":{"en":"color; colour","exs":[{"use":"Dùng để nói về màu sắc.","ex":"我喜欢这个颜色。","py":"Wǒ xǐhuan zhège yánsè.","vi":"Tôi thích màu này.","en":"I like this color."},{"use":"什么颜色的: hỏi về màu.","ex":"你想要什么颜色的？","py":"Nǐ xiǎng yào shénme yánsè de?","vi":"Bạn muốn màu nào?","en":"What color do you want?"},{"use":"有 + số + 种颜色: có mấy màu.","ex":"这件衣服有三种颜色。","py":"Zhè jiàn yīfu yǒu sān zhǒng yánsè.","vi":"Chiếc áo này có ba màu.","en":"This piece of clothing comes in three colors."},{"use":"……的颜色 + 很 + tính từ: màu của vật.","ex":"这条裙子的颜色很漂亮。","py":"Zhè tiáo qúnzi de yánsè hěn piàoliang.","vi":"Màu của chiếc váy này rất đẹp.","en":"The color of this skirt is very pretty."}]},"选择":{"en":"to choose; to select; choice; option","exs":[{"use":"选择 + danh từ / động từ.","ex":"你可以自己选择。","py":"Nǐ kěyǐ zìjǐ xuǎnzé.","vi":"Bạn có thể tự lựa chọn.","en":"You can choose by yourself."},{"use":"Danh từ: 一个 + tính từ + 选择.","ex":"这是一个很难的选择。","py":"Zhè shì yí gè hěn nán de xuǎnzé.","vi":"Đây là một lựa chọn rất khó.","en":"This is a very difficult choice."},{"use":"选择 + 了 + V: chọn làm việc gì.","ex":"他选择了学医。","py":"Tā xuǎnzé le xué yī.","vi":"Anh ấy đã chọn học y.","en":"He chose to study medicine."},{"use":"没有选择 = không có lựa chọn (danh từ).","ex":"店里的衣服太少，我没有什么选择。","py":"Diànlǐ de yīfu tài shǎo, wǒ méiyǒu shénme xuǎnzé.","vi":"Quần áo trong tiệm quá ít, tôi chẳng có nhiều lựa chọn.","en":"There are so few clothes in the store that I had little choice."},{"use":"选择 + phương tiện / cách thức.","ex":"很多人选择坐火车回家。","py":"Hěn duō rén xuǎnzé zuò huǒchē huí jiā.","vi":"Nhiều người chọn đi tàu hỏa về nhà.","en":"Many people choose to go home by train."}]},"蓝色":{"en":"blue","exs":[{"use":"Tên một màu sắc.","ex":"蓝色看起来很舒服。","py":"Lánsè kàn qǐlai hěn shūfu.","vi":"Màu xanh lam trông rất dễ chịu.","en":"Blue looks very soothing."},{"use":"是……的: miêu tả màu của vật.","ex":"天空是蓝色的。","py":"Tiānkōng shì lánsè de.","vi":"Bầu trời có màu xanh lam.","en":"The sky is blue."},{"use":"蓝色的 + danh từ: định ngữ chỉ màu.","ex":"我想买一条蓝色的裤子。","py":"Wǒ xiǎng mǎi yì tiáo lánsè de kùzi.","vi":"Tôi muốn mua một chiếc quần màu xanh lam.","en":"I want to buy a pair of blue pants."},{"use":"蓝色 làm chủ ngữ trong câu so sánh sở thích.","ex":"蓝色是我最喜欢的颜色。","py":"Lánsè shì wǒ zuì xǐhuan de yánsè.","vi":"Màu xanh lam là màu tôi thích nhất.","en":"Blue is my favorite color."}]},"看上去":{"en":"to look; to seem; to appear","exs":[{"use":"看上去 + tính từ: trông có vẻ.","ex":"他看上去很累。","py":"Tā kàn shangqu hěn lèi.","vi":"Trông anh ấy có vẻ rất mệt.","en":"He looks very tired."},{"use":"看上去……，吃起来……: ngoại hình và mùi vị.","ex":"这道菜看上去不错，吃起来也很香。","py":"Zhè dào cài kàn shangqu búcuò, chī qǐlai yě hěn xiāng.","vi":"Món này trông đẹp mắt, ăn cũng rất thơm ngon.","en":"This dish looks good and tastes great too."},{"use":"看上去 + 比 + người + tính từ.","ex":"她看上去比我还年轻。","py":"Tā kàn shangqu bǐ wǒ hái niánqīng.","vi":"Trông cô ấy còn trẻ hơn cả tôi.","en":"She looks even younger than me."},{"use":"看上去 + 像: trông giống như.","ex":"这个东西看上去像一只小鸟。","py":"Zhège dōngxi kàn shangqu xiàng yì zhī xiǎo niǎo.","vi":"Thứ này nhìn giống một chú chim nhỏ.","en":"This thing looks like a little bird."}]},"冰箱":{"en":"refrigerator; fridge","exs":[{"use":"冰箱里 = trong tủ lạnh.","ex":"冰箱里还有两个苹果。","py":"Bīngxiāng lǐ hái yǒu liǎng gè píngguǒ.","vi":"Trong tủ lạnh còn hai quả táo.","en":"There are still two apples in the fridge."},{"use":"把 + vật + 放进冰箱.","ex":"把牛奶放进冰箱里吧。","py":"Bǎ niúnǎi fàng jìn bīngxiāng lǐ ba.","vi":"Cất sữa vào tủ lạnh đi.","en":"Put the milk in the fridge."},{"use":"冰箱坏了 = tủ lạnh hỏng.","ex":"我们家的冰箱坏了，要找人来修。","py":"Wǒmen jiā de bīngxiāng huài le, yào zhǎo rén lái xiū.","vi":"Tủ lạnh nhà chúng tôi hỏng rồi, phải tìm người đến sửa.","en":"Our fridge is broken; we need to find someone to fix it."},{"use":"Lượng từ: 台.","ex":"这台冰箱很大，可以放很多东西。","py":"Zhè tái bīngxiāng hěn dà, kěyǐ fàng hěn duō dōngxi.","vi":"Chiếc tủ lạnh này rất lớn, để được nhiều đồ.","en":"This fridge is big and can hold a lot of things."}]},"商场":{"en":"shopping mall; market; department store","exs":[{"use":"Nơi có nhiều cửa hàng.","ex":"商场里人很多。","py":"Shāngchǎng lǐ rén hěn duō.","vi":"Trong trung tâm thương mại rất đông người.","en":"There are a lot of people in the mall."},{"use":"商场 làm chủ ngữ: hoạt động giảm giá.","ex":"这个商场周末打折。","py":"Zhège shāngchǎng zhōumò dǎzhé.","vi":"Trung tâm thương mại này cuối tuần giảm giá.","en":"This mall has discounts on weekends."},{"use":"在商场门口: chỉ nơi hẹn gặp.","ex":"我在商场门口等你。","py":"Wǒ zài shāngchǎng ménkǒu děng nǐ.","vi":"Tôi đợi bạn ở cổng trung tâm thương mại.","en":"I'll wait for you at the entrance of the mall."},{"use":"商场里有…: mô tả tiện ích.","ex":"大商场里有电影院和饭馆。","py":"Dà shāngchǎng lǐ yǒu diànyǐngyuàn hé fànguǎn.","vi":"Trong trung tâm thương mại lớn có rạp chiếu phim và nhà hàng.","en":"The big mall has a cinema and restaurants."}]},"顺便":{"en":"in passing; conveniently; while one is at it","exs":[{"use":"顺便 + động từ: nhân tiện làm thêm việc.","ex":"去超市的时候，顺便帮我买瓶水。","py":"Qù chāoshì de shíhou, shùnbiàn bāng wǒ mǎi píng shuǐ.","vi":"Lúc đi siêu thị, nhân tiện mua giúp tôi chai nước.","en":"While you're at the supermarket, pick up a bottle of water for me."},{"use":"Việc chính + 顺便 + việc phụ.","ex":"我去邮局寄信，顺便买了几张邮票。","py":"Wǒ qù yóujú jì xìn, shùnbiàn mǎi le jǐ zhāng yóupiào.","vi":"Tôi đến bưu điện gửi thư, tiện thể mua mấy con tem.","en":"I went to the post office to mail a letter and bought some stamps while there."},{"use":"顺便 + 把……: nhờ làm giúp khi tiện đường.","ex":"你出门的时候，顺便把垃圾带下去。","py":"Nǐ chūmén de shíhou, shùnbiàn bǎ lājī dài xiàqu.","vi":"Lúc bạn ra ngoài, tiện tay mang rác xuống luôn nhé.","en":"When you go out, take the trash down on your way."},{"use":"顺便问一下: nhân tiện hỏi một chút.","ex":"顺便问一下，这附近有银行吗？","py":"Shùnbiàn wèn yíxià, zhè fùjìn yǒu yínháng ma?","vi":"Nhân tiện hỏi một chút, gần đây có ngân hàng không?","en":"By the way, is there a bank nearby?"}]},"再说":{"en":"besides; moreover; (to deal with) later","exs":[{"use":"Liên từ: 再说 = hơn nữa (thêm lý do).","ex":"太晚了，再说我也累了，明天去吧。","py":"Tài wǎn le, zàishuō wǒ yě lèi le, míngtiān qù ba.","vi":"Muộn quá rồi, vả lại tôi cũng mệt, mai đi nhé.","en":"It's too late, and besides I'm tired; let's go tomorrow."},{"use":"Lý do 1，再说 + lý do 2.","ex":"这件衣服太贵了，再说颜色我也不喜欢。","py":"Zhè jiàn yīfu tài guì le, zàishuō yánsè wǒ yě bù xǐhuan.","vi":"Chiếc áo này đắt quá, hơn nữa tôi cũng không thích màu.","en":"This piece is too expensive, and I don't like the color either."},{"use":"Đưa ra lý do ủng hộ một đề nghị.","ex":"那儿很近，再说天气也好，我们走路去吧。","py":"Nàr hěn jìn, zàishuō tiānqì yě hǎo, wǒmen zǒulù qù ba.","vi":"Chỗ đó gần, vả lại thời tiết cũng đẹp, chúng ta đi bộ đi.","en":"It's close, and the weather is nice too, so let's walk."},{"use":"Động từ: …… 以后再说 = để sau hãy tính.","ex":"现在没时间，等放假以后再说。","py":"Xiànzài méi shíjiān, děng fàngjià yǐhòu zàishuō.","vi":"Bây giờ không có thời gian, đợi nghỉ rồi hãy nói.","en":"I don't have time now; let's talk about it after the holiday."}]},"实在":{"en":"really; truly; indeed; honest (adj.)","exs":[{"use":"实在 + 太 + tính từ: thật sự quá.","ex":"这道题实在太难了。","py":"Zhè dào tí shízài tài nán le.","vi":"Câu này thật sự quá khó.","en":"This problem is really too difficult."},{"use":"实在 + 不/没: nhấn mạnh phủ định.","ex":"我实在吃不下了。","py":"Wǒ shízài chī bú xià le.","vi":"Tôi thật sự không ăn nổi nữa.","en":"I really can't eat any more."},{"use":"Tính từ: 实在 (shízai) = thật thà, chắc chắn.","ex":"他这个人很实在，从不骗人。","py":"Tā zhège rén hěn shízai, cóng bú piàn rén.","vi":"Anh ấy là người rất thật thà, chưa bao giờ lừa ai.","en":"He is an honest person who never cheats anyone."},{"use":"Giải thích lý do: 实在 + tính từ.","ex":"今天实在太累了，我不想做饭。","py":"Jīntiān shízài tài lèi le, wǒ bù xiǎng zuò fàn.","vi":"Hôm nay mệt quá thật, tôi không muốn nấu cơm.","en":"I'm really too tired today; I don't want to cook."}]},"制冷":{"en":"to refrigerate; to cool","exs":[{"use":"制冷 làm động từ; thường nói về điều hòa.","ex":"这台空调制冷效果很好。","py":"Zhè tái kōngtiáo zhìlěng xiàoguǒ hěn hǎo.","vi":"Chiếc điều hòa này làm lạnh rất hiệu quả.","en":"This air conditioner cools very well."},{"use":"制冷 + 快 / 慢: tốc độ làm lạnh.","ex":"这个冰箱制冷快，省电。","py":"Zhège bīngxiāng zhìlěng kuài, shěng diàn.","vi":"Tủ lạnh này làm lạnh nhanh, tiết kiệm điện.","en":"This fridge cools fast and saves electricity."},{"use":"不制冷了 = không còn làm lạnh.","ex":"冰箱不制冷了，里面的东西都坏了。","py":"Bīngxiāng bú zhìlěng le, lǐmiàn de dōngxi dōu huài le.","vi":"Tủ lạnh không còn lạnh nữa, đồ bên trong hỏng hết rồi.","en":"The fridge stopped cooling and everything inside went bad."},{"use":"一直制冷: chạy làm lạnh liên tục.","ex":"夏天空调一直制冷，电费很高。","py":"Xiàtiān kōngtiáo yìzhí zhìlěng, diànfèi hěn gāo.","vi":"Mùa hè điều hòa chạy làm lạnh liên tục nên tiền điện rất cao.","en":"In summer the air conditioner runs nonstop, so the electricity bill is high."}]},"效果":{"en":"effect; result; efficacy","exs":[{"use":"效果好/不好.","ex":"这个办法效果很好。","py":"Zhège bànfǎ xiàoguǒ hěn hǎo.","vi":"Cách này hiệu quả rất tốt.","en":"This method works very well."},{"use":"效果 + 明显 / 不明显.","ex":"这种药的效果不太明显。","py":"Zhè zhǒng yào de xiàoguǒ bú tài míngxiǎn.","vi":"Hiệu quả của loại thuốc này không rõ rệt lắm.","en":"The effect of this medicine is not very obvious."},{"use":"广告的效果: tác dụng của quảng cáo.","ex":"这个广告的效果很好，卖了很多东西。","py":"Zhège guǎnggào de xiàoguǒ hěn hǎo, mài le hěn duō dōngxi.","vi":"Quảng cáo này hiệu quả rất tốt, bán được nhiều hàng.","en":"This ad worked well and sold a lot of products."},{"use":"没有什么效果 = chẳng có tác dụng gì.","ex":"这样做没有什么效果。","py":"Zhèyàng zuò méiyǒu shénme xiàoguǒ.","vi":"Làm như thế chẳng có hiệu quả gì.","en":"Doing it this way has no effect."},{"use":"学习效果: hiệu quả học tập.","ex":"每天复习，学习效果会更好。","py":"Měitiān fùxí, xuéxí xiàoguǒ huì gèng hǎo.","vi":"Ngày nào cũng ôn tập thì hiệu quả học tập sẽ tốt hơn.","en":"If you review every day, your study results will be better."}]},"现金":{"en":"cash","exs":[{"use":"用现金 / 用手机: phương thức thanh toán.","ex":"这里可以用现金，也可以用手机付钱。","py":"Zhèlǐ kěyǐ yòng xiànjīn, yě kěyǐ yòng shǒujī fù qián.","vi":"Ở đây có thể dùng tiền mặt, cũng có thể trả bằng điện thoại.","en":"You can pay in cash here, or with your phone."},{"use":"没带现金 = không mang tiền mặt.","ex":"我身上没带现金。","py":"Wǒ shēnshang méi dài xiànjīn.","vi":"Trên người tôi không mang tiền mặt.","en":"I don't have any cash on me."},{"use":"付现金还是刷卡: câu hỏi khi thanh toán.","ex":"您付现金还是刷卡？","py":"Nín fù xiànjīn háishi shuā kǎ?","vi":"Quý khách trả tiền mặt hay quẹt thẻ?","en":"Will you pay in cash or by card?"},{"use":"只收现金 = chỉ nhận tiền mặt.","ex":"这家小店只收现金。","py":"Zhè jiā xiǎo diàn zhǐ shōu xiànjīn.","vi":"Quán nhỏ này chỉ nhận tiền mặt.","en":"This little shop only accepts cash."}]},"信用卡":{"en":"credit card","exs":[{"use":"用信用卡 + 付钱.","ex":"你可以用信用卡付钱。","py":"Nǐ kěyǐ yòng xìnyòngkǎ fù qián.","vi":"Bạn có thể trả tiền bằng thẻ tín dụng.","en":"You can pay with a credit card."},{"use":"信用卡丢了 = mất thẻ tín dụng.","ex":"我的信用卡丢了，得马上打电话。","py":"Wǒ de xìnyòngkǎ diū le, děi mǎshàng dǎ diànhuà.","vi":"Thẻ tín dụng của tôi bị mất, phải gọi điện ngay.","en":"I lost my credit card; I have to call right away."},{"use":"刷信用卡 = quẹt thẻ tín dụng.","ex":"这家饭馆不能刷信用卡。","py":"Zhè jiā fànguǎn bù néng shuā xìnyòngkǎ.","vi":"Nhà hàng này không quẹt thẻ tín dụng được.","en":"This restaurant doesn't accept credit cards."},{"use":"办信用卡 = làm thẻ tín dụng; lượng từ 张.","ex":"办一张信用卡要带身份证。","py":"Bàn yì zhāng xìnyòngkǎ yào dài shēnfènzhèng.","vi":"Làm một thẻ tín dụng cần mang theo chứng minh thư.","en":"You need your ID to apply for a credit card."}]},"邀请":{"en":"to invite; invitation","exs":[{"use":"邀请 + người + V: mời ai làm gì.","ex":"他邀请我参加他的生日聚会。","py":"Tā yāoqǐng wǒ cānjiā tā de shēngrì jùhuì.","vi":"Anh ấy mời tôi tham dự tiệc sinh nhật của anh ấy.","en":"He invited me to his birthday party."},{"use":"Danh từ: 谢谢你的邀请.","ex":"谢谢你的邀请。","py":"Xièxie nǐ de yāoqǐng.","vi":"Cảm ơn lời mời của bạn.","en":"Thank you for your invitation."},{"use":"邀请了 + số lượng + người + V.","ex":"我们邀请了很多朋友来家里吃饭。","py":"Wǒmen yāoqǐng le hěn duō péngyou lái jiālǐ chī fàn.","vi":"Chúng tôi đã mời nhiều bạn đến nhà ăn cơm.","en":"We invited many friends to come to our home for dinner."},{"use":"邀请 + người + 去…… (mời đến một nơi).","ex":"老师邀请我们去她家过中秋节。","py":"Lǎoshī yāoqǐng wǒmen qù tā jiā guò Zhōngqiūjié.","vi":"Cô giáo mời chúng tôi đến nhà cô đón Tết Trung thu.","en":"Our teacher invited us to her home for the Mid-Autumn Festival."}]},"做客":{"en":"to be a guest; to visit","exs":[{"use":"去 + nhà ai + 做客.","ex":"周末朋友请我去他家做客。","py":"Zhōumò péngyou qǐng wǒ qù tā jiā zuòkè.","vi":"Cuối tuần bạn mời tôi đến nhà chơi.","en":"My friend invited me to visit his home this weekend."},{"use":"欢迎 + 来 + 做客: lời mời.","ex":"欢迎你来我们家做客。","py":"Huānyíng nǐ lái wǒmen jiā zuòkè.","vi":"Hoan nghênh bạn đến nhà chúng tôi chơi.","en":"You're welcome to visit our home."},{"use":"Đến nhà người khác: nên mang quà.","ex":"第一次去别人家做客，应该带一点儿礼物。","py":"Dì yī cì qù biérén jiā zuòkè, yīnggāi dài yìdiǎnr lǐwù.","vi":"Lần đầu đến nhà người khác làm khách, nên mang theo chút quà.","en":"When visiting someone's home for the first time, you should bring a small gift."},{"use":"在 + nhà ai + 做客: đang làm khách.","ex":"他在王老师家做客，聊了一下午。","py":"Tā zài Wáng lǎoshī jiā zuòkè, liáo le yí xiàwǔ.","vi":"Anh ấy làm khách ở nhà thầy Vương, trò chuyện cả buổi chiều.","en":"He was a guest at Teacher Wang's home and chatted all afternoon."}]},"点儿":{"en":"a little; a bit (measure word)","exs":[{"use":"Tính từ + 一点儿: hơn một chút.","ex":"请再说慢一点儿。","py":"Qǐng zài shuō màn yìdiǎnr.","vi":"Xin nói chậm hơn một chút.","en":"Please speak a little slower."},{"use":"V + 点儿 + N: một ít.","ex":"我想喝点儿水。","py":"Wǒ xiǎng hē diǎnr shuǐ.","vi":"Tôi muốn uống chút nước.","en":"I'd like to drink some water."},{"use":"有点儿 + tính từ: hơi (thường nghĩa không tốt).","ex":"我今天有点儿累。","py":"Wǒ jīntiān yǒudiǎnr lèi.","vi":"Hôm nay tôi hơi mệt.","en":"I'm a bit tired today."},{"use":"Tính từ + 点儿: yêu cầu nhẹ nhàng khi mặc cả.","ex":"这件衣服能便宜点儿吗？","py":"Zhè jiàn yīfu néng piányi diǎnr ma?","vi":"Chiếc áo này có thể rẻ hơn chút không?","en":"Can this piece be a bit cheaper?"}]},"礼物":{"en":"gift; present","exs":[{"use":"礼物 thường đi với 送、收到.","ex":"这是送给你的礼物。","py":"Zhè shì sòng gěi nǐ de lǐwù.","vi":"Đây là quà tặng cho bạn.","en":"This is a gift for you."},{"use":"生日礼物: quà sinh nhật.","ex":"我给妈妈买了一件生日礼物。","py":"Wǒ gěi māma mǎi le yí jiàn shēngrì lǐwù.","vi":"Tôi đã mua cho mẹ một món quà sinh nhật.","en":"I bought my mom a birthday gift."},{"use":"收到礼物 = nhận được quà.","ex":"他收到了很多新年礼物。","py":"Tā shōudào le hěn duō xīnnián lǐwù.","vi":"Anh ấy nhận được rất nhiều quà năm mới.","en":"He received many New Year gifts."},{"use":"送 + 人 + 什么礼物: hỏi tặng quà gì.","ex":"你想送她什么礼物？","py":"Nǐ xiǎng sòng tā shénme lǐwù?","vi":"Bạn định tặng cô ấy quà gì?","en":"What gift do you want to give her?"}]},"葡萄酒":{"en":"wine; grape wine","exs":[{"use":"红葡萄酒 = rượu vang đỏ.","ex":"他喜欢喝红葡萄酒。","py":"Tā xǐhuan hē hóng pútáojiǔ.","vi":"Anh ấy thích uống rượu vang đỏ.","en":"He likes to drink red wine."},{"use":"Lượng từ: 瓶 (chai).","ex":"这瓶葡萄酒是朋友从法国带来的。","py":"Zhè píng pútáojiǔ shì péngyou cóng Fǎguó dàilái de.","vi":"Chai rượu vang này là bạn mang từ Pháp về.","en":"This bottle of wine was brought from France by a friend."},{"use":"来一杯葡萄酒: gọi một ly rượu vang.","ex":"吃牛肉的时候，来一杯葡萄酒很不错。","py":"Chī niúròu de shíhou, lái yì bēi pútáojiǔ hěn búcuò.","vi":"Lúc ăn thịt bò, uống một ly rượu vang thì rất tuyệt.","en":"A glass of wine goes well with beef."},{"use":"买葡萄酒当礼物.","ex":"我们去商店买了两瓶葡萄酒当礼物。","py":"Wǒmen qù shāngdiàn mǎi le liǎng píng pútáojiǔ dàng lǐwù.","vi":"Chúng tôi đến cửa hàng mua hai chai rượu vang làm quà.","en":"We went to the store and bought two bottles of wine as a gift."}]},"可是":{"en":"but; however","exs":[{"use":"Chuyển ý: câu 1，可是 + câu 2.","ex":"这件衣服很好看，可是太贵了。","py":"Zhè jiàn yīfu hěn hǎokàn, kěshì tài guì le.","vi":"Chiếc áo này rất đẹp, nhưng đắt quá.","en":"This piece looks great, but it's too expensive."},{"use":"很想……，可是没有……","ex":"我很想去，可是没有时间。","py":"Wǒ hěn xiǎng qù, kěshì méiyǒu shíjiān.","vi":"Tôi rất muốn đi, nhưng không có thời gian.","en":"I really want to go, but I don't have time."},{"use":"虽然……，可是……","ex":"虽然下雨了，可是他还是去跑步了。","py":"Suīrán xià yǔ le, kěshì tā háishi qù pǎobù le.","vi":"Tuy trời mưa nhưng anh ấy vẫn đi chạy bộ.","en":"Although it was raining, he still went running."},{"use":"可是 đứng đầu vế sau, chuyển ý nhẹ.","ex":"他中文说得不太好，可是很喜欢聊天。","py":"Tā Zhōngwén shuō de bú tài hǎo, kěshì hěn xǐhuan liáotiān.","vi":"Anh ấy nói tiếng Trung không giỏi lắm, nhưng rất thích trò chuyện.","en":"His Chinese isn't very good, but he loves to chat."}]},"酒瓶":{"en":"wine bottle; liquor bottle","exs":[{"use":"把 + 空酒瓶 + 放…: chai rượu rỗng.","ex":"请把空酒瓶放在门外。","py":"Qǐng bǎ kōng jiǔpíng fàng zài mén wài.","vi":"Xin hãy để vỏ chai rượu ngoài cửa.","en":"Please put the empty bottles outside the door."},{"use":"Lượng từ: 个.","ex":"桌子上有一个漂亮的酒瓶。","py":"Zhuōzi shang yǒu yí gè piàoliang de jiǔpíng.","vi":"Trên bàn có một chai rượu rất đẹp.","en":"There is a pretty wine bottle on the table."},{"use":"酒瓶 làm chủ ngữ: 掉在地上摔坏了.","ex":"酒瓶掉在地上摔坏了。","py":"Jiǔpíng diào zài dì shang shuāi huài le.","vi":"Chai rượu rơi xuống đất vỡ mất.","en":"The bottle fell on the floor and broke."},{"use":"把 + 酒瓶 + 拿去卖: bán phế liệu.","ex":"他把用完的酒瓶拿去卖了。","py":"Tā bǎ yòng wán de jiǔpíng ná qù mài le.","vi":"Anh ấy mang những chai rượu đã dùng hết đi bán.","en":"He took the empty bottles away to sell them."}]},"艺术":{"en":"art","exs":[{"use":"一门艺术 = một loại nghệ thuật.","ex":"说话也是一门艺术。","py":"Shuōhuà yě shì yì mén yìshù.","vi":"Nói chuyện cũng là một nghệ thuật.","en":"Speaking is also an art."},{"use":"喜欢艺术: yêu thích nghệ thuật nói chung.","ex":"她从小就喜欢艺术，会画画儿也会唱歌。","py":"Tā cóngxiǎo jiù xǐhuan yìshù, huì huà huàr yě huì chàng gē.","vi":"Cô ấy từ nhỏ đã thích nghệ thuật, biết vẽ cũng biết hát.","en":"She has loved art since childhood and can both paint and sing."},{"use":"艺术家 = nghệ sĩ.","ex":"他是一位有名的艺术家。","py":"Tā shì yí wèi yǒumíng de yìshùjiā.","vi":"Ông ấy là một nghệ sĩ nổi tiếng.","en":"He is a famous artist."},{"use":"学艺术 = học nghệ thuật.","ex":"他在大学学艺术。","py":"Tā zài dàxué xué yìshù.","vi":"Anh ấy học nghệ thuật ở đại học.","en":"He studies art at university."}]},"电视":{"en":"television; TV","exs":[{"use":"看电视 = xem ti vi.","ex":"晚上我们一家人一起看电视。","py":"Wǎnshang wǒmen yì jiā rén yìqǐ kàn diànshì.","vi":"Buổi tối cả nhà chúng tôi cùng xem ti vi.","en":"In the evening, our whole family watches TV together."},{"use":"Lượng từ: 台.","ex":"这台电视是新买的。","py":"Zhè tái diànshì shì xīn mǎi de.","vi":"Chiếc ti vi này mới mua.","en":"This TV was newly bought."},{"use":"电视里的 + danh từ: chương trình trên TV.","ex":"我最喜欢看电视里的体育节目。","py":"Wǒ zuì xǐhuan kàn diànshì lǐ de tǐyù jiémù.","vi":"Tôi thích xem nhất là các chương trình thể thao trên ti vi.","en":"I like watching sports programs on TV the most."},{"use":"关电视 = tắt ti vi.","ex":"他把电视关了，去睡觉。","py":"Tā bǎ diànshì guān le, qù shuìjiào.","vi":"Anh ấy tắt ti vi rồi đi ngủ.","en":"He turned off the TV and went to bed."}]},"广告":{"en":"advertisement; ad; commercial","exs":[{"use":"电视里的广告: quảng cáo trên TV.","ex":"电视里的广告太多了。","py":"Diànshì lǐ de guǎnggào tài duō le.","vi":"Quảng cáo trên ti vi nhiều quá.","en":"There are too many ads on TV."},{"use":"Đánh giá một quảng cáo.","ex":"这个广告很有意思，我看了好几遍。","py":"Zhège guǎnggào hěn yǒu yìsi, wǒ kàn le hǎo jǐ biàn.","vi":"Quảng cáo này rất thú vị, tôi xem mấy lần liền.","en":"This ad is interesting; I watched it several times."},{"use":"做广告 = quảng cáo (động từ cụm).","ex":"他们公司在报纸上做广告。","py":"Tāmen gōngsī zài bàozhǐ shang zuò guǎnggào.","vi":"Công ty họ đăng quảng cáo trên báo.","en":"Their company advertises in the newspaper."},{"use":"发广告 = phát tờ rơi quảng cáo.","ex":"马路上有人在发广告。","py":"Mǎlù shang yǒu rén zài fā guǎnggào.","vi":"Trên đường có người đang phát quảng cáo.","en":"Someone is handing out ads on the street."}]},"味道":{"en":"taste; flavor; smell","exs":[{"use":"Mùi vị của món ăn.","ex":"这道菜的味道很好。","py":"Zhè dào cài de wèidao hěn hǎo.","vi":"Món này có vị rất ngon.","en":"This dish tastes very good."},{"use":"味道 = mùi (ngửi thấy).","ex":"房间里有一种奇怪的味道。","py":"Fángjiān lǐ yǒu yì zhǒng qíguài de wèidao.","vi":"Trong phòng có một mùi lạ.","en":"There is a strange smell in the room."},{"use":"味道怎么样? hỏi cảm nhận về vị.","ex":"你尝尝这个，味道怎么样？","py":"Nǐ chángchang zhège, wèidao zěnmeyàng?","vi":"Bạn nếm thử cái này xem, vị thế nào?","en":"Try this; how does it taste?"},{"use":"Nghĩa bóng: có cảm giác, không khí.","ex":"这里的咖啡有家的味道。","py":"Zhèlǐ de kāfēi yǒu jiā de wèidao.","vi":"Cà phê ở đây có hương vị của gia đình.","en":"The coffee here tastes like home."}]},"优点":{"en":"strong point; merit; advantage","exs":[{"use":"有自己的优点.","ex":"每个人都有自己的优点。","py":"Měi gè rén dōu yǒu zìjǐ de yōudiǎn.","vi":"Mỗi người đều có ưu điểm riêng.","en":"Everyone has their own strengths."},{"use":"……的优点是…: nêu ưu điểm của sản phẩm.","ex":"这个手机的优点是电池用得久。","py":"Zhège shǒujī de yōudiǎn shì diànchí yòng de jiǔ.","vi":"Ưu điểm của chiếc điện thoại này là pin dùng lâu.","en":"The advantage of this phone is its long battery life."},{"use":"优点和缺点: đối lập với 缺点.","ex":"这个方法有优点，也有缺点。","py":"Zhège fāngfǎ yǒu yōudiǎn, yě yǒu quēdiǎn.","vi":"Phương pháp này có ưu điểm, cũng có khuyết điểm.","en":"This method has both advantages and disadvantages."},{"use":"看别人的优点: nhìn vào điểm tốt của người khác.","ex":"我们要多看别人的优点。","py":"Wǒmen yào duō kàn biérén de yōudiǎn.","vi":"Chúng ta nên nhìn nhiều hơn vào ưu điểm của người khác.","en":"We should focus more on other people's strengths."}]},"实际上":{"en":"in fact; actually; in reality","exs":[{"use":"……，实际上……: đối lập vẻ ngoài và thực tế.","ex":"他看上去很年轻，实际上已经四十岁了。","py":"Tā kàn shangqu hěn niánqīng, shíjì shang yǐjīng sìshí suì le.","vi":"Anh ấy trông rất trẻ, thực ra đã bốn mươi tuổi rồi.","en":"He looks young, but he's actually forty."},{"use":"实际上 + 并不……: thực tế không như vậy.","ex":"大家都说很难，实际上并不难。","py":"Dàjiā dōu shuō hěn nán, shíjì shang bìng bù nán.","vi":"Mọi người đều nói khó, nhưng thực ra không khó.","en":"Everyone says it's hard, but actually it isn't."},{"use":"我以为……，实际上……: đính chính hiểu lầm.","ex":"我以为他是中国人，实际上他是日本人。","py":"Wǒ yǐwéi tā shì Zhōngguórén, shíjì shang tā shì Rìběnrén.","vi":"Tôi tưởng anh ấy là người Trung Quốc, thật ra anh ấy là người Nhật.","en":"I thought he was Chinese, but he's actually Japanese."},{"use":"Đứng đầu câu, giải thích thực tế.","ex":"实际上，我也不太清楚这件事。","py":"Shíjì shang, wǒ yě bú tài qīngchu zhè jiàn shì.","vi":"Thật ra, tôi cũng không rõ lắm chuyện này.","en":"Actually, I'm not too clear about this matter either."}]},"不能":{"en":"cannot; must not; may not","exs":[{"use":"不能 = không được phép (quy định).","ex":"这里不能抽烟。","py":"Zhèlǐ bù néng chōu yān.","vi":"Ở đây không được hút thuốc.","en":"You can't smoke here."},{"use":"不能 = không thể (do hoàn cảnh).","ex":"我感冒了，不能去上课。","py":"Wǒ gǎnmào le, bù néng qù shàngkè.","vi":"Tôi bị cảm, không thể đi học.","en":"I have a cold and can't go to class."},{"use":"不能 + 这样 + V: khuyên can, phê bình.","ex":"你不能这样说他。","py":"Nǐ bù néng zhèyàng shuō tā.","vi":"Bạn không thể nói anh ấy như thế.","en":"You can't talk about him like that."},{"use":"不能 + V: điều cấm cho trẻ em.","ex":"孩子不能一个人过马路。","py":"Háizi bù néng yí gè rén guò mǎlù.","vi":"Trẻ con không được tự mình băng qua đường.","en":"Children must not cross the road alone."},{"use":"不能 + 喝酒: kiêng cữ vì sức khỏe.","ex":"病人不能喝酒。","py":"Bìngrén bù néng hē jiǔ.","vi":"Người bệnh không được uống rượu.","en":"Patients must not drink alcohol."}]},"支持":{"en":"to support; to back; support","exs":[{"use":"支持 + người / ý kiến.","ex":"谢谢大家的支持。","py":"Xièxie dàjiā de zhīchí.","vi":"Cảm ơn sự ủng hộ của mọi người.","en":"Thank you all for your support."},{"use":"Động từ: 支持 + quyết định, ý kiến.","ex":"我支持你的决定。","py":"Wǒ zhīchí nǐ de juédìng.","vi":"Tôi ủng hộ quyết định của bạn.","en":"I support your decision."},{"use":"支持 + người + V: ủng hộ ai làm gì.","ex":"家人都支持我去国外学习。","py":"Jiārén dōu zhīchí wǒ qù guówài xuéxí.","vi":"Cả nhà đều ủng hộ tôi đi du học.","en":"My family all support me studying abroad."},{"use":"Danh từ: 没有……的支持.","ex":"没有家人的支持，我很难坚持下来。","py":"Méiyǒu jiārén de zhīchí, wǒ hěn nán jiānchí xiàlai.","vi":"Không có sự ủng hộ của gia đình, tôi khó mà kiên trì được.","en":"Without my family's support, it would be hard for me to keep going."}]},"举行":{"en":"to hold (a meeting, ceremony, etc.)","exs":[{"use":"举行 + hoạt động chính thức (lễ, cuộc thi, hội nghị).","ex":"学校举行了运动会。","py":"Xuéxiào jǔxíng le yùndònghuì.","vi":"Nhà trường đã tổ chức hội thao.","en":"The school held a sports meet."},{"use":"在 + địa điểm/thời gian + 举行.","ex":"婚礼将在下周六举行。","py":"Hūnlǐ jiāng zài xià zhōuliù jǔxíng.","vi":"Lễ cưới sẽ được tổ chức vào thứ Bảy tuần sau.","en":"The wedding will be held next Saturday."},{"use":"举行 + 会议.","ex":"明天上午九点举行会议。","py":"Míngtiān shàngwǔ jiǔ diǎn jǔxíng huìyì.","vi":"Chín giờ sáng mai sẽ họp.","en":"A meeting will be held tomorrow at nine a.m."},{"use":"每年举行: sự kiện định kỳ.","ex":"我们学校每年六月举行毕业典礼。","py":"Wǒmen xuéxiào měi nián liù yuè jǔxíng bìyè diǎnlǐ.","vi":"Trường chúng tôi mỗi năm vào tháng Sáu tổ chức lễ tốt nghiệp.","en":"Our school holds its graduation ceremony every June."}]},"活动":{"en":"activity; event; to exercise; to move about","exs":[{"use":"举办活动 = tổ chức hoạt động.","ex":"周末有一个读书活动。","py":"Zhōumò yǒu yí gè dúshū huódòng.","vi":"Cuối tuần có một hoạt động đọc sách.","en":"There is a reading event this weekend."},{"use":"Động từ: 活动活动 = vận động cho giãn gân cốt.","ex":"坐了很久，站起来活动活动身体吧。","py":"Zuò le hěn jiǔ, zhàn qǐlai huódòng huódòng shēntǐ ba.","vi":"Ngồi lâu rồi, đứng dậy vận động người một chút đi.","en":"You've been sitting a long time; stand up and move around."},{"use":"组织 + 活动: tổ chức hoạt động tập thể.","ex":"周末公司组织了一次爬山活动。","py":"Zhōumò gōngsī zǔzhī le yí cì páshān huódòng.","vi":"Cuối tuần công ty tổ chức một buổi hoạt động leo núi.","en":"The company organized a hiking activity over the weekend."},{"use":"Động từ: người già vận động ngoài trời.","ex":"老人早上喜欢在公园里活动。","py":"Lǎorén zǎoshang xǐhuan zài gōngyuán lǐ huódòng.","vi":"Người già buổi sáng thích vận động trong công viên.","en":"Older people like to exercise in the park in the morning."},{"use":"参加活动 = tham gia hoạt động.","ex":"你想参加这次活动吗？","py":"Nǐ xiǎng cānjiā zhè cì huódòng ma?","vi":"Bạn có muốn tham gia hoạt động lần này không?","en":"Do you want to take part in this event?"}]},"词典":{"en":"dictionary","exs":[{"use":"查词典 = tra từ điển.","ex":"不会的词可以查词典。","py":"Bú huì de cí kěyǐ chá cídiǎn.","vi":"Từ nào không biết có thể tra từ điển.","en":"You can look up words you don't know in a dictionary."},{"use":"Lượng từ: 本 (quyển).","ex":"这本词典很厚，里面的词很多。","py":"Zhè běn cídiǎn hěn hòu, lǐmiàn de cí hěn duō.","vi":"Quyển từ điển này rất dày, có rất nhiều từ.","en":"This dictionary is thick and has a lot of words."},{"use":"汉语词典 = từ điển tiếng Hán.","ex":"我买了一本汉语词典。","py":"Wǒ mǎi le yì běn Hànyǔ cídiǎn.","vi":"Tôi đã mua một quyển từ điển tiếng Hán.","en":"I bought a Chinese dictionary."},{"use":"电子词典 = từ điển điện tử.","ex":"手机上有电子词典，查词很方便。","py":"Shǒujī shang yǒu diànzǐ cídiǎn, chá cí hěn fāngbiàn.","vi":"Trong điện thoại có từ điển điện tử, tra từ rất tiện.","en":"There's an electronic dictionary on my phone, so looking up words is easy."},{"use":"带词典来上课.","ex":"老师让我们带词典来上课。","py":"Lǎoshī ràng wǒmen dài cídiǎn lái shàngkè.","vi":"Thầy giáo bảo chúng tôi mang từ điển đến lớp.","en":"The teacher asked us to bring dictionaries to class."}]},"免费":{"en":"free of charge; to be free","exs":[{"use":"免费 + động từ / 是免费的.","ex":"这个活动是免费的。","py":"Zhège huódòng shì miǎnfèi de.","vi":"Hoạt động này miễn phí.","en":"This event is free."},{"use":"Tính từ: 是……免费的.","ex":"这家酒店的早饭是免费的。","py":"Zhè jiā jiǔdiàn de zǎofàn shì miǎnfèi de.","vi":"Bữa sáng của khách sạn này miễn phí.","en":"Breakfast at this hotel is free."},{"use":"免费 + V: làm gì miễn phí (trạng ngữ).","ex":"学生可以免费参观博物馆。","py":"Xuésheng kěyǐ miǎnfèi cānguān bówùguǎn.","vi":"Học sinh được tham quan bảo tàng miễn phí.","en":"Students can visit the museum for free."},{"use":"免费的 + danh từ: dịch vụ/đồ miễn phí.","ex":"这里提供免费的茶水。","py":"Zhèlǐ tígōng miǎnfèi de cháshuǐ.","vi":"Ở đây cung cấp trà nước miễn phí.","en":"Free tea and water are provided here."},{"use":"Động từ: 身高 + 以下 + 免费 (được miễn phí).","ex":"孩子身高一米二以下免费。","py":"Háizi shēngāo yì mǐ èr yǐxià miǎnfèi.","vi":"Trẻ em cao dưới một mét hai được miễn phí.","en":"Children under 1.2 meters tall get in free."}]},"会员卡":{"en":"membership card; member card","exs":[{"use":"办会员卡 = làm thẻ hội viên.","ex":"办会员卡可以打折。","py":"Bàn huìyuánkǎ kěyǐ dǎzhé.","vi":"Làm thẻ hội viên có thể được giảm giá.","en":"You can get a discount if you sign up for a membership card."},{"use":"补办会员卡 = làm lại thẻ; 一张会员卡 (lượng từ 张).","ex":"我的会员卡丢了，想重新补办一张。","py":"Wǒ de huìyuánkǎ diū le, xiǎng chóngxīn bǔbàn yì zhāng.","vi":"Thẻ hội viên của tôi bị mất, tôi muốn làm lại một cái.","en":"I lost my membership card and want to get a replacement."},{"use":"出示会员卡 = xuất trình thẻ hội viên khi thanh toán.","ex":"结账的时候请出示您的会员卡。","py":"Jiézhàng de shíhou qǐng chūshì nín de huìyuánkǎ.","vi":"Khi thanh toán xin quý khách xuất trình thẻ hội viên.","en":"Please show your membership card when you pay."},{"use":"会员卡 làm định ngữ chỉ thẻ của một nơi: 健身房的会员卡.","ex":"这家健身房的会员卡一年一千块。","py":"Zhè jiā jiànshēnfáng de huìyuánkǎ yì nián yì qiān kuài.","vi":"Thẻ hội viên của phòng tập này một năm một nghìn tệ.","en":"The membership card for this gym costs a thousand yuan a year."}]},"小说":{"en":"novel; fiction","exs":[{"use":"看小说 / 写小说.","ex":"他喜欢看小说。","py":"Tā xǐhuan kàn xiǎoshuō.","vi":"Anh ấy thích đọc tiểu thuyết.","en":"He likes reading novels."},{"use":"这本小说: lượng từ 本; 有意思 = thú vị.","ex":"这本小说很有意思，我一晚上就看完了。","py":"Zhè běn xiǎoshuō hěn yǒuyìsi, wǒ yì wǎnshang jiù kàn wán le.","vi":"Cuốn tiểu thuyết này rất hay, tôi đọc xong trong một buổi tối.","en":"This novel is very interesting; I finished it in one evening."},{"use":"写小说; lượng từ 部 cho tác phẩm dài.","ex":"她打算写一部关于家乡的小说。","py":"Tā dǎsuàn xiě yí bù guānyú jiāxiāng de xiǎoshuō.","vi":"Cô ấy định viết một cuốn tiểu thuyết về quê hương.","en":"She plans to write a novel about her hometown."},{"use":"Thể loại + 小说: 爱情小说, 历史小说.","ex":"我最爱看爱情小说和历史小说。","py":"Wǒ zuì ài kàn àiqíng xiǎoshuō hé lìshǐ xiǎoshuō.","vi":"Tôi thích đọc nhất là tiểu thuyết tình yêu và tiểu thuyết lịch sử.","en":"I love reading romance novels and historical novels most."}]},"地图":{"en":"map","exs":[{"use":"看地图 = xem bản đồ.","ex":"我用手机看地图。","py":"Wǒ yòng shǒujī kàn dìtú.","vi":"Tôi dùng điện thoại để xem bản đồ.","en":"I use my phone to look at a map."},{"use":"把 + 地图 + 打开; 在哪儿 = ở đâu.","ex":"请把地图打开，看看我们现在在哪儿。","py":"Qǐng bǎ dìtú dǎkāi, kànkan wǒmen xiànzài zài nǎr.","vi":"Hãy mở bản đồ ra xem bây giờ chúng ta đang ở đâu.","en":"Please open the map and see where we are now."},{"use":"Lượng từ 张; 中国地图 = bản đồ Trung Quốc.","ex":"这张中国地图上有很多城市的名字。","py":"Zhè zhāng Zhōngguó dìtú shàng yǒu hěn duō chéngshì de míngzi.","vi":"Trên tấm bản đồ Trung Quốc này có tên của rất nhiều thành phố.","en":"This map of China has the names of many cities on it."},{"use":"没有 + 地图: dùng trong câu giả thiết.","ex":"没有地图，我们很容易迷路。","py":"Méiyǒu dìtú, wǒmen hěn róngyì mílù.","vi":"Không có bản đồ, chúng tôi rất dễ bị lạc đường.","en":"Without a map, we can easily get lost."}]},"留学":{"en":"to study abroad","exs":[{"use":"去 + nước + 留学; 留学生 = du học sinh.","ex":"她想去英国留学。","py":"Tā xiǎng qù Yīngguó liúxué.","vi":"Cô ấy muốn sang Anh du học.","en":"She wants to go to Britain to study abroad."},{"use":"在 + nơi + 留学 + thời gian.","ex":"他在美国留学三年了。","py":"Tā zài Měiguó liúxué sān nián le.","vi":"Anh ấy du học ở Mỹ ba năm rồi.","en":"He has been studying in the United States for three years."},{"use":"留学生 = du học sinh (danh từ).","ex":"很多留学生周末喜欢一起做饭。","py":"Hěn duō liúxuéshēng zhōumò xǐhuan yìqǐ zuòfàn.","vi":"Nhiều du học sinh cuối tuần thích cùng nhau nấu ăn.","en":"Many international students like cooking together on weekends."},{"use":"Động từ + 留学 trong mệnh đề thời gian: 留学…以前 / 以后.","ex":"去国外留学以前，你要先准备好签证。","py":"Qù guówài liúxué yǐqián, nǐ yào xiān zhǔnbèi hǎo qiānzhèng.","vi":"Trước khi ra nước ngoài du học, bạn phải chuẩn bị xong visa.","en":"Before going abroad to study, you need to get your visa ready."}]},"获得":{"en":"to obtain; to gain; to win; to receive","exs":[{"use":"获得 + giải thưởng / cơ hội / thành công.","ex":"他获得了第一名。","py":"Tā huòdé le dì-yī míng.","vi":"Anh ấy đã giành được hạng nhất.","en":"He won first place."},{"use":"Nghĩa 'nhận được': 获得 + học bổng / giải thưởng.","ex":"经过努力，她获得了奖学金。","py":"Jīngguò nǔlì, tā huòdé le jiǎngxuéjīn.","vi":"Sau nỗ lực, cô ấy đã nhận được học bổng.","en":"After working hard, she received a scholarship."},{"use":"Nghĩa 'có được': 获得 + kinh nghiệm / kiến thức (trừu tượng).","ex":"通过这次旅行，我获得了很多新的经验。","py":"Tōngguò zhè cì lǚxíng, wǒ huòdé le hěn duō xīn de jīngyàn.","vi":"Qua chuyến đi này, tôi đã có được nhiều kinh nghiệm mới.","en":"Through this trip, I gained a lot of new experience."},{"use":"获得 + sự yêu thích / công nhận / tán thưởng.","ex":"这个电影获得了很多人的喜欢。","py":"Zhège diànyǐng huòdé le hěn duō rén de xǐhuan.","vi":"Bộ phim này được rất nhiều người yêu thích.","en":"This movie has won the affection of many people."}]},"选购":{"en":"to choose and buy; to select and purchase","exs":[{"use":"Hay dùng trong quảng cáo, cửa hàng.","ex":"欢迎大家选购。","py":"Huānyíng dàjiā xuǎngòu.","vi":"Hoan nghênh mọi người chọn mua.","en":"Everyone is welcome to pick out and buy."},{"use":"在 + nơi + 选购 + hàng hóa (mua sau khi chọn).","ex":"他在网上选购了一台新电脑。","py":"Tā zài wǎng shàng xuǎngòu le yì tái xīn diànnǎo.","vi":"Anh ấy chọn mua một chiếc máy tính mới trên mạng.","en":"He picked and bought a new computer online."},{"use":"去 + nơi + 选购 + đồ: chỉ mục đích đi mua sắm.","ex":"周末我们去商场选购新年礼物。","py":"Zhōumò wǒmen qù shāngchǎng xuǎngòu xīnnián lǐwù.","vi":"Cuối tuần chúng tôi đi trung tâm thương mại chọn mua quà năm mới.","en":"This weekend we're going to the mall to pick out New Year gifts."},{"use":"选购 + hàng hóa làm chủ ngữ của mệnh đề 'khi…'.","ex":"选购水果的时候要看新不新鲜。","py":"Xuǎngòu shuǐguǒ de shíhou yào kàn xīn bu xīnxiān.","vi":"Khi chọn mua trái cây phải xem có tươi hay không.","en":"When choosing fruit to buy, you should check whether it's fresh."}]},"一般":{"en":"ordinary; average; generally; usually","exs":[{"use":"一般 + động từ (phó từ: thường).","ex":"我一般七点起床。","py":"Wǒ yìbān qī diǎn qǐchuáng.","vi":"Tôi thường dậy lúc bảy giờ.","en":"I usually get up at seven."},{"use":"Tính từ làm vị ngữ: 一般 = bình thường, tầm tầm.","ex":"这家饭馆的菜味道一般，价格不便宜。","py":"Zhè jiā fànguǎn de cài wèidao yìbān, jiàgé bù piányi.","vi":"Món ăn ở quán này vị bình thường, giá lại không rẻ.","en":"The food at this restaurant tastes so-so, and the prices aren't cheap."},{"use":"一般来说 = nói chung, thông thường.","ex":"一般来说，周末超市的人比较多。","py":"Yìbān lái shuō, zhōumò chāoshì de rén bǐjiào duō.","vi":"Nói chung, cuối tuần siêu thị khá đông người.","en":"Generally speaking, supermarkets are more crowded on weekends."},{"use":"一般的 + danh từ = ... thông thường.","ex":"他的汉语水平和一般的学生差不多。","py":"Tā de Hànyǔ shuǐpíng hé yìbān de xuésheng chàbuduō.","vi":"Trình độ tiếng Trung của anh ấy xêm xêm học sinh bình thường.","en":"His Chinese level is about the same as an average student's."}]},"例如":{"en":"for example; for instance; such as","exs":[{"use":"Dùng trước ví dụ minh họa.","ex":"我喜欢水果，例如苹果。","py":"Wǒ xǐhuan shuǐguǒ, lìrú píngguǒ.","vi":"Tôi thích hoa quả, ví dụ như táo.","en":"I like fruit, for example apples."},{"use":"例如 + liệt kê nhiều ví dụ ngăn bằng dấu 、.","ex":"我去过很多国家，例如日本、泰国和法国。","py":"Wǒ qù guo hěn duō guójiā, lìrú Rìběn, Tàiguó hé Fǎguó.","vi":"Tôi đã đi nhiều nước, ví dụ Nhật Bản, Thái Lan và Pháp.","en":"I've been to many countries, such as Japan, Thailand and France."},{"use":"例如 + danh từ nêu ví dụ cho nơi chốn / sự vật nói trước.","ex":"这里有很多好玩的地方，例如公园和博物馆。","py":"Zhèlǐ yǒu hěn duō hǎowán de dìfang, lìrú gōngyuán hé bówùguǎn.","vi":"Ở đây có nhiều chỗ vui chơi, ví dụ công viên và bảo tàng.","en":"There are many fun places here, for example parks and museums."},{"use":"例如 + cả một mệnh đề / câu làm ví dụ.","ex":"很多城市都有地铁，例如北京就有二十多条线。","py":"Hěn duō chéngshì dōu yǒu dìtiě, lìrú Běijīng jiù yǒu èrshí duō tiáo xiàn.","vi":"Nhiều thành phố có tàu điện ngầm, ví dụ Bắc Kinh có hơn hai mươi tuyến.","en":"Many cities have subways; for example, Beijing has more than twenty lines."}]},"节日":{"en":"festival; holiday","exs":[{"use":"过节日 / 节日快乐.","ex":"春节是中国最大的节日。","py":"Chūnjié shì Zhōngguó zuì dà de jiérì.","vi":"Tết Xuân là ngày lễ lớn nhất của Trung Quốc.","en":"The Spring Festival is China's biggest holiday."},{"use":"……是……的节日: nói về ngày lễ của một nhóm người.","ex":"中秋节是中国人团圆的节日。","py":"Zhōngqiūjié shì Zhōngguó rén tuányuán de jiérì.","vi":"Tết Trung thu là ngày lễ đoàn viên của người Trung Quốc.","en":"The Mid-Autumn Festival is the holiday for Chinese families to reunite."},{"use":"节日快乐 = lời chúc ngày lễ.","ex":"节日快乐！祝你和家人幸福。","py":"Jiérì kuàilè! Zhù nǐ hé jiārén xìngfú.","vi":"Chúc mừng ngày lễ! Chúc bạn và gia đình hạnh phúc.","en":"Happy holidays! Wishing you and your family happiness."},{"use":"过节日的时候 = vào dịp lễ.","ex":"过节日的时候，街上到处都很热闹。","py":"Guò jiérì de shíhou, jiē shàng dàochù dōu hěn rènao.","vi":"Vào dịp lễ, trên phố đâu đâu cũng náo nhiệt.","en":"During holidays, the streets are lively everywhere."}]},"举办":{"en":"to hold; to organize (an event)","exs":[{"use":"举办 + hoạt động; gần nghĩa 举行.","ex":"公司举办了一次会议。","py":"Gōngsī jǔbàn le yí cì huìyì.","vi":"Công ty đã tổ chức một cuộc họp.","en":"The company held a meeting."},{"use":"举办 + 运动会 / 比赛 / 活动 (sự kiện thể thao, văn hóa).","ex":"学校下个月要举办运动会。","py":"Xuéxiào xià ge yuè yào jǔbàn yùndònghuì.","vi":"Tháng sau trường sẽ tổ chức hội thao.","en":"The school will hold a sports meet next month."},{"use":"由 + chủ thể + 举办 = do… tổ chức.","ex":"这次比赛由我们城市举办。","py":"Zhè cì bǐsài yóu wǒmen chéngshì jǔbàn.","vi":"Cuộc thi lần này do thành phố chúng tôi tổ chức.","en":"This competition is hosted by our city."},{"use":"举办 + 一场 + sự kiện (lượng từ 场).","ex":"他们打算在公园里举办一场生日晚会。","py":"Tāmen dǎsuàn zài gōngyuán lǐ jǔbàn yì chǎng shēngrì wǎnhuì.","vi":"Họ định tổ chức một buổi tiệc sinh nhật trong công viên.","en":"They plan to hold a birthday party in the park."}]},"各种各样":{"en":"all kinds of; various; of every description","exs":[{"use":"各种各样 + 的 + danh từ.","ex":"商店里有各种各样的东西。","py":"Shāngdiàn lǐ yǒu gèzhǒng gèyàng de dōngxi.","vi":"Trong cửa hàng có đủ loại đồ vật.","en":"There are all kinds of things in the store."},{"use":"各种各样的 + danh từ (trái cây, hàng hóa).","ex":"这个市场里有各种各样的水果。","py":"Zhège shìchǎng lǐ yǒu gèzhǒng gèyàng de shuǐguǒ.","vi":"Trong chợ này có đủ loại trái cây.","en":"This market has all kinds of fruit."},{"use":"Làm định ngữ chỉ sở thích, đồ chơi: 各种各样的玩具.","ex":"孩子们喜欢各种各样的玩具。","py":"Háizimen xǐhuan gèzhǒng gèyàng de wánjù.","vi":"Bọn trẻ thích đủ loại đồ chơi.","en":"Children like all sorts of toys."},{"use":"遇到 + 各种各样的人 = gặp đủ hạng người.","ex":"我在旅行中遇到了各种各样的人。","py":"Wǒ zài lǚxíng zhōng yùdào le gèzhǒng gèyàng de rén.","vi":"Trong chuyến đi tôi đã gặp đủ loại người.","en":"I met all sorts of people on my trip."},{"use":"Làm vị ngữ: chủ ngữ + 各种各样, rồi giải thích thêm.","ex":"他们的爱好各种各样，有的爱唱歌，有的爱画画。","py":"Tāmen de àihào gèzhǒng gèyàng, yǒu de ài chànggē, yǒu de ài huà huà.","vi":"Sở thích của họ muôn hình muôn vẻ, người thích hát, người thích vẽ.","en":"Their hobbies vary widely: some love singing, some love drawing."}]},"降低":{"en":"to lower; to reduce; to drop","exs":[{"use":"降低 + giá cả / chi phí / mức độ.","ex":"这个月价格降低了。","py":"Zhège yuè jiàgé jiàngdī le.","vi":"Tháng này giá đã giảm.","en":"Prices dropped this month."},{"use":"降低 + nguy cơ / khả năng (trừu tượng).","ex":"多运动可以降低生病的可能。","py":"Duō yùndòng kěyǐ jiàngdī shēngbìng de kěnéng.","vi":"Vận động nhiều có thể giảm khả năng bị bệnh.","en":"Exercising more can lower the chance of getting sick."},{"use":"把 + âm thanh + 降低 + 一点儿: hạ nhỏ xuống.","ex":"请把声音降低一点儿，孩子在睡觉。","py":"Qǐng bǎ shēngyīn jiàngdī yìdiǎnr, háizi zài shuìjiào.","vi":"Xin hạ âm thanh nhỏ lại một chút, em bé đang ngủ.","en":"Please turn the volume down a little; the child is sleeping."},{"use":"降低成本 = giảm chi phí (cụm cố định trong kinh doanh).","ex":"公司想办法降低成本。","py":"Gōngsī xiǎng bànfǎ jiàngdī chéngběn.","vi":"Công ty tìm cách giảm chi phí.","en":"The company is finding ways to cut costs."},{"use":"Chủ ngữ là nhiệt độ: 温度降低了 (tự giảm, không có tân ngữ).","ex":"天气冷了，温度降低了很多。","py":"Tiānqì lěng le, wēndù jiàngdī le hěn duō.","vi":"Trời lạnh rồi, nhiệt độ giảm đi nhiều.","en":"The weather has turned cold and the temperature has dropped a lot."}]},"朋友们":{"en":"friends (plural); everyone","exs":[{"use":"Gọi một nhóm bạn: 朋友们, … (lời gọi đầu câu).","ex":"朋友们，欢迎来到我家！","py":"Péngyoumen, huānyíng láidào wǒ jiā!","vi":"Các bạn ơi, chào mừng đến nhà tôi!","en":"Friends, welcome to my home!"},{"use":"我的朋友们 = các bạn của tôi (làm chủ ngữ).","ex":"我的朋友们都喜欢看电影。","py":"Wǒ de péngyoumen dōu xǐhuan kàn diànyǐng.","vi":"Các bạn của tôi đều thích xem phim.","en":"My friends all like watching movies."},{"use":"和 + 朋友们 + 一起 + V.","ex":"周末我和朋友们一起去爬山。","py":"Zhōumò wǒ hé péngyoumen yìqǐ qù páshān.","vi":"Cuối tuần tôi cùng các bạn đi leo núi.","en":"On weekends I go hiking with my friends."}]},"为了":{"en":"in order to; for the sake of; for","exs":[{"use":"为了 + mục đích, chủ ngữ + hành động.","ex":"为了健康，他每天早上跑步。","py":"Wèile jiànkāng, tā měitiān zǎoshang pǎobù.","vi":"Vì sức khỏe, mỗi sáng anh ấy chạy bộ.","en":"For his health, he runs every morning."},{"use":"Chủ ngữ + 为了 + V (mục đích đặt giữa câu).","ex":"他为了学好汉语，来中国留学。","py":"Tā wèile xuéhǎo Hànyǔ, lái Zhōngguó liúxué.","vi":"Để học giỏi tiếng Trung, anh ấy đến Trung Quốc du học.","en":"In order to learn Chinese well, he came to China to study."},{"use":"为了 + 不 + V = để không…","ex":"为了不迟到，我们坐出租车去吧。","py":"Wèile bù chídào, wǒmen zuò chūzūchē qù ba.","vi":"Để khỏi đến muộn, chúng ta đi taxi nhé.","en":"So as not to be late, let's take a taxi."},{"use":"是为了 + người = là vì…","ex":"这是为了你好，你别生气。","py":"Zhè shì wèile nǐ hǎo, nǐ bié shēngqì.","vi":"Đây là vì tốt cho bạn, đừng giận.","en":"This is for your own good, so don't be angry."}]},"书店":{"en":"bookstore; bookshop","exs":[{"use":"去书店 + V: đi hiệu sách làm gì.","ex":"我常去那家书店买书。","py":"Wǒ cháng qù nà jiā shūdiàn mǎi shū.","vi":"Tôi thường đến hiệu sách đó mua sách.","en":"I often go to that bookstore to buy books."},{"use":"书店在……旁边: chỉ vị trí.","ex":"书店在超市的旁边，很好找。","py":"Shūdiàn zài chāoshì de pángbiān, hěn hǎo zhǎo.","vi":"Hiệu sách ở cạnh siêu thị, rất dễ tìm.","en":"The bookstore is next to the supermarket and is easy to find."},{"use":"这家书店: lượng từ 家 cho cửa hàng.","ex":"这家书店晚上十点才关门。","py":"Zhè jiā shūdiàn wǎnshang shí diǎn cái guānmén.","vi":"Hiệu sách này mười giờ tối mới đóng cửa.","en":"This bookstore doesn't close until ten at night."}]},"图书":{"en":"books; (printed) publications","exs":[{"use":"图书 + 馆 / 公司: từ ghép thường gặp.","ex":"学校图书馆里有很多图书。","py":"Xuéxiào túshūguǎn lǐ yǒu hěn duō túshū.","vi":"Trong thư viện trường có rất nhiều sách.","en":"The school library has a lot of books."},{"use":"图书 là danh từ tập hợp, không dùng lượng từ riêng.","ex":"这些图书都可以免费借。","py":"Zhèxiē túshū dōu kěyǐ miǎnfèi jiè.","vi":"Những sách này đều có thể mượn miễn phí.","en":"All of these books can be borrowed for free."},{"use":"图书 làm định ngữ chỉ ngành nghề: 图书公司.","ex":"他在一家图书公司工作。","py":"Tā zài yì jiā túshū gōngsī gōngzuò.","vi":"Anh ấy làm việc ở một công ty sách.","en":"He works at a book publishing company."}]},"其中":{"en":"among them; of which; in it","exs":[{"use":"Số lượng tổng, 其中 + phần nhỏ trong đó.","ex":"我们班有二十个学生，其中十个是女生。","py":"Wǒmen bān yǒu èrshí ge xuésheng, qízhōng shí ge shì nǚshēng.","vi":"Lớp chúng tôi có hai mươi học sinh, trong đó mười em là nữ.","en":"There are twenty students in our class, ten of whom are girls."},{"use":"其中 + ... 最 ...: nêu cái nổi bật nhất.","ex":"他去过很多国家，其中印象最深的是日本。","py":"Tā qù guo hěn duō guójiā, qízhōng yìnxiàng zuì shēn de shì Rìběn.","vi":"Anh ấy đã đi nhiều nước, trong đó ấn tượng sâu nhất là Nhật Bản.","en":"He has been to many countries; Japan left the deepest impression."},{"use":"其中一 + lượng từ = một trong số đó.","ex":"桌子上有三本书，其中一本是新的。","py":"Zhuōzi shàng yǒu sān běn shū, qízhōng yì běn shì xīn de.","vi":"Trên bàn có ba quyển sách, trong đó có một quyển mới.","en":"There are three books on the table, one of which is new."}]},"考试":{"en":"to take an exam; exam; test","exs":[{"use":"Động từ: 考试 = thi, kiểm tra.","ex":"明天我们考试，今天要早点儿睡。","py":"Míngtiān wǒmen kǎoshì, jīntiān yào zǎodiǎnr shuì.","vi":"Ngày mai chúng tôi thi, hôm nay phải ngủ sớm.","en":"We have an exam tomorrow, so I need to sleep early today."},{"use":"Danh từ: 这次考试 = kỳ thi lần này.","ex":"这次考试不太难。","py":"Zhè cì kǎoshì bú tài nán.","vi":"Kỳ thi lần này không quá khó.","en":"This exam isn't too hard."},{"use":"考试 + 考得 + adj (lặp động từ khi có bổ ngữ).","ex":"他考试考得很好。","py":"Tā kǎoshì kǎo de hěn hǎo.","vi":"Anh ấy thi rất tốt.","en":"He did very well on the exam."},{"use":"参加 + 考试: tham gia kỳ thi.","ex":"参加汉语考试以前，要先报名。","py":"Cānjiā Hànyǔ kǎoshì yǐqián, yào xiān bàomíng.","vi":"Trước khi dự thi tiếng Trung phải đăng ký trước.","en":"Before taking the Chinese exam, you have to register first."}]},"生日":{"en":"birthday","exs":[{"use":"明天是我的生日: 是 + sinh nhật.","ex":"明天是我的生日，我想请朋友吃饭。","py":"Míngtiān shì wǒ de shēngrì, wǒ xiǎng qǐng péngyou chīfàn.","vi":"Ngày mai là sinh nhật tôi, tôi muốn mời bạn bè ăn cơm.","en":"Tomorrow is my birthday, and I want to treat my friends to a meal."},{"use":"祝你生日快乐 = chúc mừng sinh nhật.","ex":"祝你生日快乐！","py":"Zhù nǐ shēngrì kuàilè!","vi":"Chúc bạn sinh nhật vui vẻ!","en":"Happy birthday to you!"},{"use":"生日 làm định ngữ: 生日蛋糕, 生日礼物.","ex":"妈妈给我买了一个生日蛋糕。","py":"Māma gěi wǒ mǎi le yí ge shēngrì dàngāo.","vi":"Mẹ mua cho tôi một chiếc bánh sinh nhật.","en":"Mom bought me a birthday cake."},{"use":"Hỏi ngày sinh: 你的生日是几月几号？","ex":"你的生日是几月几号？","py":"Nǐ de shēngrì shì jǐ yuè jǐ hào?","vi":"Sinh nhật của bạn là ngày mấy tháng mấy?","en":"What is your birthday (month and day)?"}]},"所有":{"en":"all; every; whole","exs":[{"use":"所有的 + danh từ + 都 …","ex":"所有的学生都参加了这次活动。","py":"Suǒyǒu de xuésheng dōu cānjiā le zhè cì huódòng.","vi":"Tất cả học sinh đều tham gia hoạt động lần này.","en":"All the students took part in this activity."},{"use":"把 + 所有的 + danh từ + 都 + V.","ex":"他把所有的钱都花完了。","py":"Tā bǎ suǒyǒu de qián dōu huā wán le.","vi":"Anh ấy đã tiêu hết toàn bộ số tiền.","en":"He spent all of his money."},{"use":"所有人 = tất cả mọi người.","ex":"所有人都觉得这个办法很好。","py":"Suǒyǒu rén dōu juéde zhège bànfǎ hěn hǎo.","vi":"Mọi người đều thấy cách này rất tốt.","en":"Everyone thinks this method is very good."}]},"小朋友":{"en":"child; kid; little friend","exs":[{"use":"Gọi trẻ em: 小朋友们, …","ex":"小朋友们，今天我们来学唱歌。","py":"Xiǎopéngyoumen, jīntiān wǒmen lái xué chànggē.","vi":"Các bạn nhỏ ơi, hôm nay chúng ta học hát nhé.","en":"Children, today we're going to learn to sing."},{"use":"这个小朋友 + tuổi: nói về một em bé.","ex":"这个小朋友今年五岁了。","py":"Zhège xiǎopéngyou jīnnián wǔ suì le.","vi":"Bạn nhỏ này năm nay năm tuổi rồi.","en":"This little kid is five years old this year."},{"use":"很多小朋友在 + V: số đông trẻ em.","ex":"公园里有很多小朋友在玩。","py":"Gōngyuán lǐ yǒu hěn duō xiǎopéngyou zài wán.","vi":"Trong công viên có nhiều bạn nhỏ đang chơi.","en":"Many children are playing in the park."},{"use":"请 + 小朋友 + …: lời nhắc nhở lịch sự trên biển báo.","ex":"请小朋友一定要跟着大人。","py":"Qǐng xiǎopéngyou yídìng yào gēnzhe dàrén.","vi":"Các bạn nhỏ nhất định phải đi theo người lớn.","en":"Children, please be sure to stay with an adult."}]},"欢迎":{"en":"to welcome; welcome","exs":[{"use":"欢迎 + người + V: chào đón ai làm gì.","ex":"欢迎你来我们公司参观。","py":"Huānyíng nǐ lái wǒmen gōngsī cānguān.","vi":"Hoan nghênh bạn đến công ty chúng tôi tham quan.","en":"You're welcome to visit our company."},{"use":"欢迎光临 = kính chào quý khách (câu chào ở cửa hàng).","ex":"欢迎光临！请问几位？","py":"Huānyíng guānglín! Qǐngwèn jǐ wèi?","vi":"Kính chào quý khách! Xin hỏi mấy vị ạ?","en":"Welcome! How many in your party?"},{"use":"很欢迎 + người: hoan nghênh, đón nhận.","ex":"同学们都很欢迎新来的老师。","py":"Tóngxuémen dōu hěn huānyíng xīn lái de lǎoshī.","vi":"Các bạn học đều rất chào đón thầy cô giáo mới đến.","en":"The students all warmly welcomed the new teacher."},{"use":"受…欢迎 = được… yêu thích, ưa chuộng.","ex":"这部电影很受孩子们欢迎。","py":"Zhè bù diànyǐng hěn shòu háizimen huānyíng.","vi":"Bộ phim này rất được trẻ em yêu thích.","en":"This movie is very popular with children."}]},"意思":{"en":"meaning; idea; interest; token of goodwill","exs":[{"use":"Nghĩa 1: ý nghĩa của từ — 什么意思?","ex":"这个词是什么意思？","py":"Zhège cí shì shénme yìsi?","vi":"Từ này có nghĩa là gì?","en":"What does this word mean?"},{"use":"Nghĩa 2: ý định, ý tứ — 有……的意思.","ex":"你别误会，我没有别的意思。","py":"Nǐ bié wùhuì, wǒ méiyǒu bié de yìsi.","vi":"Bạn đừng hiểu lầm, tôi không có ý gì khác.","en":"Don't misunderstand; I don't mean anything else by it."},{"use":"有意思 = thú vị, hay.","ex":"这本书很有意思。","py":"Zhè běn shū hěn yǒu yìsi.","vi":"Cuốn sách này rất thú vị.","en":"This book is very interesting."},{"use":"小意思 = chút lòng thành khi tặng quà.","ex":"一点儿小意思，请收下。","py":"Yìdiǎnr xiǎo yìsi, qǐng shōuxià.","vi":"Chỉ là chút lòng thành, xin nhận cho.","en":"It's just a small token; please accept it."},{"use":"不好意思 = xin lỗi, ngại quá (lời xin lỗi nhẹ).","ex":"不好意思，我来晚了。","py":"Bù hǎoyìsi, wǒ lái wǎn le.","vi":"Ngại quá, tôi đến muộn rồi.","en":"Sorry, I'm late."}]},"关系":{"en":"relationship; relation; connection","exs":[{"use":"A 和 B 的关系 + adj: mối quan hệ giữa hai bên.","ex":"他和同事的关系很好。","py":"Tā hé tóngshì de guānxi hěn hǎo.","vi":"Quan hệ giữa anh ấy và đồng nghiệp rất tốt.","en":"He has a good relationship with his colleagues."},{"use":"没关系 = không sao đâu (đáp lời xin lỗi).","ex":"没关系，下次再来吧。","py":"Méi guānxi, xià cì zài lái ba.","vi":"Không sao, lần sau lại đến nhé.","en":"It doesn't matter; come again next time."},{"use":"A 和 B 有关系 = A có liên quan đến B.","ex":"吃饭太快和胃疼有关系。","py":"Chī fàn tài kuài hé wèi téng yǒu guānxi.","vi":"Ăn quá nhanh có liên quan đến việc đau dạ dày.","en":"Eating too fast is related to stomachaches."},{"use":"Nghĩa 'quan hệ quen biết': 朋友的关系.","ex":"通过朋友的关系，他找到了这份工作。","py":"Tōngguò péngyou de guānxi, tā zhǎodào le zhè fèn gōngzuò.","vi":"Nhờ quan hệ của bạn bè, anh ấy tìm được công việc này.","en":"Through a friend's connections, he found this job."}]},"情况":{"en":"situation; circumstances; condition","exs":[{"use":"说一下……的情况: hỏi / kể về tình hình.","ex":"请你说一下那里的情况。","py":"Qǐng nǐ shuō yíxià nàlǐ de qíngkuàng.","vi":"Xin bạn kể qua tình hình ở đó.","en":"Please tell me about the situation there."},{"use":"身体情况 = tình trạng sức khỏe.","ex":"他的身体情况越来越好。","py":"Tā de shēntǐ qíngkuàng yuè lái yuè hǎo.","vi":"Tình trạng sức khỏe của anh ấy ngày càng tốt.","en":"His physical condition is getting better and better."},{"use":"在这种情况下 = trong tình huống này.","ex":"在这种情况下，我们只能等。","py":"Zài zhè zhǒng qíngkuàng xià, wǒmen zhǐ néng děng.","vi":"Trong tình huống này, chúng ta chỉ có thể đợi.","en":"Under these circumstances, we can only wait."},{"use":"学习情况 = tình hình học tập; 了解 + 情况.","ex":"老师了解每个学生的学习情况。","py":"Lǎoshī liǎojiě měi ge xuésheng de xuéxí qíngkuàng.","vi":"Thầy giáo nắm rõ tình hình học tập của từng học sinh.","en":"The teacher understands each student's study situation."}]},"春天":{"en":"spring (season)","exs":[{"use":"春天到了 = mùa xuân đến rồi.","ex":"春天到了，花都开了。","py":"Chūntiān dào le, huā dōu kāi le.","vi":"Mùa xuân đến rồi, hoa đều nở.","en":"Spring has come and the flowers are all in bloom."},{"use":"地方 + 的春天: mùa xuân của một nơi.","ex":"北京的春天常常刮风。","py":"Běijīng de chūntiān chángcháng guāfēng.","vi":"Mùa xuân ở Bắc Kinh thường có gió.","en":"It is often windy in Beijing in spring."},{"use":"在春天 + V: vào mùa xuân làm gì.","ex":"我最喜欢在春天去公园散步。","py":"Wǒ zuì xǐhuan zài chūntiān qù gōngyuán sànbù.","vi":"Tôi thích nhất là đi dạo công viên vào mùa xuân.","en":"I like taking walks in the park in spring the most."}]},"冬天":{"en":"winter","exs":[{"use":"地方 + 的冬天 + 特别冷.","ex":"哈尔滨的冬天特别冷。","py":"Hā'ěrbīn de dōngtiān tèbié lěng.","vi":"Mùa đông ở Cáp Nhĩ Tân đặc biệt lạnh.","en":"Winter in Harbin is especially cold."},{"use":"冬天 làm trạng ngữ thời gian đứng đầu câu.","ex":"冬天我喜欢喝热茶。","py":"Dōngtiān wǒ xǐhuan hē rè chá.","vi":"Mùa đông tôi thích uống trà nóng.","en":"In winter I like drinking hot tea."},{"use":"去年冬天 = mùa đông năm ngoái.","ex":"去年冬天我们去南方旅游了。","py":"Qùnián dōngtiān wǒmen qù nánfāng lǚyóu le.","vi":"Mùa đông năm ngoái chúng tôi đi du lịch miền Nam.","en":"Last winter we traveled to the south."}]},"昨天":{"en":"yesterday","exs":[{"use":"昨天 làm trạng ngữ thời gian, đặt trước động từ.","ex":"昨天我和朋友去看了电影。","py":"Zuótiān wǒ hé péngyou qù kàn le diànyǐng.","vi":"Hôm qua tôi cùng bạn đi xem phim.","en":"Yesterday I went to see a movie with a friend."},{"use":"昨天晚上 = tối hôm qua.","ex":"昨天晚上下了一场大雨。","py":"Zuótiān wǎnshang xià le yì chǎng dàyǔ.","vi":"Tối hôm qua có một trận mưa lớn.","en":"There was a heavy rain last night."},{"use":"昨天 + V + 的 + danh từ: định ngữ chỉ thời gian.","ex":"这是昨天买的衣服。","py":"Zhè shì zuótiān mǎi de yīfu.","vi":"Đây là quần áo mua hôm qua.","en":"These are the clothes I bought yesterday."}]},"打电话":{"en":"to make a phone call","exs":[{"use":"给 + người + 打电话 = gọi điện cho ai.","ex":"我晚上给妈妈打电话。","py":"Wǒ wǎnshang gěi māma dǎ diànhuà.","vi":"Buổi tối tôi gọi điện cho mẹ.","en":"I call my mom in the evening."},{"use":"正在打电话 = đang gọi điện (tiến hành).","ex":"他正在打电话，请你等一下。","py":"Tā zhèngzài dǎ diànhuà, qǐng nǐ děng yíxià.","vi":"Anh ấy đang gọi điện, xin bạn đợi một chút.","en":"He's on the phone; please wait a moment."},{"use":"打电话给 + người: gọi cho ai (kết cấu khác).","ex":"你有事就打电话给我。","py":"Nǐ yǒu shì jiù dǎ diànhuà gěi wǒ.","vi":"Có việc gì thì cứ gọi điện cho tôi.","en":"If you need anything, just call me."},{"use":"不要 + 打电话: lời cấm / nhắc nhở.","ex":"在路上不要打电话，太危险。","py":"Zài lù shàng bú yào dǎ diànhuà, tài wēixiǎn.","vi":"Đừng gọi điện thoại trên đường, rất nguy hiểm.","en":"Don't make phone calls while walking on the road; it's too dangerous."}]},"超市":{"en":"supermarket","exs":[{"use":"去超市 + V: đi siêu thị làm gì.","ex":"我下班后要去超市买菜。","py":"Wǒ xiàbān hòu yào qù chāoshì mǎi cài.","vi":"Sau khi tan làm tôi sẽ đến siêu thị mua rau.","en":"After work I'm going to the supermarket to buy groceries."},{"use":"这家超市: lượng từ 家 cho siêu thị.","ex":"这家超市的东西又新鲜又便宜。","py":"Zhè jiā chāoshì de dōngxi yòu xīnxiān yòu piányi.","vi":"Đồ ở siêu thị này vừa tươi vừa rẻ.","en":"The goods in this supermarket are both fresh and cheap."},{"use":"超市 + 离 + nơi: nói về khoảng cách.","ex":"超市离我家很近，走路五分钟就到。","py":"Chāoshì lí wǒ jiā hěn jìn, zǒulù wǔ fēnzhōng jiù dào.","vi":"Siêu thị rất gần nhà tôi, đi bộ năm phút là tới.","en":"The supermarket is very close to my home; it's a five-minute walk."}]},"果汁":{"en":"fruit juice","exs":[{"use":"一杯 + 水果 + 果汁: lượng từ 杯.","ex":"我想喝一杯西瓜果汁。","py":"Wǒ xiǎng hē yì bēi xīguā guǒzhī.","vi":"Tôi muốn uống một ly nước ép dưa hấu.","en":"I'd like a glass of watermelon juice."},{"use":"瓶 + 果汁; 没有加糖 = không thêm đường.","ex":"这瓶果汁里没有加糖。","py":"Zhè píng guǒzhī lǐ méiyǒu jiā táng.","vi":"Chai nước ép này không thêm đường.","en":"There is no sugar added to this bottle of juice."},{"use":"Dùng khi gọi đồ ở nhà hàng: 请给我 + 果汁.","ex":"服务员，请给我一杯果汁。","py":"Fúwùyuán, qǐng gěi wǒ yì bēi guǒzhī.","vi":"Phục vụ ơi, cho tôi một ly nước ép trái cây.","en":"Waiter, a glass of juice for me, please."}]},"长时间":{"en":"a long time; for a long period","exs":[{"use":"长时间 + V: làm gì trong thời gian dài.","ex":"长时间看手机对眼睛不好。","py":"Cháng shíjiān kàn shǒujī duì yǎnjing bù hǎo.","vi":"Nhìn điện thoại thời gian dài có hại cho mắt.","en":"Looking at your phone for a long time is bad for your eyes."},{"use":"长时间 + 没有 + V: lâu rồi chưa…","ex":"他长时间没有回家了。","py":"Tā cháng shíjiān méiyǒu huíjiā le.","vi":"Anh ấy đã lâu không về nhà rồi.","en":"He hasn't been home for a long time."},{"use":"长时间地 + V: làm trạng ngữ với 地.","ex":"我们长时间地等着，可是车还没来。","py":"Wǒmen cháng shíjiān de děngzhe, kěshì chē hái méi lái.","vi":"Chúng tôi đợi rất lâu mà xe vẫn chưa đến.","en":"We waited for a long time, but the bus still hasn't come."},{"use":"长时间 + V + 以后, + hành động tiếp theo.","ex":"长时间工作以后，要休息一下。","py":"Cháng shíjiān gōngzuò yǐhòu, yào xiūxi yíxià.","vi":"Sau khi làm việc lâu, cần nghỉ ngơi một chút.","en":"After working for a long time, you should take a break."}]},"进门":{"en":"to enter (a door); to come in","exs":[{"use":"一进门，就…: vừa vào cửa là…","ex":"一进门，他就闻到了饭菜的香味。","py":"Yí jìnmén, tā jiù wén dào le fàncài de xiāngwèi.","vi":"Vừa vào cửa, anh ấy đã ngửi thấy mùi thơm của đồ ăn.","en":"As soon as he came in, he smelled the delicious food."},{"use":"进门前 / 进门后: trạng ngữ thời gian.","ex":"进门前请先换鞋。","py":"Jìnmén qián qǐng xiān huàn xié.","vi":"Trước khi vào cửa xin hãy thay giày trước.","en":"Please change your shoes before coming in."},{"use":"进门的时候, nhắc nhở làm gì đó.","ex":"你进门的时候，记得关灯。","py":"Nǐ jìnmén de shíhou, jìde guān dēng.","vi":"Khi bạn vào cửa, nhớ tắt đèn.","en":"When you come in, remember to turn off the light."}]},"热情":{"en":"enthusiastic; warm; warm-heartedness; enthusiasm","exs":[{"use":"热情地 + động từ / 很热情.","ex":"他对人很热情。","py":"Tā duì rén hěn rèqíng.","vi":"Anh ấy rất nhiệt tình với mọi người.","en":"He is very warm toward people."},{"use":"热情地 + V: làm gì một cách nhiệt tình.","ex":"房东热情地请我们进屋喝茶。","py":"Fángdōng rèqíng de qǐng wǒmen jìn wū hē chá.","vi":"Chủ nhà nhiệt tình mời chúng tôi vào nhà uống trà.","en":"The landlord warmly invited us in for tea."},{"use":"非常热情: tính từ làm vị ngữ.","ex":"这里的人们都非常热情。","py":"Zhèlǐ de rénmen dōu fēicháng rèqíng.","vi":"Người dân ở đây đều vô cùng nhiệt tình.","en":"The people here are all extremely friendly."},{"use":"Danh từ: 对……有热情 = có nhiệt huyết với…","ex":"他对工作很有热情。","py":"Tā duì gōngzuò hěn yǒu rèqíng.","vi":"Anh ấy rất có nhiệt huyết với công việc.","en":"He is very enthusiastic about his work."}]},"裤子":{"en":"trousers; pants","exs":[{"use":"一条裤子: lượng từ 条.","ex":"我想买一条黑色的裤子。","py":"Wǒ xiǎng mǎi yì tiáo hēisè de kùzi.","vi":"Tôi muốn mua một chiếc quần màu đen.","en":"I want to buy a pair of black trousers."},{"use":"太 + adj + 了: nhận xét kích cỡ quần.","ex":"这条裤子太长了，我想改短一点儿。","py":"Zhè tiáo kùzi tài cháng le, wǒ xiǎng gǎi duǎn yìdiǎnr.","vi":"Chiếc quần này dài quá, tôi muốn sửa ngắn lại một chút.","en":"These trousers are too long; I'd like to have them shortened."},{"use":"穿 + 裤子: động từ mặc.","ex":"他穿着一条新裤子。","py":"Tā chuānzhe yì tiáo xīn kùzi.","vi":"Anh ấy đang mặc một chiếc quần mới.","en":"He is wearing a new pair of trousers."}]},"一件":{"en":"one piece (of clothing / matter)","exs":[{"use":"一件 + quần áo: lượng từ 件 cho áo.","ex":"我想买一件红色的外套。","py":"Wǒ xiǎng mǎi yí jiàn hóngsè de wàitào.","vi":"Tôi muốn mua một chiếc áo khoác màu đỏ.","en":"I want to buy a red coat."},{"use":"一件 + 事: lượng từ 件 cho sự việc.","ex":"今天发生了一件有意思的事。","py":"Jīntiān fāshēng le yí jiàn yǒu yìsi de shì.","vi":"Hôm nay đã xảy ra một chuyện thú vị.","en":"An interesting thing happened today."},{"use":"一件 + hành lý, đồ đạc.","ex":"我只有一件行李，不用托运。","py":"Wǒ zhǐ yǒu yí jiàn xíngli, bú yòng tuōyùn.","vi":"Tôi chỉ có một kiện hành lý, không cần ký gửi.","en":"I only have one piece of luggage, so I don't need to check it in."}]},"衬衫":{"en":"shirt","exs":[{"use":"穿 + 白衬衫: mặc áo sơ mi trắng.","ex":"他每天上班都穿白衬衫。","py":"Tā měitiān shàngbān dōu chuān bái chènshān.","vi":"Ngày nào đi làm anh ấy cũng mặc áo sơ mi trắng.","en":"He wears a white shirt to work every day."},{"use":"这件衬衫: lượng từ 件.","ex":"这件衬衫洗了很多次，还是很新。","py":"Zhè jiàn chènshān xǐ le hěn duō cì, háishi hěn xīn.","vi":"Chiếc áo sơ mi này giặt nhiều lần mà vẫn còn mới.","en":"This shirt has been washed many times and still looks new."},{"use":"给 + người + 买 + 衬衫.","ex":"我想给爸爸买一件蓝衬衫。","py":"Wǒ xiǎng gěi bàba mǎi yí jiàn lán chènshān.","vi":"Tôi muốn mua cho bố một chiếc áo sơ mi xanh.","en":"I want to buy my dad a blue shirt."}]},"袜子":{"en":"socks; stockings","exs":[{"use":"穿 + 袜子; 厚袜子 = tất dày.","ex":"冬天要穿厚袜子。","py":"Dōngtiān yào chuān hòu wàzi.","vi":"Mùa đông phải đi tất dày.","en":"In winter you need to wear thick socks."},{"use":"一只袜子 (lượng từ 只) = một chiếc tất.","ex":"我的袜子不见了一只。","py":"Wǒ de wàzi bújiàn le yì zhī.","vi":"Tất của tôi mất một chiếc.","en":"One of my socks is missing."},{"use":"五双袜子 (lượng từ 双) = năm đôi tất.","ex":"他买了五双新袜子。","py":"Tā mǎi le wǔ shuāng xīn wàzi.","vi":"Anh ấy đã mua năm đôi tất mới.","en":"He bought five new pairs of socks."}]},"然后":{"en":"then; after that; afterwards","exs":[{"use":"先……，然后……: trình tự hai hành động.","ex":"我们先吃饭，然后去看电影。","py":"Wǒmen xiān chīfàn, ránhòu qù kàn diànyǐng.","vi":"Chúng ta ăn cơm trước, sau đó đi xem phim.","en":"Let's eat first, and then go see a movie."},{"use":"Chỉ đường: 先……，然后……，就到了.","ex":"先向左拐，然后一直走，就到了。","py":"Xiān xiàng zuǒ guǎi, ránhòu yìzhí zǒu, jiù dào le.","vi":"Rẽ trái trước, sau đó đi thẳng là tới.","en":"Turn left first, then keep walking straight and you'll be there."},{"use":"……，然后才……: làm xong việc này mới làm việc kia.","ex":"他写完作业，然后才出去玩。","py":"Tā xiě wán zuòyè, ránhòu cái chūqù wán.","vi":"Anh ấy làm xong bài tập rồi mới đi chơi.","en":"He finishes his homework, and only then goes out to play."},{"use":"然后呢？ = rồi sao nữa? (hỏi tiếp diễn biến).","ex":"然后呢？你后来怎么做的？","py":"Ránhòu ne? Nǐ hòulái zěnme zuò de?","vi":"Rồi sao nữa? Sau đó bạn làm thế nào?","en":"And then? What did you do afterwards?"}]},"高高兴兴":{"en":"happy; joyful; in high spirits","exs":[{"use":"高高兴兴地 + V: làm gì một cách vui vẻ.","ex":"孩子们高高兴兴地去公园玩。","py":"Háizimen gāogāoxìngxìng de qù gōngyuán wán.","vi":"Bọn trẻ vui vẻ hớn hở đi chơi công viên.","en":"The children happily went to play in the park."},{"use":"高高兴兴地 + 收下 / 接受: vui vẻ nhận.","ex":"她高高兴兴地收下了礼物。","py":"Tā gāogāoxìngxìng de shōuxià le lǐwù.","vi":"Cô ấy vui vẻ nhận món quà.","en":"She happily accepted the gift."},{"use":"高高兴兴 + V (không có 地), dùng trong lời rủ rê.","ex":"我们高高兴兴过春节吧。","py":"Wǒmen gāogāoxìngxìng guò Chūnjié ba.","vi":"Chúng ta hãy vui vẻ đón Tết nhé.","en":"Let's have a joyful Spring Festival."}]},"回家":{"en":"to go home; to return home","exs":[{"use":"回家 là động từ ly hợp, không thêm tân ngữ.","ex":"我每天六点回家。","py":"Wǒ měitiān liù diǎn huíjiā.","vi":"Mỗi ngày tôi về nhà lúc sáu giờ.","en":"I go home at six every day."},{"use":"早点儿回家: lời dặn dò.","ex":"路上小心，早点儿回家。","py":"Lùshang xiǎoxīn, zǎodiǎnr huíjiā.","vi":"Đi đường cẩn thận, về nhà sớm nhé.","en":"Be careful on the way and come home early."},{"use":"回家以后, + hành động tiếp theo.","ex":"回家以后，我先洗手再吃饭。","py":"Huíjiā yǐhòu, wǒ xiān xǐ shǒu zài chīfàn.","vi":"Về nhà rồi, tôi rửa tay trước rồi mới ăn cơm.","en":"After I get home, I wash my hands before eating."},{"use":"要 + 回家 + 和…: mục đích về nhà.","ex":"过年的时候，很多人都要回家和家人团圆。","py":"Guònián de shíhou, hěn duō rén dōu yào huíjiā hé jiārén tuányuán.","vi":"Dịp Tết, nhiều người đều về nhà sum họp với gia đình.","en":"At New Year, many people go home to reunite with their families."}]},"打扰":{"en":"to disturb; to bother; to interrupt","exs":[{"use":"打扰一下 = làm phiền một chút (mở lời lịch sự).","ex":"对不起，打扰一下，请问这里有人吗？","py":"Duìbuqǐ, dǎrǎo yíxià, qǐngwèn zhèlǐ yǒu rén ma?","vi":"Xin lỗi, làm phiền một chút, chỗ này có ai ngồi không ạ?","en":"Sorry to bother you, is this seat taken?"},{"use":"请不要打扰 + người: xin đừng làm phiền ai.","ex":"他在学习，请不要打扰他。","py":"Tā zài xuéxí, qǐng bú yào dǎrǎo tā.","vi":"Anh ấy đang học, xin đừng làm phiền anh ấy.","en":"He is studying; please don't disturb him."},{"use":"打扰 + người + V + 了: xin lỗi vì đã làm phiền.","ex":"不好意思，打扰你休息了。","py":"Bù hǎoyìsi, dǎrǎo nǐ xiūxi le.","vi":"Ngại quá, đã làm phiền bạn nghỉ ngơi.","en":"Sorry for disturbing your rest."}]},"竟然":{"en":"unexpectedly; actually; to one's surprise","exs":[{"use":"竟然 + V: diễn tả bất ngờ, ngoài dự liệu.","ex":"他竟然忘了自己的生日。","py":"Tā jìngrán wàng le zìjǐ de shēngrì.","vi":"Anh ấy lại quên cả sinh nhật của mình.","en":"He actually forgot his own birthday."},{"use":"Dùng sau mệnh đề nhượng bộ: 这么难……竟然.","ex":"这么难的题，他竟然做对了。","py":"Zhème nán de tí, tā jìngrán zuò duì le.","vi":"Câu khó như vậy mà anh ấy lại làm đúng.","en":"He actually got such a hard question right."},{"use":"没想到 + … 竟然 + 是…: bất ngờ về danh tính.","ex":"我没想到她竟然是我的邻居。","py":"Wǒ méi xiǎngdào tā jìngrán shì wǒ de línjū.","vi":"Tôi không ngờ cô ấy lại là hàng xóm của tôi.","en":"I never expected that she would turn out to be my neighbor."}]},"西红柿":{"en":"tomato","exs":[{"use":"西红柿炒鸡蛋 = món cà chua xào trứng.","ex":"我想吃西红柿炒鸡蛋。","py":"Wǒ xiǎng chī xīhóngshì chǎo jīdàn.","vi":"Tôi muốn ăn món cà chua xào trứng.","en":"I'd like to eat stir-fried tomatoes with eggs."},{"use":"又……又……: miêu tả tính chất của cà chua.","ex":"这些西红柿又大又红。","py":"Zhèxiē xīhóngshì yòu dà yòu hóng.","vi":"Những quả cà chua này vừa to vừa đỏ.","en":"These tomatoes are big and red."},{"use":"买两个西红柿: lượng từ 个.","ex":"请帮我买两个西红柿。","py":"Qǐng bāng wǒ mǎi liǎng ge xīhóngshì.","vi":"Làm ơn mua giúp tôi hai quả cà chua.","en":"Please buy two tomatoes for me."}]},"百分之百":{"en":"one hundred percent; completely","exs":[{"use":"百分之百 + V: chắc chắn, hoàn toàn (phó từ).","ex":"我百分之百相信你。","py":"Wǒ bǎifēnzhībǎi xiāngxìn nǐ.","vi":"Tôi tin bạn một trăm phần trăm.","en":"I trust you one hundred percent."},{"use":"不能百分之百 + V: không thể đảm bảo tuyệt đối.","ex":"这个办法不能百分之百成功。","py":"Zhège bànfǎ bù néng bǎifēnzhībǎi chénggōng.","vi":"Cách này không thể thành công một trăm phần trăm.","en":"This method can't be one hundred percent successful."},{"use":"百分之百的 + danh từ: nguyên chất / thuần.","ex":"这种果汁是百分之百的水果做的。","py":"Zhè zhǒng guǒzhī shì bǎifēnzhībǎi de shuǐguǒ zuò de.","vi":"Loại nước ép này làm hoàn toàn từ trái cây.","en":"This juice is made from 100% fruit."}]},"记得":{"en":"to remember; to recall","exs":[{"use":"记得 + người / vật: còn nhớ ai, cái gì.","ex":"你还记得我吗？","py":"Nǐ hái jìde wǒ ma?","vi":"Bạn còn nhớ tôi không?","en":"Do you still remember me?"},{"use":"记得 + V: nhớ phải làm gì (nhắc nhở).","ex":"明天要考试，你记得带身份证。","py":"Míngtiān yào kǎoshì, nǐ jìde dài shēnfènzhèng.","vi":"Ngày mai thi, bạn nhớ mang theo chứng minh thư.","en":"You have an exam tomorrow, so remember to bring your ID."},{"use":"我记得 + mệnh đề: tôi nhớ là…","ex":"我记得他是去年来的。","py":"Wǒ jìde tā shì qùnián lái de.","vi":"Tôi nhớ là anh ấy đến từ năm ngoái.","en":"I remember that he came last year."},{"use":"不记得 + mệnh đề / từ nghi vấn: không nhớ.","ex":"我不记得钥匙放在哪儿了。","py":"Wǒ bú jìde yàoshi fàng zài nǎr le.","vi":"Tôi không nhớ đã để chìa khóa ở đâu.","en":"I don't remember where I put the key."}]},"两倍":{"en":"twice as much; double; two times","exs":[{"use":"A 是 B 的两倍 + adj: gấp đôi.","ex":"这个房间是那个房间的两倍大。","py":"Zhège fángjiān shì nàge fángjiān de liǎng bèi dà.","vi":"Căn phòng này lớn gấp đôi căn phòng kia.","en":"This room is twice as big as that one."},{"use":"A 是 B 的两倍: so sánh số lượng.","ex":"今年的价格是去年的两倍。","py":"Jīnnián de jiàgé shì qùnián de liǎng bèi.","vi":"Giá năm nay gấp đôi năm ngoái.","en":"This year's price is double last year's."},{"use":"……的时间是……的两倍: so sánh thời gian.","ex":"他每天锻炼的时间是我的两倍。","py":"Tā měitiān duànliàn de shíjiān shì wǒ de liǎng bèi.","vi":"Thời gian tập luyện mỗi ngày của anh ấy gấp đôi tôi.","en":"He exercises twice as long as I do every day."}]},"绿色":{"en":"green; green (eco-friendly)","exs":[{"use":"Tên một màu sắc: 是 + 绿色 + 的.","ex":"草是绿色的。","py":"Cǎo shì lǜsè de.","vi":"Cỏ có màu xanh lá.","en":"Grass is green."},{"use":"绿色的 + danh từ: định ngữ chỉ màu.","ex":"我喜欢这件绿色的衣服。","py":"Wǒ xǐhuan zhè jiàn lǜsè de yīfu.","vi":"Tôi thích chiếc áo màu xanh lá này.","en":"I like this green piece of clothing."},{"use":"变成绿色 = trở thành màu xanh.","ex":"春天一到，山上都变成了绿色。","py":"Chūntiān yí dào, shān shàng dōu biànchéng le lǜsè.","vi":"Xuân vừa đến, trên núi đều chuyển sang màu xanh.","en":"As soon as spring arrives, the mountains turn green."},{"use":"Nghĩa 2: 绿色食品 / 绿色蔬菜 = thực phẩm sạch, thân thiện môi trường.","ex":"现在很多人愿意买绿色食品。","py":"Xiànzài hěn duō rén yuànyì mǎi lǜsè shípǐn.","vi":"Bây giờ nhiều người sẵn lòng mua thực phẩm xanh sạch.","en":"Nowadays many people are willing to buy green (organic) food."}]},"一分钱一分货":{"en":"you get what you pay for","exs":[{"use":"Thành ngữ: giá nào của nấy, thường dùng để giải thích vì sao hàng đắt.","ex":"俗话说“一分钱一分货”，太便宜的东西质量不一定好。","py":"Súhuà shuō “yì fēn qián yì fēn huò”, tài piányi de dōngxi zhìliàng bù yídìng hǎo.","vi":"Tục ngữ nói “tiền nào của nấy”, đồ quá rẻ chưa chắc chất lượng tốt.","en":"As the saying goes, “you get what you pay for”: things that are too cheap aren't necessarily good quality."},{"use":"……是……，不过一分钱一分货: biện hộ cho hàng giá cao.","ex":"这个包贵是贵，不过一分钱一分货，质量真的很好。","py":"Zhège bāo guì shì guì, búguò yì fēn qián yì fēn huò, zhìliàng zhēn de hěn hǎo.","vi":"Cái túi này đắt thì đắt thật, nhưng tiền nào của nấy, chất lượng rất tốt.","en":"This bag is expensive, but you get what you pay for; the quality is really good."},{"use":"Dùng để khuyên: mua đồ rẻ dễ hỏng.","ex":"你应该知道一分钱一分货，买便宜的容易坏。","py":"Nǐ yīnggāi zhīdào yì fēn qián yì fēn huò, mǎi piányi de róngyì huài.","vi":"Bạn nên biết tiền nào của nấy, mua đồ rẻ dễ hỏng.","en":"You should know you get what you pay for; cheap things break easily."}]},"皮肤":{"en":"skin","exs":[{"use":"皮肤 + 干 / 白 / 好: miêu tả làn da.","ex":"冬天空气干，我的皮肤很干。","py":"Dōngtiān kōngqì gān, wǒ de pífū hěn gān.","vi":"Mùa đông không khí khô, da của tôi rất khô.","en":"The air is dry in winter, so my skin is very dry."},{"use":"皮肤很白 = da trắng.","ex":"她的皮肤很白。","py":"Tā de pífū hěn bái.","vi":"Da của cô ấy rất trắng.","en":"Her skin is very fair."},{"use":"对皮肤很好 = tốt cho da.","ex":"这种水果对皮肤很好。","py":"Zhè zhǒng shuǐguǒ duì pífū hěn hǎo.","vi":"Loại trái cây này rất tốt cho da.","en":"This kind of fruit is very good for your skin."},{"use":"晒伤皮肤 = cháy nắng, tân ngữ của 晒伤.","ex":"太阳太大，会晒伤皮肤。","py":"Tàiyáng tài dà, huì shàishāng pífū.","vi":"Nắng gắt quá sẽ làm cháy da.","en":"The sun is too strong and will burn your skin."}]},"好处":{"en":"benefit; advantage; good","exs":[{"use":"对……有好处 = có lợi cho…","ex":"多喝水对身体有好处。","py":"Duō hē shuǐ duì shēntǐ yǒu hǎochu.","vi":"Uống nhiều nước có lợi cho cơ thể.","en":"Drinking more water is good for your body."},{"use":"有很多好处: nhiều lợi ích.","ex":"学外语有很多好处。","py":"Xué wàiyǔ yǒu hěn duō hǎochu.","vi":"Học ngoại ngữ có nhiều lợi ích.","en":"Learning a foreign language has many benefits."},{"use":"没有好处 = không có lợi.","ex":"这样做对你没有好处。","py":"Zhèyàng zuò duì nǐ méiyǒu hǎochu.","vi":"Làm như vậy không có lợi gì cho bạn.","en":"Doing this is of no benefit to you."},{"use":"得到好处: nhận được lợi lộc (nghĩa vật chất).","ex":"他帮你，是想得到好处。","py":"Tā bāng nǐ, shì xiǎng dédào hǎochu.","vi":"Anh ta giúp bạn là muốn nhận được lợi lộc.","en":"He's helping you because he wants something in return."}]},"尝尝":{"en":"to taste; to try (food)","exs":[{"use":"V 重叠: 尝尝 = nếm thử một chút.","ex":"这个菜很好吃，你尝尝。","py":"Zhège cài hěn hǎochī, nǐ chángchang.","vi":"Món này rất ngon, bạn nếm thử đi.","en":"This dish is delicious; try some."},{"use":"请尝尝 + món ăn: mời nếm thử.","ex":"请尝尝我做的饺子。","py":"Qǐng chángchang wǒ zuò de jiǎozi.","vi":"Mời bạn nếm thử bánh chẻ tôi làm.","en":"Please try the dumplings I made."},{"use":"想尝尝 + đặc sản: muốn thử.","ex":"我想尝尝你们这儿的特色菜。","py":"Wǒ xiǎng chángchang nǐmen zhèr de tèsècài.","vi":"Tôi muốn nếm thử món đặc sản của chỗ các bạn.","en":"I'd like to try your local specialty dishes."}]},"先生":{"en":"Mr.; sir; gentleman; husband; teacher (old usage)","exs":[{"use":"Xưng hô lịch sự với nam khách: 先生, ……","ex":"先生，请问您需要点儿什么？","py":"Xiānsheng, qǐngwèn nín xūyào diǎnr shénme?","vi":"Thưa ông, xin hỏi ông cần gì ạ?","en":"Sir, what can I get for you?"},{"use":"Họ + 先生 = ông + họ.","ex":"王先生今天不在公司。","py":"Wáng xiānsheng jīntiān bú zài gōngsī.","vi":"Ông Vương hôm nay không có ở công ty.","en":"Mr. Wang is not at the company today."},{"use":"女士们，先生们: lời chào khán giả.","ex":"女士们，先生们，欢迎大家。","py":"Nǚshìmen, xiānshengmen, huānyíng dàjiā.","vi":"Thưa quý bà quý ông, xin chào mừng mọi người.","en":"Ladies and gentlemen, welcome everyone."},{"use":"Nghĩa 'chồng': 我先生 = chồng tôi.","ex":"我先生在医院工作。","py":"Wǒ xiānsheng zài yīyuàn gōngzuò.","vi":"Chồng tôi làm việc ở bệnh viện.","en":"My husband works at a hospital."}]},"行李箱":{"en":"suitcase; luggage case","exs":[{"use":"太重了，拿不动 = nặng quá, không xách nổi.","ex":"我的行李箱太重了，拿不动。","py":"Wǒ de xínglǐxiāng tài zhòng le, ná bu dòng.","vi":"Va li của tôi nặng quá, tôi không xách nổi.","en":"My suitcase is too heavy; I can't carry it."},{"use":"买 + 一个新的行李箱: lượng từ 个.","ex":"他买了一个新的行李箱。","py":"Tā mǎi le yí ge xīn de xínglǐxiāng.","vi":"Anh ấy đã mua một chiếc va li mới.","en":"He bought a new suitcase."},{"use":"把 + 行李箱 + 放在 + nơi.","ex":"请把行李箱放在这儿。","py":"Qǐng bǎ xínglǐxiāng fàng zài zhèr.","vi":"Xin đặt va li ở đây.","en":"Please put the suitcase here."}]},"请问":{"en":"excuse me; may I ask","exs":[{"use":"请问，+ câu hỏi đường đi.","ex":"请问，去火车站怎么走？","py":"Qǐngwèn, qù huǒchēzhàn zěnme zǒu?","vi":"Xin hỏi, đến ga tàu đi thế nào?","en":"Excuse me, how do I get to the train station?"},{"use":"请问 + 你 + 叫什么名字: hỏi tên lịch sự.","ex":"请问你叫什么名字？","py":"Qǐngwèn nǐ jiào shénme míngzi?","vi":"Xin hỏi bạn tên là gì?","en":"May I ask what your name is?"},{"use":"请问，+ 可以……吗？: hỏi xin phép.","ex":"请问，这里可以拍照吗？","py":"Qǐngwèn, zhèlǐ kěyǐ pāizhào ma?","vi":"Xin hỏi, ở đây có thể chụp ảnh không?","en":"Excuse me, may I take photos here?"}]},"一点儿":{"en":"a little; a bit","exs":[{"use":"adj + 一点儿: hơn một chút (yêu cầu).","ex":"请说慢一点儿。","py":"Qǐng shuō màn yìdiǎnr.","vi":"Xin nói chậm một chút.","en":"Please speak a little more slowly."},{"use":"会说一点儿 + ngôn ngữ: biết chút ít.","ex":"我只会说一点儿汉语。","py":"Wǒ zhǐ huì shuō yìdiǎnr Hànyǔ.","vi":"Tôi chỉ biết nói một chút tiếng Trung.","en":"I can only speak a little Chinese."},{"use":"放 + 一点儿 + danh từ: cho thêm chút.","ex":"菜里再放一点儿盐吧。","py":"Cài lǐ zài fàng yìdiǎnr yán ba.","vi":"Cho thêm một chút muối vào món ăn đi.","en":"Add a little more salt to the dish."},{"use":"一点儿也不 + adj = hoàn toàn không…","ex":"我一点儿也不累。","py":"Wǒ yìdiǎnr yě bú lèi.","vi":"Tôi một chút cũng không mệt.","en":"I'm not tired at all."}]},"方面":{"en":"aspect; respect; side; field","exs":[{"use":"在……方面 = về mặt…","ex":"在学习方面，他一直很努力。","py":"Zài xuéxí fāngmiàn, tā yìzhí hěn nǔlì.","vi":"Về mặt học tập, anh ấy luôn rất chăm chỉ.","en":"In terms of studying, he has always worked hard."},{"use":"服务方面 = về mặt dịch vụ.","ex":"这家公司在服务方面做得很好。","py":"Zhè jiā gōngsī zài fúwù fāngmiàn zuò de hěn hǎo.","vi":"Công ty này làm rất tốt về mặt dịch vụ.","en":"This company does very well in terms of service."},{"use":"一方面……，一方面……: một mặt…, một mặt…","ex":"一方面想去旅游，一方面又没有时间。","py":"Yì fāngmiàn xiǎng qù lǚyóu, yì fāngmiàn yòu méiyǒu shíjiān.","vi":"Một mặt muốn đi du lịch, mặt khác lại không có thời gian.","en":"On the one hand I want to travel, but on the other hand I have no time."},{"use":"各个方面 = mọi mặt, các phương diện.","ex":"我们要从各个方面考虑这个问题。","py":"Wǒmen yào cóng gègè fāngmiàn kǎolǜ zhège wèntí.","vi":"Chúng ta phải xem xét vấn đề này từ mọi phương diện.","en":"We need to consider this issue from all angles."}]},"值得":{"en":"to be worth; to deserve","exs":[{"use":"值得 + V: đáng để làm gì.","ex":"这本书很好，值得一看。","py":"Zhè běn shū hěn hǎo, zhíde yí kàn.","vi":"Cuốn sách này rất hay, đáng đọc.","en":"This book is great; it's worth a read."},{"use":"值得 + người + V: đáng để chúng ta…","ex":"这件事值得我们认真考虑。","py":"Zhè jiàn shì zhíde wǒmen rènzhēn kǎolǜ.","vi":"Việc này đáng để chúng ta cân nhắc nghiêm túc.","en":"This matter deserves our serious consideration."},{"use":"是值得的 = là xứng đáng (làm vị ngữ).","ex":"为了健康，花这些钱是值得的。","py":"Wèile jiànkāng, huā zhèxiē qián shì zhíde de.","vi":"Vì sức khỏe, tiêu số tiền này là xứng đáng.","en":"For the sake of health, spending this money is worth it."},{"use":"很值得 + V: rất đáng để làm.","ex":"这个地方很值得去。","py":"Zhège dìfang hěn zhíde qù.","vi":"Nơi này rất đáng để đi.","en":"This place is well worth visiting."}]},"修理":{"en":"to repair; to fix","exs":[{"use":"拿去修理 = mang đi sửa.","ex":"我的手机坏了，要拿去修理。","py":"Wǒ de shǒujī huài le, yào ná qù xiūlǐ.","vi":"Điện thoại của tôi hỏng rồi, phải mang đi sửa.","en":"My phone is broken; I need to take it to be repaired."},{"use":"正在修理 + đồ vật: đang sửa.","ex":"师傅正在修理电视。","py":"Shīfu zhèngzài xiūlǐ diànshì.","vi":"Bác thợ đang sửa chiếc tivi.","en":"The repairman is fixing the TV."},{"use":"修理好了吗？ = sửa xong chưa? (bổ ngữ kết quả 好).","ex":"这辆自行车修理好了吗？","py":"Zhè liàng zìxíngchē xiūlǐ hǎo le ma?","vi":"Chiếc xe đạp này sửa xong chưa?","en":"Has this bike been fixed yet?"},{"use":"修理费 = phí sửa chữa (danh từ ghép).","ex":"修理费要两百块。","py":"Xiūlǐ fèi yào liǎng bǎi kuài.","vi":"Phí sửa chữa là hai trăm tệ.","en":"The repair fee is two hundred yuan."}]},"服务":{"en":"to serve; service","exs":[{"use":"Danh từ: 服务很好 = dịch vụ tốt.","ex":"这家酒店的服务很好。","py":"Zhè jiā jiǔdiàn de fúwù hěn hǎo.","vi":"Dịch vụ của khách sạn này rất tốt.","en":"The service at this hotel is very good."},{"use":"Động từ: 为…服务 = phục vụ cho…","ex":"我们愿意为大家服务。","py":"Wǒmen yuànyì wèi dàjiā fúwù.","vi":"Chúng tôi sẵn lòng phục vụ mọi người.","en":"We are happy to serve everyone."},{"use":"服务员 = nhân viên phục vụ.","ex":"服务员，请给我一杯水。","py":"Fúwùyuán, qǐng gěi wǒ yì bēi shuǐ.","vi":"Phục vụ ơi, cho tôi một ly nước.","en":"Waiter, a glass of water for me, please."},{"use":"提供 + ...服务 = cung cấp dịch vụ…","ex":"这家餐厅提供免费送货服务。","py":"Zhè jiā cāntīng tígōng miǎnfèi sòng huò fúwù.","vi":"Nhà hàng này cung cấp dịch vụ giao hàng miễn phí.","en":"This restaurant offers a free delivery service."}]},"健康":{"en":"health; healthy","exs":[{"use":"Có thể làm danh từ hoặc tính từ: 身体健康 (cơ thể khỏe mạnh).","ex":"健康比什么都重要。","py":"Jiànkāng bǐ shénme dōu zhòngyào.","vi":"Sức khỏe quan trọng hơn tất cả mọi thứ.","en":"Health is more important than anything else."},{"use":"Làm tính từ: 很健康 (rất khỏe mạnh), làm vị ngữ.","ex":"她的身体很健康，很少生病。","py":"Tā de shēntǐ hěn jiànkāng, hěn shǎo shēngbìng.","vi":"Cơ thể cô ấy rất khỏe mạnh, hiếm khi bị ốm.","en":"She is in good health and rarely gets sick."},{"use":"Làm danh từ: 对健康有好处 (có lợi cho sức khỏe).","ex":"多吃蔬菜对健康有好处。","py":"Duō chī shūcài duì jiànkāng yǒu hǎochù.","vi":"Ăn nhiều rau có lợi cho sức khỏe.","en":"Eating more vegetables is good for your health."},{"use":"健康的 + danh từ: bổ nghĩa cho danh từ.","ex":"健康的生活方式很重要。","py":"Jiànkāng de shēnghuó fāngshì hěn zhòngyào.","vi":"Lối sống lành mạnh rất quan trọng.","en":"A healthy lifestyle is very important."}]},"才":{"en":"only then; not until; just; only","exs":[{"use":"才 nhấn mạnh điều kiện cần để có kết quả: …才会…","ex":"努力学习才会进步。","py":"Nǔlì xuéxí cái huì jìnbù.","vi":"Chăm chỉ học thì mới tiến bộ.","en":"You will only make progress if you study hard."},{"use":"才 + thời gian: nhấn mạnh việc xảy ra muộn (mãi mới…).","ex":"他十点才起床。","py":"Tā shí diǎn cái qǐchuáng.","vi":"Mười giờ anh ấy mới dậy.","en":"He didn't get up until ten o'clock."},{"use":"才 = vừa mới, chỉ thời gian xảy ra chưa lâu.","ex":"我昨天才知道这件事。","py":"Wǒ zuótiān cái zhīdào zhè jiàn shì.","vi":"Hôm qua tôi mới biết chuyện này.","en":"I only found out about this yesterday."},{"use":"才 + số lượng: nhấn mạnh số lượng ít, giá rẻ (chỉ có).","ex":"这件衣服才五十块钱。","py":"Zhè jiàn yīfu cái wǔshí kuài qián.","vi":"Chiếc áo này chỉ có năm mươi tệ.","en":"This piece of clothing costs only fifty yuan."}]},"认为":{"en":"to think; to consider; to believe","exs":[{"use":"Thường dùng: 认为 + mệnh đề.","ex":"我认为这个办法很好。","py":"Wǒ rènwéi zhège bànfǎ hěn hǎo.","vi":"Tôi cho rằng cách này rất tốt.","en":"I think this method is very good."},{"use":"认为 + chủ ngữ + 是 + …: coi ai/cái gì là…","ex":"大家都认为他是个好老师。","py":"Dàjiā dōu rènwéi tā shì ge hǎo lǎoshī.","vi":"Mọi người đều cho rằng anh ấy là một thầy giáo tốt.","en":"Everyone thinks he is a good teacher."},{"use":"Dùng trong câu hỏi để hỏi ý kiến: 你认为…?","ex":"你认为我们应该怎么办？","py":"Nǐ rènwéi wǒmen yīnggāi zěnme bàn?","vi":"Bạn cho rằng chúng ta nên làm thế nào?","en":"What do you think we should do?"},{"use":"Dạng phủ định: 不认为 + mệnh đề (không cho rằng).","ex":"我不认为他会同意。","py":"Wǒ bú rènwéi tā huì tóngyì.","vi":"Tôi không cho rằng anh ấy sẽ đồng ý.","en":"I don't think he will agree."}]},"指":{"en":"to point at; to refer to; finger","exs":[{"use":"Thường dùng để giải thích một từ hoặc khái niệm: A 指 B.","ex":"这里的“他”指谁？","py":"Zhèlǐ de “tā” zhǐ shéi?","vi":"“Anh ấy” ở đây chỉ ai?","en":"Who does “he” refer to here?"},{"use":"Động từ: dùng ngón tay chỉ vào (指着 + nơi chốn).","ex":"他用手指着前面的路。","py":"Tā yòng shǒu zhǐzhe qiánmiàn de lù.","vi":"Anh ấy dùng tay chỉ con đường phía trước.","en":"He pointed at the road ahead with his hand."},{"use":"Làm danh từ trong 手指 (ngón tay).","ex":"小孩子的手指很小。","py":"Xiǎo háizi de shǒuzhǐ hěn xiǎo.","vi":"Ngón tay của trẻ con rất nhỏ.","en":"A small child's fingers are tiny."},{"use":"Nghĩa “chỉ số”: 指数 (chỉ số).","ex":"今天的空气质量指数很高。","py":"Jīntiān de kōngqì zhìliàng zhǐshù hěn gāo.","vi":"Chỉ số chất lượng không khí hôm nay rất cao.","en":"Today's air quality index is very high."}]},"认识到":{"en":"to realize; to recognize (that)","exs":[{"use":"认识到 + sự việc / ý nghĩa / vấn đề.","ex":"我终于认识到时间的重要性。","py":"Wǒ zhōngyú rènshi dào shíjiān de zhòngyàoxìng.","vi":"Cuối cùng tôi cũng nhận ra tầm quan trọng của thời gian.","en":"I finally realized how important time is."},{"use":"认识到 + 自己的错误: nhận ra lỗi của bản thân.","ex":"他认识到自己的错误，马上道歉了。","py":"Tā rènshi dào zìjǐ de cuòwu, mǎshàng dàoqiàn le.","vi":"Anh ấy nhận ra lỗi của mình nên lập tức xin lỗi.","en":"He realized his mistake and apologized right away."},{"use":"通过…认识到…: nhận ra điều gì qua một trải nghiệm.","ex":"通过这次生病，我认识到健康的重要。","py":"Tōngguò zhè cì shēngbìng, wǒ rènshi dào jiànkāng de zhòngyào.","vi":"Qua lần ốm này, tôi nhận ra sức khỏe quan trọng thế nào.","en":"Through this illness, I realized how important health is."},{"use":"要/应该 + 认识到: cần phải nhận thức được.","ex":"我们要认识到问题的严重性。","py":"Wǒmen yào rènshi dào wèntí de yánzhòngxìng.","vi":"Chúng ta cần nhận thức được mức độ nghiêm trọng của vấn đề.","en":"We need to recognize how serious the problem is."}]},"精神":{"en":"spirit; mind; energy; vigorous","exs":[{"use":"Trong bài, 精神 chỉ trạng thái tinh thần / sức sống: 精神很好.","ex":"她今天精神很好。","py":"Tā jīntiān jīngshén hěn hǎo.","vi":"Hôm nay tinh thần cô ấy rất tốt.","en":"She is in very good spirits today."},{"use":"没精神: không có tinh thần, uể oải.","ex":"他昨晚没睡好，今天没精神。","py":"Tā zuówǎn méi shuìhǎo, jīntiān méi jīngshén.","vi":"Tối qua anh ấy ngủ không ngon, hôm nay uể oải.","en":"He didn't sleep well last night and has no energy today."},{"use":"Tính từ: 有精神 / 很精神 (tràn đầy sức sống).","ex":"老人看起来很有精神。","py":"Lǎorén kàn qǐlái hěn yǒu jīngshén.","vi":"Ông cụ trông rất có tinh thần.","en":"The old man looks full of energy."},{"use":"Danh từ trừu tượng: tinh thần (thái độ, phẩm chất): …的精神.","ex":"我们要学习他认真工作的精神。","py":"Wǒmen yào xuéxí tā rènzhēn gōngzuò de jīngshén.","vi":"Chúng ta cần học tập tinh thần làm việc nghiêm túc của anh ấy.","en":"We should learn from his spirit of working conscientiously."}]},"精神上":{"en":"mentally; in spirit; on the mental level","exs":[{"use":"Thường dùng sau một danh từ để nói về một phương diện nào đó.","ex":"他精神上压力很大。","py":"Tā jīngshén shàng yālì hěn dà.","vi":"Về mặt tinh thần, anh ấy chịu áp lực rất lớn.","en":"He is under great mental pressure."},{"use":"在…精神上…: về mặt tinh thần, thường đối lập với 身体上 (về thể chất).","ex":"孩子在精神上也需要家人的支持。","py":"Háizi zài jīngshén shàng yě xūyào jiārén de zhīchí.","vi":"Về mặt tinh thần, trẻ con cũng cần sự ủng hộ của người nhà.","en":"Children also need their family's support mentally."},{"use":"对…精神上有帮助: có ích cho tinh thần.","ex":"运动不但对身体好，对精神上也有帮助。","py":"Yùndòng búdàn duì shēntǐ hǎo, duì jīngshén shàng yě yǒu bāngzhù.","vi":"Vận động không chỉ tốt cho cơ thể mà còn giúp ích về mặt tinh thần.","en":"Exercise is good not only for the body but also for the mind."},{"use":"精神上的 + danh từ: dùng làm định ngữ.","ex":"我们不只要照顾身体，也要关心精神上的健康。","py":"Wǒmen bù zhǐ yào zhàogù shēntǐ, yě yào guānxīn jīngshén shàng de jiànkāng.","vi":"Chúng ta không chỉ chăm sóc cơ thể mà còn cần quan tâm sức khỏe tinh thần.","en":"We should look after not only our bodies but also our mental health."}]},"只有…才…":{"en":"only if…, then…; only when… can…","exs":[{"use":"Nhấn mạnh điều kiện cần thiết để kết quả phía sau xảy ra.","ex":"只有认真练习，才会说好中文。","py":"Zhǐyǒu rènzhēn liànxí, cái huì shuōhǎo Zhōngwén.","vi":"Chỉ có luyện tập nghiêm túc thì mới nói tốt tiếng Trung.","en":"Only by practicing seriously can you speak Chinese well."},{"use":"只有 + điều kiện，才能 + kết quả.","ex":"只有多听多说，才能学好汉语。","py":"Zhǐyǒu duō tīng duō shuō, cái néng xuéhǎo Hànyǔ.","vi":"Chỉ có nghe nhiều nói nhiều mới học giỏi tiếng Hán.","en":"Only by listening and speaking a lot can you learn Chinese well."},{"use":"Điều kiện là một người cụ thể: 只有你…，他才会…","ex":"只有你亲自去，他才会相信。","py":"Zhǐyǒu nǐ qīnzì qù, tā cái huì xiāngxìn.","vi":"Chỉ có bạn đích thân đi thì anh ấy mới tin.","en":"He will only believe it if you go in person."},{"use":"Liên hệ sức khỏe: 只有 + tính từ，才能 + động từ.","ex":"只有身体健康，才能好好工作。","py":"Zhǐyǒu shēntǐ jiànkāng, cái néng hǎohāo gōngzuò.","vi":"Chỉ khi cơ thể khỏe mạnh mới làm việc tốt được.","en":"Only when you are healthy can you work well."},{"use":"Nói về cấu trúc: viết đầy đủ là 只有…才….","ex":"我们今天学习“只有…才…”这个句型。","py":"Wǒmen jīntiān xuéxí “zhǐyǒu…cái…” zhège jùxíng.","vi":"Hôm nay chúng ta học mẫu câu “只有…才…”.","en":"Today we are learning the sentence pattern “只有…才…”."}]},"算":{"en":"to count as; to calculate; to regard as","exs":[{"use":"Thường dùng: 算 + danh từ / 算是 + danh từ (tính là, được coi là).","ex":"这样算不算迟到？","py":"Zhèyàng suàn bu suàn chídào?","vi":"Như vậy có được tính là đi muộn không?","en":"Does this count as being late?"},{"use":"算是 + danh từ: coi như là, có thể xem là.","ex":"他算是我的老师。","py":"Tā suànshì wǒ de lǎoshī.","vi":"Anh ấy coi như là thầy của tôi.","en":"He can be considered my teacher."},{"use":"Nghĩa 2: tính toán, tính tiền.","ex":"你算一下，一共多少钱？","py":"Nǐ suàn yíxià, yígòng duōshao qián?","vi":"Bạn tính thử xem, tổng cộng bao nhiêu tiền?","en":"Please calculate how much it comes to in total."},{"use":"不算 + tính từ: không thể coi là…, không đến mức…","ex":"今天不算太冷。","py":"Jīntiān bú suàn tài lěng.","vi":"Hôm nay không tính là quá lạnh.","en":"It's not too cold today."},{"use":"算数: có hiệu lực, giữ lời.","ex":"说话要算数，不能骗人。","py":"Shuōhuà yào suànshù, bù néng piàn rén.","vi":"Đã nói thì phải giữ lời, không được lừa người.","en":"You must keep your word and not deceive people."}]},"教授":{"en":"professor","exs":[{"use":"Cách gọi chức danh học thuật: 王教授.","ex":"王教授正在给学生上课。","py":"Wáng jiàoshòu zhèngzài gěi xuésheng shàngkè.","vi":"Giáo sư Vương đang dạy học sinh.","en":"Professor Wang is teaching the students."},{"use":"Làm danh từ: …大学的教授 (giáo sư của trường đại học…).","ex":"他是北京大学的教授。","py":"Tā shì Běijīng Dàxué de jiàoshòu.","vi":"Ông ấy là giáo sư của Đại học Bắc Kinh.","en":"He is a professor at Peking University."},{"use":"教授 + 的 + danh từ: thuộc về giáo sư.","ex":"教授的课很受学生欢迎。","py":"Jiàoshòu de kè hěn shòu xuésheng huānyíng.","vi":"Bài giảng của giáo sư rất được sinh viên yêu thích.","en":"The professor's classes are very popular with students."},{"use":"请 + 教授 + động từ: nhờ giáo sư làm gì.","ex":"我想请教授帮我看看这篇文章。","py":"Wǒ xiǎng qǐng jiàoshòu bāng wǒ kànkan zhè piān wénzhāng.","vi":"Tôi muốn nhờ giáo sư xem giúp bài viết này.","en":"I'd like to ask the professor to look over this article for me."}]},"数字":{"en":"number; figure; digit","exs":[{"use":"Dùng cho số liệu, chữ số hoặc số lượng thể hiện bằng số.","ex":"这个数字不太准确。","py":"Zhège shùzì bú tài zhǔnquè.","vi":"Con số này không được chính xác lắm.","en":"This figure is not very accurate."},{"use":"Nghĩa chữ số: 阿拉伯数字 (chữ số Ả Rập).","ex":"阿拉伯数字很容易写。","py":"Ālābó shùzì hěn róngyì xiě.","vi":"Chữ số Ả Rập rất dễ viết.","en":"Arabic numerals are easy to write."},{"use":"数字 chỉ các con số trong dãy số, như số điện thoại.","ex":"请把电话号码的数字写清楚。","py":"Qǐng bǎ diànhuà hàomǎ de shùzì xiě qīngchu.","vi":"Hãy viết rõ các chữ số của số điện thoại.","en":"Please write the digits of the phone number clearly."},{"use":"Nghĩa số liệu thống kê: 数字 + 显示/说明…","ex":"最新的数字显示，游客越来越多。","py":"Zuìxīn de shùzì xiǎnshì, yóukè yuè lái yuè duō.","vi":"Số liệu mới nhất cho thấy du khách ngày càng nhiều.","en":"The latest figures show more and more tourists."}]},"说明":{"en":"to explain; to show; instructions; explanation","exs":[{"use":"说明 + sự việc / nguyên nhân / ý nghĩa (động từ: chứng tỏ, cho thấy).","ex":"这个例子说明了问题。","py":"Zhège lìzi shuōmíngle wèntí.","vi":"Ví dụ này đã cho thấy vấn đề.","en":"This example illustrates the problem."},{"use":"Động từ: giải thích cho ai điều gì (向…说明…).","ex":"他向大家说明了迟到的原因。","py":"Tā xiàng dàjiā shuōmíngle chídào de yuányīn.","vi":"Anh ấy giải thích cho mọi người lý do đến muộn.","en":"He explained to everyone why he was late."},{"use":"Danh từ: 说明书 (sách hướng dẫn sử dụng).","ex":"请先看一下产品说明书。","py":"Qǐng xiān kàn yíxià chǎnpǐn shuōmíngshū.","vi":"Xin hãy xem hướng dẫn sử dụng sản phẩm trước.","en":"Please read the product instructions first."}]},"要是":{"en":"if; in case","exs":[{"use":"Dùng để giả định điều kiện, gần nghĩa với 如果.","ex":"要是明天下雨，我们就不去了。","py":"Yàoshi míngtiān xiàyǔ, wǒmen jiù bú qù le.","vi":"Nếu ngày mai mưa, chúng tôi sẽ không đi.","en":"If it rains tomorrow, we won't go."},{"use":"要是…就…: nếu… thì…, thường dùng trong khẩu ngữ.","ex":"要是你有时间，就来我家玩吧。","py":"Yàoshi nǐ yǒu shíjiān, jiù lái wǒ jiā wán ba.","vi":"Nếu bạn có thời gian thì đến nhà tôi chơi nhé.","en":"If you have time, come over to my place."},{"use":"要是我是你: giả thiết trái với thực tế.","ex":"要是我是你，我就不会这么做。","py":"Yàoshi wǒ shì nǐ, wǒ jiù bú huì zhème zuò.","vi":"Nếu tôi là bạn thì tôi sẽ không làm thế.","en":"If I were you, I wouldn't do that."},{"use":"要是 + sự việc + 了: nếu đã xảy ra việc gì thì nên…","ex":"要是感冒了，就多喝点热水。","py":"Yàoshi gǎnmào le, jiù duō hē diǎn rè shuǐ.","vi":"Nếu bị cảm thì hãy uống nhiều nước nóng.","en":"If you catch a cold, drink more hot water."}]},"其他":{"en":"other; else; the rest","exs":[{"use":"Thường đứng trước danh từ: 其他人, 其他事情.","ex":"其他问题以后再说。","py":"Qítā wèntí yǐhòu zài shuō.","vi":"Những vấn đề khác để sau nói tiếp.","en":"We'll talk about the other issues later."},{"use":"除了…，其他…都…: ngoài… ra, những cái khác đều…","ex":"除了苹果，其他水果我都喜欢。","py":"Chúle píngguǒ, qítā shuǐguǒ wǒ dōu xǐhuan.","vi":"Ngoài táo ra, các loại trái cây khác tôi đều thích.","en":"Apart from apples, I like all other fruits."},{"use":"其他 + 的 + danh từ / 还有其他…吗: hỏi còn gì khác không.","ex":"你还有其他事吗？","py":"Nǐ hái yǒu qítā shì ma?","vi":"Bạn còn việc gì khác không?","en":"Do you have anything else?"},{"use":"其他人: những người khác.","ex":"他走了，其他人也都回家了。","py":"Tā zǒu le, qítā rén yě dōu huíjiā le.","vi":"Anh ấy đi rồi, những người khác cũng đều về nhà.","en":"He left, and everyone else went home too."}]},"后面":{"en":"behind; back; the rest (of a text)","exs":[{"use":"Có thể chỉ vị trí hoặc phần nội dung ở sau.","ex":"答案在书的后面。","py":"Dá'àn zài shū de hòumian.","vi":"Đáp án ở phía sau quyển sách.","en":"The answers are at the back of the book."},{"use":"Danh từ phương vị: 地点 + 后面 (phía sau nơi nào đó).","ex":"我家后面有一个小公园。","py":"Wǒ jiā hòumian yǒu yí ge xiǎo gōngyuán.","vi":"Phía sau nhà tôi có một công viên nhỏ.","en":"There is a small park behind my house."},{"use":"往后面 + động từ: về phía sau.","ex":"请大家往后面坐。","py":"Qǐng dàjiā wǎng hòumian zuò.","vi":"Mời mọi người ngồi lùi về phía sau.","en":"Everyone, please sit toward the back."},{"use":"后面的 + danh từ: phần nội dung phía sau.","ex":"后面的内容更有意思。","py":"Hòumian de nèiróng gèng yǒu yìsi.","vi":"Nội dung phía sau thú vị hơn.","en":"The content that follows is more interesting."}]},"没用":{"en":"useless; of no use","exs":[{"use":"Dùng để nói một việc, đồ vật hoặc cách làm không đem lại hiệu quả.","ex":"光着急是没用的。","py":"Guāng zháojí shì méi yòng de.","vi":"Chỉ lo lắng thôi thì không có tác dụng.","en":"Just worrying is useless."},{"use":"Làm vị ngữ: 这个/那个 + 没用.","ex":"这个办法对他一点儿也没用。","py":"Zhège bànfǎ duì tā yìdiǎnr yě méi yòng.","vi":"Cách này chẳng có tác dụng gì với anh ấy.","en":"This method doesn't work on him at all."},{"use":"Nói về người: 觉得自己没用 (cảm thấy mình vô dụng).","ex":"别说自己没用，你已经做得很好了。","py":"Bié shuō zìjǐ méi yòng, nǐ yǐjīng zuò de hěn hǎo le.","vi":"Đừng nói mình vô dụng, bạn đã làm rất tốt rồi.","en":"Don't say you're useless; you've done very well."},{"use":"没用 cũng có thể là 没 + 用 (động từ): chưa dùng.","ex":"这支笔我还没用过。","py":"Zhè zhī bǐ wǒ hái méi yòng guo.","vi":"Cây bút này tôi vẫn chưa dùng lần nào.","en":"I haven't used this pen yet."}]},"锻炼":{"en":"to exercise; to train; to temper","exs":[{"use":"Thường dùng: 锻炼身体; cũng có thể là rèn luyện năng lực.","ex":"为了健康，他每天锻炼身体。","py":"Wèile jiànkāng, tā měitiān duànliàn shēntǐ.","vi":"Vì sức khỏe, anh ấy tập luyện cơ thể mỗi ngày.","en":"For the sake of his health, he exercises every day."},{"use":"Động từ không tân ngữ: 去公园锻炼.","ex":"我早上常去公园锻炼。","py":"Wǒ zǎoshang cháng qù gōngyuán duànliàn.","vi":"Buổi sáng tôi thường ra công viên tập thể dục.","en":"I often go to the park to exercise in the morning."},{"use":"Nghĩa rèn luyện năng lực: 锻炼 + 能力/意志.","ex":"打工可以锻炼自己的能力。","py":"Dǎgōng kěyǐ duànliàn zìjǐ de nénglì.","vi":"Đi làm thêm có thể rèn luyện năng lực của bản thân.","en":"Part-time work can build your abilities."},{"use":"Danh từ: 锻炼 (sự rèn luyện, việc tập luyện) với 多/少/缺少.","ex":"你最近缺少锻炼，应该多运动。","py":"Nǐ zuìjìn quēshǎo duànliàn, yīnggāi duō yùndòng.","vi":"Dạo này bạn thiếu tập luyện, nên vận động nhiều hơn.","en":"You haven't been exercising enough lately; you should be more active."}]},"别":{"en":"don't; do not; (别人) other people","exs":[{"use":"Đặt trước động từ để tạo câu mệnh lệnh phủ định.","ex":"别忘了带手机。","py":"Bié wàng le dài shǒujī.","vi":"Đừng quên mang điện thoại.","en":"Don't forget to bring your phone."},{"use":"别 + động từ + 了: khuyên ngăn, bảo dừng việc gì.","ex":"天太晚了，你别去了。","py":"Tiān tài wǎn le, nǐ bié qù le.","vi":"Trời muộn quá rồi, bạn đừng đi nữa.","en":"It's too late; don't go."},{"use":"别 + 担心/着急: lời an ủi.","ex":"别担心，一切都会好的。","py":"Bié dānxīn, yíqiè dōu huì hǎo de.","vi":"Đừng lo, mọi chuyện sẽ ổn thôi.","en":"Don't worry, everything will be fine."},{"use":"Trong 别人 (người khác), 别 mang nghĩa “khác”.","ex":"别人的东西不能随便用。","py":"Biéren de dōngxi bù néng suíbiàn yòng.","vi":"Đồ của người khác không được tùy tiện dùng.","en":"You can't just use other people's things."}]},"等":{"en":"to wait; to wait for; etc.","exs":[{"use":"Thường dùng: 等 + người / sự việc; 等一下 là đợi một lát.","ex":"请你等我一下。","py":"Qǐng nǐ děng wǒ yíxià.","vi":"Bạn hãy đợi tôi một lát.","en":"Please wait for me a moment."},{"use":"等 + mệnh đề + 再/就…: đợi đến khi… rồi mới/thì…","ex":"等你到了，再给我打电话。","py":"Děng nǐ dào le, zài gěi wǒ dǎ diànhuà.","vi":"Đợi bạn đến nơi rồi hãy gọi điện cho tôi.","en":"Call me once you arrive."},{"use":"等 + người + động từ: chờ ai làm gì.","ex":"我在门口等朋友来。","py":"Wǒ zài ménkǒu děng péngyou lái.","vi":"Tôi đợi bạn đến ở cửa.","en":"I'm waiting at the door for my friend to come."},{"use":"Nghĩa “vân vân” đặt sau liệt kê: A、B 等 + danh từ.","ex":"他买了苹果、香蕉等水果。","py":"Tā mǎile píngguǒ, xiāngjiāo děng shuǐguǒ.","vi":"Anh ấy mua táo, chuối và các loại trái cây khác.","en":"He bought apples, bananas and other fruit."}]},"出问题":{"en":"to go wrong; to have a problem","exs":[{"use":"Dùng cho sức khỏe, máy móc, kế hoạch hoặc công việc gặp vấn đề.","ex":"电脑出问题了，打不开。","py":"Diànnǎo chū wèntí le, dǎ bù kāi.","vi":"Máy tính xảy ra vấn đề rồi, không mở được.","en":"Something's wrong with the computer; it won't open."},{"use":"Nói về cơ thể: 身体/胃 + 出问题.","ex":"他的胃最近出问题了。","py":"Tā de wèi zuìjìn chū wèntí le.","vi":"Dạ dày của anh ấy dạo này có vấn đề.","en":"His stomach has been giving him trouble lately."},{"use":"Nói về công việc, kế hoạch: 计划/工作 + 出问题.","ex":"要是计划出问题，我们就换一个办法。","py":"Yàoshi jìhuà chū wèntí, wǒmen jiù huàn yí ge bànfǎ.","vi":"Nếu kế hoạch gặp trục trặc thì chúng ta đổi cách khác.","en":"If the plan goes wrong, we'll try another way."},{"use":"Dạng phủ định/ hỏi: 不会出问题 / 出什么问题.","ex":"别担心，这次不会出问题的。","py":"Bié dānxīn, zhè cì bú huì chū wèntí de.","vi":"Đừng lo, lần này sẽ không có vấn đề gì đâu.","en":"Don't worry, nothing will go wrong this time."}]},"后悔":{"en":"to regret","exs":[{"use":"Thường dùng: 后悔 + động từ / 后悔做了某事.","ex":"我后悔没有早点开始学习。","py":"Wǒ hòuhuǐ méiyǒu zǎodiǎn kāishǐ xuéxí.","vi":"Tôi hối hận vì đã không bắt đầu học sớm hơn.","en":"I regret not starting to study earlier."},{"use":"别后悔 / 不后悔: lời khuyên hoặc khẳng định không hối tiếc.","ex":"这个决定我一点儿也不后悔。","py":"Zhège juédìng wǒ yìdiǎnr yě bú hòuhuǐ.","vi":"Quyết định này tôi không hề hối hận.","en":"I don't regret this decision at all."},{"use":"会后悔: sẽ hối hận (cảnh báo).","ex":"现在不努力，以后会后悔的。","py":"Xiànzài bù nǔlì, yǐhòu huì hòuhuǐ de.","vi":"Bây giờ không cố gắng, sau này sẽ hối hận.","en":"If you don't work hard now, you'll regret it later."},{"use":"后悔 + 极了/死了: hối hận vô cùng (khẩu ngữ).","ex":"我没带伞，后悔极了。","py":"Wǒ méi dài sǎn, hòuhuǐ jí le.","vi":"Tôi không mang ô, hối hận vô cùng.","en":"I didn't bring an umbrella and regret it terribly."}]},"医生":{"en":"doctor; physician","exs":[{"use":"Danh từ chỉ nghề nghiệp: 医生 (bác sĩ).","ex":"我妈妈是一位医生。","py":"Wǒ māma shì yí wèi yīshēng.","vi":"Mẹ tôi là một bác sĩ.","en":"My mother is a doctor."},{"use":"看医生: đi khám bác sĩ.","ex":"你不舒服就去看医生吧。","py":"Nǐ bù shūfu jiù qù kàn yīshēng ba.","vi":"Nếu thấy không khỏe thì đi khám bác sĩ đi.","en":"If you feel unwell, go and see a doctor."},{"use":"医生 + 说/让: lời dặn của bác sĩ.","ex":"医生说我要多休息，少喝咖啡。","py":"Yīshēng shuō wǒ yào duō xiūxi, shǎo hē kāfēi.","vi":"Bác sĩ nói tôi cần nghỉ ngơi nhiều, uống ít cà phê.","en":"The doctor said I should rest more and drink less coffee."},{"use":"当医生: làm bác sĩ (ước mơ, nghề nghiệp).","ex":"他长大以后想当医生。","py":"Tā zhǎngdà yǐhòu xiǎng dāng yīshēng.","vi":"Lớn lên cậu ấy muốn làm bác sĩ.","en":"He wants to be a doctor when he grows up."}]},"运动":{"en":"to exercise; sport; exercise","exs":[{"use":"Động từ: tập thể dục, vận động.","ex":"我每天晚上都去公园运动。","py":"Wǒ měitiān wǎnshang dōu qù gōngyuán yùndòng.","vi":"Mỗi tối tôi đều ra công viên tập thể dục.","en":"I go to the park to exercise every evening."},{"use":"Danh từ: môn thể thao, hoạt động thể thao: 喜欢…运动.","ex":"你最喜欢什么运动？","py":"Nǐ zuì xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào nhất?","en":"What sport do you like best?"},{"use":"多运动 / 做运动: vận động nhiều, tập luyện.","ex":"医生让我多运动，少坐着。","py":"Yīshēng ràng wǒ duō yùndòng, shǎo zuòzhe.","vi":"Bác sĩ bảo tôi vận động nhiều, ngồi ít thôi.","en":"The doctor told me to exercise more and sit less."},{"use":"运动 + 鞋/会/场: các từ ghép (giày thể thao, đại hội thể thao…).","ex":"这双运动鞋穿起来很舒服。","py":"Zhè shuāng yùndòngxié chuān qǐlái hěn shūfu.","vi":"Đôi giày thể thao này đi rất thoải mái.","en":"These sneakers are very comfortable to wear."}]},"散步":{"en":"to take a walk; to stroll","exs":[{"use":"Động từ ly hợp (V + O): 散散步, 散了步.","ex":"吃完晚饭，我们去河边散步。","py":"Chīwán wǎnfàn, wǒmen qù hébiān sànbù.","vi":"Ăn tối xong, chúng tôi ra bờ sông đi dạo.","en":"After dinner, we go for a walk by the river."},{"use":"去/出去 + 散步: đi dạo.","ex":"天气不错，我们出去散散步吧。","py":"Tiānqì búcuò, wǒmen chūqu sànsan bù ba.","vi":"Thời tiết đẹp, chúng ta ra ngoài đi dạo đi.","en":"The weather is nice; let's go out for a walk."},{"use":"Chỉ thói quen: 每天…散步.","ex":"爷爷每天早上都要散步一个小时。","py":"Yéye měitiān zǎoshang dōu yào sànbù yí ge xiǎoshí.","vi":"Ông nội sáng nào cũng đi dạo một tiếng.","en":"Grandpa takes an hour's walk every morning."},{"use":"和…一起散步: đi dạo cùng ai.","ex":"周末我喜欢和家人一起散步。","py":"Zhōumò wǒ xǐhuan hé jiārén yìqǐ sànbù.","vi":"Cuối tuần tôi thích đi dạo cùng người nhà.","en":"On weekends I like to take walks with my family."}]},"最后":{"en":"last; finally; in the end","exs":[{"use":"Làm trạng ngữ: 最后, … (cuối cùng).","ex":"最后，我们都同意了他的想法。","py":"Zuìhòu, wǒmen dōu tóngyì le tā de xiǎngfǎ.","vi":"Cuối cùng, chúng tôi đều đồng ý với ý kiến của anh ấy.","en":"In the end, we all agreed with his idea."},{"use":"最后 + 一 + lượng từ + danh từ: cuối cùng, sau chót.","ex":"这是最后一班地铁，快走吧。","py":"Zhè shì zuìhòu yì bān dìtiě, kuài zǒu ba.","vi":"Đây là chuyến tàu điện ngầm cuối, đi nhanh thôi.","en":"This is the last subway train; let's hurry."},{"use":"先…然后…最后…: trình tự các bước.","ex":"先洗菜，然后切菜，最后炒菜。","py":"Xiān xǐ cài, ránhòu qiē cài, zuìhòu chǎo cài.","vi":"Trước rửa rau, rồi thái rau, cuối cùng xào rau.","en":"First wash the vegetables, then chop them, and finally stir-fry them."},{"use":"最后 + 动词: chỉ kết quả cuối cùng của sự việc.","ex":"他试了很多次，最后成功了。","py":"Tā shìle hěn duō cì, zuìhòu chénggōng le.","vi":"Anh ấy thử rất nhiều lần, cuối cùng đã thành công.","en":"He tried many times and finally succeeded."}]},"同意":{"en":"to agree; to consent","exs":[{"use":"同意 + người / ý kiến / đề nghị.","ex":"我同意你的看法。","py":"Wǒ tóngyì nǐ de kànfǎ.","vi":"Tôi đồng ý với quan điểm của bạn.","en":"I agree with your view."},{"use":"Xin phép: 同意 + 我 + động từ (đồng ý cho…).","ex":"爸爸同意我一个人去旅行。","py":"Bàba tóngyì wǒ yí ge rén qù lǚxíng.","vi":"Bố đồng ý cho tôi đi du lịch một mình.","en":"Dad agreed to let me travel alone."},{"use":"Dạng phủ định: 不同意.","ex":"老板不同意这个计划。","py":"Lǎobǎn bù tóngyì zhège jìhuà.","vi":"Sếp không đồng ý kế hoạch này.","en":"The boss doesn't approve of this plan."},{"use":"Dùng trong hội thoại: 我同意 / 你同意吗？","ex":"你同意明天开会吗？","py":"Nǐ tóngyì míngtiān kāihuì ma?","vi":"Bạn có đồng ý họp vào ngày mai không?","en":"Do you agree to hold the meeting tomorrow?"}]},"减肥":{"en":"to lose weight; to go on a diet","exs":[{"use":"Động từ ly hợp (V + O): 减肥, 减了肥.","ex":"她最近在减肥，不吃甜的。","py":"Tā zuìjìn zài jiǎnféi, bù chī tián de.","vi":"Dạo này cô ấy đang giảm cân, không ăn đồ ngọt.","en":"She's dieting lately and doesn't eat sweets."},{"use":"为了减肥: để giảm cân.","ex":"为了减肥，他每天跑步半小时。","py":"Wèile jiǎnféi, tā měitiān pǎobù bàn xiǎoshí.","vi":"Để giảm cân, anh ấy chạy bộ nửa tiếng mỗi ngày.","en":"To lose weight, he runs for half an hour every day."},{"use":"想减肥 / 要减肥: muốn giảm cân.","ex":"你不胖，不用减肥。","py":"Nǐ bú pàng, búyòng jiǎnféi.","vi":"Bạn không béo, không cần giảm cân.","en":"You're not fat; you don't need to lose weight."},{"use":"减肥 + 的 + 方法: phương pháp giảm cân.","ex":"多运动是最好的减肥方法。","py":"Duō yùndòng shì zuì hǎo de jiǎnféi fāngfǎ.","vi":"Vận động nhiều là cách giảm cân tốt nhất.","en":"Exercising more is the best way to lose weight."}]},"跑步":{"en":"to run; to jog","exs":[{"use":"Động từ ly hợp (V + O): 跑步, 跑了步.","ex":"我每天早上去公园跑步。","py":"Wǒ měitiān zǎoshang qù gōngyuán pǎobù.","vi":"Mỗi sáng tôi ra công viên chạy bộ.","en":"I go jogging in the park every morning."},{"use":"Lặp động từ để chỉ thời lượng: 跑步跑了 + thời gian.","ex":"他昨天跑步跑了一个小时。","py":"Tā zuótiān pǎobù pǎole yí ge xiǎoshí.","vi":"Hôm qua anh ấy chạy bộ một tiếng.","en":"He ran for an hour yesterday."},{"use":"Danh từ chỉ môn: 喜欢跑步.","ex":"我喜欢跑步，不喜欢游泳。","py":"Wǒ xǐhuan pǎobù, bù xǐhuan yóuyǒng.","vi":"Tôi thích chạy bộ, không thích bơi.","en":"I like running, not swimming."},{"use":"下雨天不能跑步: điều kiện hạn chế.","ex":"下雨了，今天不能去跑步了。","py":"Xiàyǔ le, jīntiān bù néng qù pǎobù le.","vi":"Trời mưa rồi, hôm nay không đi chạy bộ được.","en":"It's raining, so I can't go jogging today."}]},"辛苦":{"en":"hard; laborious; (to) trouble","exs":[{"use":"Tính từ: vất vả, cực nhọc.","ex":"妈妈每天工作很辛苦。","py":"Māma měitiān gōngzuò hěn xīnkǔ.","vi":"Mẹ làm việc mỗi ngày rất vất vả.","en":"Mom works very hard every day."},{"use":"Lời cảm ơn: 辛苦了 (bạn vất vả rồi).","ex":"今天大家都辛苦了，早点回家休息吧。","py":"Jīntiān dàjiā dōu xīnkǔ le, zǎodiǎn huíjiā xiūxi ba.","vi":"Hôm nay mọi người vất vả rồi, về nhà nghỉ sớm đi.","en":"Thanks for all your hard work today; go home and rest early."},{"use":"Dùng như động từ khi nhờ vả: 辛苦你 + động từ.","ex":"辛苦你帮我拿一下这个箱子。","py":"Xīnkǔ nǐ bāng wǒ ná yíxià zhège xiāngzi.","vi":"Phiền bạn xách giúp tôi cái vali này.","en":"Sorry to trouble you, but could you carry this box for me?"},{"use":"Thể hiện sự thông cảm: 多辛苦啊.","ex":"做医生又忙又辛苦。","py":"Zuò yīshēng yòu máng yòu xīnkǔ.","vi":"Làm bác sĩ vừa bận vừa vất vả.","en":"Being a doctor is both busy and tiring."}]},"晚饭":{"en":"dinner; supper","exs":[{"use":"Danh từ: 吃晚饭 (ăn tối).","ex":"我们七点吃晚饭。","py":"Wǒmen qī diǎn chī wǎnfàn.","vi":"Chúng tôi ăn tối lúc bảy giờ.","en":"We eat dinner at seven."},{"use":"做晚饭: nấu bữa tối.","ex":"妈妈正在厨房做晚饭。","py":"Māma zhèngzài chúfáng zuò wǎnfàn.","vi":"Mẹ đang nấu bữa tối trong bếp.","en":"Mom is cooking dinner in the kitchen."},{"use":"晚饭后/晚饭前: sau/trước bữa tối.","ex":"晚饭后我常常出去散步。","py":"Wǎnfàn hòu wǒ chángcháng chūqu sànbù.","vi":"Sau bữa tối tôi thường ra ngoài đi dạo.","en":"After dinner I often go out for a walk."},{"use":"请…吃晚饭: mời ai ăn tối.","ex":"今天我请你吃晚饭。","py":"Jīntiān wǒ qǐng nǐ chī wǎnfàn.","vi":"Hôm nay tôi mời bạn ăn tối.","en":"Today dinner is on me."}]},"一家人":{"en":"a whole family; one family","exs":[{"use":"Chỉ cả gia đình sống cùng nhau: 我们一家人.","ex":"周末我们一家人去公园玩。","py":"Zhōumò wǒmen yìjiārén qù gōngyuán wán.","vi":"Cuối tuần cả nhà chúng tôi đi công viên chơi.","en":"On weekends our whole family goes to the park."},{"use":"一家人 + 在一起: cả nhà quây quần.","ex":"过年的时候，一家人在一起吃饭。","py":"Guònián de shíhou, yìjiārén zài yìqǐ chīfàn.","vi":"Dịp Tết, cả nhà quây quần ăn cơm.","en":"At the New Year, the whole family eats together."},{"use":"Câu nói quen thuộc: 都是一家人 (đều là người một nhà, đừng khách sáo).","ex":"都是一家人，不用客气。","py":"Dōu shì yìjiārén, búyòng kèqi.","vi":"Đều là người một nhà, không cần khách sáo.","en":"We're all family; no need to be polite."},{"use":"Dùng để nói quan hệ thân thiết như người nhà.","ex":"我们相处得像一家人一样。","py":"Wǒmen xiāngchǔ de xiàng yìjiārén yíyàng.","vi":"Chúng tôi chung sống như người một nhà.","en":"We get along like one family."}]},"肚子":{"en":"belly; stomach; abdomen","exs":[{"use":"Danh từ: bụng (bộ phận cơ thể).","ex":"我的肚子有点儿疼。","py":"Wǒ de dùzi yǒudiǎnr téng.","vi":"Bụng tôi hơi đau.","en":"My stomach hurts a little."},{"use":"肚子饿了: đói bụng.","ex":"我肚子饿了，想吃点东西。","py":"Wǒ dùzi è le, xiǎng chī diǎn dōngxi.","vi":"Tôi đói bụng rồi, muốn ăn chút gì đó.","en":"I'm hungry and want something to eat."},{"use":"拉肚子: bị tiêu chảy.","ex":"他吃坏了东西，一直拉肚子。","py":"Tā chīhuàile dōngxi, yìzhí lādùzi.","vi":"Anh ấy ăn phải đồ hỏng nên cứ bị tiêu chảy mãi.","en":"He ate something bad and keeps having diarrhea."},{"use":"吃得肚子很胀: ăn no căng bụng.","ex":"晚饭吃得太多，肚子很不舒服。","py":"Wǎnfàn chī de tài duō, dùzi hěn bù shūfu.","vi":"Bữa tối ăn quá nhiều, bụng rất khó chịu.","en":"I ate too much at dinner and my stomach feels uncomfortable."}]},"家人":{"en":"family member; family","exs":[{"use":"Danh từ: người nhà, thành viên trong gia đình.","ex":"我很想念我的家人。","py":"Wǒ hěn xiǎngniàn wǒ de jiārén.","vi":"Tôi rất nhớ người nhà của mình.","en":"I miss my family very much."},{"use":"和家人 + động từ: cùng người nhà làm gì.","ex":"春节我会和家人一起过。","py":"Chūnjié wǒ huì hé jiārén yìqǐ guò.","vi":"Tết tôi sẽ đón cùng người nhà.","en":"I will spend the Spring Festival with my family."},{"use":"给家人 + động từ: dành cho người nhà.","ex":"我给家人买了一些礼物。","py":"Wǒ gěi jiārén mǎile yìxiē lǐwù.","vi":"Tôi mua một ít quà cho người nhà.","en":"I bought some gifts for my family."},{"use":"Nhấn mạnh sự quan tâm: 关心家人.","ex":"工作再忙，也要多关心家人。","py":"Gōngzuò zài máng, yě yào duō guānxīn jiārén.","vi":"Công việc bận đến mấy cũng phải quan tâm người nhà nhiều hơn.","en":"However busy work is, you should care more for your family."}]},"一天":{"en":"one day; a whole day","exs":[{"use":"Chỉ khoảng thời gian một ngày: 一天 + 三顿饭.","ex":"一天要吃三顿饭。","py":"Yì tiān yào chī sān dùn fàn.","vi":"Một ngày phải ăn ba bữa.","en":"You should eat three meals a day."},{"use":"Dùng như trạng ngữ: một ngày (trọn ngày).","ex":"我忙了一天，现在很累。","py":"Wǒ mángle yì tiān, xiànzài hěn lèi.","vi":"Tôi bận suốt một ngày, bây giờ rất mệt.","en":"I've been busy all day and now I'm very tired."},{"use":"Số lượng + 一天: mỗi ngày bao nhiêu (đơn vị/ngày).","ex":"他一天喝五杯水。","py":"Tā yì tiān hē wǔ bēi shuǐ.","vi":"Một ngày anh ấy uống năm cốc nước.","en":"He drinks five glasses of water a day."},{"use":"Chỉ một ngày nào đó (trong tương lai/quá khứ): 有一天.","ex":"有一天，他突然给我打了电话。","py":"Yǒu yì tiān, tā tūrán gěi wǒ dǎle diànhuà.","vi":"Có một ngày, anh ấy đột nhiên gọi điện cho tôi.","en":"One day, he suddenly called me."}]},"夫妻":{"en":"husband and wife; married couple","exs":[{"use":"Danh từ: vợ chồng, thường dùng chỉ cặp vợ chồng.","ex":"他们是一对幸福的夫妻。","py":"Tāmen shì yí duì xìngfú de fūqī.","vi":"Họ là một đôi vợ chồng hạnh phúc.","en":"They are a happy married couple."},{"use":"夫妻 + 俩: hai vợ chồng.","ex":"这对夫妻俩一起开了一家小饭馆。","py":"Zhè duì fūqī liǎ yìqǐ kāile yì jiā xiǎo fànguǎn.","vi":"Hai vợ chồng này cùng mở một quán ăn nhỏ.","en":"The couple opened a small restaurant together."},{"use":"夫妻感情: tình cảm vợ chồng.","ex":"夫妻之间要多沟通。","py":"Fūqī zhījiān yào duō gōutōng.","vi":"Giữa vợ chồng cần trao đổi nhiều với nhau.","en":"Husbands and wives should communicate more."},{"use":"Cụm cố định: 老夫妻 / 新婚夫妻.","ex":"那对老夫妻每天一起散步。","py":"Nà duì lǎo fūqī měitiān yìqǐ sànbù.","vi":"Cặp vợ chồng già ấy ngày nào cũng cùng nhau đi dạo.","en":"The elderly couple takes a walk together every day."}]},"加深":{"en":"to deepen","exs":[{"use":"加深 + sự hiểu biết / tình cảm / ấn tượng.","ex":"旅行可以加深我们之间的感情。","py":"Lǚxíng kěyǐ jiāshēn wǒmen zhījiān de gǎnqíng.","vi":"Du lịch có thể làm sâu sắc thêm tình cảm giữa chúng ta.","en":"Traveling can deepen the bond between us."},{"use":"加深 + 印象 (làm ấn tượng sâu hơn).","ex":"多读几遍可以加深印象。","py":"Duō dú jǐ biàn kěyǐ jiāshēn yìnxiàng.","vi":"Đọc thêm vài lần có thể khắc sâu ấn tượng.","en":"Reading it a few more times will help you remember it better."},{"use":"加深 + 了解: hiểu biết sâu hơn.","ex":"聊天能加深我们对彼此的了解。","py":"Liáotiān néng jiāshēn wǒmen duì bǐcǐ de liǎojiě.","vi":"Trò chuyện giúp chúng tôi hiểu nhau sâu sắc hơn.","en":"Chatting helps us understand each other better."},{"use":"Dùng với vấn đề, mâu thuẫn: 矛盾 + 加深.","ex":"这样做只会加深你们的矛盾。","py":"Zhèyàng zuò zhǐ huì jiāshēn nǐmen de máodùn.","vi":"Làm như vậy chỉ khiến mâu thuẫn giữa các bạn thêm sâu sắc.","en":"Doing this will only deepen the conflict between you."}]},"感情":{"en":"feeling; emotion; affection","exs":[{"use":"Trong bài là thay đổi cảm xúc.","ex":"颜色会影响人的感情。","py":"Yánsè huì yǐngxiǎng rén de gǎnqíng.","vi":"Màu sắc có thể ảnh hưởng cảm xúc của con người.","en":"Colors can affect people's emotions."},{"use":"Nghĩa tình cảm giữa người với người: 感情很好/深.","ex":"他们俩的感情很好。","py":"Tāmen liǎ de gǎnqíng hěn hǎo.","vi":"Tình cảm của hai người họ rất tốt.","en":"The two of them are very close."},{"use":"对…有感情: có tình cảm với…","ex":"我对这个城市很有感情。","py":"Wǒ duì zhège chéngshì hěn yǒu gǎnqíng.","vi":"Tôi có nhiều tình cảm với thành phố này.","en":"I am very attached to this city."},{"use":"Tình yêu đôi lứa/ tình cảm: 谈感情, 感情问题.","ex":"朋友之间的感情需要用心维护。","py":"Péngyou zhījiān de gǎnqíng xūyào yòngxīn wéihù.","vi":"Tình cảm giữa bạn bè cần được vun đắp bằng cả tấm lòng.","en":"Friendship needs to be tended with care."}]},"孩子":{"en":"child; children; kid","exs":[{"use":"Danh từ: đứa trẻ, trẻ em.","ex":"这个孩子很聪明。","py":"Zhège háizi hěn cōngming.","vi":"Đứa trẻ này rất thông minh.","en":"This child is very smart."},{"use":"Nghĩa “con cái” trong gia đình: 我的孩子.","ex":"我有两个孩子，一个男孩一个女孩。","py":"Wǒ yǒu liǎng ge háizi, yí ge nánhái yí ge nǚhái.","vi":"Tôi có hai đứa con, một trai một gái.","en":"I have two children, a boy and a girl."},{"use":"孩子们: số nhiều (bọn trẻ).","ex":"孩子们在院子里玩得很开心。","py":"Háizimen zài yuànzi lǐ wán de hěn kāixīn.","vi":"Bọn trẻ chơi rất vui trong sân.","en":"The children are having great fun in the yard."},{"use":"教育孩子: dạy dỗ con cái.","ex":"父母应该多花时间陪孩子。","py":"Fùmǔ yīnggāi duō huā shíjiān péi háizi.","vi":"Cha mẹ nên dành nhiều thời gian bên con cái.","en":"Parents should spend more time with their children."}]},"烦恼":{"en":"worried; vexed; trouble; worries","exs":[{"use":"Có thể là danh từ hoặc động từ.","ex":"别为小事烦恼。","py":"Bié wèi xiǎoshì fánnǎo.","vi":"Đừng phiền não vì chuyện nhỏ.","en":"Don't worry about small things."},{"use":"Danh từ: 有烦恼 (có nỗi phiền muộn).","ex":"每个人都有自己的烦恼。","py":"Měi ge rén dōu yǒu zìjǐ de fánnǎo.","vi":"Mỗi người đều có nỗi phiền não riêng.","en":"Everyone has their own worries."},{"use":"烦恼 + 的 + danh từ: bổ nghĩa cho danh từ.","ex":"跟朋友聊聊天，烦恼的事就少了。","py":"Gēn péngyou liáoliao tiān, fánnǎo de shì jiù shǎo le.","vi":"Trò chuyện với bạn bè thì những chuyện phiền lòng sẽ bớt đi.","en":"Chatting with friends makes your troubles feel smaller."},{"use":"Tính từ: cảm thấy phiền muộn, khó chịu.","ex":"考试没考好，他很烦恼。","py":"Kǎoshì méi kǎohǎo, tā hěn fánnǎo.","vi":"Thi không tốt nên anh ấy rất buồn phiền.","en":"He is upset because he didn't do well on the exam."}]},"鼻子":{"en":"nose","exs":[{"use":"Danh từ: mũi (bộ phận cơ thể).","ex":"他的鼻子又高又直。","py":"Tā de bízi yòu gāo yòu zhí.","vi":"Mũi của anh ấy vừa cao vừa thẳng.","en":"His nose is tall and straight."},{"use":"Triệu chứng cảm: 鼻子不通 / 鼻子难受.","ex":"我感冒了，鼻子不通气。","py":"Wǒ gǎnmào le, bízi bù tōngqì.","vi":"Tôi bị cảm, mũi bị nghẹt.","en":"I have a cold and my nose is blocked."},{"use":"Dùng với động từ: 捂住/摸 + 鼻子.","ex":"这里太臭了，他捂住了鼻子。","py":"Zhèlǐ tài chòu le, tā wǔzhùle bízi.","vi":"Ở đây hôi quá, anh ấy bịt mũi lại.","en":"It smells awful here, so he held his nose."},{"use":"用 + 鼻子: dùng mũi để làm gì.","ex":"我们用鼻子闻味道。","py":"Wǒmen yòng bízi wén wèidào.","vi":"Chúng ta dùng mũi để ngửi mùi.","en":"We smell with our nose."}]},"流血":{"en":"to bleed","exs":[{"use":"Động từ ly hợp (V + O): 流血 (chảy máu).","ex":"他的手受伤了，一直在流血。","py":"Tā de shǒu shòushāng le, yìzhí zài liúxiě.","vi":"Tay anh ấy bị thương, máu cứ chảy mãi.","en":"His hand is hurt and keeps bleeding."},{"use":"流血 + 了/不止: chảy máu / chảy máu không cầm.","ex":"他的鼻子突然流血了。","py":"Tā de bízi tūrán liúxiě le.","vi":"Mũi anh ấy đột nhiên chảy máu.","en":"His nose suddenly started bleeding."},{"use":"Cần xử lý khi chảy máu: 流血 + 要…","ex":"要是流血了，要马上去医院。","py":"Yàoshi liúxiě le, yào mǎshàng qù yīyuàn.","vi":"Nếu chảy máu thì phải đến bệnh viện ngay.","en":"If you're bleeding, go to the hospital right away."},{"use":"Nghĩa bóng: 流血流汗 (đổ máu đổ mồ hôi).","ex":"运动员们流血流汗，才取得了成功。","py":"Yùndòngyuánmen liúxiě liúhàn, cái qǔdéle chénggōng.","vi":"Các vận động viên đổ máu đổ mồ hôi mới giành được thành công.","en":"The athletes shed blood and sweat before they achieved success."}]},"擦擦":{"en":"to wipe; to rub (a little)","exs":[{"use":"擦擦 là dạng lặp của 擦 (lau một chút).","ex":"你擦擦桌子，我来拿碗。","py":"Nǐ cāca zhuōzi, wǒ lái ná wǎn.","vi":"Bạn lau bàn một chút, tôi đi lấy bát.","en":"You wipe the table; I'll get the bowls."},{"use":"擦擦 + 汗 / 脸: lau mồ hôi, lau mặt.","ex":"你出汗了，快擦擦吧。","py":"Nǐ chūhàn le, kuài cāca ba.","vi":"Bạn ra mồ hôi rồi, mau lau đi.","en":"You're sweating; wipe it off quickly."},{"use":"擦擦 + 眼泪: lau nước mắt.","ex":"别哭了，擦擦眼泪吧。","py":"Bié kū le, cāca yǎnlèi ba.","vi":"Đừng khóc nữa, lau nước mắt đi.","en":"Stop crying and wipe your tears."},{"use":"擦擦 + 鼻子/血: lau mũi, lau vết máu.","ex":"他的鼻子流血了，我给他擦擦。","py":"Tā de bízi liúxiě le, wǒ gěi tā cāca.","vi":"Mũi anh ấy chảy máu, tôi lau giúp anh ấy.","en":"His nose is bleeding; I'll wipe it for him."}]},"北方":{"en":"north; the northern part (of a country)","exs":[{"use":"Danh từ phương vị: miền Bắc (của một nước).","ex":"我是北方人，喜欢吃面食。","py":"Wǒ shì běifāng rén, xǐhuan chī miànshí.","vi":"Tôi là người miền Bắc, thích ăn món bột mì.","en":"I'm from the north and like wheat-based food."},{"use":"北方 + 的 + danh từ: …của miền Bắc.","ex":"北方的冬天又冷又干。","py":"Běifāng de dōngtiān yòu lěng yòu gān.","vi":"Mùa đông miền Bắc vừa lạnh vừa khô.","en":"Winters in the north are cold and dry."},{"use":"Đối lập với 南方 (miền Nam).","ex":"北方和南方的饮食习惯不一样。","py":"Běifāng hé nánfāng de yǐnshí xíguàn bù yíyàng.","vi":"Thói quen ăn uống ở miền Bắc và miền Nam không giống nhau.","en":"Eating habits differ between the north and the south."},{"use":"去北方 / 在北方: đi/ở miền Bắc.","ex":"我明年想去北方看雪。","py":"Wǒ míngnián xiǎng qù běifāng kàn xuě.","vi":"Sang năm tôi muốn đi miền Bắc ngắm tuyết.","en":"Next year I want to go to the north to see snow."}]},"气候":{"en":"climate","exs":[{"use":"Danh từ: khí hậu của một vùng: 这里的气候.","ex":"这里的气候很舒服，夏天不太热。","py":"Zhèlǐ de qìhòu hěn shūfu, xiàtiān bú tài rè.","vi":"Khí hậu ở đây rất dễ chịu, mùa hè không quá nóng.","en":"The climate here is pleasant; summers aren't too hot."},{"use":"气候 + 变化: biến đổi khí hậu.","ex":"气候变化影响着我们的生活。","py":"Qìhòu biànhuà yǐngxiǎngzhe wǒmen de shēnghuó.","vi":"Biến đổi khí hậu đang ảnh hưởng đến cuộc sống của chúng ta.","en":"Climate change is affecting our lives."},{"use":"适应…气候: thích nghi với khí hậu.","ex":"刚到这儿，我还不习惯这里的气候。","py":"Gāng dào zhèr, wǒ hái bù xíguàn zhèlǐ de qìhòu.","vi":"Mới đến đây, tôi vẫn chưa quen khí hậu nơi này.","en":"I just arrived and am not yet used to the climate here."},{"use":"Khí hậu khác thời tiết: 北方气候干燥.","ex":"北方气候干燥，南方气候潮湿。","py":"Běifāng qìhòu gānzào, nánfāng qìhòu cháoshī.","vi":"Khí hậu miền Bắc khô, khí hậu miền Nam ẩm.","en":"The north has a dry climate and the south a humid one."}]},"估计":{"en":"to estimate; to reckon; estimate","exs":[{"use":"Động từ: ước đoán, phỏng chừng: 估计 + mệnh đề.","ex":"我估计他今天不会来了。","py":"Wǒ gūjì tā jīntiān bú huì lái le.","vi":"Tôi đoán hôm nay anh ấy sẽ không đến nữa.","en":"I reckon he won't come today."},{"use":"Đứng đầu câu: 估计 + …, ước chừng.","ex":"估计明天会下雨，你带把伞吧。","py":"Gūjì míngtiān huì xiàyǔ, nǐ dài bǎ sǎn ba.","vi":"Chắc ngày mai sẽ mưa, bạn mang theo ô nhé.","en":"It will probably rain tomorrow; take an umbrella."},{"use":"估计 + số lượng/thời gian: ước tính.","ex":"我估计开车到那里要两个小时。","py":"Wǒ gūjì kāichē dào nàlǐ yào liǎng ge xiǎoshí.","vi":"Tôi ước tính lái xe đến đó mất hai tiếng.","en":"I estimate it takes two hours to drive there."},{"use":"Danh từ: 估计 (sự ước tính), 据估计…","ex":"据估计，这个城市有一千万人口。","py":"Jù gūjì, zhège chéngshì yǒu yì qiān wàn rénkǒu.","vi":"Theo ước tính, thành phố này có mười triệu dân.","en":"It is estimated that this city has ten million people."}]},"天气":{"en":"weather","exs":[{"use":"Danh từ: thời tiết; 今天天气 + tính từ.","ex":"今天天气很好，我们去爬山吧。","py":"Jīntiān tiānqì hěn hǎo, wǒmen qù pá shān ba.","vi":"Hôm nay thời tiết đẹp, chúng ta đi leo núi đi.","en":"The weather is nice today; let's go hiking."},{"use":"天气 + 预报: dự báo thời tiết.","ex":"你看了明天的天气预报吗？","py":"Nǐ kànle míngtiān de tiānqì yùbào ma?","vi":"Bạn xem dự báo thời tiết ngày mai chưa?","en":"Have you checked tomorrow's weather forecast?"},{"use":"Hỏi thời tiết: …天气怎么样？","ex":"北京现在的天气怎么样？","py":"Běijīng xiànzài de tiānqì zěnmeyàng?","vi":"Thời tiết ở Bắc Kinh bây giờ thế nào?","en":"What's the weather like in Beijing now?"},{"use":"天气 + 变化: thời tiết thay đổi, ảnh hưởng sức khỏe.","ex":"天气变冷了，要注意身体。","py":"Tiānqì biàn lěng le, yào zhùyì shēntǐ.","vi":"Trời trở lạnh rồi, phải chú ý giữ gìn sức khỏe.","en":"It has turned cold, so take care of your health."}]},"感冒":{"en":"to catch a cold; common cold","exs":[{"use":"Động từ: bị cảm (感冒了).","ex":"我感冒了，头有点疼。","py":"Wǒ gǎnmào le, tóu yǒudiǎn téng.","vi":"Tôi bị cảm rồi, đầu hơi đau.","en":"I've caught a cold and have a slight headache."},{"use":"Danh từ: 得/患感冒, 重感冒.","ex":"他得了重感冒，已经三天没上班了。","py":"Tā déle zhòng gǎnmào, yǐjīng sān tiān méi shàngbān le.","vi":"Anh ấy bị cảm nặng, đã ba ngày không đi làm.","en":"He has a bad cold and hasn't gone to work for three days."},{"use":"Nguyên nhân: 因为…感冒了.","ex":"昨天淋了雨，所以今天感冒了。","py":"Zuótiān línle yǔ, suǒyǐ jīntiān gǎnmào le.","vi":"Hôm qua bị dầm mưa nên hôm nay bị cảm.","en":"I got caught in the rain yesterday, so I have a cold today."},{"use":"Phòng cảm: 小心别感冒 / 预防感冒.","ex":"天冷了，多穿点儿，小心别感冒。","py":"Tiān lěng le, duō chuān diǎnr, xiǎoxīn bié gǎnmào.","vi":"Trời lạnh rồi, mặc thêm áo, cẩn thận kẻo bị cảm.","en":"It's cold now; wear more clothes so you don't catch a cold."}]},"只是":{"en":"just; merely; only; it's just that","exs":[{"use":"Phó từ: chỉ là, chỉ là… (giảm nhẹ mức độ).","ex":"别担心，我只是有点儿累。","py":"Bié dānxīn, wǒ zhǐshì yǒudiǎnr lèi.","vi":"Đừng lo, tôi chỉ hơi mệt thôi.","en":"Don't worry, I'm just a bit tired."},{"use":"只是 + danh từ/động từ: chỉ là… mà thôi.","ex":"这只是一个小问题，不用紧张。","py":"Zhè zhǐshì yí ge xiǎo wèntí, búyòng jǐnzhāng.","vi":"Đây chỉ là một vấn đề nhỏ, không cần căng thẳng.","en":"This is only a minor problem; no need to be nervous."},{"use":"Nghĩa chuyển ngoặt: …，只是… (nhưng mà).","ex":"这件衣服很好看，只是有点贵。","py":"Zhè jiàn yīfu hěn hǎokàn, zhǐshì yǒudiǎn guì.","vi":"Chiếc áo này rất đẹp, chỉ là hơi đắt.","en":"This piece of clothing is pretty, it's just a little expensive."},{"use":"Phủ định: 不只是 (không chỉ là).","ex":"学习不只是为了考试。","py":"Xuéxí bù zhǐshì wèile kǎoshì.","vi":"Học tập không chỉ là để đi thi.","en":"Studying is not only for taking exams."}]},"咳嗽":{"en":"to cough","exs":[{"use":"Động từ: ho (咳嗽 + 得…).","ex":"他咳嗽得很厉害，晚上睡不着。","py":"Tā késou de hěn lìhai, wǎnshang shuì bù zháo.","vi":"Anh ấy ho rất dữ, ban đêm không ngủ được.","en":"He coughs terribly and can't sleep at night."},{"use":"Triệu chứng đi cùng: 感冒/发烧 + 咳嗽.","ex":"我感冒了，一直咳嗽。","py":"Wǒ gǎnmào le, yìzhí késou.","vi":"Tôi bị cảm, ho suốt.","en":"I have a cold and keep coughing."},{"use":"Khuyên bảo: 咳嗽 + 要…","ex":"咳嗽的时候要用手捂住嘴。","py":"Késou de shíhou yào yòng shǒu wǔzhù zuǐ.","vi":"Khi ho phải dùng tay che miệng.","en":"Cover your mouth with your hand when you cough."},{"use":"咳嗽 + 药: thuốc ho; danh từ hóa.","ex":"医生给我开了咳嗽药。","py":"Yīshēng gěi wǒ kāile késou yào.","vi":"Bác sĩ kê cho tôi thuốc ho.","en":"The doctor prescribed me cough medicine."}]},"头疼":{"en":"to have a headache; headache; troublesome","exs":[{"use":"Tính từ/động từ: đau đầu.","ex":"我今天头疼，想早点睡觉。","py":"Wǒ jīntiān tóuténg, xiǎng zǎodiǎn shuìjiào.","vi":"Hôm nay tôi đau đầu, muốn đi ngủ sớm.","en":"I have a headache today and want to go to bed early."},{"use":"头疼 + 得 + bổ ngữ: đau đầu dữ dội.","ex":"他头疼得睡不着觉。","py":"Tā tóuténg de shuì bù zháo jiào.","vi":"Anh ấy đau đầu đến không ngủ được.","en":"His head hurts so much that he can't sleep."},{"use":"Nghĩa bóng: gây đau đầu (phiền toái): 让人头疼.","ex":"这个问题真让人头疼。","py":"Zhège wèntí zhēn ràng rén tóuténg.","vi":"Vấn đề này thật khiến người ta đau đầu.","en":"This problem is really a headache."},{"use":"Thường kèm cảm: 感冒了，头疼，还咳嗽.","ex":"他又感冒又头疼，只好请假了。","py":"Tā yòu gǎnmào yòu tóuténg, zhǐhǎo qǐngjià le.","vi":"Anh ấy vừa bị cảm vừa đau đầu nên đành xin nghỉ.","en":"He had a cold and a headache, so he had to take leave."}]},"严重":{"en":"serious; severe; grave","exs":[{"use":"Tính từ: nghiêm trọng (mức độ bệnh, vấn đề).","ex":"他的病很严重，要住院。","py":"Tā de bìng hěn yánzhòng, yào zhùyuàn.","vi":"Bệnh của anh ấy rất nghiêm trọng, phải nhập viện.","en":"His illness is serious and he must be hospitalized."},{"use":"严重 + 的 + danh từ: bổ nghĩa.","ex":"这是一个很严重的错误。","py":"Zhè shì yí ge hěn yánzhòng de cuòwù.","vi":"Đây là một sai lầm rất nghiêm trọng.","en":"This is a very serious mistake."},{"use":"Trạng ngữ: 严重 + động từ (ảnh hưởng nghiêm trọng).","ex":"污染严重影响了人们的健康。","py":"Wūrǎn yánzhòng yǐngxiǎngle rénmen de jiànkāng.","vi":"Ô nhiễm ảnh hưởng nghiêm trọng đến sức khỏe mọi người.","en":"Pollution has seriously affected people's health."},{"use":"Phủ định/hỏi: 不严重 / 严重吗？","ex":"别担心，只是小感冒，不严重。","py":"Bié dānxīn, zhǐshì xiǎo gǎnmào, bù yánzhòng.","vi":"Đừng lo, chỉ là cảm nhẹ, không nghiêm trọng.","en":"Don't worry, it's just a minor cold, nothing serious."}]},"时冷时热":{"en":"sometimes cold, sometimes hot","exs":[{"use":"Thành ngữ dạng 时…时…: lúc… lúc…; chỉ thời tiết hoặc cảm giác cơ thể.","ex":"这几天天气时冷时热，很容易感冒。","py":"Zhè jǐ tiān tiānqì shí lěng shí rè, hěn róngyì gǎnmào.","vi":"Mấy hôm nay thời tiết lúc nóng lúc lạnh, rất dễ bị cảm.","en":"The weather has been hot one moment and cold the next; it's easy to catch a cold."},{"use":"Nói về cảm giác cơ thể khi bệnh.","ex":"他发烧了，觉得身体时冷时热。","py":"Tā fāshāo le, juéde shēntǐ shí lěng shí rè.","vi":"Anh ấy bị sốt, cảm thấy người lúc lạnh lúc nóng.","en":"He has a fever and feels hot and cold by turns."},{"use":"Dùng làm vị ngữ với 变得/总是.","ex":"春天的天气总是时冷时热的。","py":"Chūntiān de tiānqì zǒngshì shí lěng shí rè de.","vi":"Thời tiết mùa xuân lúc nào cũng lúc lạnh lúc nóng.","en":"Spring weather is always changeable, cold one moment and hot the next."},{"use":"Dùng với phòng điều hòa: nhiệt độ thất thường.","ex":"房间里的空调时冷时热，不太舒服。","py":"Fángjiān lǐ de kōngtiáo shí lěng shí rè, bú tài shūfu.","vi":"Điều hòa trong phòng lúc lạnh lúc nóng, không thoải mái lắm.","en":"The air conditioner in the room swings between cold and hot; it's not comfortable."}]},"保暖":{"en":"to keep warm","exs":[{"use":"Động từ: giữ ấm; 注意保暖.","ex":"冬天要注意保暖，别感冒。","py":"Dōngtiān yào zhùyì bǎonuǎn, bié gǎnmào.","vi":"Mùa đông phải chú ý giữ ấm, đừng để bị cảm.","en":"Keep warm in winter so you don't catch a cold."},{"use":"保暖 + danh từ: đồ giữ ấm (保暖衣, 保暖鞋).","ex":"这件羽绒服保暖效果很好。","py":"Zhè jiàn yǔróngfú bǎonuǎn xiàoguǒ hěn hǎo.","vi":"Chiếc áo lông vũ này giữ ấm rất tốt.","en":"This down jacket keeps you very warm."},{"use":"为了保暖: để giữ ấm.","ex":"为了保暖，她戴上了帽子和围巾。","py":"Wèile bǎonuǎn, tā dàishàngle màozi hé wéijīn.","vi":"Để giữ ấm, cô ấy đội mũ và quàng khăn.","en":"To stay warm, she put on a hat and scarf."},{"use":"Khuyên người khác: 给…保暖.","ex":"天冷了，给孩子穿厚点保暖。","py":"Tiān lěng le, gěi háizi chuān hòu diǎn bǎonuǎn.","vi":"Trời lạnh rồi, mặc dày cho con để giữ ấm.","en":"It's cold; dress the child warmly."}]},"打开":{"en":"to open; to turn on","exs":[{"use":"打开 + vật thể (cửa, hộp, sách…).","ex":"请打开书，翻到第十页。","py":"Qǐng dǎkāi shū, fāndào dì shí yè.","vi":"Hãy mở sách ra, lật đến trang mười.","en":"Please open your book and turn to page ten."},{"use":"打开 + thiết bị: bật (TV, máy tính…).","ex":"他回家第一件事就是打开电视。","py":"Tā huíjiā dì yī jiàn shì jiù shì dǎkāi diànshì.","vi":"Việc đầu tiên khi về nhà của anh ấy là bật TV.","en":"The first thing he does when he gets home is turn on the TV."},{"use":"打开 + 窗户/门: mở cửa sổ, cửa.","ex":"房间太热了，把窗户打开吧。","py":"Fángjiān tài rè le, bǎ chuānghu dǎkāi ba.","vi":"Phòng nóng quá, mở cửa sổ ra đi.","en":"It's too hot in here; open the window."},{"use":"打开 + hộp, quà: mở ra xem bên trong.","ex":"我打开盒子，里面是一份生日礼物。","py":"Wǒ dǎkāi hézi, lǐmiàn shì yí fèn shēngrì lǐwù.","vi":"Tôi mở hộp ra, bên trong là một món quà sinh nhật.","en":"I opened the box and found a birthday present inside."}]},"窗户":{"en":"window","exs":[{"use":"Danh từ. 常用：开窗户、关窗户。","ex":"请打开窗户。","py":"Qǐng dǎkāi chuānghu.","vi":"Hãy mở cửa sổ.","en":"Please open the window."},{"use":"关窗户: đóng cửa sổ.","ex":"外面下雨了，快去关窗户。","py":"Wàimiàn xiàyǔ le, kuài qù guān chuānghu.","vi":"Bên ngoài mưa rồi, mau đi đóng cửa sổ.","en":"It's raining outside; go close the window."},{"use":"Lượng từ: 一扇窗户.","ex":"这个房间有两扇大窗户。","py":"Zhège fángjiān yǒu liǎng shàn dà chuānghu.","vi":"Căn phòng này có hai ô cửa sổ lớn.","en":"This room has two large windows."},{"use":"Vị trí: 窗户旁边 / 靠窗户.","ex":"我喜欢坐在窗户旁边看书。","py":"Wǒ xǐhuan zuò zài chuānghu pángbiān kànshū.","vi":"Tôi thích ngồi cạnh cửa sổ đọc sách.","en":"I like sitting by the window to read."}]},"换换":{"en":"to change; to switch (a little)","exs":[{"use":"换换 là dạng lặp của 换: đổi một chút.","ex":"天气冷了，该换换衣服了。","py":"Tiānqì lěng le, gāi huànhuan yīfu le.","vi":"Trời lạnh rồi, đến lúc thay quần áo rồi.","en":"It's getting cold; time to change your clothes."},{"use":"换换 + 空气: thay đổi không khí, đổi môi trường.","ex":"屋里太闷了，开窗换换空气吧。","py":"Wū lǐ tài mēn le, kāi chuāng huànhuan kōngqì ba.","vi":"Trong nhà ngột ngạt quá, mở cửa cho thoáng khí đi.","en":"It's stuffy inside; open a window to let in some fresh air."},{"use":"换换 + 心情/环境: đổi không khí cho tinh thần.","ex":"周末出去旅游，换换心情。","py":"Zhōumò chūqu lǚyóu, huànhuan xīnqíng.","vi":"Cuối tuần đi du lịch để đổi tâm trạng.","en":"Go traveling on the weekend to refresh your mood."},{"use":"换换 + 口味/方法: thử cái khác.","ex":"天天吃米饭，我想换换口味。","py":"Tiāntiān chī mǐfàn, wǒ xiǎng huànhuan kǒuwèi.","vi":"Ngày nào cũng ăn cơm, tôi muốn đổi khẩu vị.","en":"I eat rice every day and want to try something different."}]},"空气":{"en":"air; atmosphere","exs":[{"use":"Danh từ: không khí; 新鲜空气 (không khí trong lành).","ex":"公园里的空气很新鲜。","py":"Gōngyuán lǐ de kōngqì hěn xīnxiān.","vi":"Không khí trong công viên rất trong lành.","en":"The air in the park is very fresh."},{"use":"空气 + 质量/污染: chất lượng, ô nhiễm không khí.","ex":"这个城市的空气质量越来越好了。","py":"Zhège chéngshì de kōngqì zhìliàng yuè lái yuè hǎo le.","vi":"Chất lượng không khí của thành phố này ngày càng tốt.","en":"The air quality of this city is getting better."},{"use":"呼吸空气 / 换空气: hít thở, thay đổi không khí.","ex":"早上起来，先开窗换换空气。","py":"Zǎoshang qǐlái, xiān kāi chuāng huànhuan kōngqì.","vi":"Buổi sáng ngủ dậy, mở cửa sổ cho thoáng khí trước.","en":"When you get up in the morning, first open a window to air the room."},{"use":"Nghĩa bóng: bầu không khí (气氛).","ex":"会议室里的空气一下子紧张起来。","py":"Huìyìshì lǐ de kōngqì yíxiàzi jǐnzhāng qǐlái.","vi":"Không khí trong phòng họp bỗng trở nên căng thẳng.","en":"The atmosphere in the meeting room suddenly became tense."}]},"抽烟":{"en":"to smoke (a cigarette)","exs":[{"use":"Động từ ly hợp (V + O): 抽烟 (hút thuốc).","ex":"我爸爸以前抽烟，现在不抽了。","py":"Wǒ bàba yǐqián chōuyān, xiànzài bù chōu le.","vi":"Bố tôi trước đây hút thuốc, bây giờ không hút nữa.","en":"My dad used to smoke, but he doesn't anymore."},{"use":"Biển cấm: 请不要抽烟 / 禁止抽烟.","ex":"这里不能抽烟，请到外面去。","py":"Zhèlǐ bù néng chōuyān, qǐng dào wàimiàn qù.","vi":"Ở đây không được hút thuốc, xin ra ngoài.","en":"You can't smoke here; please go outside."},{"use":"抽烟 + 对…不好: hại cho…","ex":"抽烟对身体很不好。","py":"Chōuyān duì shēntǐ hěn bù hǎo.","vi":"Hút thuốc rất có hại cho cơ thể.","en":"Smoking is very bad for your health."},{"use":"Hỏi xin phép: 你介意我抽烟吗？","ex":"请问，我可以在这儿抽烟吗？","py":"Qǐngwèn, wǒ kěyǐ zài zhèr chōuyān ma?","vi":"Xin hỏi, tôi có thể hút thuốc ở đây không?","en":"Excuse me, may I smoke here?"}]},"动作":{"en":"movement; action; motion","exs":[{"use":"Danh từ: động tác (của cơ thể): 做动作.","ex":"老师做了一个动作，让我们跟着学。","py":"Lǎoshī zuòle yí ge dòngzuò, ràng wǒmen gēnzhe xué.","vi":"Thầy làm một động tác, bảo chúng tôi làm theo.","en":"The teacher made a movement and had us follow along."},{"use":"动作 + 形容词: 动作很快/慢/标准.","ex":"他跳舞的动作非常漂亮。","py":"Tā tiàowǔ de dòngzuò fēicháng piàoliang.","vi":"Động tác nhảy của anh ấy rất đẹp.","en":"His dance moves are very beautiful."},{"use":"Phân tích động tác khi tập thể thao.","ex":"做运动时，动作要标准，不然容易受伤。","py":"Zuò yùndòng shí, dòngzuò yào biāozhǔn, bùrán róngyì shòushāng.","vi":"Khi tập thể thao, động tác phải chuẩn, không thì dễ bị thương.","en":"When you exercise, your form must be correct or you may get hurt."},{"use":"动作 + 慢点儿: yêu cầu làm chậm.","ex":"你的动作快一点，我们要迟到了。","py":"Nǐ de dòngzuò kuài yìdiǎn, wǒmen yào chídào le.","vi":"Bạn nhanh tay lên một chút, chúng ta sắp muộn rồi.","en":"Hurry up a bit; we're going to be late."}]},"出现":{"en":"to appear; to emerge; to arise","exs":[{"use":"Động từ: xuất hiện (người, vật, hiện tượng).","ex":"他突然出现在门口，吓了我一跳。","py":"Tā tūrán chūxiàn zài ménkǒu, xiàle wǒ yí tiào.","vi":"Anh ấy đột nhiên xuất hiện ở cửa, làm tôi giật mình.","en":"He suddenly appeared at the door and startled me."},{"use":"出现 + vấn đề/triệu chứng: nảy sinh, xuất hiện.","ex":"吃了药以后，他出现了一些反应。","py":"Chīle yào yǐhòu, tā chūxiànle yìxiē fǎnyìng.","vi":"Sau khi uống thuốc, anh ấy xuất hiện một số phản ứng.","en":"After taking the medicine, he had some reactions."},{"use":"出现 + 新…: có cái mới ra đời.","ex":"最近市场上出现了很多新手机。","py":"Zuìjìn shìchǎng shàng chūxiànle hěn duō xīn shǒujī.","vi":"Gần đây trên thị trường xuất hiện rất nhiều điện thoại mới.","en":"Lots of new phones have appeared on the market recently."},{"use":"Phủ định: 没出现 / 不要出现.","ex":"希望这样的错误不要再出现。","py":"Xīwàng zhèyàng de cuòwù búyào zài chūxiàn.","vi":"Hy vọng những sai sót như vậy không xuất hiện nữa.","en":"I hope mistakes like this won't happen again."}]},"来不及":{"en":"not have enough time to; too late to; cannot make it in time","exs":[{"use":"来不及 + động từ: không kịp làm gì","ex":"时间太紧，我来不及吃早饭。","py":"Shíjiān tài jǐn, wǒ láibují chī zǎofàn.","vi":"Thời gian quá gấp, tôi không kịp ăn sáng.","en":"Time was so tight that I didn't have time to eat breakfast."},{"use":"来不及了 đứng cuối câu: đã muộn, không kịp nữa","ex":"快走吧，再不走就来不及了。","py":"Kuài zǒu ba, zài bù zǒu jiù láibují le.","vi":"Đi nhanh đi, không đi nữa là không kịp đâu.","en":"Hurry up, if we don't leave now we'll be too late."},{"use":"来不及 chỉ việc đã muộn để làm gì (hối hận, sửa chữa)","ex":"现在后悔已经来不及了。","py":"Xiànzài hòuhuǐ yǐjīng láibují le.","vi":"Bây giờ hối hận thì đã muộn rồi.","en":"It's too late to regret it now."},{"use":"来不及 + V + 完: không kịp làm xong","ex":"作业太多，我来不及做完。","py":"Zuòyè tài duō, wǒ láibují zuò wán.","vi":"Bài tập nhiều quá, tôi không kịp làm xong.","en":"There's too much homework; I can't finish it in time."}]},"反对":{"en":"to oppose; to object to; opposition","exs":[{"use":"反对 + tân ngữ: phản đối điều gì","ex":"父母反对我一个人去旅行。","py":"Fùmǔ fǎnduì wǒ yí gè rén qù lǚxíng.","vi":"Bố mẹ phản đối việc tôi đi du lịch một mình.","en":"My parents object to me traveling alone."},{"use":"没有人反对: không ai phản đối (dùng để nói đồng thuận)","ex":"没有人反对这个计划。","py":"Méiyǒu rén fǎnduì zhège jìhuà.","vi":"Không ai phản đối kế hoạch này.","en":"Nobody opposes this plan."},{"use":"反对 + 在…V: phản đối việc làm gì ở đâu","ex":"我反对在教室里抽烟。","py":"Wǒ fǎnduì zài jiàoshì lǐ chōuyān.","vi":"Tôi phản đối việc hút thuốc trong lớp học.","en":"I'm against smoking in the classroom."},{"use":"làm danh từ: sự phản đối (他的反对)","ex":"他的反对没有用，大家还是决定去了。","py":"Tā de fǎnduì méiyǒu yòng, dàjiā háishi juédìng qù le.","vi":"Sự phản đối của anh ấy vô ích, mọi người vẫn quyết định đi.","en":"His objection was useless; everyone still decided to go."}]},"担心":{"en":"to worry; to be anxious about","exs":[{"use":"担心 + tân ngữ: lo lắng về ai/việc gì","ex":"妈妈很担心我的身体。","py":"Māma hěn dānxīn wǒ de shēntǐ.","vi":"Mẹ rất lo lắng cho sức khỏe của tôi.","en":"Mom is very worried about my health."},{"use":"担心 + 会 + V: lo rằng sẽ…","ex":"我担心明天会下雨。","py":"Wǒ dānxīn míngtiān huì xià yǔ.","vi":"Tôi lo ngày mai sẽ mưa.","en":"I'm worried it will rain tomorrow."},{"use":"别担心 / 不用担心: câu an ủi","ex":"别担心，我已经准备好了。","py":"Bié dānxīn, wǒ yǐjīng zhǔnbèi hǎo le.","vi":"Đừng lo, tôi đã chuẩn bị xong rồi.","en":"Don't worry, I'm already prepared."},{"use":"为…担心: lo lắng vì…","ex":"大家都在为他的考试担心。","py":"Dàjiā dōu zài wèi tā de kǎoshì dānxīn.","vi":"Mọi người đều đang lo cho kỳ thi của anh ấy.","en":"Everyone is worried about his exam."}]},"身体健康":{"en":"good health; to be healthy (in body)","exs":[{"use":"lời chúc: 祝你身体健康","ex":"祝你身体健康！","py":"Zhù nǐ shēntǐ jiànkāng!","vi":"Chúc bạn sức khỏe!","en":"Wishing you good health!"},{"use":"làm chủ ngữ + so sánh 比…更重要","ex":"身体健康比赚钱更重要。","py":"Shēntǐ jiànkāng bǐ zhuànqián gèng zhòngyào.","vi":"Sức khỏe quan trọng hơn kiếm tiền.","en":"Good health is more important than making money."},{"use":"为了身体健康: vì mục đích sức khỏe","ex":"为了身体健康，他每天早上都去跑步。","py":"Wèile shēntǐ jiànkāng, tā měi tiān zǎoshang dōu qù pǎobù.","vi":"Vì sức khỏe, sáng nào anh ấy cũng đi chạy bộ.","en":"For the sake of his health, he goes running every morning."},{"use":"希望 + ai đó + 身体健康","ex":"爷爷最希望家人身体健康。","py":"Yéye zuì xīwàng jiārén shēntǐ jiànkāng.","vi":"Ông nội mong nhất là người nhà khỏe mạnh.","en":"Grandpa most hopes his family stays healthy."}]},"大夫":{"en":"doctor (colloquial)","exs":[{"use":"gọi bác sĩ khi khám bệnh: 大夫，……","ex":"大夫，我头疼得很厉害。","py":"Dàifu, wǒ tóuténg de hěn lìhai.","vi":"Bác sĩ ơi, tôi đau đầu dữ lắm.","en":"Doctor, I have a terrible headache."},{"use":"看大夫: đi khám bác sĩ","ex":"我去医院看大夫。","py":"Wǒ qù yīyuàn kàn dàifu.","vi":"Tôi đến bệnh viện khám bác sĩ.","en":"I'm going to the hospital to see a doctor."},{"use":"大夫说…: lời dặn của bác sĩ","ex":"大夫说我要多喝水，多休息。","py":"Dàifu shuō wǒ yào duō hē shuǐ, duō xiūxi.","vi":"Bác sĩ bảo tôi phải uống nhiều nước, nghỉ ngơi nhiều.","en":"The doctor said I should drink more water and rest more."},{"use":"量词 位 + 大夫: chỉ nghề nghiệp","ex":"她爸爸是一位有经验的大夫。","py":"Tā bàba shì yí wèi yǒu jīngyàn de dàifu.","vi":"Bố cô ấy là một bác sĩ có kinh nghiệm.","en":"Her father is an experienced doctor."}]},"电脑":{"en":"computer","exs":[{"use":"量词 台: 一台电脑","ex":"这台电脑又轻又便宜。","py":"Zhè tái diànnǎo yòu qīng yòu piányi.","vi":"Chiếc máy tính này vừa nhẹ vừa rẻ.","en":"This computer is both light and cheap."},{"use":"电脑坏了: hỏng máy","ex":"我的电脑坏了，明天要拿去修。","py":"Wǒ de diànnǎo huài le, míngtiān yào ná qù xiū.","vi":"Máy tính của tôi hỏng rồi, mai phải mang đi sửa.","en":"My computer is broken; I need to take it for repair tomorrow."},{"use":"用电脑 + V: dùng máy tính làm gì","ex":"他每天用电脑工作八个小时。","py":"Tā měi tiān yòng diànnǎo gōngzuò bā gè xiǎoshí.","vi":"Mỗi ngày anh ấy dùng máy tính làm việc tám tiếng.","en":"He works on the computer eight hours a day."},{"use":"在电脑上: trên máy tính","ex":"他喜欢在电脑上看电影。","py":"Tā xǐhuan zài diànnǎo shàng kàn diànyǐng.","vi":"Anh ấy thích xem phim trên máy tính.","en":"He likes watching movies on the computer."}]},"前面":{"en":"front; ahead; in front of; above (earlier part)","exs":[{"use":"danh từ phương vị: 地点 + 前面 + 有…","ex":"学校前面有一家书店。","py":"Xuéxiào qiánmiàn yǒu yì jiā shūdiàn.","vi":"Phía trước trường có một hiệu sách.","en":"There is a bookstore in front of the school."},{"use":"前面的 + N: định ngữ","ex":"前面的那个人是我的老师。","py":"Qiánmiàn de nà ge rén shì wǒ de lǎoshī.","vi":"Người phía trước kia là thầy giáo của tôi.","en":"The person up ahead is my teacher."},{"use":"在 + N + 前面: ở phía trước…","ex":"车停在房子前面。","py":"Chē tíng zài fángzi qiánmiàn.","vi":"Xe đỗ ở phía trước ngôi nhà.","en":"The car is parked in front of the house."},{"use":"往前面 + V: hướng về phía trước (chỉ đường)","ex":"一直往前面走，就能看到地铁站。","py":"Yìzhí wǎng qiánmiàn zǒu, jiù néng kàndào dìtiězhàn.","vi":"Cứ đi thẳng về phía trước là thấy ga tàu điện ngầm.","en":"Keep going straight ahead and you'll see the subway station."},{"use":"nghĩa 2: phần đã nói ở trên (văn bản, lời nói)","ex":"前面说过的话，请大家记住。","py":"Qiánmiàn shuō guo de huà, qǐng dàjiā jìzhù.","vi":"Những điều đã nói ở trên, mong mọi người ghi nhớ.","en":"Please remember what was said earlier."}]},"小时":{"en":"hour","exs":[{"use":"số + 个 + 小时: số giờ (thời lượng)","ex":"我每天睡八个小时。","py":"Wǒ měi tiān shuì bā gè xiǎoshí.","vi":"Mỗi ngày tôi ngủ tám tiếng.","en":"I sleep eight hours a day."},{"use":"两个半小时: hai tiếng rưỡi","ex":"飞机要飞两个半小时。","py":"Fēijī yào fēi liǎng gè bàn xiǎoshí.","vi":"Máy bay phải bay hai tiếng rưỡi.","en":"The flight takes two and a half hours."},{"use":"V + 了 + số + 个小时: bổ ngữ thời lượng","ex":"他等了你三个小时。","py":"Tā děng le nǐ sān gè xiǎoshí.","vi":"Anh ấy đã đợi bạn ba tiếng.","en":"He waited for you for three hours."},{"use":"每小时: mỗi giờ (tốc độ)","ex":"这辆车每小时跑一百公里。","py":"Zhè liàng chē měi xiǎoshí pǎo yì bǎi gōnglǐ.","vi":"Chiếc xe này chạy một trăm cây số mỗi giờ.","en":"This car goes 100 kilometers per hour."}]},"休息":{"en":"to rest; to take a break; rest","exs":[{"use":"休息 + 需要: nghỉ ngơi","ex":"眼睛需要休息。","py":"Yǎnjing xūyào xiūxi.","vi":"Mắt cần nghỉ ngơi.","en":"Your eyes need rest."},{"use":"休息一下 = nghỉ một chút","ex":"工作累了就休息一下。","py":"Gōngzuò lèi le jiù xiūxi yíxià.","vi":"Làm việc mệt thì nghỉ một chút.","en":"If you get tired from work, take a short break."},{"use":"休息 ở nhà, cuối tuần","ex":"我周末在家休息，哪儿也不去。","py":"Wǒ zhōumò zài jiā xiūxi, nǎr yě bú qù.","vi":"Cuối tuần tôi ở nhà nghỉ ngơi, không đi đâu cả.","en":"I rest at home on weekends and don't go anywhere."},{"use":"好好儿休息: nghỉ ngơi cho tốt (khuyên bảo)","ex":"你病了，应该好好儿休息。","py":"Nǐ bìng le, yīnggāi hǎohāor xiūxi.","vi":"Bạn bị bệnh rồi, nên nghỉ ngơi cho tốt.","en":"You're sick, so you should get plenty of rest."},{"use":"休息时间: dùng như định ngữ/danh từ","ex":"休息时间只有十分钟。","py":"Xiūxi shíjiān zhǐyǒu shí fēnzhōng.","vi":"Thời gian nghỉ chỉ có mười phút.","en":"The break time is only ten minutes."}]},"远处":{"en":"distance; a faraway place","exs":[{"use":"远处 + 有 + N: ở xa có…","ex":"远处有一座山。","py":"Yuǎnchù yǒu yí zuò shān.","vi":"Ở xa có một ngọn núi.","en":"There is a mountain in the distance."},{"use":"从远处 + V: từ xa nhìn…","ex":"从远处看，这座城市像一幅画。","py":"Cóng yuǎnchù kàn, zhè zuò chéngshì xiàng yì fú huà.","vi":"Nhìn từ xa, thành phố này như một bức tranh.","en":"Seen from afar, this city looks like a painting."},{"use":"远处传来…: từ xa vọng lại (âm thanh)","ex":"远处传来了音乐声。","py":"Yuǎnchù chuánlái le yīnyuè shēng.","vi":"Từ xa vọng lại tiếng nhạc.","en":"Music drifted over from far away."},{"use":"指着远处的 + N: chỉ vào nơi xa","ex":"他指着远处的那座桥说：“我家就在那儿。”","py":"Tā zhǐ zhe yuǎnchù de nà zuò qiáo shuō: “Wǒ jiā jiù zài nàr.”","vi":"Anh ấy chỉ vào cây cầu phía xa nói: “Nhà tôi ở ngay đó.”","en":"Pointing at the bridge in the distance, he said, “My home is right there.”"}]},"植物":{"en":"plant; vegetation","exs":[{"use":"danh từ chung: 很多种植物","ex":"这个公园里有很多种植物。","py":"Zhège gōngyuán lǐ yǒu hěn duō zhǒng zhíwù.","vi":"Trong công viên này có rất nhiều loại thực vật.","en":"There are many kinds of plants in this park."},{"use":"植物 làm chủ ngữ: nhu cầu sinh trưởng","ex":"植物需要阳光和水才能长大。","py":"Zhíwù xūyào yángguāng hé shuǐ cái néng zhǎngdà.","vi":"Thực vật cần ánh nắng và nước mới lớn được.","en":"Plants need sunlight and water to grow."},{"use":"量词 盆: trồng cây cảnh","ex":"我在阳台上种了几盆植物。","py":"Wǒ zài yángtái shàng zhòng le jǐ pén zhíwù.","vi":"Tôi trồng mấy chậu cây trên ban công.","en":"I planted a few pots of plants on the balcony."},{"use":"động vật và thực vật: 动物和植物","ex":"动物和植物都是生命。","py":"Dòngwù hé zhíwù dōu shì shēngmìng.","vi":"Động vật và thực vật đều là sinh mệnh.","en":"Animals and plants are all living things."}]},"不好":{"en":"not good; bad; unwell; hard to (do)","exs":[{"use":"不好 + (adj): không tốt (thời tiết…)","ex":"今天天气不好，不要出去了。","py":"Jīntiān tiānqì bù hǎo, búyào chūqù le.","vi":"Hôm nay thời tiết xấu, đừng ra ngoài nữa.","en":"The weather is bad today, so don't go out."},{"use":"V + 得 + 不好: làm không tốt","ex":"我最近睡得不好。","py":"Wǒ zuìjìn shuì de bù hǎo.","vi":"Dạo này tôi ngủ không ngon.","en":"I haven't been sleeping well lately."},{"use":"身体不好: sức khỏe yếu","ex":"他身体不好，不能喝酒。","py":"Tā shēntǐ bù hǎo, bù néng hē jiǔ.","vi":"Sức khỏe anh ấy không tốt, không được uống rượu.","en":"He's in poor health and can't drink alcohol."},{"use":"不好意思: xin lỗi, ngại quá","ex":"不好意思，我来晚了。","py":"Bù hǎoyìsi, wǒ láiwǎn le.","vi":"Xin lỗi, tôi đến muộn.","en":"Sorry, I'm late."},{"use":"不好 + V: khó/không tiện làm gì","ex":"这个字不好写。","py":"Zhège zì bù hǎo xiě.","vi":"Chữ này khó viết.","en":"This character is hard to write."}]},"研究":{"en":"to research; to study; to discuss; research","exs":[{"use":"研究 + vấn đề / lĩnh vực","ex":"他们正在研究这个问题。","py":"Tāmen zhèngzài yánjiū zhège wèntí.","vi":"Họ đang nghiên cứu vấn đề này.","en":"They are studying this problem."},{"use":"làm danh từ: 一项研究","ex":"这项研究花了五年时间。","py":"Zhè xiàng yánjiū huā le wǔ nián shíjiān.","vi":"Nghiên cứu này mất năm năm.","en":"This research took five years."},{"use":"研究研究 / 研究一下: bàn bạc, xem xét","ex":"我们研究一下再决定。","py":"Wǒmen yánjiū yíxià zài juédìng.","vi":"Chúng ta bàn bạc xem xét một chút rồi hãy quyết định.","en":"Let's look into it a bit before deciding."},{"use":"研究 + môn học / lĩnh vực chuyên môn","ex":"他在大学研究中国历史。","py":"Tā zài dàxué yánjiū Zhōngguó lìshǐ.","vi":"Anh ấy nghiên cứu lịch sử Trung Quốc ở đại học.","en":"He studies Chinese history at the university."}]},"静坐":{"en":"to sit quietly; to meditate","exs":[{"use":"静坐 + thời gian: ngồi yên bao lâu","ex":"他每天早上静坐十分钟。","py":"Tā měi tiān zǎoshang jìngzuò shí fēnzhōng.","vi":"Mỗi sáng anh ấy ngồi yên mười phút.","en":"He sits quietly for ten minutes every morning."},{"use":"静坐可以…: lợi ích của việc ngồi thiền","ex":"静坐可以让人放松心情。","py":"Jìngzuò kěyǐ ràng rén fàngsōng xīnqíng.","vi":"Ngồi yên tĩnh tâm giúp con người thư giãn.","en":"Sitting quietly can help people relax."},{"use":"在 + nơi + 静坐","ex":"同学们在教室里静坐，等老师来。","py":"Tóngxuémen zài jiàoshì lǐ jìngzuò, děng lǎoshī lái.","vi":"Các bạn ngồi yên trong lớp, đợi thầy cô đến.","en":"The students sat quietly in the classroom waiting for the teacher."},{"use":"一个人静坐: ngồi một mình thư thái","ex":"她喜欢一个人在湖边静坐。","py":"Tā xǐhuan yí gè rén zài húbiān jìngzuò.","vi":"Cô ấy thích một mình ngồi yên bên hồ.","en":"She likes to sit quietly by the lake alone."}]},"超过":{"en":"to exceed; to surpass; to overtake","exs":[{"use":"超过 + số lượng: vượt quá","ex":"今天的温度超过三十度。","py":"Jīntiān de wēndù chāoguò sānshí dù.","vi":"Nhiệt độ hôm nay vượt quá ba mươi độ.","en":"Today's temperature is over thirty degrees."},{"use":"超过 + xe/người: vượt qua","ex":"那辆车超过了前面的公共汽车。","py":"Nà liàng chē chāoguò le qiánmiàn de gōnggòng qìchē.","vi":"Chiếc xe đó vượt qua xe buýt phía trước.","en":"That car overtook the bus ahead."},{"use":"不要超过 + số: đừng quá…","ex":"每天看手机不要超过两个小时。","py":"Měi tiān kàn shǒujī búyào chāoguò liǎng gè xiǎoshí.","vi":"Mỗi ngày đừng xem điện thoại quá hai tiếng.","en":"Don't look at your phone for more than two hours a day."},{"use":"超过 + người: giỏi hơn, vượt hơn (so sánh)","ex":"他的成绩已经超过了我。","py":"Tā de chéngjì yǐjīng chāoguò le wǒ.","vi":"Thành tích của anh ấy đã vượt tôi rồi.","en":"His grades have already surpassed mine."}]},"久坐":{"en":"to sit for a long time; prolonged sitting","exs":[{"use":"làm chủ ngữ: 久坐对…不好","ex":"久坐对身体不好。","py":"Jiǔzuò duì shēntǐ bù hǎo.","vi":"Ngồi lâu không tốt cho sức khỏe.","en":"Sitting for long periods is bad for your health."},{"use":"久坐 trong công việc","ex":"工作时间久坐，每小时要站起来动一动。","py":"Gōngzuò shíjiān jiǔzuò, měi xiǎoshí yào zhàn qǐlái dòng yi dòng.","vi":"Làm việc ngồi lâu thì mỗi giờ phải đứng dậy vận động một chút.","en":"If you sit a long time at work, stand up and move every hour."},{"use":"久坐的人: định ngữ chỉ người","ex":"医生提醒我们，久坐的人容易腰疼。","py":"Yīshēng tíxǐng wǒmen, jiǔzuò de rén róngyì yāo téng.","vi":"Bác sĩ nhắc rằng người ngồi lâu dễ bị đau lưng.","en":"The doctor warns that people who sit for long are prone to back pain."},{"use":"常常久坐: thói quen ngồi nhiều","ex":"办公室的人常常久坐，所以应该多运动。","py":"Bàngōngshì de rén chángcháng jiǔzuò, suǒyǐ yīnggāi duō yùndòng.","vi":"Nhân viên văn phòng thường ngồi lâu nên cần vận động nhiều.","en":"Office workers often sit for long hours, so they should exercise more."}]},"起来":{"en":"to get up; (directional complement) up; starting to; (seems) when…","exs":[{"use":"bổ ngữ xu hướng: V + 起来 (hướng lên)","ex":"请大家站起来。","py":"Qǐng dàjiā zhàn qǐlái.","vi":"Mời mọi người đứng dậy.","en":"Everyone, please stand up."},{"use":"V + 起来: bắt đầu một hành động / trạng thái","ex":"听到这个笑话，大家都笑起来了。","py":"Tīngdào zhège xiàohua, dàjiā dōu xiào qǐlái le.","vi":"Nghe câu chuyện cười, mọi người đều bật cười.","en":"Hearing the joke, everyone started laughing."},{"use":"看/听/吃 + 起来 + adj: nhìn/nghe có vẻ","ex":"这个菜看起来很好吃。","py":"Zhège cài kàn qǐlái hěn hǎochī.","vi":"Món này trông có vẻ rất ngon.","en":"This dish looks delicious."},{"use":"động từ độc lập: thức dậy, ngồi dậy","ex":"他早上六点就起来了。","py":"Tā zǎoshang liù diǎn jiù qǐlái le.","vi":"Sáng sáu giờ anh ấy đã dậy rồi.","en":"He got up at six in the morning."},{"use":"想起来: nhớ ra","ex":"我想起来了，钥匙在桌子上。","py":"Wǒ xiǎng qǐlái le, yàoshi zài zhuōzi shàng.","vi":"Tôi nhớ ra rồi, chìa khóa ở trên bàn.","en":"I remember now; the keys are on the table."}]},"午饭":{"en":"lunch","exs":[{"use":"吃午饭: ăn trưa","ex":"中午我们一起去吃午饭吧。","py":"Zhōngwǔ wǒmen yìqǐ qù chī wǔfàn ba.","vi":"Trưa nay chúng ta cùng đi ăn trưa nhé.","en":"Let's go have lunch together at noon."},{"use":"做午饭: nấu cơm trưa","ex":"妈妈在做午饭。","py":"Māma zài zuò wǔfàn.","vi":"Mẹ đang nấu cơm trưa.","en":"Mom is making lunch."},{"use":"吃完午饭: sau khi ăn trưa","ex":"吃完午饭，我习惯睡十五分钟。","py":"Chī wán wǔfàn, wǒ xíguàn shuì shíwǔ fēnzhōng.","vi":"Ăn trưa xong, tôi quen ngủ mười lăm phút.","en":"After lunch, I like to nap for fifteen minutes."},{"use":"午饭时间: định ngữ","ex":"午饭时间到了，大家都去餐厅了。","py":"Wǔfàn shíjiān dào le, dàjiā dōu qù cāntīng le.","vi":"Đến giờ ăn trưa, mọi người đều đi nhà ăn.","en":"It's lunchtime, and everyone has gone to the cafeteria."}]},"附近":{"en":"nearby; vicinity","exs":[{"use":"hỏi địa điểm: 这附近有…吗？","ex":"这附近有银行吗？","py":"Zhè fùjìn yǒu yínháng ma?","vi":"Gần đây có ngân hàng không?","en":"Is there a bank nearby?"},{"use":"在 + N + 附近: gần…","ex":"我家在地铁站附近。","py":"Wǒ jiā zài dìtiězhàn fùjìn.","vi":"Nhà tôi ở gần ga tàu điện ngầm.","en":"My home is near the subway station."},{"use":"附近的 + N: định ngữ","ex":"我常去附近的超市买菜。","py":"Wǒ cháng qù fùjìn de chāoshì mǎi cài.","vi":"Tôi hay đến siêu thị gần đây mua rau.","en":"I often buy groceries at the nearby supermarket."},{"use":"住在附近: sống gần","ex":"我就住在附近，走路五分钟就到。","py":"Wǒ jiù zhù zài fùjìn, zǒulù wǔ fēnzhōng jiù dào.","vi":"Tôi sống ngay gần đây, đi bộ năm phút là tới.","en":"I live nearby; it's a five-minute walk."}]},"公园":{"en":"park","exs":[{"use":"去公园 + V: đi công viên làm gì","ex":"周末我们带孩子去公园玩。","py":"Zhōumò wǒmen dài háizi qù gōngyuán wán.","vi":"Cuối tuần chúng tôi đưa con đi chơi công viên.","en":"On weekends we take the kids to the park to play."},{"use":"公园里有…: ở trong công viên","ex":"公园里有很多花和树。","py":"Gōngyuán lǐ yǒu hěn duō huā hé shù.","vi":"Trong công viên có nhiều hoa và cây.","en":"There are lots of flowers and trees in the park."},{"use":"在公园里 + V: hoạt động buổi sáng","ex":"老人们早上在公园里打太极拳。","py":"Lǎorénmen zǎoshang zài gōngyuán lǐ dǎ tàijíquán.","vi":"Buổi sáng các cụ tập thái cực quyền trong công viên.","en":"In the morning, the elderly practice tai chi in the park."},{"use":"离…近: khoảng cách","ex":"这个公园离我家很近。","py":"Zhège gōngyuán lí wǒ jiā hěn jìn.","vi":"Công viên này rất gần nhà tôi.","en":"This park is very close to my home."}]},"散散步":{"en":"to take a stroll (reduplicated form of 散步)","exs":[{"use":"V重叠 (AAB): đi dạo một chút, nhẹ nhàng","ex":"晚饭后，我们去外面散散步吧。","py":"Wǎnfàn hòu, wǒmen qù wàimiàn sànsànbù ba.","vi":"Sau bữa tối, chúng ta ra ngoài đi dạo nhé.","en":"After dinner, let's go out for a stroll."},{"use":"就 + 出去散散步: gợi ý thư giãn","ex":"你累了就出去散散步，放松一下。","py":"Nǐ lèi le jiù chūqù sànsànbù, fàngsōng yíxià.","vi":"Mệt thì ra ngoài đi dạo cho thư giãn.","en":"If you're tired, go for a walk and relax."},{"use":"散散步，聊聊天: liệt kê hoạt động nhàn nhã","ex":"爷爷每天在公园里散散步，和朋友聊聊天。","py":"Yéye měi tiān zài gōngyuán lǐ sànsànbù, hé péngyou liáoliao tiān.","vi":"Ông ngày nào cũng đi dạo trong công viên, trò chuyện với bạn bè.","en":"Grandpa takes a stroll in the park every day and chats with friends."},{"use":"V重叠 sau điều kiện thời gian","ex":"吃饱了以后散散步对身体好。","py":"Chī bǎo le yǐhòu sànsànbù duì shēntǐ hǎo.","vi":"Ăn no xong đi dạo một chút tốt cho sức khỏe.","en":"Taking a stroll after eating is good for your health."}]},"草":{"en":"grass; lawn; herb","exs":[{"use":"danh từ chỉ cỏ","ex":"草绿了。","py":"Cǎo lǜ le.","vi":"Cỏ xanh rồi.","en":"The grass has turned green."},{"use":"吃草: ăn cỏ (động vật)","ex":"牛喜欢吃草。","py":"Niú xǐhuan chī cǎo.","vi":"Bò thích ăn cỏ.","en":"Cows like to eat grass."},{"use":"草地: bãi cỏ","ex":"孩子们坐在草地上玩游戏。","py":"Háizimen zuò zài cǎodì shàng wán yóuxì.","vi":"Bọn trẻ ngồi trên bãi cỏ chơi trò chơi.","en":"The children sit on the lawn playing games."},{"use":"花草: hoa và cỏ; mùa xuân","ex":"春天来了，花和草都长出来了。","py":"Chūntiān lái le, huā hé cǎo dōu zhǎng chūlái le.","vi":"Xuân đến rồi, hoa và cỏ đều nhú lên.","en":"Spring has come, and flowers and grass are sprouting."},{"use":"biển báo: 不要踩草","ex":"请不要踩草。","py":"Qǐng búyào cǎi cǎo.","vi":"Xin đừng giẫm lên cỏ.","en":"Please don't step on the grass."}]},"生命":{"en":"life; living being","exs":[{"use":"danh từ: sự sống, quý giá","ex":"生命很宝贵。","py":"Shēngmìng hěn bǎoguì.","vi":"Sự sống rất quý giá.","en":"Life is precious."},{"use":"保护生命: bảo vệ tính mạng","ex":"医生的工作是保护人的生命。","py":"Yīshēng de gōngzuò shì bǎohù rén de shēngmìng.","vi":"Công việc của bác sĩ là bảo vệ sinh mạng con người.","en":"A doctor's job is to protect human life."},{"use":"没有…就没有生命","ex":"没有水就没有生命。","py":"Méiyǒu shuǐ jiù méiyǒu shēngmìng.","vi":"Không có nước thì không có sự sống.","en":"Without water there is no life."},{"use":"生命在于运动: thành ngữ","ex":"俗话说，生命在于运动。","py":"Súhuà shuō, shēngmìng zàiyú yùndòng.","vi":"Tục ngữ nói, sự sống nằm ở vận động.","en":"As the saying goes, life lies in movement."},{"use":"生命的意义: ý nghĩa cuộc sống","ex":"这本书让我重新认识了生命的意义。","py":"Zhè běn shū ràng wǒ chóngxīn rènshi le shēngmìng de yìyì.","vi":"Cuốn sách này giúp tôi nhận thức lại ý nghĩa của cuộc sống.","en":"This book made me rethink the meaning of life."}]},"花":{"en":"flower; to spend (money/time)","exs":[{"use":"danh từ: hoa (nở)","ex":"花开了。","py":"Huā kāi le.","vi":"Hoa nở rồi.","en":"The flowers have bloomed."},{"use":"给花浇水: tưới hoa","ex":"她每天都给花浇水。","py":"Tā měi tiān dōu gěi huā jiāo shuǐ.","vi":"Ngày nào cô ấy cũng tưới hoa.","en":"She waters the flowers every day."},{"use":"量词 束 + 花","ex":"妈妈今天买了一束红色的花。","py":"Māma jīntiān mǎi le yí shù hóngsè de huā.","vi":"Hôm nay mẹ mua một bó hoa màu đỏ.","en":"Mom bought a bunch of red flowers today."},{"use":"nghĩa 2 (động từ, huā): tiêu (tiền)","ex":"买这个手机花了我三千块钱。","py":"Mǎi zhège shǒujī huā le wǒ sānqiān kuài qián.","vi":"Mua chiếc điện thoại này tốn của tôi ba nghìn tệ.","en":"This phone cost me three thousand yuan."},{"use":"nghĩa 2: 花时间 = tốn thời gian","ex":"学汉语要花很多时间。","py":"Xué Hànyǔ yào huā hěn duō shíjiān.","vi":"Học tiếng Trung phải tốn nhiều thời gian.","en":"Learning Chinese takes a lot of time."}]},"缺少":{"en":"to lack; to be short of","exs":[{"use":"缺少 + danh từ","ex":"这里缺少水。","py":"Zhèlǐ quēshǎo shuǐ.","vi":"Ở đây thiếu nước.","en":"There is a lack of water here."},{"use":"缺少 + 睡眠 (thiếu ngủ)","ex":"孩子缺少睡眠，上课容易没精神。","py":"Háizi quēshǎo shuìmián, shàngkè róngyì méi jīngshen.","vi":"Trẻ thiếu ngủ nên lên lớp dễ uể oải.","en":"Kids who lack sleep easily feel drained in class."},{"use":"缺少 + 经验 (thiếu kinh nghiệm)","ex":"他很聪明，只是缺少经验。","py":"Tā hěn cōngming, zhǐshì quēshǎo jīngyàn.","vi":"Anh ấy rất thông minh, chỉ là thiếu kinh nghiệm.","en":"He's very smart, just lacking in experience."},{"use":"不可缺少: không thể thiếu","ex":"水是生活中不可缺少的东西。","py":"Shuǐ shì shēnghuó zhōng bùkě quēshǎo de dōngxi.","vi":"Nước là thứ không thể thiếu trong cuộc sống.","en":"Water is indispensable in life."}]},"有关":{"en":"to be related to; concerning","exs":[{"use":"跟/和…有关: liên quan đến","ex":"这件事跟你的工作有关。","py":"Zhè jiàn shì gēn nǐ de gōngzuò yǒuguān.","vi":"Việc này có liên quan đến công việc của bạn.","en":"This matter is related to your work."},{"use":"有关 + N (làm định ngữ): về…","ex":"我想看有关中国文化的书。","py":"Wǒ xiǎng kàn yǒuguān Zhōngguó wénhuà de shū.","vi":"Tôi muốn đọc sách về văn hóa Trung Quốc.","en":"I want to read books about Chinese culture."},{"use":"与…有关: trang trọng","ex":"睡眠不好与压力有关。","py":"Shuìmián bù hǎo yǔ yālì yǒuguān.","vi":"Ngủ không ngon có liên quan đến áp lực.","en":"Poor sleep is related to stress."},{"use":"有关部门: cơ quan liên quan","ex":"有关部门正在检查这件事。","py":"Yǒuguān bùmén zhèngzài jiǎnchá zhè jiàn shì.","vi":"Cơ quan liên quan đang kiểm tra việc này.","en":"The relevant department is looking into this matter."}]},"穿":{"en":"to wear; to put on; to pass through","exs":[{"use":"穿 + quần áo: mặc","ex":"今天很冷，记得多穿一点儿。","py":"Jīntiān hěn lěng, jìde duō chuān yìdiǎnr.","vi":"Hôm nay lạnh, nhớ mặc thêm một chút.","en":"It's cold today; remember to wear more."},{"use":"穿 + 裙子/衣服: mặc (kèm lượng từ)","ex":"她今天穿了一条红色的裙子。","py":"Tā jīntiān chuān le yì tiáo hóngsè de qúnzi.","vi":"Hôm nay cô ấy mặc một chiếc váy đỏ.","en":"She's wearing a red skirt today."},{"use":"穿上 + giày dép: xỏ, mang","ex":"进门请穿上拖鞋。","py":"Jìn mén qǐng chuānshàng tuōxié.","vi":"Vào cửa xin hãy xỏ dép đi trong nhà.","en":"Please put on slippers when you come in."},{"use":"nghĩa 2: 穿过 = xuyên qua, băng qua","ex":"我们穿过公园去地铁站。","py":"Wǒmen chuānguò gōngyuán qù dìtiězhàn.","vi":"Chúng tôi băng qua công viên đến ga tàu điện ngầm.","en":"We cut through the park to the subway station."}]},"只要":{"en":"as long as; provided that","exs":[{"use":"只要…就…: chỉ cần… thì…","ex":"只要努力，就会进步。","py":"Zhǐyào nǔlì, jiù huì jìnbù.","vi":"Chỉ cần cố gắng thì sẽ tiến bộ.","en":"As long as you work hard, you'll improve."},{"use":"只要 + điều kiện, 就 + kết quả","ex":"只要你有时间，我们就见面。","py":"Zhǐyào nǐ yǒu shíjiān, wǒmen jiù jiànmiàn.","vi":"Chỉ cần bạn có thời gian, chúng ta sẽ gặp nhau.","en":"As long as you have time, we'll meet."},{"use":"只要不…就…: chỉ cần không…","ex":"只要不下雨，我们就去爬山。","py":"Zhǐyào bú xià yǔ, wǒmen jiù qù páshān.","vi":"Chỉ cần không mưa, chúng ta sẽ đi leo núi.","en":"As long as it doesn't rain, we'll go hiking."},{"use":"只要有…都…: điều kiện + 都","ex":"只要有网络，在哪儿都可以工作。","py":"Zhǐyào yǒu wǎngluò, zài nǎr dōu kěyǐ gōngzuò.","vi":"Chỉ cần có mạng, ở đâu cũng làm việc được.","en":"As long as there's internet, I can work anywhere."}]},"到处":{"en":"everywhere; all over; in all places","exs":[{"use":"到处 + 都是 + N: khắp nơi đều là","ex":"这里到处都是花。","py":"Zhèlǐ dàochù dōu shì huā.","vi":"Ở đây đâu đâu cũng có hoa.","en":"There are flowers everywhere here."},{"use":"到处 + V: khắp nơi làm gì (tìm kiếm)","ex":"我到处找钥匙，也没找到。","py":"Wǒ dàochù zhǎo yàoshi, yě méi zhǎodào.","vi":"Tôi tìm chìa khóa khắp nơi mà không thấy.","en":"I looked everywhere for my keys but couldn't find them."},{"use":"V + 得 + 到处都是: bừa bãi","ex":"他把东西扔得到处都是。","py":"Tā bǎ dōngxi rēng de dàochù dōu shì.","vi":"Anh ấy vứt đồ bừa bãi khắp nơi.","en":"He threw his things all over the place."},{"use":"到处 + 旅行: đi khắp nơi","ex":"他喜欢到处旅行。","py":"Tā xǐhuan dàochù lǚxíng.","vi":"Anh ấy thích đi du lịch khắp nơi.","en":"He likes traveling all over."}]},"而":{"en":"and; but; yet; and yet (conjunction)","exs":[{"use":"nối hai vế: bổ sung/đối lập nhẹ","ex":"他很努力，而结果也很好。","py":"Tā hěn nǔlì, ér jiéguǒ yě hěn hǎo.","vi":"Anh ấy rất nỗ lực, và kết quả cũng tốt.","en":"He works hard, and the results are good too."},{"use":"而且: hơn nữa","ex":"这个手机便宜，而且很好用。","py":"Zhège shǒujī piányi, érqiě hěn hǎoyòng.","vi":"Chiếc điện thoại này rẻ, hơn nữa còn dễ dùng.","en":"This phone is cheap and also easy to use."},{"use":"A 而不是 B: A chứ không phải B","ex":"我要的是红色的，而不是白色的。","py":"Wǒ yào de shì hóngsè de, ér bú shì báisè de.","vi":"Tôi cần cái màu đỏ chứ không phải màu trắng.","en":"I want the red one, not the white one."},{"use":"A…，而 B…: đối lập (còn thì)","ex":"他喜欢安静，而我喜欢热闹。","py":"Tā xǐhuan ānjìng, ér wǒ xǐhuan rènao.","vi":"Anh ấy thích yên tĩnh, còn tôi thích náo nhiệt.","en":"He likes quiet, whereas I like lively places."},{"use":"因…而…: vì… mà…","ex":"他因生病而没有来上课。","py":"Tā yīn shēngbìng ér méiyǒu lái shàngkè.","vi":"Anh ấy vì bị bệnh mà không đến lớp.","en":"He didn't come to class because he was ill."},{"use":"然而: tuy nhiên","ex":"他很聪明，然而不太努力。","py":"Tā hěn cōngming, rán'ér bú tài nǔlì.","vi":"Anh ấy rất thông minh, tuy nhiên không chăm chỉ lắm.","en":"He's very smart; however, he doesn't work very hard."}]},"却":{"en":"but; yet; however (adverb)","exs":[{"use":"想…，却…: muốn… nhưng lại…","ex":"他想帮忙，却不知道怎么做。","py":"Tā xiǎng bāngmáng, què bù zhīdào zěnme zuò.","vi":"Anh ấy muốn giúp, nhưng lại không biết làm thế nào.","en":"He wanted to help but didn't know how."},{"use":"A…，他却…: trái với dự đoán","ex":"外面下着大雨，他却没带伞。","py":"Wàimiàn xià zhe dàyǔ, tā què méi dài sǎn.","vi":"Bên ngoài mưa to, vậy mà anh ấy lại không mang ô.","en":"It was pouring outside, yet he didn't bring an umbrella."},{"use":"虽然…却…","ex":"虽然很累，他却很高兴。","py":"Suīrán hěn lèi, tā què hěn gāoxìng.","vi":"Tuy rất mệt, nhưng anh ấy lại rất vui.","en":"Although he was tired, he was very happy."},{"use":"很…，却没…","ex":"我很想去，却没有时间。","py":"Wǒ hěn xiǎng qù, què méiyǒu shíjiān.","vi":"Tôi rất muốn đi, nhưng lại không có thời gian.","en":"I really want to go, but I don't have time."}]},"得到":{"en":"to get; to obtain; to receive","exs":[{"use":"得到 + thứ trừu tượng (sự ủng hộ, giúp đỡ)","ex":"他终于得到了大家的支持。","py":"Tā zhōngyú dédào le dàjiā de zhīchí.","vi":"Cuối cùng anh ấy đã nhận được sự ủng hộ của mọi người.","en":"He finally got everyone's support."},{"use":"得到 + 工作/cơ hội","ex":"我得到了一份新工作。","py":"Wǒ dédào le yí fèn xīn gōngzuò.","vi":"Tôi đã có được một công việc mới.","en":"I got a new job."},{"use":"得到 + 表扬: được khen (bị động ngầm)","ex":"孩子得到老师的表扬，非常开心。","py":"Háizi dédào lǎoshī de biǎoyáng, fēicháng kāixīn.","vi":"Đứa trẻ được cô giáo khen nên rất vui.","en":"The child was praised by the teacher and was very happy."},{"use":"只有…才能得到…: có… mới đạt được","ex":"只有努力，才能得到好成绩。","py":"Zhǐyǒu nǔlì, cái néng dédào hǎo chéngjì.","vi":"Chỉ có cố gắng mới đạt được thành tích tốt.","en":"Only with effort can you get good grades."},{"use":"没有得到 + N: không nhận được","ex":"我给他发了短信，但是没有得到回答。","py":"Wǒ gěi tā fā le duǎnxìn, dànshì méiyǒu dédào huídá.","vi":"Tôi nhắn tin cho anh ấy nhưng không nhận được trả lời.","en":"I texted him but didn't get a reply."}]},"窗外":{"en":"outside the window","exs":[{"use":"窗外 + động từ/hiện tượng thời tiết","ex":"窗外下雨了。","py":"Chuāngwài xià yǔ le.","vi":"Bên ngoài cửa sổ trời mưa rồi.","en":"It's raining outside the window."},{"use":"窗外 + 有 + N","ex":"窗外有一棵很大的树。","py":"Chuāngwài yǒu yì kē hěn dà de shù.","vi":"Ngoài cửa sổ có một cái cây rất to.","en":"There's a big tree outside the window."},{"use":"看着窗外: nhìn ra ngoài cửa sổ","ex":"她看着窗外，不知道在想什么。","py":"Tā kàn zhe chuāngwài, bù zhīdào zài xiǎng shénme.","vi":"Cô ấy nhìn ra ngoài cửa sổ, không biết đang nghĩ gì.","en":"She gazed out the window, lost in thought."},{"use":"窗外的 + N: định ngữ","ex":"窗外的风景很美。","py":"Chuāngwài de fēngjǐng hěn měi.","vi":"Phong cảnh ngoài cửa sổ rất đẹp.","en":"The view outside the window is beautiful."},{"use":"窗外传来…: vọng từ ngoài cửa sổ","ex":"窗外传来小鸟的叫声。","py":"Chuāngwài chuánlái xiǎoniǎo de jiào shēng.","vi":"Từ ngoài cửa sổ vọng vào tiếng chim hót.","en":"The sound of birds comes from outside the window."}]},"站":{"en":"to stand; to stop; station","exs":[{"use":"站在 + địa điểm: đứng ở đâu","ex":"请站在门口等我。","py":"Qǐng zhàn zài ménkǒu děng wǒ.","vi":"Hãy đứng ở cửa chờ tôi.","en":"Please stand at the door and wait for me."},{"use":"站起来: đứng dậy","ex":"老师进来时，学生都站了起来。","py":"Lǎoshī jìnlái shí, xuésheng dōu zhàn le qǐlái.","vi":"Khi thầy giáo bước vào, học sinh đều đứng dậy.","en":"When the teacher came in, all the students stood up."},{"use":"站着 + V: vừa đứng vừa…","ex":"车上没有座位，我站了一个小时。","py":"Chē shàng méiyǒu zuòwèi, wǒ zhàn le yí gè xiǎoshí.","vi":"Trên xe không có chỗ ngồi, tôi đứng một tiếng.","en":"There were no seats on the bus, so I stood for an hour."},{"use":"站着 + V: làm việc trong tư thế đứng","ex":"他喜欢站着工作。","py":"Tā xǐhuan zhàn zhe gōngzuò.","vi":"Anh ấy thích đứng làm việc.","en":"He likes to work standing up."},{"use":"nghĩa danh từ: trạm (车站, 站)","ex":"下一站是北京站。","py":"Xià yí zhàn shì Běijīng zhàn.","vi":"Trạm tiếp theo là ga Bắc Kinh.","en":"The next stop is Beijing Station."}]},"选":{"en":"to choose; to select; to elect","exs":[{"use":"选 + danh từ: chọn cái gì","ex":"你可以选自己喜欢的颜色。","py":"Nǐ kěyǐ xuǎn zìjǐ xǐhuan de yánsè.","vi":"Bạn có thể chọn màu mình thích.","en":"You can choose the color you like."},{"use":"不知道选什么: phân vân lựa chọn","ex":"菜单很长，我不知道选什么。","py":"Càidān hěn cháng, wǒ bù zhīdào xuǎn shénme.","vi":"Thực đơn dài quá, tôi không biết chọn gì.","en":"The menu is long and I don't know what to choose."},{"use":"选 + người + 当…: bầu ai làm…","ex":"大家选他当班长。","py":"Dàjiā xuǎn tā dāng bānzhǎng.","vi":"Mọi người bầu anh ấy làm lớp trưởng.","en":"Everyone elected him class monitor."},{"use":"从…中选: chọn từ trong","ex":"请从这三个中选一个。","py":"Qǐng cóng zhè sān gè zhōng xuǎn yí gè.","vi":"Hãy chọn một trong ba cái này.","en":"Please choose one of these three."},{"use":"选课: chọn môn","ex":"这个学期我选了三门课。","py":"Zhège xuéqī wǒ xuǎn le sān mén kè.","vi":"Học kỳ này tôi chọn ba môn.","en":"This semester I signed up for three courses."}]},"与":{"en":"and; with; (formal) together with","exs":[{"use":"与…一起 / 与 = 和/跟 (trang trọng)","ex":"我想与你分享这个好消息。","py":"Wǒ xiǎng yǔ nǐ fēnxiǎng zhège hǎo xiāoxi.","vi":"Tôi muốn chia sẻ tin tốt này với bạn.","en":"I want to share this good news with you."},{"use":"与…有关: có liên quan","ex":"健康与饮食有很大关系。","py":"Jiànkāng yǔ yǐnshí yǒu hěn dà guānxi.","vi":"Sức khỏe có quan hệ lớn với chế độ ăn uống.","en":"Health is closely related to diet."},{"use":"A 与 B: nối hai danh từ ngang hàng","ex":"工作与生活都很重要。","py":"Gōngzuò yǔ shēnghuó dōu hěn zhòngyào.","vi":"Công việc và cuộc sống đều quan trọng.","en":"Both work and life are important."},{"use":"将与…一起: văn viết","ex":"我明天将与朋友一起去旅行。","py":"Wǒ míngtiān jiāng yǔ péngyou yìqǐ qù lǚxíng.","vi":"Ngày mai tôi sẽ cùng bạn bè đi du lịch.","en":"Tomorrow I will travel together with my friends."},{"use":"与…相比: so với","ex":"与去年相比，今年的天气暖和多了。","py":"Yǔ qùnián xiāngbǐ, jīnnián de tiānqì nuǎnhuo duō le.","vi":"So với năm ngoái, thời tiết năm nay ấm hơn nhiều.","en":"Compared with last year, this year's weather is much warmer."}]},"态度":{"en":"attitude; manner; approach","exs":[{"use":"N + 的 + 态度 + adj","ex":"他的学习态度很好。","py":"Tā de xuéxí tàidu hěn hǎo.","vi":"Thái độ học tập của anh ấy rất tốt.","en":"His attitude toward studying is very good."},{"use":"对…的态度: thái độ đối với","ex":"老师对学生的态度很友好。","py":"Lǎoshī duì xuésheng de tàidu hěn yǒuhǎo.","vi":"Thái độ của thầy cô với học sinh rất thân thiện.","en":"The teacher's attitude toward students is very friendly."},{"use":"态度好/不好: đánh giá dịch vụ","ex":"那位服务员态度不太好。","py":"Nà wèi fúwùyuán tàidu bú tài hǎo.","vi":"Nhân viên phục vụ đó thái độ không tốt lắm.","en":"That waiter's attitude isn't very good."},{"use":"积极的态度: thái độ tích cực","ex":"面对困难，要有积极的态度。","py":"Miànduì kùnnan, yào yǒu jījí de tàidu.","vi":"Đối mặt khó khăn phải có thái độ tích cực.","en":"In the face of difficulties, you need a positive attitude."}]},"因此":{"en":"therefore; as a result; thus","exs":[{"use":"A，因此 B: nguyên nhân – kết quả","ex":"他生病了，因此没来。","py":"Tā shēngbìng le, yīncǐ méi lái.","vi":"Anh ấy bị ốm, vì vậy không đến.","en":"He was ill and therefore didn't come."},{"use":"因此 + kết quả (giao thông, giá cả)","ex":"这里交通方便，因此房价很高。","py":"Zhèlǐ jiāotōng fāngbiàn, yīncǐ fángjià hěn gāo.","vi":"Ở đây giao thông thuận tiện, vì vậy giá nhà rất cao.","en":"Transportation is convenient here, so housing prices are high."},{"use":"因此 + 取得: kết quả tích cực","ex":"他一直很努力，因此取得了好成绩。","py":"Tā yìzhí hěn nǔlì, yīncǐ qǔdé le hǎo chéngjì.","vi":"Anh ấy luôn rất cố gắng nên đạt thành tích tốt.","en":"He has always worked hard and so achieved good results."},{"use":"因此， đầu câu mới, sau dấu chấm","ex":"我们没有准备好。因此，比赛推迟了。","py":"Wǒmen méiyǒu zhǔnbèi hǎo. Yīncǐ, bǐsài tuīchí le.","vi":"Chúng tôi chưa chuẩn bị xong. Vì thế trận đấu bị hoãn.","en":"We weren't ready. Therefore, the match was postponed."}]},"心情":{"en":"mood; state of mind","exs":[{"use":"心情 + adj: tâm trạng tốt/xấu","ex":"我今天心情很好。","py":"Wǒ jīntiān xīnqíng hěn hǎo.","vi":"Hôm nay tâm trạng tôi rất tốt.","en":"I'm in a great mood today."},{"use":"心情不好: tâm trạng không tốt","ex":"他最近心情不好，不想说话。","py":"Tā zuìjìn xīnqíng bù hǎo, bù xiǎng shuōhuà.","vi":"Dạo này anh ấy tâm trạng không tốt, không muốn nói chuyện.","en":"He's been in a bad mood lately and doesn't want to talk."},{"use":"心情变好: thay đổi tâm trạng","ex":"看到蓝天，我的心情一下子变好了。","py":"Kàndào lántiān, wǒ de xīnqíng yíxiàzi biàn hǎo le.","vi":"Nhìn thấy bầu trời xanh, tâm trạng tôi bỗng tốt lên.","en":"Seeing the blue sky instantly lifted my mood."},{"use":"影响心情: tác động","ex":"天气会影响人的心情。","py":"Tiānqì huì yǐngxiǎng rén de xīnqíng.","vi":"Thời tiết có thể ảnh hưởng đến tâm trạng con người.","en":"The weather can affect people's moods."},{"use":"没心情 + V: không có hứng làm gì","ex":"工作太多，我没心情去逛街。","py":"Gōngzuò tài duō, wǒ méi xīnqíng qù guàngjiē.","vi":"Công việc nhiều quá, tôi không có tâm trạng đi dạo phố.","en":"I have too much work and am not in the mood to go shopping."}]},"无法":{"en":"unable to; cannot; there is no way to","exs":[{"use":"无法 + động từ: không thể","ex":"我无法回答这个问题。","py":"Wǒ wúfǎ huídá zhège wèntí.","vi":"Tôi không thể trả lời câu hỏi này.","en":"I cannot answer this question."},{"use":"无法 + V (do hoàn cảnh)","ex":"手机没电了，我无法给你打电话。","py":"Shǒujī méi diàn le, wǒ wúfǎ gěi nǐ dǎ diànhuà.","vi":"Điện thoại hết pin, tôi không thể gọi cho bạn.","en":"My phone is out of battery, so I can't call you."},{"use":"无法用…来 + V: không thể diễn tả bằng…","ex":"他的心情无法用语言来表达。","py":"Tā de xīnqíng wúfǎ yòng yǔyán lái biǎodá.","vi":"Tâm trạng của anh ấy không thể diễn tả bằng lời.","en":"His feelings can't be expressed in words."},{"use":"无法相信: không thể tin","ex":"我无法相信这是真的。","py":"Wǒ wúfǎ xiāngxìn zhè shì zhēn de.","vi":"Tôi không thể tin đây là thật.","en":"I can't believe this is true."},{"use":"无法参加: từ chối lịch sự","ex":"明天有事，我无法参加会议。","py":"Míngtiān yǒu shì, wǒ wúfǎ cānjiā huìyì.","vi":"Ngày mai có việc, tôi không thể tham dự cuộc họp.","en":"I have something on tomorrow and can't attend the meeting."}]},"带给":{"en":"to bring to; to give (feelings, effects) to","exs":[{"use":"带给 + người + điều gì (cảm xúc)","ex":"音乐带给我快乐。","py":"Yīnyuè dài gěi wǒ kuàilè.","vi":"Âm nhạc mang đến cho tôi niềm vui.","en":"Music brings me joy."},{"use":"N 带给 + 我们 + 快乐","ex":"孩子带给我们很多快乐。","py":"Háizi dài gěi wǒmen hěn duō kuàilè.","vi":"Con cái mang đến cho chúng tôi rất nhiều niềm vui.","en":"Children bring us a lot of joy."},{"use":"带给 + ý tưởng/ảnh hưởng","ex":"这次旅行带给我很多新的想法。","py":"Zhè cì lǚxíng dài gěi wǒ hěn duō xīn de xiǎngfǎ.","vi":"Chuyến đi này mang lại cho tôi nhiều ý tưởng mới.","en":"This trip gave me many new ideas."},{"use":"带给 nghĩa tiêu cực: áp lực","ex":"这件事带给他很大的压力。","py":"Zhè jiàn shì dài gěi tā hěn dà de yālì.","vi":"Việc này gây cho anh ấy áp lực rất lớn.","en":"This matter put a lot of pressure on him."}]},"科学":{"en":"science; scientific","exs":[{"use":"danh từ: khoa học","ex":"科学改变生活。","py":"Kēxué gǎibiàn shēnghuó.","vi":"Khoa học thay đổi cuộc sống.","en":"Science changes life."},{"use":"tính từ: 很科学 (hợp lý, đúng khoa học)","ex":"这种方法很科学。","py":"Zhè zhǒng fāngfǎ hěn kēxué.","vi":"Phương pháp này rất khoa học.","en":"This method is very scientific."},{"use":"对科学感兴趣; 科学家","ex":"他对科学很感兴趣，长大想当科学家。","py":"Tā duì kēxué hěn gǎn xìngqù, zhǎngdà xiǎng dāng kēxuéjiā.","vi":"Cậu ấy rất hứng thú với khoa học, lớn lên muốn làm nhà khoa học.","en":"He's very interested in science and wants to be a scientist when he grows up."},{"use":"科学地 + V: một cách khoa học","ex":"要科学地安排时间。","py":"Yào kēxué de ānpái shíjiān.","vi":"Phải sắp xếp thời gian một cách khoa học.","en":"You should arrange your time scientifically."},{"use":"科学和技术: cặp từ hay đi cùng","ex":"科学和技术的发展很快。","py":"Kēxué hé jìshù de fāzhǎn hěn kuài.","vi":"Khoa học và kỹ thuật phát triển rất nhanh.","en":"Science and technology are developing rapidly."}]},"证明":{"en":"to prove; to demonstrate; proof; certificate","exs":[{"use":"动词: 证明 + kết luận","ex":"事实证明他是对的。","py":"Shìshí zhèngmíng tā shì duì de.","vi":"Sự thật chứng minh anh ấy đúng.","en":"The facts prove that he was right."},{"use":"用…证明: dùng… để chứng minh","ex":"他用成绩证明了自己的能力。","py":"Tā yòng chéngjì zhèngmíng le zìjǐ de nénglì.","vi":"Anh ấy dùng thành tích để chứng minh năng lực của mình.","en":"He proved his ability through his grades."},{"use":"实验证明…: kết quả thí nghiệm","ex":"这个实验证明了这种方法有效。","py":"Zhège shíyàn zhèngmíng le zhè zhǒng fāngfǎ yǒuxiào.","vi":"Thí nghiệm này chứng minh phương pháp này có hiệu quả.","en":"This experiment proved the method is effective."},{"use":"danh từ: giấy chứng nhận (收入证明, 病假证明)","ex":"医生给我开了一张病假证明。","py":"Yīshēng gěi wǒ kāi le yì zhāng bìngjià zhèngmíng.","vi":"Bác sĩ cấp cho tôi một giấy chứng nhận nghỉ bệnh.","en":"The doctor gave me a sick-leave certificate."}]},"往往":{"en":"often; usually; tend to","exs":[{"use":"往往 + V: thường xảy ra (quy luật)","ex":"他往往很早起床。","py":"Tā wǎngwǎng hěn zǎo qǐchuáng.","vi":"Anh ấy thường dậy rất sớm.","en":"He usually gets up very early."},{"use":"thói quen cuối tuần","ex":"周末我往往在家看书。","py":"Zhōumò wǒ wǎngwǎng zài jiā kàn shū.","vi":"Cuối tuần tôi thường ở nhà đọc sách.","en":"On weekends I usually read at home."},{"use":"往往 + 容易: xu hướng chung","ex":"人在累的时候，往往容易发脾气。","py":"Rén zài lèi de shíhou, wǎngwǎng róngyì fā píqi.","vi":"Con người khi mệt thường dễ nổi nóng.","en":"People tend to lose their temper when tired."},{"use":"往往 + 不会: nhận xét chung","ex":"好机会往往不会等人。","py":"Hǎo jīhuì wǎngwǎng bú huì děng rén.","vi":"Cơ hội tốt thường không chờ đợi ai.","en":"Good opportunities usually don't wait for anyone."}]},"白色":{"en":"white; the color white","exs":[{"use":"danh từ màu sắc + 衣服","ex":"我喜欢白色衣服。","py":"Wǒ xǐhuan báisè yīfu.","vi":"Tôi thích quần áo màu trắng.","en":"I like white clothes."},{"use":"是…白色的: câu 是…的","ex":"这个房间的墙是白色的。","py":"Zhège fángjiān de qiáng shì báisè de.","vi":"Tường của căn phòng này màu trắng.","en":"The walls of this room are white."},{"use":"白色的 + N: định ngữ","ex":"我家有一只白色的小狗。","py":"Wǒ jiā yǒu yì zhī báisè de xiǎo gǒu.","vi":"Nhà tôi có một chú chó nhỏ màu trắng.","en":"We have a little white dog at home."},{"use":"一片白色: toàn một màu trắng","ex":"冬天，山上是一片白色。","py":"Dōngtiān, shān shàng shì yí piàn báisè.","vi":"Mùa đông, trên núi một màu trắng xóa.","en":"In winter the mountains are a sea of white."}]},"阳光":{"en":"sunshine; sunlight; sunny/optimistic (of a person)","exs":[{"use":"tính từ: 阳光 = tích cực, lạc quan","ex":"她是一个很阳光的人。","py":"Tā shì yí gè hěn yángguāng de rén.","vi":"Cô ấy là người rất lạc quan.","en":"She is a very sunny, upbeat person."},{"use":"danh từ: 阳光很好 = nắng đẹp","ex":"今天阳光很好，我们去晒被子吧。","py":"Jīntiān yángguāng hěn hǎo, wǒmen qù shài bèizi ba.","vi":"Hôm nay nắng đẹp, chúng ta đi phơi chăn đi.","en":"The sun is nice today; let's go air out the quilts."},{"use":"阳光照进…: ánh nắng chiếu vào","ex":"阳光从窗外照进房间。","py":"Yángguāng cóng chuāngwài zhào jìn fángjiān.","vi":"Ánh nắng từ ngoài cửa sổ chiếu vào phòng.","en":"Sunlight shines into the room through the window."},{"use":"阳光的 + N: người sống tích cực","ex":"他总是笑着，是个阳光的男孩。","py":"Tā zǒngshì xiào zhe, shì gè yángguāng de nánhái.","vi":"Cậu ấy luôn mỉm cười, là một chàng trai rạng rỡ.","en":"He's always smiling; he's a sunny kind of boy."},{"use":"阳光让人…: tác động của nắng","ex":"冬天的阳光让人觉得很暖和。","py":"Dōngtiān de yángguāng ràng rén juéde hěn nuǎnhuo.","vi":"Nắng mùa đông khiến người ta thấy ấm áp.","en":"Winter sunshine makes people feel warm."}]},"积极向上":{"en":"positive and upward-striving; proactive and optimistic","exs":[{"use":"定语: 积极向上的 + 态度","ex":"保持积极向上的态度。","py":"Bǎochí jījí xiàngshàng de tàidu.","vi":"Giữ thái độ tích cực vươn lên.","en":"Maintain a positive, upward-striving attitude."},{"use":"miêu tả người: 积极向上的年轻人","ex":"他是一个积极向上的年轻人。","py":"Tā shì yí gè jījí xiàngshàng de niánqīng rén.","vi":"Anh ấy là một chàng trai trẻ tích cực vươn lên.","en":"He is a positive, driven young man."},{"use":"miêu tả tinh thần tổ chức","ex":"公司希望员工有积极向上的精神。","py":"Gōngsī xīwàng yuángōng yǒu jījí xiàngshàng de jīngshén.","vi":"Công ty mong nhân viên có tinh thần tích cực vươn lên.","en":"The company hopes its employees have a positive, striving spirit."},{"use":"làm vị ngữ: miêu tả bài hát","ex":"这首歌很积极向上，听了让人有力量。","py":"Zhè shǒu gē hěn jījí xiàngshàng, tīng le ràng rén yǒu lìliang.","vi":"Bài hát này rất tích cực, nghe xong khiến người ta có thêm sức mạnh.","en":"This song is uplifting and gives people strength."},{"use":"生活得积极向上: bổ ngữ trạng thái","ex":"她生活得积极向上，从不抱怨。","py":"Tā shēnghuó de jījí xiàngshàng, cóng bù bàoyuàn.","vi":"Cô ấy sống tích cực vươn lên, chưa bao giờ phàn nàn.","en":"She lives positively and never complains."}]},"特点":{"en":"characteristic; feature; distinguishing trait","exs":[{"use":"N + 的特点: đặc điểm của…","ex":"这是它的特点。","py":"Zhè shì tā de tèdiǎn.","vi":"Đây là đặc điểm của nó.","en":"This is its distinguishing feature."},{"use":"每个人都有自己的特点","ex":"每个人都有自己的特点。","py":"Měi gè rén dōu yǒu zìjǐ de tèdiǎn.","vi":"Ai cũng có đặc điểm riêng của mình.","en":"Everyone has their own characteristics."},{"use":"…的特点是…: nêu đặc điểm","ex":"这个城市的特点是天气暖和，人也很友好。","py":"Zhège chéngshì de tèdiǎn shì tiānqì nuǎnhuo, rén yě hěn yǒuhǎo.","vi":"Đặc điểm của thành phố này là thời tiết ấm áp, người dân cũng thân thiện.","en":"This city is known for its warm weather and friendly people."},{"use":"有…特点 / 说说特点: giới thiệu","ex":"请你说说这家饭馆的特点。","py":"Qǐng nǐ shuōshuo zhè jiā fànguǎn de tèdiǎn.","vi":"Bạn hãy nói về đặc điểm của quán ăn này đi.","en":"Please tell me what's special about this restaurant."}]},"红色":{"en":"red; the color red","exs":[{"use":"danh từ màu sắc","ex":"红色让人热情。","py":"Hóngsè ràng rén rèqíng.","vi":"Màu đỏ khiến người ta nhiệt tình.","en":"Red makes people feel passionate."},{"use":"红色在中国: ý nghĩa văn hóa","ex":"红色在中国代表好运。","py":"Hóngsè zài Zhōngguó dàibiǎo hǎoyùn.","vi":"Màu đỏ ở Trung Quốc tượng trưng cho may mắn.","en":"In China, red stands for good luck."},{"use":"红色的 + N: định ngữ","ex":"他买了一辆红色的汽车。","py":"Tā mǎi le yí liàng hóngsè de qìchē.","vi":"Anh ấy mua một chiếc ô tô màu đỏ.","en":"He bought a red car."},{"use":"过年: đèn lồng đỏ","ex":"过年时，家家门口都挂着红色的灯笼。","py":"Guònián shí, jiājiā ménkǒu dōu guà zhe hóngsè de dēnglong.","vi":"Dịp Tết, trước cửa nhà nào cũng treo đèn lồng đỏ.","en":"At the New Year, every house hangs red lanterns at the door."}]},"变化":{"en":"change; to change","exs":[{"use":"danh từ: 发生变化 = xảy ra thay đổi","ex":"天气发生了变化。","py":"Tiānqì fāshēng le biànhuà.","vi":"Thời tiết đã có thay đổi.","en":"The weather has changed."},{"use":"động từ: 变化很大","ex":"这几年，我的家乡变化很大。","py":"Zhè jǐ nián, wǒ de jiāxiāng biànhuà hěn dà.","vi":"Mấy năm nay, quê tôi thay đổi rất nhiều.","en":"My hometown has changed a lot in recent years."},{"use":"danh từ: N + 的变化","ex":"他的变化让大家很吃惊。","py":"Tā de biànhuà ràng dàjiā hěn chījīng.","vi":"Sự thay đổi của anh ấy khiến mọi người rất ngạc nhiên.","en":"His change surprised everyone."},{"use":"động từ: 变化很快 (thời tiết)","ex":"这里天气变化很快，出门带上伞。","py":"Zhèlǐ tiānqì biànhuà hěn kuài, chūmén dàishàng sǎn.","vi":"Thời tiết ở đây thay đổi rất nhanh, ra ngoài nhớ mang ô.","en":"The weather changes quickly here; take an umbrella when you go out."}]},"黄色":{"en":"yellow; the color yellow","exs":[{"use":"danh từ màu sắc","ex":"黄色让人心情愉快。","py":"Huángsè ràng rén xīnqíng yúkuài.","vi":"Màu vàng khiến người ta vui vẻ.","en":"Yellow puts people in a cheerful mood."},{"use":"变成黄色: chuyển sang màu vàng","ex":"秋天，树叶变成了黄色。","py":"Qiūtiān, shùyè biànchéng le huángsè.","vi":"Mùa thu, lá cây chuyển sang màu vàng.","en":"In autumn, the leaves turn yellow."},{"use":"是…黄色的","ex":"美国的校车是黄色的。","py":"Měiguó de xiàochē shì huángsè de.","vi":"Xe buýt trường học ở Mỹ có màu vàng.","en":"School buses in America are yellow."},{"use":"黄色的 + N: định ngữ","ex":"我想买一件黄色的外套。","py":"Wǒ xiǎng mǎi yí jiàn huángsè de wàitào.","vi":"Tôi muốn mua một chiếc áo khoác màu vàng.","en":"I'd like to buy a yellow coat."}]},"愉快":{"en":"happy; cheerful; pleasant","exs":[{"use":"祝你…愉快: lời chúc","ex":"祝你旅途愉快。","py":"Zhù nǐ lǚtú yúkuài.","vi":"Chúc bạn chuyến đi vui vẻ.","en":"Have a pleasant trip."},{"use":"祝你周末愉快","ex":"祝你周末愉快！","py":"Zhù nǐ zhōumò yúkuài!","vi":"Chúc bạn cuối tuần vui vẻ!","en":"Have a nice weekend!"},{"use":"愉快的 + N: định ngữ","ex":"我们度过了愉快的一天。","py":"Wǒmen dùguò le yúkuài de yì tiān.","vi":"Chúng tôi đã trải qua một ngày vui vẻ.","en":"We had a pleasant day."},{"use":"合作愉快: khách sáo công việc","ex":"很高兴认识你，希望合作愉快。","py":"Hěn gāoxìng rènshi nǐ, xīwàng hézuò yúkuài.","vi":"Rất vui được làm quen, mong hợp tác vui vẻ.","en":"Nice to meet you; I hope we'll work well together."},{"use":"愉快地 + V: một cách vui vẻ","ex":"她愉快地答应了我们的邀请。","py":"Tā yúkuài de dāying le wǒmen de yāoqǐng.","vi":"Cô ấy vui vẻ nhận lời mời của chúng tôi.","en":"She happily accepted our invitation."}]},"黑色":{"en":"black; the color black","exs":[{"use":"danh từ + 衣服","ex":"他穿黑色衣服。","py":"Tā chuān hēisè yīfu.","vi":"Anh ấy mặc quần áo màu đen.","en":"He wears black clothes."},{"use":"是…黑色的","ex":"我的电脑是黑色的。","py":"Wǒ de diànnǎo shì hēisè de.","vi":"Máy tính của tôi màu đen.","en":"My computer is black."},{"use":"黑色的 + N: tóc","ex":"她有一头黑色的长头发。","py":"Tā yǒu yì tóu hēisè de cháng tóufa.","vi":"Cô ấy có mái tóc dài màu đen.","en":"She has long black hair."},{"use":"夜空: miêu tả cảnh","ex":"夜里，天空是黑色的，只有几颗星星。","py":"Yèlǐ, tiānkōng shì hēisè de, zhǐyǒu jǐ kē xīngxing.","vi":"Ban đêm bầu trời đen kịt, chỉ có vài ngôi sao.","en":"At night the sky is black with only a few stars."},{"use":"量词 双 + 黑色的鞋","ex":"他今天穿了一双黑色的鞋。","py":"Tā jīntiān chuān le yì shuāng hēisè de xié.","vi":"Hôm nay anh ấy đi một đôi giày màu đen.","en":"He's wearing a pair of black shoes today."}]},"伤心":{"en":"sad; heartbroken; to hurt (someone's) feelings","exs":[{"use":"伤心: buồn (lời khuyên)","ex":"别太伤心。","py":"Bié tài shāngxīn.","vi":"Đừng quá buồn.","en":"Don't be too sad."},{"use":"伤心地 + V: một cách đau lòng","ex":"她收到坏消息，伤心地哭了。","py":"Tā shōudào huài xiāoxi, shāngxīn de kū le.","vi":"Cô ấy nhận tin xấu, đau lòng khóc.","en":"She received bad news and cried sadly."},{"use":"让…很伤心: khiến ai buồn","ex":"你的话让妈妈很伤心。","py":"Nǐ de huà ràng māma hěn shāngxīn.","vi":"Lời của con khiến mẹ rất buồn.","en":"What you said made Mom very sad."},{"use":"伤心的 + 事: định ngữ","ex":"别提那件伤心的事了。","py":"Bié tí nà jiàn shāngxīn de shì le.","vi":"Đừng nhắc đến chuyện đau lòng đó nữa.","en":"Don't bring up that sad matter again."},{"use":"为…伤心: buồn vì","ex":"不要为这点小事伤心。","py":"Búyào wèi zhè diǎn xiǎoshì shāngxīn.","vi":"Đừng buồn vì chuyện nhỏ này.","en":"Don't be sad over such a small thing."}]},"安静":{"en":"quiet; peaceful; calm","exs":[{"use":"请安静: yêu cầu giữ im lặng","ex":"请安静一下。","py":"Qǐng ānjìng yíxià.","vi":"Xin hãy yên lặng một chút.","en":"Please be quiet for a moment."},{"use":"nơi chốn: 很安静","ex":"图书馆里很安静。","py":"Túshūguǎn lǐ hěn ānjìng.","vi":"Trong thư viện rất yên tĩnh.","en":"It is very quiet in the library."},{"use":"安静的 + N: định ngữ","ex":"我喜欢住在安静的地方。","py":"Wǒ xǐhuan zhù zài ānjìng de dìfang.","vi":"Tôi thích sống ở nơi yên tĩnh.","en":"I like living in a quiet place."},{"use":"安静地 + V: trạng ngữ","ex":"他安静地坐在那里看书。","py":"Tā ānjìng de zuò zài nàlǐ kàn shū.","vi":"Anh ấy lặng lẽ ngồi đó đọc sách.","en":"He sat there reading quietly."}]},"科学研究":{"en":"scientific research","exs":[{"use":"danh từ ghép: 科学研究 + cần tiền","ex":"这项科学研究需要很多钱。","py":"Zhè xiàng kēxué yánjiū xūyào hěn duō qián.","vi":"Công trình nghiên cứu khoa học này cần rất nhiều tiền.","en":"This scientific research needs a lot of money."},{"use":"做科学研究: làm nghiên cứu","ex":"他一生都在做科学研究。","py":"Tā yìshēng dōu zài zuò kēxué yánjiū.","vi":"Cả đời ông ấy làm nghiên cứu khoa học.","en":"He spent his whole life doing scientific research."},{"use":"科学研究 + 要 + phẩm chất","ex":"科学研究要有耐心。","py":"Kēxué yánjiū yào yǒu nàixīn.","vi":"Nghiên cứu khoa học cần có sự kiên nhẫn.","en":"Scientific research requires patience."},{"use":"…的科学研究: định ngữ về cơ sở","ex":"这所大学的科学研究很有名。","py":"Zhè suǒ dàxué de kēxué yánjiū hěn yǒumíng.","vi":"Nghiên cứu khoa học của trường đại học này rất nổi tiếng.","en":"This university is famous for its scientific research."}]},"她们":{"en":"they; them (female)","exs":[{"use":"làm chủ ngữ: 她们 + 是…","ex":"她们是我的同学。","py":"Tāmen shì wǒ de tóngxué.","vi":"Họ (các cô ấy) là bạn học của tôi.","en":"They are my classmates."},{"use":"làm tân ngữ: 看见她们","ex":"我看见她们在公园里散步。","py":"Wǒ kànjiàn tāmen zài gōngyuán lǐ sànbù.","vi":"Tôi thấy các cô ấy đang đi dạo trong công viên.","en":"I saw them walking in the park."},{"use":"她们的 + N: sở hữu","ex":"她们的老师很年轻。","py":"Tāmen de lǎoshī hěn niánqīng.","vi":"Giáo viên của các cô ấy rất trẻ.","en":"Their teacher is very young."},{"use":"thay thế nhóm nữ đã nhắc trước đó","ex":"妈妈和姐姐去商店了，她们下午才回来。","py":"Māma hé jiějie qù shāngdiàn le, tāmen xiàwǔ cái huílái.","vi":"Mẹ và chị đi cửa hàng rồi, chiều họ mới về.","en":"Mom and my sister went to the store; they won't be back until the afternoon."}]},"带来":{"en":"to bring; to bring about","exs":[{"use":"带来 + tân ngữ cụ thể: mang đến","ex":"我给你带来了一份礼物。","py":"Wǒ gěi nǐ dàilái le yí fèn lǐwù.","vi":"Tôi mang đến cho bạn một món quà.","en":"I brought you a gift."},{"use":"给…带来 + điều trừu tượng","ex":"这场雨给我们带来了凉爽。","py":"Zhè chǎng yǔ gěi wǒmen dàilái le liángshuǎng.","vi":"Cơn mưa này mang lại sự mát mẻ cho chúng tôi.","en":"This rain has brought us some coolness."},{"use":"新技术带来方便","ex":"新技术带来了很多方便。","py":"Xīn jìshù dàilái le hěn duō fāngbiàn.","vi":"Công nghệ mới mang lại nhiều tiện lợi.","en":"New technology has brought a lot of convenience."},{"use":"请带来: yêu cầu mang theo","ex":"请带来你的作业。","py":"Qǐng dàilái nǐ de zuòyè.","vi":"Hãy mang bài tập của bạn đến.","en":"Please bring your homework."}]},"巧克力":{"en":"chocolate","exs":[{"use":"吃巧克力","ex":"我最爱吃巧克力。","py":"Wǒ zuì ài chī qiǎokèlì.","vi":"Tôi thích ăn sô-cô-la nhất.","en":"I love eating chocolate most of all."},{"use":"量词 盒 + 巧克力: quà tặng","ex":"情人节，他送给她一盒巧克力。","py":"Qíngrénjié, tā sòng gěi tā yì hé qiǎokèlì.","vi":"Ngày Valentine, anh ấy tặng cô ấy một hộp sô-cô-la.","en":"On Valentine's Day he gave her a box of chocolates."},{"use":"巧克力 + 蛋糕: làm định ngữ","ex":"我想买一个巧克力蛋糕。","py":"Wǒ xiǎng mǎi yí gè qiǎokèlì dàngāo.","vi":"Tôi muốn mua một cái bánh sô-cô-la.","en":"I want to buy a chocolate cake."},{"use":"吃太多…对…不好","ex":"吃太多巧克力对牙不好。","py":"Chī tài duō qiǎokèlì duì yá bù hǎo.","vi":"Ăn nhiều sô-cô-la không tốt cho răng.","en":"Eating too much chocolate is bad for your teeth."}]},"出国":{"en":"to go abroad; to leave the country","exs":[{"use":"出国 + V: đi nước ngoài làm gì","ex":"我打算明年出国留学。","py":"Wǒ dǎsuàn míngnián chūguó liúxué.","vi":"Tôi dự định năm sau ra nước ngoài du học.","en":"I plan to study abroad next year."},{"use":"出国要带…: lưu ý khi ra nước ngoài","ex":"出国要带护照。","py":"Chūguó yào dài hùzhào.","vi":"Ra nước ngoài phải mang hộ chiếu.","en":"You need to bring your passport to go abroad."},{"use":"第一次出国: lần đầu","ex":"他第一次出国，很紧张。","py":"Tā dì yī cì chūguó, hěn jǐnzhāng.","vi":"Anh ấy lần đầu ra nước ngoài nên rất căng thẳng.","en":"It's his first time going abroad, and he's nervous."},{"use":"想出国旅游","ex":"假期他们想出国旅游。","py":"Jiàqī tāmen xiǎng chūguó lǚyóu.","vi":"Kỳ nghỉ họ muốn ra nước ngoài du lịch.","en":"They want to travel abroad during the holiday."}]},"外国":{"en":"foreign country; foreign; abroad","exs":[{"use":"làm danh từ: nước ngoài","ex":"我想去外国留学。","py":"Wǒ xiǎng qù wàiguó liúxué.","vi":"Tôi muốn ra nước ngoài du học.","en":"I want to study abroad."},{"use":"外国 + danh từ: thuộc về nước ngoài","ex":"她有很多外国朋友。","py":"Tā yǒu hěn duō wàiguó péngyou.","vi":"Cô ấy có rất nhiều bạn người nước ngoài.","en":"She has many foreign friends."},{"use":"外国人: người nước ngoài","ex":"这家饭馆外国人特别多。","py":"Zhè jiā fànguǎn wàiguórén tèbié duō.","vi":"Quán ăn này có đặc biệt nhiều người nước ngoài.","en":"This restaurant has especially many foreigners."},{"use":"从外国 + động từ: từ nước ngoài","ex":"这些水果是从外国进口的。","py":"Zhèxiē shuǐguǒ shì cóng wàiguó jìnkǒu de.","vi":"Những loại trái cây này được nhập khẩu từ nước ngoài.","en":"These fruits are imported from abroad."}]},"送给":{"en":"to give (as a gift) to","exs":[{"use":"送给 + người + vật: tặng cho ai cái gì","ex":"我把这本书送给你。","py":"Wǒ bǎ zhè běn shū sònggěi nǐ.","vi":"Tôi tặng cuốn sách này cho bạn.","en":"I'm giving this book to you."},{"use":"送给 + người, dùng cho quà sinh nhật","ex":"他送给妈妈一束花。","py":"Tā sònggěi māma yí shù huā.","vi":"Anh ấy tặng mẹ một bó hoa.","en":"He gave his mom a bouquet of flowers."},{"use":"Vật + 送给 + người (bị động nhẹ, nhấn mạnh quà)","ex":"这条围巾是我送给她的礼物。","py":"Zhè tiáo wéijīn shì wǒ sònggěi tā de lǐwù.","vi":"Chiếc khăn quàng này là món quà tôi tặng cô ấy.","en":"This scarf is a gift I gave to her."},{"use":"送给 + người: tặng ai làm kỷ niệm","ex":"朋友送给我一张音乐会的票。","py":"Péngyou sònggěi wǒ yì zhāng yīnyuèhuì de piào.","vi":"Bạn tặng tôi một tấm vé buổi hòa nhạc.","en":"A friend gave me a concert ticket."}]},"亲戚朋友":{"en":"relatives and friends","exs":[{"use":"làm danh từ: họ hàng và bạn bè","ex":"过年的时候,我们要去看亲戚朋友。","py":"Guònián de shíhou, wǒmen yào qù kàn qīnqīpéngyǒu.","vi":"Dịp Tết, chúng tôi phải đi thăm họ hàng bạn bè.","en":"During the New Year, we visit relatives and friends."},{"use":"làm tân ngữ: mời họ hàng bạn bè","ex":"他结婚那天请了很多亲戚朋友。","py":"Tā jiéhūn nà tiān qǐng le hěn duō qīnqīpéngyǒu.","vi":"Hôm cưới, anh ấy mời rất nhiều họ hàng bạn bè.","en":"He invited many relatives and friends to his wedding."},{"use":"làm chủ ngữ: nói chung về người thân quen","ex":"亲戚朋友都很关心他的身体。","py":"Qīnqīpéngyǒu dōu hěn guānxīn tā de shēntǐ.","vi":"Họ hàng bạn bè đều rất quan tâm đến sức khỏe của anh ấy.","en":"Relatives and friends all care about his health."}]},"女性":{"en":"female; woman; the female sex","exs":[{"use":"làm danh từ: giới nữ","ex":"现在越来越多的女性出来工作。","py":"Xiànzài yuèláiyuè duō de nǚxìng chūlái gōngzuò.","vi":"Hiện nay ngày càng nhiều phụ nữ đi làm.","en":"More and more women are working these days."},{"use":"女性 + danh từ: thuộc nữ giới (trang trọng)","ex":"这是一本专门给女性看的杂志。","py":"Zhè shì yì běn zhuānmén gěi nǚxìng kàn de zázhì.","vi":"Đây là một cuốn tạp chí dành riêng cho phụ nữ.","en":"This is a magazine made specifically for women."},{"use":"对比 男性: nam giới và nữ giới","ex":"这家公司的女性员工比男性多。","py":"Zhè jiā gōngsī de nǚxìng yuángōng bǐ nánxìng duō.","vi":"Công ty này có nhân viên nữ nhiều hơn nam.","en":"This company has more female employees than male ones."}]},"大多":{"en":"mostly; for the most part; the majority","exs":[{"use":"trạng từ: 大多 + động từ, phần lớn","ex":"来参加聚会的人大多是我的同学。","py":"Lái cānjiā jùhuì de rén dàduō shì wǒ de tóngxué.","vi":"Những người đến dự tiệc phần lớn là bạn học của tôi.","en":"Most of the people at the party are my classmates."},{"use":"大多 + 数: 大多数 = đại đa số","ex":"大多数学生都喜欢周末。","py":"Dàduōshù xuésheng dōu xǐhuan zhōumò.","vi":"Đại đa số học sinh đều thích cuối tuần.","en":"Most students like the weekend."},{"use":"大多 + 都 / 在: nhấn mạnh tính phổ biến","ex":"这里的年轻人大多在大城市工作。","py":"Zhèlǐ de niánqīngrén dàduō zài dà chéngshì gōngzuò.","vi":"Thanh niên ở đây phần lớn làm việc ở thành phố lớn.","en":"Most young people here work in big cities."}]},"景色":{"en":"scenery; view; landscape","exs":[{"use":"làm danh từ: phong cảnh","ex":"这里的景色真美!","py":"Zhèlǐ de jǐngsè zhēn měi!","vi":"Phong cảnh ở đây thật đẹp!","en":"The scenery here is really beautiful!"},{"use":"欣赏 + 景色: ngắm cảnh","ex":"我们坐在山上欣赏美丽的景色。","py":"Wǒmen zuò zài shān shàng xīnshǎng měilì de jǐngsè.","vi":"Chúng tôi ngồi trên núi ngắm phong cảnh tuyệt đẹp.","en":"We sat on the mountain enjoying the beautiful scenery."},{"use":"景色 + 迷人/不错: làm chủ ngữ","ex":"从窗户看出去,外面的景色很迷人。","py":"Cóng chuānghu kàn chūqù, wàimiàn de jǐngsè hěn mírén.","vi":"Nhìn ra từ cửa sổ, cảnh bên ngoài rất quyến rũ.","en":"Looking out the window, the view outside is charming."}]},"放松":{"en":"to relax; to loosen; relaxed","exs":[{"use":"động từ: thư giãn","ex":"周末我喜欢在家放松一下。","py":"Zhōumò wǒ xǐhuan zài jiā fàngsōng yíxià.","vi":"Cuối tuần tôi thích ở nhà thư giãn một chút.","en":"I like to relax at home on weekends."},{"use":"放松 + tân ngữ: làm cho thả lỏng","ex":"听音乐可以放松心情。","py":"Tīng yīnyuè kěyǐ fàngsōng xīnqíng.","vi":"Nghe nhạc có thể giúp thư giãn tâm trạng.","en":"Listening to music can help you relax."},{"use":"làm tính từ: 很放松 (thoải mái, không căng thẳng)","ex":"考试结束后,大家都觉得很放松。","py":"Kǎoshì jiéshù hòu, dàjiā dōu juéde hěn fàngsōng.","vi":"Sau khi thi xong, mọi người đều thấy rất thoải mái.","en":"After the exam, everyone felt very relaxed."},{"use":"放松 + bộ phận cơ thể: thả lỏng","ex":"深呼吸,把肩膀放松。","py":"Shēn hūxī, bǎ jiānbǎng fàngsōng.","vi":"Hít sâu, thả lỏng đôi vai.","en":"Take a deep breath and relax your shoulders."}]},"压力":{"en":"pressure; stress","exs":[{"use":"làm danh từ: áp lực","ex":"最近工作压力很大。","py":"Zuìjìn gōngzuò yālì hěn dà.","vi":"Dạo này áp lực công việc rất lớn.","en":"Work pressure has been heavy lately."},{"use":"有压力 / 没有压力","ex":"你别太紧张,不要给自己压力。","py":"Nǐ bié tài jǐnzhāng, búyào gěi zìjǐ yālì.","vi":"Bạn đừng quá căng thẳng, đừng tự tạo áp lực cho mình.","en":"Don't be too nervous; don't put pressure on yourself."},{"use":"压力 + 大/小: vị ngữ chỉ mức độ","ex":"学生的学习压力越来越大。","py":"Xuésheng de xuéxí yālì yuèláiyuè dà.","vi":"Áp lực học tập của học sinh ngày càng lớn.","en":"Students' study pressure keeps growing."},{"use":"减轻/缓解 + 压力: giảm áp lực","ex":"运动是减轻压力的好方法。","py":"Yùndòng shì jiǎnqīng yālì de hǎo fāngfǎ.","vi":"Tập thể dục là cách tốt để giảm áp lực.","en":"Exercise is a good way to relieve stress."}]},"好好儿":{"en":"properly; well; carefully (adverb)","exs":[{"use":"好好儿 + động từ: làm cho tử tế","ex":"你要好好儿休息,别太累了。","py":"Nǐ yào hǎohāor xiūxi, bié tài lèi le.","vi":"Bạn phải nghỉ ngơi cho tử tế, đừng quá mệt.","en":"You should rest well and not get too tired."},{"use":"好好儿 + học/làm: nghiêm túc","ex":"你好好儿学习,将来才有好工作。","py":"Nǐ hǎohāor xuéxí, jiānglái cái yǒu hǎo gōngzuò.","vi":"Con học hành cho tử tế thì sau này mới có việc tốt.","en":"Study hard and you'll get a good job in the future."},{"use":"好好儿 + 想想: suy nghĩ kỹ","ex":"这个问题你回去好好儿想想。","py":"Zhège wèntí nǐ huíqù hǎohāor xiǎngxiang.","vi":"Vấn đề này bạn về nhà suy nghĩ kỹ đi.","en":"Go home and think this over carefully."},{"use":"好好儿 + 的 (khẩu ngữ): còn lành lặn, nguyên vẹn","ex":"这杯子昨天还好好儿的,怎么坏了?","py":"Zhè bēizi zuótiān hái hǎohāor de, zěnme huài le?","vi":"Cái cốc này hôm qua còn nguyên lành, sao lại hỏng rồi?","en":"This cup was fine yesterday; how did it break?"}]},"准备":{"en":"to prepare; to get ready; to plan","exs":[{"use":"động từ: chuẩn bị + tân ngữ","ex":"妈妈正在准备晚饭。","py":"Māma zhèngzài zhǔnbèi wǎnfàn.","vi":"Mẹ đang chuẩn bị bữa tối.","en":"Mom is preparing dinner."},{"use":"准备 + động từ: định, dự định","ex":"我准备下个月去北京旅游。","py":"Wǒ zhǔnbèi xià ge yuè qù Běijīng lǚyóu.","vi":"Tôi định tháng sau đi Bắc Kinh du lịch.","en":"I plan to travel to Beijing next month."},{"use":"为…做准备: làm danh từ (sự chuẩn bị)","ex":"他每天都在为考试做准备。","py":"Tā měitiān dōu zài wèi kǎoshì zuò zhǔnbèi.","vi":"Ngày nào anh ấy cũng chuẩn bị cho kỳ thi.","en":"He prepares for the exam every day."},{"use":"准备好了: kết quả bổ ngữ, đã sẵn sàng","ex":"你准备好了吗?我们该出发了。","py":"Nǐ zhǔnbèi hǎo le ma? Wǒmen gāi chūfā le.","vi":"Bạn chuẩn bị xong chưa? Chúng ta nên xuất phát rồi.","en":"Are you ready? It's time for us to leave."}]},"房间":{"en":"room","exs":[{"use":"làm danh từ: căn phòng","ex":"我的房间在二楼。","py":"Wǒ de fángjiān zài èr lóu.","vi":"Phòng của tôi ở tầng hai.","en":"My room is on the second floor."},{"use":"订房间: đặt phòng (khách sạn)","ex":"我想订一个双人房间。","py":"Wǒ xiǎng dìng yí ge shuāngrén fángjiān.","vi":"Tôi muốn đặt một phòng đôi.","en":"I'd like to book a double room."},{"use":"打扫房间: dọn dẹp phòng","ex":"周末我要把房间打扫干净。","py":"Zhōumò wǒ yào bǎ fángjiān dǎsǎo gānjìng.","vi":"Cuối tuần tôi phải dọn phòng cho sạch.","en":"I'm going to clean my room this weekend."},{"use":"量词 间 + 房间: lượng từ đi kèm","ex":"这套房子有三个房间。","py":"Zhè tào fángzi yǒu sān ge fángjiān.","vi":"Căn nhà này có ba phòng.","en":"This apartment has three rooms."}]},"回忆":{"en":"to recall; to recollect; memory","exs":[{"use":"động từ: hồi tưởng","ex":"他常常回忆小时候的生活。","py":"Tā chángcháng huíyì xiǎoshíhou de shēnghuó.","vi":"Anh ấy thường hồi tưởng cuộc sống thời thơ ấu.","en":"He often recalls his childhood life."},{"use":"回忆起 + nội dung: nhớ lại","ex":"看到这张照片,我回忆起了很多事。","py":"Kàndào zhè zhāng zhàopiàn, wǒ huíyì qǐ le hěn duō shì.","vi":"Nhìn tấm ảnh này, tôi nhớ lại rất nhiều chuyện.","en":"Seeing this photo, I recalled many things."},{"use":"làm danh từ: kỷ niệm, hồi ức","ex":"这次旅行给我留下了美好的回忆。","py":"Zhè cì lǚxíng gěi wǒ liúxià le měihǎo de huíyì.","vi":"Chuyến du lịch này để lại cho tôi những kỷ niệm đẹp.","en":"This trip left me with wonderful memories."}]},"发生":{"en":"to happen; to occur","exs":[{"use":"发生 + sự việc: xảy ra","ex":"昨天路上发生了一起交通事故。","py":"Zuótiān lùshang fāshēng le yì qǐ jiāotōng shìgù.","vi":"Hôm qua trên đường đã xảy ra một vụ tai nạn giao thông.","en":"A traffic accident happened on the road yesterday."},{"use":"发生了什么事: hỏi chuyện gì xảy ra","ex":"出什么事了?发生了什么?","py":"Chū shénme shì le? Fāshēng le shénme?","vi":"Có chuyện gì vậy? Đã xảy ra chuyện gì?","en":"What's wrong? What happened?"},{"use":"发生 + 变化: xảy ra thay đổi","ex":"这几年我们的城市发生了很大的变化。","py":"Zhè jǐ nián wǒmen de chéngshì fāshēng le hěn dà de biànhuà.","vi":"Mấy năm nay thành phố chúng ta đã có sự thay đổi rất lớn.","en":"Our city has changed a lot in recent years."},{"use":"地点 + 发生: sự việc xảy ra ở đâu","ex":"这件事发生在去年夏天。","py":"Zhè jiàn shì fāshēng zài qùnián xiàtiān.","vi":"Chuyện này xảy ra vào mùa hè năm ngoái.","en":"This happened last summer."}]},"师傅":{"en":"master; skilled worker; (polite address for drivers, workers)","exs":[{"use":"xưng hô tài xế: 师傅","ex":"师傅,请开慢一点儿。","py":"Shīfu, qǐng kāi màn yìdiǎnr.","vi":"Bác tài ơi, làm ơn lái chậm một chút.","en":"Driver, please drive a bit slower."},{"use":"xưng hô thợ: 师傅 + 修理","ex":"师傅,我的空调坏了,您能来看看吗?","py":"Shīfu, wǒ de kōngtiáo huài le, nín néng lái kànkan ma?","vi":"Thợ ơi, máy lạnh nhà tôi hỏng rồi, anh đến xem giúp được không?","en":"Sir, my air conditioner is broken. Could you come take a look?"},{"use":"họ + 师傅: gọi thợ/bác lớn tuổi lịch sự","ex":"王师傅做的菜特别好吃。","py":"Wáng shīfu zuò de cài tèbié hǎochī.","vi":"Món ăn bác Vương nấu đặc biệt ngon.","en":"The dishes Master Wang cooks are especially tasty."},{"use":"nghĩa gốc: sư phụ, người dạy nghề","ex":"他跟着师傅学做面包已经三年了。","py":"Tā gēnzhe shīfu xué zuò miànbāo yǐjīng sān nián le.","vi":"Anh ấy theo sư phụ học làm bánh mì đã ba năm rồi.","en":"He has been learning to bake bread from his master for three years."}]},"大使馆":{"en":"embassy","exs":[{"use":"làm danh từ: đại sứ quán","ex":"中国大使馆在市中心。","py":"Zhōngguó dàshǐguǎn zài shì zhōngxīn.","vi":"Đại sứ quán Trung Quốc ở trung tâm thành phố.","en":"The Chinese embassy is in the city center."},{"use":"去大使馆办事: làm thủ tục","ex":"我明天要去大使馆办签证。","py":"Wǒ míngtiān yào qù dàshǐguǎn bàn qiānzhèng.","vi":"Ngày mai tôi phải đến đại sứ quán làm visa.","en":"I'm going to the embassy tomorrow to apply for a visa."},{"use":"在…大使馆工作: làm việc","ex":"我姐姐在美国大使馆工作。","py":"Wǒ jiějie zài Měiguó dàshǐguǎn gōngzuò.","vi":"Chị tôi làm việc ở đại sứ quán Mỹ.","en":"My older sister works at the American embassy."}]},"上班时间":{"en":"working hours; time to go to work","exs":[{"use":"làm danh từ: giờ làm việc","ex":"我们公司的上班时间是九点到六点。","py":"Wǒmen gōngsī de shàngbān shíjiān shì jiǔ diǎn dào liù diǎn.","vi":"Giờ làm việc của công ty chúng tôi là từ chín giờ đến sáu giờ.","en":"Our company's working hours are 9 to 6."},{"use":"上班时间 + không được làm gì","ex":"上班时间不能玩儿手机。","py":"Shàngbān shíjiān bù néng wánr shǒujī.","vi":"Trong giờ làm việc không được chơi điện thoại.","en":"You can't play with your phone during work hours."},{"use":"上班时间 + 堵车: giờ cao điểm","ex":"上班时间路上堵车很厉害。","py":"Shàngbān shíjiān lùshang dǔchē hěn lìhai.","vi":"Giờ đi làm trên đường tắc xe rất nặng.","en":"Traffic is terrible during rush hour on the way to work."}]},"堵车":{"en":"traffic jam; to be stuck in traffic","exs":[{"use":"động từ ly hợp: 堵车","ex":"今天早上堵车堵得很厉害。","py":"Jīntiān zǎoshang dǔchē dǔ de hěn lìhai.","vi":"Sáng nay tắc đường rất nặng.","en":"The traffic was terrible this morning."},{"use":"因为堵车: nguyên nhân đến muộn","ex":"我因为堵车,所以迟到了。","py":"Wǒ yīnwèi dǔchē, suǒyǐ chídào le.","vi":"Tôi bị tắc đường nên đến muộn.","en":"I was late because of a traffic jam."},{"use":"怕/会 + 堵车: lo ngại, dự đoán","ex":"现在出门会堵车,我们晚点儿走吧。","py":"Xiànzài chūmén huì dǔchē, wǒmen wǎndiǎnr zǒu ba.","vi":"Bây giờ ra đường sẽ tắc, chúng ta đi muộn một chút nhé.","en":"There will be traffic if we leave now; let's go a bit later."},{"use":"在 + nơi + 堵车: tắc ở đâu","ex":"我们在桥上堵车堵了半个小时。","py":"Wǒmen zài qiáo shang dǔchē dǔ le bàn ge xiǎoshí.","vi":"Chúng tôi bị tắc xe trên cầu nửa tiếng.","en":"We were stuck in traffic on the bridge for half an hour."}]},"距离":{"en":"distance; to be apart from","exs":[{"use":"làm danh từ: khoảng cách","ex":"我家和公司的距离不远。","py":"Wǒ jiā hé gōngsī de jùlí bù yuǎn.","vi":"Khoảng cách từ nhà tôi đến công ty không xa.","en":"The distance between my home and the company isn't far."},{"use":"A 距离 B + khoảng cách: cách (làm giới từ)","ex":"学校距离地铁站只有五百米。","py":"Xuéxiào jùlí dìtiězhàn zhǐyǒu wǔbǎi mǐ.","vi":"Trường cách ga tàu điện ngầm chỉ có năm trăm mét.","en":"The school is only 500 meters from the subway station."},{"use":"距离 + thời gian: còn cách (thời điểm)","ex":"距离考试还有一个星期。","py":"Jùlí kǎoshì hái yǒu yí ge xīngqī.","vi":"Còn một tuần nữa là đến kỳ thi.","en":"There's still one week until the exam."},{"use":"距离 nghĩa bóng: khoảng cách giữa người với người","ex":"有时候,父母和孩子之间有距离。","py":"Yǒu shíhou, fùmǔ hé háizi zhījiān yǒu jùlí.","vi":"Đôi khi giữa cha mẹ và con cái có khoảng cách.","en":"Sometimes there is a distance between parents and children."}]},"浪费时间":{"en":"to waste time","exs":[{"use":"động từ + tân ngữ: lãng phí thời gian","ex":"别在这件小事上浪费时间了。","py":"Bié zài zhè jiàn xiǎoshì shang làngfèi shíjiān le.","vi":"Đừng lãng phí thời gian vào chuyện nhỏ này nữa.","en":"Don't waste time on this little matter."},{"use":"太/很 + 浪费时间: nhận xét","ex":"坐火车去太浪费时间了,还是坐飞机吧。","py":"Zuò huǒchē qù tài làngfèi shíjiān le, háishi zuò fēijī ba.","vi":"Đi tàu hỏa lãng phí thời gian quá, vẫn nên đi máy bay.","en":"Taking the train wastes too much time; let's fly instead."},{"use":"不想/怕 + 浪费时间","ex":"我不想浪费时间,直接说吧。","py":"Wǒ bù xiǎng làngfèi shíjiān, zhíjiē shuō ba.","vi":"Tôi không muốn lãng phí thời gian, nói thẳng nhé.","en":"I don't want to waste time, so let me be direct."}]},"可不是":{"en":"exactly; you can say that again; isn't that so","exs":[{"use":"đáp lời đồng tình: 可不是!","ex":"A:今天真热啊! B:可不是,有三十八度呢。","py":"A: Jīntiān zhēn rè a! B: Kěbúshì, yǒu sānshíbā dù ne.","vi":"A: Hôm nay nóng thật! B: Chứ còn gì, những 38 độ cơ.","en":"A: It's so hot today! B: Tell me about it, it's 38 degrees."},{"use":"可不是 + câu giải thích thêm","ex":"可不是嘛,这家店的东西又好又便宜。","py":"Kěbúshì ma, zhè jiā diàn de dōngxi yòu hǎo yòu piányi.","vi":"Đúng thế đấy, đồ ở tiệm này vừa tốt vừa rẻ.","en":"Exactly, the stuff in this shop is both good and cheap."},{"use":"可不是 đồng ý với lời than phiền","ex":"A:最近房价涨得太快了。 B:可不是,我们都买不起了。","py":"A: Zuìjìn fángjià zhǎng de tài kuài le. B: Kěbúshì, wǒmen dōu mǎi bù qǐ le.","vi":"A: Dạo này giá nhà tăng nhanh quá. B: Đúng vậy, chúng ta đều không mua nổi nữa.","en":"A: House prices are rising too fast lately. B: You said it; we can't afford one anymore."}]},"下班":{"en":"to get off work","exs":[{"use":"động từ ly hợp: tan làm","ex":"我六点下班。","py":"Wǒ liù diǎn xiàbān.","vi":"Tôi sáu giờ tan làm.","en":"I get off work at six."},{"use":"下班后 + hoạt động","ex":"下班后我常去健身房。","py":"Xiàbān hòu wǒ cháng qù jiànshēnfáng.","vi":"Sau giờ làm tôi thường đến phòng gym.","en":"After work I often go to the gym."},{"use":"下班了: có 了 cuối cụm, chỉ hoàn thành","ex":"你下班了给我打个电话。","py":"Nǐ xiàbān le gěi wǒ dǎ ge diànhuà.","vi":"Tan làm xong bạn gọi điện cho tôi nhé.","en":"Call me when you get off work."},{"use":"下班 + 回家 (liên động)","ex":"他每天下班就回家做饭。","py":"Tā měitiān xiàbān jiù huíjiā zuòfàn.","vi":"Ngày nào anh ấy cũng tan làm là về nhà nấu cơm.","en":"Every day he goes home to cook as soon as he finishes work."}]},"马路":{"en":"road; street","exs":[{"use":"làm danh từ: đường phố","ex":"过马路的时候要小心。","py":"Guò mǎlù de shíhou yào xiǎoxīn.","vi":"Khi qua đường phải cẩn thận.","en":"Be careful when crossing the road."},{"use":"马路 + 上: trên đường","ex":"马路上有很多车。","py":"Mǎlù shang yǒu hěn duō chē.","vi":"Trên đường có rất nhiều xe.","en":"There are lots of cars on the road."},{"use":"马路对面: bên kia đường","ex":"银行就在马路对面。","py":"Yínháng jiù zài mǎlù duìmiàn.","vi":"Ngân hàng ở ngay bên kia đường.","en":"The bank is right across the street."}]},"开车":{"en":"to drive a car","exs":[{"use":"động từ ly hợp: lái xe","ex":"我爸爸开车去上班。","py":"Wǒ bàba kāichē qù shàngbān.","vi":"Bố tôi lái xe đi làm.","en":"My dad drives to work."},{"use":"会/不会 + 开车: biết lái xe","ex":"你会开车吗?","py":"Nǐ huì kāichē ma?","vi":"Bạn biết lái xe không?","en":"Can you drive?"},{"use":"开车 + bổ ngữ: 开得快/慢","ex":"他开车开得很稳。","py":"Tā kāichē kāi de hěn wěn.","vi":"Anh ấy lái xe rất vững.","en":"He drives very steadily."},{"use":"开车 + 去/到: đi bằng xe","ex":"从这儿开车到机场要一个小时。","py":"Cóng zhèr kāichē dào jīchǎng yào yí ge xiǎoshí.","vi":"Từ đây lái xe đến sân bay mất một tiếng.","en":"It takes an hour to drive to the airport from here."}]},"耐心":{"en":"patience; patient","exs":[{"use":"làm danh từ: sự kiên nhẫn","ex":"教小孩子需要很多耐心。","py":"Jiāo xiǎo háizi xūyào hěn duō nàixīn.","vi":"Dạy trẻ con cần rất nhiều kiên nhẫn.","en":"Teaching kids takes a lot of patience."},{"use":"有耐心 / 没有耐心","ex":"他很有耐心,从来不发火。","py":"Tā hěn yǒu nàixīn, cónglái bù fāhuǒ.","vi":"Anh ấy rất kiên nhẫn, chưa bao giờ nổi nóng.","en":"He's very patient and never loses his temper."},{"use":"耐心 + 地 + động từ: làm trạng ngữ (nghĩa tính từ)","ex":"老师耐心地回答了我的问题。","py":"Lǎoshī nàixīn de huídá le wǒ de wèntí.","vi":"Thầy giáo kiên nhẫn trả lời câu hỏi của tôi.","en":"The teacher patiently answered my question."},{"use":"失去耐心: mất kiên nhẫn","ex":"等了两个小时,他渐渐失去了耐心。","py":"Děng le liǎng ge xiǎoshí, tā jiànjiàn shīqù le nàixīn.","vi":"Đợi hai tiếng, anh ấy dần mất kiên nhẫn.","en":"After waiting two hours, he gradually lost patience."}]},"长期":{"en":"long-term; for a long time","exs":[{"use":"长期 + động từ: trạng ngữ, lâu dài","ex":"他长期在国外工作。","py":"Tā chángqī zài guówài gōngzuò.","vi":"Anh ấy làm việc ở nước ngoài lâu dài.","en":"He has long worked abroad."},{"use":"长期 + danh từ: định ngữ","ex":"我们希望和你们建立长期合作关系。","py":"Wǒmen xīwàng hé nǐmen jiànlì chángqī hézuò guānxi.","vi":"Chúng tôi hy vọng thiết lập quan hệ hợp tác lâu dài với các bạn.","en":"We hope to build a long-term partnership with you."},{"use":"长期 对比 短期","ex":"这个办法只是短期有用,长期看不行。","py":"Zhège bànfǎ zhǐshì duǎnqī yǒuyòng, chángqī kàn bù xíng.","vi":"Cách này chỉ có ích trong ngắn hạn, về lâu dài thì không được.","en":"This method only works in the short term, not in the long run."},{"use":"长期 + 以来: bấy lâu nay","ex":"长期以来,他一直坚持锻炼身体。","py":"Chángqī yǐlái, tā yìzhí jiānchí duànliàn shēntǐ.","vi":"Bấy lâu nay, anh ấy luôn kiên trì tập thể dục.","en":"For a long time, he has kept exercising."}]},"听听":{"en":"to listen (a bit); to give a listen","exs":[{"use":"động từ lặp: 听听 = nghe thử","ex":"你听听这首歌怎么样。","py":"Nǐ tīngting zhè shǒu gē zěnmeyàng.","vi":"Bạn nghe thử bài hát này xem thế nào.","en":"Give this song a listen and see what you think."},{"use":"听听 + ý kiến người khác","ex":"做决定以前,先听听大家的意见。","py":"Zuò juédìng yǐqián, xiān tīngting dàjiā de yìjiàn.","vi":"Trước khi quyết định, hãy nghe ý kiến mọi người trước.","en":"Before deciding, listen to everyone's opinions first."},{"use":"听听 + 看 / 吧: ngữ khí đề nghị","ex":"你来听听,这个声音正常吗?","py":"Nǐ lái tīngting, zhège shēngyīn zhèngcháng ma?","vi":"Bạn lại nghe thử xem, tiếng này có bình thường không?","en":"Come and listen; does this sound normal?"}]},"音乐":{"en":"music","exs":[{"use":"làm danh từ: âm nhạc","ex":"我喜欢听轻松的音乐。","py":"Wǒ xǐhuan tīng qīngsōng de yīnyuè.","vi":"Tôi thích nghe nhạc nhẹ nhàng.","en":"I like listening to relaxing music."},{"use":"音乐会: buổi hòa nhạc","ex":"周末我们去听音乐会吧。","py":"Zhōumò wǒmen qù tīng yīnyuèhuì ba.","vi":"Cuối tuần chúng ta đi nghe hòa nhạc nhé.","en":"Let's go to a concert this weekend."},{"use":"音乐 + danh từ: chuyên ngành","ex":"她在音乐学院学习钢琴。","py":"Tā zài yīnyuè xuéyuàn xuéxí gāngqín.","vi":"Cô ấy học piano ở nhạc viện.","en":"She studies piano at the conservatory."}]},"勇敢":{"en":"brave; courageous","exs":[{"use":"làm tính từ vị ngữ: dũng cảm","ex":"这个孩子很勇敢。","py":"Zhège háizi hěn yǒnggǎn.","vi":"Đứa trẻ này rất dũng cảm.","en":"This child is very brave."},{"use":"勇敢 + 地 + động từ: trạng ngữ","ex":"面对困难,我们要勇敢地往前走。","py":"Miànduì kùnnan, wǒmen yào yǒnggǎn de wǎng qián zǒu.","vi":"Đối mặt với khó khăn, chúng ta phải dũng cảm tiến lên.","en":"In the face of difficulties, we must move forward bravely."},{"use":"勇敢的 + danh từ: định ngữ","ex":"他是一个勇敢的消防员。","py":"Tā shì yí ge yǒnggǎn de xiāofángyuán.","vi":"Anh ấy là một lính cứu hỏa dũng cảm.","en":"He is a brave firefighter."}]},"结果":{"en":"result; outcome; as a result","exs":[{"use":"danh từ: kết quả","ex":"考试结果明天公布。","py":"Kǎoshì jiéguǒ míngtiān gōngbù.","vi":"Kết quả thi ngày mai công bố.","en":"The exam results will be announced tomorrow."},{"use":"结果 làm liên từ: kết cục là (đầu vế sau)","ex":"我昨天没带伞,结果被雨淋湿了。","py":"Wǒ zuótiān méi dài sǎn, jiéguǒ bèi yǔ lín shī le.","vi":"Hôm qua tôi không mang ô, kết quả là bị mưa ướt hết.","en":"I didn't bring an umbrella yesterday and ended up soaked."},{"use":"不管结果如何: dù kết quả thế nào","ex":"不管结果怎么样,我都会接受。","py":"Bùguǎn jiéguǒ zěnmeyàng, wǒ dōu huì jiēshòu.","vi":"Dù kết quả thế nào, tôi cũng sẽ chấp nhận.","en":"Whatever the outcome, I will accept it."},{"use":"结果 + 是: nêu kết quả","ex":"比赛的结果是我们队赢了。","py":"Bǐsài de jiéguǒ shì wǒmen duì yíng le.","vi":"Kết quả trận đấu là đội chúng tôi thắng.","en":"The result of the match was that our team won."}]},"失败":{"en":"to fail; failure; defeat","exs":[{"use":"động từ: thất bại","ex":"他第一次考驾照失败了。","py":"Tā dì yī cì kǎo jiàzhào shībài le.","vi":"Lần đầu thi bằng lái anh ấy đã trượt.","en":"He failed his driving test the first time."},{"use":"danh từ: sự thất bại","ex":"失败是成功的妈妈。","py":"Shībài shì chénggōng de māma.","vi":"Thất bại là mẹ của thành công.","en":"Failure is the mother of success."},{"use":"从失败中 + học: rút kinh nghiệm","ex":"我们要从失败中学到经验。","py":"Wǒmen yào cóng shībài zhōng xuédào jīngyàn.","vi":"Chúng ta phải rút kinh nghiệm từ thất bại.","en":"We should learn from failure."},{"use":"失败 + 了 / 的: tính chất kết quả","ex":"这次试验失败的原因是什么?","py":"Zhè cì shìyàn shībài de yuányīn shì shénme?","vi":"Nguyên nhân thí nghiệm lần này thất bại là gì?","en":"What is the reason this experiment failed?"}]},"看重":{"en":"to value; to regard as important","exs":[{"use":"看重 + danh từ: coi trọng","ex":"公司很看重你的工作经验。","py":"Gōngsī hěn kànzhòng nǐ de gōngzuò jīngyàn.","vi":"Công ty rất coi trọng kinh nghiệm làm việc của bạn.","en":"The company values your work experience a lot."},{"use":"被 + 看重 / 最看重","ex":"我最看重的是家人的健康。","py":"Wǒ zuì kànzhòng de shì jiārén de jiànkāng.","vi":"Điều tôi coi trọng nhất là sức khỏe của người nhà.","en":"What I value most is my family's health."},{"use":"不太看重 + danh từ: phủ định","ex":"现在的年轻人不太看重面子。","py":"Xiànzài de niánqīngrén bú tài kànzhòng miànzi.","vi":"Giới trẻ bây giờ không mấy coi trọng thể diện.","en":"Young people today don't care much about saving face."}]},"注意力":{"en":"attention; focus","exs":[{"use":"làm danh từ: sự chú ý","ex":"孩子的注意力很容易分散。","py":"Háizi de zhùyìlì hěn róngyì fēnsàn.","vi":"Sự chú ý của trẻ con rất dễ bị phân tán.","en":"Children's attention is easily distracted."},{"use":"集中注意力: tập trung chú ý","ex":"上课时请集中注意力。","py":"Shàngkè shí qǐng jízhōng zhùyìlì.","vi":"Khi lên lớp xin hãy tập trung chú ý.","en":"Please pay attention in class."},{"use":"吸引注意力: thu hút sự chú ý","ex":"这个广告很吸引大家的注意力。","py":"Zhège guǎnggào hěn xīyǐn dàjiā de zhùyìlì.","vi":"Quảng cáo này rất thu hút sự chú ý của mọi người.","en":"This ad really grabs everyone's attention."}]},"过程":{"en":"process; course","exs":[{"use":"làm danh từ: quá trình","ex":"学习语言是一个长期的过程。","py":"Xuéxí yǔyán shì yí ge chángqī de guòchéng.","vi":"Học ngôn ngữ là một quá trình lâu dài.","en":"Learning a language is a long process."},{"use":"在…的过程中: trong quá trình","ex":"在学习的过程中,他遇到了很多困难。","py":"Zài xuéxí de guòchéng zhōng, tā yùdào le hěn duō kùnnan.","vi":"Trong quá trình học, anh ấy gặp rất nhiều khó khăn.","en":"In the course of studying, he met many difficulties."},{"use":"过程 对比 结果","ex":"比起结果,我更看重过程。","py":"Bǐqǐ jiéguǒ, wǒ gèng kànzhòng guòchéng.","vi":"So với kết quả, tôi coi trọng quá trình hơn.","en":"Compared with the result, I value the process more."}]},"至少":{"en":"at least","exs":[{"use":"至少 + số lượng: ít nhất","ex":"我每天至少喝八杯水。","py":"Wǒ měitiān zhìshǎo hē bā bēi shuǐ.","vi":"Mỗi ngày tôi uống ít nhất tám cốc nước.","en":"I drink at least eight glasses of water a day."},{"use":"至少 + 也 / 要: mức tối thiểu","ex":"你至少要睡七个小时。","py":"Nǐ zhìshǎo yào shuì qī ge xiǎoshí.","vi":"Bạn ít nhất phải ngủ bảy tiếng.","en":"You need to sleep at least seven hours."},{"use":"至少 nêu điều tối thiểu còn lại (an ủi)","ex":"虽然没赢,但至少我们努力了。","py":"Suīrán méi yíng, dàn zhìshǎo wǒmen nǔlì le.","vi":"Tuy không thắng, nhưng ít nhất chúng ta đã cố gắng.","en":"We didn't win, but at least we tried."}]},"总结":{"en":"to summarize; summary","exs":[{"use":"động từ: tổng kết","ex":"请你把今天的会议总结一下。","py":"Qǐng nǐ bǎ jīntiān de huìyì zǒngjié yíxià.","vi":"Mời bạn tổng kết lại cuộc họp hôm nay.","en":"Please summarize today's meeting."},{"use":"danh từ: bản tổng kết","ex":"老师让我们写一份学期总结。","py":"Lǎoshī ràng wǒmen xiě yí fèn xuéqī zǒngjié.","vi":"Thầy giáo bảo chúng tôi viết một bản tổng kết học kỳ.","en":"The teacher asked us to write a semester summary."},{"use":"总结 + 经验: rút ra kinh nghiệm","ex":"每次失败后,他都会总结经验。","py":"Měi cì shībài hòu, tā dōu huì zǒngjié jīngyàn.","vi":"Sau mỗi lần thất bại, anh ấy đều rút kinh nghiệm.","en":"After each failure, he sums up the lessons."}]},"放弃":{"en":"to give up; to abandon","exs":[{"use":"放弃 + tân ngữ: từ bỏ cái gì","ex":"他放弃了去国外工作的机会。","py":"Tā fàngqì le qù guówài gōngzuò de jīhuì.","vi":"Anh ấy từ bỏ cơ hội đi làm ở nước ngoài.","en":"He gave up the chance to work abroad."},{"use":"不要/别 + 放弃: khuyên không bỏ cuộc","ex":"遇到困难也不要放弃。","py":"Yùdào kùnnan yě búyào fàngqì.","vi":"Gặp khó khăn cũng đừng bỏ cuộc.","en":"Don't give up even when you meet difficulties."},{"use":"放弃 + động từ: bỏ không làm nữa","ex":"我已经放弃减肥了。","py":"Wǒ yǐjīng fàngqì jiǎnféi le.","vi":"Tôi đã bỏ ý định giảm cân rồi.","en":"I've given up trying to lose weight."}]},"爱迪生":{"en":"Edison (Thomas Edison)","exs":[{"use":"tên riêng: nhà phát minh Edison","ex":"爱迪生是一位很有名的发明家。","py":"Àidíshēng shì yí wèi hěn yǒumíng de fāmíngjiā.","vi":"Edison là một nhà phát minh rất nổi tiếng.","en":"Edison was a very famous inventor."},{"use":"爱迪生 + 发明: phát minh của ông","ex":"爱迪生发明了电灯。","py":"Àidíshēng fāmíng le diàndēng.","vi":"Edison đã phát minh ra bóng đèn điện.","en":"Edison invented the electric light."},{"use":"爱迪生的故事: dùng làm định ngữ","ex":"老师给我们讲了爱迪生小时候的故事。","py":"Lǎoshī gěi wǒmen jiǎng le Àidíshēng xiǎoshíhou de gùshi.","vi":"Thầy kể cho chúng tôi nghe chuyện thời nhỏ của Edison.","en":"The teacher told us a story about Edison's childhood."}]},"点亮":{"en":"to light up; to illuminate","exs":[{"use":"点亮 + tân ngữ: thắp sáng","ex":"晚上他点亮了房间里的灯。","py":"Wǎnshang tā diǎnliàng le fángjiān lǐ de dēng.","vi":"Buổi tối anh ấy bật sáng đèn trong phòng.","en":"In the evening he switched on the light in the room."},{"use":"点亮 nghĩa bóng: thắp lên hy vọng","ex":"你的话点亮了我心中的希望。","py":"Nǐ de huà diǎnliàng le wǒ xīn zhōng de xīwàng.","vi":"Lời của bạn đã thắp lên hy vọng trong lòng tôi.","en":"Your words lit up hope in my heart."},{"use":"点亮 + 蜡烛/灯: nến, đèn","ex":"孩子们点亮了生日蛋糕上的蜡烛。","py":"Háizimen diǎnliàng le shēngrì dàngāo shang de làzhú.","vi":"Bọn trẻ thắp nến trên bánh sinh nhật.","en":"The kids lit the candles on the birthday cake."}]},"经历":{"en":"to experience; to go through; experience","exs":[{"use":"làm danh từ: trải nghiệm, kinh lịch (câu có sẵn)","ex":"旅行能丰富我们的经历。","py":"Lǚxíng néng fēngfù wǒmen de jīnglì.","vi":"Du lịch làm phong phú trải nghiệm của chúng ta.","en":"Traveling can enrich our experiences."},{"use":"động từ: trải qua + sự việc","ex":"他经历了很多困难,终于成功了。","py":"Tā jīnglì le hěn duō kùnnan, zhōngyú chénggōng le.","vi":"Anh ấy đã trải qua nhiều khó khăn, cuối cùng thành công.","en":"He went through many hardships and finally succeeded."},{"use":"danh từ: 经历 = quãng đời đã từng trải","ex":"他给我们讲了自己的工作经历。","py":"Tā gěi wǒmen jiǎng le zìjǐ de gōngzuò jīnglì.","vi":"Anh ấy kể cho chúng tôi nghe về kinh nghiệm làm việc của mình.","en":"He told us about his work experience."},{"use":"有…经历: từng có trải nghiệm","ex":"你有没有在国外生活的经历?","py":"Nǐ yǒu méiyǒu zài guówài shēnghuó de jīnglì?","vi":"Bạn đã từng có trải nghiệm sống ở nước ngoài chưa?","en":"Have you ever had the experience of living abroad?"}]},"区别":{"en":"difference; to distinguish","exs":[{"use":"danh từ: sự khác biệt","ex":"这两个词的区别是什么?","py":"Zhè liǎng ge cí de qūbié shì shénme?","vi":"Sự khác nhau giữa hai từ này là gì?","en":"What is the difference between these two words?"},{"use":"有区别 / 没有区别","ex":"这两种牛奶有什么区别吗?","py":"Zhè liǎng zhǒng niúnǎi yǒu shénme qūbié ma?","vi":"Hai loại sữa này có gì khác nhau không?","en":"Is there any difference between these two kinds of milk?"},{"use":"区别 + 于/开: động từ, phân biệt","ex":"你能区别出这两种茶的味道吗?","py":"Nǐ néng qūbié chū zhè liǎng zhǒng chá de wèidào ma?","vi":"Bạn có phân biệt được vị của hai loại trà này không?","en":"Can you tell the flavors of these two teas apart?"},{"use":"A 和 B 的区别: cấu trúc so sánh","ex":"城市和农村的区别越来越小了。","py":"Chéngshì hé nóngcūn de qūbié yuèláiyuè xiǎo le.","vi":"Sự khác biệt giữa thành thị và nông thôn ngày càng nhỏ.","en":"The gap between cities and the countryside is getting smaller."}]},"坚持":{"en":"to persist; to insist on; to keep up","exs":[{"use":"坚持 + động từ.","ex":"请坚持每天阅读。","py":"Qǐng jiānchí měitiān yuèdú.","vi":"Hãy kiên trì đọc sách mỗi ngày.","en":"Please keep reading every day."},{"use":"坚持 + 到底: kiên trì đến cùng","ex":"不管多难,我都会坚持到底。","py":"Bùguǎn duō nán, wǒ dōu huì jiānchí dàodǐ.","vi":"Dù khó đến đâu, tôi cũng sẽ kiên trì đến cùng.","en":"No matter how hard it is, I'll stick with it to the end."},{"use":"坚持 + 意见/看法: giữ vững ý kiến","ex":"他坚持自己的想法,不肯改变。","py":"Tā jiānchí zìjǐ de xiǎngfǎ, bù kěn gǎibiàn.","vi":"Anh ấy kiên quyết giữ ý kiến của mình, không chịu thay đổi.","en":"He sticks to his own ideas and won't change."},{"use":"坚持 + 下去: bổ ngữ xu hướng","ex":"再坚持一下,马上就到山顶了。","py":"Zài jiānchí yíxià, mǎshàng jiù dào shāndǐng le.","vi":"Cố gắng thêm chút nữa, sắp lên đến đỉnh núi rồi.","en":"Hang in there a bit more; we'll reach the summit soon."}]},"暂时":{"en":"temporarily; for the time being","exs":[{"use":"暂时 + động từ: trạng ngữ","ex":"我暂时住在朋友家。","py":"Wǒ zànshí zhù zài péngyou jiā.","vi":"Tôi tạm thời ở nhà bạn.","en":"I'm staying at a friend's place for now."},{"use":"暂时 + 不/没: tạm chưa","ex":"这个问题暂时不用担心。","py":"Zhège wèntí zànshí búyòng dānxīn.","vi":"Vấn đề này tạm thời chưa cần lo.","en":"There's no need to worry about this for the time being."},{"use":"暂时 + 的: định ngữ (tính chất ngắn hạn)","ex":"这只是暂时的困难,会过去的。","py":"Zhè zhǐshì zànshí de kùnnan, huì guòqù de.","vi":"Đây chỉ là khó khăn tạm thời, sẽ qua thôi.","en":"This is only a temporary difficulty; it will pass."}]},"面对":{"en":"to face; to confront","exs":[{"use":"面对 + tân ngữ: đối mặt","ex":"我们要勇敢地面对困难。","py":"Wǒmen yào yǒnggǎn de miànduì kùnnan.","vi":"Chúng ta phải dũng cảm đối mặt với khó khăn.","en":"We must bravely face difficulties."},{"use":"面对 + 面: nghĩa đen, đối diện nhau","ex":"我们面对面坐着聊了一个晚上。","py":"Wǒmen miàn duì miàn zuòzhe liáo le yí ge wǎnshang.","vi":"Chúng tôi ngồi đối diện nói chuyện cả buổi tối.","en":"We sat face to face and chatted all evening."},{"use":"面对 + 现实/问题","ex":"面对现实吧,这件事已经不能改变了。","py":"Miànduì xiànshí ba, zhè jiàn shì yǐjīng bù néng gǎibiàn le.","vi":"Hãy đối mặt với thực tế đi, chuyện này không thể thay đổi nữa.","en":"Face reality; this can't be changed anymore."}]},"之前":{"en":"before; previously; ago","exs":[{"use":"Thời điểm/Việc + 之前: trước khi","ex":"睡觉之前,我喜欢看一会儿书。","py":"Shuìjiào zhīqián, wǒ xǐhuan kàn yíhuìr shū.","vi":"Trước khi ngủ tôi thích đọc sách một lát.","en":"Before going to sleep, I like to read for a while."},{"use":"Thời gian + 之前: trước mốc thời gian","ex":"请在五点之前把作业交给老师。","py":"Qǐng zài wǔ diǎn zhīqián bǎ zuòyè jiāo gěi lǎoshī.","vi":"Xin hãy nộp bài cho thầy trước năm giờ.","en":"Please hand in your homework to the teacher before five."},{"use":"làm danh từ độc lập: trước đó","ex":"之前我不知道这件事。","py":"Zhīqián wǒ bù zhīdào zhè jiàn shì.","vi":"Trước đó tôi không biết chuyện này.","en":"I didn't know about this before."},{"use":"一个月之前: khoảng thời gian + 之前 = cách đây","ex":"他是一个月之前搬到这里来的。","py":"Tā shì yí ge yuè zhīqián bān dào zhèlǐ lái de.","vi":"Anh ấy chuyển đến đây cách đây một tháng.","en":"He moved here a month ago."}]},"一样":{"en":"same; alike; the same as","exs":[{"use":"A 跟/和 B 一样: giống nhau","ex":"我的手机跟你的一样。","py":"Wǒ de shǒujī gēn nǐ de yíyàng.","vi":"Điện thoại của tôi giống của bạn.","en":"My phone is the same as yours."},{"use":"A 跟 B 一样 + adj: so sánh ngang bằng","ex":"他和哥哥一样高。","py":"Tā hé gēge yíyàng gāo.","vi":"Cậu ấy cao bằng anh trai.","en":"He is as tall as his older brother."},{"use":"不一样: phủ định","ex":"这两个地方的天气不一样。","py":"Zhè liǎng ge dìfang de tiānqì bù yíyàng.","vi":"Thời tiết hai nơi này không giống nhau.","en":"The weather in these two places is different."},{"use":"像…一样: như là","ex":"她像妈妈一样关心我。","py":"Tā xiàng māma yíyàng guānxīn wǒ.","vi":"Cô ấy quan tâm tôi như mẹ vậy.","en":"She cares for me just like a mother."}]},"电灯":{"en":"electric light; lamp","exs":[{"use":"làm danh từ: đèn điện","ex":"房间里的电灯坏了。","py":"Fángjiān lǐ de diàndēng huài le.","vi":"Đèn điện trong phòng bị hỏng rồi.","en":"The light in the room is broken."},{"use":"开/关 + 电灯: bật/tắt","ex":"睡觉前别忘了关电灯。","py":"Shuìjiào qián bié wàng le guān diàndēng.","vi":"Trước khi ngủ đừng quên tắt đèn.","en":"Don't forget to turn off the light before bed."},{"use":"发明电灯","ex":"爱迪生发明了电灯,让夜晚变亮了。","py":"Àidíshēng fāmíng le diàndēng, ràng yèwǎn biàn liàng le.","vi":"Edison phát minh ra bóng đèn điện, làm đêm trở nên sáng.","en":"Edison invented the electric light and brightened the night."}]},"取得":{"en":"to obtain; to achieve; to gain","exs":[{"use":"取得 + thành tích/kết quả.","ex":"他取得了好成绩。","py":"Tā qǔdé le hǎo chéngjì.","vi":"Anh ấy đạt được thành tích tốt.","en":"He achieved good grades."},{"use":"取得 + 成功/进步","ex":"只要努力,你一定会取得成功。","py":"Zhǐyào nǔlì, nǐ yídìng huì qǔdé chénggōng.","vi":"Chỉ cần cố gắng, bạn nhất định sẽ thành công.","en":"As long as you work hard, you will surely succeed."},{"use":"取得 + 联系/同意: thu được, có được","ex":"我们终于和他取得了联系。","py":"Wǒmen zhōngyú hé tā qǔdé le liánxì.","vi":"Cuối cùng chúng tôi cũng liên lạc được với anh ấy.","en":"We finally got in touch with him."},{"use":"取得 + 信任","ex":"要取得别人的信任,需要很长时间。","py":"Yào qǔdé biéren de xìnrèn, xūyào hěn cháng shíjiān.","vi":"Muốn có được sự tin tưởng của người khác cần rất nhiều thời gian.","en":"Gaining other people's trust takes a long time."}]},"许多":{"en":"many; a lot of","exs":[{"use":"许多 + danh từ: rất nhiều","ex":"公园里有许多人在跑步。","py":"Gōngyuán lǐ yǒu xǔduō rén zài pǎobù.","vi":"Trong công viên có rất nhiều người đang chạy bộ.","en":"Many people are jogging in the park."},{"use":"许多 + 的 + danh từ / 许许多多","ex":"我在中国学到了许多新东西。","py":"Wǒ zài Zhōngguó xuédào le xǔduō xīn dōngxi.","vi":"Tôi học được nhiều điều mới ở Trung Quốc.","en":"I learned many new things in China."},{"use":"好了许多: bổ ngữ, hơn nhiều","ex":"吃了药以后,我感觉好了许多。","py":"Chī le yào yǐhòu, wǒ gǎnjué hǎo le xǔduō.","vi":"Uống thuốc xong, tôi thấy khá hơn nhiều.","en":"After taking the medicine, I feel much better."}]},"就算":{"en":"even if; even though","exs":[{"use":"就算…也…: dù cho … cũng …","ex":"就算下雨,我们也要去。","py":"Jiùsuàn xiàyǔ, wǒmen yě yào qù.","vi":"Dù trời mưa, chúng tôi cũng phải đi.","en":"Even if it rains, we still have to go."},{"use":"就算…还是…","ex":"就算很累,他还是坚持完成了工作。","py":"Jiùsuàn hěn lèi, tā háishi jiānchí wánchéng le gōngzuò.","vi":"Dù rất mệt, anh ấy vẫn kiên trì hoàn thành công việc.","en":"Even though he was tired, he still finished the work."},{"use":"就算 + giả thiết, kết quả không đổi","ex":"就算你不说,我也知道是谁做的。","py":"Jiùsuàn nǐ bù shuō, wǒ yě zhīdào shì shéi zuò de.","vi":"Dù bạn không nói, tôi cũng biết là ai làm.","en":"Even if you don't say it, I know who did it."}]},"饼干":{"en":"biscuit; cookie; cracker","exs":[{"use":"làm danh từ: bánh quy","ex":"我喜欢吃巧克力饼干。","py":"Wǒ xǐhuan chī qiǎokèlì bǐnggān.","vi":"Tôi thích ăn bánh quy sô-cô-la.","en":"I like chocolate cookies."},{"use":"量词 块/包 + 饼干","ex":"他一口气吃了三块饼干。","py":"Tā yìkǒuqì chī le sān kuài bǐnggān.","vi":"Anh ấy ăn một mạch ba cái bánh quy.","en":"He ate three cookies in one go."},{"use":"做饼干: tự làm","ex":"妈妈今天下午在家做饼干。","py":"Māma jīntiān xiàwǔ zài jiā zuò bǐnggān.","vi":"Chiều nay mẹ làm bánh quy ở nhà.","en":"Mom is baking cookies at home this afternoon."}]},"难道":{"en":"could it be that...; surely not (rhetorical)","exs":[{"use":"难道…吗?: câu hỏi tu từ","ex":"难道你不知道今天是她的生日吗?","py":"Nándào nǐ bù zhīdào jīntiān shì tā de shēngrì ma?","vi":"Lẽ nào bạn không biết hôm nay là sinh nhật cô ấy sao?","en":"Don't you know today is her birthday?"},{"use":"难道 + 说 / 是…: phỏng đoán nghi ngờ","ex":"这么晚了还没回来,难道出事了?","py":"Zhème wǎn le hái méi huílái, nándào chūshì le?","vi":"Muộn thế này mà chưa về, lẽ nào xảy ra chuyện rồi?","en":"It's so late and he isn't back. Could something have happened?"},{"use":"难道…不成: văn nói, nhấn mạnh phản bác","ex":"你难道想一个人去不成?","py":"Nǐ nándào xiǎng yí ge rén qù bù chéng?","vi":"Lẽ nào bạn định đi một mình à?","en":"Surely you don't plan to go alone?"}]},"瘦下来":{"en":"to slim down; to lose weight","exs":[{"use":"V + 下来: gầy đi (kết quả dần dần)","ex":"他运动了三个月,终于瘦下来了。","py":"Tā yùndòng le sān ge yuè, zhōngyú shòu xiàlái le.","vi":"Anh ấy tập luyện ba tháng, cuối cùng đã gầy đi.","en":"After exercising for three months, he finally slimmed down."},{"use":"想/能 + 瘦下来: mong muốn","ex":"我想瘦下来,所以每天跑步。","py":"Wǒ xiǎng shòu xiàlái, suǒyǐ měitiān pǎobù.","vi":"Tôi muốn gầy đi nên ngày nào cũng chạy bộ.","en":"I want to slim down, so I run every day."},{"use":"瘦下来 + 了 + số lượng","ex":"她瘦下来了十公斤。","py":"Tā shòu xiàlái le shí gōngjīn.","vi":"Cô ấy đã giảm được mười ký.","en":"She has lost ten kilograms."},{"use":"不容易瘦下来: phủ định","ex":"晚上吃太多,很难瘦下来。","py":"Wǎnshang chī tài duō, hěn nán shòu xiàlái.","vi":"Buổi tối ăn quá nhiều thì rất khó gầy đi.","en":"If you eat too much at night, it's hard to lose weight."}]},"公斤":{"en":"kilogram","exs":[{"use":"lượng từ: số + 公斤","ex":"我买了两公斤苹果。","py":"Wǒ mǎi le liǎng gōngjīn píngguǒ.","vi":"Tôi mua hai ký táo.","en":"I bought two kilograms of apples."},{"use":"体重 + số + 公斤","ex":"他的体重是七十公斤。","py":"Tā de tǐzhòng shì qīshí gōngjīn.","vi":"Cân nặng của anh ấy là bảy mươi ký.","en":"He weighs seventy kilograms."},{"use":"多少公斤: hỏi cân nặng; 重…公斤","ex":"这个行李箱重二十多公斤。","py":"Zhège xínglixiāng zhòng èrshí duō gōngjīn.","vi":"Chiếc vali này nặng hơn hai mươi ký.","en":"This suitcase weighs over twenty kilograms."}]},"有效":{"en":"effective; valid","exs":[{"use":"有效的 + danh từ.","ex":"这个方法很有效。","py":"Zhège fāngfǎ hěn yǒuxiào.","vi":"Phương pháp này rất hiệu quả.","en":"This method is very effective."},{"use":"有效的 + danh từ: định ngữ","ex":"医生给了我一个有效的办法。","py":"Yīshēng gěi le wǒ yí ge yǒuxiào de bànfǎ.","vi":"Bác sĩ đưa cho tôi một cách hiệu quả.","en":"The doctor gave me an effective solution."},{"use":"有效 nghĩa: còn hiệu lực","ex":"这张票三天内有效。","py":"Zhè zhāng piào sān tiān nèi yǒuxiào.","vi":"Tấm vé này có hiệu lực trong ba ngày.","en":"This ticket is valid for three days."},{"use":"对…有效: có tác dụng với","ex":"这种药对感冒很有效。","py":"Zhè zhǒng yào duì gǎnmào hěn yǒuxiào.","vi":"Loại thuốc này rất hiệu quả với cảm cúm.","en":"This medicine is very effective for colds."}]},"打算":{"en":"to plan; to intend; plan","exs":[{"use":"打算 + động từ: dự định làm gì","ex":"暑假你打算做什么?","py":"Shǔjià nǐ dǎsuàn zuò shénme?","vi":"Kỳ nghỉ hè bạn định làm gì?","en":"What do you plan to do this summer?"},{"use":"không dự định: 不打算","ex":"我不打算买新手机。","py":"Wǒ bù dǎsuàn mǎi xīn shǒujī.","vi":"Tôi không định mua điện thoại mới.","en":"I don't plan to buy a new phone."},{"use":"danh từ: kế hoạch, dự tính","ex":"你对将来有什么打算?","py":"Nǐ duì jiānglái yǒu shénme dǎsuàn?","vi":"Bạn có dự định gì cho tương lai?","en":"What are your plans for the future?"}]},"刚才":{"en":"just now; a moment ago","exs":[{"use":"刚才 + động từ: vừa nãy (đứng trước hoặc sau chủ ngữ)","ex":"刚才有人给你打电话。","py":"Gāngcái yǒu rén gěi nǐ dǎ diànhuà.","vi":"Vừa nãy có người gọi điện cho bạn.","en":"Someone called you just now."},{"use":"chủ ngữ + 刚才","ex":"我刚才在开会,没听见电话。","py":"Wǒ gāngcái zài kāihuì, méi tīngjiàn diànhuà.","vi":"Vừa nãy tôi đang họp nên không nghe thấy điện thoại.","en":"I was in a meeting just now and didn't hear the phone."},{"use":"刚才 + 的 + danh từ: định ngữ","ex":"刚才的话你别放在心上。","py":"Gāngcái de huà nǐ bié fàng zài xīn shang.","vi":"Lời vừa nãy bạn đừng để trong lòng.","en":"Don't take what I said just now to heart."}]},"主意":{"en":"idea; plan; decision","exs":[{"use":"想主意 / 出主意","ex":"大家一起想想主意吧。","py":"Dàjiā yìqǐ xiǎngxiang zhǔyì ba.","vi":"Mọi người cùng nghĩ ý tưởng nhé.","en":"Let's all think of ideas together."},{"use":"好主意: ý hay","ex":"去海边玩,这个主意真不错!","py":"Qù hǎibiān wán, zhège zhǔyì zhēn búcuò!","vi":"Đi biển chơi, ý này thật không tồi!","en":"Going to the beach is a great idea!"},{"use":"有主意 / 拿主意: có chính kiến, quyết định","ex":"这件事你自己拿主意吧。","py":"Zhè jiàn shì nǐ zìjǐ ná zhǔyì ba.","vi":"Chuyện này bạn tự quyết định đi.","en":"You make the decision on this yourself."},{"use":"改变主意: đổi ý","ex":"我改变主意了,明天不去了。","py":"Wǒ gǎibiàn zhǔyì le, míngtiān bú qù le.","vi":"Tôi đổi ý rồi, ngày mai không đi nữa.","en":"I changed my mind; I'm not going tomorrow."}]},"网球":{"en":"tennis","exs":[{"use":"làm danh từ: quần vợt","ex":"我周末常常和朋友打网球。","py":"Wǒ zhōumò chángcháng hé péngyou dǎ wǎngqiú.","vi":"Cuối tuần tôi thường chơi tennis với bạn.","en":"I often play tennis with friends on weekends."},{"use":"网球 + danh từ: sân, vợt","ex":"他买了一个新网球拍。","py":"Tā mǎi le yí ge xīn wǎngqiú pāi.","vi":"Anh ấy mua một cây vợt tennis mới.","en":"He bought a new tennis racket."},{"use":"网球比赛: trận đấu","ex":"今天晚上有一场网球比赛。","py":"Jīntiān wǎnshang yǒu yì chǎng wǎngqiú bǐsài.","vi":"Tối nay có một trận đấu tennis.","en":"There's a tennis match tonight."}]},"国际":{"en":"international","exs":[{"use":"国际 + danh từ: quốc tế","ex":"北京有很多国际学校。","py":"Běijīng yǒu hěn duō guójì xuéxiào.","vi":"Bắc Kinh có rất nhiều trường quốc tế.","en":"Beijing has many international schools."},{"use":"国际 + 航班/比赛","ex":"明天有一场重要的国际比赛。","py":"Míngtiān yǒu yì chǎng zhòngyào de guójì bǐsài.","vi":"Ngày mai có một trận đấu quốc tế quan trọng.","en":"There's an important international match tomorrow."},{"use":"国际 + 化/上: ở tầm quốc tế","ex":"这位歌手在国际上很有名。","py":"Zhè wèi gēshǒu zài guójì shang hěn yǒumíng.","vi":"Ca sĩ này rất nổi tiếng trên thế giới.","en":"This singer is very famous internationally."}]},"大奖":{"en":"grand prize; major award","exs":[{"use":"得大奖 / 拿大奖","ex":"这部电影拿了国际大奖。","py":"Zhè bù diànyǐng ná le guójì dàjiǎng.","vi":"Bộ phim này đã giành giải thưởng quốc tế lớn.","en":"This film won a major international award."},{"use":"赢得大奖: giành được","ex":"他在比赛中赢得了大奖。","py":"Tā zài bǐsài zhōng yíngdé le dàjiǎng.","vi":"Anh ấy giành giải lớn trong cuộc thi.","en":"He won the grand prize in the competition."},{"use":"中大奖: trúng thưởng lớn","ex":"要是我中了大奖,就环游世界。","py":"Yàoshi wǒ zhòng le dàjiǎng, jiù huányóu shìjiè.","vi":"Nếu tôi trúng giải lớn, tôi sẽ đi vòng quanh thế giới.","en":"If I won the jackpot, I'd travel around the world."}]},"轻轻松松":{"en":"easy; relaxed; effortless","exs":[{"use":"làm trạng ngữ: 轻轻松松地 + động từ","ex":"他轻轻松松地通过了考试。","py":"Tā qīngqīngsōngsōng de tōngguò le kǎoshì.","vi":"Anh ấy dễ dàng vượt qua kỳ thi.","en":"He passed the exam with ease."},{"use":"làm vị ngữ: V + 得 + 轻轻松松 (thoải mái, không áp lực)","ex":"她每天过得轻轻松松，一点儿压力也没有。","py":"Tā měitiān guò de qīngqīngsōngsōng, yìdiǎnr yālì yě méiyǒu.","vi":"Cô ấy ngày nào cũng sống nhẹ nhàng, không hề có áp lực.","en":"She lives a relaxed life every day, without any pressure at all."},{"use":"nghĩa thoải mái, thư thả (về tâm trạng)","ex":"周末我想轻轻松松地在家休息。","py":"Zhōumò wǒ xiǎng qīngqīngsōngsōng de zài jiā xiūxi.","vi":"Cuối tuần tôi muốn thong thả nghỉ ngơi ở nhà.","en":"This weekend I want to relax at home."}]},"哪里":{"en":"where; (humble reply) not at all; anywhere","exs":[{"use":"nghĩa 1: đại từ nghi vấn hỏi nơi chốn","ex":"请问，洗手间在哪里？","py":"Qǐngwèn, xǐshǒujiān zài nǎlǐ?","vi":"Xin hỏi, nhà vệ sinh ở đâu?","en":"Excuse me, where is the restroom?"},{"use":"nghĩa 1: 去 + 哪里 + động từ","ex":"你想去哪里旅游？","py":"Nǐ xiǎng qù nǎlǐ lǚyóu?","vi":"Bạn muốn đi du lịch ở đâu?","en":"Where do you want to travel?"},{"use":"nghĩa 2: 哪里哪里 dùng để khiêm tốn đáp lại lời khen","ex":"你的汉语说得真好！——哪里哪里，我还要多练习。","py":"Nǐ de Hànyǔ shuō de zhēn hǎo! Nǎlǐ nǎlǐ, wǒ hái yào duō liànxí.","vi":"Bạn nói tiếng Trung giỏi quá! — Đâu có đâu có, tôi còn phải luyện tập nhiều.","en":"You speak Chinese so well! — Not at all, I still need to practice more."},{"use":"nghĩa 3: 哪里 + 都/也 = bất kỳ nơi nào","ex":"这个城市很安全，你哪里都可以去。","py":"Zhège chéngshì hěn ānquán, nǐ nǎlǐ dōu kěyǐ qù.","vi":"Thành phố này rất an toàn, bạn đi đâu cũng được.","en":"This city is very safe; you can go anywhere."}]},"练习":{"en":"to practice; exercise; practice","exs":[{"use":"làm động từ: 练习 + V/O","ex":"每天晚上我都练习写汉字。","py":"Měitiān wǎnshang wǒ dōu liànxí xiě Hànzì.","vi":"Tối nào tôi cũng luyện viết chữ Hán.","en":"Every evening I practice writing Chinese characters."},{"use":"làm danh từ: bài tập, bài luyện","ex":"老师给我们布置了很多练习。","py":"Lǎoshī gěi wǒmen bùzhì le hěn duō liànxí.","vi":"Thầy giáo giao cho chúng tôi rất nhiều bài tập.","en":"The teacher assigned us a lot of exercises."},{"use":"cấu trúc 多 + 练习 (luyện nhiều)","ex":"多练习才能说好外语。","py":"Duō liànxí cái néng shuō hǎo wàiyǔ.","vi":"Luyện tập nhiều mới nói giỏi ngoại ngữ được.","en":"You can speak a foreign language well only by practicing a lot."}]},"随随便便":{"en":"casual; careless; arbitrary","exs":[{"use":"dạng lặp AABB của 随便, nghĩa qua loa, cẩu thả","ex":"做作业不能随随便便，要认真检查。","py":"Zuò zuòyè bù néng suísuíbiànbiàn, yào rènzhēn jiǎnchá.","vi":"Làm bài tập không được qua loa, phải kiểm tra cẩn thận.","en":"You can't do homework carelessly; you must check it carefully."},{"use":"làm trạng ngữ: 随随便便地 + V","ex":"他随随便便地穿了件衣服就出门了。","py":"Tā suísuíbiànbiàn de chuān le jiàn yīfu jiù chūmén le.","vi":"Anh ấy tùy tiện mặc bộ đồ nào đó rồi ra ngoài.","en":"He threw on some clothes and went out."},{"use":"thường đi với 不能 để phê bình sự tùy tiện","ex":"这么重要的事，不能随随便便决定。","py":"Zhème zhòngyào de shì, bù néng suísuíbiànbiàn juédìng.","vi":"Việc quan trọng thế này không thể quyết định tùy tiện.","en":"You can't decide such an important matter casually."},{"use":"nghĩa tích cực: thoải mái, không câu nệ","ex":"跟好朋友在一起，大家都随随便便的。","py":"Gēn hǎo péngyou zài yìqǐ, dàjiā dōu suísuíbiànbiàn de.","vi":"Ở cùng bạn thân, mọi người đều thoải mái, không câu nệ.","en":"Among good friends, everyone is relaxed and informal."}]},"从小":{"en":"from childhood; since one was young","exs":[{"use":"làm trạng ngữ: 从小 + 就 + V","ex":"我从小就喜欢画画儿。","py":"Wǒ cóngxiǎo jiù xǐhuan huà huàr.","vi":"Tôi thích vẽ từ nhỏ.","en":"I have liked drawing since I was a child."},{"use":"从小 + 在 + nơi chốn + 长大","ex":"他从小在北京长大。","py":"Tā cóngxiǎo zài Běijīng zhǎngdà.","vi":"Anh ấy lớn lên ở Bắc Kinh từ nhỏ.","en":"He grew up in Beijing from childhood."},{"use":"đứng trước chủ ngữ để nhấn mạnh thời điểm","ex":"从小父母就教我要诚实。","py":"Cóngxiǎo fùmǔ jiù jiāo wǒ yào chéngshí.","vi":"Từ nhỏ bố mẹ đã dạy tôi phải thành thật.","en":"Since I was little, my parents taught me to be honest."},{"use":"nói về thể trạng, thói quen từ bé","ex":"她从小身体不好，经常去医院。","py":"Tā cóngxiǎo shēntǐ bù hǎo, jīngcháng qù yīyuàn.","vi":"Cô ấy từ nhỏ sức khỏe đã yếu, thường xuyên đến bệnh viện.","en":"She has been in poor health since childhood and often goes to the hospital."}]},"感兴趣":{"en":"to be interested in","exs":[{"use":"cấu trúc 对 + N + 感兴趣","ex":"我对中国历史很感兴趣。","py":"Wǒ duì Zhōngguó lìshǐ hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với lịch sử Trung Quốc.","en":"I am very interested in Chinese history."},{"use":"câu hỏi: 对什么 + 感兴趣","ex":"你对什么运动感兴趣？","py":"Nǐ duì shénme yùndòng gǎn xìngqù?","vi":"Bạn hứng thú với môn thể thao nào?","en":"What sports are you interested in?"},{"use":"dạng phủ định: 不感兴趣","ex":"他对做生意不感兴趣。","py":"Tā duì zuò shēngyi bù gǎn xìngqù.","vi":"Anh ấy không có hứng thú với việc kinh doanh.","en":"He is not interested in doing business."},{"use":"dùng không có 对 khi đối tượng đã rõ","ex":"如果你感兴趣，可以和我们一起去。","py":"Rúguǒ nǐ gǎn xìngqù, kěyǐ hé wǒmen yìqǐ qù.","vi":"Nếu bạn có hứng thú thì có thể đi cùng chúng tôi.","en":"If you're interested, you can come with us."}]},"春夏秋冬":{"en":"spring, summer, autumn and winter; the four seasons","exs":[{"use":"liệt kê bốn mùa trong năm","ex":"一年有春夏秋冬四个季节。","py":"Yì nián yǒu chūn xià qiū dōng sì gè jìjié.","vi":"Một năm có bốn mùa xuân hạ thu đông.","en":"A year has four seasons: spring, summer, autumn and winter."},{"use":"làm chủ ngữ, nói về sự khác nhau giữa các mùa","ex":"春夏秋冬，每个季节的风景都不一样。","py":"Chūn xià qiū dōng, měi gè jìjié de fēngjǐng dōu bù yíyàng.","vi":"Xuân hạ thu đông, mỗi mùa có một cảnh sắc khác nhau.","en":"Spring, summer, autumn, winter: each season has different scenery."},{"use":"不管 + 春夏秋冬 + 都 (bất kể quanh năm)","ex":"不管春夏秋冬，他每天都坚持跑步。","py":"Bùguǎn chūn xià qiū dōng, tā měitiān dōu jiānchí pǎobù.","vi":"Bất kể xuân hạ thu đông, ngày nào anh ấy cũng kiên trì chạy bộ.","en":"Regardless of the season, he keeps running every day."},{"use":"làm trạng ngữ thời gian: quanh năm","ex":"这个公园春夏秋冬都很漂亮。","py":"Zhège gōngyuán chūn xià qiū dōng dōu hěn piàoliang.","vi":"Công viên này mùa nào cũng đẹp.","en":"This park is beautiful in every season."}]},"练球":{"en":"to practice a ball sport; to train with the ball","exs":[{"use":"động từ ly hợp (động từ + tân ngữ)","ex":"我们每天下午在学校练球。","py":"Wǒmen měitiān xiàwǔ zài xuéxiào liànqiú.","vi":"Chiều nào chúng tôi cũng tập bóng ở trường.","en":"We practice ball games at school every afternoon."},{"use":"lặp động từ: 练球练得 + adj","ex":"他练球练得很认真。","py":"Tā liànqiú liàn de hěn rènzhēn.","vi":"Anh ấy tập bóng rất nghiêm túc.","en":"He practices ball sports very seriously."},{"use":"đi với địa điểm + thời gian cụ thể","ex":"明天下午三点去球场练球，别迟到。","py":"Míngtiān xiàwǔ sān diǎn qù qiúchǎng liànqiú, bié chídào.","vi":"Ba giờ chiều mai đi sân bóng tập bóng, đừng đến muộn.","en":"Go to the field to practice at three tomorrow afternoon; don't be late."},{"use":"chỉ mục đích: 为了 + ..., 练球","ex":"为了比赛，队员们周末也要练球。","py":"Wèile bǐsài, duìyuánmen zhōumò yě yào liànqiú.","vi":"Để chuẩn bị thi đấu, các thành viên đội cuối tuần cũng phải tập bóng.","en":"To prepare for the match, the team members have to practice even on weekends."}]},"鲜花":{"en":"fresh flowers","exs":[{"use":"lượng từ 束/朵: 一束鲜花","ex":"她收到了一束鲜花。","py":"Tā shōudào le yí shù xiānhuā.","vi":"Cô ấy nhận được một bó hoa tươi.","en":"She received a bouquet of fresh flowers."},{"use":"cấu trúc 开满了 + 鲜花","ex":"春天到了，公园里开满了鲜花。","py":"Chūntiān dào le, gōngyuán lǐ kāi mǎn le xiānhuā.","vi":"Xuân đến, trong công viên hoa tươi nở rộ.","en":"Spring has come, and the park is full of blooming flowers."},{"use":"làm tân ngữ của 买/送 (tặng hoa)","ex":"母亲节我给妈妈买了鲜花。","py":"Mǔqīn Jié wǒ gěi māma mǎi le xiānhuā.","vi":"Ngày của mẹ tôi mua hoa tươi tặng mẹ.","en":"On Mother's Day I bought fresh flowers for my mom."},{"use":"đi với tính từ mô tả cửa hàng, giá cả","ex":"这家店的鲜花又新鲜又便宜。","py":"Zhè jiā diàn de xiānhuā yòu xīnxiān yòu piányi.","vi":"Hoa ở cửa hàng này vừa tươi vừa rẻ.","en":"The flowers at this shop are both fresh and cheap."}]},"汗水":{"en":"sweat; perspiration","exs":[{"use":"nghĩa bóng: 汗水 chỉ sự nỗ lực, vất vả","ex":"成功来自努力和汗水。","py":"Chénggōng láizì nǔlì hé hànshuǐ.","vi":"Thành công đến từ nỗ lực và mồ hôi.","en":"Success comes from effort and sweat."},{"use":"nghĩa đen: mồ hôi; 满头都是汗水","ex":"他跑完步，满头都是汗水。","py":"Tā pǎo wán bù, mǎn tóu dōu shì hànshuǐ.","vi":"Chạy xong, anh ấy mồ hôi đầm đìa khắp đầu.","en":"After running, his head was covered in sweat."},{"use":"用汗水换来 + N (đổi mồ hôi lấy thành quả)","ex":"运动员用汗水换来了金牌。","py":"Yùndòngyuán yòng hànshuǐ huàn lái le jīnpái.","vi":"Vận động viên đã dùng mồ hôi đổi lấy tấm huy chương vàng.","en":"The athlete earned the gold medal through sweat and hard work."},{"use":"làm tân ngữ của 擦 (lau mồ hôi)","ex":"她擦了擦脸上的汗水。","py":"Tā cā le cā liǎn shàng de hànshuǐ.","vi":"Cô ấy lau mồ hôi trên mặt.","en":"She wiped the sweat from her face."}]},"通过":{"en":"through; by means of; to pass; to go through; to be approved","exs":[{"use":"通过 + cách thức.","ex":"我们通过练习提高水平。","py":"Wǒmen tōngguò liànxí tígāo shuǐpíng.","vi":"Thông qua","en":"Through (by means of)"},{"use":"giới từ: 通过 + người/phương tiện + V","ex":"他通过朋友找到了这份工作。","py":"Tā tōngguò péngyou zhǎodào le zhè fèn gōngzuò.","vi":"Anh ấy tìm được công việc này thông qua bạn bè.","en":"He found this job through a friend."},{"use":"động từ: vượt qua kỳ thi, kiểm tra","ex":"我终于通过了汉语考试。","py":"Wǒ zhōngyú tōngguò le Hànyǔ kǎoshì.","vi":"Cuối cùng tôi đã đỗ kỳ thi tiếng Trung.","en":"I finally passed the Chinese exam."},{"use":"động từ: đi qua, lưu thông (V + 不了)","ex":"这条路太窄，汽车通过不了。","py":"Zhè tiáo lù tài zhǎi, qìchē tōngguò bù liǎo.","vi":"Con đường này quá hẹp, xe ô tô không đi qua được.","en":"This road is too narrow for cars to pass through."},{"use":"động từ: (kế hoạch, đề án) được thông qua","ex":"这个计划已经通过了。","py":"Zhège jìhuà yǐjīng tōngguò le.","vi":"Kế hoạch này đã được thông qua.","en":"This plan has already been approved."}]},"报纸":{"en":"newspaper","exs":[{"use":"làm tân ngữ của 看 (đọc báo)","ex":"爸爸每天早上看报纸。","py":"Bàba měitiān zǎoshang kàn bàozhǐ.","vi":"Sáng nào bố cũng đọc báo.","en":"Dad reads the newspaper every morning."},{"use":"kết hợp 今天的报纸","ex":"这是今天的报纸，你看了吗？","py":"Zhè shì jīntiān de bàozhǐ, nǐ kàn le ma?","vi":"Đây là tờ báo hôm nay, bạn xem chưa?","en":"This is today's newspaper. Have you read it?"},{"use":"cấu trúc 在报纸上 (trên báo)","ex":"我在报纸上看到了这个消息。","py":"Wǒ zài bàozhǐ shàng kàndào le zhège xiāoxi.","vi":"Tôi đọc được tin này trên báo.","en":"I saw this news in the newspaper."},{"use":"chỉ giấy báo cũ","ex":"旧报纸可以拿去卖钱。","py":"Jiù bàozhǐ kěyǐ ná qù mài qián.","vi":"Báo cũ có thể mang đi bán lấy tiền.","en":"Old newspapers can be sold for money."}]},"关于":{"en":"about; concerning; regarding","exs":[{"use":"đứng đầu câu làm trạng ngữ: 关于 + N，...","ex":"关于这个问题，我们明天再讨论。","py":"Guānyú zhège wèntí, wǒmen míngtiān zài tǎolùn.","vi":"Về vấn đề này, ngày mai chúng ta sẽ thảo luận tiếp.","en":"Regarding this issue, we'll discuss it tomorrow."},{"use":"cấu trúc 关于 + N + 的 + N (định ngữ)","ex":"我买了一本关于中国文化的书。","py":"Wǒ mǎi le yì běn guānyú Zhōngguó wénhuà de shū.","vi":"Tôi mua một cuốn sách về văn hóa Trung Quốc.","en":"I bought a book about Chinese culture."},{"use":"làm định ngữ chỉ chủ đề phim, sách","ex":"这是一部关于爱情的电影。","py":"Zhè shì yí bù guānyú àiqíng de diànyǐng.","vi":"Đây là một bộ phim về tình yêu.","en":"This is a movie about love."},{"use":"关于 + người/việc, nêu mức độ hiểu biết","ex":"关于他的事，我知道得不多。","py":"Guānyú tā de shì, wǒ zhīdào de bù duō.","vi":"Về chuyện của anh ấy, tôi biết không nhiều.","en":"As for his affairs, I don't know much."}]},"有名":{"en":"famous; well-known","exs":[{"use":"làm vị ngữ: 很/非常 + 有名","ex":"这位演员非常有名。","py":"Zhè wèi yǎnyuán fēicháng yǒumíng.","vi":"Diễn viên này vô cùng nổi tiếng.","en":"This actor is very famous."},{"use":"cấu trúc 在 + phạm vi + 很有名","ex":"北京烤鸭在世界上很有名。","py":"Běijīng kǎoyā zài shìjiè shàng hěn yǒumíng.","vi":"Vịt quay Bắc Kinh nổi tiếng trên thế giới.","en":"Peking duck is famous around the world."},{"use":"làm định ngữ: 有名的 + N","ex":"他是一个有名的作家。","py":"Tā shì yí ge yǒumíng de zuòjiā.","vi":"Ông ấy là một nhà văn nổi tiếng.","en":"He is a famous writer."},{"use":"cấu trúc 以 + N + 有名 (nổi tiếng về...)","ex":"这个地方以美食有名。","py":"Zhège dìfang yǐ měishí yǒumíng.","vi":"Nơi này nổi tiếng về ẩm thực.","en":"This place is famous for its food."}]},"作家":{"en":"writer; author","exs":[{"use":"làm vị ngữ sau 是: 一位 + 作家","ex":"他是一位很有名的作家。","py":"Tā shì yí wèi hěn yǒumíng de zuòjiā.","vi":"Ông ấy là một nhà văn rất nổi tiếng.","en":"He is a very famous writer."},{"use":"làm định ngữ rút gọn: 我最喜欢的作家","ex":"我最喜欢的作家是鲁迅。","py":"Wǒ zuì xǐhuan de zuòjiā shì Lǔ Xùn.","vi":"Nhà văn tôi thích nhất là Lỗ Tấn.","en":"My favorite writer is Lu Xun."},{"use":"cấu trúc 当 + 作家 (trở thành nhà văn)","ex":"她从小就想当作家。","py":"Tā cóngxiǎo jiù xiǎng dāng zuòjiā.","vi":"Từ nhỏ cô ấy đã muốn làm nhà văn.","en":"She has wanted to be a writer since childhood."},{"use":"làm chủ ngữ, đi với 写 (viết)","ex":"这位作家写了很多小说。","py":"Zhè wèi zuòjiā xiě le hěn duō xiǎoshuō.","vi":"Nhà văn này đã viết rất nhiều tiểu thuyết.","en":"This author has written many novels."}]},"当时":{"en":"at that time; then","exs":[{"use":"làm trạng ngữ thời gian đứng đầu câu","ex":"当时我不知道他是谁。","py":"Dāngshí wǒ bù zhīdào tā shì shéi.","vi":"Lúc đó tôi không biết anh ấy là ai.","en":"At that time I didn't know who he was."},{"use":"cấu trúc 当时的 + N (định ngữ)","ex":"我还记得当时的情况。","py":"Wǒ hái jìde dāngshí de qíngkuàng.","vi":"Tôi vẫn nhớ tình hình lúc đó.","en":"I still remember the situation back then."},{"use":"nối với một mốc thời gian trong quá khứ","ex":"三年前我在上海工作，当时的工资不高。","py":"Sān nián qián wǒ zài Shànghǎi gōngzuò, dāngshí de gōngzī bù gāo.","vi":"Ba năm trước tôi làm việc ở Thượng Hải, lương lúc đó không cao.","en":"Three years ago I worked in Shanghai, and the salary then wasn't high."},{"use":"đứng sau chủ ngữ: 他当时 + ...","ex":"他说他当时太忙，没有时间给我打电话。","py":"Tā shuō tā dāngshí tài máng, méiyǒu shíjiān gěi wǒ dǎ diànhuà.","vi":"Anh ấy nói lúc đó anh ấy quá bận nên không có thời gian gọi điện cho tôi.","en":"He said he was too busy at the time to call me."}]},"父母":{"en":"parents; father and mother","exs":[{"use":"làm chủ ngữ: 我父母 + V","ex":"我父母住在乡下。","py":"Wǒ fùmǔ zhù zài xiāngxia.","vi":"Bố mẹ tôi sống ở quê.","en":"My parents live in the countryside."},{"use":"làm chủ ngữ, đi với 都希望","ex":"父母都希望孩子健康快乐。","py":"Fùmǔ dōu xīwàng háizi jiànkāng kuàilè.","vi":"Bố mẹ đều mong con cái khỏe mạnh vui vẻ.","en":"Parents all hope their children are healthy and happy."},{"use":"làm tân ngữ của 看望/照顾","ex":"周末我常常回家看望父母。","py":"Zhōumò wǒ chángcháng huí jiā kànwàng fùmǔ.","vi":"Cuối tuần tôi thường về nhà thăm bố mẹ.","en":"On weekends I often go home to visit my parents."},{"use":"cấu trúc 在父母面前 (trước mặt bố mẹ)","ex":"孩子在父母面前总是很放松。","py":"Háizi zài fùmǔ miànqián zǒngshì hěn fàngsōng.","vi":"Con cái trước mặt bố mẹ lúc nào cũng thoải mái.","en":"Children always feel relaxed in front of their parents."}]},"亲戚":{"en":"relative; relatives","exs":[{"use":"làm tân ngữ của 看/拜访 (thăm họ hàng)","ex":"春节的时候，我们去看亲戚。","py":"Chūnjié de shíhou, wǒmen qù kàn qīnqi.","vi":"Dịp Tết, chúng tôi đi thăm họ hàng.","en":"During the Spring Festival, we visit relatives."},{"use":"cấu trúc 有 + 亲戚 + ở nơi nào","ex":"他在国外有很多亲戚。","py":"Tā zài guówài yǒu hěn duō qīnqi.","vi":"Anh ấy có rất nhiều họ hàng ở nước ngoài.","en":"He has many relatives abroad."},{"use":"dùng với lượng từ 一个 chỉ một người họ hàng","ex":"我有一个亲戚在医院工作。","py":"Wǒ yǒu yí ge qīnqi zài yīyuàn gōngzuò.","vi":"Tôi có một người họ hàng làm việc ở bệnh viện.","en":"I have a relative who works at a hospital."},{"use":"thêm 们 chỉ số nhiều","ex":"过年时亲戚们都聚在一起。","py":"Guònián shí qīnqimen dōu jù zài yìqǐ.","vi":"Dịp năm mới, họ hàng đều tụ họp lại với nhau.","en":"At New Year, all the relatives get together."}]},"所有人":{"en":"everyone; all people","exs":[{"use":"làm chủ ngữ, thường đi với 都","ex":"所有人都同意这个办法。","py":"Suǒyǒu rén dōu tóngyì zhège bànfǎ.","vi":"Tất cả mọi người đều đồng ý cách này.","en":"Everyone agrees with this method."},{"use":"làm tân ngữ sau 让 (khiến mọi người)","ex":"他的笑话让所有人都笑了。","py":"Tā de xiàohua ràng suǒyǒu rén dōu xiào le.","vi":"Câu chuyện cười của anh ấy khiến mọi người đều bật cười.","en":"His joke made everyone laugh."},{"use":"làm chủ ngữ trong câu mệnh lệnh, mong muốn","ex":"老师希望所有人明天都按时来。","py":"Lǎoshī xīwàng suǒyǒu rén míngtiān dōu ànshí lái.","vi":"Thầy giáo mong tất cả mọi người ngày mai đều đến đúng giờ.","en":"The teacher hopes everyone will come on time tomorrow."},{"use":"phủ định bộ phận: 不是所有人都...","ex":"这件事不是所有人都知道。","py":"Zhè jiàn shì bú shì suǒyǒu rén dōu zhīdào.","vi":"Chuyện này không phải ai cũng biết.","en":"Not everyone knows about this."}]},"正确":{"en":"correct; right; proper","exs":[{"use":"正确的 + danh từ.","ex":"这是正确的方法。","py":"Zhè shì zhèngquè de fāngfǎ.","vi":"Đúng đắn","en":"This is the correct method."},{"use":"làm vị ngữ, thường có 完全/非常","ex":"你的答案完全正确。","py":"Nǐ de dá'àn wánquán zhèngquè.","vi":"Đáp án của bạn hoàn toàn chính xác.","en":"Your answer is completely correct."},{"use":"làm định ngữ: 选择正确的 + N","ex":"请选择正确的答案。","py":"Qǐng xuǎnzé zhèngquè de dá'àn.","vi":"Xin hãy chọn đáp án đúng.","en":"Please choose the correct answer."},{"use":"làm trạng ngữ: 正确 + V","ex":"只有正确使用方法，药才有效。","py":"Zhǐyǒu zhèngquè shǐyòng fāngfǎ, yào cái yǒuxiào.","vi":"Chỉ khi dùng đúng cách thì thuốc mới có hiệu quả.","en":"The medicine works only if you use it correctly."},{"use":"V + 得 + 正确 (bổ ngữ trạng thái)","ex":"你的发音读得很正确。","py":"Nǐ de fāyīn dú de hěn zhèngquè.","vi":"Phát âm của bạn đọc rất chuẩn.","en":"You pronounce it very correctly."}]},"理想":{"en":"ideal; dream; aspiration; ideal (adj)","exs":[{"use":"làm danh từ: ước mơ, lý tưởng; hỏi 理想是什么","ex":"你的理想是什么？","py":"Nǐ de lǐxiǎng shì shénme?","vi":"Lý tưởng của bạn là gì?","en":"What is your ideal (dream)?"},{"use":"cấu trúc 我的理想是 + V/O","ex":"我的理想是当一名医生。","py":"Wǒ de lǐxiǎng shì dāng yì míng yīshēng.","vi":"Lý tưởng của tôi là trở thành một bác sĩ.","en":"My dream is to become a doctor."},{"use":"làm tính từ: lý tưởng, vừa ý (thường phủ định)","ex":"这份工作不太理想，工资太低。","py":"Zhè fèn gōngzuò bú tài lǐxiǎng, gōngzī tài dī.","vi":"Công việc này không lý tưởng lắm, lương quá thấp.","en":"This job is not ideal; the salary is too low."},{"use":"cấu trúc 实现理想 (thực hiện lý tưởng)","ex":"为了实现理想，他每天都努力学习。","py":"Wèile shíxiàn lǐxiǎng, tā měitiān dōu nǔlì xuéxí.","vi":"Để thực hiện lý tưởng, ngày nào anh ấy cũng nỗ lực học tập.","en":"To realize his dream, he studies hard every day."}]},"聪明":{"en":"smart; intelligent; clever","exs":[{"use":"làm vị ngữ: 很 + 聪明","ex":"这个孩子很聪明。","py":"Zhège háizi hěn cōngmíng.","vi":"Đứa bé này rất thông minh.","en":"This child is very smart."},{"use":"kết hợp với 又...: thông minh lại chăm chỉ","ex":"他聪明又努力，成绩一直很好。","py":"Tā cōngmíng yòu nǔlì, chéngjì yìzhí hěn hǎo.","vi":"Anh ấy vừa thông minh vừa chăm chỉ, thành tích luôn rất tốt.","en":"He is both smart and hardworking, and his grades have always been good."},{"use":"dùng để khen: 你真聪明","ex":"你真聪明，一下子就想出了办法。","py":"Nǐ zhēn cōngmíng, yíxiàzi jiù xiǎng chū le bànfǎ.","vi":"Bạn thông minh thật, chớp mắt đã nghĩ ra cách.","en":"You're so clever; you came up with a solution right away."},{"use":"làm định ngữ: 聪明的 + N","ex":"聪明的人也需要努力。","py":"Cōngmíng de rén yě xūyào nǔlì.","vi":"Người thông minh cũng cần phải nỗ lực.","en":"Smart people also need to work hard."}]},"学会":{"en":"to learn (how to); to master","exs":[{"use":"V + 会 (bổ ngữ kết quả): học được","ex":"我学会了做中国菜。","py":"Wǒ xuéhuì le zuò Zhōngguó cài.","vi":"Tôi đã học được cách nấu món Trung Quốc.","en":"I have learned how to cook Chinese food."},{"use":"学会 + V: học được một kỹ năng","ex":"他三岁就学会了游泳。","py":"Tā sān suì jiù xuéhuì le yóuyǒng.","vi":"Anh ấy ba tuổi đã biết bơi.","en":"He learned to swim at the age of three."},{"use":"câu hỏi với 了吗","ex":"你学会开车了吗？","py":"Nǐ xuéhuì kāichē le ma?","vi":"Bạn đã học lái xe được chưa?","en":"Have you learned to drive yet?"},{"use":"学会 + 照顾/自己...: học cách (nghĩa mở rộng)","ex":"孩子要学会照顾自己。","py":"Háizi yào xuéhuì zhàogù zìjǐ.","vi":"Trẻ con cần học cách tự chăm sóc bản thân.","en":"Children need to learn to take care of themselves."},{"use":"dạng phủ định: 没学会","ex":"这个字我还没学会写。","py":"Zhège zì wǒ hái méi xuéhuì xiě.","vi":"Chữ này tôi vẫn chưa học viết được.","en":"I still haven't learned to write this character."}]},"获得成功":{"en":"to achieve success; to succeed","exs":[{"use":"cấu trúc 能 + 获得成功","ex":"只要努力，你一定能获得成功。","py":"Zhǐyào nǔlì, nǐ yídìng néng huòdé chénggōng.","vi":"Chỉ cần nỗ lực, bạn nhất định sẽ giành được thành công.","en":"As long as you work hard, you will definitely succeed."},{"use":"在 + lĩnh vực + 获得成功","ex":"他在生意上获得成功。","py":"Tā zài shēngyi shàng huòdé chénggōng.","vi":"Anh ấy thành công trong kinh doanh.","en":"He succeeded in business."},{"use":"要 + 获得成功 (muốn thành công thì...)","ex":"要获得成功，不但要努力，还要有好的方法。","py":"Yào huòdé chénggōng, búdàn yào nǔlì, hái yào yǒu hǎo de fāngfǎ.","vi":"Muốn thành công, không chỉ phải nỗ lực mà còn phải có phương pháp tốt.","en":"To succeed, you need not only effort but also good methods."},{"use":"就 + 获得成功: thành công ngay lần đầu","ex":"第一次开店就获得成功，他非常高兴。","py":"Dì yī cì kāi diàn jiù huòdé chénggōng, tā fēicháng gāoxìng.","vi":"Mở cửa hàng lần đầu đã thành công, anh ấy rất vui.","en":"He opened a shop for the first time and succeeded right away, which made him very happy."}]},"经济":{"en":"economy; (financial) means; economic","exs":[{"use":"danh từ: nền kinh tế","ex":"中国的经济发展得很快。","py":"Zhōngguó de jīngjì fāzhǎn de hěn kuài.","vi":"Kinh tế Trung Quốc phát triển rất nhanh.","en":"China's economy is developing quickly."},{"use":"làm tân ngữ: học ngành kinh tế","ex":"他在大学学经济。","py":"Tā zài dàxué xué jīngjì.","vi":"Anh ấy học kinh tế ở đại học.","en":"He studies economics at university."},{"use":"nói về tình hình chung","ex":"最近经济不太好，找工作很难。","py":"Zuìjìn jīngjì bú tài hǎo, zhǎo gōngzuò hěn nán.","vi":"Gần đây kinh tế không tốt lắm, tìm việc rất khó.","en":"The economy hasn't been good lately, and finding a job is hard."},{"use":"nghĩa tài chính gia đình: 经济条件","ex":"我们家的经济条件还不错。","py":"Wǒmen jiā de jīngjì tiáojiàn hái búcuò.","vi":"Điều kiện kinh tế gia đình chúng tôi cũng khá tốt.","en":"Our family's financial situation is quite good."}]},"条件":{"en":"condition; requirement; circumstances","exs":[{"use":"nghĩa điều kiện sống, hoàn cảnh","ex":"这个城市的生活条件很好。","py":"Zhège chéngshì de shēnghuó tiáojiàn hěn hǎo.","vi":"Điều kiện sống ở thành phố này rất tốt.","en":"The living conditions in this city are very good."},{"use":"nghĩa điều kiện đặt ra trong thỏa thuận","ex":"我有一个条件：你必须按时完成。","py":"Wǒ yǒu yí ge tiáojiàn: nǐ bìxū ànshí wánchéng.","vi":"Tôi có một điều kiện: bạn phải hoàn thành đúng hạn.","en":"I have one condition: you must finish on time."},{"use":"nghĩa yêu cầu, tiêu chuẩn (tuyển dụng)","ex":"这份工作要求什么条件？","py":"Zhè fèn gōngzuò yāoqiú shénme tiáojiàn?","vi":"Công việc này yêu cầu những điều kiện gì?","en":"What requirements does this job have?"},{"use":"cấu trúc 在...条件下 (trong điều kiện...)","ex":"在这样的条件下，他还是完成了任务。","py":"Zài zhèyàng de tiáojiàn xià, tā háishi wánchéng le rènwu.","vi":"Trong điều kiện như vậy, anh ấy vẫn hoàn thành nhiệm vụ.","en":"Under such conditions, he still completed the task."}]},"富人":{"en":"rich people; the wealthy","exs":[{"use":"làm chủ ngữ, so sánh với 穷人","ex":"富人不一定比穷人快乐。","py":"Fùrén bù yídìng bǐ qióngrén kuàilè.","vi":"Người giàu chưa chắc đã vui hơn người nghèo.","en":"Rich people are not necessarily happier than poor people."},{"use":"làm tân ngữ: 住着很多富人","ex":"这个小区住着很多富人。","py":"Zhège xiǎoqū zhù zhe hěn duō fùrén.","vi":"Khu dân cư này có rất nhiều người giàu sinh sống.","en":"Many wealthy people live in this neighborhood."},{"use":"làm chủ ngữ với 应该 (nêu quan điểm)","ex":"富人应该多帮助别人。","py":"Fùrén yīnggāi duō bāngzhù biérén.","vi":"Người giàu nên giúp đỡ người khác nhiều hơn.","en":"Rich people should help others more."},{"use":"dạng phủ định: 不是富人","ex":"他不是富人，但生活得很幸福。","py":"Tā bú shì fùrén, dàn shēnghuó de hěn xìngfú.","vi":"Anh ấy không phải người giàu, nhưng sống rất hạnh phúc.","en":"He is not rich, but he lives a very happy life."}]},"穷人":{"en":"poor people; the poor","exs":[{"use":"làm định ngữ trong 穷人家庭 (gia đình nghèo)","ex":"他出生在一个穷人家庭。","py":"Tā chūshēng zài yí ge qióngrén jiātíng.","vi":"Anh ấy sinh ra trong một gia đình nghèo.","en":"He was born into a poor family."},{"use":"làm tân ngữ của 帮助","ex":"这家医院免费帮助穷人看病。","py":"Zhè jiā yīyuàn miǎnfèi bāngzhù qióngrén kànbìng.","vi":"Bệnh viện này khám bệnh miễn phí giúp đỡ người nghèo.","en":"This hospital helps poor people see a doctor for free."},{"use":"làm chủ ngữ + 也 (người nghèo cũng...)","ex":"穷人也有自己的快乐。","py":"Qióngrén yě yǒu zìjǐ de kuàilè.","vi":"Người nghèo cũng có niềm vui riêng của họ.","en":"Poor people also have their own happiness."},{"use":"cấu trúc 把...给了穷人","ex":"那位老人把钱都给了穷人。","py":"Nà wèi lǎorén bǎ qián dōu gěi le qióngrén.","vi":"Cụ già đó đã đem hết tiền cho người nghèo.","en":"That old man gave all his money to the poor."}]},"由于":{"en":"because of; due to; owing to","exs":[{"use":"đứng đầu câu chỉ nguyên nhân: 由于 + N/V，...","ex":"由于下大雨，比赛取消了。","py":"Yóuyú xià dàyǔ, bǐsài qǔxiāo le.","vi":"Do trời mưa to nên trận đấu bị hủy.","en":"Due to heavy rain, the match was canceled."},{"use":"由于 + nguyên nhân，只/没能 + kết quả","ex":"由于时间不够，我们只参观了一个地方。","py":"Yóuyú shíjiān búgòu, wǒmen zhǐ cānguān le yí ge dìfang.","vi":"Vì không đủ thời gian nên chúng tôi chỉ tham quan một nơi.","en":"Because there wasn't enough time, we visited only one place."},{"use":"đứng sau chủ ngữ: 他由于 + ...","ex":"他由于生病，没能参加会议。","py":"Tā yóuyú shēngbìng, méi néng cānjiā huìyì.","vi":"Vì bị ốm nên anh ấy không thể tham dự cuộc họp.","en":"Because of illness, he couldn't attend the meeting."},{"use":"cặp 由于...所以...","ex":"由于路上堵车，所以他迟到了。","py":"Yóuyú lùshang dǔchē, suǒyǐ tā chídào le.","vi":"Do tắc đường nên anh ấy đến muộn.","en":"Because of the traffic jam, he was late."}]},"小时候":{"en":"in childhood; when one was a child","exs":[{"use":"làm trạng ngữ thời gian đầu câu","ex":"小时候，我家住在农村。","py":"Xiǎoshíhou, wǒ jiā zhù zài nóngcūn.","vi":"Hồi nhỏ, nhà tôi ở nông thôn.","en":"When I was little, my family lived in the countryside."},{"use":"đứng sau chủ ngữ: 我小时候 + ...","ex":"我小时候很怕打针。","py":"Wǒ xiǎoshíhou hěn pà dǎzhēn.","vi":"Hồi nhỏ tôi rất sợ tiêm.","en":"I was very afraid of getting shots as a child."},{"use":"dùng trong câu hỏi về quá khứ","ex":"你小时候最喜欢玩什么？","py":"Nǐ xiǎoshíhou zuì xǐhuan wán shénme?","vi":"Hồi nhỏ bạn thích chơi gì nhất?","en":"What did you like to play most when you were a kid?"},{"use":"cấu trúc 小时候的 + N (định ngữ)","ex":"他小时候的梦想是当飞行员。","py":"Tā xiǎoshíhou de mèngxiǎng shì dāng fēixíngyuán.","vi":"Ước mơ hồi nhỏ của anh ấy là làm phi công.","en":"His childhood dream was to be a pilot."}]},"橡皮":{"en":"eraser; rubber","exs":[{"use":"nghĩa 1: cục tẩy; làm chủ ngữ/tân ngữ","ex":"我的橡皮找不到了。","py":"Wǒ de xiàngpí zhǎo bú dào le.","vi":"Cục tẩy của tôi không tìm thấy nữa.","en":"I can't find my eraser."},{"use":"dùng với 用...擦掉 (dùng tẩy xóa đi)","ex":"写错了就用橡皮擦掉。","py":"Xiě cuò le jiù yòng xiàngpí cā diào.","vi":"Viết sai thì dùng tẩy xóa đi.","en":"If you write something wrong, erase it with an eraser."},{"use":"lượng từ 块: 一块橡皮","ex":"能借我一块橡皮吗？","py":"Néng jiè wǒ yí kuài xiàngpí ma?","vi":"Cho tôi mượn một cục tẩy được không?","en":"Could I borrow an eraser?"},{"use":"nghĩa 2: cao su (chất liệu)","ex":"这个玩具是用橡皮做的。","py":"Zhège wánjù shì yòng xiàngpí zuò de.","vi":"Món đồ chơi này làm bằng cao su.","en":"This toy is made of rubber."}]},"长大":{"en":"to grow up","exs":[{"use":"cấu trúc 长大以后 + ... (sau khi lớn lên)","ex":"我长大以后想当老师。","py":"Wǒ zhǎngdà yǐhòu xiǎng dāng lǎoshī.","vi":"Sau khi lớn lên tôi muốn làm giáo viên.","en":"When I grow up, I want to be a teacher."},{"use":"cấu trúc 一天天 + 长大了","ex":"孩子们一天天长大了。","py":"Háizimen yì tiān tiān zhǎngdà le.","vi":"Bọn trẻ ngày một lớn lên.","en":"The children are growing up day by day."},{"use":"在 + nơi chốn + 长大","ex":"他在农村长大，很会干农活。","py":"Tā zài nóngcūn zhǎngdà, hěn huì gàn nónghuó.","vi":"Anh ấy lớn lên ở nông thôn, rất giỏi làm việc đồng áng.","en":"He grew up in the countryside and is good at farm work."},{"use":"等 + 你 + 长大 (đợi khi con lớn)","ex":"等你长大就明白了。","py":"Děng nǐ zhǎngdà jiù míngbai le.","vi":"Đợi khi con lớn lên sẽ hiểu thôi.","en":"You'll understand when you grow up."}]},"幸福感":{"en":"sense of happiness; feeling of well-being","exs":[{"use":"cấu trúc 有 + 幸福感","ex":"有家人在身边，我很有幸福感。","py":"Yǒu jiārén zài shēnbiān, wǒ hěn yǒu xìngfúgǎn.","vi":"Có người nhà bên cạnh, tôi cảm thấy rất hạnh phúc.","en":"With my family beside me, I feel a strong sense of happiness."},{"use":"làm tân ngữ của 提高","ex":"钱多不一定能提高幸福感。","py":"Qián duō bù yídìng néng tígāo xìngfúgǎn.","vi":"Nhiều tiền chưa chắc đã nâng cao cảm giác hạnh phúc.","en":"Having more money doesn't necessarily raise your sense of happiness."},{"use":"làm tân ngữ của 带来","ex":"一杯热茶也能带来幸福感。","py":"Yì bēi rè chá yě néng dàilái xìngfúgǎn.","vi":"Một tách trà nóng cũng có thể mang lại cảm giác hạnh phúc.","en":"Even a cup of hot tea can bring a sense of happiness."},{"use":"làm chủ ngữ: 幸福感 + 很高","ex":"这个城市居民的幸福感很高。","py":"Zhège chéngshì jūmín de xìngfúgǎn hěn gāo.","vi":"Cảm giác hạnh phúc của cư dân thành phố này rất cao.","en":"The residents of this city have a high sense of well-being."}]},"高低":{"en":"height; level; high and low; (win or lose)","exs":[{"use":"nghĩa cao thấp (độ cao)","ex":"这两座山的高低差不多。","py":"Zhè liǎng zuò shān de gāodī chàbuduō.","vi":"Hai ngọn núi này cao thấp gần như nhau.","en":"These two mountains are about the same height."},{"use":"nghĩa cao thấp của âm thanh","ex":"唱歌的时候，声音高低要有变化。","py":"Chànggē de shíhou, shēngyīn gāodī yào yǒu biànhuà.","vi":"Khi hát, độ cao thấp của giọng phải có sự thay đổi.","en":"When singing, the pitch should vary."},{"use":"不管 + N + 高低 (bất kể cao thấp)","ex":"不管职位高低，大家都要遵守规定。","py":"Bùguǎn zhíwèi gāodī, dàjiā dōu yào zūnshǒu guīdìng.","vi":"Bất kể chức vụ cao hay thấp, mọi người đều phải tuân thủ quy định.","en":"Regardless of rank, everyone must follow the rules."},{"use":"cấu trúc 分出高低 (phân thắng bại)","ex":"他们俩比了一场，想分出高低。","py":"Tāmen liǎ bǐ le yì chǎng, xiǎng fēn chū gāodī.","vi":"Hai người họ đấu một trận để phân cao thấp.","en":"The two of them had a match to see who was better."}]},"标准答案":{"en":"standard answer; model answer","exs":[{"use":"cấu trúc 没有标准答案","ex":"这道题没有标准答案。","py":"Zhè dào tí méiyǒu biāozhǔn dá'àn.","vi":"Câu hỏi này không có đáp án chuẩn.","en":"This question has no standard answer."},{"use":"làm tân ngữ của 给 (cho đáp án)","ex":"考试结束后，老师会给大家标准答案。","py":"Kǎoshì jiéshù hòu, lǎoshī huì gěi dàjiā biāozhǔn dá'àn.","vi":"Sau khi thi xong, giáo viên sẽ đưa đáp án chuẩn cho mọi người.","en":"After the exam, the teacher will give everyone the standard answers."},{"use":"nghĩa mở rộng: vấn đề cuộc sống","ex":"生活中的很多问题没有标准答案。","py":"Shēnghuó zhōng de hěn duō wèntí méiyǒu biāozhǔn dá'àn.","vi":"Nhiều vấn đề trong cuộc sống không có đáp án chuẩn.","en":"Many problems in life have no standard answer."},{"use":"cấu trúc 把...和标准答案对","ex":"我把我的答案和标准答案对了一下。","py":"Wǒ bǎ wǒ de dá'àn hé biāozhǔn dá'àn duì le yíxià.","vi":"Tôi đối chiếu đáp án của mình với đáp án chuẩn.","en":"I checked my answers against the standard answers."}]},"房子":{"en":"house; building; apartment","exs":[{"use":"lượng từ 套: 一套房子","ex":"他们新买了一套房子。","py":"Tāmen xīn mǎi le yí tào fángzi.","vi":"Họ vừa mua một căn nhà mới.","en":"They just bought a new house."},{"use":"lượng từ 所: 这所房子","ex":"这所房子很旧，但是很安静。","py":"Zhè suǒ fángzi hěn jiù, dànshì hěn ānjìng.","vi":"Căn nhà này rất cũ nhưng rất yên tĩnh.","en":"This house is old but very quiet."},{"use":"làm tân ngữ của 租 (thuê nhà)","ex":"我想租一间离公司近的房子。","py":"Wǒ xiǎng zū yì jiān lí gōngsī jìn de fángzi.","vi":"Tôi muốn thuê một căn nhà gần công ty.","en":"I want to rent a place close to the company."},{"use":"nói về giá cả: 越来越贵","ex":"现在的房子越来越贵了。","py":"Xiànzài de fángzi yuèláiyuè guì le.","vi":"Nhà bây giờ ngày càng đắt.","en":"Houses are getting more and more expensive these days."}]},"比如":{"en":"for example; such as","exs":[{"use":"đưa ví dụ liệt kê: 比如 + A、B","ex":"我喜欢运动，比如游泳、跑步。","py":"Wǒ xǐhuan yùndòng, bǐrú yóuyǒng, pǎobù.","vi":"Tôi thích thể thao, ví dụ như bơi lội, chạy bộ.","en":"I like sports, such as swimming and running."},{"use":"đứng sau mệnh đề chung để minh họa","ex":"很多水果我都爱吃，比如苹果和香蕉。","py":"Hěn duō shuǐguǒ wǒ dōu ài chī, bǐrú píngguǒ hé xiāngjiāo.","vi":"Nhiều loại trái cây tôi đều thích ăn, ví dụ táo và chuối.","en":"I like many fruits, for example apples and bananas."},{"use":"dạng 比如说 (chẳng hạn như)","ex":"比如说，你可以先打个电话问问。","py":"Bǐrú shuō, nǐ kěyǐ xiān dǎ ge diànhuà wènwen.","vi":"Chẳng hạn, bạn có thể gọi điện hỏi trước.","en":"For example, you could call and ask first."},{"use":"đưa ví dụ về địa danh","ex":"中国有很多有名的城市，比如北京、上海。","py":"Zhōngguó yǒu hěn duō yǒumíng de chéngshì, bǐrú Běijīng, Shànghǎi.","vi":"Trung Quốc có nhiều thành phố nổi tiếng, ví dụ Bắc Kinh, Thượng Hải.","en":"China has many famous cities, such as Beijing and Shanghai."}]},"礼拜天":{"en":"Sunday","exs":[{"use":"làm trạng ngữ thời gian: 礼拜天 + V","ex":"礼拜天我们一起去公园玩儿吧。","py":"Lǐbàitiān wǒmen yìqǐ qù gōngyuán wánr ba.","vi":"Chủ nhật chúng ta cùng đi chơi công viên nhé.","en":"Let's go to the park together on Sunday."},{"use":"dạng phủ định: 从不 + V","ex":"他礼拜天从不加班。","py":"Tā lǐbàitiān cóng bù jiābān.","vi":"Chủ nhật anh ấy không bao giờ tăng ca.","en":"He never works overtime on Sundays."},{"use":"下个礼拜天 (Chủ nhật tuần sau)","ex":"下个礼拜天是我的生日。","py":"Xià ge lǐbàitiān shì wǒ de shēngrì.","vi":"Chủ nhật tuần sau là sinh nhật tôi.","en":"Next Sunday is my birthday."},{"use":"cách nói khẩu ngữ, tương đương 星期天","ex":"礼拜天商店里人很多。","py":"Lǐbàitiān shāngdiàn lǐ rén hěn duō.","vi":"Chủ nhật trong cửa hàng rất đông người.","en":"There are lots of people in the shops on Sundays."}]},"生日礼物":{"en":"birthday present; birthday gift","exs":[{"use":"cấu trúc 送 + người + 生日礼物","ex":"这是我送你的生日礼物。","py":"Zhè shì wǒ sòng nǐ de shēngrì lǐwù.","vi":"Đây là quà sinh nhật tôi tặng bạn.","en":"This is the birthday present I'm giving you."},{"use":"lượng từ 份: 一份生日礼物","ex":"妈妈给我买了一份生日礼物。","py":"Māma gěi wǒ mǎi le yí fèn shēngrì lǐwù.","vi":"Mẹ mua cho tôi một món quà sinh nhật.","en":"Mom bought me a birthday present."},{"use":"câu hỏi với 什么","ex":"你想要什么生日礼物？","py":"Nǐ xiǎng yào shénme shēngrì lǐwù?","vi":"Bạn muốn quà sinh nhật gì?","en":"What birthday gift do you want?"},{"use":"dùng trong câu có 还没...","ex":"我还没想好给他买什么生日礼物。","py":"Wǒ hái méi xiǎng hǎo gěi tā mǎi shénme shēngrì lǐwù.","vi":"Tôi vẫn chưa nghĩ ra nên mua quà sinh nhật gì cho anh ấy.","en":"I haven't decided what birthday gift to buy him."}]},"上有老":{"en":"having elderly parents to support (above)","exs":[{"use":"thành ngữ 上有老，下有小: gánh nặng gia đình","ex":"他上有老，下有小，压力很大。","py":"Tā shàng yǒu lǎo, xià yǒu xiǎo, yālì hěn dà.","vi":"Anh ấy trên có cha mẹ già, dưới có con nhỏ, áp lực rất lớn.","en":"He has elderly parents and young children to support, so he is under great pressure."},{"use":"nói về thế hệ trung niên","ex":"我们这一代人上有老，下有小，每天都很忙。","py":"Wǒmen zhè yí dài rén shàng yǒu lǎo, xià yǒu xiǎo, měitiān dōu hěn máng.","vi":"Thế hệ chúng tôi trên có cha mẹ già, dưới có con nhỏ, ngày nào cũng bận rộn.","en":"Our generation has both parents and children to look after, and we are busy every day."},{"use":"dùng riêng 上有老 làm vế đầu, giải thích lý do","ex":"上有老要照顾，所以他不敢随便换工作。","py":"Shàng yǒu lǎo yào zhàogù, suǒyǐ tā bù gǎn suíbiàn huàn gōngzuò.","vi":"Trên còn cha mẹ già cần chăm sóc, nên anh ấy không dám tùy tiện đổi việc.","en":"With elderly parents to care for, he doesn't dare change jobs casually."}]},"下有小":{"en":"having young children to raise (below)","exs":[{"use":"dùng riêng 下有小 làm lý do","ex":"他下有小，不能随便辞职。","py":"Tā xià yǒu xiǎo, bù néng suíbiàn cízhí.","vi":"Anh ấy dưới còn con nhỏ, không thể tùy tiện nghỉ việc.","en":"With young children to support, he can't just quit."},{"use":"thành ngữ 上有老，下有小","ex":"上有老，下有小，他不得不努力工作。","py":"Shàng yǒu lǎo, xià yǒu xiǎo, tā bùdébù nǔlì gōngzuò.","vi":"Trên có cha mẹ già, dưới có con nhỏ, anh ấy buộc phải làm việc chăm chỉ.","en":"With parents above and children below to support, he has to work hard."},{"use":"cấu trúc 我 + 下有小 + giải thích chi phí","ex":"我下有小，每个月都要给孩子交学费。","py":"Wǒ xià yǒu xiǎo, měi ge yuè dōu yào gěi háizi jiāo xuéfèi.","vi":"Tôi dưới có con nhỏ, tháng nào cũng phải đóng học phí cho con.","en":"I have young kids, so I have to pay tuition every month."}]},"除了":{"en":"besides; except; apart from","exs":[{"use":"cấu trúc 除了...还...: ngoài ra còn","ex":"除了英语，我还会说汉语。","py":"Chúle Yīngyǔ, wǒ hái huì shuō Hànyǔ.","vi":"Ngoài tiếng Anh, tôi còn biết nói tiếng Trung.","en":"Besides English, I can also speak Chinese."},{"use":"cấu trúc 除了...都...: ngoại trừ","ex":"除了小王，大家都来了。","py":"Chúle Xiǎo Wáng, dàjiā dōu lái le.","vi":"Ngoại trừ Tiểu Vương, mọi người đều đến cả.","en":"Everyone came except Xiao Wang."},{"use":"除了 + thời gian + 都/每天","ex":"除了周末，我每天都要上班。","py":"Chúle zhōumò, wǒ měitiān dōu yào shàngbān.","vi":"Trừ cuối tuần ra, ngày nào tôi cũng phải đi làm.","en":"Except for weekends, I go to work every day."},{"use":"cấu trúc 除了...以外，还...","ex":"除了听音乐以外，我还喜欢看电影。","py":"Chúle tīng yīnyuè yǐwài, wǒ hái xǐhuan kàn diànyǐng.","vi":"Ngoài nghe nhạc ra, tôi còn thích xem phim.","en":"Besides listening to music, I also like watching movies."}]},"以外":{"en":"outside; beyond; besides","exs":[{"use":"cấu trúc 除了...以外，还...","ex":"除了苹果以外，我还买了香蕉。","py":"Chúle píngguǒ yǐwài, wǒ hái mǎi le xiāngjiāo.","vi":"Ngoài táo ra, tôi còn mua chuối.","en":"Besides apples, I also bought bananas."},{"use":"chỉ vị trí: N + 以外 (bên ngoài)","ex":"学校以外有一家小书店。","py":"Xuéxiào yǐwài yǒu yì jiā xiǎo shūdiàn.","vi":"Bên ngoài trường có một hiệu sách nhỏ.","en":"There is a small bookstore outside the school."},{"use":"chỉ khoảng cách: số lượng + 以外","ex":"三公里以外就是海边。","py":"Sān gōnglǐ yǐwài jiùshì hǎibiān.","vi":"Cách ba cây số là biển.","en":"The seaside is three kilometers away."},{"use":"cấu trúc 除...以外，没有人...","ex":"除你以外，没有人知道这件事。","py":"Chú nǐ yǐwài, méiyǒu rén zhīdào zhè jiàn shì.","vi":"Ngoài bạn ra, không ai biết chuyện này.","en":"Apart from you, nobody knows about this."}]},"母亲":{"en":"mother","exs":[{"use":"làm định ngữ chỉ quan hệ: 我的母亲","ex":"我的母亲是一位老师。","py":"Wǒ de mǔqīn shì yí wèi lǎoshī.","vi":"Mẹ tôi là một giáo viên.","en":"My mother is a teacher."},{"use":"làm chủ ngữ, văn viết/trang trọng hơn 妈妈","ex":"母亲每天都为家人做饭。","py":"Mǔqīn měitiān dōu wèi jiārén zuòfàn.","vi":"Ngày nào mẹ cũng nấu cơm cho cả nhà.","en":"Mother cooks for the family every day."},{"use":"trong từ 母亲节 (Ngày của Mẹ)","ex":"五月的第二个星期日是母亲节。","py":"Wǔ yuè de dì èr ge xīngqīrì shì Mǔqīn Jié.","vi":"Chủ nhật thứ hai của tháng Năm là Ngày của Mẹ.","en":"The second Sunday in May is Mother's Day."},{"use":"làm tân ngữ có định ngữ: 伟大的母亲","ex":"她是一位伟大的母亲。","py":"Tā shì yí wèi wěidà de mǔqīn.","vi":"Bà ấy là một người mẹ vĩ đại.","en":"She is a great mother."}]},"儿子":{"en":"son","exs":[{"use":"nói về số con: 一个儿子和一个女儿","ex":"他有一个儿子和一个女儿。","py":"Tā yǒu yí ge érzi hé yí ge nǚ'ér.","vi":"Anh ấy có một con trai và một con gái.","en":"He has one son and one daughter."},{"use":"cấu trúc 我儿子 + 今年...岁","ex":"我儿子今年五岁了。","py":"Wǒ érzi jīnnián wǔ suì le.","vi":"Con trai tôi năm nay năm tuổi.","en":"My son is five this year."},{"use":"làm chủ ngữ, 正在 + V","ex":"儿子正在房间里写作业。","py":"Érzi zhèngzài fángjiān lǐ xiě zuòyè.","vi":"Con trai đang làm bài tập trong phòng.","en":"My son is doing homework in his room."},{"use":"cấu trúc 为/给 + 儿子 + V","ex":"她为儿子准备了生日礼物。","py":"Tā wèi érzi zhǔnbèi le shēngrì lǐwù.","vi":"Cô ấy chuẩn bị quà sinh nhật cho con trai.","en":"She prepared a birthday gift for her son."}]},"照顾":{"en":"to take care of; to look after","exs":[{"use":"照顾 + người (chăm sóc người thân)","ex":"妈妈生病了，我要照顾她。","py":"Māma shēngbìng le, wǒ yào zhàogù tā.","vi":"Mẹ bị ốm, tôi phải chăm sóc mẹ.","en":"Mom is sick, so I have to take care of her."},{"use":"cảm ơn vì đã chăm sóc","ex":"谢谢你照顾我的孩子。","py":"Xièxie nǐ zhàogù wǒ de háizi.","vi":"Cảm ơn bạn đã chăm sóc con tôi.","en":"Thank you for taking care of my child."},{"use":"lời nói lịch sự: 请多多照顾","ex":"我刚来公司，请大家多多照顾。","py":"Wǒ gāng lái gōngsī, qǐng dàjiā duōduō zhàogù.","vi":"Tôi mới vào công ty, mong mọi người giúp đỡ nhiều.","en":"I just joined the company; please look after me."},{"use":"V + 好 (bổ ngữ kết quả) / 很难 + 照顾好","ex":"他一个人很难照顾好两个孩子。","py":"Tā yí ge rén hěn nán zhàogù hǎo liǎng ge háizi.","vi":"Một mình anh ấy rất khó chăm sóc tốt hai đứa trẻ.","en":"It is hard for him to take good care of two kids alone."}]},"脸色":{"en":"complexion; facial expression","exs":[{"use":"nghĩa sắc mặt (sức khỏe)","ex":"你脸色不好，是不是生病了？","py":"Nǐ liǎnsè bù hǎo, shì bu shì shēngbìng le?","vi":"Sắc mặt bạn không tốt, có phải bị bệnh không?","en":"You look pale. Are you sick?"},{"use":"cấu trúc 脸色 + 变 + màu sắc","ex":"他的脸色一下子变白了。","py":"Tā de liǎnsè yíxiàzi biàn bái le.","vi":"Sắc mặt anh ấy bỗng chốc trở nên trắng bệch.","en":"His face suddenly turned pale."},{"use":"nghĩa nét mặt, thái độ: 看脸色","ex":"看他的脸色，我就知道他很生气。","py":"Kàn tā de liǎnsè, wǒ jiù zhīdào tā hěn shēngqì.","vi":"Nhìn sắc mặt anh ấy, tôi biết ngay anh ấy rất tức giận.","en":"Judging by his expression, I knew he was very angry."},{"use":"so sánh trước sau: 脸色好多了","ex":"休息了几天，她的脸色好多了。","py":"Xiūxi le jǐ tiān, tā de liǎnsè hǎo duō le.","vi":"Nghỉ ngơi vài ngày, sắc mặt cô ấy tốt hơn nhiều.","en":"After resting a few days, her complexion looks much better."}]},"没事儿":{"en":"it's nothing; no problem; to be fine; to be free","exs":[{"use":"nghĩa không sao, ổn: 我没事儿","ex":"别担心，我没事儿。","py":"Bié dānxīn, wǒ méishìr.","vi":"Đừng lo, tôi không sao.","en":"Don't worry, I'm fine."},{"use":"đáp lại lời xin lỗi","ex":"对不起！——没事儿！","py":"Duìbuqǐ! Méishìr!","vi":"Xin lỗi! — Không sao đâu!","en":"Sorry! — It's no problem!"},{"use":"dùng trong câu hỏi quan tâm: 你没事儿吧？","ex":"你没事儿吧？","py":"Nǐ méishìr ba?","vi":"Bạn không sao chứ?","en":"Are you okay?"},{"use":"nghĩa rảnh rỗi, không bận việc","ex":"今天没事儿，我们一起去逛街吧。","py":"Jīntiān méishìr, wǒmen yìqǐ qù guàngjiē ba.","vi":"Hôm nay rảnh, chúng ta cùng đi dạo phố nhé.","en":"I'm free today, so let's go shopping together."}]},"不过":{"en":"but; however; only; no more than","exs":[{"use":"liên từ: nhưng, tuy nhiên (chuyển ngoặt nhẹ)","ex":"这个菜很好吃，不过有点儿贵。","py":"Zhège cài hěn hǎochī, búguò yǒudiǎnr guì.","vi":"Món này rất ngon, có điều hơi đắt.","en":"This dish is delicious, but a bit expensive."},{"use":"nối hai vế đối lập","ex":"我想去旅游，不过没有时间。","py":"Wǒ xiǎng qù lǚyóu, búguò méiyǒu shíjiān.","vi":"Tôi muốn đi du lịch, nhưng không có thời gian.","en":"I want to travel, but I don't have time."},{"use":"phó từ: 不过是 = chỉ là","ex":"他不过是个孩子，你别生气。","py":"Tā búguò shì ge háizi, nǐ bié shēngqì.","vi":"Cậu ấy chỉ là đứa trẻ thôi, bạn đừng giận.","en":"He's only a child; don't be angry."},{"use":"phó từ: 不过 + số lượng = chỉ, không quá","ex":"这件事不过五分钟就能做完。","py":"Zhè jiàn shì búguò wǔ fēnzhōng jiù néng zuò wán.","vi":"Việc này chỉ năm phút là làm xong.","en":"This job takes no more than five minutes."},{"use":"cấu trúc 再...不过了 (không gì ... bằng)","ex":"这个办法再好不过了。","py":"Zhège bànfǎ zài hǎo búguò le.","vi":"Cách này không còn gì tốt hơn nữa.","en":"This method couldn't be better."}]},"面前":{"en":"in front of; before; in the face of","exs":[{"use":"cấu trúc 在 + người + 面前","ex":"他站在大家面前讲话。","py":"Tā zhàn zài dàjiā miànqián jiǎnghuà.","vi":"Anh ấy đứng trước mặt mọi người phát biểu.","en":"He stood in front of everyone and gave a speech."},{"use":"nghĩa bóng: 在困难面前","ex":"在困难面前，我们不能放弃。","py":"Zài kùnnan miànqián, wǒmen bù néng fàngqì.","vi":"Đứng trước khó khăn, chúng ta không thể bỏ cuộc.","en":"In the face of difficulties, we must not give up."},{"use":"nghĩa đen: vật bày ngay trước mặt","ex":"一桌好菜摆在我面前。","py":"Yì zhuō hǎo cài bǎi zài wǒ miànqián.","vi":"Một bàn thức ăn ngon bày ngay trước mặt tôi.","en":"A table full of good food was laid out in front of me."},{"use":"cấu trúc 在 + người + 面前 + thái độ","ex":"孩子在父母面前总是很放松。","py":"Háizi zài fùmǔ miànqián zǒngshì hěn fàngsōng.","vi":"Con cái trước mặt bố mẹ lúc nào cũng thoải mái.","en":"Children always feel relaxed in front of their parents."}]},"永远":{"en":"forever; always; ever","exs":[{"use":"làm trạng ngữ: 永远 + V","ex":"我会永远记住你的帮助。","py":"Wǒ huì yǒngyuǎn jìzhù nǐ de bāngzhù.","vi":"Tôi sẽ mãi mãi ghi nhớ sự giúp đỡ của bạn.","en":"I will always remember your help."},{"use":"永远 + 是 + N","ex":"他们永远是最好的朋友。","py":"Tāmen yǒngyuǎn shì zuì hǎo de péngyou.","vi":"Họ mãi mãi là những người bạn tốt nhất.","en":"They will always be the best of friends."},{"use":"永远不要 + V (đừng bao giờ)","ex":"永远不要放弃自己的梦想。","py":"Yǒngyuǎn bú yào fàngqì zìjǐ de mèngxiǎng.","vi":"Đừng bao giờ từ bỏ ước mơ của mình.","en":"Never give up on your dreams."},{"use":"bày tỏ tình cảm: 永远爱你","ex":"妈妈永远爱你。","py":"Māma yǒngyuǎn ài nǐ.","vi":"Mẹ mãi mãi yêu con.","en":"Mom will love you forever."}]},"方向":{"en":"direction; orientation","exs":[{"use":"nghĩa hướng đi (phương hướng không gian)","ex":"请问，火车站在哪个方向？","py":"Qǐngwèn, huǒchēzhàn zài nǎ ge fāngxiàng?","vi":"Xin hỏi, ga tàu ở hướng nào?","en":"Excuse me, which direction is the train station?"},{"use":"cấu trúc 走错方向","ex":"我们走错方向了。","py":"Wǒmen zǒu cuò fāngxiàng le.","vi":"Chúng ta đi nhầm hướng rồi.","en":"We went in the wrong direction."},{"use":"nghĩa bóng: phương hướng cuộc đời","ex":"他不知道今后的人生方向。","py":"Tā bù zhīdào jīnhòu de rénshēng fāngxiàng.","vi":"Anh ấy không biết phương hướng cuộc đời sau này.","en":"He doesn't know his life direction going forward."},{"use":"cấu trúc 往 + 这个 + 方向","ex":"往这个方向走五分钟就到了。","py":"Wǎng zhège fāngxiàng zǒu wǔ fēnzhōng jiù dào le.","vi":"Đi theo hướng này năm phút là đến.","en":"Walk in this direction for five minutes and you'll be there."},{"use":"nghĩa mục tiêu cố gắng: 努力的方向","ex":"老师给我们指出了努力的方向。","py":"Lǎoshī gěi wǒmen zhǐchū le nǔlì de fāngxiàng.","vi":"Thầy giáo đã chỉ ra cho chúng tôi hướng cố gắng.","en":"The teacher pointed out the direction for our efforts."}]},"人家":{"en":"other people; he/she/they; I (coquettish); household","exs":[{"use":"nghĩa 1: người khác, người ta","ex":"这是人家的东西，不能随便拿。","py":"Zhè shì rénjia de dōngxi, bù néng suíbiàn ná.","vi":"Đây là đồ của người ta, không được tùy tiện lấy.","en":"This belongs to someone else; you can't just take it."},{"use":"nghĩa 2: tôi (giọng nũng nịu, thường là nữ)","ex":"你别催了，人家正在做呢。","py":"Nǐ bié cuī le, rénjia zhèngzài zuò ne.","vi":"Đừng giục nữa, người ta đang làm mà.","en":"Stop rushing me; I'm doing it!"},{"use":"nghĩa 1: chỉ một người cụ thể đã nhắc tới","ex":"人家都已经到了，你怎么还没出门？","py":"Rénjia dōu yǐjīng dào le, nǐ zěnme hái méi chūmén?","vi":"Người ta đến cả rồi, sao bạn vẫn chưa ra khỏi nhà?","en":"They have all arrived already; why haven't you left yet?"},{"use":"đứng trước tên người để so sánh","ex":"人家小李每天都学习到很晚。","py":"Rénjia Xiǎo Lǐ měitiān dōu xuéxí dào hěn wǎn.","vi":"Người ta Tiểu Lý ngày nào cũng học đến khuya.","en":"Xiao Li studies until late every day, you know."},{"use":"nghĩa 3 (rénjiā): hộ gia đình, nhà","ex":"这一带住着几户人家。","py":"Zhè yídài zhù zhe jǐ hù rénjiā.","vi":"Khu vực này có mấy hộ gia đình sinh sống.","en":"A few households live in this area."}]},"王老师":{"en":"Teacher Wang; Mr./Ms. Wang","exs":[{"use":"làm chủ ngữ, giới thiệu thầy/cô","ex":"王老师是我们的汉语老师。","py":"Wáng lǎoshī shì wǒmen de Hànyǔ lǎoshī.","vi":"Thầy/Cô Vương là giáo viên tiếng Trung của chúng tôi.","en":"Teacher Wang is our Chinese teacher."},{"use":"dùng để xưng hô, gọi thầy/cô","ex":"王老师，请问这个字怎么读？","py":"Wáng lǎoshī, qǐngwèn zhège zì zěnme dú?","vi":"Thầy/Cô Vương ơi, chữ này đọc thế nào ạ?","en":"Teacher Wang, how do you read this character?"},{"use":"làm chủ ngữ + V + 得 + adj","ex":"王老师讲课讲得非常清楚。","py":"Wáng lǎoshī jiǎngkè jiǎng de fēicháng qīngchu.","vi":"Thầy/Cô Vương giảng bài rất rõ ràng.","en":"Teacher Wang explains lessons very clearly."},{"use":"làm tân ngữ của 喜欢","ex":"我们都很喜欢王老师。","py":"Wǒmen dōu hěn xǐhuan Wáng lǎoshī.","vi":"Chúng tôi đều rất quý Thầy/Cô Vương.","en":"We all like Teacher Wang very much."}]},"漂亮":{"en":"beautiful; pretty; nice; excellent","exs":[{"use":"V + 得 + 很漂亮 (miêu tả vẻ ngoài)","ex":"她今天穿得很漂亮。","py":"Tā jīntiān chuān de hěn piàoliang.","vi":"Hôm nay cô ấy ăn mặc rất đẹp.","en":"She is dressed beautifully today."},{"use":"làm vị ngữ miêu tả nơi chốn","ex":"这个城市又干净又漂亮。","py":"Zhège chéngshì yòu gānjìng yòu piàoliang.","vi":"Thành phố này vừa sạch vừa đẹp.","en":"This city is both clean and beautiful."},{"use":"nói về chữ viết, khen kết quả","ex":"你的字写得真漂亮！","py":"Nǐ de zì xiě de zhēn piàoliang!","vi":"Chữ bạn viết đẹp thật!","en":"Your handwriting is really beautiful!"},{"use":"nghĩa xuất sắc, đẹp mắt (làm việc)","ex":"这场比赛他打得很漂亮。","py":"Zhè chǎng bǐsài tā dǎ de hěn piàoliang.","vi":"Trận đấu này anh ấy chơi rất xuất sắc.","en":"He played brilliantly in this match."},{"use":"làm định ngữ: 漂亮的 + N","ex":"她买了一条漂亮的裙子。","py":"Tā mǎi le yì tiáo piàoliang de qúnzi.","vi":"Cô ấy mua một chiếc váy đẹp.","en":"She bought a pretty dress."}]},"优秀":{"en":"excellent; outstanding","exs":[{"use":"làm định ngữ: 优秀的 + N","ex":"他是一名优秀的学生。","py":"Tā shì yì míng yōuxiù de xuésheng.","vi":"Cậu ấy là một học sinh xuất sắc.","en":"He is an outstanding student."},{"use":"làm định ngữ chỉ người tham gia","ex":"这次比赛有很多优秀的选手。","py":"Zhè cì bǐsài yǒu hěn duō yōuxiù de xuǎnshǒu.","vi":"Cuộc thi lần này có nhiều tuyển thủ xuất sắc.","en":"There are many excellent players in this competition."},{"use":"làm vị ngữ: 成绩 + 优秀","ex":"她的成绩非常优秀。","py":"Tā de chéngjì fēicháng yōuxiù.","vi":"Thành tích của cô ấy vô cùng xuất sắc.","en":"Her grades are excellent."},{"use":"cấu trúc 被评为优秀 + N","ex":"他被评为公司的优秀员工。","py":"Tā bèi píng wéi gōngsī de yōuxiù yuángōng.","vi":"Anh ấy được bình chọn là nhân viên xuất sắc của công ty.","en":"He was named an outstanding employee of the company."}]},"硕士":{"en":"master's degree; master's graduate","exs":[{"use":"cấu trúc 读硕士 (học thạc sĩ)","ex":"她在北京大学读硕士。","py":"Tā zài Běijīng Dàxué dú shuòshì.","vi":"Cô ấy học thạc sĩ tại Đại học Bắc Kinh.","en":"She is doing a master's at Peking University."},{"use":"有硕士学位 (có bằng thạc sĩ)","ex":"我哥哥有硕士学位。","py":"Wǒ gēge yǒu shuòshì xuéwèi.","vi":"Anh trai tôi có bằng thạc sĩ.","en":"My older brother has a master's degree."},{"use":"硕士 + 毕业 (tốt nghiệp thạc sĩ)","ex":"他硕士毕业后进了一家银行工作。","py":"Tā shuòshì bìyè hòu jìn le yì jiā yínháng gōngzuò.","vi":"Sau khi tốt nghiệp thạc sĩ, anh ấy vào làm ở một ngân hàng.","en":"After finishing his master's, he joined a bank."},{"use":"cấu trúc 考硕士 (thi vào cao học)","ex":"我打算明年考硕士。","py":"Wǒ dǎsuàn míngnián kǎo shuòshì.","vi":"Tôi dự định năm sau thi cao học.","en":"I plan to take the master's entrance exam next year."}]},"翻译":{"en":"to translate; translation; interpreter; translator","exs":[{"use":"động từ: 把...翻译成...","ex":"请把这句话翻译成英语。","py":"Qǐng bǎ zhè jù huà fānyì chéng Yīngyǔ.","vi":"Xin hãy dịch câu này sang tiếng Anh.","en":"Please translate this sentence into English."},{"use":"danh từ: người phiên dịch","ex":"她是一名翻译，会说三种语言。","py":"Tā shì yì míng fānyì, huì shuō sān zhǒng yǔyán.","vi":"Cô ấy là một phiên dịch viên, biết nói ba thứ tiếng.","en":"She is a translator who speaks three languages."},{"use":"danh từ: bản dịch","ex":"这本书的翻译很准确。","py":"Zhè běn shū de fānyì hěn zhǔnquè.","vi":"Bản dịch của cuốn sách này rất chính xác.","en":"The translation of this book is very accurate."},{"use":"làm vị ngữ: 很难翻译","ex":"这个词很难翻译。","py":"Zhège cí hěn nán fānyì.","vi":"Từ này rất khó dịch.","en":"This word is very hard to translate."},{"use":"cấu trúc 当翻译 (làm phiên dịch)","ex":"开会时，小李给外国客人当翻译。","py":"Kāihuì shí, Xiǎo Lǐ gěi wàiguó kèrén dāng fānyì.","vi":"Khi họp, Tiểu Lý làm phiên dịch cho khách nước ngoài.","en":"During the meeting, Xiao Li interpreted for the foreign guests."}]},"确实":{"en":"indeed; really; truly; indeed (adv)","exs":[{"use":"trạng từ nhấn mạnh: 确实 + adj","ex":"这家饭馆的菜确实不错。","py":"Zhè jiā fànguǎn de cài quèshí búcuò.","vi":"Món ăn của quán này quả thực không tệ.","en":"The food at this restaurant is indeed good."},{"use":"đồng tình với lời nói của người khác","ex":"你说得确实有道理。","py":"Nǐ shuō de quèshí yǒu dàolǐ.","vi":"Bạn nói quả thực có lý.","en":"What you said does make sense."},{"use":"确实 + phủ định: thực sự không","ex":"他确实不知道这件事。","py":"Tā quèshí bù zhīdào zhè jiàn shì.","vi":"Anh ấy thực sự không biết chuyện này.","en":"He really doesn't know about this."},{"use":"dùng đáp lời đồng ý","ex":"今天真冷。——确实，我也觉得很冷。","py":"Jīntiān zhēn lěng. Quèshí, wǒ yě juéde hěn lěng.","vi":"Hôm nay lạnh thật. — Đúng thế, tôi cũng thấy rất lạnh.","en":"It's really cold today. — Indeed, I think so too."}]},"拿到":{"en":"to get; to obtain; to receive","exs":[{"use":"V + 到 (kết quả đạt được): 拿到 + 了 + N","ex":"我昨天拿到了驾照。","py":"Wǒ zuótiān nádào le jiàzhào.","vi":"Hôm qua tôi đã lấy được bằng lái xe.","en":"I got my driver's license yesterday."},{"use":"nhận được học bổng, giấy tờ","ex":"他拿到奖学金了。","py":"Tā nádào jiǎngxuéjīn le.","vi":"Anh ấy nhận được học bổng rồi.","en":"He got the scholarship."},{"use":"câu hỏi với 了吗","ex":"你拿到包裹了吗？","py":"Nǐ nádào bāoguǒ le ma?","vi":"Bạn nhận được bưu kiện chưa?","en":"Did you get the package?"},{"use":"đi với 一定要 (nhất định phải lấy được)","ex":"我下班前一定要拿到这份文件。","py":"Wǒ xiàbān qián yídìng yào nádào zhè fèn wénjiàn.","vi":"Trước khi tan làm tôi nhất định phải lấy được tài liệu này.","en":"I must get this document before I leave work."},{"use":"nhận được thứ hạng, thành tích","ex":"她拿到了第一名，高兴得跳了起来。","py":"Tā nádào le dì yī míng, gāoxìng de tiào le qǐlái.","vi":"Cô ấy giành được hạng nhất, vui đến nhảy cẫng lên.","en":"She got first place and jumped for joy."}]},"兴奋":{"en":"excited; thrilled","exs":[{"use":"tính từ, làm vị ngữ: 很兴奋","ex":"听到这个好消息，大家都很兴奋。","py":"Tīngdào zhège hǎo xiāoxi, dàjiā dōu hěn xīngfèn.","vi":"Nghe tin tốt này, ai cũng rất phấn khích.","en":"Hearing the good news, everyone was very excited."},{"use":"V/adj + 得 + 兴奋: bổ ngữ mức độ","ex":"明天就要去旅行了，孩子们兴奋得睡不着觉。","py":"Míngtiān jiù yào qù lǚxíng le, háizimen xīngfèn de shuì bù zháo jiào.","vi":"Mai là đi du lịch rồi, bọn trẻ phấn khích đến mức không ngủ được.","en":"The kids are leaving on a trip tomorrow and are too excited to sleep."},{"use":"兴奋地 + động từ: làm trạng ngữ","ex":"看到喜欢的歌手，她兴奋地叫了起来。","py":"Kàndào xǐhuan de gēshǒu, tā xīngfèn de jiào le qǐlái.","vi":"Thấy ca sĩ mình thích, cô ấy phấn khích hét lên.","en":"Seeing her favorite singer, she cried out excitedly."}]},"那时":{"en":"at that time; then","exs":[{"use":"Chỉ thời điểm trong quá khứ, đứng đầu câu","ex":"那时我还是个小学生。","py":"Nàshí wǒ hái shì ge xiǎoxuéshēng.","vi":"Lúc đó tôi vẫn còn là học sinh tiểu học.","en":"At that time I was still a primary school student."},{"use":"Nêu bối cảnh sau một mốc thời gian","ex":"十年前我住在北京，那时这里还没有地铁。","py":"Shí nián qián wǒ zhù zài Běijīng, nàshí zhèlǐ hái méiyǒu dìtiě.","vi":"Mười năm trước tôi sống ở Bắc Kinh, lúc đó ở đây còn chưa có tàu điện ngầm.","en":"Ten years ago I lived in Beijing, and back then there was no subway here."},{"use":"Dạng mở rộng 那时候, hay dùng khi kể chuyện","ex":"那时候他刚来中国，一句汉语也不会说。","py":"Nàshíhou tā gāng lái Zhōngguó, yí jù Hànyǔ yě bú huì shuō.","vi":"Lúc đó anh ấy mới đến Trung Quốc, không biết nói một câu tiếng Trung nào.","en":"At that time he had just come to China and couldn't speak a word of Chinese."}]},"心里":{"en":"in one's heart; inside","exs":[{"use":"Chỉ nội tâm: 心里 + cảm xúc","ex":"他心里很难过，但是什么也没说。","py":"Tā xīnli hěn nánguò, dànshì shénme yě méi shuō.","vi":"Trong lòng anh ấy rất buồn nhưng không nói gì cả.","en":"He felt very sad inside, but said nothing."},{"use":"心里有 + điều suy nghĩ","ex":"你心里有什么想法，可以直接告诉我。","py":"Nǐ xīnli yǒu shénme xiǎngfa, kěyǐ zhíjiē gàosu wǒ.","vi":"Trong lòng bạn có suy nghĩ gì thì cứ nói thẳng với tôi.","en":"Whatever you have on your mind, you can tell me directly."},{"use":"心里 + trạng thái (紧张, 高兴…)","ex":"考试前，我心里一直很紧张。","py":"Kǎoshì qián, wǒ xīnli yìzhí hěn jǐnzhāng.","vi":"Trước kỳ thi, trong lòng tôi luôn rất căng thẳng.","en":"Before the exam, I was nervous the whole time."}]},"不用":{"en":"need not; no need to","exs":[{"use":"不用 + động từ: không cần làm gì","ex":"这点小事，你不用担心。","py":"Zhè diǎn xiǎoshì, nǐ búyòng dānxīn.","vi":"Chuyện nhỏ này, bạn không cần lo.","en":"It's a small matter; you don't need to worry."},{"use":"不用 + V + 了: lịch sự từ chối giúp đỡ","ex":"我自己能去，你不用送我了。","py":"Wǒ zìjǐ néng qù, nǐ búyòng sòng wǒ le.","vi":"Tôi tự đi được, bạn không cần tiễn tôi đâu.","en":"I can go by myself; you don't need to see me off."},{"use":"Dùng độc lập để đáp lại: 不用，谢谢","ex":"要我帮你拿吗？不用，谢谢你。","py":"Yào wǒ bāng nǐ ná ma? Búyòng, xièxie nǐ.","vi":"Để tôi cầm giúp bạn nhé? Không cần đâu, cảm ơn bạn.","en":"Shall I carry it for you? No need, thank you."}]},"建议":{"en":"to suggest; suggestion","exs":[{"use":"động từ: 建议 + ai + làm gì","ex":"老师建议我们每天读半小时书。","py":"Lǎoshī jiànyì wǒmen měitiān dú bàn xiǎoshí shū.","vi":"Thầy giáo đề nghị chúng tôi mỗi ngày đọc sách nửa tiếng.","en":"The teacher suggested that we read for half an hour every day."},{"use":"danh từ: 你的建议 / 有一个建议","ex":"谢谢你的建议，我会好好考虑的。","py":"Xièxie nǐ de jiànyì, wǒ huì hǎohāo kǎolǜ de.","vi":"Cảm ơn lời đề nghị của bạn, tôi sẽ cân nhắc kỹ.","en":"Thanks for your suggestion; I'll think it over carefully."},{"use":"động từ: 建议 + ai + 少/多 + V","ex":"医生建议他少吃油腻的东西。","py":"Yīshēng jiànyì tā shǎo chī yóunì de dōngxi.","vi":"Bác sĩ khuyên anh ấy ăn ít đồ dầu mỡ.","en":"The doctor advised him to eat less greasy food."},{"use":"danh từ: 提出/有 + 建议","ex":"我有一个建议，我们明天早点出发。","py":"Wǒ yǒu yí ge jiànyì, wǒmen míngtiān zǎodiǎn chūfā.","vi":"Tôi có một đề nghị: ngày mai chúng ta xuất phát sớm hơn.","en":"I have a suggestion: let's set out earlier tomorrow."}]},"职业":{"en":"occupation; profession","exs":[{"use":"hỏi nghề nghiệp","ex":"你的职业是什么？","py":"Nǐ de zhíyè shì shénme?","vi":"Nghề nghiệp của bạn là gì?","en":"What is your occupation?"},{"use":"是 + 一个 + adj + 的职业","ex":"老师是一个很受人尊敬的职业。","py":"Lǎoshī shì yí ge hěn shòu rén zūnjìng de zhíyè.","vi":"Giáo viên là một nghề rất được mọi người kính trọng.","en":"Teaching is a highly respected profession."},{"use":"选择职业: động từ + 职业","ex":"选择职业的时候，要考虑自己的兴趣。","py":"Xuǎnzé zhíyè de shíhou, yào kǎolǜ zìjǐ de xìngqù.","vi":"Khi chọn nghề, cần cân nhắc sở thích của bản thân.","en":"When choosing a career, you should consider your own interests."}]},"在我看来":{"en":"in my opinion; as I see it","exs":[{"use":"Mở đầu câu nêu quan điểm, sau có dấu phẩy","ex":"在我看来，这个办法很不错。","py":"Zài wǒ kànlái, zhège bànfǎ hěn búcuò.","vi":"Theo tôi thấy, cách này rất được.","en":"In my opinion, this method is quite good."},{"use":"Nêu nhận định về việc học","ex":"在我看来，学习语言最重要的是多说。","py":"Zài wǒ kànlái, xuéxí yǔyán zuì zhòngyào de shì duō shuō.","vi":"Theo tôi, điều quan trọng nhất khi học ngôn ngữ là nói nhiều.","en":"In my view, the most important thing in learning a language is to speak a lot."},{"use":"Dùng trong câu có đối lập 不是…而是…","ex":"在我看来，他不是不努力，而是方法不对。","py":"Zài wǒ kànlái, tā bú shì bù nǔlì, ér shì fāngfǎ bú duì.","vi":"Theo tôi, anh ấy không phải không cố gắng mà là phương pháp không đúng.","en":"As I see it, he isn't lazy; his method is just wrong."}]},"关键":{"en":"key; crux; crucial","exs":[{"use":"danh từ: …的关键 là + …","ex":"学好汉语的关键是多练习。","py":"Xuéhǎo Hànyǔ de guānjiàn shì duō liànxí.","vi":"Mấu chốt để học tốt tiếng Trung là luyện tập nhiều.","en":"The key to learning Chinese well is lots of practice."},{"use":"tính từ: 关键时刻 (thời khắc then chốt)","ex":"现在是关键时刻，大家一定要坚持。","py":"Xiànzài shì guānjiàn shíkè, dàjiā yídìng yào jiānchí.","vi":"Bây giờ là thời khắc then chốt, mọi người nhất định phải kiên trì.","en":"This is the critical moment; everyone must hold on."},{"use":"关键在于 + …: mấu chốt nằm ở…","ex":"这个问题的关键在于时间。","py":"Zhège wèntí de guānjiàn zàiyú shíjiān.","vi":"Mấu chốt của vấn đề này nằm ở thời gian.","en":"The crux of this problem is time."}]},"将来":{"en":"future; in the future","exs":[{"use":"Chỉ thời gian, đứng đầu câu: 将来 + chủ ngữ + …","ex":"将来我想当一名医生。","py":"Jiānglái wǒ xiǎng dāng yì míng yīshēng.","vi":"Sau này tôi muốn làm bác sĩ.","en":"In the future I want to be a doctor."},{"use":"Danh từ: 不知道将来","ex":"谁也不知道将来会发生什么。","py":"Shéi yě bù zhīdào jiānglái huì fāshēng shénme.","vi":"Không ai biết tương lai sẽ xảy ra chuyện gì.","en":"Nobody knows what will happen in the future."},{"use":"将来的 + danh từ: làm định ngữ","ex":"为了将来的生活，我们现在要努力工作。","py":"Wèile jiānglái de shēnghuó, wǒmen xiànzài yào nǔlì gōngzuò.","vi":"Vì cuộc sống sau này, bây giờ chúng ta phải làm việc chăm chỉ.","en":"For our future life, we need to work hard now."}]},"发展":{"en":"to develop; development","exs":[{"use":"động từ: 发展 + 得 + adj","ex":"这个城市发展得很快。","py":"Zhège chéngshì fāzhǎn de hěn kuài.","vi":"Thành phố này phát triển rất nhanh.","en":"This city is developing very fast."},{"use":"động từ: 不断发展","ex":"孩子的身体和智力都在不断发展。","py":"Háizi de shēntǐ hé zhìlì dōu zài búduàn fāzhǎn.","vi":"Cơ thể và trí tuệ của trẻ đều không ngừng phát triển.","en":"A child's body and intelligence are both constantly developing."},{"use":"danh từ: 公司的发展","ex":"我们要为公司的发展努力工作。","py":"Wǒmen yào wèi gōngsī de fāzhǎn nǔlì gōngzuò.","vi":"Chúng ta phải nỗ lực làm việc vì sự phát triển của công ty.","en":"We must work hard for the development of the company."}]},"有钱":{"en":"rich; wealthy","exs":[{"use":"tính từ: 很有钱","ex":"他很有钱，但是一点也不骄傲。","py":"Tā hěn yǒuqián, dànshì yìdiǎn yě bù jiāo'ào.","vi":"Anh ấy rất giàu nhưng chẳng kiêu ngạo chút nào.","en":"He is very rich, but not proud at all."},{"use":"làm chủ ngữ: 有钱 + 不一定 …","ex":"有钱不一定幸福。","py":"Yǒuqián bù yídìng xìngfú.","vi":"Có tiền chưa chắc đã hạnh phúc.","en":"Being rich doesn't necessarily mean being happy."},{"use":"So sánh: 没有 + A + 那么 + 有钱","ex":"我没有他那么有钱，买不起这么贵的车。","py":"Wǒ méiyǒu tā nàme yǒuqián, mǎi bu qǐ zhème guì de chē.","vi":"Tôi không giàu như anh ấy, không mua nổi chiếc xe đắt thế này.","en":"I'm not as rich as he is; I can't afford such an expensive car."}]},"结束":{"en":"to end; to finish","exs":[{"use":"động từ nội động: 会议/课 + 结束","ex":"会议九点结束。","py":"Huìyì jiǔ diǎn jiéshù.","vi":"Cuộc họp kết thúc lúc chín giờ.","en":"The meeting ends at nine."},{"use":"…结束以后: sau khi kết thúc","ex":"电影结束以后，我们去吃了晚饭。","py":"Diànyǐng jiéshù yǐhòu, wǒmen qù chīle wǎnfàn.","vi":"Sau khi phim kết thúc, chúng tôi đi ăn tối.","en":"After the movie ended, we went for dinner."},{"use":"động từ ngoại động: 结束 + tân ngữ","ex":"结束了一天的工作，他累极了。","py":"Jiéshùle yì tiān de gōngzuò, tā lèi jí le.","vi":"Kết thúc công việc một ngày, anh ấy mệt vô cùng.","en":"Having finished a day's work, he was exhausted."}]},"热水澡":{"en":"hot bath; hot shower","exs":[{"use":"洗 + 个 + 热水澡","ex":"洗个热水澡，你会觉得舒服一点。","py":"Xǐ ge rèshuǐzǎo, nǐ huì juéde shūfu yìdiǎn.","vi":"Tắm nước nóng một cái, bạn sẽ thấy dễ chịu hơn.","en":"Take a hot bath and you'll feel a bit better."},{"use":"想先洗热水澡: nói về thói quen mùa đông","ex":"冬天回到家，我最想先洗个热水澡。","py":"Dōngtiān huídào jiā, wǒ zuì xiǎng xiān xǐ ge rèshuǐzǎo.","vi":"Mùa đông về đến nhà, tôi muốn tắm nước nóng trước nhất.","en":"In winter, when I get home I most want to take a hot bath first."},{"use":"Dùng sau trạng ngữ thời gian: 睡觉前洗热水澡","ex":"睡觉前洗热水澡，可以睡得更好。","py":"Shuìjiào qián xǐ rèshuǐzǎo, kěyǐ shuì de gèng hǎo.","vi":"Tắm nước nóng trước khi ngủ có thể ngủ ngon hơn.","en":"Taking a hot bath before bed helps you sleep better."}]},"睡觉":{"en":"to sleep; to go to bed","exs":[{"use":"động từ ly hợp: 几点睡觉","ex":"我每天十一点睡觉。","py":"Wǒ měitiān shíyī diǎn shuìjiào.","vi":"Mỗi ngày tôi đi ngủ lúc mười một giờ.","en":"I go to bed at eleven every day."},{"use":"…才睡觉: mãi mới đi ngủ","ex":"昨天晚上他很晚才睡觉，所以今天很累。","py":"Zuótiān wǎnshang tā hěn wǎn cái shuìjiào, suǒyǐ jīntiān hěn lèi.","vi":"Tối qua anh ấy rất muộn mới đi ngủ nên hôm nay rất mệt.","en":"He went to bed very late last night, so he's tired today."},{"use":"睡觉前 + …: trước khi ngủ","ex":"睡觉前不要玩手机。","py":"Shuìjiào qián búyào wán shǒujī.","vi":"Trước khi ngủ đừng chơi điện thoại.","en":"Don't play with your phone before bed."}]},"根据":{"en":"according to; based on; to base on","exs":[{"use":"根据 + danh từ, nêu căn cứ.","ex":"根据调查，我们发现了问题。","py":"Gēnjù diàochá, wǒmen fāxiàn le wèntí.","vi":"Căn cứ vào cuộc điều tra, chúng tôi đã phát hiện ra vấn đề.","en":"According to the survey, we found the problem."},{"use":"根据 + danh từ.","ex":"根据情况选择方法。","py":"Gēnjù qíngkuàng xuǎnzé fāngfǎ.","vi":"Hãy chọn phương pháp tùy theo tình hình.","en":"Choose the method according to the situation."},{"use":"giới từ: 根据 + danh từ, nêu căn cứ","ex":"这个故事是根据真实的事情写的。","py":"Zhège gùshi shì gēnjù zhēnshí de shìqing xiě de.","vi":"Câu chuyện này được viết dựa trên sự việc có thật.","en":"This story was written based on real events."},{"use":"giới từ: 根据 + tin tức/dự báo","ex":"根据天气预报，明天会下大雨。","py":"Gēnjù tiānqì yùbào, míngtiān huì xià dàyǔ.","vi":"Theo dự báo thời tiết, ngày mai sẽ có mưa to.","en":"According to the weather forecast, it will rain heavily tomorrow."}]},"阅读能力":{"en":"reading ability; reading comprehension skill","exs":[{"use":"Chỉ khả năng đọc hiểu.","ex":"他的阅读能力很强。","py":"Tā de yuèdú nénglì hěn qiáng.","vi":"Năng lực đọc hiểu của anh ấy rất mạnh.","en":"His reading ability is very strong."},{"use":"提高 + 阅读能力: nâng cao","ex":"多读书可以提高阅读能力。","py":"Duō dú shū kěyǐ tígāo yuèdú nénglì.","vi":"Đọc nhiều sách có thể nâng cao năng lực đọc hiểu.","en":"Reading more books can improve your reading ability."},{"use":"检查/测试 + 阅读能力","ex":"这次考试主要检查学生的阅读能力。","py":"Zhè cì kǎoshì zhǔyào jiǎnchá xuésheng de yuèdú nénglì.","vi":"Kỳ thi lần này chủ yếu kiểm tra năng lực đọc hiểu của học sinh.","en":"This exam mainly tests students' reading comprehension."}]},"不但…而且…":{"en":"not only … but also …","exs":[{"use":"Liên kết hai ý tăng tiến.","ex":"她不但会说中文，而且会说英语。","py":"Tā búdàn huì shuō Zhōngwén, érqiě huì shuō Yīngyǔ.","vi":"Cô ấy không những biết nói tiếng Trung mà còn biết nói tiếng Anh.","en":"She can speak not only Chinese but also English."},{"use":"Cấu trúc tăng tiến: chủ ngữ giống nhau, 不但 đứng sau chủ ngữ","ex":"这家饭店不但便宜，而且很干净。","py":"Zhè jiā fàndiàn búdàn piányi, érqiě hěn gānjìng.","vi":"Quán này không những rẻ mà còn rất sạch.","en":"This restaurant is not only cheap but also very clean."},{"use":"Nối hai vế danh từ: 不但是…而且是…","ex":"他不但是我的同事，而且是我最好的朋友。","py":"Tā búdàn shì wǒ de tóngshì, érqiě shì wǒ zuì hǎo de péngyou.","vi":"Anh ấy không những là đồng nghiệp mà còn là bạn thân nhất của tôi.","en":"He is not only my colleague but also my best friend."},{"use":"Chủ ngữ khác nhau: 不但 đứng trước chủ ngữ","ex":"不但今天，而且明天我也要加班。","py":"Búdàn jīntiān, érqiě míngtiān wǒ yě yào jiābān.","vi":"Không chỉ hôm nay mà ngày mai tôi cũng phải tăng ca.","en":"Not only today, but tomorrow too, I have to work overtime."}]},"提高":{"en":"to raise; to improve","exs":[{"use":"提高 + năng lực/trình độ.","ex":"多练习能提高水平。","py":"Duō liànxí néng tígāo shuǐpíng.","vi":"Luyện tập nhiều có thể nâng cao trình độ.","en":"More practice can improve your level."},{"use":"提高 + trình độ/năng lực","ex":"他的汉语水平提高得很快。","py":"Tā de Hànyǔ shuǐpíng tígāo de hěn kuài.","vi":"Trình độ tiếng Trung của anh ấy nâng cao rất nhanh.","en":"His Chinese level is improving very fast."},{"use":"提高 + lương/giá/mức (con số)","ex":"公司决定提高工人的工资。","py":"Gōngsī juédìng tígāo gōngrén de gōngzī.","vi":"Công ty quyết định tăng lương cho công nhân.","en":"The company decided to raise the workers' wages."},{"use":"为了提高 + thành tích: nêu mục đích","ex":"为了提高成绩，她每天复习到很晚。","py":"Wèile tígāo chéngjì, tā měitiān fùxí dào hěn wǎn.","vi":"Để nâng cao thành tích, cô ấy ngày nào cũng ôn bài đến khuya.","en":"To improve her grades, she studies until late every day."}]},"读书笔记":{"en":"reading notes; book notes","exs":[{"use":"做/写读书笔记.","ex":"我每天写读书笔记。","py":"Wǒ měitiān xiě dúshū bǐjì.","vi":"Mỗi ngày tôi đều viết ghi chép đọc sách.","en":"I write reading notes every day."},{"use":"写 + 读书笔记 (một bài ghi chép)","ex":"读完这本书，我要写一篇读书笔记。","py":"Dúwán zhè běn shū, wǒ yào xiě yì piān dúshū bǐjì.","vi":"Đọc xong cuốn sách này, tôi sẽ viết một bài ghi chép đọc sách.","en":"After finishing this book, I'm going to write a set of reading notes."},{"use":"交 + 读书笔记: nộp bài","ex":"老师让我们把读书笔记交上来。","py":"Lǎoshī ràng wǒmen bǎ dúshū bǐjì jiāo shànglái.","vi":"Thầy giáo bảo chúng tôi nộp ghi chép đọc sách lên.","en":"The teacher asked us to hand in our reading notes."}]},"主要内容":{"en":"main content; gist","exs":[{"use":"主要 + danh từ.","ex":"请说说文章的主要内容。","py":"Qǐng shuōshuo wénzhāng de zhǔyào nèiróng.","vi":"Xin hãy nói về nội dung chính của bài viết.","en":"Please talk about the main content of the article."},{"use":"hỏi nội dung chính: …的主要内容是什么","ex":"这篇文章的主要内容是什么？","py":"Zhè piān wénzhāng de zhǔyào nèiróng shì shénme?","vi":"Nội dung chính của bài viết này là gì?","en":"What is the main content of this article?"},{"use":"说/概括 + 主要内容: tóm tắt","ex":"看完电影后，他简单地说了说故事的主要内容。","py":"Kànwán diànyǐng hòu, tā jiǎndān de shuōle shuo gùshi de zhǔyào nèiróng.","vi":"Xem phim xong, anh ấy kể sơ qua nội dung chính của câu chuyện.","en":"After the movie, he briefly told us the main plot."}]},"看法":{"en":"view; opinion","exs":[{"use":"对…有看法.","ex":"我有不同的看法。","py":"Wǒ yǒu bùtóng de kànfa.","vi":"Tôi có quan điểm khác.","en":"I have a different opinion."},{"use":"对…有看法: có ý kiến về…","ex":"你对这件事有什么看法？","py":"Nǐ duì zhè jiàn shì yǒu shénme kànfa?","vi":"Bạn có quan điểm gì về việc này?","en":"What do you think about this matter?"},{"use":"每个人的看法 + 不同","ex":"每个人的看法都不一样。","py":"Měi ge rén de kànfa dōu bù yíyàng.","vi":"Quan điểm của mỗi người đều không giống nhau.","en":"Everyone's view is different."}]},"虽然…但是…":{"en":"although … (but) …","exs":[{"use":"Biểu thị chuyển ý.","ex":"虽然很忙，但是他还在学习。","py":"Suīrán hěn máng, dànshì tā hái zài xuéxí.","vi":"Tuy rất bận nhưng anh ấy vẫn đang học.","en":"Although he is very busy, he is still studying."},{"use":"Cấu trúc nhượng bộ: 虽然 ở vế đầu, 但是 ở vế sau","ex":"虽然天气很冷，但是我们还是去爬山了。","py":"Suīrán tiānqì hěn lěng, dànshì wǒmen háishi qù páshān le.","vi":"Tuy trời rất lạnh nhưng chúng tôi vẫn đi leo núi.","en":"Although it was very cold, we still went hiking."},{"use":"虽然 đứng sau chủ ngữ","ex":"这件衣服虽然不便宜，但是质量很好。","py":"Zhè jiàn yīfu suīrán bù piányi, dànshì zhìliàng hěn hǎo.","vi":"Bộ quần áo này tuy không rẻ nhưng chất lượng rất tốt.","en":"Although this garment isn't cheap, its quality is very good."}]},"顺序":{"en":"order; sequence","exs":[{"use":"按顺序 = theo thứ tự.","ex":"请按顺序回答问题。","py":"Qǐng àn shùnxù huídá wèntí.","vi":"Xin hãy trả lời câu hỏi theo thứ tự.","en":"Please answer the questions in order."},{"use":"按顺序 + động từ","ex":"请按顺序排好队。","py":"Qǐng àn shùnxù páihǎo duì.","vi":"Xin hãy xếp hàng theo thứ tự.","en":"Please line up in order."},{"use":"…的顺序: thứ tự của…","ex":"这几个字的顺序错了。","py":"Zhè jǐ ge zì de shùnxù cuò le.","vi":"Thứ tự của mấy chữ này bị sai rồi.","en":"The order of these characters is wrong."},{"use":"Nói về trình tự các bước","ex":"做菜的顺序很重要，先放油，再放菜。","py":"Zuò cài de shùnxù hěn zhòngyào, xiān fàng yóu, zài fàng cài.","vi":"Thứ tự khi nấu ăn rất quan trọng: cho dầu trước, rồi mới cho rau.","en":"The order of cooking matters: add oil first, then the vegetables."}]},"有限":{"en":"limited; finite","exs":[{"use":"有限的 + danh từ.","ex":"时间是有限的。","py":"Shíjiān shì yǒuxiàn de.","vi":"Thời gian là có hạn.","en":"Time is limited."},{"use":"tính từ làm vị ngữ: 钱/时间有限","ex":"我的钱有限，买不起太贵的东西。","py":"Wǒ de qián yǒuxiàn, mǎi bu qǐ tài guì de dōngxi.","vi":"Tiền của tôi có hạn, không mua nổi đồ quá đắt.","en":"My money is limited; I can't afford anything too expensive."},{"use":"名额/数量有限: số lượng có hạn","ex":"这次活动名额有限，请尽快报名。","py":"Zhè cì huódòng míng'é yǒuxiàn, qǐng jǐnkuài bàomíng.","vi":"Hoạt động lần này số chỗ có hạn, xin đăng ký sớm.","en":"Places for this event are limited, so please sign up soon."},{"use":"有限公司: công ty trách nhiệm hữu hạn","ex":"他在一家有限公司工作。","py":"Tā zài yì jiā yǒuxiàn gōngsī gōngzuò.","vi":"Anh ấy làm việc ở một công ty trách nhiệm hữu hạn.","en":"He works at a limited company."}]},"养成":{"en":"to form (a habit); to cultivate","exs":[{"use":"养成 + thói quen.","ex":"要养成好习惯。","py":"Yào yǎngchéng hǎo xíguàn.","vi":"Cần hình thành thói quen tốt.","en":"You should develop good habits."},{"use":"养成 + 习惯 (thói quen)","ex":"他从小就养成了早起的习惯。","py":"Tā cóng xiǎo jiù yǎngchéngle zǎoqǐ de xíguàn.","vi":"Từ nhỏ anh ấy đã hình thành thói quen dậy sớm.","en":"He formed the habit of getting up early from childhood."},{"use":"要/应该养成 + 好习惯","ex":"孩子要养成自己整理房间的好习惯。","py":"Háizi yào yǎngchéng zìjǐ zhěnglǐ fángjiān de hǎo xíguàn.","vi":"Trẻ em cần hình thành thói quen tốt là tự dọn phòng.","en":"Children should develop the good habit of tidying their own rooms."},{"use":"Điều kiện: 坚持…就能养成","ex":"坚持三个月，你就能养成运动的习惯。","py":"Jiānchí sān ge yuè, nǐ jiù néng yǎngchéng yùndòng de xíguàn.","vi":"Kiên trì ba tháng, bạn sẽ hình thành được thói quen vận động.","en":"Stick with it for three months and you'll build an exercise habit."}]},"兴趣爱好":{"en":"interests and hobbies; hobby","exs":[{"use":"Sở thích cá nhân.","ex":"阅读是我的兴趣爱好。","py":"Yuèdú shì wǒ de xìngqù àihào.","vi":"Đọc sách là sở thích của tôi.","en":"Reading is my hobby."},{"use":"hỏi sở thích","ex":"你有什么兴趣爱好？","py":"Nǐ yǒu shénme xìngqù àihào?","vi":"Bạn có sở thích gì?","en":"What are your hobbies?"},{"use":"…的兴趣爱好是…","ex":"我的兴趣爱好是听音乐和旅行。","py":"Wǒ de xìngqù àihào shì tīng yīnyuè hé lǚxíng.","vi":"Sở thích của tôi là nghe nhạc và du lịch.","en":"My hobbies are listening to music and traveling."},{"use":"介绍兴趣爱好: dùng khi viết sơ yếu lý lịch","ex":"写简历的时候，可以介绍一下自己的兴趣爱好。","py":"Xiě jiǎnlì de shíhou, kěyǐ jièshào yíxià zìjǐ de xìngqù àihào.","vi":"Khi viết sơ yếu lý lịch, có thể giới thiệu sở thích của bản thân.","en":"When writing a résumé, you can mention your interests and hobbies."}]},"精彩":{"en":"wonderful; brilliant; splendid","exs":[{"use":"很/非常精彩.","ex":"比赛非常精彩。","py":"Bǐsài fēicháng jīngcǎi.","vi":"Trận đấu vô cùng đặc sắc.","en":"The match is very exciting."},{"use":"太…了: 太精彩了 (cảm thán)","ex":"昨天的演出太精彩了！","py":"Zuótiān de yǎnchū tài jīngcǎi le!","vi":"Buổi biểu diễn hôm qua quá đặc sắc!","en":"Yesterday's performance was absolutely brilliant!"},{"use":"tính từ làm vị ngữ: 发言/表演 + 精彩","ex":"他的发言非常精彩，大家都鼓掌了。","py":"Tā de fāyán fēicháng jīngcǎi, dàjiā dōu gǔzhǎng le.","vi":"Bài phát biểu của anh ấy rất đặc sắc, mọi người đều vỗ tay.","en":"His speech was excellent, and everyone applauded."},{"use":"精彩的 + danh từ: làm định ngữ","ex":"我们看了一场精彩的足球比赛。","py":"Wǒmen kànle yì chǎng jīngcǎi de zúqiú bǐsài.","vi":"Chúng tôi đã xem một trận bóng đá rất đặc sắc.","en":"We watched an exciting football match."}]},"不但":{"en":"not only","exs":[{"use":"不但…还…: tăng tiến với 还","ex":"他不但会唱歌，还会跳舞。","py":"Tā búdàn huì chàng gē, hái huì tiàowǔ.","vi":"Anh ấy không những biết hát mà còn biết nhảy.","en":"He can not only sing but also dance."},{"use":"不但…而且…: kết hợp với 而且","ex":"这个孩子不但聪明，而且很有礼貌。","py":"Zhège háizi búdàn cōngming, érqiě hěn yǒu lǐmào.","vi":"Đứa trẻ này không những thông minh mà còn rất lễ phép.","en":"This child is not only smart but also very polite."},{"use":"不但 đứng trước chủ ngữ khi hai vế khác chủ ngữ","ex":"不但我喜欢这本书，我的同学也很喜欢。","py":"Búdàn wǒ xǐhuan zhè běn shū, wǒ de tóngxué yě hěn xǐhuan.","vi":"Không chỉ tôi thích cuốn sách này, bạn học của tôi cũng rất thích.","en":"Not only do I like this book, my classmates like it a lot too."}]},"词语":{"en":"word; term; expression","exs":[{"use":"hỏi nghĩa của từ","ex":"这个词语是什么意思？","py":"Zhège cíyǔ shì shénme yìsi?","vi":"Từ này có nghĩa là gì?","en":"What does this word mean?"},{"use":"用 + 词语 + 造句","ex":"请用这个词语造一个句子。","py":"Qǐng yòng zhège cíyǔ zào yí ge jùzi.","vi":"Hãy dùng từ này đặt một câu.","en":"Please make a sentence with this word."},{"use":"新词语: từ mới","ex":"我每天记十个新词语。","py":"Wǒ měitiān jì shí ge xīn cíyǔ.","vi":"Mỗi ngày tôi nhớ mười từ mới.","en":"I memorize ten new words every day."}]},"句子":{"en":"sentence","exs":[{"use":"nói về ngữ pháp của câu","ex":"这个句子的语法有问题。","py":"Zhège jùzi de yǔfǎ yǒu wèntí.","vi":"Ngữ pháp của câu này có vấn đề.","en":"There is a grammar problem in this sentence."},{"use":"把 + 句子 + 翻译成…","ex":"请把这个句子翻译成英语。","py":"Qǐng bǎ zhège jùzi fānyì chéng Yīngyǔ.","vi":"Hãy dịch câu này sang tiếng Anh.","en":"Please translate this sentence into English."},{"use":"句子 + adj: miêu tả câu","ex":"他写的句子很短，也很清楚。","py":"Tā xiě de jùzi hěn duǎn, yě hěn qīngchu.","vi":"Những câu anh ấy viết rất ngắn và cũng rất rõ ràng.","en":"The sentences he writes are short and clear."}]},"记下":{"en":"to write down; to note down","exs":[{"use":"记下来: bổ ngữ xu hướng, ghi lại điều đã nghe","ex":"把老师说的重点记下来。","py":"Bǎ lǎoshī shuō de zhòngdiǎn jì xiàlái.","vi":"Hãy ghi lại những điểm trọng tâm thầy giáo nói.","en":"Write down the key points the teacher mentions."},{"use":"把 + tân ngữ + 记下了","ex":"我把他的电话号码记下了。","py":"Wǒ bǎ tā de diànhuà hàomǎ jì xià le.","vi":"Tôi đã ghi lại số điện thoại của anh ấy.","en":"I've noted down his phone number."},{"use":"就 + 记下来: ghi lại ngay","ex":"听到好句子，她就马上记下来。","py":"Tīngdào hǎo jùzi, tā jiù mǎshàng jì xiàlái.","vi":"Nghe được câu hay, cô ấy liền ghi lại ngay.","en":"Whenever she hears a good sentence, she writes it down right away."}]},"文章":{"en":"article; essay; piece of writing","exs":[{"use":"量词 篇: 一篇文章","ex":"这篇文章写得很好。","py":"Zhè piān wénzhāng xiě de hěn hǎo.","vi":"Bài viết này viết rất hay.","en":"This article is very well written."},{"use":"发表文章: đăng bài","ex":"他每个星期都在报纸上发表一篇文章。","py":"Tā měi ge xīngqī dōu zài bàozhǐ shàng fābiǎo yì piān wénzhāng.","vi":"Tuần nào anh ấy cũng đăng một bài viết trên báo.","en":"Every week he publishes an article in the newspaper."},{"use":"读文章 rồi làm bài","ex":"请读一下这篇文章，然后回答问题。","py":"Qǐng dú yíxià zhè piān wénzhāng, ránhòu huídá wèntí.","vi":"Hãy đọc bài văn này rồi trả lời câu hỏi.","en":"Please read this article and then answer the questions."}]},"想法":{"en":"idea; thought; opinion","exs":[{"use":"有想法: có ý nghĩ","ex":"你有什么想法，说出来听听。","py":"Nǐ yǒu shénme xiǎngfa, shuō chūlái tīngting.","vi":"Bạn có ý tưởng gì thì nói ra nghe thử.","en":"If you have any ideas, tell me."},{"use":"A 的想法和 B 不一样","ex":"他的想法和我不一样。","py":"Tā de xiǎngfa hé wǒ bù yíyàng.","vi":"Suy nghĩ của anh ấy khác với tôi.","en":"His thinking is different from mine."},{"use":"Chủ ngữ là 想法, vị ngữ miêu tả","ex":"孩子们的想法常常很有意思。","py":"Háizimen de xiǎngfa chángcháng hěn yǒu yìsi.","vi":"Suy nghĩ của bọn trẻ thường rất thú vị.","en":"Children's ideas are often very interesting."}]},"然而":{"en":"however; but; yet","exs":[{"use":"Liên từ chuyển ý ở vế sau (văn viết)","ex":"他很努力，然而成绩还是不太好。","py":"Tā hěn nǔlì, rán'ér chéngjì háishi bú tài hǎo.","vi":"Anh ấy rất cố gắng, tuy nhiên thành tích vẫn không tốt lắm.","en":"He works hard; however, his grades are still not very good."},{"use":"Chuyển ý trái với dự đoán","ex":"大家都以为会下雨，然而一整天都是晴天。","py":"Dàjiā dōu yǐwéi huì xià yǔ, rán'ér yì zhěng tiān dōu shì qíngtiān.","vi":"Ai cũng tưởng trời sẽ mưa, nhưng cả ngày đều nắng đẹp.","en":"Everyone thought it would rain, yet it was sunny all day."},{"use":"Đối lập 看起来…然而做起来…","ex":"这个办法看起来简单，然而做起来并不容易。","py":"Zhège bànfǎ kàn qǐlái jiǎndān, rán'ér zuò qǐlái bìng bù róngyì.","vi":"Cách này nhìn thì đơn giản, nhưng làm thì không dễ.","en":"This method looks simple, but it isn't easy to carry out."}]},"书本":{"en":"book; textbook","exs":[{"use":"Chỉ sách vở, tri thức sách vở","ex":"学习不能只靠书本，还要多实践。","py":"Xuéxí bù néng zhǐ kào shūběn, hái yào duō shíjiàn.","vi":"Học không thể chỉ dựa vào sách vở mà còn phải thực hành nhiều.","en":"Learning can't rely only on books; you need practice too."},{"use":"Chỉ vật cụ thể: 把书本放进…","ex":"他把书本放进书包里。","py":"Tā bǎ shūběn fàng jìn shūbāo li.","vi":"Anh ấy cho sách vở vào cặp.","en":"He put his books into his schoolbag."},{"use":"书本上的知识: kiến thức trong sách","ex":"书本上的知识要和生活联系起来。","py":"Shūběn shàng de zhīshi yào hé shēnghuó liánxì qǐlái.","vi":"Kiến thức trong sách vở cần gắn liền với cuộc sống.","en":"Knowledge from books should be linked to real life."}]},"内容":{"en":"content; substance","exs":[{"use":"…的内容: nội dung của sách/phim","ex":"这本书的内容很有意思。","py":"Zhè běn shū de nèiróng hěn yǒu yìsi.","vi":"Nội dung cuốn sách này rất thú vị.","en":"The content of this book is very interesting."},{"use":"hỏi nội dung: 说说…的内容","ex":"你能说说会议的内容吗？","py":"Nǐ néng shuōshuo huìyì de nèiróng ma?","vi":"Bạn có thể nói về nội dung cuộc họp không?","en":"Can you tell me what the meeting was about?"},{"use":"内容 + 适合: nói về mức độ phù hợp","ex":"这个节目的内容适合孩子看。","py":"Zhège jiémù de nèiróng shìhé háizi kàn.","vi":"Nội dung chương trình này phù hợp cho trẻ em xem.","en":"The content of this show is suitable for children."}]},"读书":{"en":"to read; to study; to attend school","exs":[{"use":"nghĩa 1: đọc sách (ly hợp)","ex":"他每天晚上都在家读书。","py":"Tā měitiān wǎnshang dōu zài jiā dúshū.","vi":"Tối nào anh ấy cũng ở nhà đọc sách.","en":"He reads at home every evening."},{"use":"nghĩa 2: đi học, theo học ở đâu","ex":"她的女儿在北京读书。","py":"Tā de nǚ'ér zài Běijīng dúshū.","vi":"Con gái cô ấy đang học ở Bắc Kinh.","en":"Her daughter studies in Beijing."},{"use":"多读书: đọc nhiều sách (có ích)","ex":"多读书对学习汉语很有帮助。","py":"Duō dúshū duì xuéxí Hànyǔ hěn yǒu bāngzhù.","vi":"Đọc nhiều sách rất có ích cho việc học tiếng Trung.","en":"Reading more helps a lot with learning Chinese."}]},"相同":{"en":"same; identical","exs":[{"use":"tính từ làm vị ngữ: 爱好相同","ex":"我们的爱好相同，所以常常一起玩儿。","py":"Wǒmen de àihào xiāngtóng, suǒyǐ chángcháng yìqǐ wánr.","vi":"Sở thích của chúng tôi giống nhau nên thường chơi cùng.","en":"We share the same hobbies, so we often play together."},{"use":"不完全相同: không hoàn toàn giống","ex":"这两个词的意思不完全相同。","py":"Zhè liǎng ge cí de yìsi bù wánquán xiāngtóng.","vi":"Nghĩa của hai từ này không hoàn toàn giống nhau.","en":"The meanings of these two words are not exactly the same."},{"use":"相同的 + danh từ: làm định ngữ","ex":"他们穿着相同的衣服。","py":"Tāmen chuānzhe xiāngtóng de yīfu.","vi":"Họ mặc quần áo giống hệt nhau.","en":"They are wearing identical clothes."}]},"汉字":{"en":"Chinese character; Hanzi","exs":[{"use":"Nhận xét về chữ Hán","ex":"汉字很有意思，每个字都像一幅画。","py":"Hànzì hěn yǒu yìsi, měi ge zì dōu xiàng yì fú huà.","vi":"Chữ Hán rất thú vị, mỗi chữ đều như một bức tranh.","en":"Chinese characters are interesting; each one looks like a picture."},{"use":"会写 + số lượng + 个汉字","ex":"我现在会写三百个汉字。","py":"Wǒ xiànzài huì xiě sānbǎi ge Hànzì.","vi":"Bây giờ tôi biết viết ba trăm chữ Hán.","en":"I can now write three hundred Chinese characters."},{"use":"hỏi cách đọc: 这个汉字怎么读","ex":"这个汉字怎么读？","py":"Zhège Hànzì zěnme dú?","vi":"Chữ Hán này đọc thế nào?","en":"How do you read this character?"}]},"表示":{"en":"to express; to show; to indicate; to mean","exs":[{"use":"nghĩa 1: bày tỏ thái độ","ex":"他点点头，表示同意。","py":"Tā diǎndian tóu, biǎoshì tóngyì.","vi":"Anh ấy gật đầu, tỏ ý đồng ý.","en":"He nodded to show his agreement."},{"use":"nghĩa 2: biểu thị, có nghĩa là","ex":"红灯表示不能过马路。","py":"Hóngdēng biǎoshì bù néng guò mǎlù.","vi":"Đèn đỏ có nghĩa là không được qua đường.","en":"A red light means you must not cross the road."},{"use":"对 + ai + 表示 + cảm xúc","ex":"我想对你表示感谢。","py":"Wǒ xiǎng duì nǐ biǎoshì gǎnxiè.","vi":"Tôi muốn bày tỏ lòng cảm ơn với bạn.","en":"I'd like to express my thanks to you."}]},"世界":{"en":"world","exs":[{"use":"Chỉ thế giới nói chung","ex":"世界很大，我想去看看。","py":"Shìjiè hěn dà, wǒ xiǎng qù kànkan.","vi":"Thế giới rất rộng lớn, tôi muốn đi xem thử.","en":"The world is big, and I want to go see it."},{"use":"世界 làm định ngữ: 世界有名","ex":"他是世界有名的歌手。","py":"Tā shì shìjiè yǒumíng de gēshǒu.","vi":"Anh ấy là ca sĩ nổi tiếng thế giới.","en":"He is a world-famous singer."},{"use":"世界上: trên thế giới","ex":"汉语已经成为世界上很多人学习的语言。","py":"Hànyǔ yǐjīng chéngwéi shìjiè shàng hěn duō rén xuéxí de yǔyán.","vi":"Tiếng Trung đã trở thành ngôn ngữ mà nhiều người trên thế giới học.","en":"Chinese has become a language that many people around the world study."}]},"阅读":{"en":"to read; reading","exs":[{"use":"động từ: đọc, đọc hiểu","ex":"我喜欢在安静的地方阅读。","py":"Wǒ xǐhuan zài ānjìng de dìfang yuèdú.","vi":"Tôi thích đọc ở nơi yên tĩnh.","en":"I like reading in a quiet place."},{"use":"động từ + tân ngữ: 阅读 + tài liệu","ex":"他每天阅读一小时的英文新闻。","py":"Tā měitiān yuèdú yì xiǎoshí de Yīngwén xīnwén.","vi":"Mỗi ngày anh ấy đọc tin tức tiếng Anh một tiếng.","en":"He reads English news for an hour every day."},{"use":"danh từ làm chủ ngữ: 阅读对…有帮助","ex":"阅读对提高汉语水平很有帮助。","py":"Yuèdú duì tígāo Hànyǔ shuǐpíng hěn yǒu bāngzhù.","vi":"Việc đọc rất có ích cho việc nâng cao trình độ tiếng Trung.","en":"Reading is very helpful for improving your Chinese."}]},"同时":{"en":"at the same time; meanwhile; moreover","exs":[{"use":"Chỉ hai việc xảy ra cùng lúc: 一边…，同时…","ex":"他一边工作，同时还在学习汉语。","py":"Tā yìbiān gōngzuò, tóngshí hái zài xuéxí Hànyǔ.","vi":"Anh ấy vừa làm việc, đồng thời còn đang học tiếng Trung.","en":"He works and, at the same time, is studying Chinese."},{"use":"Trạng ngữ: 同时 + động từ","ex":"两个人同时说了“你好”。","py":"Liǎng ge rén tóngshí shuōle “nǐ hǎo”.","vi":"Hai người cùng lúc nói “xin chào”.","en":"The two of them said “hello” at the same time."},{"use":"Liên từ: bổ sung ý, 同时也…","ex":"这个工作很有意思，同时也很辛苦。","py":"Zhège gōngzuò hěn yǒu yìsi, tóngshí yě hěn xīnkǔ.","vi":"Công việc này rất thú vị, đồng thời cũng rất vất vả.","en":"This job is interesting, but it is also very tiring."}]},"情感":{"en":"emotion; feeling; affection","exs":[{"use":"表达 + 情感: bày tỏ tình cảm","ex":"这首歌表达了他对家人的情感。","py":"Zhè shǒu gē biǎodále tā duì jiārén de qínggǎn.","vi":"Bài hát này thể hiện tình cảm của anh ấy với gia đình.","en":"This song expresses his feelings for his family."},{"use":"情感 + 支持: sự hỗ trợ tinh thần","ex":"孩子需要父母的情感支持。","py":"Háizi xūyào fùmǔ de qínggǎn zhīchí.","vi":"Trẻ em cần sự hỗ trợ về tình cảm của cha mẹ.","en":"Children need their parents' emotional support."},{"use":"真实的情感: tình cảm chân thật","ex":"好的文章要有真实的情感。","py":"Hǎo de wénzhāng yào yǒu zhēnshí de qínggǎn.","vi":"Bài văn hay cần có tình cảm chân thật.","en":"A good piece of writing needs genuine emotion."}]},"大卫":{"en":"David (personal name)","exs":[{"use":"Tên người nước ngoài (phiên âm David)","ex":"大卫是我的美国同事。","py":"Dàwèi shì wǒ de Měiguó tóngshì.","vi":"David là đồng nghiệp người Mỹ của tôi.","en":"David is my American colleague."},{"use":"Làm chủ ngữ","ex":"大卫每天早上都去公园跑步。","py":"Dàwèi měitiān zǎoshang dōu qù gōngyuán pǎobù.","vi":"Sáng nào David cũng ra công viên chạy bộ.","en":"David goes jogging in the park every morning."},{"use":"和 + 大卫 + 一起: cùng với David","ex":"我明天要和大卫一起去看电影。","py":"Wǒ míngtiān yào hé Dàwèi yìqǐ qù kàn diànyǐng.","vi":"Ngày mai tôi sẽ đi xem phim cùng David.","en":"Tomorrow I'm going to the movies with David."}]},"汉语":{"en":"Chinese language (Mandarin)","exs":[{"use":"说 + 汉语 + 得 + adj","ex":"你的汉语说得真好。","py":"Nǐ de Hànyǔ shuō de zhēn hǎo.","vi":"Tiếng Trung của bạn nói thật giỏi.","en":"You speak Chinese really well."},{"use":"学习汉语 + thời lượng","ex":"我在大学学习汉语已经两年了。","py":"Wǒ zài dàxué xuéxí Hànyǔ yǐjīng liǎng nián le.","vi":"Tôi học tiếng Trung ở đại học đã hai năm rồi.","en":"I have been studying Chinese at university for two years."},{"use":"对…来说: nói về độ khó","ex":"汉语的发音对外国人来说有点儿难。","py":"Hànyǔ de fāyīn duì wàiguórén lái shuō yǒudiǎnr nán.","vi":"Phát âm tiếng Trung đối với người nước ngoài hơi khó.","en":"Chinese pronunciation is a bit difficult for foreigners."}]},"流利":{"en":"fluent; smooth","exs":[{"use":"V + 得 + 很流利","ex":"他的英语说得很流利。","py":"Tā de Yīngyǔ shuō de hěn liúlì.","vi":"Anh ấy nói tiếng Anh rất lưu loát.","en":"He speaks English very fluently."},{"use":"流利地 + động từ: làm trạng ngữ","ex":"她能流利地用汉语介绍自己。","py":"Tā néng liúlì de yòng Hànyǔ jièshào zìjǐ.","vi":"Cô ấy có thể giới thiệu bản thân bằng tiếng Trung một cách lưu loát.","en":"She can introduce herself fluently in Chinese."},{"use":"想…就得…: điều kiện để nói lưu loát","ex":"要想说得流利，就得多练习。","py":"Yào xiǎng shuō de liúlì, jiù děi duō liànxí.","vi":"Muốn nói lưu loát thì phải luyện tập nhiều.","en":"If you want to speak fluently, you must practice a lot."}]},"厉害":{"en":"awesome; impressive; terrible; severe","exs":[{"use":"nghĩa 1: giỏi, lợi hại (khen ngợi)","ex":"他篮球打得很厉害。","py":"Tā lánqiú dǎ de hěn lìhai.","vi":"Anh ấy chơi bóng rổ rất cừ.","en":"He plays basketball really well."},{"use":"nghĩa 2: adj + 得厉害: ghê gớm, nặng","ex":"今天冷得厉害，多穿点衣服。","py":"Jīntiān lěng de lìhai, duō chuān diǎn yīfu.","vi":"Hôm nay lạnh kinh khủng, mặc thêm áo vào.","en":"It's terribly cold today, so wear more clothes."},{"use":"Câu cảm thán khen: 真厉害","ex":"你一个人做了这么多工作，真厉害！","py":"Nǐ yí ge rén zuòle zhème duō gōngzuò, zhēn lìhai!","vi":"Một mình bạn làm nhiều việc thế này, giỏi thật!","en":"You did all this work by yourself. Impressive!"}]},"语法":{"en":"grammar","exs":[{"use":"nhận xét độ khó","ex":"汉语语法不太难。","py":"Hànyǔ yǔfǎ bú tài nán.","vi":"Ngữ pháp tiếng Trung không quá khó.","en":"Chinese grammar is not too difficult."},{"use":"讲语法: giảng ngữ pháp","ex":"老师正在讲这个句子的语法。","py":"Lǎoshī zhèngzài jiǎng zhège jùzi de yǔfǎ.","vi":"Thầy giáo đang giảng ngữ pháp của câu này.","en":"The teacher is explaining the grammar of this sentence."},{"use":"语法错误: lỗi ngữ pháp","ex":"我常常犯语法错误。","py":"Wǒ chángcháng fàn yǔfǎ cuòwù.","vi":"Tôi thường mắc lỗi ngữ pháp.","en":"I often make grammar mistakes."}]},"准确":{"en":"accurate; precise; exact","exs":[{"use":"准确地 + động từ.","ex":"这个答案很准确。","py":"Zhège dá'àn hěn zhǔnquè.","vi":"Đáp án này rất chính xác.","en":"This answer is very accurate."},{"use":"tính từ: 发音准确","ex":"他的发音很准确。","py":"Tā de fāyīn hěn zhǔnquè.","vi":"Phát âm của anh ấy rất chuẩn.","en":"His pronunciation is very accurate."},{"use":"准确地 + động từ: làm trạng ngữ","ex":"请准确地告诉我你到达的时间。","py":"Qǐng zhǔnquè de gàosu wǒ nǐ dàodá de shíjiān.","vi":"Xin hãy cho tôi biết chính xác thời gian bạn đến.","en":"Please tell me exactly when you will arrive."},{"use":"phủ định: 不一定准确","ex":"天气预报不一定每次都准确。","py":"Tiānqì yùbào bù yídìng měi cì dōu zhǔnquè.","vi":"Dự báo thời tiết chưa chắc lần nào cũng chính xác.","en":"The weather forecast isn't necessarily accurate every time."}]},"中国人":{"en":"Chinese person; the Chinese","exs":[{"use":"Chỉ quốc tịch/dân tộc: 是中国人","ex":"他是中国人，但是在美国长大。","py":"Tā shì Zhōngguórén, dànshì zài Měiguó zhǎngdà.","vi":"Anh ấy là người Trung Quốc nhưng lớn lên ở Mỹ.","en":"He is Chinese, but grew up in the United States."},{"use":"Nói chung về người Trung Quốc","ex":"很多中国人喜欢喝茶。","py":"Hěn duō Zhōngguórén xǐhuan hē chá.","vi":"Nhiều người Trung Quốc thích uống trà.","en":"Many Chinese people like drinking tea."},{"use":"和 + 中国人 + 聊天: giao tiếp","ex":"我想多和中国人聊天，练习口语。","py":"Wǒ xiǎng duō hé Zhōngguórén liáotiān, liànxí kǒuyǔ.","vi":"Tôi muốn trò chuyện nhiều với người Trung Quốc để luyện nói.","en":"I want to chat with Chinese people more to practice speaking."}]},"做到":{"en":"to accomplish; to achieve; to make it happen","exs":[{"use":"能做到: có thể làm được","ex":"只要努力，你一定能做到。","py":"Zhǐyào nǔlì, nǐ yídìng néng zuòdào.","vi":"Chỉ cần cố gắng, bạn nhất định làm được.","en":"As long as you work hard, you can definitely do it."},{"use":"说到做到: nói được làm được","ex":"说到做到，才是好朋友。","py":"Shuōdào zuòdào, cái shì hǎo péngyou.","vi":"Nói được làm được mới là bạn tốt.","en":"Only those who do what they say are good friends."},{"use":"…做到了: đã thực hiện được","ex":"他答应的事情都做到了。","py":"Tā dāying de shìqing dōu zuòdào le.","vi":"Những việc anh ấy đã hứa đều làm được.","en":"He has done everything he promised."},{"use":"是怎么做到的: hỏi cách làm được","ex":"这么难的事，你是怎么做到的？","py":"Zhème nán de shì, nǐ shì zěnme zuòdào de?","vi":"Việc khó như vậy, bạn làm được bằng cách nào?","en":"Such a hard thing: how did you manage it?"}]},"聊天儿":{"en":"to chat","exs":[{"use":"động từ ly hợp: 去…聊天儿","ex":"周末我们一起去咖啡馆聊天儿吧。","py":"Zhōumò wǒmen yìqǐ qù kāfēiguǎn liáo tiānr ba.","vi":"Cuối tuần chúng ta cùng đến quán cà phê tán gẫu nhé.","en":"Let's go chat at a café this weekend."},{"use":"和 + ai + 聊天儿","ex":"他喜欢和邻居聊天儿。","py":"Tā xǐhuan hé línjū liáo tiānr.","vi":"Anh ấy thích trò chuyện với hàng xóm.","en":"He likes chatting with his neighbors."},{"use":"给 + ai + 打电话聊天儿","ex":"奶奶常常给我打电话聊天儿。","py":"Nǎinai chángcháng gěi wǒ dǎ diànhuà liáo tiānr.","vi":"Bà thường gọi điện cho tôi để trò chuyện.","en":"Grandma often calls me for a chat."}]},"中文":{"en":"Chinese (language)","exs":[{"use":"会说中文: biết nói tiếng Trung","ex":"你会说中文吗？","py":"Nǐ huì shuō Zhōngwén ma?","vi":"Bạn biết nói tiếng Trung không?","en":"Can you speak Chinese?"},{"use":"用中文 + động từ: bằng tiếng Trung","ex":"这本书是用中文写的。","py":"Zhè běn shū shì yòng Zhōngwén xiě de.","vi":"Cuốn sách này được viết bằng tiếng Trung.","en":"This book is written in Chinese."},{"use":"中文 làm định ngữ: 中文名字","ex":"他的中文名字很好听。","py":"Tā de Zhōngwén míngzi hěn hǎotīng.","vi":"Tên tiếng Trung của anh ấy rất hay.","en":"His Chinese name sounds nice."}]},"新词语":{"en":"new words; new vocabulary","exs":[{"use":"Số lượng + 新词语","ex":"老师每天教我们五个新词语。","py":"Lǎoshī měitiān jiāo wǒmen wǔ ge xīncíyǔ.","vi":"Mỗi ngày thầy giáo dạy chúng tôi năm từ mới.","en":"The teacher teaches us five new words every day."},{"use":"记下新词语: ghi lại từ mới","ex":"我用本子记下了今天学的新词语。","py":"Wǒ yòng běnzi jì xiàle jīntiān xué de xīncíyǔ.","vi":"Tôi dùng quyển vở ghi lại những từ mới học hôm nay.","en":"I wrote down today's new words in my notebook."},{"use":"遇到新词语: gặp từ mới","ex":"读文章时遇到新词语，要查词典。","py":"Dú wénzhāng shí yùdào xīncíyǔ, yào chá cídiǎn.","vi":"Khi đọc bài mà gặp từ mới thì phải tra từ điển.","en":"When you meet new words while reading, look them up in a dictionary."}]},"看得懂":{"en":"can understand (by reading/watching)","exs":[{"use":"V + 得 + 懂: khả năng, có thể hiểu","ex":"这篇文章我看得懂。","py":"Zhè piān wénzhāng wǒ kàn de dǒng.","vi":"Bài văn này tôi đọc hiểu được.","en":"I can understand this article."},{"use":"Câu hỏi: 看得懂…吗","ex":"你看得懂中文电影吗？","py":"Nǐ kàn de dǒng Zhōngwén diànyǐng ma?","vi":"Bạn xem hiểu phim tiếng Trung không?","en":"Can you understand Chinese movies?"},{"use":"没有…也看得懂: dù không có … vẫn hiểu","ex":"没有字幕，你也看得懂吗？","py":"Méiyǒu zìmù, nǐ yě kàn de dǒng ma?","vi":"Không có phụ đề, bạn cũng xem hiểu chứ?","en":"Without subtitles, can you still follow it?"}]},"本子":{"en":"notebook; exercise book","exs":[{"use":"Chỉ quyển vở: 把本子拿出来","ex":"请把本子拿出来，我们记一下。","py":"Qǐng bǎ běnzi ná chūlái, wǒmen jì yíxià.","vi":"Hãy lấy quyển vở ra, chúng ta ghi lại một chút.","en":"Please take out your notebooks and let's write this down."},{"use":"数量 + 个 + 本子","ex":"我买了两个新本子。","py":"Wǒ mǎile liǎng ge xīn běnzi.","vi":"Tôi đã mua hai quyển vở mới.","en":"I bought two new notebooks."},{"use":"本子上: ở trên vở","ex":"他的本子上写满了汉字。","py":"Tā de běnzi shàng xiěmǎnle Hànzì.","vi":"Quyển vở của anh ấy viết đầy chữ Hán.","en":"His notebook is filled with Chinese characters."}]},"出来":{"en":"to come out; to go out; (complement) out","exs":[{"use":"động từ: 走出来 (đi ra)","ex":"他从房间里走出来了。","py":"Tā cóng fángjiān li zǒu chūlái le.","vi":"Anh ấy từ trong phòng đi ra.","en":"He walked out of the room."},{"use":"Chỉ sự xuất hiện: 太阳出来了","ex":"太阳出来了，天气暖和多了。","py":"Tàiyáng chūlái le, tiānqì nuǎnhuo duō le.","vi":"Mặt trời ló ra rồi, trời ấm hơn nhiều.","en":"The sun has come out, and it's much warmer."},{"use":"Bổ ngữ xu hướng nghĩa mở rộng: 听出来 (nhận ra)","ex":"你能听出来这是谁的声音吗？","py":"Nǐ néng tīng chūlái zhè shì shéi de shēngyīn ma?","vi":"Bạn có nghe ra đây là giọng của ai không?","en":"Can you tell whose voice this is?"}]},"复习":{"en":"to review; to revise","exs":[{"use":"复习 + trước kỳ thi","ex":"明天要考试，我今天晚上要复习。","py":"Míngtiān yào kǎoshì, wǒ jīntiān wǎnshang yào fùxí.","vi":"Ngày mai thi, tối nay tôi phải ôn bài.","en":"I have an exam tomorrow, so I need to review tonight."},{"use":"复习 + tân ngữ: 复习生词","ex":"回家以后，请复习今天学的生词。","py":"Huí jiā yǐhòu, qǐng fùxí jīntiān xué de shēngcí.","vi":"Sau khi về nhà, hãy ôn lại từ mới học hôm nay.","en":"After you get home, please review today's new words."},{"use":"带…复习: dẫn dắt ôn tập","ex":"老师带我们复习了第三课。","py":"Lǎoshī dài wǒmen fùxíle dì-sān kè.","vi":"Thầy giáo đã cùng chúng tôi ôn lại bài ba.","en":"The teacher led us in reviewing Lesson 3."}]},"说真的":{"en":"to be honest; really; seriously","exs":[{"use":"Mở đầu câu nêu ý thật lòng","ex":"说真的，我不太喜欢这家饭店。","py":"Shuō zhēn de, wǒ bú tài xǐhuan zhè jiā fàndiàn.","vi":"Nói thật, tôi không thích quán này lắm.","en":"Honestly, I don't like this restaurant very much."},{"use":"Dùng để khen thật lòng","ex":"说真的，你的汉语进步很大。","py":"Shuō zhēn de, nǐ de Hànyǔ jìnbù hěn dà.","vi":"Nói thật, tiếng Trung của bạn tiến bộ rất nhiều.","en":"Honestly, your Chinese has improved a lot."},{"use":"Dùng để tâm sự","ex":"说真的，我昨天一晚上没睡好。","py":"Shuō zhēn de, wǒ zuótiān yì wǎnshang méi shuìhǎo.","vi":"Nói thật, tối qua tôi cả đêm không ngủ ngon.","en":"To be honest, I didn't sleep well all night last night."}]},"来得及":{"en":"to be in time; to have enough time to","exs":[{"use":"Động từ: còn kịp, còn đủ thời gian (làm gì)","ex":"现在出发还来得及赶火车。","py":"Xiànzài chūfā hái láidejí gǎn huǒchē.","vi":"Bây giờ xuất phát vẫn còn kịp bắt tàu.","en":"If we leave now, we can still catch the train."},{"use":"Dạng câu hỏi: 还来得及吗？","ex":"现在去商店还来得及吗？","py":"Xiànzài qù shāngdiàn hái láidejí ma?","vi":"Bây giờ đến cửa hàng có còn kịp không?","en":"Is there still time to go to the store now?"},{"use":"来得及 + V: có đủ thời gian để làm gì","ex":"你别着急，我们还来得及准备。","py":"Nǐ bié zháojí, wǒmen hái láidejí zhǔnbèi.","vi":"Bạn đừng vội, chúng ta vẫn kịp chuẩn bị.","en":"Don't worry, we still have time to get ready."},{"use":"Dùng sau 如果/只要để nói điều kiện còn kịp","ex":"如果你现在开始复习，肯定来得及。","py":"Rúguǒ nǐ xiànzài kāishǐ fùxí, kěndìng láidejí.","vi":"Nếu bây giờ bạn bắt đầu ôn tập thì chắc chắn còn kịp.","en":"If you start reviewing now, you will definitely have enough time."}]},"比较复杂":{"en":"rather complicated; fairly complex","exs":[{"use":"比较 + adj làm vị ngữ: khá phức tạp","ex":"这个问题比较复杂，我需要想一想。","py":"Zhège wèntí bǐjiào fùzá, wǒ xūyào xiǎng yi xiǎng.","vi":"Vấn đề này khá phức tạp, tôi cần suy nghĩ một chút.","en":"This problem is rather complicated; I need to think about it."},{"use":"Nói về thủ tục, quy trình phức tạp","ex":"办签证的手续比较复杂，你最好早点儿准备。","py":"Bàn qiānzhèng de shǒuxù bǐjiào fùzá, nǐ zuìhǎo zǎodiǎnr zhǔnbèi.","vi":"Thủ tục làm visa khá phức tạp, tốt nhất bạn nên chuẩn bị sớm.","en":"The visa procedure is fairly complicated, so you'd better prepare early."},{"use":"Nói về quan hệ, tình hình phức tạp","ex":"他们家的关系比较复杂，我不太了解。","py":"Tāmen jiā de guānxì bǐjiào fùzá, wǒ bú tài liǎojiě.","vi":"Quan hệ trong gia đình họ khá phức tạp, tôi không hiểu rõ lắm.","en":"Their family relationships are rather complicated, and I don't understand them very well."},{"use":"Nói về cách làm, quy trình","ex":"这道菜的做法比较复杂，需要很多时间。","py":"Zhè dào cài de zuòfǎ bǐjiào fùzá, xūyào hěn duō shíjiān.","vi":"Cách làm món này khá phức tạp, cần nhiều thời gian.","en":"This dish is fairly complicated to make and takes a lot of time."}]},"只好":{"en":"have no choice but to; had to","exs":[{"use":"只好 + V: đành phải, vì hoàn cảnh bắt buộc","ex":"雨太大了，我们只好在家看电影。","py":"Yǔ tài dà le, wǒmen zhǐhǎo zài jiā kàn diànyǐng.","vi":"Mưa to quá, chúng tôi đành ở nhà xem phim.","en":"It rained too hard, so we had no choice but to watch a movie at home."},{"use":"Vế sau của câu nguyên nhân - kết quả","ex":"末班车已经走了，他只好打车回家。","py":"Mòbānchē yǐjīng zǒu le, tā zhǐhǎo dǎchē huí jiā.","vi":"Chuyến xe buýt cuối đã đi rồi, anh ấy đành đi taxi về nhà.","en":"The last bus had already left, so he had to take a taxi home."},{"use":"Thường dùng với 再/只好 + thời gian khác","ex":"商店关门了，我只好明天再来。","py":"Shāngdiàn guānmén le, wǒ zhǐhǎo míngtiān zài lái.","vi":"Cửa hàng đóng cửa rồi, tôi đành ngày mai quay lại.","en":"The shop was closed, so I had to come back tomorrow."}]},"填空题":{"en":"fill-in-the-blank question","exs":[{"use":"Danh từ, lượng từ thường dùng là 道","ex":"这次考试有十道填空题。","py":"Zhè cì kǎoshì yǒu shí dào tiánkòngtí.","vi":"Kỳ thi lần này có mười câu điền vào chỗ trống.","en":"This exam has ten fill-in-the-blank questions."},{"use":"So sánh với 选择题","ex":"我觉得填空题比选择题难。","py":"Wǒ juéde tiánkòngtí bǐ xuǎnzétí nán.","vi":"Tôi thấy câu điền từ khó hơn câu trắc nghiệm.","en":"I think fill-in-the-blank questions are harder than multiple-choice ones."},{"use":"做 + 填空题: làm bài điền từ","ex":"老师让我们做完这些填空题再下课。","py":"Lǎoshī ràng wǒmen zuòwán zhèxiē tiánkòngtí zài xiàkè.","vi":"Cô giáo bảo chúng tôi làm xong các câu điền từ này rồi mới tan học.","en":"The teacher asked us to finish these fill-in-the-blank questions before class ends."}]},"选择题":{"en":"multiple-choice question","exs":[{"use":"Danh từ, lượng từ thường dùng là 道","ex":"这张试卷有二十道选择题。","py":"Zhè zhāng shìjuàn yǒu èrshí dào xuǎnzétí.","vi":"Tờ đề thi này có hai mươi câu trắc nghiệm.","en":"This test paper has twenty multiple-choice questions."},{"use":"做 + 选择题: làm bài trắc nghiệm","ex":"做选择题的时候，我常常先排除错误答案。","py":"Zuò xuǎnzétí de shíhou, wǒ chángcháng xiān páichú cuòwù dáàn.","vi":"Khi làm câu trắc nghiệm, tôi thường loại trừ đáp án sai trước.","en":"When doing multiple-choice questions, I often eliminate the wrong answers first."},{"use":"Làm chủ ngữ, nói về tỉ lệ điểm","ex":"选择题的分数占总分的一半。","py":"Xuǎnzétí de fēnshù zhàn zǒngfēn de yíbàn.","vi":"Điểm của phần trắc nghiệm chiếm một nửa tổng điểm.","en":"The multiple-choice section counts for half of the total score."}]},"随便":{"en":"casual; as one pleases; careless","exs":[{"use":"Trả lời 'sao cũng được', tùy bạn","ex":"你想吃什么？——随便，我什么都可以。","py":"Nǐ xiǎng chī shénme? —Suíbiàn, wǒ shénme dōu kěyǐ.","vi":"Bạn muốn ăn gì? – Tùy, gì tôi cũng được.","en":"What do you want to eat? —Anything is fine with me."},{"use":"随便 + V: tùy tiện, bừa bãi (nghĩa không tốt)","ex":"不要随便动别人的东西。","py":"Búyào suíbiàn dòng biérén de dōngxi.","vi":"Đừng tùy tiện động vào đồ của người khác.","en":"Don't touch other people's things without asking."},{"use":"Mời khách: cứ tự nhiên","ex":"你随便坐，不用客气。","py":"Nǐ suíbiàn zuò, búyòng kèqi.","vi":"Bạn cứ ngồi tự nhiên, đừng khách sáo.","en":"Sit wherever you like; make yourself at home."},{"use":"Làm vị ngữ: giản dị, thoải mái","ex":"他穿得很随便，像个学生。","py":"Tā chuān de hěn suíbiàn, xiàng ge xuésheng.","vi":"Anh ấy ăn mặc rất giản dị, trông như học sinh.","en":"He dresses very casually, like a student."}]},"答案":{"en":"answer; key","exs":[{"use":"Danh từ: đáp án của câu hỏi","ex":"这道题的答案是什么？","py":"Zhè dào tí de dáàn shì shénme?","vi":"Đáp án của câu này là gì?","en":"What is the answer to this question?"},{"use":"对答案: đối chiếu đáp án","ex":"做完练习后，请对一下答案。","py":"Zuòwán liànxí hòu, qǐng duì yíxià dáàn.","vi":"Làm xong bài tập, hãy đối chiếu đáp án.","en":"After finishing the exercises, please check your answers."},{"use":"标准答案: đáp án chuẩn","ex":"这个问题没有标准答案，说出你的想法就行。","py":"Zhège wèntí méiyǒu biāozhǔn dáàn, shuōchū nǐ de xiǎngfǎ jiù xíng.","vi":"Câu hỏi này không có đáp án chuẩn, bạn cứ nói suy nghĩ của mình là được.","en":"There is no standard answer to this question; just say what you think."}]},"否则":{"en":"otherwise; or else","exs":[{"use":"否则 nối hai vế: nếu không thì... (hậu quả xấu)","ex":"快走吧，否则我们要迟到了。","py":"Kuài zǒu ba, fǒuzé wǒmen yào chídào le.","vi":"Đi nhanh lên, nếu không chúng ta sẽ muộn mất.","en":"Hurry up, or else we'll be late."},{"use":"Vế trước nêu yêu cầu, vế sau nêu hậu quả","ex":"你必须按时吃药，否则病不会好。","py":"Nǐ bìxū ànshí chī yào, fǒuzé bìng bú huì hǎo.","vi":"Bạn phải uống thuốc đúng giờ, nếu không bệnh sẽ không khỏi.","en":"You must take your medicine on time, otherwise you won't get better."},{"use":"Lời nhắc, dặn dò","ex":"出门要带伞，否则会被雨淋湿。","py":"Chūmén yào dài sǎn, fǒuzé huì bèi yǔ línshī.","vi":"Ra ngoài phải mang ô, không thì sẽ bị mưa ướt.","en":"Take an umbrella when you go out, or you'll get soaked by the rain."}]},"客厅":{"en":"living room","exs":[{"use":"Danh từ chỉ nơi chốn: phòng khách","ex":"客人来了，请他们先坐在客厅。","py":"Kèrén lái le, qǐng tāmen xiān zuò zài kètīng.","vi":"Khách đến rồi, mời họ ngồi ở phòng khách trước.","en":"The guests have arrived; please have them sit in the living room first."},{"use":"Làm chủ ngữ, miêu tả căn nhà","ex":"我家的客厅不大，但是很干净。","py":"Wǒ jiā de kètīng bú dà, dànshì hěn gānjìng.","vi":"Phòng khách nhà tôi không lớn nhưng rất sạch sẽ.","en":"The living room in my home isn't big, but it's very clean."},{"use":"在 + 客厅 + 里 + V: hoạt động trong phòng khách","ex":"孩子们在客厅里看电视。","py":"Háizimen zài kètīng lǐ kàn diànshì.","vi":"Bọn trẻ đang xem tivi trong phòng khách.","en":"The children are watching TV in the living room."}]},"无论是":{"en":"whether it is ... or ...; no matter whether","exs":[{"use":"无论是…还是…，都…: dù là A hay B đều...","ex":"无论是工作还是学习，我们都要认真。","py":"Wúlùn shì gōngzuò háishi xuéxí, wǒmen dōu yào rènzhēn.","vi":"Dù là công việc hay học tập, chúng ta đều phải nghiêm túc.","en":"Whether it's work or study, we must be serious."},{"use":"无论是 + người A + 还是 + người B","ex":"无论是大人还是孩子，都喜欢这个游戏。","py":"Wúlùn shì dàrén háishi háizi, dōu xǐhuan zhège yóuxì.","vi":"Dù là người lớn hay trẻ con đều thích trò chơi này.","en":"Whether adults or children, everyone likes this game."},{"use":"无论是 + cụm động từ + 还是 + cụm động từ","ex":"无论是坐飞机还是坐火车，都要提前买票。","py":"Wúlùn shì zuò fēijī háishi zuò huǒchē, dōu yào tíqián mǎi piào.","vi":"Dù đi máy bay hay đi tàu hỏa đều phải mua vé trước.","en":"Whether you go by plane or by train, you need to buy tickets in advance."}]},"杂志":{"en":"magazine","exs":[{"use":"Danh từ, lượng từ: 本","ex":"我每个月都买一本旅游杂志。","py":"Wǒ měi ge yuè dōu mǎi yì běn lǚyóu zázhì.","vi":"Mỗi tháng tôi đều mua một cuốn tạp chí du lịch.","en":"I buy a travel magazine every month."},{"use":"在杂志上: trên tạp chí","ex":"他在杂志上看到了这个消息。","py":"Tā zài zázhì shàng kàndào le zhège xiāoxi.","vi":"Anh ấy đã đọc được tin này trên tạp chí.","en":"He saw this news in a magazine."},{"use":"Làm định ngữ chỉ loại: 英文杂志","ex":"图书馆里有很多英文杂志。","py":"Túshūguǎn lǐ yǒu hěn duō Yīngwén zázhì.","vi":"Trong thư viện có rất nhiều tạp chí tiếng Anh.","en":"The library has many English magazines."}]},"著名":{"en":"famous; well-known","exs":[{"use":"著名 + 的 + danh từ: làm định ngữ","ex":"这位著名的作家来过我们学校。","py":"Zhè wèi zhùmíng de zuòjiā láiguo wǒmen xuéxiào.","vi":"Nhà văn nổi tiếng này đã từng đến trường chúng tôi.","en":"This famous writer has visited our school."},{"use":"Làm vị ngữ: 很/非常 + 著名","ex":"北京烤鸭非常著名。","py":"Běijīng kǎoyā fēicháng zhùmíng.","vi":"Vịt quay Bắc Kinh vô cùng nổi tiếng.","en":"Beijing roast duck is extremely famous."},{"use":"以…而著名: nổi tiếng vì...","ex":"杭州以美丽的西湖而著名。","py":"Hángzhōu yǐ měilì de Xīhú ér zhùmíng.","vi":"Hàng Châu nổi tiếng nhờ Tây Hồ xinh đẹp.","en":"Hangzhou is famous for its beautiful West Lake."}]},"分钟":{"en":"minute","exs":[{"use":"Số + 分钟: chỉ khoảng thời gian","ex":"从我家到公司要四十分钟。","py":"Cóng wǒ jiā dào gōngsī yào sìshí fēnzhōng.","vi":"Từ nhà tôi đến công ty mất bốn mươi phút.","en":"It takes forty minutes from my home to the company."},{"use":"等 + số + 分钟: chờ bao lâu","ex":"请等我五分钟，我马上就来。","py":"Qǐng děng wǒ wǔ fēnzhōng, wǒ mǎshàng jiù lái.","vi":"Xin đợi tôi năm phút, tôi đến ngay.","en":"Please wait five minutes for me; I'll be right there."},{"use":"V + số + 分钟: thời lượng hoạt động","ex":"每天我跑步三十分钟。","py":"Měi tiān wǒ pǎobù sānshí fēnzhōng.","vi":"Mỗi ngày tôi chạy bộ ba mươi phút.","en":"I run for thirty minutes every day."},{"use":"Nói độ dài của phim, buổi họp","ex":"这个电影只有九十分钟，不太长。","py":"Zhège diànyǐng zhǐ yǒu jiǔshí fēnzhōng, bú tài cháng.","vi":"Bộ phim này chỉ dài chín mươi phút, không quá dài.","en":"This movie is only ninety minutes long, which isn't too long."}]},"半个":{"en":"half (a); half of","exs":[{"use":"半个 + danh từ: nửa cái (quả, vật)","ex":"我吃了半个西瓜。","py":"Wǒ chīle bàn ge xīguā.","vi":"Tôi đã ăn nửa quả dưa hấu.","en":"I ate half a watermelon."},{"use":"半个 + 小时/月: nửa giờ, nửa tháng","ex":"他等了半个小时。","py":"Tā děngle bàn ge xiǎoshí.","vi":"Anh ấy đã chờ nửa tiếng.","en":"He waited for half an hour."},{"use":"半个月后: nửa tháng sau","ex":"半个月后我们要去上海旅行。","py":"Bàn ge yuè hòu wǒmen yào qù Shànghǎi lǚxíng.","vi":"Nửa tháng nữa chúng tôi sẽ đi du lịch Thượng Hải.","en":"In half a month we are going to travel to Shanghai."},{"use":"Chỉ ăn/dùng một nửa","ex":"这个苹果太大了，我只吃半个。","py":"Zhège píngguǒ tài dà le, wǒ zhǐ chī bàn ge.","vi":"Quả táo này to quá, tôi chỉ ăn nửa quả.","en":"This apple is too big; I'll only eat half."}]},"增加":{"en":"to increase; to add","exs":[{"use":"增加 + tân ngữ: tăng thêm cái gì","ex":"公司今年增加了不少新员工。","py":"Gōngsī jīnnián zēngjiāle bù shǎo xīn yuángōng.","vi":"Năm nay công ty tăng thêm không ít nhân viên mới.","en":"The company has added quite a few new employees this year."},{"use":"增加 + 知识/经验: làm tăng tri thức","ex":"多读书可以增加知识。","py":"Duō dúshū kěyǐ zēngjiā zhīshi.","vi":"Đọc nhiều sách có thể làm tăng kiến thức.","en":"Reading more can increase your knowledge."},{"use":"Nội động từ: tự tăng lên, 一年比一年增加","ex":"城市的人口一年比一年增加。","py":"Chéngshì de rénkǒu yì nián bǐ yì nián zēngjiā.","vi":"Dân số thành phố năm sau tăng hơn năm trước.","en":"The city's population increases year after year."},{"use":"为了增加…: để tăng thêm (thu nhập)","ex":"为了增加收入，他找了一份兼职。","py":"Wèile zēngjiā shōurù, tā zhǎole yí fèn jiānzhí.","vi":"Để tăng thu nhập, anh ấy tìm một công việc làm thêm.","en":"To increase his income, he found a part-time job."}]},"减轻":{"en":"to lighten; to reduce; to relieve","exs":[{"use":"减轻 + 痛苦/病情: làm giảm nhẹ (bệnh, đau)","ex":"吃药以后，他的痛苦减轻了。","py":"Chī yào yǐhòu, tā de tòngkǔ jiǎnqīng le.","vi":"Sau khi uống thuốc, nỗi đau của anh ấy đã giảm bớt.","en":"After taking medicine, his pain was eased."},{"use":"减轻 + 负担: giảm gánh nặng","ex":"老师决定减轻学生的作业负担。","py":"Lǎoshī juédìng jiǎnqīng xuésheng de zuòyè fùdān.","vi":"Cô giáo quyết định giảm gánh nặng bài tập cho học sinh.","en":"The teacher decided to lighten the students' homework load."},{"use":"减轻 + 压力: giảm áp lực","ex":"听音乐可以减轻压力。","py":"Tīng yīnyuè kěyǐ jiǎnqīng yālì.","vi":"Nghe nhạc có thể giúp giảm căng thẳng.","en":"Listening to music can reduce stress."}]},"轻松":{"en":"relaxed; light; easy","exs":[{"use":"Làm vị ngữ: nhẹ nhõm, thoải mái","ex":"这份工作很轻松，压力不大。","py":"Zhè fèn gōngzuò hěn qīngsōng, yālì bú dà.","vi":"Công việc này rất nhẹ nhàng, áp lực không lớn.","en":"This job is very easy-going and not stressful."},{"use":"V + 得 + 轻松: bổ ngữ trạng thái","ex":"周末我喜欢在家过得轻松一点儿。","py":"Zhōumò wǒ xǐhuan zài jiā guò de qīngsōng yìdiǎnr.","vi":"Cuối tuần tôi thích ở nhà sống thoải mái một chút.","en":"On weekends I like to take it easy at home."},{"use":"轻松地 + V: làm trạng ngữ","ex":"做完作业，他轻松地笑了。","py":"Zuòwán zuòyè, tā qīngsōng de xiào le.","vi":"Làm xong bài tập, cậu ấy cười nhẹ nhõm.","en":"After finishing his homework, he smiled in relief."},{"use":"放轻松: thả lỏng, đừng căng thẳng","ex":"别紧张，放轻松。","py":"Bié jǐnzhāng, fàng qīngsōng.","vi":"Đừng căng thẳng, thư giãn đi.","en":"Don't be nervous; relax."}]},"使用":{"en":"to use; to employ","exs":[{"use":"使用 + công cụ/phương pháp.","ex":"请正确使用这个方法。","py":"Qǐng zhèngquè shǐyòng zhège fāngfǎ.","vi":"Sử dụng","en":"Please use this method correctly."},{"use":"使用方法: danh từ hóa, làm định ngữ","ex":"这台机器的使用方法很简单。","py":"Zhè tái jīqì de shǐyòng fāngfǎ hěn jiǎndān.","vi":"Cách sử dụng chiếc máy này rất đơn giản.","en":"The way to use this machine is very simple."},{"use":"长时间使用 + đồ vật: dùng lâu","ex":"长时间使用手机对眼睛不好。","py":"Cháng shíjiān shǐyòng shǒujī duì yǎnjing bù hǎo.","vi":"Dùng điện thoại trong thời gian dài không tốt cho mắt.","en":"Using a phone for a long time is bad for your eyes."},{"use":"在 + nơi + 使用 + vật: dùng ở đâu","ex":"请不要在教室里使用手机。","py":"Qǐng búyào zài jiàoshì lǐ shǐyòng shǒujī.","vi":"Xin đừng sử dụng điện thoại trong lớp học.","en":"Please do not use mobile phones in the classroom."}]},"语言":{"en":"language","exs":[{"use":"Chỉ ngôn ngữ nói hoặc viết.","ex":"语言是交流的工具。","py":"Yǔyán shì jiāoliú de gōngjù.","vi":"Ngôn ngữ","en":"Language is a tool for communication."},{"use":"学 + 门 + 语言: học một ngôn ngữ","ex":"学习一门新语言需要耐心。","py":"Xuéxí yì mén xīn yǔyán xūyào nàixīn.","vi":"Học một ngôn ngữ mới cần có sự kiên nhẫn.","en":"Learning a new language takes patience."},{"use":"几种语言: hỏi số ngôn ngữ biết","ex":"你会说几种语言？","py":"Nǐ huì shuō jǐ zhǒng yǔyán?","vi":"Bạn biết nói mấy thứ tiếng?","en":"How many languages can you speak?"},{"use":"语言和文化: nói về mối quan hệ","ex":"语言和文化有很深的关系。","py":"Yǔyán hé wénhuà yǒu hěn shēn de guānxì.","vi":"Ngôn ngữ và văn hóa có quan hệ rất sâu sắc.","en":"Language and culture are deeply related."}]},"直接":{"en":"directly; direct","exs":[{"use":"直接 + động từ.","ex":"请直接告诉我。","py":"Qǐng zhíjiē gàosu wǒ.","vi":"Trực tiếp","en":"Please just tell me directly."},{"use":"Tính từ: nói năng thẳng thắn","ex":"他说话很直接，不喜欢绕圈子。","py":"Tā shuōhuà hěn zhíjiē, bù xǐhuan rào quānzi.","vi":"Anh ấy nói chuyện rất thẳng, không thích vòng vo.","en":"He speaks very directly and doesn't like beating around the bush."},{"use":"直接 + V: làm thẳng, không qua bước trung gian","ex":"下了飞机，我直接去了酒店。","py":"Xiàle fēijī, wǒ zhíjiē qùle jiǔdiàn.","vi":"Xuống máy bay, tôi đi thẳng đến khách sạn.","en":"After getting off the plane, I went straight to the hotel."},{"use":"直接的 + danh từ: làm định ngữ","ex":"这件事对他有直接的影响。","py":"Zhè jiàn shì duì tā yǒu zhíjiē de yǐngxiǎng.","vi":"Việc này có ảnh hưởng trực tiếp đến anh ấy.","en":"This matter has a direct impact on him."}]},"引起":{"en":"to cause; to arouse","exs":[{"use":"引起 + kết quả/phản ứng.","ex":"这件事引起了误会。","py":"Zhè jiàn shì yǐnqǐ le wùhuì.","vi":"Gây ra","en":"This matter caused a misunderstanding."},{"use":"引起 + 注意: thu hút sự chú ý","ex":"这个新闻引起了大家的注意。","py":"Zhège xīnwén yǐnqǐle dàjiā de zhùyì.","vi":"Tin tức này đã thu hút sự chú ý của mọi người.","en":"This news caught everyone's attention."},{"use":"引起 + bệnh/triệu chứng: gây ra","ex":"吃太多油腻的东西容易引起胃疼。","py":"Chī tài duō yóunì de dōngxi róngyì yǐnqǐ wèi téng.","vi":"Ăn quá nhiều đồ dầu mỡ dễ gây đau dạ dày.","en":"Eating too much greasy food can easily cause stomachaches."},{"use":"引起 + 兴趣: khơi dậy hứng thú","ex":"这本书引起了孩子的兴趣。","py":"Zhè běn shū yǐnqǐle háizi de xìngqù.","vi":"Cuốn sách này đã khơi dậy hứng thú của đứa trẻ.","en":"This book aroused the child's interest."}]},"误会":{"en":"misunderstanding; to misunderstand","exs":[{"use":"产生误会 / 误会某人.","ex":"请别误会我的意思。","py":"Qǐng bié wùhuì wǒ de yìsi.","vi":"Hiểu lầm","en":"Please don't misunderstand what I mean."},{"use":"Danh từ: một sự hiểu lầm","ex":"这只是一个小误会，说清楚就好了。","py":"Zhè zhǐshì yí ge xiǎo wùhuì, shuō qīngchu jiù hǎo le.","vi":"Đây chỉ là một hiểu lầm nhỏ, nói rõ ra là xong.","en":"This is just a small misunderstanding; once we explain, it'll be fine."},{"use":"产生误会: nảy sinh hiểu lầm","ex":"沟通太少容易产生误会。","py":"Gōutōng tài shǎo róngyì chǎnshēng wùhuì.","vi":"Ít trao đổi thì dễ nảy sinh hiểu lầm.","en":"Too little communication easily leads to misunderstandings."},{"use":"被 + 误会: bị hiểu lầm","ex":"他被大家误会了，心情不好。","py":"Tā bèi dàjiā wùhuì le, xīnqíng bù hǎo.","vi":"Anh ấy bị mọi người hiểu lầm nên tâm trạng không tốt.","en":"He was misunderstood by everyone and is in a bad mood."}]},"指出":{"en":"to point out","exs":[{"use":"指出 + vấn đề/lỗi.","ex":"老师指出了我的问题。","py":"Lǎoshī zhǐchū le wǒ de wèntí.","vi":"Chỉ ra","en":"The teacher pointed out my problem."},{"use":"指出 + 错误: chỉ ra lỗi sai","ex":"请你指出这句话的错误。","py":"Qǐng nǐ zhǐchū zhè jù huà de cuòwù.","vi":"Mời bạn chỉ ra lỗi sai của câu này.","en":"Please point out the mistake in this sentence."},{"use":"指出，…: dẫn nội dung báo cáo, nghiên cứu","ex":"报告指出，今年的游客比去年多。","py":"Bàogào zhǐchū, jīnnián de yóukè bǐ qùnián duō.","vi":"Báo cáo chỉ ra rằng năm nay khách du lịch nhiều hơn năm ngoái.","en":"The report points out that there are more tourists this year than last year."},{"use":"Dùng khi chuyên gia nêu quan điểm","ex":"医生指出，每天运动对健康有好处。","py":"Yīshēng zhǐchū, měitiān yùndòng duì jiànkāng yǒu hǎochù.","vi":"Bác sĩ chỉ ra rằng vận động mỗi ngày có lợi cho sức khỏe.","en":"The doctor pointed out that exercising every day is good for your health."}]},"友好":{"en":"friendly; amicable","exs":[{"use":"对…友好.","ex":"大家对我很友好。","py":"Dàjiā duì wǒ hěn yǒuhǎo.","vi":"Thân thiện","en":"Everyone is very friendly to me."},{"use":"友好的 + 关系: làm định ngữ","ex":"两个国家一直保持着友好的关系。","py":"Liǎng ge guójiā yìzhí bǎochízhe yǒuhǎo de guānxì.","vi":"Hai nước luôn giữ quan hệ hữu hảo.","en":"The two countries have always maintained friendly relations."},{"use":"Làm vị ngữ, tả thái độ","ex":"他笑得很友好，让我不再紧张。","py":"Tā xiào de hěn yǒuhǎo, ràng wǒ bú zài jǐnzhāng.","vi":"Anh ấy cười rất thân thiện, khiến tôi hết căng thẳng.","en":"He smiled in a friendly way, which made me less nervous."},{"use":"友好地 + V: làm trạng ngữ","ex":"他友好地向我伸出了手。","py":"Tā yǒuhǎo de xiàng wǒ shēnchūle shǒu.","vi":"Anh ấy thân thiện đưa tay ra với tôi.","en":"He extended his hand to me in a friendly manner."}]},"无论":{"en":"no matter (what/how); regardless of","exs":[{"use":"无论…都…","ex":"无论多忙，我都学习。","py":"Wúlùn duō máng, wǒ dōu xuéxí.","vi":"Bất luận","en":"No matter how busy I am, I study."},{"use":"无论 + từ nghi vấn + 都: dù ... cũng","ex":"无论你去哪儿，我都支持你。","py":"Wúlùn nǐ qù nǎr, wǒ dōu zhīchí nǐ.","vi":"Dù bạn đi đâu, tôi cũng ủng hộ bạn.","en":"No matter where you go, I'll support you."},{"use":"无论…还是…，都…","ex":"无论天气好还是不好，他都去跑步。","py":"Wúlùn tiānqì hǎo háishi bù hǎo, tā dōu qù pǎobù.","vi":"Dù thời tiết tốt hay xấu, anh ấy đều đi chạy bộ.","en":"Whether the weather is good or bad, he goes running."},{"use":"无论如何: dù thế nào đi nữa","ex":"无论如何，我们都要按时完成任务。","py":"Wúlùn rúhé, wǒmen dōu yào ànshí wánchéng rènwu.","vi":"Dù thế nào chúng ta cũng phải hoàn thành nhiệm vụ đúng hạn.","en":"In any case, we must complete the task on time."}]},"事半功倍":{"en":"half the effort, twice the result","exs":[{"use":"Dùng khi hiệu quả cao.","ex":"用对方法能事半功倍。","py":"Yòng duì fāngfǎ néng shìbàn gōngbèi.","vi":"Ít công nhiều hiệu quả","en":"Using the right method can double the result with half the effort."},{"use":"Thành ngữ làm vị ngữ sau 才能/就能","ex":"学习要讲究方法，这样才能事半功倍。","py":"Xuéxí yào jiǎngjiu fāngfǎ, zhèyàng cái néng shìbàn gōngbèi.","vi":"Học tập cần chú ý phương pháp, như vậy mới được việc nửa công mà hiệu quả gấp đôi.","en":"Studying requires good methods; only then can you get twice the result with half the effort."},{"use":"Nói về công cụ hỗ trợ giúp làm việc hiệu quả","ex":"有了好工具，做事就能事半功倍。","py":"Yǒule hǎo gōngjù, zuòshì jiù néng shìbàn gōngbèi.","vi":"Có công cụ tốt thì làm việc sẽ ít công mà hiệu quả cao.","en":"With good tools, you can accomplish more with less effort."},{"use":"真是 + thành ngữ: khen cách dạy/cách làm","ex":"老师教得好，我们学汉语真是事半功倍。","py":"Lǎoshī jiāo de hǎo, wǒmen xué Hànyǔ zhēn shì shìbàn gōngbèi.","vi":"Thầy cô dạy tốt nên chúng tôi học tiếng Hán thật sự ít công mà hiệu quả cao.","en":"The teacher teaches well, so learning Chinese really takes half the effort for double the result."}]},"节约":{"en":"to save; to economize; thrifty","exs":[{"use":"节约 + thời gian/tài nguyên.","ex":"我们要节约时间。","py":"Wǒmen yào jiéyuē shíjiān.","vi":"Tiết kiệm","en":"We should save time."},{"use":"节约 + 用水/用电: tiết kiệm tài nguyên","ex":"节约用水是每个人的责任。","py":"Jiéyuē yòngshuǐ shì měi ge rén de zérèn.","vi":"Tiết kiệm nước là trách nhiệm của mỗi người.","en":"Saving water is everyone's responsibility."},{"use":"节约 + 不要浪费: đối lập với 浪费","ex":"妈妈教我从小要节约，不要浪费食物。","py":"Māma jiāo wǒ cóngxiǎo yào jiéyuē, búyào làngfèi shíwù.","vi":"Mẹ dạy tôi từ nhỏ phải tiết kiệm, đừng lãng phí thức ăn.","en":"Mom taught me from childhood to be thrifty and not waste food."},{"use":"Tính từ: tiết kiệm, căn cơ","ex":"他生活很节约，每个月都存钱。","py":"Tā shēnghuó hěn jiéyuē, měi ge yuè dōu cún qián.","vi":"Anh ấy sống rất tiết kiệm, tháng nào cũng gửi tiền.","en":"He lives very frugally and saves money every month."}]},"相反":{"en":"opposite; on the contrary","exs":[{"use":"Dùng để nêu ý trái ngược.","ex":"相反，他不喜欢。","py":"Xiāngfǎn, tā bù xǐhuan.","vi":"Ngược lại","en":"On the contrary, he doesn't like it."},{"use":"Tính từ làm vị ngữ: trái ngược","ex":"他的看法和我的完全相反。","py":"Tā de kànfǎ hé wǒ de wánquán xiāngfǎn.","vi":"Quan điểm của anh ấy hoàn toàn trái ngược với tôi.","en":"His view is completely opposite to mine."},{"use":"相反的 + danh từ: định ngữ","ex":"我们走错了，应该往相反的方向走。","py":"Wǒmen zǒucuò le, yīnggāi wǎng xiāngfǎn de fāngxiàng zǒu.","vi":"Chúng ta đi nhầm rồi, nên đi theo hướng ngược lại.","en":"We went the wrong way; we should go in the opposite direction."},{"use":"相反，…: liên từ nêu ý đối lập","ex":"我以为他会生气，相反，他笑了。","py":"Wǒ yǐwéi tā huì shēngqì, xiāngfǎn, tā xiào le.","vi":"Tôi tưởng anh ấy sẽ giận, ngược lại, anh ấy còn cười.","en":"I thought he would be angry; on the contrary, he laughed."}]},"事倍功半":{"en":"twice the effort, half the result","exs":[{"use":"Trái nghĩa với 事半功倍.","ex":"方法不对会事倍功半。","py":"Fāngfǎ bú duì huì shìbèi gōngbàn.","vi":"Nhiều công ít hiệu quả","en":"With the wrong method, you work twice as hard for half the result."},{"use":"Nói về việc thiếu chuẩn bị, làm sai cách","ex":"不复习只做新题，常常事倍功半。","py":"Bù fùxí zhǐ zuò xīn tí, chángcháng shìbèi gōngbàn.","vi":"Không ôn tập mà chỉ làm đề mới thì thường tốn công mà ít hiệu quả.","en":"Doing only new problems without reviewing often means a lot of effort for little result."},{"use":"Kết quả: 结果 + thành ngữ","ex":"没有计划就开始工作，结果事倍功半。","py":"Méiyǒu jìhuà jiù kāishǐ gōngzuò, jiéguǒ shìbèi gōngbàn.","vi":"Chưa có kế hoạch đã bắt tay vào làm, kết quả là tốn công mà ít hiệu quả.","en":"He started working without a plan, and as a result put in double the effort for half the outcome."},{"use":"Dùng để chỉ nguyên nhân như thiếu ngủ","ex":"睡得太少，学习起来事倍功半。","py":"Shuì de tài shǎo, xuéxí qǐlái shìbèi gōngbàn.","vi":"Ngủ quá ít thì học hành tốn công mà ít kết quả.","en":"If you sleep too little, studying takes twice the effort for half the result."}]},"听取":{"en":"to listen to (opinions); to hear out","exs":[{"use":"听取 + 意见/建议.","ex":"我们应该听取意见。","py":"Wǒmen yīnggāi tīngqǔ yìjiàn.","vi":"Lắng nghe, tiếp thu","en":"We should listen to opinions."},{"use":"听取 + 建议: lắng nghe đề xuất (văn viết, trang trọng)","ex":"经理认真听取了大家的建议。","py":"Jīnglǐ rènzhēn tīngqǔle dàjiā de jiànyì.","vi":"Giám đốc đã nghiêm túc lắng nghe đề xuất của mọi người.","en":"The manager seriously listened to everyone's suggestions."},{"use":"Trước khi quyết định cần 听取 ý kiến","ex":"做决定以前，要多听取家人的意见。","py":"Zuò juédìng yǐqián, yào duō tīngqǔ jiārén de yìjiàn.","vi":"Trước khi quyết định, cần lắng nghe nhiều ý kiến của người nhà.","en":"Before making a decision, you should listen to your family's opinions."},{"use":"听取 + 说明/汇报: nghe trình bày","ex":"医生听取了病人的说明，然后开了药。","py":"Yīshēng tīngqǔle bìngrén de shuōmíng, ránhòu kāile yào.","vi":"Bác sĩ nghe bệnh nhân trình bày rồi mới kê thuốc.","en":"The doctor listened to the patient's description and then prescribed medicine."}]},"仔细":{"en":"careful; carefully; meticulous","exs":[{"use":"仔细 + động từ.","ex":"请仔细考虑一下。","py":"Qǐng zǐxì kǎolǜ yíxià.","vi":"Cẩn thận, kỹ lưỡng","en":"Please think it over carefully."},{"use":"Tính từ làm vị ngữ: cẩn thận","ex":"他做事很仔细，从来不出错。","py":"Tā zuòshì hěn zǐxì, cónglái bù chūcuò.","vi":"Anh ấy làm việc rất cẩn thận, chưa bao giờ sai sót.","en":"He is very careful in his work and never makes mistakes."},{"use":"仔细 + V: trạng ngữ, xem/nghe kỹ","ex":"请仔细看这张照片，你发现了什么？","py":"Qǐng zǐxì kàn zhè zhāng zhàopiàn, nǐ fāxiàn le shénme?","vi":"Hãy xem kỹ tấm ảnh này, bạn phát hiện ra điều gì?","en":"Please look at this photo carefully; what did you notice?"},{"use":"V + 得 + 仔细: bổ ngữ trạng thái","ex":"这篇文章我读得很仔细。","py":"Zhè piān wénzhāng wǒ dú de hěn zǐxì.","vi":"Bài văn này tôi đọc rất kỹ.","en":"I read this article very carefully."}]},"达到":{"en":"to reach; to attain; to achieve","exs":[{"use":"达到 + mục tiêu/tiêu chuẩn.","ex":"我们达到了目标。","py":"Wǒmen dádào le mùbiāo.","vi":"Đạt tới","en":"We reached the goal."},{"use":"达到 + trình độ/tiêu chuẩn","ex":"他的汉语水平已经达到了四级。","py":"Tā de Hànyǔ shuǐpíng yǐjīng dádàole sì jí.","vi":"Trình độ tiếng Hán của anh ấy đã đạt cấp bốn.","en":"His Chinese level has already reached level four."},{"use":"达到 + con số: lên tới","ex":"气温最高会达到三十五度。","py":"Qìwēn zuìgāo huì dádào sānshíwǔ dù.","vi":"Nhiệt độ cao nhất sẽ lên tới ba mươi lăm độ.","en":"The temperature will reach as high as 35 degrees."},{"use":"为了达到目的: để đạt mục đích","ex":"为了达到目的，他每天努力工作。","py":"Wèile dádào mùdì, tā měitiān nǔlì gōngzuò.","vi":"Để đạt được mục đích, anh ấy ngày nào cũng làm việc chăm chỉ.","en":"To achieve his goal, he works hard every day."}]},"人人":{"en":"everyone; everybody","exs":[{"use":"人人 + 都: ai ai cũng","ex":"人人都应该遵守交通规则。","py":"Rénrén dōu yīnggāi zūnshǒu jiāotōng guīzé.","vi":"Ai cũng nên tuân thủ luật giao thông.","en":"Everyone should obey the traffic rules."},{"use":"Chỉ mọi người trong một tập thể","ex":"在这个班里，人人都很努力。","py":"Zài zhège bān lǐ, rénrén dōu hěn nǔlì.","vi":"Trong lớp này, ai cũng rất chăm chỉ.","en":"In this class, everybody works hard."},{"use":"人人有责: ai cũng có trách nhiệm","ex":"保护环境，人人有责。","py":"Bǎohù huánjìng, rénrén yǒu zé.","vi":"Bảo vệ môi trường, người người đều có trách nhiệm.","en":"Protecting the environment is everyone's responsibility."},{"use":"Nói về sở thích chung","ex":"人人都喜欢听好话。","py":"Rénrén dōu xǐhuan tīng hǎohuà.","vi":"Ai cũng thích nghe lời hay.","en":"Everybody likes to hear nice words."}]},"说话":{"en":"to speak; to talk","exs":[{"use":"Động từ ly hợp: nói chuyện","ex":"老师在说话，请大家安静。","py":"Lǎoshī zài shuōhuà, qǐng dàjiā ānjìng.","vi":"Cô giáo đang nói, mọi người xin hãy yên lặng.","en":"The teacher is speaking; everyone, please be quiet."},{"use":"说话的 + danh từ: giọng nói, cách nói","ex":"他说话的声音很好听。","py":"Tā shuōhuà de shēngyīn hěn hǎotīng.","vi":"Giọng nói của anh ấy rất dễ nghe.","en":"His speaking voice is very pleasant."},{"use":"会/不会说话: biết nói hay chưa","ex":"孩子才一岁，还不会说话。","py":"Háizi cái yí suì, hái bú huì shuōhuà.","vi":"Đứa bé mới một tuổi, vẫn chưa biết nói.","en":"The baby is only one year old and can't talk yet."},{"use":"一边…一边说话: vừa ... vừa nói","ex":"他喜欢一边走路一边说话。","py":"Tā xǐhuan yìbiān zǒulù yìbiān shuōhuà.","vi":"Anh ấy thích vừa đi bộ vừa nói chuyện.","en":"He likes to talk while walking."}]},"力气":{"en":"physical strength; effort","exs":[{"use":"Làm vị ngữ: 力气很大/小","ex":"他力气很大，一个人就能搬动冰箱。","py":"Tā lìqi hěn dà, yí ge rén jiù néng bāndòng bīngxiāng.","vi":"Anh ấy rất khỏe, một mình cũng khiêng được tủ lạnh.","en":"He is very strong and can move the refrigerator by himself."},{"use":"没有力气: kiệt sức","ex":"我跑了一天，现在一点儿力气也没有。","py":"Wǒ pǎole yì tiān, xiànzài yìdiǎnr lìqi yě méiyǒu.","vi":"Tôi chạy cả ngày, giờ không còn chút sức lực nào.","en":"I've been running all day and now I have no strength left."},{"use":"花力气: tốn công sức","ex":"这件事花了我不少力气。","py":"Zhè jiàn shì huāle wǒ bù shǎo lìqi.","vi":"Việc này tốn của tôi không ít sức lực.","en":"This task took quite a lot of effort from me."},{"use":"Nói về trẻ em sức yếu","ex":"小孩子力气小，拿不动这个箱子。","py":"Xiǎo háizi lìqi xiǎo, ná bú dòng zhège xiāngzi.","vi":"Trẻ con sức yếu, không xách nổi cái hòm này.","en":"Small children don't have much strength and can't carry this box."}]},"任务":{"en":"task; mission; assignment","exs":[{"use":"给 + người + 安排任务","ex":"老师给我们安排了一个新任务。","py":"Lǎoshī gěi wǒmen ānpáile yí ge xīn rènwu.","vi":"Cô giáo giao cho chúng tôi một nhiệm vụ mới.","en":"The teacher assigned us a new task."},{"use":"完成任务: hoàn thành nhiệm vụ","ex":"我们必须在周五以前完成这个任务。","py":"Wǒmen bìxū zài zhōuwǔ yǐqián wánchéng zhège rènwu.","vi":"Chúng ta phải hoàn thành nhiệm vụ này trước thứ Sáu.","en":"We must finish this task before Friday."},{"use":"Làm chủ ngữ, vị ngữ là tính từ: 重/难","ex":"这次的任务很重，大家要互相帮助。","py":"Zhè cì de rènwu hěn zhòng, dàjiā yào hùxiāng bāngzhù.","vi":"Nhiệm vụ lần này rất nặng nề, mọi người phải giúp đỡ nhau.","en":"This task is a heavy one, so we need to help each other."}]},"变成":{"en":"to become; to turn into","exs":[{"use":"A 变成 B: biến thành (trạng thái vật lý)","ex":"冰遇到热会变成水。","py":"Bīng yùdào rè huì biànchéng shuǐ.","vi":"Băng gặp nóng sẽ biến thành nước.","en":"Ice turns into water when it gets hot."},{"use":"Sự thay đổi theo thời gian","ex":"几年不见，小女孩变成了大姑娘。","py":"Jǐ nián bú jiàn, xiǎo nǚháir biànchéng le dà gūniang.","vi":"Mấy năm không gặp, cô bé đã trở thành thiếu nữ.","en":"After a few years apart, the little girl has grown into a young woman."},{"use":"变成 + danh từ trừu tượng","ex":"我的爱好变成了工作。","py":"Wǒ de àihào biànchéngle gōngzuò.","vi":"Sở thích của tôi đã biến thành công việc.","en":"My hobby has become my job."},{"use":"Đèn giao thông đổi màu","ex":"红灯变成绿灯了，我们走吧。","py":"Hóngdēng biànchéng lǜdēng le, wǒmen zǒu ba.","vi":"Đèn đỏ chuyển sang xanh rồi, chúng ta đi thôi.","en":"The red light has turned green; let's go."}]},"也许":{"en":"perhaps; maybe","exs":[{"use":"也许 + suy đoán nguyên nhân","ex":"他还没来，也许路上堵车了。","py":"Tā hái méi lái, yěxǔ lùshang dǔchē le.","vi":"Anh ấy chưa đến, có lẽ trên đường bị kẹt xe.","en":"He hasn't come yet; maybe he's stuck in traffic."},{"use":"也许 + dự đoán tương lai","ex":"也许明天会下雨，你带把伞吧。","py":"Yěxǔ míngtiān huì xià yǔ, nǐ dài bǎ sǎn ba.","vi":"Có lẽ ngày mai sẽ mưa, bạn mang theo ô đi.","en":"It might rain tomorrow, so take an umbrella."},{"use":"Đứng sau chủ ngữ: 你也许…","ex":"你也许不知道，他以前是我的老师。","py":"Nǐ yěxǔ bù zhīdào, tā yǐqián shì wǒ de lǎoshī.","vi":"Có lẽ bạn không biết, trước đây anh ấy là thầy của tôi.","en":"You may not know this, but he used to be my teacher."}]},"意见":{"en":"opinion; suggestion; objection","exs":[{"use":"Nghĩa 1: ý kiến, quan điểm","ex":"关于这个计划，你有什么意见？","py":"Guānyú zhège jìhuà, nǐ yǒu shénme yìjiàn?","vi":"Về kế hoạch này, bạn có ý kiến gì không?","en":"What is your opinion about this plan?"},{"use":"Nghĩa 2: 对…有意见 (bất mãn, có ý kiến phản đối)","ex":"我对这家餐厅的服务有意见。","py":"Wǒ duì zhè jiā cāntīng de fúwù yǒu yìjiàn.","vi":"Tôi không hài lòng về dịch vụ của nhà hàng này.","en":"I have complaints about this restaurant's service."},{"use":"提意见: đưa ra ý kiến","ex":"请大家多提意见。","py":"Qǐng dàjiā duō tí yìjiàn.","vi":"Mong mọi người góp nhiều ý kiến.","en":"Please everyone give us more feedback."},{"use":"同意 + 意见: đồng ý với ý kiến","ex":"我同意你的意见。","py":"Wǒ tóngyì nǐ de yìjiàn.","vi":"Tôi đồng ý với ý kiến của bạn.","en":"I agree with your opinion."}]},"规定":{"en":"regulation; rule; to stipulate","exs":[{"use":"Động từ: quy định rằng","ex":"学校规定学生不能带手机进教室。","py":"Xuéxiào guīdìng xuésheng bù néng dài shǒujī jìn jiàoshì.","vi":"Nhà trường quy định học sinh không được mang điện thoại vào lớp.","en":"The school stipulates that students cannot bring phones into the classroom."},{"use":"Danh từ: công ty có 规定","ex":"这是公司的规定，我们必须遵守。","py":"Zhè shì gōngsī de guīdìng, wǒmen bìxū zūnshǒu.","vi":"Đây là quy định của công ty, chúng tôi phải tuân thủ.","en":"This is a company rule, and we must follow it."},{"use":"按照规定: theo quy định","ex":"按照规定，客人要在门口登记。","py":"Ànzhào guīdìng, kèrén yào zài ménkǒu dēngjì.","vi":"Theo quy định, khách phải đăng ký ở cổng.","en":"According to the rules, guests must register at the entrance."},{"use":"法律规定: luật quy định","ex":"法律规定，开车不能喝酒。","py":"Fǎlǜ guīdìng, kāichē bù néng hē jiǔ.","vi":"Pháp luật quy định lái xe không được uống rượu.","en":"The law stipulates that you cannot drink and drive."}]},"解决问题":{"en":"to solve a problem","exs":[{"use":"想办法 + 解决问题: tìm cách giải quyết","ex":"我们要想办法解决问题。","py":"Wǒmen yào xiǎng bànfǎ jiějué wèntí.","vi":"Chúng ta phải nghĩ cách giải quyết vấn đề.","en":"We need to find a way to solve the problem."},{"use":"会解决问题: có năng lực giải quyết vấn đề","ex":"他很会解决问题，大家都愿意找他帮忙。","py":"Tā hěn huì jiějué wèntí, dàjiā dōu yuànyì zhǎo tā bāngmáng.","vi":"Anh ấy rất giỏi giải quyết vấn đề nên ai cũng muốn nhờ anh ấy giúp.","en":"He is good at solving problems, so everyone is willing to ask him for help."},{"use":"不能解决问题: phủ định","ex":"光抱怨不能解决问题。","py":"Guāng bàoyuàn bù néng jiějué wèntí.","vi":"Chỉ than phiền thì không giải quyết được vấn đề.","en":"Complaining alone cannot solve the problem."},{"use":"Dạng nghi vấn: 能…吗","ex":"这个办法能解决问题吗？","py":"Zhège bànfǎ néng jiějué wèntí ma?","vi":"Cách này có giải quyết được vấn đề không?","en":"Can this method solve the problem?"}]},"可惜":{"en":"pity; unfortunately; regrettable","exs":[{"use":"Tính từ làm vị ngữ: 真可惜","ex":"这么好的机会你没去，真可惜。","py":"Zhème hǎo de jīhuì nǐ méi qù, zhēn kěxī.","vi":"Cơ hội tốt như vậy mà bạn không đi, thật đáng tiếc.","en":"What a pity you didn't go to such a good opportunity."},{"use":"可惜 đầu câu như phó từ: tiếc là","ex":"可惜我明天有事，不能参加你的生日会。","py":"Kěxī wǒ míngtiān yǒu shì, bù néng cānjiā nǐ de shēngrì huì.","vi":"Tiếc là ngày mai tôi có việc, không thể dự sinh nhật của bạn.","en":"Unfortunately I have something on tomorrow and can't come to your birthday party."},{"use":"太可惜了: tiếc đồ vật, lãng phí","ex":"这件衣服扔了太可惜了。","py":"Zhè jiàn yīfu rēng le tài kěxī le.","vi":"Chiếc áo này vứt đi thì tiếc quá.","en":"It would be such a waste to throw this garment away."}]},"走走":{"en":"to take a walk; to stroll around","exs":[{"use":"去 + nơi + 走走: đi dạo (động từ lặp)","ex":"晚饭后我们去公园走走吧。","py":"Wǎnfàn hòu wǒmen qù gōngyuán zǒuzou ba.","vi":"Sau bữa tối chúng ta ra công viên đi dạo nhé.","en":"Let's take a walk in the park after dinner."},{"use":"起来走走: đứng dậy đi lại","ex":"坐了一天，起来走走对身体好。","py":"Zuòle yì tiān, qǐlái zǒuzou duì shēntǐ hǎo.","vi":"Ngồi cả ngày, đứng dậy đi lại một chút tốt cho sức khỏe.","en":"After sitting all day, getting up and walking around is good for you."},{"use":"出去走走: ra ngoài chơi, thư giãn","ex":"周末我想带父母出去走走。","py":"Zhōumò wǒ xiǎng dài fùmǔ chūqù zǒuzou.","vi":"Cuối tuần tôi muốn đưa bố mẹ ra ngoài đi chơi.","en":"This weekend I want to take my parents out for a walk."}]},"商量":{"en":"to discuss; to talk over","exs":[{"use":"和 + người + 商量一下: bàn bạc với ai","ex":"这件事我想和家人商量一下。","py":"Zhè jiàn shì wǒ xiǎng hé jiārén shāngliang yíxià.","vi":"Việc này tôi muốn bàn bạc với người nhà một chút.","en":"I'd like to talk this over with my family."},{"use":"商量好了: bổ ngữ kết quả","ex":"我们商量好了，明天一起去爬山。","py":"Wǒmen shāngliang hǎo le, míngtiān yìqǐ qù páshān.","vi":"Chúng tôi đã bàn xong rồi, ngày mai cùng đi leo núi.","en":"We have agreed that we'll go hiking together tomorrow."},{"use":"有事好商量: có gì từ từ bàn","ex":"有事好商量，别生气。","py":"Yǒu shì hǎo shāngliang, bié shēngqì.","vi":"Có chuyện gì cứ từ từ bàn bạc, đừng giận.","en":"Let's talk it over calmly; don't get angry."}]},"及时发现":{"en":"to discover in time; to detect promptly","exs":[{"use":"及时发现 + vấn đề: phát hiện kịp thời","ex":"如果能及时发现问题，就不会有大麻烦。","py":"Rúguǒ néng jíshí fāxiàn wèntí, jiù bú huì yǒu dà máfan.","vi":"Nếu có thể phát hiện vấn đề kịp thời thì sẽ không có rắc rối lớn.","en":"If problems are detected in time, there won't be big trouble."},{"use":"只要…及时发现，就…: chỉ cần phát hiện sớm","ex":"这种病只要及时发现，就可以治好。","py":"Zhè zhǒng bìng zhǐyào jíshí fāxiàn, jiù kěyǐ zhìhǎo.","vi":"Loại bệnh này chỉ cần phát hiện kịp thời là có thể chữa khỏi.","en":"This disease can be cured as long as it is found early."},{"use":"幸亏/多亏 + người + 及时发现","ex":"幸亏医生及时发现，他的病很快就好了。","py":"Xìngkuī yīshēng jíshí fāxiàn, tā de bìng hěn kuài jiù hǎo le.","vi":"May nhờ bác sĩ phát hiện kịp thời nên bệnh của anh ấy nhanh chóng khỏi.","en":"Thanks to the doctor spotting it in time, he recovered quickly."}]},"并且":{"en":"and; moreover; furthermore","exs":[{"use":"并且 nối hai vị ngữ: và còn","ex":"他会说汉语，并且说得很流利。","py":"Tā huì shuō Hànyǔ, bìngqiě shuō de hěn liúlì.","vi":"Anh ấy biết nói tiếng Hán, hơn nữa còn nói rất lưu loát.","en":"He can speak Chinese, and he speaks it fluently."},{"use":"并且 nối hai vế tính chất","ex":"这家饭店的菜好吃，并且价格便宜。","py":"Zhè jiā fàndiàn de cài hǎochī, bìngqiě jiàgé piányi.","vi":"Món ăn của nhà hàng này ngon, hơn nữa giá lại rẻ.","en":"The food at this restaurant is delicious, and the prices are cheap too."},{"use":"并且 nối hai hành động nối tiếp","ex":"他完成了任务，并且得到了经理的表扬。","py":"Tā wánchéngle rènwu, bìngqiě dédàole jīnglǐ de biǎoyáng.","vi":"Anh ấy hoàn thành nhiệm vụ và còn được giám đốc khen.","en":"He completed the task and was also praised by the manager."}]},"难看":{"en":"ugly; unattractive; unwell-looking","exs":[{"use":"Nghĩa 1: xấu, không đẹp mắt","ex":"这件衣服的颜色太难看了。","py":"Zhè jiàn yīfu de yánsè tài nánkàn le.","vi":"Màu của chiếc áo này xấu quá.","en":"The color of this garment is really ugly."},{"use":"Nghĩa 2: 脸色难看 (sắc mặt xấu, ốm yếu)","ex":"他的脸色很难看，是不是生病了？","py":"Tā de liǎnsè hěn nánkàn, shì bu shì shēngbìng le?","vi":"Sắc mặt anh ấy rất tệ, có phải bị ốm không?","en":"He looks terrible; is he sick?"},{"use":"Chữ viết xấu","ex":"这个字写得真难看。","py":"Zhège zì xiě de zhēn nánkàn.","vi":"Chữ này viết xấu thật.","en":"This character is written really badly."}]},"放盐":{"en":"to add salt","exs":[{"use":"放盐: cho muối khi nấu ăn","ex":"做汤的时候别忘了放盐。","py":"Zuò tāng de shíhou bié wàngle fàng yán.","vi":"Khi nấu canh đừng quên cho muối.","en":"Don't forget to add salt when making soup."},{"use":"忘了放盐: quên cho muối (kết quả nhạt)","ex":"这个菜我忘了放盐，所以没有味道。","py":"Zhège cài wǒ wàngle fàng yán, suǒyǐ méiyǒu wèidao.","vi":"Món này tôi quên cho muối nên không có vị.","en":"I forgot to put salt in this dish, so it has no flavor."},{"use":"少放盐: cho ít muối (vì sức khỏe)","ex":"医生让爸爸做菜时少放盐。","py":"Yīshēng ràng bàba zuòcài shí shǎo fàng yán.","vi":"Bác sĩ bảo bố khi nấu ăn nên cho ít muối.","en":"The doctor told Dad to use less salt when cooking."}]},"做饭":{"en":"to cook (a meal)","exs":[{"use":"Động từ ly hợp: nấu cơm","ex":"我妈妈每天都在家做饭。","py":"Wǒ māma měitiān dōu zài jiā zuòfàn.","vi":"Mẹ tôi ngày nào cũng nấu cơm ở nhà.","en":"My mother cooks at home every day."},{"use":"不会做饭: không biết nấu ăn","ex":"他不会做饭，常常吃外卖。","py":"Tā bú huì zuòfàn, chángcháng chī wàimài.","vi":"Anh ấy không biết nấu ăn, thường ăn đồ giao tận nơi.","en":"He can't cook, so he often orders takeout."},{"use":"我来做饭: để tôi nấu","ex":"今天我来做饭，你休息一下。","py":"Jīntiān wǒ lái zuòfàn, nǐ xiūxi yíxià.","vi":"Hôm nay để tôi nấu cơm, bạn nghỉ ngơi một chút.","en":"I'll cook today; you take a rest."},{"use":"一边…一边做饭","ex":"我喜欢一边听音乐一边做饭。","py":"Wǒ xǐhuan yìbiān tīng yīnyuè yìbiān zuòfàn.","vi":"Tôi thích vừa nghe nhạc vừa nấu ăn.","en":"I like to listen to music while cooking."}]},"盐水":{"en":"salt water; brine","exs":[{"use":"用盐水 + V: dùng nước muối","ex":"感冒的时候，用盐水漱口会舒服一点儿。","py":"Gǎnmào de shíhou, yòng yánshuǐ shùkǒu huì shūfu yìdiǎnr.","vi":"Khi bị cảm, súc miệng bằng nước muối sẽ dễ chịu hơn.","en":"When you have a cold, gargling with salt water will make you feel better."},{"use":"放进盐水里: ngâm trong nước muối","ex":"把青菜放进盐水里泡一会儿。","py":"Bǎ qīngcài fàngjìn yánshuǐ lǐ pào yíhuìr.","vi":"Cho rau xanh vào nước muối ngâm một lát.","en":"Put the greens into salt water and soak them for a while."},{"use":"Nói về nước mặn không uống được","ex":"海里的水是盐水，不能直接喝。","py":"Hǎi lǐ de shuǐ shì yánshuǐ, bù néng zhíjiē hē.","vi":"Nước biển là nước mặn, không thể uống trực tiếp.","en":"Sea water is salt water and can't be drunk directly."}]},"次数":{"en":"number of times; frequency","exs":[{"use":"次数 + 多/少: số lần nhiều hay ít","ex":"你每周去健身房的次数多不多？","py":"Nǐ měi zhōu qù jiànshēnfáng de cìshù duō bu duō?","vi":"Mỗi tuần bạn đi phòng gym có nhiều lần không?","en":"How often do you go to the gym each week?"},{"use":"次数 + 越来越多","ex":"他迟到的次数越来越多。","py":"Tā chídào de cìshù yuè lái yuè duō.","vi":"Số lần anh ấy đi muộn ngày càng nhiều.","en":"The number of times he is late is increasing."},{"use":"减少…的次数: giảm số lần","ex":"减少吃零食的次数对健康有好处。","py":"Jiǎnshǎo chī língshí de cìshù duì jiànkāng yǒu hǎochù.","vi":"Giảm số lần ăn vặt có lợi cho sức khỏe.","en":"Reducing how often you eat snacks is good for your health."}]},"保护":{"en":"to protect; protection","exs":[{"use":"保护 + người thân: che chở","ex":"爸爸总是保护家人。","py":"Bàba zǒngshì bǎohù jiārén.","vi":"Bố luôn bảo vệ cả nhà.","en":"Dad always protects the family."},{"use":"保护 + bộ phận cơ thể","ex":"看书时要注意保护眼睛。","py":"Kàn shū shí yào zhùyì bǎohù yǎnjing.","vi":"Khi đọc sách phải chú ý bảo vệ mắt.","en":"Pay attention to protecting your eyes when reading."},{"use":"Dùng biện pháp để bảo vệ","ex":"出去玩要涂防晒霜保护皮肤。","py":"Chūqù wán yào tú fángshàishuāng bǎohù pífū.","vi":"Đi chơi phải bôi kem chống nắng để bảo vệ da.","en":"Put on sunscreen to protect your skin when going out."},{"use":"Danh từ: sự bảo vệ","ex":"这些动物需要我们的保护。","py":"Zhèxiē dòngwù xūyào wǒmen de bǎohù.","vi":"Những loài động vật này cần sự bảo vệ của chúng ta.","en":"These animals need our protection."}]},"作用":{"en":"effect; function; role","exs":[{"use":"对…有作用: có tác dụng với","ex":"这种药对感冒有很好的作用。","py":"Zhè zhǒng yào duì gǎnmào yǒu hěn hǎo de zuòyòng.","vi":"Loại thuốc này có tác dụng tốt với bệnh cảm.","en":"This medicine works well against colds."},{"use":"对…有很大的作用","ex":"运动对减轻压力有很大的作用。","py":"Yùndòng duì jiǎnqīng yālì yǒu hěn dà de zuòyòng.","vi":"Vận động có tác dụng rất lớn trong việc giảm căng thẳng.","en":"Exercise plays a big role in relieving stress."},{"use":"起作用: có hiệu quả","ex":"我试了几个办法，都没起作用。","py":"Wǒ shìle jǐ ge bànfǎ, dōu méi qǐ zuòyòng.","vi":"Tôi đã thử mấy cách nhưng đều không có tác dụng.","en":"I tried several methods, but none of them worked."}]},"不少":{"en":"quite a few; not a few","exs":[{"use":"Làm vị ngữ: 人不少","ex":"来参加会议的人不少。","py":"Lái cānjiā huìyì de rén bù shǎo.","vi":"Số người đến dự họp không ít.","en":"Quite a few people came to the meeting."},{"use":"不少 + danh từ: khá nhiều","ex":"他在中国住了很多年，认识不少朋友。","py":"Tā zài Zhōngguó zhùle hěn duō nián, rènshi bù shǎo péngyou.","vi":"Anh ấy sống ở Trung Quốc nhiều năm nên quen không ít bạn.","en":"He lived in China for many years and knows quite a few friends."},{"use":"Nói về số lượng đồ vật","ex":"我书架上有不少汉语书。","py":"Wǒ shūjià shàng yǒu bù shǎo Hànyǔ shū.","vi":"Trên giá sách của tôi có khá nhiều sách tiếng Hán.","en":"There are quite a few Chinese books on my shelf."},{"use":"V + 了 + 不少 + N","ex":"最近下了不少雨。","py":"Zuìjìn xiàle bù shǎo yǔ.","vi":"Gần đây mưa khá nhiều.","en":"It has rained quite a lot recently."}]},"课本":{"en":"textbook","exs":[{"use":"把 + 课本 + V: dùng trong lớp học","ex":"请大家把课本翻到第十页。","py":"Qǐng dàjiā bǎ kèběn fāndào dì shí yè.","vi":"Mời cả lớp mở sách giáo khoa đến trang mười.","en":"Everyone, please turn your textbooks to page ten."},{"use":"Làm chủ ngữ: quên/mang sách","ex":"我的课本忘在家里了。","py":"Wǒ de kèběn wàng zài jiā lǐ le.","vi":"Sách giáo khoa của tôi để quên ở nhà rồi.","en":"I left my textbook at home."},{"use":"Nói về nội dung sách","ex":"这本课本的内容很有意思，还有很多图片。","py":"Zhè běn kèběn de nèiróng hěn yǒu yìsi, hái yǒu hěn duō túpiàn.","vi":"Nội dung cuốn sách giáo khoa này rất thú vị, lại có nhiều hình ảnh.","en":"The content of this textbook is interesting, and it has lots of pictures."}]},"用心":{"en":"attentively; conscientiously; with care","exs":[{"use":"Làm vị ngữ: 学习很用心","ex":"他学习很用心，成绩一直不错。","py":"Tā xuéxí hěn yòngxīn, chéngjì yìzhí búcuò.","vi":"Anh ấy học tập rất chăm chú, thành tích luôn tốt.","en":"He studies very conscientiously, and his grades have always been good."},{"use":"用心 + V: làm trạng ngữ (用心听)","ex":"上课要用心听，不要看手机。","py":"Shàngkè yào yòngxīn tīng, búyào kàn shǒujī.","vi":"Trong giờ học phải chú tâm nghe, đừng xem điện thoại.","en":"Listen attentively in class and don't look at your phone."},{"use":"用心地 + V: trạng ngữ với 地","ex":"妈妈用心地为我准备了生日蛋糕。","py":"Māma yòngxīn de wèi wǒ zhǔnbèile shēngrì dàngāo.","vi":"Mẹ đã chu đáo chuẩn bị bánh sinh nhật cho tôi.","en":"Mom carefully prepared a birthday cake for me."},{"use":"看得出来 + 很用心: nhận ra sự chu đáo","ex":"这份礼物看得出来他很用心。","py":"Zhè fèn lǐwù kàn de chūlái tā hěn yòngxīn.","vi":"Món quà này có thể thấy anh ấy rất tâm huyết.","en":"You can tell he put a lot of thought into this gift."}]},"学生":{"en":"student; pupil","exs":[{"use":"Danh từ: số lượng học sinh","ex":"我们班有二十个学生。","py":"Wǒmen bān yǒu èrshí ge xuésheng.","vi":"Lớp chúng tôi có hai mươi học sinh.","en":"There are twenty students in our class."},{"use":"Làm trung tâm của định ngữ","ex":"老师很喜欢认真的学生。","py":"Lǎoshī hěn xǐhuan rènzhēn de xuésheng.","vi":"Giáo viên rất thích những học sinh chăm chỉ.","en":"Teachers like diligent students."},{"use":"学生们: số nhiều, chỉ nhóm","ex":"学生们正在操场上踢足球。","py":"Xuéshengmen zhèngzài cāochǎng shàng tī zúqiú.","vi":"Các học sinh đang đá bóng trên sân vận động.","en":"The students are playing football on the playground."},{"use":"Nói về thân phận: là học sinh","ex":"我以前是学生，现在已经工作了。","py":"Wǒ yǐqián shì xuésheng, xiànzài yǐjīng gōngzuò le.","vi":"Trước đây tôi là học sinh, bây giờ đã đi làm rồi.","en":"I used to be a student, but now I have a job."}]},"详细":{"en":"detailed; in detail","exs":[{"use":"详细地 + V: trạng ngữ","ex":"请把旅行计划详细地告诉我。","py":"Qǐng bǎ lǚxíng jìhuà xiángxì de gàosu wǒ.","vi":"Hãy kể chi tiết kế hoạch du lịch cho tôi.","en":"Please tell me the travel plan in detail."},{"use":"Làm vị ngữ: 写得很详细","ex":"这份说明写得很详细。","py":"Zhè fèn shuōmíng xiě de hěn xiángxì.","vi":"Bản hướng dẫn này viết rất chi tiết.","en":"This instruction sheet is written in great detail."},{"use":"详细的 + danh từ: làm định ngữ","ex":"请给我详细的地址和电话。","py":"Qǐng gěi wǒ xiángxì de dìzhǐ hé diànhuà.","vi":"Xin cho tôi địa chỉ và số điện thoại chi tiết.","en":"Please give me the detailed address and phone number."}]},"谈谈":{"en":"to talk about; to have a chat","exs":[{"use":"和 + người + 谈谈: nói chuyện với ai","ex":"下课后我想和你谈谈。","py":"Xiàkè hòu wǒ xiǎng hé nǐ tántan.","vi":"Sau giờ học tôi muốn nói chuyện với bạn một chút.","en":"I'd like to have a talk with you after class."},{"use":"谈谈 + 看法/想法: nêu quan điểm","ex":"请你谈谈对这个问题的看法。","py":"Qǐng nǐ tántan duì zhège wèntí de kànfǎ.","vi":"Mời bạn nói về quan điểm của mình đối với vấn đề này.","en":"Please share your view on this issue."},{"use":"慢慢谈谈: trò chuyện thong thả","ex":"我们坐下来慢慢谈谈吧。","py":"Wǒmen zuòxiàlái mànmàn tántan ba.","vi":"Chúng ta ngồi xuống nói chuyện từ từ nhé.","en":"Let's sit down and talk it over slowly."},{"use":"谈谈 + công việc, vấn đề cần bàn","ex":"他想跟老板谈谈工资的事。","py":"Tā xiǎng gēn lǎobǎn tántan gōngzī de shì.","vi":"Anh ấy muốn bàn với sếp về chuyện lương.","en":"He wants to talk to the boss about his salary."}]},"复杂":{"en":"complicated; complex","exs":[{"use":"Làm vị ngữ: tình tiết phức tạp","ex":"这个故事很复杂，我看了两遍才懂。","py":"Zhège gùshi hěn fùzá, wǒ kànle liǎng biàn cái dǒng.","vi":"Câu chuyện này rất phức tạp, tôi xem hai lần mới hiểu.","en":"This story is complicated; I had to watch it twice to understand."},{"use":"Tả tâm trạng đan xen","ex":"他的心情很复杂，又高兴又难过。","py":"Tā de xīnqíng hěn fùzá, yòu gāoxìng yòu nánguò.","vi":"Tâm trạng anh ấy rất phức tạp, vừa vui vừa buồn.","en":"His feelings are complicated; he is both happy and sad."},{"use":"想得太复杂: bổ ngữ trạng thái","ex":"别把简单的事情想得太复杂。","py":"Bié bǎ jiǎndān de shìqing xiǎng de tài fùzá.","vi":"Đừng nghĩ những chuyện đơn giản quá phức tạp.","en":"Don't overcomplicate simple things."},{"use":"手续太复杂了: nói về thủ tục","ex":"办这件事的手续太复杂了。","py":"Bàn zhè jiàn shì de shǒuxù tài fùzá le.","vi":"Thủ tục làm việc này phức tạp quá.","en":"The procedure for this is far too complicated."}]},"解释":{"en":"to explain; to interpret; explanation","exs":[{"use":"động từ + tân ngữ: giải thích cho ai điều gì","ex":"老师给我们解释了这个词的意思。","py":"Lǎoshī gěi wǒmen jiěshì le zhège cí de yìsi.","vi":"Thầy giáo giải thích ý nghĩa của từ này cho chúng tôi.","en":"The teacher explained the meaning of this word to us."},{"use":"解释一下: nhờ ai giải thích một chút","ex":"请你再解释一下这个句子，好吗？","py":"Qǐng nǐ zài jiěshì yíxià zhège jùzi, hǎo ma?","vi":"Bạn giải thích lại câu này một chút được không?","en":"Could you explain this sentence once more, please?"},{"use":"nghĩa giải thích, biện giải lý do","ex":"迟到了就要解释原因，不要找借口。","py":"Chídào le jiù yào jiěshì yuányīn, bú yào zhǎo jièkǒu.","vi":"Đi muộn thì phải giải thích nguyên nhân, đừng viện cớ.","en":"If you are late, you should explain why instead of making excuses."},{"use":"解释 + 清楚: bổ ngữ kết quả, giải thích rõ","ex":"这个问题很难解释清楚。","py":"Zhège wèntí hěn nán jiěshì qīngchu.","vi":"Vấn đề này rất khó giải thích cho rõ.","en":"This problem is hard to explain clearly."}]},"清楚":{"en":"clear; distinct; to be clear about","exs":[{"use":"tính từ: rõ ràng, nghe/nhìn rõ","ex":"他的声音很清楚。","py":"Tā de shēngyīn hěn qīngchu.","vi":"Giọng của anh ấy rất rõ.","en":"His voice is very clear."},{"use":"V + 清楚: bổ ngữ kết quả, làm cho rõ","ex":"请你把地址写清楚。","py":"Qǐng nǐ bǎ dìzhǐ xiě qīngchu.","vi":"Bạn hãy viết địa chỉ cho rõ ràng.","en":"Please write the address clearly."},{"use":"động từ/tính từ vị ngữ: biết rõ, hiểu rõ","ex":"这件事我不太清楚。","py":"Zhè jiàn shì wǒ bú tài qīngchu.","vi":"Việc này tôi không rõ lắm.","en":"I am not very clear about this matter."},{"use":"听清楚: nghe rõ (hỏi lại)","ex":"你听清楚了吗？","py":"Nǐ tīng qīngchu le ma?","vi":"Bạn nghe rõ chưa?","en":"Did you hear it clearly?"}]},"听懂":{"en":"to understand (by listening)","exs":[{"use":"V + 没 + 听懂: phủ định quá khứ","ex":"他说得太快，我没听懂。","py":"Tā shuō de tài kuài, wǒ méi tīngdǒng.","vi":"Anh ấy nói nhanh quá, tôi nghe không hiểu.","en":"He spoke too fast and I did not understand."},{"use":"能 + 听懂: hỏi khả năng nghe hiểu","ex":"你能听懂中文广播吗？","py":"Nǐ néng tīngdǒng Zhōngwén guǎngbō ma?","vi":"Bạn có nghe hiểu đài phát thanh tiếng Trung không?","en":"Can you understand Chinese radio broadcasts?"},{"use":"điều kiện: …就能听懂","ex":"慢慢说，我就能听懂。","py":"Màn man shuō, wǒ jiù néng tīngdǒng.","vi":"Nói chậm thôi thì tôi sẽ nghe hiểu được.","en":"If you speak slowly, I can understand."},{"use":"V + 了 + 听懂 với 才: mãi mới hiểu","ex":"看了字幕，我才听懂了那个笑话。","py":"Kàn le zìmù, wǒ cái tīngdǒng le nàge xiàohua.","vi":"Xem phụ đề rồi tôi mới nghe hiểu câu chuyện cười đó.","en":"Only after reading the subtitles did I understand that joke."}]},"水平":{"en":"level; standard; proficiency","exs":[{"use":"水平 + 提高: trình độ nâng cao","ex":"他的汉语水平提高得很快。","py":"Tā de Hànyǔ shuǐpíng tígāo de hěn kuài.","vi":"Trình độ tiếng Hán của anh ấy tiến bộ rất nhanh.","en":"His Chinese level has improved very quickly."},{"use":"N + 水平 + 高/低: mức độ chất lượng","ex":"这家餐厅的服务水平很高。","py":"Zhè jiā cāntīng de fúwù shuǐpíng hěn gāo.","vi":"Chất lượng phục vụ của nhà hàng này rất cao.","en":"The service standard of this restaurant is very high."},{"use":"生活水平: mức sống","ex":"现在人们的生活水平越来越高了。","py":"Xiànzài rénmen de shēnghuó shuǐpíng yuè lái yuè gāo le.","vi":"Mức sống của mọi người hiện nay ngày càng cao.","en":"People's standard of living is getting higher and higher."},{"use":"达到 + 水平: đạt trình độ","ex":"他的英语已经达到了很高的水平。","py":"Tā de Yīngyǔ yǐjīng dádào le hěn gāo de shuǐpíng.","vi":"Tiếng Anh của anh ấy đã đạt trình độ rất cao.","en":"His English has already reached a very high level."}]},"对于":{"en":"regarding; with regard to; as for","exs":[{"use":"对于 + N, câu: đứng đầu câu nêu đối tượng","ex":"对于这个问题，大家的看法不一样。","py":"Duìyú zhège wèntí, dàjiā de kànfǎ bù yíyàng.","vi":"Đối với vấn đề này, quan điểm của mọi người không giống nhau.","en":"Regarding this issue, everyone has a different view."},{"use":"对于…来说: đối với… mà nói","ex":"对于学生来说，时间非常重要。","py":"Duìyú xuésheng lái shuō, shíjiān fēicháng zhòngyào.","vi":"Đối với học sinh mà nói, thời gian vô cùng quan trọng.","en":"For students, time is extremely important."},{"use":"对于 + N + 的 + N: làm định ngữ","ex":"对于孩子的教育，父母要有耐心。","py":"Duìyú háizi de jiàoyù, fùmǔ yào yǒu nàixīn.","vi":"Đối với việc giáo dục con cái, cha mẹ phải có kiên nhẫn.","en":"When it comes to educating children, parents need patience."},{"use":"chủ ngữ + 对于 + N + vị ngữ","ex":"他对于这次比赛很有信心。","py":"Tā duìyú zhè cì bǐsài hěn yǒu xìnxīn.","vi":"Anh ấy rất có lòng tin đối với cuộc thi lần này.","en":"He is very confident about this competition."}]},"叶子":{"en":"leaf; leaves","exs":[{"use":"danh từ: lá cây","ex":"秋天到了，树上的叶子变黄了。","py":"Qiūtiān dào le, shù shang de yèzi biàn huáng le.","vi":"Mùa thu đến rồi, lá trên cây đã chuyển vàng.","en":"Autumn has come and the leaves on the trees have turned yellow."},{"use":"叶子 + 很 + adj: miêu tả lá","ex":"这盆花的叶子很绿。","py":"Zhè pén huā de yèzi hěn lǜ.","vi":"Lá của chậu hoa này rất xanh.","en":"The leaves of this potted flower are very green."},{"use":"lá trà, lá cây dùng được","ex":"这种茶的叶子又细又长。","py":"Zhè zhǒng chá de yèzi yòu xì yòu cháng.","vi":"Lá của loại trà này vừa nhỏ vừa dài.","en":"The leaves of this kind of tea are thin and long."},{"use":"địa điểm + V + 满 + 叶子","ex":"地上落满了叶子。","py":"Dìshang luò mǎn le yèzi.","vi":"Trên mặt đất rơi đầy lá.","en":"The ground is covered with fallen leaves."}]},"同样":{"en":"same; equal; likewise","exs":[{"use":"同样 + 的 + N: làm định ngữ","ex":"我们买了同样的手机。","py":"Wǒmen mǎi le tóngyàng de shǒujī.","vi":"Chúng tôi mua cùng một loại điện thoại.","en":"We bought the same phone."},{"use":"同样 + 一 + lượng từ + N: cùng một","ex":"同样一件事，他和我的看法不同。","py":"Tóngyàng yí jiàn shì, tā hé wǒ de kànfǎ bù tóng.","vi":"Cùng một việc mà cách nhìn của anh ấy và tôi khác nhau.","en":"Even about the same matter, his view and mine are different."},{"use":"同样,…: liên từ, tương tự như vậy","ex":"他很努力，同样，他的朋友也很认真。","py":"Tā hěn nǔlì, tóngyàng, tā de péngyou yě hěn rènzhēn.","vi":"Anh ấy rất cố gắng, tương tự, bạn của anh ấy cũng rất nghiêm túc.","en":"He works hard, and likewise his friend is very serious."},{"use":"同样是…: cùng là… nhưng khác nhau","ex":"同样是水果，苹果比香蕉便宜。","py":"Tóngyàng shì shuǐguǒ, píngguǒ bǐ xiāngjiāo piányi.","vi":"Cùng là trái cây, táo rẻ hơn chuối.","en":"Both are fruit, but apples are cheaper than bananas."}]},"教育":{"en":"education; to educate","exs":[{"use":"danh từ: nền giáo dục, việc giáo dục","ex":"孩子的教育是家庭最重要的事。","py":"Háizi de jiàoyù shì jiātíng zuì zhòngyào de shì.","vi":"Việc giáo dục con cái là chuyện quan trọng nhất của gia đình.","en":"Children's education is the most important thing for a family."},{"use":"động từ: giáo dục, dạy dỗ ai","ex":"父母应该教育孩子要诚实。","py":"Fùmǔ yīnggāi jiàoyù háizi yào chéngshí.","vi":"Cha mẹ nên dạy dỗ con cái phải thật thà.","en":"Parents should teach their children to be honest."},{"use":"受教育: được học hành","ex":"每个孩子都有受教育的权利。","py":"Měi ge háizi dōu yǒu shòu jiàoyù de quánlì.","vi":"Mỗi đứa trẻ đều có quyền được giáo dục.","en":"Every child has the right to receive an education."},{"use":"教育 + N: lĩnh vực giáo dục","ex":"他在一所大学做教育工作。","py":"Tā zài yì suǒ dàxué zuò jiàoyù gōngzuò.","vi":"Anh ấy làm công tác giáo dục ở một trường đại học.","en":"He works in education at a university."}]},"筷子":{"en":"chopsticks","exs":[{"use":"用 + 筷子: dùng đũa để ăn","ex":"中国人吃饭用筷子。","py":"Zhōngguó rén chīfàn yòng kuàizi.","vi":"Người Trung Quốc ăn cơm bằng đũa.","en":"Chinese people use chopsticks to eat."},{"use":"一双 + 筷子: lượng từ 双 (đôi)","ex":"我想买一双新筷子。","py":"Wǒ xiǎng mǎi yì shuāng xīn kuàizi.","vi":"Tôi muốn mua một đôi đũa mới.","en":"I want to buy a new pair of chopsticks."},{"use":"把 + 筷子 + 放在…: cấu trúc 把","ex":"请把筷子放在碗的右边。","py":"Qǐng bǎ kuàizi fàng zài wǎn de yòubian.","vi":"Hãy đặt đũa ở bên phải cái bát.","en":"Please put the chopsticks on the right side of the bowl."}]},"历史":{"en":"history; past record","exs":[{"use":"有 + số năm + 的历史: có lịch sử bao lâu","ex":"这座城市有三千年的历史。","py":"Zhè zuò chéngshì yǒu sānqiān nián de lìshǐ.","vi":"Thành phố này có lịch sử ba nghìn năm.","en":"This city has a history of three thousand years."},{"use":"历史课: môn học lịch sử","ex":"我最喜欢上历史课。","py":"Wǒ zuì xǐhuan shàng lìshǐ kè.","vi":"Tôi thích nhất là học môn lịch sử.","en":"I like history class the best."},{"use":"成为历史: đã thành quá khứ","ex":"这件事已经成了历史。","py":"Zhè jiàn shì yǐjīng chéng le lìshǐ.","vi":"Việc này đã trở thành lịch sử rồi.","en":"This matter has already become history."}]},"外国人":{"en":"foreigner","exs":[{"use":"外国人 + 会/能 + V: người nước ngoài làm gì","ex":"那个外国人会说很好的汉语。","py":"Nàge wàiguó rén huì shuō hěn hǎo de Hànyǔ.","vi":"Người nước ngoài đó nói tiếng Hán rất giỏi.","en":"That foreigner speaks very good Chinese."},{"use":"有 + 很多 + 外国人: chỉ số lượng","ex":"我们班有很多外国人。","py":"Wǒmen bān yǒu hěn duō wàiguó rén.","vi":"Lớp chúng tôi có rất nhiều người nước ngoài.","en":"There are many foreigners in our class."},{"use":"对外国人来说: đối với người nước ngoài","ex":"对外国人来说，汉字很难。","py":"Duì wàiguó rén lái shuō, Hànzì hěn nán.","vi":"Đối với người nước ngoài, chữ Hán rất khó.","en":"For foreigners, Chinese characters are difficult."}]},"错误":{"en":"mistake; error; wrong","exs":[{"use":"danh từ: lỗi, sai lầm; 犯错误","ex":"写作文时要少犯错误。","py":"Xiě zuòwén shí yào shǎo fàn cuòwù.","vi":"Khi viết văn phải phạm ít lỗi.","en":"You should make fewer mistakes when writing an essay."},{"use":"tính từ: sai, không đúng (错误的)","ex":"这个答案是错误的。","py":"Zhège dá'àn shì cuòwù de.","vi":"Đáp án này là sai.","en":"This answer is wrong."},{"use":"承认错误: thừa nhận sai lầm","ex":"他很快就承认了自己的错误。","py":"Tā hěn kuài jiù chéngrèn le zìjǐ de cuòwù.","vi":"Anh ấy nhanh chóng thừa nhận lỗi của mình.","en":"He quickly admitted his mistake."},{"use":"错误的 + N: làm định ngữ","ex":"这是一个错误的决定。","py":"Zhè shì yí ge cuòwù de juédìng.","vi":"Đây là một quyết định sai lầm.","en":"This is a wrong decision."}]},"饮料":{"en":"drink; beverage","exs":[{"use":"喝 + 饮料: uống đồ uống","ex":"夏天我喜欢喝冰的饮料。","py":"Xiàtiān wǒ xǐhuan hē bīng de yǐnliào.","vi":"Mùa hè tôi thích uống đồ uống lạnh.","en":"In summer I like to drink cold beverages."},{"use":"hỏi ở nhà hàng: 有什么饮料","ex":"请问，你们这儿有什么饮料？","py":"Qǐngwèn, nǐmen zhèr yǒu shénme yǐnliào?","vi":"Xin hỏi, ở đây có những đồ uống gì?","en":"Excuse me, what drinks do you have here?"},{"use":"饮料 làm chủ ngữ: nói về tác hại","ex":"太甜的饮料对身体不好。","py":"Tài tián de yǐnliào duì shēntǐ bù hǎo.","vi":"Đồ uống quá ngọt không tốt cho cơ thể.","en":"Overly sweet drinks are bad for your health."}]},"解渴":{"en":"to quench one's thirst","exs":[{"use":"喝…就能解渴: uống gì thì hết khát","ex":"天太热了，喝杯凉水就能解渴。","py":"Tiān tài rè le, hē bēi liángshuǐ jiù néng jiěkě.","vi":"Trời nóng quá, uống cốc nước mát là giải khát được.","en":"It is so hot that a glass of cold water can quench your thirst."},{"use":"N + 能解渴: thứ có tác dụng giải khát","ex":"西瓜又甜又能解渴。","py":"Xīguā yòu tián yòu néng jiěkě.","vi":"Dưa hấu vừa ngọt vừa giải khát.","en":"Watermelon is sweet and quenches thirst."},{"use":"不解渴: phủ định","ex":"我喝了一瓶水，还是不解渴。","py":"Wǒ hē le yì píng shuǐ, háishi bù jiěkě.","vi":"Tôi uống hết một chai nước mà vẫn chưa hết khát.","en":"I drank a bottle of water and still was not satisfied."}]},"茶文化":{"en":"tea culture","exs":[{"use":"có + lịch sử: 茶文化 làm chủ ngữ","ex":"中国的茶文化有几千年的历史。","py":"Zhōngguó de chá wénhuà yǒu jǐ qiān nián de lìshǐ.","vi":"Văn hóa trà của Trung Quốc có lịch sử mấy nghìn năm.","en":"China's tea culture has a history of several thousand years."},{"use":"对…感兴趣: đối tượng quan tâm","ex":"他对茶文化很感兴趣。","py":"Tā duì chá wénhuà hěn gǎn xìngqù.","vi":"Anh ấy rất hứng thú với văn hóa trà.","en":"He is very interested in tea culture."},{"use":"茶文化 + N: định ngữ cho danh từ","ex":"在茶文化博物馆里，我们看到了很多茶具。","py":"Zài chá wénhuà bówùguǎn lǐ, wǒmen kàn dào le hěn duō chájù.","vi":"Trong bảo tàng văn hóa trà, chúng tôi thấy rất nhiều bộ trà cụ.","en":"In the tea culture museum we saw many tea sets."}]},"普遍":{"en":"common; widespread; universal","exs":[{"use":"很普遍: tính từ vị ngữ, phổ biến","ex":"使用手机在年轻人中很普遍。","py":"Shǐyòng shǒujī zài niánqīngrén zhōng hěn pǔbiàn.","vi":"Dùng điện thoại rất phổ biến trong giới trẻ.","en":"Using mobile phones is very common among young people."},{"use":"普遍的 + N: làm định ngữ","ex":"这是一个普遍的问题，很多学校都有。","py":"Zhè shì yí ge pǔbiàn de wèntí, hěn duō xuéxiào dōu yǒu.","vi":"Đây là vấn đề phổ biến, nhiều trường đều có.","en":"This is a widespread problem found in many schools."},{"use":"普遍 + động từ: phó từ, nói chung, phổ biến","ex":"人们普遍认为早睡早起对身体好。","py":"Rénmen pǔbiàn rènwéi zǎo shuì zǎo qǐ duì shēntǐ hǎo.","vi":"Mọi người nhìn chung đều cho rằng ngủ sớm dậy sớm tốt cho sức khỏe.","en":"People generally believe that going to bed and getting up early is good for health."}]},"稍微":{"en":"slightly; a little","exs":[{"use":"稍微 + adj + 一点: hơi một chút (so sánh)","ex":"今天比昨天稍微冷一点。","py":"Jīntiān bǐ zuótiān shāowēi lěng yìdiǎn.","vi":"Hôm nay hơi lạnh hơn hôm qua một chút.","en":"Today is slightly colder than yesterday."},{"use":"稍微 + V + 一下: làm một chút (nhờ vả)","ex":"你稍微等一下，我马上就来。","py":"Nǐ shāowēi děng yíxià, wǒ mǎshàng jiù lái.","vi":"Bạn đợi một chút, tôi đến ngay.","en":"Wait a moment, I will be right there."},{"use":"稍微有点 + adj: hơi… (nhận xét)","ex":"这件衣服稍微有点大。","py":"Zhè jiàn yīfu shāowēi yǒudiǎn dà.","vi":"Chiếc áo này hơi rộng một chút.","en":"This piece of clothing is a bit big."}]},"中药":{"en":"traditional Chinese medicine; herbal medicine","exs":[{"use":"喝中药: uống thuốc Đông y","ex":"他感冒了，医生让他喝中药。","py":"Tā gǎnmào le, yīshēng ràng tā hē zhōngyào.","vi":"Anh ấy bị cảm, bác sĩ bảo anh ấy uống thuốc Đông y.","en":"He has a cold and the doctor told him to take Chinese herbal medicine."},{"use":"中药的味道: nói về mùi vị","ex":"中药的味道有点苦。","py":"Zhōngyào de wèidào yǒudiǎn kǔ.","vi":"Thuốc Đông y có vị hơi đắng.","en":"Chinese medicine tastes a little bitter."},{"use":"中药店: cửa hàng thuốc Đông y","ex":"奶奶常去中药店买药。","py":"Nǎinai cháng qù zhōngyào diàn mǎi yào.","vi":"Bà thường đến tiệm thuốc Đông y để mua thuốc.","en":"Grandma often goes to the herbal medicine shop to buy medicine."}]},"大约":{"en":"about; approximately; probably","exs":[{"use":"大约 + số lượng: khoảng (thời gian, khoảng cách)","ex":"从这儿到机场大约需要四十分钟。","py":"Cóng zhèr dào jīchǎng dàyuē xūyào sìshí fēnzhōng.","vi":"Từ đây đến sân bay mất khoảng bốn mươi phút.","en":"It takes about forty minutes from here to the airport."},{"use":"大约 + số tuổi","ex":"他大约三十岁。","py":"Tā dàyuē sānshí suì.","vi":"Anh ấy khoảng ba mươi tuổi.","en":"He is about thirty years old."},{"use":"大约 + thời điểm: khoảng mấy giờ","ex":"会议大约九点开始。","py":"Huìyì dàyuē jiǔ diǎn kāishǐ.","vi":"Cuộc họp khoảng chín giờ bắt đầu.","en":"The meeting will start at about nine o'clock."},{"use":"nghĩa phỏng đoán: có lẽ, đại khái","ex":"现在大约没有人在办公室了。","py":"Xiànzài dàyuē méiyǒu rén zài bàngōngshì le.","vi":"Bây giờ có lẽ không còn ai ở văn phòng nữa.","en":"There is probably no one left in the office now."}]},"餐厅":{"en":"restaurant; dining hall","exs":[{"use":"danh từ: nhà hàng","ex":"这家餐厅的菜又好吃又便宜。","py":"Zhè jiā cāntīng de cài yòu hǎochī yòu piányi.","vi":"Món ăn của nhà hàng này vừa ngon vừa rẻ.","en":"The food at this restaurant is both tasty and cheap."},{"use":"学校餐厅: căng tin, nhà ăn","ex":"我们在学校餐厅吃午饭。","py":"Wǒmen zài xuéxiào cāntīng chī wǔfàn.","vi":"Chúng tôi ăn trưa ở căng tin trường.","en":"We have lunch in the school dining hall."},{"use":"在餐厅订位子","ex":"我已经在餐厅订了位子。","py":"Wǒ yǐjīng zài cāntīng dìng le wèizi.","vi":"Tôi đã đặt chỗ ở nhà hàng rồi.","en":"I have already reserved a table at the restaurant."}]},"互联网":{"en":"the Internet","exs":[{"use":"在互联网上: trên Internet","ex":"现在人们可以在互联网上买东西。","py":"Xiànzài rénmen kěyǐ zài hùliánwǎng shang mǎi dōngxī.","vi":"Bây giờ mọi người có thể mua đồ trên Internet.","en":"Nowadays people can shop on the Internet."},{"use":"互联网 làm chủ ngữ","ex":"互联网让世界变得越来越小。","py":"Hùliánwǎng ràng shìjiè biàn de yuè lái yuè xiǎo.","vi":"Internet làm cho thế giới ngày càng nhỏ lại.","en":"The Internet makes the world smaller and smaller."},{"use":"互联网 + N: công ty/ngành Internet","ex":"他在一家互联网公司工作。","py":"Tā zài yì jiā hùliánwǎng gōngsī gōngzuò.","vi":"Anh ấy làm việc ở một công ty Internet.","en":"He works at an Internet company."}]},"进行":{"en":"to carry out; to conduct; to be in progress","exs":[{"use":"正在进行: đang diễn ra","ex":"会议正在进行。","py":"Huìyì zhèngzài jìnxíng.","vi":"Cuộc họp đang diễn ra.","en":"The meeting is in progress."},{"use":"对…进行 + động từ hai âm tiết: tiến hành","ex":"我们对这个问题进行了讨论。","py":"Wǒmen duì zhège wèntí jìnxíng le tǎolùn.","vi":"Chúng tôi đã thảo luận về vấn đề này.","en":"We held a discussion on this issue."},{"use":"进行 + thời gian: sẽ tiến hành vào lúc","ex":"比赛将在下周进行。","py":"Bǐsài jiāng zài xià zhōu jìnxíng.","vi":"Cuộc thi sẽ được tổ chức vào tuần sau.","en":"The competition will take place next week."},{"use":"对 + người + 进行 + kiểm tra","ex":"医生要对他进行检查。","py":"Yīshēng yào duì tā jìnxíng jiǎnchá.","vi":"Bác sĩ sẽ kiểm tra cho anh ấy.","en":"The doctor is going to examine him."}]},"好好":{"en":"properly; carefully; to one's heart's content; in good condition","exs":[{"use":"好好 + V: hãy làm cho tử tế (khuyên bảo)","ex":"你要好好休息。","py":"Nǐ yào hǎohāo xiūxi.","vi":"Bạn phải nghỉ ngơi cho tốt.","en":"You must get a good rest."},{"use":"请好好 + V: làm cẩn thận","ex":"请好好想一想再回答。","py":"Qǐng hǎohāo xiǎng yi xiǎng zài huídá.","vi":"Hãy suy nghĩ kỹ rồi hãy trả lời.","en":"Please think carefully before answering."},{"use":"好好的: còn nguyên vẹn, đang ổn","ex":"这台电脑昨天还好好的，今天怎么坏了？","py":"Zhè tái diànnǎo zuótiān hái hǎohāo de, jīntiān zěnme huài le?","vi":"Chiếc máy tính này hôm qua còn tốt, sao hôm nay hỏng rồi?","en":"This computer was fine yesterday; why is it broken today?"},{"use":"好好 + V: thỏa thích","ex":"周末我想好好玩儿一天。","py":"Zhōumò wǒ xiǎng hǎohāo wánr yì tiān.","vi":"Cuối tuần tôi muốn chơi thỏa thích một ngày.","en":"This weekend I want to have a good day of fun."}]},"常见":{"en":"common; frequently seen","exs":[{"use":"很常见的 + N: định ngữ","ex":"感冒是冬天很常见的病。","py":"Gǎnmào shì dōngtiān hěn chángjiàn de bìng.","vi":"Cảm lạnh là bệnh rất thường gặp vào mùa đông.","en":"A cold is a very common illness in winter."},{"use":"地点 + 很常见: thường gặp ở đâu","ex":"这种鸟在南方很常见。","py":"Zhè zhǒng niǎo zài nánfāng hěn chángjiàn.","vi":"Loài chim này rất thường gặp ở miền Nam.","en":"This kind of bird is very common in the south."},{"use":"常见的 + 错误: lỗi thường gặp","ex":"这是学生常见的错误。","py":"Zhè shì xuésheng chángjiàn de cuòwù.","vi":"Đây là lỗi mà học sinh thường mắc.","en":"This is a mistake students often make."},{"use":"不常见: phủ định, hiếm thấy","ex":"这么大的雪，在这里不常见。","py":"Zhème dà de xuě, zài zhèlǐ bù chángjiàn.","vi":"Tuyết lớn như vậy ở đây không thường thấy.","en":"Such heavy snow is not common here."}]},"最早":{"en":"earliest; at the earliest","exs":[{"use":"最早的 + N: tính từ, sớm nhất","ex":"这是最早的一班火车。","py":"Zhè shì zuìzǎo de yì bān huǒchē.","vi":"Đây là chuyến tàu sớm nhất.","en":"This is the earliest train."},{"use":"最早 + V: phó từ, người/việc đầu tiên","ex":"他是班里最早到教室的人。","py":"Tā shì bān lǐ zuìzǎo dào jiàoshì de rén.","vi":"Anh ấy là người đến lớp sớm nhất trong lớp.","en":"He is the earliest person in the class to arrive at the classroom."},{"use":"最早 + xuất hiện: sớm nhất về mặt lịch sử","ex":"茶最早出现在中国。","py":"Chá zuìzǎo chūxiàn zài Zhōngguó.","vi":"Trà xuất hiện sớm nhất ở Trung Quốc.","en":"Tea first appeared in China."},{"use":"最早…才…: sớm nhất cũng phải…","ex":"这份快递最早明天才能到。","py":"Zhè fèn kuàidì zuìzǎo míngtiān cái néng dào.","vi":"Bưu kiện này sớm nhất cũng phải ngày mai mới đến.","en":"This package will not arrive until tomorrow at the earliest."}]},"当作":{"en":"to treat as; to regard as","exs":[{"use":"把 + A + 当作 + B: coi A như B","ex":"他把我当作最好的朋友。","py":"Tā bǎ wǒ dàngzuò zuì hǎo de péngyou.","vi":"Anh ấy coi tôi là người bạn tốt nhất.","en":"He regards me as his best friend."},{"use":"别把…当作…: đừng coi… là…","ex":"别把这件事当作玩笑。","py":"Bié bǎ zhè jiàn shì dàngzuò wánxiào.","vi":"Đừng coi chuyện này là trò đùa.","en":"Don't treat this matter as a joke."},{"use":"被…当作…: câu bị động","ex":"这个房间被我们当作办公室。","py":"Zhège fángjiān bèi wǒmen dàngzuò bàngōngshì.","vi":"Căn phòng này được chúng tôi dùng làm văn phòng.","en":"This room is used as an office by us."},{"use":"当作 + vật + dùng: dùng làm","ex":"她常常把手机当作闹钟用。","py":"Tā chángcháng bǎ shǒujī dàngzuò nàozhōng yòng.","vi":"Cô ấy thường dùng điện thoại làm đồng hồ báo thức.","en":"She often uses her phone as an alarm clock."}]},"随着":{"en":"along with; as; following","exs":[{"use":"随着 + N + 的 + V, …: cùng với sự…","ex":"随着经济的发展，人们的生活越来越好。","py":"Suízhe jīngjì de fāzhǎn, rénmen de shēnghuó yuè lái yuè hǎo.","vi":"Cùng với sự phát triển của kinh tế, cuộc sống của mọi người ngày càng tốt hơn.","en":"With economic development, people's lives are getting better and better."},{"use":"随着 + mệnh đề: khi… thì…","ex":"随着天气变冷，我们都穿上了厚衣服。","py":"Suízhe tiānqì biàn lěng, wǒmen dōu chuān shàng le hòu yīfu.","vi":"Khi trời lạnh dần, chúng tôi đều mặc áo dày vào.","en":"As the weather got colder, we all put on thick clothes."},{"use":"随着年龄的增长: theo tuổi tác","ex":"随着年龄的增长，他懂得了很多道理。","py":"Suízhe niánlíng de zēngzhǎng, tā dǒngde le hěn duō dàolǐ.","vi":"Theo tuổi tác lớn dần, anh ấy hiểu ra nhiều đạo lý.","en":"As he grew older, he came to understand many truths."}]},"十分":{"en":"very; extremely; fully","exs":[{"use":"十分 + adj: rất, vô cùng","ex":"今天的天气十分好。","py":"Jīntiān de tiānqì shífēn hǎo.","vi":"Thời tiết hôm nay vô cùng tốt.","en":"The weather is extremely nice today."},{"use":"对…十分 + adj tâm lý (满意…)","ex":"我对这份工作十分满意。","py":"Wǒ duì zhè fèn gōngzuò shífēn mǎnyì.","vi":"Tôi rất hài lòng với công việc này.","en":"I am very satisfied with this job."},{"use":"十分 + 不 + adj: rất không…","ex":"他对这件事十分不高兴。","py":"Tā duì zhè jiàn shì shífēn bù gāoxìng.","vi":"Anh ấy rất không vui về chuyện này.","en":"He is extremely unhappy about this matter."},{"use":"十分 + động từ tâm lý (关心…)","ex":"老师十分关心每个学生。","py":"Lǎoshī shífēn guānxīn měi ge xuésheng.","vi":"Thầy giáo rất quan tâm đến từng học sinh.","en":"The teacher cares deeply about every student."}]},"名字":{"en":"name","exs":[{"use":"什么名字: hỏi tên","ex":"你叫什么名字？","py":"Nǐ jiào shénme míngzi?","vi":"Bạn tên là gì?","en":"What is your name?"},{"use":"写上名字: điền tên","ex":"请在这里写上你的名字。","py":"Qǐng zài zhèlǐ xiě shàng nǐ de míngzi.","vi":"Hãy viết tên của bạn vào đây.","en":"Please write your name here."},{"use":"记不住名字: nhớ không nổi tên","ex":"我记不住他的名字。","py":"Wǒ jì bu zhù tā de míngzi.","vi":"Tôi không nhớ nổi tên của anh ấy.","en":"I cannot remember his name."},{"use":"名字是…起的: người đặt tên","ex":"这个孩子的名字是爷爷起的。","py":"Zhège háizi de míngzi shì yéye qǐ de.","vi":"Tên của đứa bé này do ông nội đặt.","en":"This child's name was chosen by his grandfather."}]},"爷爷":{"en":"paternal grandfather; grandpa","exs":[{"use":"爷爷 + 每天…: miêu tả thói quen","ex":"我爷爷每天早上都去公园打太极拳。","py":"Wǒ yéye měi tiān zǎoshang dōu qù gōngyuán dǎ tàijíquán.","vi":"Ông nội tôi sáng nào cũng ra công viên tập thái cực quyền.","en":"My grandfather goes to the park to practice tai chi every morning."},{"use":"给 + 人 + 讲故事","ex":"爷爷给我讲了一个故事。","py":"Yéye gěi wǒ jiǎng le yí ge gùshi.","vi":"Ông nội kể cho tôi một câu chuyện.","en":"Grandpa told me a story."},{"use":"nói tuổi và sức khỏe","ex":"爷爷今年八十岁了，身体还很好。","py":"Yéye jīnnián bāshí suì le, shēntǐ hái hěn hǎo.","vi":"Năm nay ông nội tám mươi tuổi rồi, sức khỏe vẫn còn tốt.","en":"Grandpa is eighty this year and still in good health."}]},"京剧":{"en":"Beijing opera","exs":[{"use":"爱听京剧: sở thích","ex":"我奶奶爱听京剧。","py":"Wǒ nǎinai ài tīng jīngjù.","vi":"Bà nội tôi thích nghe Kinh kịch.","en":"My grandmother loves listening to Beijing opera."},{"use":"是…的传统艺术: giới thiệu","ex":"京剧是中国的传统艺术。","py":"Jīngjù shì Zhōngguó de chuántǒng yìshù.","vi":"Kinh kịch là nghệ thuật truyền thống của Trung Quốc.","en":"Beijing opera is a traditional Chinese art form."},{"use":"看过京剧: kinh nghiệm với 过","ex":"你看过京剧表演吗？","py":"Nǐ kàn guo jīngjù biǎoyǎn ma?","vi":"Bạn đã xem biểu diễn Kinh kịch bao giờ chưa?","en":"Have you ever seen a Beijing opera performance?"},{"use":"京剧 + N: 京剧演员, nghệ sĩ Kinh kịch","ex":"京剧演员的脸上画着漂亮的脸谱。","py":"Jīngjù yǎnyuán de liǎn shang huà zhe piàoliang de liǎnpǔ.","vi":"Trên mặt diễn viên Kinh kịch được vẽ những chiếc mặt nạ vẽ tay đẹp mắt.","en":"Beijing opera actors have beautiful painted faces."}]},"演员":{"en":"actor; actress; performer","exs":[{"use":"演过电影: kinh nghiệm diễn xuất","ex":"这位演员演过很多电影。","py":"Zhè wèi yǎnyuán yǎn guo hěn duō diànyǐng.","vi":"Diễn viên này đã đóng rất nhiều phim.","en":"This actor has appeared in many films."},{"use":"当演员: làm nghề diễn viên","ex":"他从小就想当演员。","py":"Tā cóngxiǎo jiù xiǎng dāng yǎnyuán.","vi":"Từ nhỏ anh ấy đã muốn làm diễn viên.","en":"He has wanted to be an actor since childhood."},{"use":"演员们: số nhiều","ex":"演员们正在后台化妆。","py":"Yǎnyuánmen zhèngzài hòutái huàzhuāng.","vi":"Các diễn viên đang trang điểm ở hậu trường.","en":"The actors are putting on makeup backstage."},{"use":"女演员: diễn viên nữ","ex":"我很喜欢那个女演员。","py":"Wǒ hěn xǐhuan nàge nǚ yǎnyuán.","vi":"Tôi rất thích nữ diễn viên đó.","en":"I really like that actress."}]},"深受":{"en":"to be deeply (loved, influenced); to receive greatly","exs":[{"use":"深受 + N + 的 + 喜爱/欢迎: được yêu thích","ex":"这部电影深受年轻人的喜爱。","py":"Zhè bù diànyǐng shēnshòu niánqīngrén de xǐ'ài.","vi":"Bộ phim này rất được giới trẻ yêu thích.","en":"This movie is deeply loved by young people."},{"use":"深受…欢迎: rất được chào đón","ex":"他深受老师和同学的欢迎。","py":"Tā shēnshòu lǎoshī hé tóngxué de huānyíng.","vi":"Anh ấy rất được thầy cô và bạn học quý mến.","en":"He is very popular among teachers and classmates."},{"use":"深受 + N + V: rất được… ưa thích","ex":"这个地方深受游客喜欢。","py":"Zhège dìfang shēnshòu yóukè xǐhuan.","vi":"Nơi này rất được du khách yêu thích.","en":"This place is very popular with tourists."},{"use":"深受…影响: chịu ảnh hưởng sâu sắc","ex":"孩子深受父母的影响。","py":"Háizi shēnshòu fùmǔ de yǐngxiǎng.","vi":"Con cái chịu ảnh hưởng sâu sắc từ cha mẹ.","en":"Children are deeply influenced by their parents."}]},"观众":{"en":"audience; spectators; viewers","exs":[{"use":"观众们 + V: khán giả làm gì","ex":"观众们热烈地鼓掌。","py":"Guānzhòngmen rèliè de gǔzhǎng.","vi":"Khán giả nhiệt liệt vỗ tay.","en":"The audience applauded enthusiastically."},{"use":"坐满了 + 观众: đầy khán giả","ex":"体育馆里坐满了观众。","py":"Tǐyùguǎn lǐ zuò mǎn le guānzhòng.","vi":"Nhà thi đấu ngồi kín khán giả.","en":"The stadium was filled with spectators."},{"use":"观众越来越多: số lượng","ex":"这个节目的观众越来越多。","py":"Zhège jiémù de guānzhòng yuè lái yuè duō.","vi":"Chương trình này ngày càng có nhiều khán giả.","en":"This show has more and more viewers."}]},"深厚":{"en":"deep; profound; solid","exs":[{"use":"深厚的 + 友谊: tình bạn sâu đậm","ex":"他们之间有深厚的友谊。","py":"Tāmen zhījiān yǒu shēnhòu de yǒuyì.","vi":"Giữa họ có tình bạn sâu đậm.","en":"There is a deep friendship between them."},{"use":"深厚的 + 感情: tình cảm sâu nặng","ex":"她对家乡有深厚的感情。","py":"Tā duì jiāxiāng yǒu shēnhòu de gǎnqíng.","vi":"Cô ấy có tình cảm sâu đậm với quê hương.","en":"She has deep feelings for her hometown."},{"use":"深厚的 + 基础: nền tảng vững","ex":"中国有深厚的文化基础。","py":"Zhōngguó yǒu shēnhòu de wénhuà jīchǔ.","vi":"Trung Quốc có nền tảng văn hóa sâu dày.","en":"China has a profound cultural foundation."},{"use":"N + 很深厚: làm vị ngữ","ex":"这位老师的文化水平很深厚。","py":"Zhè wèi lǎoshī de wénhuà shuǐpíng hěn shēnhòu.","vi":"Trình độ văn hóa của thầy giáo này rất sâu rộng.","en":"This teacher's cultural knowledge is very profound."}]},"上台":{"en":"to go on stage; to take the stage","exs":[{"use":"一…就…: vừa lên sân khấu là…","ex":"他一上台就紧张。","py":"Tā yí shàngtái jiù jǐnzhāng.","vi":"Anh ấy vừa lên sân khấu là căng thẳng.","en":"He gets nervous as soon as he goes on stage."},{"use":"请 + người + 上台 + V","ex":"请下一位同学上台讲话。","py":"Qǐng xià yí wèi tóngxué shàngtái jiǎnghuà.","vi":"Mời bạn học tiếp theo lên sân khấu phát biểu.","en":"Would the next student please come up and speak?"},{"use":"上台前: trước khi lên sân khấu","ex":"上台前，她深吸了一口气。","py":"Shàngtái qián, tā shēn xī le yì kǒu qì.","vi":"Trước khi lên sân khấu, cô ấy hít sâu một hơi.","en":"Before going on stage, she took a deep breath."},{"use":"上台 + V: lên sân khấu để làm gì","ex":"今晚谁先上台唱歌？","py":"Jīnwǎn shéi xiān shàngtái chànggē?","vi":"Tối nay ai lên sân khấu hát trước?","en":"Who will go on stage to sing first tonight?"}]},"演出":{"en":"to perform; performance; show","exs":[{"use":"động từ: biểu diễn","ex":"他们明天晚上在大剧院演出。","py":"Tāmen míngtiān wǎnshang zài dà jùyuàn yǎnchū.","vi":"Tối mai họ biểu diễn ở nhà hát lớn.","en":"They will perform at the grand theater tomorrow evening."},{"use":"danh từ: buổi biểu diễn","ex":"今晚的演出非常精彩。","py":"Jīnwǎn de yǎnchū fēicháng jīngcǎi.","vi":"Buổi biểu diễn tối nay vô cùng đặc sắc.","en":"Tonight's performance was wonderful."},{"use":"演出票: vé xem biểu diễn","ex":"我买了两张演出票。","py":"Wǒ mǎi le liǎng zhāng yǎnchū piào.","vi":"Tôi đã mua hai vé xem biểu diễn.","en":"I bought two tickets for the show."},{"use":"去 + nơi + 演出: đi lưu diễn","ex":"这个剧团去过很多国家演出。","py":"Zhège jùtuán qù guo hěn duō guójiā yǎnchū.","vi":"Đoàn kịch này đã đi biểu diễn ở nhiều nước.","en":"This theater troupe has performed in many countries."}]},"大概":{"en":"probably; approximately; general idea","exs":[{"use":"phó từ: có lẽ, chắc là","ex":"他大概不会来了。","py":"Tā dàgài bú huì lái le.","vi":"Anh ấy chắc là không đến nữa rồi.","en":"He probably won't come anymore."},{"use":"大概 + thời gian: khoảng","ex":"我大概十点到家。","py":"Wǒ dàgài shí diǎn dào jiā.","vi":"Tôi khoảng mười giờ về đến nhà.","en":"I will get home at about ten."},{"use":"danh từ: đại khái, đại thể (个大概)","ex":"这本书我只看了个大概。","py":"Zhè běn shū wǒ zhǐ kàn le ge dàgài.","vi":"Cuốn sách này tôi chỉ xem qua đại khái.","en":"I only skimmed through this book."},{"use":"大概 + 有 + số lượng: ước chừng","ex":"教室里大概有三十个学生。","py":"Jiàoshì lǐ dàgài yǒu sānshí ge xuésheng.","vi":"Trong lớp học có chừng ba mươi học sinh.","en":"There are about thirty students in the classroom."}]},"故事":{"en":"story; tale","exs":[{"use":"讲故事: kể chuyện","ex":"奶奶常给我讲故事。","py":"Nǎinai cháng gěi wǒ jiǎng gùshi.","vi":"Bà thường kể chuyện cho tôi nghe.","en":"Grandma often tells me stories."},{"use":"故事 + 很有意思: nhận xét","ex":"这个故事很有意思。","py":"Zhège gùshi hěn yǒu yìsi.","vi":"Câu chuyện này rất thú vị.","en":"This story is very interesting."},{"use":"有故事的 + N: có cốt truyện","ex":"我喜欢看有故事的电影。","py":"Wǒ xǐhuan kàn yǒu gùshi de diànyǐng.","vi":"Tôi thích xem những bộ phim có cốt truyện.","en":"I like watching movies with a story."},{"use":"N + 故事: loại truyện","ex":"这本书里有很多中国的历史故事。","py":"Zhè běn shū lǐ yǒu hěn duō Zhōngguó de lìshǐ gùshi.","vi":"Trong cuốn sách này có rất nhiều câu chuyện lịch sử Trung Quốc.","en":"This book has many Chinese historical stories."}]},"来自":{"en":"to come from; to originate from","exs":[{"use":"来自 + nước: đến từ đâu","ex":"我来自越南。","py":"Wǒ láizì Yuènán.","vi":"Tôi đến từ Việt Nam.","en":"I come from Vietnam."},{"use":"N + 来自 + nơi chốn: nguồn gốc","ex":"这些水果来自南方。","py":"Zhèxiē shuǐguǒ láizì nánfāng.","vi":"Những loại trái cây này đến từ miền Nam.","en":"These fruits come from the south."},{"use":"来自…的 + N: làm định ngữ","ex":"来自世界各地的朋友们一起过节。","py":"Láizì shìjiè gèdì de péngyoumen yìqǐ guòjié.","vi":"Bạn bè đến từ khắp nơi trên thế giới cùng nhau đón lễ.","en":"Friends from all over the world celebrate the holiday together."}]},"美国":{"en":"the United States; America","exs":[{"use":"来自美国: đến từ Mỹ","ex":"我的朋友来自美国。","py":"Wǒ de péngyou láizì Měiguó.","vi":"Bạn tôi đến từ Mỹ.","en":"My friend comes from the United States."},{"use":"美国和中国: so sánh hai nước","ex":"美国和中国的时差很大。","py":"Měiguó hé Zhōngguó de shíchā hěn dà.","vi":"Chênh lệch múi giờ giữa Mỹ và Trung Quốc rất lớn.","en":"The time difference between the US and China is large."},{"use":"在美国 + V: ở Mỹ","ex":"他在美国学习了两年。","py":"Tā zài Měiguó xuéxí le liǎng nián.","vi":"Anh ấy đã học ở Mỹ hai năm.","en":"He studied in the United States for two years."},{"use":"去美国 + V: đi Mỹ làm gì","ex":"明年我打算去美国旅游。","py":"Míngnián wǒ dǎsuàn qù Měiguó lǚyóu.","vi":"Sang năm tôi định đi du lịch Mỹ.","en":"Next year I plan to travel to the United States."}]},"留学生":{"en":"international student; student studying abroad","exs":[{"use":"有很多留学生: số lượng","ex":"我们学校有很多留学生。","py":"Wǒmen xuéxiào yǒu hěn duō liúxuéshēng.","vi":"Trường chúng tôi có rất nhiều du học sinh.","en":"Our school has many international students."},{"use":"从…来的留学生: nguồn gốc","ex":"他是从美国来的留学生。","py":"Tā shì cóng Měiguó lái de liúxuéshēng.","vi":"Anh ấy là du học sinh đến từ Mỹ.","en":"He is an international student from the United States."},{"use":"留学生宿舍: ký túc xá du học sinh","ex":"留学生宿舍就在图书馆旁边。","py":"Liúxuéshēng sùshè jiù zài túshūguǎn pángbiān.","vi":"Ký túc xá du học sinh ngay cạnh thư viện.","en":"The international students' dormitory is right next to the library."},{"use":"当留学生: trở thành du học sinh","ex":"她希望将来去中国当留学生。","py":"Tā xīwàng jiānglái qù Zhōngguó dāng liúxuéshēng.","vi":"Cô ấy hy vọng sau này sang Trung Quốc làm du học sinh.","en":"She hopes to study in China as an international student someday."}]},"跟着":{"en":"to follow; to go along with","exs":[{"use":"跟着 + người: đi theo sau","ex":"小狗一直跟着我。","py":"Xiǎo gǒu yìzhí gēnzhe wǒ.","vi":"Con chó nhỏ cứ đi theo tôi mãi.","en":"The puppy keeps following me."},{"use":"跟着 + người + V: làm theo (học theo)","ex":"请跟着老师读。","py":"Qǐng gēnzhe lǎoshī dú.","vi":"Hãy đọc theo thầy giáo.","en":"Please read along with the teacher."},{"use":"跟着导游: đi theo hướng dẫn viên","ex":"我跟着导游参观了博物馆。","py":"Wǒ gēnzhe dǎoyóu cānguān le bówùguǎn.","vi":"Tôi đi theo hướng dẫn viên tham quan bảo tàng.","en":"I followed the guide through the museum."},{"use":"A…，B也跟着…: A làm thì B cũng làm theo","ex":"他一走，大家也跟着走了。","py":"Tā yì zǒu, dàjiā yě gēnzhe zǒu le.","vi":"Anh ấy vừa đi, mọi người cũng đi theo.","en":"As soon as he left, everyone else left too."}]},"偶尔":{"en":"occasionally; once in a while","exs":[{"use":"偶尔 + V: thỉnh thoảng làm","ex":"我偶尔去公园跑步。","py":"Wǒ ǒu'ěr qù gōngyuán pǎobù.","vi":"Tôi thỉnh thoảng ra công viên chạy bộ.","en":"I occasionally go jogging in the park."},{"use":"很少…，偶尔…: đối lập tần suất","ex":"他很少迟到，偶尔会晚几分钟。","py":"Tā hěn shǎo chídào, ǒu'ěr huì wǎn jǐ fēnzhōng.","vi":"Anh ấy hiếm khi đến muộn, thỉnh thoảng chỉ muộn vài phút.","en":"He is rarely late, only occasionally a few minutes."},{"use":"偶尔也 + V: thỉnh thoảng cũng","ex":"我偶尔也想一个人安静一下。","py":"Wǒ ǒu'ěr yě xiǎng yí ge rén ānjìng yíxià.","vi":"Thỉnh thoảng tôi cũng muốn yên tĩnh một mình.","en":"Once in a while I also want some quiet time alone."},{"use":"thời gian + 偶尔 + V","ex":"周末我偶尔做饭。","py":"Zhōumò wǒ ǒu'ěr zuòfàn.","vi":"Cuối tuần thỉnh thoảng tôi nấu cơm.","en":"I occasionally cook on weekends."}]},"吃惊":{"en":"to be surprised; to be startled","exs":[{"use":"很/非常 + 吃惊: ngạc nhiên","ex":"听到这个消息，我非常吃惊。","py":"Tīngdào zhège xiāoxi, wǒ fēicháng chījīng.","vi":"Nghe tin này, tôi vô cùng ngạc nhiên.","en":"I was very surprised to hear this news."},{"use":"大家都很吃惊: chủ ngữ số nhiều","ex":"他的汉语这么好，大家都很吃惊。","py":"Tā de Hànyǔ zhème hǎo, dàjiā dōu hěn chījīng.","vi":"Tiếng Hán của anh ấy giỏi như vậy, mọi người đều rất ngạc nhiên.","en":"His Chinese is so good that everyone was surprised."},{"use":"吃惊地 + V: trạng ngữ","ex":"她吃惊地看着我。","py":"Tā chījīng de kàn zhe wǒ.","vi":"Cô ấy nhìn tôi vẻ ngạc nhiên.","en":"She looked at me in surprise."},{"use":"没什么好吃惊的: không có gì đáng ngạc nhiên","ex":"这没什么好吃惊的。","py":"Zhè méi shénme hǎo chījīng de.","vi":"Chuyện này không có gì đáng ngạc nhiên.","en":"There is nothing surprising about this."},{"use":"让人吃惊: làm người ta ngạc nhiên","ex":"这个结果真让人吃惊。","py":"Zhège jiéguǒ zhēn ràng rén chījīng.","vi":"Kết quả này thật khiến người ta ngạc nhiên.","en":"This result is really surprising."}]},"基础":{"en":"foundation; basis","exs":[{"use":"打好基础: đặt nền tảng","ex":"学汉语要先打好基础。","py":"Xué Hànyǔ yào xiān dǎ hǎo jīchǔ.","vi":"Học tiếng Hán phải đặt nền tảng tốt trước.","en":"To learn Chinese, you must first build a solid foundation."},{"use":"有/没有 + 基础: có/không có nền tảng","ex":"我没有数学基础。","py":"Wǒ méiyǒu shùxué jīchǔ.","vi":"Tôi không có nền tảng toán học.","en":"I have no background in mathematics."},{"use":"是…的基础: là nền tảng của","ex":"词汇是语言学习的基础。","py":"Cíhuì shì yǔyán xuéxí de jīchǔ.","vi":"Từ vựng là nền tảng của việc học ngôn ngữ.","en":"Vocabulary is the foundation of language learning."},{"use":"在…基础上: trên cơ sở","ex":"在这个基础上，我们再努力一下。","py":"Zài zhège jīchǔ shang, wǒmen zài nǔlì yíxià.","vi":"Trên cơ sở này, chúng ta cố gắng thêm một chút.","en":"Building on this foundation, let us work a bit harder."}]},"表演艺术":{"en":"performing arts","exs":[{"use":"学习表演艺术: ngành học","ex":"他在大学学习表演艺术。","py":"Tā zài dàxué xuéxí biǎoyǎn yìshù.","vi":"Anh ấy học nghệ thuật biểu diễn ở trường đại học.","en":"He studies performing arts at university."},{"use":"是一种…表演艺术: giới thiệu","ex":"京剧是一种传统的表演艺术。","py":"Jīngjù shì yì zhǒng chuántǒng de biǎoyǎn yìshù.","vi":"Kinh kịch là một loại hình nghệ thuật biểu diễn truyền thống.","en":"Beijing opera is a traditional performing art."},{"use":"对表演艺术感兴趣","ex":"她从小就对表演艺术很感兴趣。","py":"Tā cóngxiǎo jiù duì biǎoyǎn yìshù hěn gǎn xìngqù.","vi":"Từ nhỏ cô ấy đã rất hứng thú với nghệ thuật biểu diễn.","en":"She has been interested in the performing arts since childhood."},{"use":"表演艺术 + N: học viện, trường","ex":"这座城市有一所有名的表演艺术学校。","py":"Zhè zuò chéngshì yǒu yì suǒ yǒumíng de biǎoyǎn yìshù xuéxiào.","vi":"Thành phố này có một trường nghệ thuật biểu diễn nổi tiếng.","en":"This city has a famous performing arts school."}]},"唱法":{"en":"singing style; vocal technique","exs":[{"use":"美声唱法: phương pháp hát bel canto","ex":"他学过美声唱法。","py":"Tā xué guo měishēng chàngfǎ.","vi":"Anh ấy đã học phương pháp hát mỹ thanh.","en":"He has studied bel canto singing."},{"use":"A 的唱法和 B 不一样: so sánh","ex":"京剧的唱法和流行音乐很不一样。","py":"Jīngjù de chàngfǎ hé liúxíng yīnyuè hěn bù yíyàng.","vi":"Cách hát của Kinh kịch rất khác với nhạc pop.","en":"The singing style of Beijing opera is very different from pop music."},{"use":"正确的唱法: cách hát đúng","ex":"老师在教我们正确的唱法。","py":"Lǎoshī zài jiāo wǒmen zhèngquè de chàngfǎ.","vi":"Thầy giáo đang dạy chúng tôi cách hát đúng.","en":"The teacher is teaching us the correct way to sing."},{"use":"不同的唱法: các cách hát khác nhau","ex":"每个地方的民歌有不同的唱法。","py":"Měi ge dìfang de míngē yǒu bùtóng de chàngfǎ.","vi":"Dân ca mỗi vùng có cách hát khác nhau.","en":"Folk songs from each region have different singing styles."}]},"听不懂":{"en":"cannot understand (what one hears)","exs":[{"use":"V + 不 + 补语: bổ ngữ khả năng phủ định","ex":"他说的是方言，我听不懂。","py":"Tā shuō de shì fāngyán, wǒ tīng bu dǒng.","vi":"Anh ấy nói tiếng địa phương, tôi nghe không hiểu.","en":"He speaks a dialect and I cannot understand it."},{"use":"lịch sự yêu cầu nói lại","ex":"对不起，我听不懂，请再说一遍。","py":"Duìbuqǐ, wǒ tīng bu dǒng, qǐng zài shuō yí biàn.","vi":"Xin lỗi, tôi nghe không hiểu, xin hãy nói lại một lần nữa.","en":"Sorry, I don't understand. Please say it once more."},{"use":"宾语 đảo lên trước: tân ngữ làm chủ đề","ex":"这首歌的歌词我听不懂。","py":"Zhè shǒu gē de gēcí wǒ tīng bu dǒng.","vi":"Lời bài hát này tôi nghe không hiểu.","en":"I can't understand the lyrics of this song."},{"use":"大家都听不懂: chủ ngữ số nhiều","ex":"老师讲得太快，同学们都听不懂。","py":"Lǎoshī jiǎng de tài kuài, tóngxuémen dōu tīng bu dǒng.","vi":"Thầy giảng nhanh quá, các bạn học đều nghe không hiểu.","en":"The teacher spoke too fast and the students could not follow."}]},"流行音乐":{"en":"pop music; popular music","exs":[{"use":"喜欢流行音乐","ex":"年轻人大多喜欢流行音乐。","py":"Niánqīngrén dàduō xǐhuan liúxíng yīnyuè.","vi":"Phần lớn người trẻ thích nhạc pop.","en":"Most young people like pop music."},{"use":"一边…一边…: vừa… vừa nghe nhạc","ex":"我常常一边做饭一边听流行音乐。","py":"Wǒ chángcháng yìbiān zuòfàn yìbiān tīng liúxíng yīnyuè.","vi":"Tôi thường vừa nấu cơm vừa nghe nhạc pop.","en":"I often listen to pop music while cooking."},{"use":"流行音乐 + 歌手: định ngữ","ex":"他是一位有名的流行音乐歌手。","py":"Tā shì yí wèi yǒumíng de liúxíng yīnyuè gēshǒu.","vi":"Anh ấy là một ca sĩ nhạc pop nổi tiếng.","en":"He is a famous pop singer."},{"use":"A 比 B 更…: so sánh","ex":"流行音乐比古典音乐更容易听懂。","py":"Liúxíng yīnyuè bǐ gǔdiǎn yīnyuè gèng róngyì tīngdǒng.","vi":"Nhạc pop dễ nghe hiểu hơn nhạc cổ điển.","en":"Pop music is easier to understand than classical music."}]},"校长":{"en":"principal; headmaster; university president","exs":[{"use":"校长 + V: hiệu trưởng làm gì","ex":"校长在大会上讲了话。","py":"Xiàozhǎng zài dàhuì shang jiǎng le huà.","vi":"Hiệu trưởng phát biểu tại đại hội.","en":"The principal gave a speech at the assembly."},{"use":"我们的校长: nói về hiệu trưởng","ex":"我们的校长很关心学生。","py":"Wǒmen de xiàozhǎng hěn guānxīn xuésheng.","vi":"Hiệu trưởng của chúng tôi rất quan tâm học sinh.","en":"Our principal cares a lot about the students."},{"use":"校长办公室: văn phòng hiệu trưởng","ex":"校长办公室在二楼。","py":"Xiàozhǎng bàngōngshì zài èr lóu.","vi":"Văn phòng hiệu trưởng ở tầng hai.","en":"The principal's office is on the second floor."},{"use":"当上校长: trở thành hiệu trưởng","ex":"他去年当上了校长。","py":"Tā qùnián dāng shàng le xiàozhǎng.","vi":"Năm ngoái ông ấy trở thành hiệu trưởng.","en":"He became the principal last year."}]},"文化":{"en":"culture; civilization; education","exs":[{"use":"对…文化感兴趣","ex":"我对中国文化很感兴趣。","py":"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù.","vi":"Tôi rất hứng thú với văn hóa Trung Quốc.","en":"I am very interested in Chinese culture."},{"use":"不同的文化: sự khác biệt","ex":"不同国家有不同的文化。","py":"Bùtóng guójiā yǒu bùtóng de wénhuà.","vi":"Các nước khác nhau có nền văn hóa khác nhau.","en":"Different countries have different cultures."},{"use":"了解当地文化: tìm hiểu văn hóa địa phương","ex":"旅游可以让我们了解当地文化。","py":"Lǚyóu kěyǐ ràng wǒmen liǎojiě dāngdì wénhuà.","vi":"Du lịch giúp chúng ta hiểu văn hóa địa phương.","en":"Traveling lets us learn about local culture."},{"use":"nghĩa 2: trình độ học vấn (有文化)","ex":"他没有什么文化，但是很聪明。","py":"Tā méiyǒu shénme wénhuà, dànshì hěn cōngming.","vi":"Ông ấy không có học vấn gì nhiều nhưng rất thông minh.","en":"He has little education, but he is very smart."}]},"之间":{"en":"between; among","exs":[{"use":"A 和 B 之间: ở giữa hai vật","ex":"我家在学校和公园之间。","py":"Wǒ jiā zài xuéxiào hé gōngyuán zhījiān.","vi":"Nhà tôi nằm giữa trường học và công viên.","en":"My house is between the school and the park."},{"use":"N（số nhiều）之间: giữa những người","ex":"朋友之间应该互相帮助。","py":"Péngyou zhījiān yīnggāi hùxiāng bāngzhù.","vi":"Giữa bạn bè nên giúp đỡ lẫn nhau.","en":"Friends should help each other."},{"use":"thời gian: 在…到…之间","ex":"他每天在八点到九点之间到公司。","py":"Tā měi tiān zài bā diǎn dào jiǔ diǎn zhījiān dào gōngsī.","vi":"Mỗi ngày anh ấy đến công ty trong khoảng từ tám đến chín giờ.","en":"He arrives at the office between eight and nine every day."},{"use":"两…之间: quan hệ giữa hai bên","ex":"两个国家之间的交流越来越多。","py":"Liǎng ge guójiā zhījiān de jiāoliú yuè lái yuè duō.","vi":"Giao lưu giữa hai nước ngày càng nhiều.","en":"Exchanges between the two countries are increasing."}]},"正常":{"en":"normal; regular","exs":[{"use":"很正常: nhận xét bình thường","ex":"他的体温很正常。","py":"Tā de tǐwēn hěn zhèngcháng.","vi":"Nhiệt độ cơ thể của anh ấy rất bình thường.","en":"His body temperature is normal."},{"use":"正常 + V: phó từ, đúng như bình thường","ex":"今天火车正常出发。","py":"Jīntiān huǒchē zhèngcháng chūfā.","vi":"Hôm nay tàu xuất phát bình thường.","en":"The train departs as normal today."},{"use":"恢复正常: trở lại bình thường","ex":"网络恢复正常了。","py":"Wǎngluò huīfù zhèngcháng le.","vi":"Mạng đã hoạt động bình thường trở lại.","en":"The network is back to normal."},{"use":"这很正常: an ủi","ex":"这很正常，不用担心。","py":"Zhè hěn zhèngcháng, bú yòng dānxīn.","vi":"Chuyện này rất bình thường, đừng lo.","en":"This is quite normal; don't worry."}]},"申请":{"en":"to apply for; application","exs":[{"use":"申请 + N: xin cái gì","ex":"我想申请奖学金。","py":"Wǒ xiǎng shēnqǐng jiǎngxuéjīn.","vi":"Tôi muốn xin học bổng.","en":"I want to apply for a scholarship."},{"use":"申请 + trường/ công ty","ex":"他申请了一所美国大学。","py":"Tā shēnqǐng le yì suǒ Měiguó dàxué.","vi":"Anh ấy đã nộp đơn vào một trường đại học Mỹ.","en":"He applied to an American university."},{"use":"danh từ: 申请表 (đơn xin)","ex":"请先填写申请表。","py":"Qǐng xiān tiánxiě shēnqǐng biǎo.","vi":"Vui lòng điền vào đơn đăng ký trước.","en":"Please fill out the application form first."},{"use":"申请签证: xin visa","ex":"申请签证需要很多材料。","py":"Shēnqǐng qiānzhèng xūyào hěn duō cáiliào.","vi":"Xin visa cần rất nhiều giấy tờ.","en":"Applying for a visa requires many documents."}]},"传统":{"en":"tradition; traditional","exs":[{"use":"danh từ: truyền thống","ex":"春节吃饺子是中国的传统。","py":"Chūnjié chī jiǎozi shì Zhōngguó de chuántǒng.","vi":"Ăn sủi cảo vào Tết là truyền thống của Trung Quốc.","en":"Eating dumplings at Spring Festival is a Chinese tradition."},{"use":"tính từ: 传统的 + N","ex":"她穿着一件传统的中式衣服。","py":"Tā chuān zhe yí jiàn chuántǒng de Zhōngshì yīfu.","vi":"Cô ấy mặc một bộ trang phục kiểu Trung Hoa truyền thống.","en":"She is wearing a traditional Chinese-style outfit."},{"use":"保持传统: giữ gìn truyền thống","ex":"我们要保持尊老爱幼的传统。","py":"Wǒmen yào bǎochí zūnlǎo àiyòu de chuántǒng.","vi":"Chúng ta phải giữ gìn truyền thống kính già yêu trẻ.","en":"We must keep the tradition of respecting the old and loving the young."},{"use":"传统文化: văn hóa truyền thống","ex":"很多年轻人开始喜欢传统文化。","py":"Hěn duō niánqīngrén kāishǐ xǐhuan chuántǒng wénhuà.","vi":"Nhiều người trẻ bắt đầu yêu thích văn hóa truyền thống.","en":"Many young people are starting to like traditional culture."}]},"文化节":{"en":"cultural festival","exs":[{"use":"举行文化节: tổ chức lễ hội","ex":"学校下个月举行文化节。","py":"Xuéxiào xià ge yuè jǔxíng wénhuàjié.","vi":"Tháng sau trường tổ chức lễ hội văn hóa.","en":"The school will hold a cultural festival next month."},{"use":"在文化节上: tại lễ hội","ex":"在文化节上，各国留学生表演了节目。","py":"Zài wénhuàjié shang, gèguó liúxuéshēng biǎoyǎn le jiémù.","vi":"Tại lễ hội văn hóa, du học sinh các nước đã biểu diễn tiết mục.","en":"At the cultural festival, students from many countries performed."},{"use":"参加文化节: tham gia","ex":"我报名参加了这次文化节。","py":"Wǒ bàomíng cānjiā le zhè cì wénhuàjié.","vi":"Tôi đã đăng ký tham gia lễ hội văn hóa lần này.","en":"I signed up to take part in this cultural festival."},{"use":"文化节的活动: hoạt động","ex":"文化节的活动很丰富。","py":"Wénhuàjié de huódòng hěn fēngfù.","vi":"Các hoạt động của lễ hội văn hóa rất phong phú.","en":"The activities at the cultural festival are very rich."}]},"一方面":{"en":"on the one hand; for one thing","exs":[{"use":"一方面…，另一方面…: cặp đối lập","ex":"一方面他工作很忙，另一方面还要照顾孩子。","py":"Yì fāngmiàn tā gōngzuò hěn máng, lìng yì fāngmiàn hái yào zhàogù háizi.","vi":"Một mặt anh ấy công việc rất bận, mặt khác còn phải chăm con.","en":"On the one hand he is busy with work, and on the other he has to look after his child."},{"use":"一方面…，一方面…: hai việc song song","ex":"一方面要努力学习，一方面也要注意休息。","py":"Yì fāngmiàn yào nǔlì xuéxí, yì fāngmiàn yě yào zhùyì xiūxi.","vi":"Một mặt phải cố gắng học, một mặt cũng phải chú ý nghỉ ngơi.","en":"You should study hard and also take care to rest."},{"use":"一方面…，一方面…: nêu nhiều lý do","ex":"我不想买这个手机，一方面太贵，一方面功能也不多。","py":"Wǒ bù xiǎng mǎi zhège shǒujī, yì fāngmiàn tài guì, yì fāngmiàn gōngnéng yě bù duō.","vi":"Tôi không muốn mua chiếc điện thoại này, một mặt vì đắt, mặt khác chức năng cũng không nhiều.","en":"I don't want this phone: for one thing it is too expensive, and for another it has few features."},{"use":"是为了…: nêu nguyên nhân","ex":"他学汉语，一方面是为了工作，另一方面是因为喜欢。","py":"Tā xué Hànyǔ, yì fāngmiàn shì wèile gōngzuò, lìng yì fāngmiàn shì yīnwèi xǐhuan.","vi":"Anh ấy học tiếng Hán, một mặt vì công việc, mặt khác vì yêu thích.","en":"He studies Chinese partly for work and partly because he likes it."}]},"各国":{"en":"each country; various countries","exs":[{"use":"各国 + 的 + N: các nước","ex":"各国的游客都来参观。","py":"Gèguó de yóukè dōu lái cānguān.","vi":"Du khách từ các nước đều đến tham quan.","en":"Tourists from various countries all come to visit."},{"use":"世界各国: các nước trên thế giới","ex":"世界各国都在发展经济。","py":"Shìjiè gèguó dōu zài fāzhǎn jīngjì.","vi":"Các nước trên thế giới đều đang phát triển kinh tế.","en":"Countries around the world are developing their economies."},{"use":"有各国的 + N: đồ ăn các nước","ex":"文化节上有各国的美食。","py":"Wénhuàjié shang yǒu gèguó de měishí.","vi":"Ở lễ hội văn hóa có ẩm thực của các nước.","en":"There is food from many countries at the cultural festival."},{"use":"各国 + 人民: nhân dân các nước","ex":"各国人民都希望和平。","py":"Gèguó rénmín dōu xīwàng hépíng.","vi":"Nhân dân các nước đều mong muốn hòa bình.","en":"People of all nations hope for peace."}]},"另一方面":{"en":"on the other hand","exs":[{"use":"…，另一方面，…: nối vế thứ hai","ex":"住在城市很方便，另一方面，生活压力也比较大。","py":"Zhù zài chéngshì hěn fāngbiàn, lìng yì fāngmiàn, shēnghuó yālì yě bǐjiào dà.","vi":"Sống ở thành phố rất tiện, mặt khác áp lực cuộc sống cũng khá lớn.","en":"Living in a city is convenient; on the other hand, the pressure of life is greater."},{"use":"另一方面 chỉ ra mặt trái","ex":"网络让我们的生活更方便，另一方面，也带来了一些问题。","py":"Wǎngluò ràng wǒmen de shēnghuó gèng fāngbiàn, lìng yì fāngmiàn, yě dàilái le yìxiē wèntí.","vi":"Mạng làm cuộc sống tiện hơn, mặt khác cũng mang đến một số vấn đề.","en":"The Internet makes life more convenient, but on the other hand it has brought some problems."},{"use":"另一方面 đứng đầu câu: bổ sung ý","ex":"另一方面，我们也要考虑时间。","py":"Lìng yì fāngmiàn, wǒmen yě yào kǎolǜ shíjiān.","vi":"Mặt khác, chúng ta cũng phải cân nhắc thời gian.","en":"On the other hand, we also have to consider time."}]},"春游":{"en":"spring outing; to go on a spring outing","exs":[{"use":"động từ: đi chơi xuân, dã ngoại","ex":"我们班下周去公园春游。","py":"Wǒmen bān xià zhōu qù gōngyuán chūnyóu.","vi":"Lớp chúng tôi tuần sau đi công viên dã ngoại mùa xuân.","en":"Our class is going on a spring outing to the park next week."},{"use":"春游 + 的时候: khi đi dã ngoại","ex":"春游的时候，孩子们都很兴奋。","py":"Chūnyóu de shíhou, háizimen dōu hěn xīngfèn.","vi":"Khi đi dã ngoại mùa xuân, bọn trẻ đều rất phấn khích.","en":"On the spring outing, the children were all very excited."},{"use":"làm danh từ: chuyến dã ngoại mùa xuân","ex":"这次春游，老师带我们爬山。","py":"Zhè cì chūnyóu, lǎoshī dài wǒmen pá shān.","vi":"Chuyến dã ngoại xuân lần này, thầy giáo dẫn chúng tôi đi leo núi.","en":"On this spring outing, the teacher took us hiking."},{"use":"去春游 + 吧: rủ rê, đề nghị","ex":"天气这么好，我们一起去春游吧！","py":"Tiānqì zhème hǎo, wǒmen yìqǐ qù chūnyóu ba!","vi":"Thời tiết đẹp thế này, chúng ta cùng đi dã ngoại xuân nhé!","en":"The weather is so nice, let's go on a spring outing together!"}]},"有趣":{"en":"interesting; fun; amusing","exs":[{"use":"làm vị ngữ: hěn + 有趣","ex":"这本书很有趣，我一口气看完了。","py":"Zhè běn shū hěn yǒuqù, wǒ yìkǒuqì kànwán le.","vi":"Cuốn sách này rất thú vị, tôi đọc một mạch hết luôn.","en":"This book is very interesting; I finished it in one sitting."},{"use":"làm định ngữ: 有趣 + 的 + danh từ (người)","ex":"他是一个很有趣的人。","py":"Tā shì yí ge hěn yǒuqù de rén.","vi":"Anh ấy là một người rất thú vị.","en":"He is a very interesting person."},{"use":"觉得 + ... + 有趣: cảm thấy thú vị","ex":"我觉得学汉语很有趣。","py":"Wǒ juéde xué Hànyǔ hěn yǒuqù.","vi":"Tôi thấy học tiếng Trung rất thú vị.","en":"I find learning Chinese very interesting."},{"use":"有趣的事: những chuyện thú vị","ex":"旅行中发生了很多有趣的事。","py":"Lǚxíng zhōng fāshēng le hěn duō yǒuqù de shì.","vi":"Trong chuyến du lịch đã xảy ra rất nhiều chuyện thú vị.","en":"Many interesting things happened during the trip."}]},"玩儿":{"en":"to play; to have fun; to hang out","exs":[{"use":"玩儿 + địa điểm: đi chơi ở đâu","ex":"周末我们去海边玩儿吧。","py":"Zhōumò wǒmen qù hǎibiān wánr ba.","vi":"Cuối tuần chúng ta ra bờ biển chơi nhé.","en":"Let's go to the seaside to have fun this weekend."},{"use":"玩儿 + tân ngữ: chơi cái gì","ex":"孩子们在院子里玩儿游戏。","py":"Háizimen zài yuànzi lǐ wánr yóuxì.","vi":"Bọn trẻ đang chơi trò chơi trong sân.","en":"The children are playing games in the yard."},{"use":"V + 得 + adj: bổ ngữ trạng thái","ex":"我们在北京玩儿得很开心。","py":"Wǒmen zài Běijīng wánr de hěn kāixīn.","vi":"Chúng tôi chơi ở Bắc Kinh rất vui.","en":"We had a great time in Beijing."},{"use":"好玩儿: thú vị, vui (tính từ)","ex":"这个公园不大，但是很好玩儿。","py":"Zhège gōngyuán bú dà, dànshì hěn hǎowánr.","vi":"Công viên này không lớn nhưng rất vui.","en":"This park isn't big, but it's a lot of fun."},{"use":"玩儿手机: nghịch, chơi điện thoại","ex":"别总玩儿手机，对眼睛不好。","py":"Bié zǒng wánr shǒujī, duì yǎnjing bù hǎo.","vi":"Đừng cứ chơi điện thoại mãi, không tốt cho mắt.","en":"Don't always play on your phone; it's bad for your eyes."}]},"开心":{"en":"happy; cheerful; delighted","exs":[{"use":"làm vị ngữ: 特别/很 + 开心","ex":"今天见到老朋友，我特别开心。","py":"Jīntiān jiàndào lǎo péngyou, wǒ tèbié kāixīn.","vi":"Hôm nay gặp lại bạn cũ, tôi đặc biệt vui.","en":"I'm especially happy to see an old friend today."},{"use":"开心地 + V: làm trạng ngữ","ex":"孩子们开心地唱着歌。","py":"Háizimen kāixīn de chàngzhe gē.","vi":"Bọn trẻ vui vẻ hát.","en":"The children are singing happily."},{"use":"让/使 + người + 开心: làm ai vui","ex":"你的礼物让妈妈很开心。","py":"Nǐ de lǐwù ràng māma hěn kāixīn.","vi":"Món quà của bạn làm mẹ rất vui.","en":"Your gift made Mom very happy."},{"use":"lời chúc: 祝你 + 开心","ex":"祝你每天都开心！","py":"Zhù nǐ měi tiān dōu kāixīn!","vi":"Chúc bạn ngày nào cũng vui vẻ!","en":"Wishing you happiness every day!"}]},"继续":{"en":"to continue; to go on","exs":[{"use":"继续 + động từ: tiếp tục làm gì","ex":"休息一会儿，我们再继续工作。","py":"Xiūxi yíhuìr, wǒmen zài jìxù gōngzuò.","vi":"Nghỉ một lát rồi chúng ta lại tiếp tục làm việc.","en":"Let's take a short break and then continue working."},{"use":"继续 + V + 下去: cứ tiếp tục","ex":"不管多难，你都要继续学下去。","py":"Bùguǎn duō nán, nǐ dōu yào jìxù xué xiàqù.","vi":"Dù khó đến đâu, bạn cũng phải tiếp tục học.","en":"No matter how hard it is, you must keep on studying."},{"use":"làm vị ngữ độc lập: sự việc tiếp diễn","ex":"雨停了，比赛继续。","py":"Yǔ tíng le, bǐsài jìxù.","vi":"Mưa tạnh rồi, trận đấu tiếp tục.","en":"The rain stopped, and the match continued."},{"use":"继续 + 留/住 + ...: tiếp tục ở lại","ex":"他决定继续留在这家公司。","py":"Tā juédìng jìxù liú zài zhè jiā gōngsī.","vi":"Anh ấy quyết định tiếp tục ở lại công ty này.","en":"He decided to stay on at this company."}]},"回去":{"en":"to go back; to return","exs":[{"use":"回去 đứng một mình: về (nơi xuất phát)","ex":"太晚了，我该回去了。","py":"Tài wǎn le, wǒ gāi huíqù le.","vi":"Muộn quá rồi, tôi phải về đây.","en":"It's too late; I should head back."},{"use":"回去 + 以后 + ...: sau khi quay về","ex":"回去以后给我打个电话。","py":"Huíqù yǐhòu gěi wǒ dǎ ge diànhuà.","vi":"Về rồi thì gọi điện cho tôi nhé.","en":"Give me a call after you get back."},{"use":"V + 回去: bổ ngữ xu hướng (mang về)","ex":"你把这本书带回去看吧。","py":"Nǐ bǎ zhè běn shū dài huíqù kàn ba.","vi":"Bạn mang cuốn sách này về xem đi.","en":"Take this book back with you and read it."},{"use":"走回去: đi bộ quay về","ex":"地铁停了，我们只能走回去。","py":"Dìtiě tíng le, wǒmen zhǐ néng zǒu huíqù.","vi":"Tàu điện ngầm dừng rồi, chúng ta chỉ có thể đi bộ về.","en":"The subway has stopped, so we can only walk back."}]},"星期五":{"en":"Friday","exs":[{"use":"星期五 + thời gian trong ngày: trạng ngữ thời gian","ex":"星期五晚上我们去看电影。","py":"Xīngqīwǔ wǎnshang wǒmen qù kàn diànyǐng.","vi":"Tối thứ Sáu chúng tôi đi xem phim.","en":"We're going to see a movie on Friday evening."},{"use":"是 + 星期五: làm vị ngữ danh từ","ex":"明天是星期五，后天就是周末了。","py":"Míngtiān shì xīngqīwǔ, hòutiān jiù shì zhōumò le.","vi":"Ngày mai là thứ Sáu, ngày kia là cuối tuần rồi.","en":"Tomorrow is Friday, and the day after is the weekend."},{"use":"每个星期五: lặp lại hằng tuần","ex":"我每个星期五都去游泳。","py":"Wǒ měi ge xīngqīwǔ dōu qù yóuyǒng.","vi":"Thứ Sáu nào tôi cũng đi bơi.","en":"I go swimming every Friday."},{"use":"下星期五: thứ Sáu tuần sau","ex":"这份报告请在下星期五以前交给我。","py":"Zhè fèn bàogào qǐng zài xià xīngqīwǔ yǐqián jiāo gěi wǒ.","vi":"Bản báo cáo này xin nộp cho tôi trước thứ Sáu tuần sau.","en":"Please hand this report to me before next Friday."}]},"计划书":{"en":"written plan; proposal","exs":[{"use":"计划书 làm tân ngữ của 写","ex":"我正在写旅行计划书。","py":"Wǒ zhèngzài xiě lǚxíng jìhuàshū.","vi":"Tôi đang viết bản kế hoạch du lịch.","en":"I'm writing a travel plan."},{"use":"把 + 计划书 + 发/交: câu chữ 把","ex":"请把计划书发到我的邮箱。","py":"Qǐng bǎ jìhuàshū fā dào wǒ de yóuxiāng.","vi":"Xin gửi bản kế hoạch vào hộp thư của tôi.","en":"Please send the plan to my email."},{"use":"làm tân ngữ của 看: xem/đọc bản kế hoạch","ex":"经理看了计划书，觉得很不错。","py":"Jīnglǐ kàn le jìhuàshū, juéde hěn búcuò.","vi":"Giám đốc xem bản kế hoạch xong thấy rất tốt.","en":"The manager read the proposal and thought it was pretty good."},{"use":"量词 份 + 计划书","ex":"这份计划书需要修改一下。","py":"Zhè fèn jìhuàshū xūyào xiūgǎi yíxià.","vi":"Bản kế hoạch này cần sửa lại một chút.","en":"This proposal needs a bit of revision."}]},"塑料袋":{"en":"plastic bag","exs":[{"use":"塑料袋 + 的钱: tiền túi nhựa","ex":"超市里买东西要付塑料袋的钱。","py":"Chāoshì lǐ mǎi dōngxi yào fù sùliàodài de qián.","vi":"Mua đồ trong siêu thị phải trả tiền túi nhựa.","en":"You have to pay for plastic bags when shopping at the supermarket."},{"use":"làm chủ ngữ, nói về tác hại môi trường","ex":"塑料袋不容易分解，会污染环境。","py":"Sùliàodài bù róngyì fēnjiě, huì wūrǎn huánjìng.","vi":"Túi nhựa khó phân hủy, sẽ gây ô nhiễm môi trường.","en":"Plastic bags don't break down easily and pollute the environment."},{"use":"少用 + 塑料袋: kêu gọi giảm dùng","ex":"我们应该少用塑料袋。","py":"Wǒmen yīnggāi shǎo yòng sùliàodài.","vi":"Chúng ta nên dùng ít túi nhựa.","en":"We should use fewer plastic bags."},{"use":"量词 个 + 塑料袋: xin một cái túi","ex":"请给我一个塑料袋，谢谢。","py":"Qǐng gěi wǒ yí ge sùliàodài, xièxie.","vi":"Làm ơn cho tôi một cái túi nhựa, cảm ơn.","en":"Could I have a plastic bag, please?"}]},"大量":{"en":"a large amount of; large-scale; in large quantities","exs":[{"use":"大量 + 的 + danh từ: làm định ngữ","ex":"工厂排放了大量的废水。","py":"Gōngchǎng páifàng le dàliàng de fèishuǐ.","vi":"Nhà máy đã thải ra một lượng lớn nước thải.","en":"The factory discharged a large amount of wastewater."},{"use":"大量 + danh từ (bỏ 的)","ex":"他读了大量中文书，所以汉语很好。","py":"Tā dú le dàliàng Zhōngwén shū, suǒyǐ Hànyǔ hěn hǎo.","vi":"Anh ấy đã đọc rất nhiều sách tiếng Trung nên tiếng Trung rất giỏi.","en":"He has read a lot of Chinese books, so his Chinese is very good."},{"use":"làm trạng ngữ: 大量 + V","ex":"夏天大量喝水对身体有好处。","py":"Xiàtiān dàliàng hē shuǐ duì shēntǐ yǒu hǎochù.","vi":"Mùa hè uống nhiều nước có lợi cho sức khỏe.","en":"Drinking lots of water in summer is good for your health."},{"use":"花大量的时间/精力","ex":"学外语需要花大量的时间。","py":"Xué wàiyǔ xūyào huā dàliàng de shíjiān.","vi":"Học ngoại ngữ cần bỏ ra rất nhiều thời gian.","en":"Learning a foreign language takes a great deal of time."}]},"环境污染":{"en":"environmental pollution","exs":[{"use":"làm chủ ngữ: 环境污染 + 越来越严重","ex":"环境污染越来越严重。","py":"Huánjìng wūrǎn yuè lái yuè yánzhòng.","vi":"Ô nhiễm môi trường ngày càng nghiêm trọng.","en":"Environmental pollution is getting worse and worse."},{"use":"造成 + 环境污染: gây ra","ex":"汽车太多会造成环境污染。","py":"Qìchē tài duō huì zàochéng huánjìng wūrǎn.","vi":"Xe hơi quá nhiều sẽ gây ô nhiễm môi trường.","en":"Too many cars can cause environmental pollution."},{"use":"减少 + 环境污染: làm tân ngữ","ex":"我们要想办法减少环境污染。","py":"Wǒmen yào xiǎng bànfǎ jiǎnshǎo huánjìng wūrǎn.","vi":"Chúng ta phải nghĩ cách giảm ô nhiễm môi trường.","en":"We need to find ways to reduce environmental pollution."},{"use":"环境污染 + 是 + ... 问题","ex":"环境污染是全世界都关心的问题。","py":"Huánjìng wūrǎn shì quán shìjiè dōu guānxīn de wèntí.","vi":"Ô nhiễm môi trường là vấn đề cả thế giới quan tâm.","en":"Environmental pollution is a problem the whole world cares about."}]},"鼓励":{"en":"to encourage; encouragement","exs":[{"use":"鼓励 + người + V: khuyến khích ai làm gì","ex":"老师鼓励我们多说汉语。","py":"Lǎoshī gǔlì wǒmen duō shuō Hànyǔ.","vi":"Thầy giáo khuyến khích chúng tôi nói tiếng Trung nhiều hơn.","en":"The teacher encourages us to speak more Chinese."},{"use":"làm danh từ: 受到/得到 + 鼓励","ex":"听到大家的话，我受到了很大的鼓励。","py":"Tīngdào dàjiā de huà, wǒ shòudào le hěn dà de gǔlì.","vi":"Nghe lời mọi người nói, tôi được khích lệ rất nhiều.","en":"Hearing everyone's words gave me great encouragement."},{"use":"互相鼓励: động viên lẫn nhau","ex":"我们互相鼓励，一起努力学习。","py":"Wǒmen hùxiāng gǔlì, yìqǐ nǔlì xuéxí.","vi":"Chúng tôi động viên lẫn nhau, cùng cố gắng học tập.","en":"We encourage each other and study hard together."},{"use":"鼓励 + tân ngữ (đối lập với 批评)","ex":"父母应该鼓励孩子，而不是批评他。","py":"Fùmǔ yīnggāi gǔlì háizi, ér búshì pīpíng tā.","vi":"Cha mẹ nên khích lệ con chứ không phải chê trách con.","en":"Parents should encourage their children rather than criticize them."}]},"购物袋":{"en":"shopping bag; reusable bag","exs":[{"use":"带 + 购物袋: mang túi đi mua sắm","ex":"去超市最好自己带购物袋。","py":"Qù chāoshì zuìhǎo zìjǐ dài gòuwùdài.","vi":"Đi siêu thị tốt nhất nên tự mang túi mua sắm.","en":"It's best to bring your own shopping bag to the supermarket."},{"use":"可以用很多次: túi dùng lại","ex":"这个购物袋可以用很多次。","py":"Zhège gòuwùdài kěyǐ yòng hěn duō cì.","vi":"Cái túi mua sắm này có thể dùng nhiều lần.","en":"This shopping bag can be used many times."},{"use":"漂亮的购物袋: làm tân ngữ của 有","ex":"我妈妈有好几个漂亮的购物袋。","py":"Wǒ māma yǒu hǎo jǐ ge piàoliang de gòuwùdài.","vi":"Mẹ tôi có mấy cái túi mua sắm rất đẹp.","en":"My mother has several nice shopping bags."},{"use":"忘了带...只好买: quên mang nên đành mua","ex":"他忘了带购物袋，只好买了一个。","py":"Tā wàng le dài gòuwùdài, zhǐhǎo mǎi le yí ge.","vi":"Anh ấy quên mang túi mua sắm nên đành mua một cái.","en":"He forgot his shopping bag, so he had to buy one."}]},"责任":{"en":"responsibility; duty; blame","exs":[{"use":"是 + ... + 的责任: là trách nhiệm của ai","ex":"保护孩子是父母的责任。","py":"Bǎohù háizi shì fùmǔ de zérèn.","vi":"Bảo vệ con cái là trách nhiệm của cha mẹ.","en":"Protecting children is the parents' responsibility."},{"use":"有责任: có lỗi, phải chịu trách nhiệm","ex":"这件事我有责任，对不起。","py":"Zhè jiàn shì wǒ yǒu zérèn, duìbuqǐ.","vi":"Việc này tôi có trách nhiệm, xin lỗi.","en":"I'm partly to blame for this; I'm sorry."},{"use":"责任心: tinh thần trách nhiệm","ex":"老板喜欢有责任心的员工。","py":"Lǎobǎn xǐhuan yǒu zérènxīn de yuángōng.","vi":"Ông chủ thích nhân viên có tinh thần trách nhiệm.","en":"The boss likes employees with a sense of responsibility."},{"use":"承担责任: gánh vác trách nhiệm","ex":"出了问题，我们要一起承担责任。","py":"Chū le wèntí, wǒmen yào yìqǐ chéngdān zérèn.","vi":"Có vấn đề thì chúng ta cùng chịu trách nhiệm.","en":"If something goes wrong, we will take responsibility together."}]},"自备":{"en":"to bring one's own; to provide oneself","exs":[{"use":"请自备 + danh từ: thông báo yêu cầu tự mang","ex":"请自备午饭和水。","py":"Qǐng zìbèi wǔfàn hé shuǐ.","vi":"Xin tự mang theo cơm trưa và nước.","en":"Please bring your own lunch and water."},{"use":"要求 + người + 自备 + ...","ex":"超市要求顾客自备购物袋。","py":"Chāoshì yāoqiú gùkè zìbèi gòuwùdài.","vi":"Siêu thị yêu cầu khách hàng tự mang túi mua sắm.","en":"The supermarket asks customers to bring their own shopping bags."},{"use":"请自备 + nhiều thứ (liệt kê)","ex":"游泳请自备泳衣和毛巾。","py":"Yóuyǒng qǐng zìbèi yǒngyī hé máojīn.","vi":"Khi bơi xin tự mang đồ bơi và khăn.","en":"For swimming, please bring your own swimsuit and towel."},{"use":"需要自备 + danh từ","ex":"这个活动需要自备工具。","py":"Zhège huódòng xūyào zìbèi gōngjù.","vi":"Hoạt động này cần tự chuẩn bị dụng cụ.","en":"This activity requires you to bring your own tools."}]},"拒绝":{"en":"to refuse; to decline; refusal","exs":[{"use":"拒绝 + danh từ: từ chối cái gì","ex":"他拒绝了我的邀请。","py":"Tā jùjué le wǒ de yāoqǐng.","vi":"Anh ấy đã từ chối lời mời của tôi.","en":"He declined my invitation."},{"use":"拒绝 + động từ: từ chối làm gì","ex":"她拒绝接受这份礼物。","py":"Tā jùjué jiēshòu zhè fèn lǐwù.","vi":"Cô ấy từ chối nhận món quà này.","en":"She refused to accept this gift."},{"use":"不好意思 + 拒绝: ngại từ chối","ex":"朋友请客，我不好意思拒绝。","py":"Péngyou qǐngkè, wǒ bù hǎoyìsi jùjué.","vi":"Bạn mời, tôi ngại không từ chối được.","en":"My friend is treating me, so I feel awkward declining."},{"use":"làm danh từ: sự từ chối","ex":"面对拒绝，不要放弃。","py":"Miànduì jùjué, búyào fàngqì.","vi":"Đối mặt với sự từ chối, đừng bỏ cuộc.","en":"When facing rejection, don't give up."}]},"减少":{"en":"to reduce; to decrease; to cut down","exs":[{"use":"减少 + danh từ: giảm cái gì","ex":"多运动可以减少生病的机会。","py":"Duō yùndòng kěyǐ jiǎnshǎo shēngbìng de jīhuì.","vi":"Vận động nhiều có thể giảm khả năng bị bệnh.","en":"Exercising more can reduce your chances of getting sick."},{"use":"减少 + 用 + ...: giảm việc dùng","ex":"我们要减少用塑料袋。","py":"Wǒmen yào jiǎnshǎo yòng sùliàodài.","vi":"Chúng ta phải giảm việc dùng túi nhựa.","en":"We should cut down on using plastic bags."},{"use":"làm vị ngữ nội động: 在 + 减少","ex":"这个城市的人口在减少。","py":"Zhège chéngshì de rénkǒu zài jiǎnshǎo.","vi":"Dân số của thành phố này đang giảm.","en":"The population of this city is decreasing."},{"use":"把...减少到...: giảm xuống mức","ex":"他把每天看手机的时间减少到一个小时。","py":"Tā bǎ měi tiān kàn shǒujī de shíjiān jiǎnshǎo dào yí ge xiǎoshí.","vi":"Anh ấy giảm thời gian xem điện thoại mỗi ngày xuống còn một tiếng.","en":"He cut his daily phone time down to one hour."}]},"地球":{"en":"the Earth; the globe","exs":[{"use":"là + ...: Trái Đất là ngôi nhà chung","ex":"地球是我们共同的家。","py":"Dìqiú shì wǒmen gòngtóng de jiā.","vi":"Trái Đất là ngôi nhà chung của chúng ta.","en":"The Earth is our shared home."},{"use":"保护 + 地球: làm tân ngữ","ex":"每个人都应该保护地球。","py":"Měi ge rén dōu yīnggāi bǎohù dìqiú.","vi":"Mỗi người đều nên bảo vệ Trái Đất.","en":"Everyone should protect the Earth."},{"use":"地球上: trên Trái Đất","ex":"地球上有七十多亿人。","py":"Dìqiú shàng yǒu qīshí duō yì rén.","vi":"Trên Trái Đất có hơn bảy tỷ người.","en":"There are over seven billion people on Earth."},{"use":"làm chủ ngữ: 地球 + 围着 ... 转","ex":"地球围着太阳转。","py":"Dìqiú wéizhe tàiyáng zhuàn.","vi":"Trái Đất quay quanh Mặt Trời.","en":"The Earth revolves around the Sun."}]},"空调":{"en":"air conditioner; air conditioning","exs":[{"use":"打开/开 + 空调: bật điều hòa","ex":"天太热了，快把空调打开吧。","py":"Tiān tài rè le, kuài bǎ kōngtiáo dǎkāi ba.","vi":"Trời nóng quá, mau bật điều hòa lên đi.","en":"It's too hot; hurry and turn on the air conditioner."},{"use":"空调 + 坏了: hỏng, cần sửa","ex":"房间里的空调坏了，请人来修一下。","py":"Fángjiān lǐ de kōngtiáo huài le, qǐng rén lái xiū yíxià.","vi":"Điều hòa trong phòng hỏng rồi, hãy nhờ người đến sửa.","en":"The air conditioner in the room is broken; have someone fix it."},{"use":"空调 + 开得 + adj: bổ ngữ trạng thái","ex":"夏天空调不要开得太冷。","py":"Xiàtiān kōngtiáo bú yào kāi de tài lěng.","vi":"Mùa hè đừng bật điều hòa lạnh quá.","en":"Don't set the air conditioner too cold in summer."},{"use":"关 + 空调: tắt điều hòa","ex":"出门的时候别忘了关空调。","py":"Chūmén de shíhou bié wàng le guān kōngtiáo.","vi":"Lúc ra khỏi nhà đừng quên tắt điều hòa.","en":"Don't forget to turn off the air conditioner when you go out."}]},"用电":{"en":"to use electricity; electricity consumption","exs":[{"use":"节约用电: tiết kiệm điện","ex":"我们要节约用电。","py":"Wǒmen yào jiéyuē yòngdiàn.","vi":"Chúng ta phải tiết kiệm điện.","en":"We should save electricity."},{"use":"用电 + 太多: dùng nhiều điện","ex":"这个月我家用电太多，电费很高。","py":"Zhège yuè wǒ jiā yòngdiàn tài duō, diànfèi hěn gāo.","vi":"Tháng này nhà tôi dùng điện quá nhiều, tiền điện rất cao.","en":"My family used too much electricity this month, so the bill is high."},{"use":"用电的时候: khi dùng điện","ex":"孩子用电的时候要注意安全。","py":"Háizi yòngdiàn de shíhou yào zhùyì ānquán.","vi":"Trẻ em khi dùng điện phải chú ý an toàn.","en":"Children must be careful about safety when using electricity."},{"use":"夏天用电: danh từ hóa, chỉ lượng điện dùng","ex":"夏天用电的人特别多。","py":"Xiàtiān yòngdiàn de rén tèbié duō.","vi":"Mùa hè có đặc biệt nhiều người dùng điện.","en":"In summer, especially many people are using electricity."}]},"骑车":{"en":"to ride a bike; cycling","exs":[{"use":"骑车 + 去: đi (bằng xe đạp)","ex":"我每天骑车去学校。","py":"Wǒ měi tiān qíchē qù xuéxiào.","vi":"Mỗi ngày tôi đạp xe đến trường.","en":"I ride my bike to school every day."},{"use":"làm chủ ngữ: 骑车 既...又...","ex":"骑车既环保又锻炼身体。","py":"Qíchē jì huánbǎo yòu duànliàn shēntǐ.","vi":"Đạp xe vừa bảo vệ môi trường vừa rèn luyện sức khỏe.","en":"Cycling is both eco-friendly and good exercise."},{"use":"从...骑车到...: nêu thời gian","ex":"从我家骑车到公司只要十分钟。","py":"Cóng wǒ jiā qíchē dào gōngsī zhǐ yào shí fēnzhōng.","vi":"Từ nhà tôi đạp xe đến công ty chỉ mất mười phút.","en":"It takes just ten minutes to bike from my home to the company."},{"use":"骑车的时候: khi đạp xe","ex":"骑车的时候要注意安全。","py":"Qíchē de shíhou yào zhùyì ānquán.","vi":"Khi đạp xe phải chú ý an toàn.","en":"Be careful about safety when riding a bike."}]},"乘坐":{"en":"to ride; to travel by (a vehicle)","exs":[{"use":"乘坐 + phương tiện: đi bằng","ex":"我们乘坐飞机去上海。","py":"Wǒmen chéngzuò fēijī qù Shànghǎi.","vi":"Chúng tôi đi máy bay đến Thượng Hải.","en":"We're flying to Shanghai."},{"use":"乘坐 + xe công cộng (văn phong trang trọng)","ex":"乘坐公共汽车要先刷卡。","py":"Chéngzuò gōnggòng qìchē yào xiān shuākǎ.","vi":"Đi xe buýt phải quẹt thẻ trước.","en":"You need to swipe your card first when taking the bus."},{"use":"thông báo: 请乘坐 + tuyến","ex":"请乘坐地铁二号线。","py":"Qǐng chéngzuò dìtiě èr hào xiàn.","vi":"Xin hãy đi tàu điện ngầm tuyến số hai.","en":"Please take Subway Line 2."},{"use":"乘坐 + phương tiện + 到 + địa điểm","ex":"乘坐高铁到北京只要四个半小时。","py":"Chéngzuò gāotiě dào Běijīng zhǐ yào sì ge bàn xiǎoshí.","vi":"Đi tàu cao tốc đến Bắc Kinh chỉ mất bốn tiếng rưỡi.","en":"It only takes four and a half hours to get to Beijing by high-speed rail."}]},"地铁":{"en":"subway; metro","exs":[{"use":"坐 + 地铁: đi tàu điện ngầm","ex":"我每天坐地铁上班。","py":"Wǒ měi tiān zuò dìtiě shàngbān.","vi":"Mỗi ngày tôi đi tàu điện ngầm đi làm.","en":"I take the subway to work every day."},{"use":"地铁站: ga tàu điện ngầm","ex":"地铁站就在前面不远。","py":"Dìtiě zhàn jiù zài qiánmiàn bù yuǎn.","vi":"Ga tàu điện ngầm ở ngay phía trước không xa.","en":"The subway station is just ahead, not far."},{"use":"so sánh: 坐地铁比...快","ex":"坐地铁比坐公共汽车快多了。","py":"Zuò dìtiě bǐ zuò gōnggòng qìchē kuài duō le.","vi":"Đi tàu điện ngầm nhanh hơn đi xe buýt nhiều.","en":"Taking the subway is much faster than taking the bus."},{"use":"地铁线: tuyến tàu điện ngầm (量词 条)","ex":"这条地铁线连接机场和市中心。","py":"Zhè tiáo dìtiě xiàn liánjiē jīchǎng hé shìzhōngxīn.","vi":"Tuyến tàu điện ngầm này nối sân bay với trung tâm thành phố.","en":"This subway line connects the airport and downtown."}]},"垃圾桶":{"en":"trash can; garbage bin","exs":[{"use":"扔进 + 垃圾桶: bỏ vào thùng rác","ex":"请把垃圾扔进垃圾桶。","py":"Qǐng bǎ lājī rēng jìn lājītǒng.","vi":"Xin hãy bỏ rác vào thùng rác.","en":"Please throw the trash into the trash can."},{"use":"路边有 + 垃圾桶: câu tồn tại","ex":"路边有很多垃圾桶。","py":"Lùbiān yǒu hěn duō lājītǒng.","vi":"Ven đường có rất nhiều thùng rác.","en":"There are lots of trash cans by the roadside."},{"use":"垃圾桶 + 满了: đầy","ex":"垃圾桶满了，快去倒一下。","py":"Lājītǒng mǎn le, kuài qù dào yíxià.","vi":"Thùng rác đầy rồi, mau đi đổ đi.","en":"The trash can is full; go empty it quickly."},{"use":"分类垃圾桶: thùng rác phân loại","ex":"公园里的垃圾桶分成两种颜色。","py":"Gōngyuán lǐ de lājītǒng fēnchéng liǎng zhǒng yánsè.","vi":"Thùng rác trong công viên chia làm hai màu.","en":"The trash cans in the park come in two colors."}]},"实实在在":{"en":"real; solid; down-to-earth; practical","exs":[{"use":"实实在在 + 的 + danh từ: làm định ngữ","ex":"我们要为环境做一些实实在在的事。","py":"Wǒmen yào wèi huánjìng zuò yìxiē shíshízàizài de shì.","vi":"Chúng ta phải làm vài việc thiết thực vì môi trường.","en":"We should do some real, practical things for the environment."},{"use":"miêu tả người: thật thà, chất phác","ex":"他是个实实在在的人，从不说假话。","py":"Tā shì ge shíshízàizài de rén, cóng bù shuō jiǎhuà.","vi":"Anh ấy là người thật thà, không bao giờ nói dối.","en":"He is an honest, down-to-earth person who never lies."},{"use":"实实在在 + 的 + 好处/效果","ex":"这次活动给了我们实实在在的好处。","py":"Zhè cì huódòng gěi le wǒmen shíshízàizài de hǎochù.","vi":"Hoạt động lần này mang lại cho chúng tôi lợi ích thiết thực.","en":"This event brought us real, tangible benefits."},{"use":"实实在在地 + V: làm trạng ngữ","ex":"他实实在在地帮了我一个大忙。","py":"Tā shíshízàizài de bāng le wǒ yí ge dà máng.","vi":"Anh ấy đã giúp tôi một việc lớn một cách thực sự.","en":"He really did help me out in a big way."}]},"于是":{"en":"so; thus; then; as a result","exs":[{"use":"于是 nối nguyên nhân - kết quả (sự việc xảy ra sau đó)","ex":"天开始下雨了，于是我们回家了。","py":"Tiān kāishǐ xiàyǔ le, yúshì wǒmen huíjiā le.","vi":"Trời bắt đầu mưa, thế là chúng tôi về nhà.","en":"It began to rain, so we went home."},{"use":"于是 + hành động tiếp theo của cùng chủ ngữ","ex":"他觉得很累，于是早早睡觉了。","py":"Tā juéde hěn lèi, yúshì zǎozǎo shuìjiào le.","vi":"Anh ấy thấy rất mệt nên đi ngủ sớm.","en":"He felt very tired, so he went to bed early."},{"use":"于是 + 向/跟 + ... + 借","ex":"我没带伞，于是向同事借了一把。","py":"Wǒ méi dài sǎn, yúshì xiàng tóngshì jiè le yì bǎ.","vi":"Tôi không mang ô nên mượn đồng nghiệp một cái.","en":"I didn't bring an umbrella, so I borrowed one from a colleague."},{"use":"想... , 于是...: có ý định rồi hành động","ex":"她想学汉语，于是报了一个班。","py":"Tā xiǎng xué Hànyǔ, yúshì bào le yí ge bān.","vi":"Cô ấy muốn học tiếng Trung nên đăng ký một lớp.","en":"She wanted to learn Chinese, so she signed up for a class."}]},"国家":{"en":"country; nation; state","exs":[{"use":"量词 个 + 国家: đất nước","ex":"中国是一个很大的国家。","py":"Zhōngguó shì yí ge hěn dà de guójiā.","vi":"Trung Quốc là một quốc gia rất lớn.","en":"China is a very large country."},{"use":"几个国家: hỏi số nước","ex":"你去过几个国家？","py":"Nǐ qù guo jǐ ge guójiā?","vi":"Bạn đã đi qua mấy nước rồi?","en":"How many countries have you been to?"},{"use":"nghĩa nhà nước (chính phủ)","ex":"国家要保护环境，也要发展经济。","py":"Guójiā yào bǎohù huánjìng, yě yào fāzhǎn jīngjì.","vi":"Nhà nước phải bảo vệ môi trường, cũng phải phát triển kinh tế.","en":"The state must protect the environment and also develop the economy."},{"use":"国家 + danh từ: cấp quốc gia","ex":"这是国家图书馆，里面有很多旧书。","py":"Zhè shì guójiā túshūguǎn, lǐmiàn yǒu hěn duō jiù shū.","vi":"Đây là thư viện quốc gia, bên trong có rất nhiều sách cũ.","en":"This is the national library, and it has many old books."}]},"环境":{"en":"environment; surroundings; conditions","exs":[{"use":"nghĩa 1: môi trường xung quanh","ex":"我家附近的环境很安静。","py":"Wǒ jiā fùjìn de huánjìng hěn ānjìng.","vi":"Môi trường quanh nhà tôi rất yên tĩnh.","en":"The surroundings near my home are very quiet."},{"use":"保护 + 环境: môi trường thiên nhiên","ex":"我们应该保护环境。","py":"Wǒmen yīnggāi bǎohù huánjìng.","vi":"Chúng ta nên bảo vệ môi trường.","en":"We should protect the environment."},{"use":"工作环境: môi trường làm việc","ex":"这家公司的工作环境很好。","py":"Zhè jiā gōngsī de gōngzuò huánjìng hěn hǎo.","vi":"Môi trường làm việc của công ty này rất tốt.","en":"This company has a great working environment."},{"use":"新环境: hoàn cảnh mới, thích nghi","ex":"刚到新的环境，我还不太习惯。","py":"Gāng dào xīn de huánjìng, wǒ hái bú tài xíguàn.","vi":"Vừa đến môi trường mới, tôi vẫn chưa quen lắm.","en":"I've just arrived in a new environment and am not quite used to it yet."}]},"数量":{"en":"quantity; amount; number","exs":[{"use":"数量 + 不多: số lượng ít","ex":"这种书的数量不多，要快点儿买。","py":"Zhè zhǒng shū de shùliàng bù duō, yào kuài diǎnr mǎi.","vi":"Loại sách này số lượng không nhiều, phải mua nhanh.","en":"There aren't many copies of this book, so buy it soon."},{"use":"数量 + 越来越多: số lượng tăng","ex":"城市里汽车的数量越来越多。","py":"Chéngshì lǐ qìchē de shùliàng yuè lái yuè duō.","vi":"Số lượng xe hơi trong thành phố ngày càng nhiều.","en":"The number of cars in the city keeps growing."},{"use":"数量 đối lập với 质量","ex":"买东西不能只看数量，还要看质量。","py":"Mǎi dōngxi bù néng zhǐ kàn shùliàng, hái yào kàn zhìliàng.","vi":"Mua đồ không thể chỉ xem số lượng mà còn phải xem chất lượng.","en":"When shopping, don't look only at quantity; look at quality too."},{"use":"数量有限: số lượng có hạn","ex":"这个礼物数量有限，卖完就没有了。","py":"Zhège lǐwù shùliàng yǒuxiàn, màiwán jiù méiyǒu le.","vi":"Món quà này số lượng có hạn, bán hết là hết.","en":"This gift is limited in quantity and will be gone once sold out."}]},"夏天":{"en":"summer","exs":[{"use":"làm định ngữ: ...的夏天","ex":"北京的夏天很热。","py":"Běijīng de xiàtiān hěn rè.","vi":"Mùa hè ở Bắc Kinh rất nóng.","en":"Summers in Beijing are very hot."},{"use":"làm tân ngữ: 喜欢 + 夏天","ex":"我最喜欢夏天，因为可以游泳。","py":"Wǒ zuì xǐhuan xiàtiān, yīnwèi kěyǐ yóuyǒng.","vi":"Tôi thích mùa hè nhất vì có thể đi bơi.","en":"I like summer best because I can go swimming."},{"use":"去年夏天: trạng ngữ thời gian","ex":"去年夏天我去了海南。","py":"Qùnián xiàtiān wǒ qù le Hǎinán.","vi":"Mùa hè năm ngoái tôi đã đi Hải Nam.","en":"I went to Hainan last summer."},{"use":"夏天到了: mùa hè đến","ex":"夏天到了，大家都爱吃冰淇淋。","py":"Xiàtiān dào le, dàjiā dōu ài chī bīngqílín.","vi":"Mùa hè đến rồi, ai cũng thích ăn kem.","en":"Summer is here, and everyone loves ice cream."}]},"温度":{"en":"temperature","exs":[{"use":"温度 + 是 + số + 度","ex":"今天的温度是三十五度。","py":"Jīntiān de wēndù shì sānshíwǔ dù.","vi":"Nhiệt độ hôm nay là ba mươi lăm độ.","en":"Today's temperature is 35 degrees."},{"use":"温度 + 高/低: cao, thấp","ex":"房间里温度太高，把空调打开吧。","py":"Fángjiān lǐ wēndù tài gāo, bǎ kōngtiáo dǎkāi ba.","vi":"Nhiệt độ trong phòng quá cao, bật điều hòa lên đi.","en":"The room is too hot; let's turn on the air conditioner."},{"use":"温度 + 下降/上升: biến đổi","ex":"晚上温度会下降，多穿点儿衣服。","py":"Wǎnshang wēndù huì xiàjiàng, duō chuān diǎnr yīfu.","vi":"Buổi tối nhiệt độ sẽ giảm, mặc thêm áo vào.","en":"The temperature will drop at night, so wear more clothes."},{"use":"nhiệt độ của vật (nước, ...)","ex":"水的温度刚好，可以喝了。","py":"Shuǐ de wēndù gānghǎo, kěyǐ hē le.","vi":"Nhiệt độ của nước vừa đúng, uống được rồi.","en":"The water is at just the right temperature to drink."}]},"出门":{"en":"to go out; to leave home; to travel away from home","exs":[{"use":"出门 + thời gian: ra khỏi nhà lúc nào","ex":"我今天早上八点出门。","py":"Wǒ jīntiān zǎoshang bā diǎn chūmén.","vi":"Sáng nay tám giờ tôi ra khỏi nhà.","en":"I left home at eight this morning."},{"use":"出门 + 别忘了 + V: dặn dò khi ra ngoài","ex":"出门别忘了带钥匙。","py":"Chūmén bié wàng le dài yàoshi.","vi":"Ra ngoài đừng quên mang chìa khóa.","en":"Don't forget your keys when you go out."},{"use":"出门在外: đi xa nhà","ex":"他常常出门在外，很少回家。","py":"Tā chángcháng chūmén zài wài, hěn shǎo huí jiā.","vi":"Anh ấy thường xuyên xa nhà, rất ít khi về.","en":"He's often away from home and rarely comes back."},{"use":"不想出门: không muốn ra ngoài","ex":"外面太冷了，我不想出门。","py":"Wàimiàn tài lěng le, wǒ bù xiǎng chūmén.","vi":"Bên ngoài lạnh quá, tôi không muốn ra ngoài.","en":"It's too cold outside; I don't want to go out."}]},"公共汽车":{"en":"bus; public bus","exs":[{"use":"坐 + 公共汽车: đi xe buýt","ex":"我坐公共汽车去上班。","py":"Wǒ zuò gōnggòng qìchē qù shàngbān.","vi":"Tôi đi xe buýt đi làm.","en":"I take the bus to work."},{"use":"量词 路: tuyến xe buýt","ex":"这路公共汽车经过火车站。","py":"Zhè lù gōnggòng qìchē jīngguò huǒchēzhàn.","vi":"Tuyến xe buýt này đi qua ga tàu hỏa.","en":"This bus route passes the train station."},{"use":"公共汽车上: ở trên xe buýt","ex":"公共汽车上人很多，我没有座位。","py":"Gōnggòng qìchē shàng rén hěn duō, wǒ méiyǒu zuòwèi.","vi":"Trên xe buýt đông người, tôi không có chỗ ngồi.","en":"The bus was crowded, and I had no seat."},{"use":"下一班 + 公共汽车: chuyến tiếp theo","ex":"下一班公共汽车什么时候来？","py":"Xià yì bān gōnggòng qìchē shénme shíhou lái?","vi":"Chuyến xe buýt tiếp theo khi nào đến?","en":"When does the next bus come?"}]},"污染":{"en":"to pollute; pollution","exs":[{"use":"động từ: 污染 + tân ngữ","ex":"工厂的废水污染了河流。","py":"Gōngchǎng de fèishuǐ wūrǎn le héliú.","vi":"Nước thải của nhà máy đã làm ô nhiễm sông.","en":"The factory's wastewater has polluted the river."},{"use":"danh từ: 空气污染, 水污染","ex":"空气污染对身体不好。","py":"Kōngqì wūrǎn duì shēntǐ bù hǎo.","vi":"Ô nhiễm không khí không tốt cho sức khỏe.","en":"Air pollution is bad for your health."},{"use":"被污染: bị ô nhiễm (câu bị động)","ex":"这条河已经被污染了。","py":"Zhè tiáo hé yǐjīng bèi wūrǎn le.","vi":"Con sông này đã bị ô nhiễm rồi.","en":"This river has already been polluted."},{"use":"没有污染: không gây ô nhiễm","ex":"电动车没有污染，很环保。","py":"Diàndòngchē méiyǒu wūrǎn, hěn huánbǎo.","vi":"Xe điện không gây ô nhiễm, rất thân thiện với môi trường.","en":"Electric vehicles produce no pollution and are very eco-friendly."}]},"垃圾":{"en":"garbage; trash; rubbish","exs":[{"use":"乱扔垃圾: vứt rác bừa bãi","ex":"不要乱扔垃圾。","py":"Búyào luàn rēng lājī.","vi":"Đừng vứt rác bừa bãi.","en":"Don't litter."},{"use":"垃圾分类: phân loại rác","ex":"我们小区实行垃圾分类。","py":"Wǒmen xiǎoqū shíxíng lājī fēnlèi.","vi":"Khu dân cư của chúng tôi thực hiện phân loại rác.","en":"Our neighborhood practices garbage sorting."},{"use":"倒垃圾: đổ rác","ex":"晚上我去倒垃圾。","py":"Wǎnshang wǒ qù dào lājī.","vi":"Buổi tối tôi đi đổ rác.","en":"I'll go take out the trash this evening."},{"use":"垃圾食品: đồ ăn vặt kém dinh dưỡng","ex":"孩子不要总吃垃圾食品。","py":"Háizi bú yào zǒng chī lājī shípǐn.","vi":"Trẻ em đừng suốt ngày ăn đồ ăn vặt vô bổ.","en":"Kids shouldn't always eat junk food."}]},"美丽":{"en":"beautiful; pretty","exs":[{"use":"美丽的 + danh từ (nơi chốn): làm định ngữ","ex":"杭州是一座美丽的城市。","py":"Hángzhōu shì yí zuò měilì de chéngshì.","vi":"Hàng Châu là một thành phố xinh đẹp.","en":"Hangzhou is a beautiful city."},{"use":"làm vị ngữ: 非常美丽","ex":"春天的公园非常美丽。","py":"Chūntiān de gōngyuán fēicháng měilì.","vi":"Công viên mùa xuân vô cùng đẹp.","en":"The park in spring is very beautiful."},{"use":"miêu tả người, thường văn viết","ex":"她是一位善良又美丽的姑娘。","py":"Tā shì yí wèi shànliáng yòu měilì de gūniang.","vi":"Cô ấy là một cô gái hiền lành lại xinh đẹp.","en":"She is a kind and beautiful girl."},{"use":"美丽 + 极了: bổ ngữ mức độ","ex":"山上的风景美丽极了。","py":"Shān shàng de fēngjǐng měilì jí le.","vi":"Phong cảnh trên núi đẹp vô cùng.","en":"The scenery on the mountain is extremely beautiful."}]},"出差":{"en":"to go on a business trip; business trip","exs":[{"use":"去 + địa điểm + 出差","ex":"我下周要去上海出差。","py":"Wǒ xià zhōu yào qù Shànghǎi chūchāi.","vi":"Tuần sau tôi phải đi Thượng Hải công tác.","en":"I have to go to Shanghai on a business trip next week."},{"use":"经常出差: thường xuyên đi công tác","ex":"他经常出差，不常在家。","py":"Tā jīngcháng chūchāi, bù cháng zài jiā.","vi":"Anh ấy thường đi công tác, ít khi ở nhà.","en":"He travels on business often and isn't home much."},{"use":"出差 + 了 + thời lượng (từ ly hợp)","ex":"他去北京出差了三天。","py":"Tā qù Běijīng chūchāi le sān tiān.","vi":"Anh ấy đi công tác Bắc Kinh ba ngày.","en":"He was on a business trip in Beijing for three days."},{"use":"出差回来 + 以后","ex":"出差回来后，我给你带礼物。","py":"Chūchāi huílái hòu, wǒ gěi nǐ dài lǐwù.","vi":"Sau khi đi công tác về, tôi sẽ mang quà cho bạn.","en":"After I get back from my business trip, I'll bring you a gift."}]},"毛巾":{"en":"towel; washcloth","exs":[{"use":"量词 条 + 毛巾","ex":"请给我一条干净的毛巾。","py":"Qǐng gěi wǒ yì tiáo gānjìng de máojīn.","vi":"Làm ơn cho tôi một cái khăn sạch.","en":"Please give me a clean towel."},{"use":"用 + 毛巾 + 擦: dùng khăn lau","ex":"他用毛巾擦了擦脸上的汗。","py":"Tā yòng máojīn cā le cā liǎn shàng de hàn.","vi":"Anh ấy dùng khăn lau mồ hôi trên mặt.","en":"He wiped the sweat off his face with a towel."},{"use":"旅行带 + 毛巾","ex":"旅行时我会带一条小毛巾。","py":"Lǚxíng shí wǒ huì dài yì tiáo xiǎo máojīn.","vi":"Khi đi du lịch tôi sẽ mang theo một chiếc khăn nhỏ.","en":"I bring a small towel when I travel."},{"use":"毛巾 + 湿了: làm chủ ngữ","ex":"这条毛巾湿了，挂在外面晾一下。","py":"Zhè tiáo máojīn shī le, guà zài wàimiàn liàng yíxià.","vi":"Cái khăn này ướt rồi, treo ra ngoài phơi một chút.","en":"This towel is wet; hang it outside to dry."}]},"牙膏":{"en":"toothpaste","exs":[{"use":"量词 支 + 牙膏","ex":"我去超市买一支牙膏。","py":"Wǒ qù chāoshì mǎi yì zhī yágāo.","vi":"Tôi đi siêu thị mua một tuýp kem đánh răng.","en":"I'm going to the supermarket to buy a tube of toothpaste."},{"use":"牙膏 + 用完了: hết","ex":"牙膏用完了，记得再买一支。","py":"Yágāo yòng wán le, jìde zài mǎi yì zhī.","vi":"Kem đánh răng hết rồi, nhớ mua thêm một tuýp.","en":"We're out of toothpaste; remember to buy another tube."},{"use":"挤 + 牙膏: bóp kem","ex":"早上刷牙时，我在牙刷上挤了一点儿牙膏。","py":"Zǎoshang shuāyá shí, wǒ zài yáshuā shàng jǐ le yìdiǎnr yágāo.","vi":"Sáng đánh răng, tôi bóp một ít kem lên bàn chải.","en":"When brushing my teeth in the morning, I squeezed a little toothpaste onto the brush."},{"use":"...味的牙膏: loại hương vị","ex":"孩子喜欢草莓味的牙膏。","py":"Háizi xǐhuan cǎoméi wèi de yágāo.","vi":"Trẻ con thích kem đánh răng vị dâu.","en":"Kids like strawberry-flavored toothpaste."}]},"牙刷":{"en":"toothbrush","exs":[{"use":"牙刷 và 牙膏: đi đôi với nhau","ex":"宾馆里一般有牙刷和牙膏。","py":"Bīnguǎn lǐ yìbān yǒu yáshuā hé yágāo.","vi":"Khách sạn thường có bàn chải và kem đánh răng.","en":"Hotels usually have toothbrushes and toothpaste."},{"use":"换牙刷: thay bàn chải","ex":"牙刷每三个月要换一次。","py":"Yáshuā měi sān ge yuè yào huàn yí cì.","vi":"Bàn chải đánh răng cứ ba tháng phải thay một lần.","en":"A toothbrush should be replaced every three months."},{"use":"带牙刷: mang theo khi đi xa","ex":"出差时别忘了带牙刷。","py":"Chūchāi shí bié wàng le dài yáshuā.","vi":"Khi đi công tác đừng quên mang bàn chải đánh răng.","en":"Don't forget your toothbrush on a business trip."},{"use":"量词 把 + 牙刷; 电动牙刷","ex":"我给爸爸买了一把电动牙刷。","py":"Wǒ gěi bàba mǎi le yì bǎ diàndòng yáshuā.","vi":"Tôi mua cho bố một chiếc bàn chải điện.","en":"I bought my dad an electric toothbrush."}]},"箱子":{"en":"box; case; suitcase; trunk","exs":[{"use":"nghĩa vali: 提/拿 + 箱子","ex":"我的箱子很重，你能帮我提一下吗？","py":"Wǒ de xiāngzi hěn zhòng, nǐ néng bāng wǒ tí yíxià ma?","vi":"Vali của tôi rất nặng, bạn xách giúp tôi một chút được không?","en":"My suitcase is heavy; could you help me carry it?"},{"use":"把 + đồ + 放进 + 箱子里","ex":"把东西放进箱子里。","py":"Bǎ dōngxi fàng jìn xiāngzi lǐ.","vi":"Cho đồ vào trong thùng.","en":"Put the things into the box."},{"use":"拖着 + 箱子: kéo vali","ex":"他拖着一个大箱子走进了机场。","py":"Tā tuōzhe yí ge dà xiāngzi zǒu jìn le jīchǎng.","vi":"Anh ấy kéo một chiếc vali lớn đi vào sân bay.","en":"He walked into the airport pulling a big suitcase."},{"use":"箱子里 + 装满了 ...: nghĩa thùng, hòm","ex":"箱子里装满了书。","py":"Xiāngzi lǐ zhuāng mǎn le shū.","vi":"Trong thùng chứa đầy sách.","en":"The box is full of books."}]},"宾馆":{"en":"hotel; guesthouse","exs":[{"use":"订 + 宾馆: đặt khách sạn","ex":"我们订了一家便宜的宾馆。","py":"Wǒmen dìng le yì jiā piányi de bīnguǎn.","vi":"Chúng tôi đã đặt một khách sạn giá rẻ.","en":"We booked an inexpensive hotel."},{"use":"住 + 宾馆: ở khách sạn","ex":"出差的时候我一般住宾馆。","py":"Chūchāi de shíhou wǒ yìbān zhù bīnguǎn.","vi":"Khi đi công tác tôi thường ở khách sạn.","en":"I usually stay at a hotel on business trips."},{"use":"宾馆 + 离 + ... + 近/远","ex":"这家宾馆离火车站很近。","py":"Zhè jiā bīnguǎn lí huǒchēzhàn hěn jìn.","vi":"Khách sạn này rất gần ga tàu hỏa.","en":"This hotel is very close to the train station."},{"use":"宾馆的 + 服务员: nhân viên khách sạn","ex":"宾馆的服务员态度非常好。","py":"Bīnguǎn de fúwùyuán tàidu fēicháng hǎo.","vi":"Nhân viên khách sạn có thái độ rất tốt.","en":"The hotel staff have a very good attitude."}]},"保护环境":{"en":"to protect the environment","exs":[{"use":"làm chủ ngữ: 保护环境 + 是...","ex":"保护环境是每个人的责任。","py":"Bǎohù huánjìng shì měi ge rén de zérèn.","vi":"Bảo vệ môi trường là trách nhiệm của mỗi người.","en":"Protecting the environment is everyone's responsibility."},{"use":"为了 + 保护环境, ...: mục đích","ex":"为了保护环境，我们少开车。","py":"Wèile bǎohù huánjìng, wǒmen shǎo kāichē.","vi":"Để bảo vệ môi trường, chúng ta ít lái xe.","en":"To protect the environment, we drive less."},{"use":"从小事做起 → 就能保护环境","ex":"从小事做起，就能保护环境。","py":"Cóng xiǎoshì zuòqǐ, jiù néng bǎohù huánjìng.","vi":"Bắt đầu từ việc nhỏ là có thể bảo vệ môi trường.","en":"Starting with small things, we can protect the environment."},{"use":"怎么 + 保护环境: bảo vệ như thế nào","ex":"学校教孩子们怎么保护环境。","py":"Xuéxiào jiāo háizimen zěnme bǎohù huánjìng.","vi":"Nhà trường dạy bọn trẻ cách bảo vệ môi trường.","en":"The school teaches children how to protect the environment."}]},"小事":{"en":"small matter; trivial thing","exs":[{"use":"一件 + 小事: việc nhỏ","ex":"这只是一件小事，不用谢。","py":"Zhè zhǐshì yí jiàn xiǎoshì, búyòng xiè.","vi":"Đây chỉ là việc nhỏ thôi, không cần cảm ơn.","en":"It's just a small thing; no need to thank me."},{"use":"从小事做起","ex":"保护环境要从身边的小事做起。","py":"Bǎohù huánjìng yào cóng shēnbiān de xiǎoshì zuòqǐ.","vi":"Bảo vệ môi trường phải bắt đầu từ những việc nhỏ quanh mình.","en":"Protecting the environment starts with small things around us."},{"use":"为 + 小事 + 生气: vì chuyện nhỏ","ex":"不要为一点儿小事就生气。","py":"Búyào wèi yìdiǎnr xiǎoshì jiù shēngqì.","vi":"Đừng vì chút chuyện nhỏ mà nổi giận.","en":"Don't get angry over a trivial matter."},{"use":"对...来说是小事","ex":"这对他来说是小事。","py":"Zhè duì tā lái shuō shì xiǎoshì.","vi":"Việc này đối với anh ấy là chuyện nhỏ.","en":"For him, this is a small matter."}]},"飞机":{"en":"airplane; plane","exs":[{"use":"坐飞机: đi máy bay","ex":"从北京到广州坐飞机要三个小时。","py":"Cóng Běijīng dào Guǎngzhōu zuò fēijī yào sān ge xiǎoshí.","vi":"Từ Bắc Kinh đến Quảng Châu đi máy bay mất ba tiếng.","en":"It takes three hours to fly from Beijing to Guangzhou."},{"use":"飞机票: vé máy bay","ex":"我买到了明天的飞机票。","py":"Wǒ mǎidào le míngtiān de fēijī piào.","vi":"Tôi mua được vé máy bay ngày mai rồi.","en":"I got a plane ticket for tomorrow."},{"use":"飞机晚点: máy bay bị trễ","ex":"因为下大雨，飞机晚点了。","py":"Yīnwèi xià dàyǔ, fēijī wǎndiǎn le.","vi":"Vì mưa lớn nên máy bay bị trễ.","en":"The plane was delayed because of heavy rain."},{"use":"飞机起飞: máy bay cất cánh","ex":"飞机马上就要起飞了，请关机。","py":"Fēijī mǎshàng jiù yào qǐfēi le, qǐng guānjī.","vi":"Máy bay sắp cất cánh, xin hãy tắt máy.","en":"The plane is about to take off; please turn off your phone."}]},"送到":{"en":"to deliver to; to take (someone) to; to send to","exs":[{"use":"把 + đồ vật + 送到 + nơi","ex":"请把这个包裹送到我家。","py":"Qǐng bǎ zhège bāoguǒ sòngdào wǒ jiā.","vi":"Xin hãy đưa gói hàng này đến nhà tôi.","en":"Please deliver this package to my home."},{"use":"把 + người + 送到 + nơi: đưa đến","ex":"爸爸开车把我送到了学校门口。","py":"Bàba kāichē bǎ wǒ sòngdào le xuéxiào ménkǒu.","vi":"Bố lái xe đưa tôi đến cổng trường.","en":"Dad drove me to the school gate."},{"use":"送到: giao hàng trong thời gian","ex":"外卖半小时内能送到。","py":"Wàimài bàn xiǎoshí nèi néng sòngdào.","vi":"Đồ ăn giao đến trong vòng nửa tiếng.","en":"The takeout can be delivered within half an hour."},{"use":"送到 + văn phòng","ex":"我明天把书送到你办公室。","py":"Wǒ míngtiān bǎ shū sòngdào nǐ bàngōngshì.","vi":"Ngày mai tôi sẽ mang sách đến văn phòng bạn.","en":"I'll bring the book to your office tomorrow."}]},"机场":{"en":"airport","exs":[{"use":"去 + 机场 + 接/送","ex":"我明天早上去机场接朋友。","py":"Wǒ míngtiān zǎoshang qù jīchǎng jiē péngyou.","vi":"Sáng mai tôi ra sân bay đón bạn.","en":"I'm going to the airport tomorrow morning to pick up a friend."},{"use":"机场 + 很大","ex":"这个机场很大，我差点儿迷路了。","py":"Zhège jīchǎng hěn dà, wǒ chàdiǎnr mílù le.","vi":"Sân bay này rất lớn, tôi suýt bị lạc.","en":"This airport is huge; I almost got lost."},{"use":"từ ... đến 机场 + phương tiện + thời gian","ex":"从市中心到机场坐地铁要四十分钟。","py":"Cóng shìzhōngxīn dào jīchǎng zuò dìtiě yào sìshí fēnzhōng.","vi":"Từ trung tâm thành phố đến sân bay đi tàu điện ngầm mất bốn mươi phút.","en":"It takes forty minutes by subway from downtown to the airport."},{"use":"到机场送 + người","ex":"爸爸妈妈到机场送我。","py":"Bàba māma dào jīchǎng sòng wǒ.","vi":"Bố mẹ ra sân bay tiễn tôi.","en":"My parents came to the airport to see me off."}]},"路上":{"en":"on the way; en route","exs":[{"use":"在路上: đang trên đường","ex":"我现在还在路上，马上就到。","py":"Wǒ xiànzài hái zài lùshàng, mǎshàng jiù dào.","vi":"Tôi vẫn đang trên đường, sắp đến rồi.","en":"I'm still on my way and will be there soon."},{"use":"路上小心: lời dặn khi ai đó đi","ex":"路上小心，到了给我打电话。","py":"Lùshàng xiǎoxīn, dào le gěi wǒ dǎ diànhuà.","vi":"Đi đường cẩn thận, đến nơi gọi điện cho tôi.","en":"Be careful on the way, and call me when you arrive."},{"use":"路上 + 堵车: làm trạng ngữ","ex":"今天路上堵车，所以我迟到了。","py":"Jīntiān lùshàng dǔchē, suǒyǐ wǒ chídào le.","vi":"Hôm nay trên đường bị kẹt xe nên tôi đến muộn.","en":"There was a traffic jam today, so I was late."},{"use":"...的路上: trên đường (đi/về) ...","ex":"回家的路上，我买了一些水果。","py":"Huí jiā de lùshàng, wǒ mǎi le yìxiē shuǐguǒ.","vi":"Trên đường về nhà, tôi mua một ít trái cây.","en":"On the way home, I bought some fruit."}]},"坐地铁":{"en":"to take the subway","exs":[{"use":"坐地铁 + 去 + địa điểm","ex":"坐地铁去公司比开车方便。","py":"Zuò dìtiě qù gōngsī bǐ kāichē fāngbiàn.","vi":"Đi tàu điện ngầm đến công ty tiện hơn lái xe.","en":"Taking the subway to the office is more convenient than driving."},{"use":"坐地铁 + 到 + địa điểm","ex":"你可以坐地铁到人民广场。","py":"Nǐ kěyǐ zuò dìtiě dào Rénmín Guǎngchǎng.","vi":"Bạn có thể đi tàu điện ngầm đến Quảng trường Nhân Dân.","en":"You can take the subway to People's Square."},{"use":"làm chủ ngữ: 坐地铁 既...又...","ex":"坐地铁既快又环保。","py":"Zuò dìtiě jì kuài yòu huánbǎo.","vi":"Đi tàu điện ngầm vừa nhanh vừa thân thiện với môi trường.","en":"Taking the subway is both fast and eco-friendly."},{"use":"打算 + 坐地铁 + 去 + V","ex":"周末我们打算坐地铁去逛街。","py":"Zhōumò wǒmen dǎsuàn zuò dìtiě qù guàngjiē.","vi":"Cuối tuần chúng tôi định đi tàu điện ngầm đi dạo phố.","en":"This weekend we plan to take the subway to go shopping."}]},"油钱":{"en":"gas money; fuel cost","exs":[{"use":"油钱 + 越来越贵","ex":"现在油钱越来越贵了。","py":"Xiànzài yóuqián yuè lái yuè guì le.","vi":"Bây giờ tiền xăng ngày càng đắt.","en":"Gas money is getting more and more expensive."},{"use":"省 + 油钱: tiết kiệm tiền xăng","ex":"坐地铁可以省不少油钱。","py":"Zuò dìtiě kěyǐ shěng bù shǎo yóuqián.","vi":"Đi tàu điện ngầm có thể tiết kiệm không ít tiền xăng.","en":"Taking the subway can save quite a bit on gas."},{"use":"油钱 chia nhau trả","ex":"油钱我们一人一半。","py":"Yóuqián wǒmen yì rén yíbàn.","vi":"Tiền xăng chúng ta mỗi người một nửa.","en":"We'll each pay half of the gas money."},{"use":"花 + số tiền + 油钱","ex":"每个月我要花一千块油钱。","py":"Měi ge yuè wǒ yào huā yìqiān kuài yóuqián.","vi":"Mỗi tháng tôi phải tốn một nghìn tệ tiền xăng.","en":"I spend a thousand yuan on gas every month."}]},"污染空气":{"en":"to pollute the air","exs":[{"use":"会 + 污染空气: gây ô nhiễm không khí","ex":"汽车太多会污染空气。","py":"Qìchē tài duō huì wūrǎn kōngqì.","vi":"Xe hơi quá nhiều sẽ gây ô nhiễm không khí.","en":"Too many cars will pollute the air."},{"use":"工厂 + 污染空气","ex":"工厂冒烟，污染空气。","py":"Gōngchǎng mào yān, wūrǎn kōngqì.","vi":"Nhà máy xả khói làm ô nhiễm không khí.","en":"The factory gives off smoke and pollutes the air."},{"use":"不会污染空气: dạng phủ định","ex":"骑自行车不会污染空气。","py":"Qí zìxíngchē bú huì wūrǎn kōngqì.","vi":"Đạp xe đạp không gây ô nhiễm không khí.","en":"Riding a bicycle doesn't pollute the air."},{"use":"câu hỏi: 为什么...会污染空气","ex":"为什么烧垃圾会污染空气？","py":"Wèishénme shāo lājī huì wūrǎn kōngqì?","vi":"Tại sao đốt rác lại gây ô nhiễm không khí?","en":"Why does burning garbage pollute the air?"}]},"卫生间":{"en":"bathroom; restroom; toilet","exs":[{"use":"hỏi đường: 卫生间在哪儿","ex":"请问，卫生间在哪儿？","py":"Qǐngwèn, wèishēngjiān zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu?","en":"Excuse me, where is the restroom?"},{"use":"房间带卫生间: phòng có nhà vệ sinh riêng","ex":"这个房间带卫生间。","py":"Zhège fángjiān dài wèishēngjiān.","vi":"Phòng này có nhà vệ sinh riêng.","en":"This room has an attached bathroom."},{"use":"打扫 + 卫生间","ex":"服务员正在打扫卫生间。","py":"Fúwùyuán zhèngzài dǎsǎo wèishēngjiān.","vi":"Nhân viên phục vụ đang dọn nhà vệ sinh.","en":"The attendant is cleaning the bathroom."},{"use":"卫生间里 + 没有 ...","ex":"卫生间里没有毛巾，请再拿一条。","py":"Wèishēngjiān lǐ méiyǒu máojīn, qǐng zài ná yì tiáo.","vi":"Trong nhà vệ sinh không có khăn, xin mang thêm một cái.","en":"There's no towel in the bathroom; please bring another."}]},"客人":{"en":"guest; visitor; customer","exs":[{"use":"来客人了: có khách đến","ex":"今天晚上家里来了客人。","py":"Jīntiān wǎnshang jiā lǐ lái le kèrén.","vi":"Tối nay nhà có khách đến.","en":"We have guests at home this evening."},{"use":"招待 + 客人: tiếp đãi khách","ex":"妈妈做了很多菜招待客人。","py":"Māma zuò le hěn duō cài zhāodài kèrén.","vi":"Mẹ nấu rất nhiều món để tiếp khách.","en":"Mom cooked lots of dishes to entertain the guests."},{"use":"客人 = khách hàng ở nhà hàng, khách sạn","ex":"饭馆里的客人很多。","py":"Fànguǎn lǐ de kèrén hěn duō.","vi":"Trong quán ăn có rất nhiều khách.","en":"The restaurant has many customers."},{"use":"请 + 客人 + V: mời khách","ex":"请客人先坐，我去倒茶。","py":"Qǐng kèrén xiān zuò, wǒ qù dào chá.","vi":"Mời khách ngồi trước, tôi đi rót trà.","en":"Please have the guests sit first; I'll go pour some tea."}]},"打扫":{"en":"to clean; to sweep; to tidy up","exs":[{"use":"打扫 + phòng, nhà","ex":"周末我在家打扫房间。","py":"Zhōumò wǒ zài jiā dǎsǎo fángjiān.","vi":"Cuối tuần tôi ở nhà dọn dẹp phòng.","en":"I clean my room at home on weekends."},{"use":"把 + nơi + 打扫得 + 很干净","ex":"他把教室打扫得很干净。","py":"Tā bǎ jiàoshì dǎsǎo de hěn gānjìng.","vi":"Anh ấy quét dọn lớp học rất sạch sẽ.","en":"He cleaned the classroom until it was spotless."},{"use":"打扫一下: động từ + 一下 (nhẹ nhàng)","ex":"客人来之前，我要先打扫一下。","py":"Kèrén lái zhīqián, wǒ yào xiān dǎsǎo yíxià.","vi":"Trước khi khách đến, tôi phải dọn dẹp một chút.","en":"Before the guests arrive, I need to tidy up a bit."},{"use":"打扫卫生: dọn vệ sinh","ex":"每天早上有人来打扫卫生。","py":"Měi tiān zǎoshang yǒu rén lái dǎsǎo wèishēng.","vi":"Mỗi sáng đều có người đến dọn vệ sinh.","en":"Someone comes to clean every morning."}]},"服务员":{"en":"waiter; waitress; attendant","exs":[{"use":"gọi phục vụ: 服务员, ...","ex":"服务员，请给我菜单。","py":"Fúwùyuán, qǐng gěi wǒ càidān.","vi":"Phục vụ ơi, làm ơn cho tôi thực đơn.","en":"Waiter, could I have the menu, please?"},{"use":"当 + 服务员: làm nghề phục vụ","ex":"她在一家饭店当服务员。","py":"Tā zài yì jiā fàndiàn dāng fúwùyuán.","vi":"Cô ấy làm nhân viên phục vụ ở một nhà hàng.","en":"She works as a waitress at a restaurant."},{"use":"宾馆的服务员: nhân viên khách sạn","ex":"宾馆的服务员帮我拿了行李。","py":"Bīnguǎn de fúwùyuán bāng wǒ ná le xíngli.","vi":"Nhân viên khách sạn giúp tôi xách hành lý.","en":"The hotel attendant helped me carry my luggage."},{"use":"叫 + 服务员 + 来 + V","ex":"我们叫服务员来结账吧。","py":"Wǒmen jiào fúwùyuán lái jiézhàng ba.","vi":"Chúng ta gọi phục vụ đến tính tiền đi.","en":"Let's call the waiter over to pay the bill."}]},"抱歉":{"en":"sorry; apologetic; regretful","exs":[{"use":"很抱歉, ...: lời xin lỗi lịch sự","ex":"很抱歉，让您久等了。","py":"Hěn bàoqiàn, ràng nín jiǔ děng le.","vi":"Rất xin lỗi đã để ngài phải đợi lâu.","en":"I'm very sorry to have kept you waiting."},{"use":"对 + sự việc + 感到抱歉","ex":"我对昨天的事感到非常抱歉。","py":"Wǒ duì zuótiān de shì gǎndào fēicháng bàoqiàn.","vi":"Tôi cảm thấy vô cùng áy náy về chuyện hôm qua.","en":"I feel terribly sorry about what happened yesterday."},{"use":"抱歉, + lý do từ chối","ex":"抱歉，今天我不能参加你的生日会。","py":"Bàoqiàn, jīntiān wǒ bù néng cānjiā nǐ de shēngrì huì.","vi":"Xin lỗi, hôm nay tôi không thể dự tiệc sinh nhật của bạn.","en":"Sorry, I can't come to your birthday party today."},{"use":"觉得 + 抱歉: cảm thấy áy náy","ex":"迟到了这么久，我觉得很抱歉。","py":"Chídào le zhème jiǔ, wǒ juéde hěn bàoqiàn.","vi":"Đến muộn lâu như vậy, tôi thấy rất áy náy.","en":"I feel very sorry for being so late."}]},"桌子":{"en":"table; desk","exs":[{"use":"量词 张 + 桌子","ex":"教室里有二十张桌子。","py":"Jiàoshì lǐ yǒu èrshí zhāng zhuōzi.","vi":"Trong lớp học có hai mươi cái bàn.","en":"There are twenty desks in the classroom."},{"use":"桌子上: trên bàn","ex":"桌子上放着一杯茶。","py":"Zhuōzi shàng fàngzhe yì bēi chá.","vi":"Trên bàn đặt một tách trà.","en":"A cup of tea is sitting on the table."},{"use":"擦桌子: lau bàn","ex":"吃完饭，我来擦桌子。","py":"Chī wán fàn, wǒ lái cā zhuōzi.","vi":"Ăn cơm xong, tôi sẽ lau bàn.","en":"After the meal, I'll wipe the table."},{"use":"订桌子: đặt bàn ở nhà hàng","ex":"我们订了一张六个人的桌子。","py":"Wǒmen dìng le yì zhāng liù ge rén de zhuōzi.","vi":"Chúng tôi đã đặt một bàn sáu người.","en":"We reserved a table for six."}]},"下面":{"en":"below; underneath; next; following","exs":[{"use":"phương vị: danh từ + 下面","ex":"桌子下面有一只小猫。","py":"Zhuōzi xiàmian yǒu yì zhī xiǎo māo.","vi":"Dưới bàn có một chú mèo nhỏ.","en":"There's a kitten under the table."},{"use":"下面的 + danh từ: phần bên dưới/sau đây","ex":"请看下面的图片。","py":"Qǐng kàn xiàmian de túpiàn.","vi":"Xin hãy xem bức hình dưới đây.","en":"Please look at the picture below."},{"use":"下面 + chủ ngữ + V: tiếp theo (trình bày)","ex":"下面我来介绍一下我们的计划。","py":"Xiàmian wǒ lái jièshào yíxià wǒmen de jìhuà.","vi":"Tiếp theo, tôi xin giới thiệu kế hoạch của chúng ta.","en":"Next, let me introduce our plan."},{"use":"tầng dưới: 在...下面一层","ex":"我住在你家下面一层。","py":"Wǒ zhù zài nǐ jiā xiàmian yì céng.","vi":"Tôi ở tầng ngay dưới nhà bạn.","en":"I live one floor below you."}]},"瓶子":{"en":"bottle; jar","exs":[{"use":"量词 个 + 瓶子","ex":"桌子上有一个空瓶子。","py":"Zhuōzi shàng yǒu yí ge kōng píngzi.","vi":"Trên bàn có một cái chai rỗng.","en":"There's an empty bottle on the table."},{"use":"瓶子 làm chủ ngữ: có thể tái chế","ex":"喝完的瓶子不要扔，可以回收。","py":"Hē wán de píngzi búyào rēng, kěyǐ huíshōu.","vi":"Chai uống xong đừng vứt, có thể tái chế.","en":"Don't throw away empty bottles; they can be recycled."},{"use":"瓶子里: bên trong chai","ex":"瓶子里还有一点儿水。","py":"Píngzi lǐ hái yǒu yìdiǎnr shuǐ.","vi":"Trong chai vẫn còn một ít nước.","en":"There's still a little water in the bottle."},{"use":"把 + 瓶子 + 打破了","ex":"弟弟不小心把瓶子打破了。","py":"Dìdi bù xiǎoxīn bǎ píngzi dǎpò le.","vi":"Em trai không cẩn thận làm vỡ cái chai.","en":"My younger brother accidentally broke the bottle."}]},"纸盒子":{"en":"paper box; carton","exs":[{"use":"放在 + 纸盒子里","ex":"这个礼物放在纸盒子里。","py":"Zhège lǐwù fàng zài zhǐhézi lǐ.","vi":"Món quà này được đặt trong hộp giấy.","en":"This gift is placed in a paper box."},{"use":"可以用来 + V: tái sử dụng","ex":"旧的纸盒子可以用来放小东西。","py":"Jiù de zhǐhézi kěyǐ yònglái fàng xiǎo dōngxi.","vi":"Hộp giấy cũ có thể dùng để đựng đồ nhỏ.","en":"Old cardboard boxes can be used to store small things."},{"use":"用 + 纸盒子 + 装: dùng hộp giấy đựng","ex":"超市用纸盒子装鸡蛋。","py":"Chāoshì yòng zhǐhézi zhuāng jīdàn.","vi":"Siêu thị dùng hộp giấy để đựng trứng.","en":"The supermarket packs eggs in paper cartons."},{"use":"把 + 纸盒子 + 放进回收箱","ex":"请把纸盒子放进回收箱。","py":"Qǐng bǎ zhǐhézi fàng jìn huíshōu xiāng.","vi":"Xin hãy bỏ hộp giấy vào thùng tái chế.","en":"Please put the paper boxes into the recycling bin."}]},"扔掉":{"en":"to throw away; to discard","exs":[{"use":"làm động từ, V + 掉 chỉ kết quả \"bỏ đi\"; hay dùng với 把","ex":"请把这些旧报纸扔掉。","py":"Qǐng bǎ zhèxiē jiù bàozhǐ rēngdiào.","vi":"Xin hãy vứt những tờ báo cũ này đi.","en":"Please throw away these old newspapers."},{"use":"dùng với 别…, khuyên không nên vứt","ex":"别把吃剩的东西扔掉，明天还可以吃。","py":"Bié bǎ chī shèng de dōngxi rēngdiào, míngtiān hái kěyǐ chī.","vi":"Đừng vứt đồ ăn thừa, ngày mai vẫn ăn được.","en":"Don't throw away the leftovers; we can still eat them tomorrow."},{"use":"câu 把 + 扔掉 + 了, nói về hành động đã xảy ra","ex":"他把坏了的手机扔掉了。","py":"Tā bǎ huài le de shǒujī rēngdiào le.","vi":"Anh ấy đã vứt chiếc điện thoại hỏng đi.","en":"He threw away the broken phone."},{"use":"想 + 扔掉 + tân ngữ (đại từ), nói ý định bỏ đồ cũ","ex":"这件衣服太小了，我想扔掉它。","py":"Zhè jiàn yīfu tài xiǎo le, wǒ xiǎng rēngdiào tā.","vi":"Chiếc áo này nhỏ quá rồi, tôi muốn vứt nó đi.","en":"This shirt is too small; I want to get rid of it."}]},"干净":{"en":"clean; tidy","exs":[{"use":"làm vị ngữ: 很 + 干净","ex":"这个房间很干净。","py":"Zhège fángjiān hěn gānjìng.","vi":"Căn phòng này rất sạch sẽ.","en":"This room is very clean."},{"use":"làm bổ ngữ kết quả: V + 干净 (làm cho sạch)","ex":"请把桌子擦干净。","py":"Qǐng bǎ zhuōzi cā gānjìng.","vi":"Xin hãy lau bàn cho sạch.","en":"Please wipe the table clean."},{"use":"干净的 + danh từ, làm định ngữ","ex":"我想喝一杯干净的水。","py":"Wǒ xiǎng hē yì bēi gānjìng de shuǐ.","vi":"Tôi muốn uống một cốc nước sạch.","en":"I'd like a glass of clean water."},{"use":"bổ ngữ trạng thái: V + 得 + (不) + 干净","ex":"这件衣服洗得不太干净。","py":"Zhè jiàn yīfu xǐ de bú tài gānjìng.","vi":"Chiếc áo này giặt chưa được sạch lắm.","en":"This piece of clothing wasn't washed very clean."}]},"卫生":{"en":"hygiene; sanitation; hygienic","exs":[{"use":"tính từ: 很/不 + 卫生 (sạch sẽ, hợp vệ sinh)","ex":"这家饭馆很卫生。","py":"Zhè jiā fànguǎn hěn wèishēng.","vi":"Quán ăn này rất vệ sinh.","en":"This restaurant is very hygienic."},{"use":"danh từ: 注意 + 卫生 (giữ gìn vệ sinh)","ex":"吃饭前要注意个人卫生。","py":"Chīfàn qián yào zhùyì gèrén wèishēng.","vi":"Trước khi ăn cần chú ý vệ sinh cá nhân.","en":"You should pay attention to personal hygiene before eating."},{"use":"từ ghép 卫生间 (nhà vệ sinh)","ex":"请问，卫生间在哪儿？","py":"Qǐngwèn, wèishēngjiān zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu ạ?","en":"Excuse me, where is the restroom?"},{"use":"不 + 卫生, phủ định, chỉ không hợp vệ sinh","ex":"在路边买的东西不太卫生。","py":"Zài lùbiān mǎi de dōngxi bú tài wèishēng.","vi":"Đồ mua ở ven đường không được vệ sinh lắm.","en":"Food bought by the roadside isn't very hygienic."}]},"速度":{"en":"speed; velocity; pace","exs":[{"use":"làm chủ ngữ, vị ngữ là tính từ (快/慢)","ex":"汽车的速度很快。","py":"Qìchē de sùdù hěn kuài.","vi":"Tốc độ của xe ô tô rất nhanh.","en":"The car's speed is very fast."},{"use":"速度 + 放慢/加快, làm tân ngữ","ex":"请你把说话的速度放慢一点儿。","py":"Qǐng nǐ bǎ shuōhuà de sùdù fàngmàn yìdiǎnr.","vi":"Xin bạn nói chậm lại một chút.","en":"Please slow down the speed of your speech a little."},{"use":"以…的速度: cấu trúc chỉ tốc độ","ex":"他以每小时一百公里的速度开车。","py":"Tā yǐ měi xiǎoshí yì bǎi gōnglǐ de sùdù kāichē.","vi":"Anh ấy lái xe với tốc độ một trăm km mỗi giờ.","en":"He drives at a speed of 100 kilometers per hour."},{"use":"danh từ chỉ nhịp độ công việc, học tập","ex":"他的工作速度比以前快多了。","py":"Tā de gōngzuò sùdù bǐ yǐqián kuài duō le.","vi":"Tốc độ làm việc của anh ấy nhanh hơn trước nhiều.","en":"His work pace is much faster than before."}]},"关灯":{"en":"to turn off the light","exs":[{"use":"động từ li hợp: 关 + 灯, trái nghĩa với 开灯","ex":"睡觉前请关灯。","py":"Shuìjiào qián qǐng guāndēng.","vi":"Trước khi ngủ xin hãy tắt đèn.","en":"Please turn off the light before going to bed."},{"use":"忘了 + 关灯: quên tắt đèn","ex":"出门时别忘了关灯。","py":"Chūmén shí bié wàng le guāndēng.","vi":"Khi ra khỏi nhà đừng quên tắt đèn.","en":"Don't forget to turn off the lights when you leave."},{"use":"关灯以后: mệnh đề chỉ thời điểm sau hành động","ex":"我关灯以后，房间里一下子黑了。","py":"Wǒ guāndēng yǐhòu, fángjiān lǐ yíxiàzi hēi le.","vi":"Sau khi tôi tắt đèn, căn phòng bỗng tối om.","en":"After I turned off the light, the room suddenly went dark."},{"use":"可以 + 关灯 + 吗: hỏi xin phép","ex":"太亮了，可以关灯吗？","py":"Tài liàng le, kěyǐ guāndēng ma?","vi":"Sáng quá, tắt đèn được không?","en":"It's too bright. May I turn off the light?"}]},"既然":{"en":"since; now that; given that","exs":[{"use":"既然…就…: đã…thì (nêu tiền đề đã rõ, rút ra kết luận)","ex":"既然你不舒服，就早点儿回家休息吧。","py":"Jìrán nǐ bù shūfu, jiù zǎodiǎnr huí jiā xiūxi ba.","vi":"Đã không khỏe thì về nhà nghỉ sớm đi.","en":"Since you're not feeling well, go home and rest early."},{"use":"既然…我就…: người nói đưa ra quyết định","ex":"既然你喜欢，我就买给你。","py":"Jìrán nǐ xǐhuan, wǒ jiù mǎi gěi nǐ.","vi":"Đã thích thì anh mua cho em.","en":"Since you like it, I'll buy it for you."},{"use":"既然…就…, dùng với 来了 (đã đến rồi thì…)","ex":"既然来了，就多住几天吧。","py":"Jìrán lái le, jiù duō zhù jǐ tiān ba.","vi":"Đã đến rồi thì ở thêm vài ngày đi.","en":"Since you're already here, stay a few more days."},{"use":"既然…那…: dùng với 那/那么 ở vế sau","ex":"既然下雨了，那我们就不去公园了。","py":"Jìrán xià yǔ le, nà wǒmen jiù bú qù gōngyuán le.","vi":"Đã mưa rồi thì chúng ta không đi công viên nữa.","en":"Since it's raining, we won't go to the park."}]},"停电":{"en":"to have a power outage; power cut","exs":[{"use":"động từ li hợp, thường dùng 了 ở cuối câu","ex":"昨天晚上突然停电了。","py":"Zuótiān wǎnshang tūrán tíngdiàn le.","vi":"Tối qua đột nhiên mất điện.","en":"The power suddenly went out last night."},{"use":"因为停电: nêu nguyên nhân","ex":"因为停电，电梯不能用。","py":"Yīnwèi tíngdiàn, diàntī bù néng yòng.","vi":"Vì mất điện nên thang máy không dùng được.","en":"Because of the power outage, the elevator can't be used."},{"use":"要 + 停电: thông báo sắp cắt điện","ex":"听说明天上午我们这儿要停电。","py":"Tīngshuō míngtiān shàngwǔ wǒmen zhèr yào tíngdiàn.","vi":"Nghe nói sáng mai chỗ chúng tôi sẽ cắt điện.","en":"I heard our area will have a power cut tomorrow morning."},{"use":"停电的时候: mệnh đề thời gian","ex":"停电的时候，家里一片黑。","py":"Tíngdiàn de shíhou, jiā lǐ yí piàn hēi.","vi":"Lúc mất điện, trong nhà tối om.","en":"When the power is out, the house is pitch dark."}]},"得意":{"en":"proud of oneself; pleased with oneself; complacent","exs":[{"use":"tính từ làm vị ngữ: 很 + 得意 (đắc ý, vui vì thành công)","ex":"他考了第一名，看起来很得意。","py":"Tā kǎo le dì yī míng, kàn qǐlái hěn déyì.","vi":"Anh ấy đứng nhất kỳ thi, trông rất đắc ý.","en":"He came first in the exam and looks very pleased with himself."},{"use":"得意地 + V: làm trạng ngữ","ex":"她得意地笑了。","py":"Tā déyì de xiào le.","vi":"Cô ấy cười đắc ý.","en":"She smiled proudly."},{"use":"别太得意: lời nhắc đừng tự mãn","ex":"你别太得意，后面还有更难的比赛。","py":"Nǐ bié tài déyì, hòumian hái yǒu gèng nán de bǐsài.","vi":"Đừng đắc ý quá, phía sau còn những trận đấu khó hơn.","en":"Don't get too smug; there are harder games ahead."},{"use":"对…很得意: đắc ý về điều gì","ex":"他对自己的新车很得意。","py":"Tā duì zìjǐ de xīn chē hěn déyì.","vi":"Anh ấy rất đắc ý về chiếc xe mới của mình.","en":"He is very proud of his new car."}]},"环保":{"en":"environmental protection; environmentally friendly","exs":[{"use":"danh từ: bảo vệ môi trường (viết tắt của 环境保护)","ex":"现在大家都很关心环保。","py":"Xiànzài dàjiā dōu hěn guānxīn huánbǎo.","vi":"Bây giờ mọi người đều rất quan tâm đến bảo vệ môi trường.","en":"Nowadays everyone cares a lot about environmental protection."},{"use":"tính từ: 环保的 (thân thiện với môi trường)","ex":"这种包是环保的，可以用很多次。","py":"Zhè zhǒng bāo shì huánbǎo de, kěyǐ yòng hěn duō cì.","vi":"Loại túi này thân thiện với môi trường, dùng được nhiều lần.","en":"This kind of bag is eco-friendly and can be used many times."},{"use":"环保意识: ý thức bảo vệ môi trường","ex":"孩子们的环保意识越来越强。","py":"Háizimen de huánbǎo yìshí yuè lái yuè qiáng.","vi":"Ý thức bảo vệ môi trường của bọn trẻ ngày càng mạnh.","en":"Children's environmental awareness is getting stronger."},{"use":"từ ghép 环保袋 (túi thân thiện môi trường)","ex":"去超市买东西，最好带环保袋。","py":"Qù chāoshì mǎi dōngxi, zuìhǎo dài huánbǎodài.","vi":"Đi siêu thị mua đồ, tốt nhất nên mang túi bảo vệ môi trường.","en":"When shopping at the supermarket, it's best to bring a reusable bag."}]},"环境保护":{"en":"environmental protection","exs":[{"use":"làm chủ ngữ, vị ngữ thường là 重要","ex":"环境保护很重要。","py":"Huánjìng bǎohù hěn zhòngyào.","vi":"Bảo vệ môi trường rất quan trọng.","en":"Environmental protection is very important."},{"use":"为…出一份力: góp sức vào việc gì","ex":"每个人都应该为环境保护出一份力。","py":"Měi gè rén dōu yīnggāi wèi huánjìng bǎohù chū yí fèn lì.","vi":"Mỗi người đều nên góp một phần sức cho việc bảo vệ môi trường.","en":"Everyone should do their part for environmental protection."},{"use":"环境保护 + 工作: làm định ngữ cho danh từ","ex":"政府正在加强环境保护工作。","py":"Zhèngfǔ zhèngzài jiāqiáng huánjìng bǎohù gōngzuò.","vi":"Chính phủ đang tăng cường công tác bảo vệ môi trường.","en":"The government is strengthening environmental protection work."},{"use":"环境保护的 + N: làm định ngữ có 的","ex":"学校开了一节环境保护的课。","py":"Xuéxiào kāi le yì jié huánjìng bǎohù de kè.","vi":"Trường đã mở một tiết học về bảo vệ môi trường.","en":"The school held a class on environmental protection."}]},"目的":{"en":"purpose; aim; goal","exs":[{"use":"你来…的目的是什么: hỏi mục đích","ex":"你来这儿的目的是什么？","py":"Nǐ lái zhèr de mùdì shì shénme?","vi":"Mục đích bạn đến đây là gì?","en":"What is your purpose in coming here?"},{"use":"…的目的是…: nêu mục đích","ex":"他学汉语的目的是去中国工作。","py":"Tā xué Hànyǔ de mùdì shì qù Zhōngguó gōngzuò.","vi":"Mục đích học tiếng Hán của anh ấy là đến Trung Quốc làm việc.","en":"He studies Chinese in order to work in China."},{"use":"达到目的: đạt được mục đích","ex":"为了达到目的，他每天都努力工作。","py":"Wèile dádào mùdì, tā měitiān dōu nǔlì gōngzuò.","vi":"Để đạt được mục đích, anh ấy ngày nào cũng làm việc chăm chỉ.","en":"To achieve his goal, he works hard every day."},{"use":"từ ghép 目的地 (nơi đến)","ex":"我们明天就能到达目的地了。","py":"Wǒmen míngtiān jiù néng dàodá mùdìdì le.","vi":"Ngày mai chúng ta có thể đến nơi rồi.","en":"We can reach our destination tomorrow."}]},"节约用电":{"en":"to save electricity","exs":[{"use":"cụm động từ: 节约 + 用电, thường dùng sau 要/应该","ex":"夏天空调开太多，我们要节约用电。","py":"Xiàtiān kōngtiáo kāi tài duō, wǒmen yào jiéyuē yòngdiàn.","vi":"Mùa hè bật điều hòa quá nhiều, chúng ta cần tiết kiệm điện.","en":"We use the air conditioner too much in summer; we should save electricity."},{"use":"告诉/要求 + ai + 要节约用电","ex":"老师告诉我们要节约用电。","py":"Lǎoshī gàosu wǒmen yào jiéyuē yòngdiàn.","vi":"Cô giáo bảo chúng tôi phải tiết kiệm điện.","en":"The teacher told us to save electricity."},{"use":"节约用电的办法: làm định ngữ","ex":"离开房间时关灯是节约用电的好办法。","py":"Líkāi fángjiān shí guāndēng shì jiéyuē yòngdiàn de hǎo bànfǎ.","vi":"Tắt đèn khi rời phòng là cách tốt để tiết kiệm điện.","en":"Turning off the light when leaving a room is a good way to save electricity."},{"use":"为了 + 节约用电: nêu mục đích","ex":"为了节约用电，我们家换了新灯。","py":"Wèile jiéyuē yòngdiàn, wǒmen jiā huàn le xīn dēng.","vi":"Để tiết kiệm điện, nhà chúng tôi đã đổi đèn mới.","en":"To save electricity, our family changed to new lights."}]},"变暖":{"en":"to become warmer; to warm up","exs":[{"use":"地球 + 变暖: nói về khí hậu toàn cầu","ex":"地球正在慢慢变暖。","py":"Dìqiú zhèngzài mànmàn biàn nuǎn.","vi":"Trái đất đang dần nóng lên.","en":"The earth is slowly getting warmer."},{"use":"天气 + 变暖: thời tiết ấm lên, thường kèm 了","ex":"三月以后，天气渐渐变暖了。","py":"Sān yuè yǐhòu, tiānqì jiànjiàn biàn nuǎn le.","vi":"Sau tháng Ba, thời tiết dần ấm lên.","en":"After March, the weather gradually warms up."},{"use":"全球变暖: cụm cố định (nóng lên toàn cầu)","ex":"全球变暖让冬天越来越不冷。","py":"Quánqiú biàn nuǎn ràng dōngtiān yuè lái yuè bù lěng.","vi":"Nóng lên toàn cầu khiến mùa đông ngày càng bớt lạnh.","en":"Global warming makes winters less and less cold."},{"use":"chủ ngữ là vật/nơi chốn (phòng, nước…)","ex":"开了暖气以后，房间很快就变暖了。","py":"Kāi le nuǎnqì yǐhòu, fángjiān hěn kuài jiù biàn nuǎn le.","vi":"Sau khi bật lò sưởi, căn phòng nhanh chóng ấm lên.","en":"After the heating was turned on, the room warmed up quickly."}]},"关注":{"en":"to follow closely; to pay attention to; to be concerned about","exs":[{"use":"V + tân ngữ, mức độ mạnh hơn 关心","ex":"大家都很关注这次比赛。","py":"Dàjiā dōu hěn guānzhù zhè cì bǐsài.","vi":"Mọi người đều rất chú ý đến cuộc thi lần này.","en":"Everyone is paying close attention to this competition."},{"use":"受到 + 关注: danh từ, \"được quan tâm\"","ex":"这个问题受到了很多人的关注。","py":"Zhège wèntí shòudào le hěn duō rén de guānzhù.","vi":"Vấn đề này được nhiều người quan tâm.","en":"This issue has attracted a lot of people's attention."},{"use":"关注 + tin tức, thông tin","ex":"我每天都关注网上的新闻。","py":"Wǒ měitiān dōu guānzhù wǎngshàng de xīnwén.","vi":"Mỗi ngày tôi đều theo dõi tin tức trên mạng.","en":"I follow the online news every day."},{"use":"请 + 多关注: lời đề nghị","ex":"请大家多关注孩子的健康。","py":"Qǐng dàjiā duō guānzhù háizi de jiànkāng.","vi":"Mong mọi người quan tâm nhiều hơn đến sức khỏe của trẻ.","en":"Please everyone pay more attention to children's health."}]},"故意":{"en":"deliberately; on purpose; intentionally","exs":[{"use":"不是故意的: phủ định, xin lỗi","ex":"对不起，我不是故意的。","py":"Duìbuqǐ, wǒ bú shì gùyì de.","vi":"Xin lỗi, tôi không cố ý.","en":"I'm sorry, I didn't do it on purpose."},{"use":"故意 + V: phó từ đứng trước động từ","ex":"你是不是故意不接我的电话？","py":"Nǐ shì bu shì gùyì bù jiē wǒ de diànhuà?","vi":"Có phải bạn cố ý không nghe điện thoại của tôi không?","en":"Are you deliberately not answering my calls?"},{"use":"故意 + V, kèm mục đích phía sau","ex":"她故意不说话，想让我先道歉。","py":"Tā gùyì bù shuōhuà, xiǎng ràng wǒ xiān dàoqiàn.","vi":"Cô ấy cố tình không nói gì, muốn tôi xin lỗi trước.","en":"She stayed silent on purpose, wanting me to apologize first."},{"use":"是…故意…的: nhấn mạnh hành vi có chủ ý","ex":"他是故意迟到的，因为不想参加会议。","py":"Tā shì gùyì chídào de, yīnwèi bù xiǎng cānjiā huìyì.","vi":"Anh ấy cố ý đến muộn vì không muốn dự họp.","en":"He was late on purpose because he didn't want to attend the meeting."}]},"整理":{"en":"to sort out; to tidy up; to organize","exs":[{"use":"整理 + nơi chốn: dọn dẹp, sắp xếp","ex":"周末我要整理一下房间。","py":"Zhōumò wǒ yào zhěnglǐ yíxià fángjiān.","vi":"Cuối tuần tôi muốn dọn dẹp phòng một chút.","en":"I'm going to tidy up my room this weekend."},{"use":"整理 + 好 + 行李: sắp xếp hành lý","ex":"明天要出发，你整理好行李了吗？","py":"Míngtiān yào chūfā, nǐ zhěnglǐ hǎo xínglǐ le ma?","vi":"Mai phải khởi hành, bạn đã sắp xếp xong hành lý chưa?","en":"We leave tomorrow; have you packed your luggage?"},{"use":"整理 + 资料: sắp xếp tài liệu, thông tin","ex":"他正在整理会议的资料。","py":"Tā zhèngzài zhěnglǐ huìyì de zīliào.","vi":"Anh ấy đang sắp xếp tài liệu cuộc họp.","en":"He is organizing the meeting materials."},{"use":"把 + O + 整理好: câu chữ 把","ex":"请把书整理好，放回书架上。","py":"Qǐng bǎ shū zhěnglǐ hǎo, fàng huí shūjià shang.","vi":"Xin hãy sắp xếp sách cho gọn rồi để lại lên giá.","en":"Please tidy the books and put them back on the shelf."}]},"弄清楚":{"en":"to make clear; to figure out; to get to the bottom of","exs":[{"use":"弄清楚 + tân ngữ: làm rõ vấn đề","ex":"我们必须先弄清楚问题在哪儿。","py":"Wǒmen bìxū xiān nòng qīngchu wèntí zài nǎr.","vi":"Chúng ta phải làm rõ trước xem vấn đề nằm ở đâu.","en":"We must first figure out where the problem is."},{"use":"弄清楚 + câu nghi vấn (为什么…)","ex":"你弄清楚他为什么生气了吗？","py":"Nǐ nòng qīngchu tā wèishénme shēngqì le ma?","vi":"Bạn đã tìm hiểu rõ tại sao anh ấy giận chưa?","en":"Have you found out why he is angry?"},{"use":"没(有) + 弄清楚: phủ định bằng 没","ex":"这个词的意思我还没弄清楚。","py":"Zhège cí de yìsi wǒ hái méi nòng qīngchu.","vi":"Nghĩa của từ này tôi vẫn chưa hiểu rõ.","en":"I still haven't figured out the meaning of this word."},{"use":"把 + O + 弄清楚: câu chữ 把","ex":"请你把时间和地点弄清楚再告诉我。","py":"Qǐng nǐ bǎ shíjiān hé dìdiǎn nòng qīngchu zài gàosu wǒ.","vi":"Xin bạn làm rõ thời gian và địa điểm rồi hãy báo cho tôi.","en":"Please make sure of the time and place before telling me."}]},"关心":{"en":"to care about; to be concerned about; concern","exs":[{"use":"V + tân ngữ (người), biểu thị quan tâm, chăm sóc","ex":"我们应该关心孩子。","py":"Wǒmen yīnggāi guānxīn háizi.","vi":"Chúng ta nên quan tâm trẻ em.","en":"We should care about children."},{"use":"关心 + sức khỏe, cuộc sống của ai","ex":"妈妈很关心我的身体。","py":"Māma hěn guānxīn wǒ de shēntǐ.","vi":"Mẹ rất quan tâm đến sức khỏe của tôi.","en":"My mom cares a lot about my health."},{"use":"làm danh từ: 你的关心 (sự quan tâm)","ex":"谢谢你的关心，我已经好多了。","py":"Xièxie nǐ de guānxīn, wǒ yǐjīng hǎo duō le.","vi":"Cảm ơn sự quan tâm của bạn, tôi đỡ nhiều rồi.","en":"Thank you for your concern; I'm much better now."},{"use":"对…很关心: cấu trúc 对 + ai + 关心","ex":"他对朋友总是很关心。","py":"Tā duì péngyou zǒngshì hěn guānxīn.","vi":"Anh ấy luôn rất quan tâm đến bạn bè.","en":"He is always very caring toward his friends."}]},"合适":{"en":"suitable; appropriate; fitting","exs":[{"use":"làm vị ngữ: 很 + 合适 (vừa vặn, phù hợp)","ex":"这双鞋大小很合适。","py":"Zhè shuāng xié dàxiǎo hěn héshì.","vi":"Đôi giày này cỡ rất vừa.","en":"This pair of shoes fits just right."},{"use":"合适的 + N: làm định ngữ","ex":"我还没找到合适的工作。","py":"Wǒ hái méi zhǎodào héshì de gōngzuò.","vi":"Tôi vẫn chưa tìm được công việc phù hợp.","en":"I haven't found a suitable job yet."},{"use":"不合适: không thích hợp, không phù hợp ngữ cảnh","ex":"在图书馆大声说话不太合适。","py":"Zài túshūguǎn dàshēng shuōhuà bú tài héshì.","vi":"Nói to trong thư viện không được thích hợp lắm.","en":"It's not very appropriate to talk loudly in the library."},{"use":"V + 合适 / 你穿很合适: nói về trang phục","ex":"这件衣服你穿很合适。","py":"Zhè jiàn yīfu nǐ chuān hěn héshì.","vi":"Chiếc áo này bạn mặc rất hợp.","en":"This piece of clothing suits you well."}]},"骗":{"en":"to deceive; to cheat; to lie to","exs":[{"use":"骗 + người: lừa ai","ex":"他骗了我，说自己没有钱。","py":"Tā piàn le wǒ, shuō zìjǐ méiyǒu qián.","vi":"Anh ta lừa tôi, nói là mình không có tiền.","en":"He lied to me, saying he had no money."},{"use":"被 + 骗: bị lừa","ex":"我在网上买东西被骗了。","py":"Wǒ zài wǎngshàng mǎi dōngxi bèi piàn le.","vi":"Tôi mua đồ trên mạng bị lừa.","en":"I got cheated when shopping online."},{"use":"骗人: cụm cố định, nói người khác nói dối","ex":"别骗人了，我才不信呢。","py":"Bié piàn rén le, wǒ cái bú xìn ne.","vi":"Đừng lừa người ta nữa, tôi mới không tin đâu.","en":"Stop lying; I won't believe it."},{"use":"骗 + ai + tiền: hai tân ngữ (lừa tiền)","ex":"有人打电话骗了他一千块钱。","py":"Yǒu rén dǎ diànhuà piàn le tā yì qiān kuài qián.","vi":"Có người gọi điện lừa của anh ấy một nghìn tệ.","en":"Someone scammed him out of a thousand yuan over the phone."}]},"判断能力":{"en":"ability to judge; judgment","exs":[{"use":"làm chủ ngữ, vị ngữ là 强/弱","ex":"孩子的判断能力还不强。","py":"Háizi de pànduàn nénglì hái bù qiáng.","vi":"Khả năng phán đoán của trẻ con còn chưa mạnh.","en":"Children's ability to judge is still not strong."},{"use":"提高 + 判断能力: nâng cao khả năng","ex":"多读书可以提高判断能力。","py":"Duō dú shū kěyǐ tígāo pànduàn nénglì.","vi":"Đọc nhiều sách có thể nâng cao khả năng phán đoán.","en":"Reading more can improve your judgment."},{"use":"有 + 很强的 + 判断能力","ex":"他很聪明，有很强的判断能力。","py":"Tā hěn cōngming, yǒu hěn qiáng de pànduàn nénglì.","vi":"Anh ấy rất thông minh, có khả năng phán đoán rất tốt.","en":"He is smart and has strong judgment."},{"use":"要有自己的判断能力: yêu cầu, lời khuyên","ex":"网上的信息很多，我们要有自己的判断能力。","py":"Wǎngshàng de xìnxī hěn duō, wǒmen yào yǒu zìjǐ de pànduàn nénglì.","vi":"Thông tin trên mạng rất nhiều, chúng ta phải có khả năng phán đoán của riêng mình.","en":"There is a lot of information online, so we need our own judgment."}]},"假话":{"en":"lie; falsehood","exs":[{"use":"说假话: nói dối","ex":"他从来不说假话。","py":"Tā cónglái bù shuō jiǎhuà.","vi":"Anh ấy chưa bao giờ nói dối.","en":"He never tells lies."},{"use":"说假话 + 是不对的: nhận xét đạo đức","ex":"小孩子说假话是不对的。","py":"Xiǎo háizi shuō jiǎhuà shì bú duì de.","vi":"Trẻ con nói dối là không đúng.","en":"It is wrong for children to tell lies."},{"use":"是假话: làm vị ngữ (đó là lời nói dối)","ex":"我一听就知道他说的是假话。","py":"Wǒ yì tīng jiù zhīdào tā shuō de shì jiǎhuà.","vi":"Vừa nghe tôi đã biết anh ta nói dối.","en":"As soon as I heard it, I knew he was lying."},{"use":"对比 真话 / 假话 (lời thật / lời dối)","ex":"我喜欢听真话，不喜欢听假话。","py":"Wǒ xǐhuan tīng zhēnhuà, bù xǐhuan tīng jiǎhuà.","vi":"Tôi thích nghe lời thật, không thích nghe lời dối.","en":"I like hearing the truth, not lies."}]},"好动":{"en":"active; restless; lively (fond of moving around)","exs":[{"use":"làm vị ngữ: 比较/很 + 好动","ex":"男孩子一般比较好动。","py":"Nánháizi yìbān bǐjiào hàodòng.","vi":"Con trai thường hiếu động hơn.","en":"Boys are generally more active."},{"use":"很好动, kèm bổ ngữ mô tả (一刻也坐不住)","ex":"我的儿子很好动，一刻也坐不住。","py":"Wǒ de érzi hěn hàodòng, yí kè yě zuò bú zhù.","vi":"Con trai tôi rất hiếu động, một lúc cũng không ngồi yên được.","en":"My son is very active and can't sit still for a moment."},{"use":"好动的 + N: làm định ngữ","ex":"好动的孩子需要多做运动。","py":"Hàodòng de háizi xūyào duō zuò yùndòng.","vi":"Trẻ hiếu động cần vận động nhiều.","en":"Active children need more exercise."},{"use":"对比 trước đây / bây giờ","ex":"他小时候好动，现在却很安静。","py":"Tā xiǎoshíhou hàodòng, xiànzài què hěn ānjìng.","vi":"Hồi nhỏ cậu ấy hiếu động, bây giờ lại rất trầm lặng.","en":"He was very active as a child, but now he is quiet."}]},"年龄段":{"en":"age group; age range","exs":[{"use":"各个年龄段: mọi lứa tuổi","ex":"这本书适合各个年龄段的人。","py":"Zhè běn shū shìhé gègè niánlíngduàn de rén.","vi":"Cuốn sách này phù hợp với mọi lứa tuổi.","en":"This book suits people of all age groups."},{"use":"不同年龄段: các độ tuổi khác nhau","ex":"不同年龄段的孩子，爱好也不一样。","py":"Bùtóng niánlíngduàn de háizi, àihào yě bù yíyàng.","vi":"Trẻ em ở các độ tuổi khác nhau thì sở thích cũng khác nhau.","en":"Children in different age groups have different hobbies."},{"use":"哪个年龄段: câu hỏi","ex":"你们公司哪个年龄段的客人最多？","py":"Nǐmen gōngsī nǎge niánlíngduàn de kèrén zuì duō?","vi":"Khách hàng của công ty bạn thuộc độ tuổi nào nhiều nhất?","en":"Which age group do most of your company's customers belong to?"},{"use":"这个年龄段: chỉ độ tuổi đã nói tới","ex":"这个年龄段的孩子特别喜欢问问题。","py":"Zhège niánlíngduàn de háizi tèbié xǐhuan wèn wèntí.","vi":"Trẻ ở độ tuổi này đặc biệt thích đặt câu hỏi.","en":"Children of this age especially love asking questions."}]},"批评":{"en":"to criticize; criticism","exs":[{"use":"động từ: 批评 + người","ex":"老师批评了他。","py":"Lǎoshī pīpíng le tā.","vi":"Cô giáo đã phê bình cậu ấy.","en":"The teacher criticized him."},{"use":"被…批评: câu bị động","ex":"他迟到了，被经理批评了。","py":"Tā chídào le, bèi jīnglǐ pīpíng le.","vi":"Anh ấy đi muộn nên bị giám đốc phê bình.","en":"He was late and got criticized by the manager."},{"use":"làm danh từ: 接受 + 批评","ex":"他很能接受别人的批评。","py":"Tā hěn néng jiēshòu biérén de pīpíng.","vi":"Anh ấy rất biết tiếp thu lời phê bình của người khác.","en":"He is good at accepting other people's criticism."},{"use":"批评 + 孩子 + 时: phương pháp giáo dục","ex":"批评孩子时，要注意方法。","py":"Pīpíng háizi shí, yào zhùyì fāngfǎ.","vi":"Khi phê bình trẻ cần chú ý phương pháp.","en":"When criticizing a child, you should pay attention to how you do it."}]},"骄傲":{"en":"arrogant; proud; pride","exs":[{"use":"nghĩa xấu: kiêu ngạo, tự mãn","ex":"取得好成绩以后，不要骄傲。","py":"Qǔdé hǎo chéngjì yǐhòu, búyào jiāo'ào.","vi":"Sau khi đạt thành tích tốt, đừng kiêu ngạo.","en":"Don't be arrogant after getting good results."},{"use":"nghĩa tốt: 为…感到骄傲 (tự hào về)","ex":"我为你感到骄傲。","py":"Wǒ wèi nǐ gǎndào jiāo'ào.","vi":"Mẹ tự hào về con.","en":"I am proud of you."},{"use":"làm danh từ: …的骄傲 (niềm tự hào)","ex":"他是我们全家的骄傲。","py":"Tā shì wǒmen quánjiā de jiāo'ào.","vi":"Cậu ấy là niềm tự hào của cả nhà chúng tôi.","en":"He is the pride of our whole family."},{"use":"thành ngữ/câu nói: 骄傲使人落后","ex":"骄傲使人落后，谦虚使人进步。","py":"Jiāo'ào shǐ rén luòhòu, qiānxū shǐ rén jìnbù.","vi":"Kiêu ngạo khiến người ta tụt hậu, khiêm tốn khiến người ta tiến bộ.","en":"Pride makes people fall behind; modesty helps them progress."}]},"害羞":{"en":"shy; bashful; embarrassed","exs":[{"use":"làm vị ngữ: 会/很 + 害羞","ex":"她在很多人面前说话会害羞。","py":"Tā zài hěn duō rén miànqián shuōhuà huì hàixiū.","vi":"Cô ấy nói chuyện trước nhiều người thì ngại.","en":"She gets shy when speaking in front of many people."},{"use":"害羞地 + V: làm trạng ngữ","ex":"小女孩害羞地低下了头。","py":"Xiǎo nǚhái hàixiū de dī xià le tóu.","vi":"Cô bé ngượng ngùng cúi đầu xuống.","en":"The little girl bashfully lowered her head."},{"use":"别害羞: lời khuyên, động viên","ex":"别害羞，大胆地用汉语说吧。","py":"Bié hàixiū, dàdǎn de yòng Hànyǔ shuō ba.","vi":"Đừng ngại, cứ mạnh dạn nói tiếng Hán đi.","en":"Don't be shy; speak Chinese boldly."},{"use":"很害羞 + nêu hệ quả (不敢…)","ex":"他很害羞，不敢去问老师。","py":"Tā hěn hàixiū, bù gǎn qù wèn lǎoshī.","vi":"Cậu ấy rất nhút nhát, không dám đi hỏi thầy giáo.","en":"He is very shy and doesn't dare to ask the teacher."}]},"停下":{"en":"to stop; to halt; to pause","exs":[{"use":"V + 下: dừng hẳn lại (xe, người)","ex":"车突然停下了。","py":"Chē tūrán tíng xià le.","vi":"Xe đột nhiên dừng lại.","en":"The car suddenly stopped."},{"use":"停下来 + V: dừng việc đang làm để làm việc khác","ex":"累了就停下来休息一会儿吧。","py":"Lèi le jiù tíng xiàlái xiūxi yíhuìr ba.","vi":"Mệt thì dừng lại nghỉ một lát đi.","en":"If you're tired, stop and rest for a while."},{"use":"câu mệnh lệnh: 请停下","ex":"前面是红灯，请停下。","py":"Qiánmiàn shì hóngdēng, qǐng tíng xià.","vi":"Phía trước là đèn đỏ, xin hãy dừng lại.","en":"There's a red light ahead; please stop."},{"use":"突然停下, chỉ hành động đang liên tục bị ngắt","ex":"他说着说着，突然停下，看着窗外。","py":"Tā shuōzhe shuōzhe, tūrán tíng xià, kànzhe chuāngwài.","vi":"Anh ấy đang nói thì đột nhiên ngừng lại, nhìn ra ngoài cửa sổ.","en":"He was talking, then suddenly stopped and looked out the window."}]},"儿童":{"en":"children; kids","exs":[{"use":"danh từ: trẻ em (trang trọng hơn 小孩)","ex":"六月一日是国际儿童节。","py":"Liù yuè yī rì shì Guójì Értóngjié.","vi":"Ngày 1 tháng 6 là Quốc tế Thiếu nhi.","en":"June 1st is International Children's Day."},{"use":"儿童 + 票/用品: dùng làm định ngữ","ex":"儿童坐公交车不用买票。","py":"Értóng zuò gōngjiāochē bú yòng mǎi piào.","vi":"Trẻ em đi xe buýt không cần mua vé.","en":"Children don't need to buy a ticket for the bus."},{"use":"儿童 + 玩具: danh từ ghép trong mua sắm","ex":"这家商店专门卖儿童玩具。","py":"Zhè jiā shāngdiàn zhuānmén mài értóng wánjù.","vi":"Cửa hàng này chuyên bán đồ chơi trẻ em.","en":"This store specializes in children's toys."},{"use":"保护 + 儿童: làm tân ngữ","ex":"我们要保护儿童的健康。","py":"Wǒmen yào bǎohù értóng de jiànkāng.","vi":"Chúng ta phải bảo vệ sức khỏe của trẻ em.","en":"We must protect children's health."}]},"左右":{"en":"about; approximately; around (after numbers); left and right","exs":[{"use":"đứng sau số lượng, chỉ ước chừng","ex":"这个孩子大概一米二左右。","py":"Zhège háizi dàgài yì mǐ èr zuǒyòu.","vi":"Đứa bé này cao khoảng một mét hai.","en":"This child is about 1.2 meters tall."},{"use":"đứng sau mốc thời gian: khoảng…","ex":"我们八点左右出发，好吗？","py":"Wǒmen bā diǎn zuǒyòu chūfā, hǎo ma?","vi":"Chúng ta khoảng tám giờ xuất phát, được không?","en":"Let's set off around eight o'clock, okay?"},{"use":"đứng sau tuổi tác: khoảng…tuổi","ex":"他三十岁左右，个子很高。","py":"Tā sānshí suì zuǒyòu, gèzi hěn gāo.","vi":"Anh ấy khoảng ba mươi tuổi, dáng người rất cao.","en":"He is around thirty years old and quite tall."},{"use":"nghĩa 2: phương hướng trái và phải","ex":"过马路时要先看左右。","py":"Guò mǎlù shí yào xiān kàn zuǒyòu.","vi":"Khi qua đường phải nhìn trái phải trước.","en":"Look left and right before crossing the road."}]},"粗心":{"en":"careless; thoughtless","exs":[{"use":"làm vị ngữ: 太/很 + 粗心","ex":"他太粗心了，把名字写错了。","py":"Tā tài cūxīn le, bǎ míngzi xiěcuò le.","vi":"Cậu ấy bất cẩn quá, viết sai cả tên.","en":"He was so careless that he wrote his name wrong."},{"use":"不能/别 + 粗心: lời nhắc nhở","ex":"做作业不能粗心。","py":"Zuò zuòyè bù néng cūxīn.","vi":"Làm bài tập không được cẩu thả.","en":"You mustn't be careless when doing homework."},{"use":"因为粗心: nêu nguyên nhân","ex":"因为粗心，我忘了带钥匙。","py":"Yīnwèi cūxīn, wǒ wàng le dài yàoshi.","vi":"Vì sơ ý nên tôi quên mang chìa khóa.","en":"Because I was careless, I forgot to bring my key."},{"use":"粗心的 + N: làm định ngữ","ex":"他是个粗心的人，经常丢东西。","py":"Tā shì ge cūxīn de rén, jīngcháng diū dōngxi.","vi":"Anh ấy là người hay sơ ý, thường làm mất đồ.","en":"He is a careless person who often loses things."}]},"一边":{"en":"at the same time (doing two things); one side","exs":[{"use":"一边…一边…: vừa…vừa… (hai hành động đồng thời)","ex":"他一边吃饭一边看电视。","py":"Tā yìbiān chīfàn yìbiān kàn diànshì.","vi":"Anh ấy vừa ăn cơm vừa xem tivi.","en":"He watches TV while eating."},{"use":"一边…一边…: hai động từ cùng chủ ngữ","ex":"她一边走路一边听音乐。","py":"Tā yìbiān zǒulù yìbiān tīng yīnyuè.","vi":"Cô ấy vừa đi bộ vừa nghe nhạc.","en":"She listens to music while walking."},{"use":"不要 + 一边…一边…: lời khuyên, cảnh báo","ex":"不要一边开车一边打电话。","py":"Búyào yìbiān kāichē yìbiān dǎ diànhuà.","vi":"Đừng vừa lái xe vừa gọi điện thoại.","en":"Don't talk on the phone while driving."},{"use":"nghĩa 2: danh từ chỉ phương vị \"một bên\"","ex":"请站在路的一边。","py":"Qǐng zhàn zài lù de yìbiān.","vi":"Xin hãy đứng sang một bên đường.","en":"Please stand on one side of the road."}]},"弹钢琴":{"en":"to play the piano","exs":[{"use":"động từ + tân ngữ: 弹 + 钢琴","ex":"她每天都弹钢琴。","py":"Tā měitiān dōu tán gāngqín.","vi":"Cô ấy ngày nào cũng chơi đàn piano.","en":"She plays the piano every day."},{"use":"从…开始弹钢琴: bắt đầu học từ lúc nào","ex":"我女儿从五岁开始弹钢琴。","py":"Wǒ nǚ'ér cóng wǔ suì kāishǐ tán gāngqín.","vi":"Con gái tôi bắt đầu chơi piano từ năm tuổi.","en":"My daughter started playing the piano at the age of five."},{"use":"喜欢 + 弹钢琴: nói về sở thích","ex":"他喜欢弹钢琴，也喜欢唱歌。","py":"Tā xǐhuan tán gāngqín, yě xǐhuan chànggē.","vi":"Anh ấy thích chơi piano, cũng thích hát.","en":"He likes playing the piano and also likes singing."},{"use":"弹钢琴的 + N: mệnh đề làm định ngữ","ex":"弹钢琴的那个女孩是我的同学。","py":"Tán gāngqín de nàge nǚhái shì wǒ de tóngxué.","vi":"Cô gái đang chơi piano kia là bạn học của tôi.","en":"The girl playing the piano is my classmate."}]},"男孩子":{"en":"boy","exs":[{"use":"danh từ: đếm bằng 个","ex":"他们家有两个男孩子。","py":"Tāmen jiā yǒu liǎng ge nánháizi.","vi":"Nhà họ có hai bé trai.","en":"They have two boys in their family."},{"use":"nói về đặc điểm chung của con trai","ex":"男孩子一般喜欢踢足球。","py":"Nánháizi yìbān xǐhuan tī zúqiú.","vi":"Con trai thường thích đá bóng.","en":"Boys generally like playing soccer."},{"use":"mệnh đề định ngữ + 男孩子","ex":"那个穿蓝衣服的男孩子是我弟弟。","py":"Nàge chuān lán yīfu de nánháizi shì wǒ dìdi.","vi":"Cậu bé mặc áo xanh kia là em trai tôi.","en":"The boy in the blue clothes is my younger brother."},{"use":"đối chiếu với 女孩子","ex":"我们班男孩子比女孩子多。","py":"Wǒmen bān nánháizi bǐ nǚháizi duō.","vi":"Lớp chúng tôi con trai nhiều hơn con gái.","en":"There are more boys than girls in our class."}]},"表演":{"en":"to perform; performance; to act","exs":[{"use":"động từ: 表演 + 节目","ex":"孩子们在晚会上表演节目。","py":"Háizimen zài wǎnhuì shang biǎoyǎn jiémù.","vi":"Bọn trẻ biểu diễn tiết mục trong buổi liên hoan.","en":"The children perform acts at the party."},{"use":"làm danh từ: 精彩的表演","ex":"今天的表演非常精彩。","py":"Jīntiān de biǎoyǎn fēicháng jīngcǎi.","vi":"Buổi biểu diễn hôm nay vô cùng đặc sắc.","en":"Today's performance was wonderful."},{"use":"表演 + 给 + ai + xem","ex":"她给大家表演了一段舞蹈。","py":"Tā gěi dàjiā biǎoyǎn le yí duàn wǔdǎo.","vi":"Cô ấy biểu diễn cho mọi người một điệu múa.","en":"She performed a dance for everyone."},{"use":"bổ ngữ trạng thái: 表演得…","ex":"他表演得很自然。","py":"Tā biǎoyǎn de hěn zìrán.","vi":"Anh ấy diễn rất tự nhiên.","en":"He acts very naturally."}]},"真棒":{"en":"great; awesome; terrific","exs":[{"use":"bổ ngữ trạng thái: V + 得 + 真棒 (khen)","ex":"你的汉语说得真棒！","py":"Nǐ de Hànyǔ shuō de zhēn bàng!","vi":"Tiếng Hán của bạn nói giỏi quá!","en":"Your Chinese is great!"},{"use":"câu cảm thán đứng độc lập","ex":"真棒！你又考了第一名！","py":"Zhēn bàng! Nǐ yòu kǎo le dì yī míng!","vi":"Tuyệt quá! Bạn lại đứng nhất rồi!","en":"Awesome! You came first again!"},{"use":"làm vị ngữ nhận xét ý tưởng","ex":"这个主意真棒，我们就这么办吧。","py":"Zhège zhǔyi zhēn bàng, wǒmen jiù zhème bàn ba.","vi":"Ý này hay quá, chúng ta cứ làm như vậy đi.","en":"This idea is great; let's do it this way."},{"use":"nhận xét phim, sự việc","ex":"昨天的电影真棒，我还想再看一次。","py":"Zuótiān de diànyǐng zhēn bàng, wǒ hái xiǎng zài kàn yí cì.","vi":"Bộ phim hôm qua hay tuyệt, tôi còn muốn xem lại.","en":"Yesterday's movie was fantastic; I want to watch it again."}]},"孙子":{"en":"grandson (son's son)","exs":[{"use":"danh từ chỉ quan hệ: số lượng + 个 + 孙子","ex":"爷爷有三个孙子。","py":"Yéye yǒu sān ge sūnzi.","vi":"Ông nội có ba đứa cháu trai.","en":"Grandpa has three grandsons."},{"use":"我的/他的 + 孙子: nói về tuổi","ex":"我的孙子今年五岁了。","py":"Wǒ de sūnzi jīnnián wǔ suì le.","vi":"Cháu nội của tôi năm nay năm tuổi rồi.","en":"My grandson is five years old this year."},{"use":"带 + 孙子: ông bà trông cháu","ex":"爷爷最爱带孙子去公园玩。","py":"Yéye zuì ài dài sūnzi qù gōngyuán wán.","vi":"Ông nội thích nhất là dẫn cháu đi công viên chơi.","en":"Grandpa loves taking his grandson to the park."},{"use":"孙子 + 和 + 孙女 (cháu trai và cháu gái)","ex":"奶奶给孙子和孙女都买了新衣服。","py":"Nǎinai gěi sūnzi hé sūnnǚ dōu mǎi le xīn yīfu.","vi":"Bà nội mua quần áo mới cho cả cháu trai và cháu gái.","en":"Grandma bought new clothes for both her grandson and granddaughter."}]},"去年":{"en":"last year","exs":[{"use":"làm trạng ngữ thời gian đứng trước động từ","ex":"我去年去了北京。","py":"Wǒ qùnián qù le Běijīng.","vi":"Năm ngoái tôi đã đến Bắc Kinh.","en":"I went to Beijing last year."},{"use":"去年的 + N: làm định ngữ","ex":"这是我去年的照片。","py":"Zhè shì wǒ qùnián de zhàopiàn.","vi":"Đây là ảnh của tôi hồi năm ngoái.","en":"This is my photo from last year."},{"use":"比去年: so sánh với năm ngoái","ex":"今年的夏天比去年热多了。","py":"Jīnnián de xiàtiān bǐ qùnián rè duō le.","vi":"Mùa hè năm nay nóng hơn năm ngoái nhiều.","en":"This summer is much hotter than last year."},{"use":"是…的 + 去年夏天: nhấn mạnh thời gian","ex":"我们是去年夏天认识的。","py":"Wǒmen shì qùnián xiàtiān rènshi de.","vi":"Chúng tôi quen nhau vào mùa hè năm ngoái.","en":"We met last summer."}]},"寒假":{"en":"winter vacation","exs":[{"use":"làm chủ ngữ/thời gian: hỏi dự định","ex":"寒假你有什么打算？","py":"Hánjià nǐ yǒu shénme dǎsuàn?","vi":"Kỳ nghỉ đông bạn có dự định gì?","en":"What are your plans for the winter vacation?"},{"use":"放寒假: bắt đầu nghỉ đông","ex":"学校下个星期就放寒假了。","py":"Xuéxiào xià ge xīngqī jiù fàng hánjià le.","vi":"Tuần sau trường sẽ nghỉ đông.","en":"The school's winter break starts next week."},{"use":"寒假 + dự định đi chơi","ex":"今年寒假，我想去海南旅游。","py":"Jīnnián hánjià, wǒ xiǎng qù Hǎinán lǚyóu.","vi":"Kỳ nghỉ đông năm nay tôi muốn đi du lịch Hải Nam.","en":"This winter vacation, I want to travel to Hainan."},{"use":"寒假作业: danh từ ghép","ex":"老师给我们留了很多寒假作业。","py":"Lǎoshī gěi wǒmen liú le hěn duō hánjià zuòyè.","vi":"Cô giáo giao cho chúng tôi rất nhiều bài tập nghỉ đông.","en":"The teacher gave us a lot of winter vacation homework."}]},"新年":{"en":"New Year","exs":[{"use":"lời chúc: 新年快乐","ex":"新年快乐！祝你身体健康！","py":"Xīnnián kuàilè! Zhù nǐ shēntǐ jiànkāng!","vi":"Chúc mừng năm mới! Chúc bạn mạnh khỏe!","en":"Happy New Year! Wishing you good health!"},{"use":"新年的时候: mệnh đề thời gian","ex":"新年的时候，我们全家人在一起吃饭。","py":"Xīnnián de shíhou, wǒmen quánjiā rén zài yìqǐ chīfàn.","vi":"Vào dịp năm mới, cả nhà chúng tôi cùng ăn cơm.","en":"At New Year, our whole family eats together."},{"use":"新年到了: câu mô tả","ex":"新年到了，我有一个新的愿望。","py":"Xīnnián dào le, wǒ yǒu yí ge xīn de yuànwàng.","vi":"Năm mới đến rồi, tôi có một điều ước mới.","en":"The new year has come, and I have a new wish."},{"use":"新年礼物: danh từ ghép","ex":"爸爸送给我一份新年礼物。","py":"Bàba sòng gěi wǒ yí fèn xīnnián lǐwù.","vi":"Bố tặng tôi một món quà năm mới.","en":"Dad gave me a New Year gift."}]},"晚会":{"en":"evening party; gala","exs":[{"use":"danh từ: 有 + 晚会 (có buổi tối liên hoan)","ex":"今天晚上学校有新年晚会。","py":"Jīntiān wǎnshang xuéxiào yǒu xīnnián wǎnhuì.","vi":"Tối nay trường có buổi dạ hội mừng năm mới.","en":"Tonight there is a New Year party at school."},{"use":"参加晚会: tham dự","ex":"你要不要参加我们的晚会？","py":"Nǐ yào bu yào cānjiā wǒmen de wǎnhuì?","vi":"Bạn có muốn tham dự buổi liên hoan của chúng tôi không?","en":"Would you like to join our party?"},{"use":"开晚会: tổ chức","ex":"周末我们公司要开一个晚会。","py":"Zhōumò wǒmen gōngsī yào kāi yí ge wǎnhuì.","vi":"Cuối tuần công ty chúng tôi sẽ tổ chức một buổi liên hoan.","en":"Our company is holding a party this weekend."},{"use":"晚会上: chỉ khung cảnh","ex":"晚会上大家又唱歌又跳舞，非常热闹。","py":"Wǎnhuì shang dàjiā yòu chànggē yòu tiàowǔ, fēicháng rènao.","vi":"Trong buổi liên hoan mọi người vừa hát vừa nhảy, rất náo nhiệt.","en":"At the party everyone sang and danced; it was very lively."}]},"可爱":{"en":"cute; lovely; adorable","exs":[{"use":"làm vị ngữ: 很/非常 + 可爱","ex":"这个小女孩非常可爱。","py":"Zhège xiǎo nǚhái fēicháng kě'ài.","vi":"Cô bé này vô cùng đáng yêu.","en":"This little girl is very cute."},{"use":"可爱的 + N: làm định ngữ","ex":"我养了一只可爱的小狗。","py":"Wǒ yǎng le yì zhī kě'ài de xiǎo gǒu.","vi":"Tôi nuôi một chú chó nhỏ đáng yêu.","en":"I have a lovely little dog."},{"use":"V + 起来 + 很可爱","ex":"大家都觉得他笑起来很可爱。","py":"Dàjiā dōu juéde tā xiào qǐlái hěn kě'ài.","vi":"Mọi người đều thấy anh ấy cười lên rất dễ thương.","en":"Everyone thinks he looks cute when he smiles."},{"use":"多 + 可爱 + 啊: câu cảm thán","ex":"你看这只小猫，多可爱啊！","py":"Nǐ kàn zhè zhī xiǎo māo, duō kě'ài a!","vi":"Bạn xem chú mèo con này, đáng yêu biết bao!","en":"Look at this kitten, how cute it is!"}]},"父亲":{"en":"father (formal)","exs":[{"use":"danh từ trang trọng hơn 爸爸","ex":"我父亲是医生。","py":"Wǒ fùqīn shì yīshēng.","vi":"Cha tôi là bác sĩ.","en":"My father is a doctor."},{"use":"父亲节: Ngày của Cha","ex":"今天是父亲节，我给父亲打了电话。","py":"Jīntiān shì Fùqīnjié, wǒ gěi fùqīn dǎ le diànhuà.","vi":"Hôm nay là Ngày của Cha, tôi đã gọi điện cho cha.","en":"Today is Father's Day, and I called my father."},{"use":"dùng trong văn viết, kể chuyện","ex":"父亲每天早上六点就起床工作。","py":"Fùqīn měitiān zǎoshang liù diǎn jiù qǐchuáng gōngzuò.","vi":"Cha tôi mỗi sáng sáu giờ đã dậy đi làm.","en":"My father gets up for work at six every morning."},{"use":"父亲 + 母亲 (cha mẹ) khi giới thiệu gia đình","ex":"他的父亲是老师，母亲是护士。","py":"Tā de fùqīn shì lǎoshī, mǔqīn shì hùshi.","vi":"Cha anh ấy là giáo viên, mẹ là y tá.","en":"His father is a teacher and his mother is a nurse."}]},"昨晚":{"en":"last night","exs":[{"use":"làm trạng ngữ thời gian, đứng trước hoặc sau chủ ngữ","ex":"昨晚我睡得很好。","py":"Zuówǎn wǒ shuì de hěn hǎo.","vi":"Tối qua tôi ngủ rất ngon.","en":"I slept very well last night."},{"use":"昨晚 + sự việc đã xảy ra (了)","ex":"昨晚下了一场大雨。","py":"Zuówǎn xià le yì chǎng dàyǔ.","vi":"Tối qua có một trận mưa lớn.","en":"It rained heavily last night."},{"use":"câu hỏi: 你昨晚…吗/几点…","ex":"你昨晚几点睡觉的？","py":"Nǐ zuówǎn jǐ diǎn shuìjiào de?","vi":"Tối qua bạn mấy giờ đi ngủ?","en":"What time did you go to bed last night?"},{"use":"昨晚的 + N: làm định ngữ","ex":"昨晚的晚会真热闹。","py":"Zuówǎn de wǎnhuì zhēn rènao.","vi":"Buổi liên hoan tối qua thật náo nhiệt.","en":"Last night's party was really lively."}]},"做作业":{"en":"to do homework","exs":[{"use":"động từ + tân ngữ: 做 + 作业","ex":"放学后我先做作业。","py":"Fàngxué hòu wǒ xiān zuò zuòyè.","vi":"Tan học xong tôi làm bài tập trước.","en":"After school I do my homework first."},{"use":"…的时候: mệnh đề thời gian","ex":"你做作业的时候，不要玩手机。","py":"Nǐ zuò zuòyè de shíhou, búyào wán shǒujī.","vi":"Lúc làm bài tập đừng nghịch điện thoại.","en":"Don't play with your phone while doing homework."},{"use":"正在 + 做作业: hành động đang diễn ra","ex":"弟弟正在房间里做作业。","py":"Dìdi zhèngzài fángjiān lǐ zuò zuòyè.","vi":"Em trai đang làm bài tập trong phòng.","en":"My younger brother is doing homework in his room."},{"use":"花 + thời gian + 做作业","ex":"我每天晚上花一个小时做作业。","py":"Wǒ měitiān wǎnshang huā yí ge xiǎoshí zuò zuòyè.","vi":"Mỗi tối tôi dành một tiếng làm bài tập.","en":"I spend an hour doing homework every evening."}]},"作业":{"en":"homework; assignment","exs":[{"use":"làm chủ ngữ: 作业 + 很多","ex":"今天的作业很多。","py":"Jīntiān de zuòyè hěn duō.","vi":"Bài tập hôm nay rất nhiều.","en":"There is a lot of homework today."},{"use":"交作业: nộp bài tập","ex":"明天早上要交作业。","py":"Míngtiān zǎoshang yào jiāo zuòyè.","vi":"Sáng mai phải nộp bài tập.","en":"The homework is due tomorrow morning."},{"use":"留作业: giao bài tập","ex":"老师给我们留了很多作业。","py":"Lǎoshī gěi wǒmen liú le hěn duō zuòyè.","vi":"Cô giáo giao cho chúng tôi rất nhiều bài tập.","en":"The teacher assigned us a lot of homework."},{"use":"写作业 + 数学作业: tên môn + 作业","ex":"我还没写完数学作业。","py":"Wǒ hái méi xiěwán shùxué zuòyè.","vi":"Tôi vẫn chưa viết xong bài tập toán.","en":"I haven't finished my math homework yet."}]},"闹钟":{"en":"alarm clock","exs":[{"use":"定闹钟: cài báo thức","ex":"我定了早上六点的闹钟。","py":"Wǒ dìng le zǎoshang liù diǎn de nàozhōng.","vi":"Tôi đã đặt báo thức lúc sáu giờ sáng.","en":"I set the alarm for six in the morning."},{"use":"闹钟响了: báo thức kêu","ex":"闹钟响了三次，他还没起床。","py":"Nàozhōng xiǎng le sān cì, tā hái méi qǐchuáng.","vi":"Báo thức kêu ba lần mà anh ấy vẫn chưa dậy.","en":"The alarm rang three times and he still hasn't gotten up."},{"use":"没听到闹钟: nêu nguyên nhân đến muộn","ex":"昨天我没听到闹钟，所以迟到了。","py":"Zuótiān wǒ méi tīngdào nàozhōng, suǒyǐ chídào le.","vi":"Hôm qua tôi không nghe thấy báo thức nên đến muộn.","en":"I didn't hear the alarm yesterday, so I was late."},{"use":"把 + 闹钟 + 关了: tắt báo thức","ex":"周末我不想起早，所以把闹钟关了。","py":"Zhōumò wǒ bù xiǎng qǐ zǎo, suǒyǐ bǎ nàozhōng guān le.","vi":"Cuối tuần tôi không muốn dậy sớm nên đã tắt báo thức.","en":"I don't want to get up early on weekends, so I turned off the alarm."}]},"赶时间":{"en":"to be in a hurry; to be pressed for time","exs":[{"use":"很赶时间: đang vội","ex":"我今天很赶时间，不能和你聊了。","py":"Wǒ jīntiān hěn gǎn shíjiān, bù néng hé nǐ liáo le.","vi":"Hôm nay tôi rất vội, không thể nói chuyện với bạn được.","en":"I'm in a hurry today and can't chat with you."},{"use":"不赶时间: không vội","ex":"别着急，我们不赶时间。","py":"Bié zháojí, wǒmen bù gǎn shíjiān.","vi":"Đừng vội, chúng ta không gấp.","en":"Don't worry, we're not in a rush."},{"use":"如果/要是 + 赶时间, + đề nghị","ex":"你要是赶时间，就坐出租车吧。","py":"Nǐ yàoshi gǎn shíjiān, jiù zuò chūzūchē ba.","vi":"Nếu bạn vội thì đi taxi đi.","en":"If you're in a hurry, take a taxi."},{"use":"因为赶时间: nêu nguyên nhân","ex":"因为赶时间，他早饭都没吃。","py":"Yīnwèi gǎn shíjiān, tā zǎofàn dōu méi chī.","vi":"Vì chạy đua với thời gian nên anh ấy không kịp ăn sáng.","en":"He was in such a hurry that he didn't even eat breakfast."}]},"上学":{"en":"to go to school; to attend school","exs":[{"use":"động từ li hợp: bắt đầu đi học/đến trường","ex":"我弟弟明年开始上学。","py":"Wǒ dìdi míngnián kāishǐ shàngxué.","vi":"Em trai tôi sang năm bắt đầu đi học.","en":"My younger brother starts school next year."},{"use":"方式 + 上学: đi học bằng phương tiện","ex":"他每天骑自行车上学。","py":"Tā měitiān qí zìxíngchē shàngxué.","vi":"Ngày nào cậu ấy cũng đạp xe đi học.","en":"He rides his bike to school every day."},{"use":"上学的路上: làm định ngữ","ex":"上学的路上，我遇到了老同学。","py":"Shàngxué de lùshang, wǒ yùdào le lǎo tóngxué.","vi":"Trên đường đi học, tôi gặp một người bạn cũ.","en":"On the way to school, I ran into an old classmate."},{"use":"不用上学: không phải đến trường","ex":"周末不用上学，我可以多睡一会儿。","py":"Zhōumò búyòng shàngxué, wǒ kěyǐ duō shuì yíhuìr.","vi":"Cuối tuần không phải đi học, tôi có thể ngủ thêm một chút.","en":"I don't have to go to school on weekends, so I can sleep a bit more."}]},"厕所":{"en":"toilet; restroom","exs":[{"use":"hỏi đường: 厕所在哪儿","ex":"请问，厕所在哪儿？","py":"Qǐngwèn, cèsuǒ zài nǎr?","vi":"Xin hỏi, nhà vệ sinh ở đâu?","en":"Excuse me, where is the toilet?"},{"use":"上厕所: đi vệ sinh","ex":"我想去上厕所。","py":"Wǒ xiǎng qù shàng cèsuǒ.","vi":"Tôi muốn đi vệ sinh.","en":"I want to go to the toilet."},{"use":"公共厕所: nhà vệ sinh công cộng","ex":"这附近有公共厕所吗？","py":"Zhè fùjìn yǒu gōnggòng cèsuǒ ma?","vi":"Gần đây có nhà vệ sinh công cộng không?","en":"Is there a public restroom nearby?"},{"use":"厕所里: chỉ vị trí bên trong","ex":"厕所里没有纸了，你能帮我拿一些吗？","py":"Cèsuǒ lǐ méiyǒu zhǐ le, nǐ néng bāng wǒ ná yìxiē ma?","vi":"Trong nhà vệ sinh hết giấy rồi, bạn lấy giúp tôi một ít được không?","en":"The restroom is out of paper; could you bring me some?"}]},"管理":{"en":"to manage; to run; management","exs":[{"use":"động từ: 管理 + đối tượng (cửa hàng, công ty)","ex":"他负责管理这家商店。","py":"Tā fùzé guǎnlǐ zhè jiā shāngdiàn.","vi":"Anh ấy phụ trách quản lý cửa hàng này.","en":"He is in charge of managing this shop."},{"use":"làm danh từ: 管理 + 很好/不好","ex":"这个公司的管理很好。","py":"Zhège gōngsī de guǎnlǐ hěn hǎo.","vi":"Việc quản lý của công ty này rất tốt.","en":"This company is well managed."},{"use":"管理 + 时间: quản lý thời gian","ex":"学生要学会管理自己的时间。","py":"Xuésheng yào xuéhuì guǎnlǐ zìjǐ de shíjiān.","vi":"Học sinh cần học cách quản lý thời gian của mình.","en":"Students need to learn to manage their own time."},{"use":"管理员: người quản lý","ex":"有问题请找小区管理员。","py":"Yǒu wèntí qǐng zhǎo xiǎoqū guǎnlǐyuán.","vi":"Có vấn đề xin tìm người quản lý khu dân cư.","en":"If you have any problems, please find the community manager."}]},"医院":{"en":"hospital","exs":[{"use":"去医院: đi bệnh viện","ex":"他生病了，我送他去医院。","py":"Tā shēngbìng le, wǒ sòng tā qù yīyuàn.","vi":"Anh ấy bị ốm, tôi đưa anh ấy đến bệnh viện.","en":"He is sick, so I'm taking him to the hospital."},{"use":"在医院 + V: nơi làm việc","ex":"我妈妈在医院工作。","py":"Wǒ māma zài yīyuàn gōngzuò.","vi":"Mẹ tôi làm việc ở bệnh viện.","en":"My mom works at a hospital."},{"use":"在医院 + 住: nằm viện","ex":"奶奶在医院住了一个星期。","py":"Nǎinai zài yīyuàn zhù le yí ge xīngqī.","vi":"Bà nội đã nằm viện một tuần.","en":"Grandma stayed in the hospital for a week."},{"use":"离: khoảng cách","ex":"这家医院离我家很近。","py":"Zhè jiā yīyuàn lí wǒ jiā hěn jìn.","vi":"Bệnh viện này rất gần nhà tôi.","en":"This hospital is very close to my home."}]},"打针":{"en":"to give or have an injection; to get a shot","exs":[{"use":"động từ li hợp: đi tiêm","ex":"孩子发烧了，要去医院打针。","py":"Háizi fāshāo le, yào qù yīyuàn dǎzhēn.","vi":"Con bị sốt, phải đến bệnh viện tiêm.","en":"The child has a fever and needs to get a shot at the hospital."},{"use":"怕打针: sợ tiêm","ex":"很多小孩子都怕打针。","py":"Hěn duō xiǎo háizi dōu pà dǎzhēn.","vi":"Rất nhiều trẻ con sợ tiêm.","en":"Many children are afraid of getting shots."},{"use":"打针打得…: bổ ngữ trạng thái","ex":"护士打针打得很轻，一点儿也不疼。","py":"Hùshi dǎzhēn dǎ de hěn qīng, yìdiǎnr yě bù téng.","vi":"Y tá tiêm rất nhẹ, một chút cũng không đau.","en":"The nurse gives injections so gently that it doesn't hurt at all."},{"use":"不用打针: không cần tiêm","ex":"医生说，你不用打针，吃药就可以了。","py":"Yīshēng shuō, nǐ búyòng dǎzhēn, chī yào jiù kěyǐ le.","vi":"Bác sĩ nói bạn không cần tiêm, uống thuốc là được.","en":"The doctor said you don't need a shot; taking medicine is enough."}]},"想想":{"en":"to think (it over); to think about","exs":[{"use":"V lặp lại, hành động nhẹ nhàng, thử suy nghĩ","ex":"你再想想，真的要买吗？","py":"Nǐ zài xiǎngxiang, zhēn de yào mǎi ma?","vi":"Bạn nghĩ lại xem, thật sự muốn mua sao?","en":"Think again: do you really want to buy it?"},{"use":"让我想想: xin thời gian suy nghĩ","ex":"让我想想，明天再告诉你。","py":"Ràng wǒ xiǎngxiang, míngtiān zài gàosu nǐ.","vi":"Để tôi nghĩ đã, mai sẽ nói với bạn.","en":"Let me think about it, and I'll tell you tomorrow."},{"use":"想想看: nghĩ thử xem","ex":"你想想看，他为什么这样做？","py":"Nǐ xiǎngxiang kàn, tā wèishénme zhèyàng zuò?","vi":"Bạn thử nghĩ xem, tại sao anh ấy làm như vậy?","en":"Think about it: why did he do that?"},{"use":"想想 + tân ngữ: nghĩ đến người khác","ex":"做事以前，先想想别人的感受。","py":"Zuòshì yǐqián, xiān xiǎngxiang biérén de gǎnshòu.","vi":"Trước khi làm việc, hãy nghĩ đến cảm nhận của người khác trước.","en":"Before acting, first think about other people's feelings."}]},"小声":{"en":"in a low voice; quietly","exs":[{"use":"小声 + 一点儿: yêu cầu nói nhỏ","ex":"请小声一点儿，宝宝在睡觉。","py":"Qǐng xiǎoshēng yìdiǎnr, bǎobao zài shuìjiào.","vi":"Xin nhỏ tiếng một chút, em bé đang ngủ.","en":"Please keep your voice down; the baby is sleeping."},{"use":"小声地 + V: làm trạng ngữ","ex":"他小声地对我说了一句话。","py":"Tā xiǎoshēng de duì wǒ shuō le yí jù huà.","vi":"Anh ấy nói nhỏ với tôi một câu.","en":"He said something to me in a low voice."},{"use":"要 + 小声 + 说话: quy định nơi công cộng","ex":"图书馆里要小声说话。","py":"Túshūguǎn lǐ yào xiǎoshēng shuōhuà.","vi":"Trong thư viện phải nói nhỏ.","en":"You should speak quietly in the library."},{"use":"说话 + 小声点儿: dạng đảo ở khẩu ngữ","ex":"电影开始了，大家说话小声点儿。","py":"Diànyǐng kāishǐ le, dàjiā shuōhuà xiǎoshēng diǎnr.","vi":"Phim bắt đầu rồi, mọi người nói nhỏ thôi.","en":"The movie has started; everyone, please speak quietly."}]},"护士":{"en":"nurse","exs":[{"use":"danh từ chỉ nghề nghiệp","ex":"那位护士对病人很热情。","py":"Nà wèi hùshi duì bìngrén hěn rèqíng.","vi":"Cô y tá đó rất nhiệt tình với bệnh nhân.","en":"That nurse is very warm toward patients."},{"use":"是/当 + 护士: nghề nghiệp","ex":"我姐姐是护士，在儿童医院工作。","py":"Wǒ jiějie shì hùshi, zài értóng yīyuàn gōngzuò.","vi":"Chị gái tôi là y tá, làm việc ở bệnh viện nhi.","en":"My older sister is a nurse and works at a children's hospital."},{"use":"想当护士: ước mơ nghề nghiệp","ex":"我长大以后想当护士。","py":"Wǒ zhǎngdà yǐhòu xiǎng dāng hùshi.","vi":"Lớn lên tôi muốn làm y tá.","en":"I want to be a nurse when I grow up."},{"use":"护士 + 让/给 + ai…: hoạt động ở bệnh viện","ex":"护士让我坐在外面等一会儿。","py":"Hùshi ràng wǒ zuò zài wàimiàn děng yíhuìr.","vi":"Y tá bảo tôi ngồi bên ngoài đợi một lát.","en":"The nurse asked me to wait outside for a while."}]},"不怕":{"en":"not afraid of; to not mind","exs":[{"use":"不怕 + danh từ: không sợ (khó khăn)","ex":"只要努力，就不怕困难。","py":"Zhǐyào nǔlì, jiù bú pà kùnnan.","vi":"Chỉ cần nỗ lực thì không sợ khó khăn.","en":"As long as you work hard, you won't be afraid of difficulties."},{"use":"什么都不怕, 就怕…: đối lập không sợ / chỉ sợ","ex":"他什么都不怕，就怕黑。","py":"Tā shénme dōu bú pà, jiù pà hēi.","vi":"Anh ấy chẳng sợ gì, chỉ sợ bóng tối.","en":"He isn't afraid of anything except the dark."},{"use":"不怕 + tính từ: không ngại (lạnh, mệt)","ex":"他不怕冷，冬天也穿得很少。","py":"Tā bú pà lěng, dōngtiān yě chuān de hěn shǎo.","vi":"Anh ấy không sợ lạnh, mùa đông cũng mặc rất ít.","en":"He doesn't mind the cold and wears little even in winter."},{"use":"不怕…，只怕…: cấu trúc đối chiếu","ex":"我不怕累，只怕没有时间。","py":"Wǒ bú pà lèi, zhǐ pà méiyǒu shíjiān.","vi":"Tôi không ngại mệt, chỉ sợ không có thời gian.","en":"I'm not afraid of being tired, only of not having time."}]},"表扬":{"en":"to praise; to commend; praise","exs":[{"use":"表扬 + người (trước đám đông)","ex":"老师在全班同学面前表扬了他。","py":"Lǎoshī zài quán bān tóngxué miànqián biǎoyáng le tā.","vi":"Cô giáo khen cậu ấy trước cả lớp.","en":"The teacher praised him in front of the whole class."},{"use":"受到表扬: được khen (danh từ)","ex":"他因为帮助同学，受到了表扬。","py":"Tā yīnwèi bāngzhù tóngxué, shòudào le biǎoyáng.","vi":"Cậu ấy được khen vì giúp đỡ bạn học.","en":"He was praised for helping his classmates."},{"use":"应该 + 表扬 + ai: lời khuyên khi nuôi dạy con","ex":"孩子做得好，就应该表扬他。","py":"Háizi zuò de hǎo, jiù yīnggāi biǎoyáng tā.","vi":"Con làm tốt thì nên khen con.","en":"When a child does well, you should praise him."},{"use":"表扬信: thư khen","ex":"学校给他寄来了一封表扬信。","py":"Xuéxiào gěi tā jì lái le yì fēng biǎoyángxìn.","vi":"Nhà trường gửi cho anh ấy một bức thư khen ngợi.","en":"The school sent him a letter of commendation."}]},"小孩儿":{"en":"child; kid","exs":[{"use":"danh từ: đứa trẻ (khẩu ngữ, có âm 儿)","ex":"这个小孩儿真聪明。","py":"Zhège xiǎoháir zhēn cōngming.","vi":"Đứa bé này thật thông minh.","en":"This kid is really smart."},{"use":"带小孩儿: chăm trẻ","ex":"她一个人带着两个小孩儿。","py":"Tā yí ge rén dàizhe liǎng ge xiǎoháir.","vi":"Cô ấy một mình nuôi hai đứa nhỏ.","en":"She is raising two children on her own."},{"use":"小孩儿都…: nói chung về trẻ nhỏ","ex":"小孩儿都喜欢吃糖。","py":"Xiǎoháir dōu xǐhuan chī táng.","vi":"Trẻ con đều thích ăn kẹo.","en":"Kids all love candy."},{"use":"mệnh đề định ngữ + 小孩儿","ex":"公园里有很多玩游戏的小孩儿。","py":"Gōngyuán lǐ yǒu hěn duō wán yóuxì de xiǎoháir.","vi":"Trong công viên có rất nhiều trẻ đang chơi trò chơi.","en":"There are many kids playing games in the park."}]},"有用":{"en":"useful; helpful","exs":[{"use":"对…有用: có ích đối với","ex":"这本书对学汉语很有用。","py":"Zhè běn shū duì xué Hànyǔ hěn yǒuyòng.","vi":"Cuốn sách này rất có ích cho việc học tiếng Hán.","en":"This book is very useful for learning Chinese."},{"use":"làm vị ngữ nhận xét biện pháp","ex":"你说的这个办法很有用。","py":"Nǐ shuō de zhège bànfǎ hěn yǒuyòng.","vi":"Cách bạn nói rất hiệu quả.","en":"The method you mentioned is very useful."},{"use":"有用的 + N: làm định ngữ","ex":"他给了我很多有用的建议。","py":"Tā gěi le wǒ hěn duō yǒuyòng de jiànyì.","vi":"Anh ấy cho tôi rất nhiều lời khuyên hữu ích.","en":"He gave me a lot of useful advice."},{"use":"…有用吗: câu hỏi tu từ","ex":"哭有用吗？还是想想办法吧。","py":"Kū yǒuyòng ma? Háishi xiǎngxiang bànfǎ ba.","vi":"Khóc thì có ích gì? Vẫn nên nghĩ cách đi.","en":"What good does crying do? Let's think of a solution."}]},"千万":{"en":"by all means; absolutely (must / must not)","exs":[{"use":"千万 + 别/不要: dặn dò mạnh, nhất định đừng","ex":"你千万别忘了带护照。","py":"Nǐ qiānwàn bié wàngle dài hùzhào.","vi":"Bạn nhất định đừng quên mang hộ chiếu.","en":"Whatever you do, don't forget your passport."},{"use":"千万 + 要: nhất định phải (cẩn thận, nhớ…)","ex":"过马路的时候千万要小心。","py":"Guò mǎlù de shíhou qiānwàn yào xiǎoxīn.","vi":"Khi qua đường nhất định phải cẩn thận.","en":"Be sure to be careful when crossing the street."},{"use":"千万 + 不要: tuyệt đối đừng","ex":"这件事千万不要告诉别人。","py":"Zhè jiàn shì qiānwàn búyào gàosu biérén.","vi":"Chuyện này tuyệt đối đừng nói với ai.","en":"Absolutely do not tell anyone about this."},{"use":"千万 + 不能: tuyệt đối không được","ex":"考试的时候千万不能迟到。","py":"Kǎoshì de shíhou qiānwàn bù néng chídào.","vi":"Lúc thi tuyệt đối không được đến muộn.","en":"You absolutely must not be late for the exam."}]},"怀疑":{"en":"to doubt; to suspect; doubt","exs":[{"use":"động từ: nghi ngờ (lời nói có thật không)","ex":"我怀疑他没有说真话。","py":"Wǒ huáiyí tā méiyǒu shuō zhēnhuà.","vi":"Tôi nghi ngờ anh ấy không nói thật.","en":"I doubt that he is telling the truth."},{"use":"怀疑 + 自己: hoài nghi bản thân","ex":"他一直怀疑自己的能力。","py":"Tā yìzhí huáiyí zìjǐ de nénglì.","vi":"Anh ấy luôn nghi ngờ năng lực của bản thân.","en":"He has always doubted his own ability."},{"use":"怀疑 + mệnh đề: ngờ rằng, đoán là (có phần nghi ngại)","ex":"我怀疑这个消息是假的。","py":"Wǒ huáiyí zhège xiāoxi shì jiǎ de.","vi":"Tôi ngờ tin này là giả.","en":"I suspect this news is fake."},{"use":"làm danh từ: sự nghi ngờ (对…有怀疑)","ex":"大家对他的话有些怀疑。","py":"Dàjiā duì tā de huà yǒuxiē huáiyí.","vi":"Mọi người có chút nghi ngờ lời anh ấy nói.","en":"Everyone has some doubts about what he said."}]},"积极性":{"en":"enthusiasm; initiative; zeal","exs":[{"use":"提高/激发 + 积极性: nâng cao tính tích cực","ex":"老师的表扬提高了学生的学习积极性。","py":"Lǎoshī de biǎoyáng tígāo le xuésheng de xuéxí jījíxìng.","vi":"Lời khen của thầy cô đã nâng cao tính tích cực học tập của học sinh.","en":"The teacher's praise raised the students' enthusiasm for learning."},{"use":"调动 + 积极性: khơi dậy sự hăng hái (thường dùng trong công việc)","ex":"公司想办法调动员工的工作积极性。","py":"Gōngsī xiǎng bànfǎ diàodòng yuángōng de gōngzuò jījíxìng.","vi":"Công ty tìm cách khơi dậy sự hăng hái làm việc của nhân viên.","en":"The company is finding ways to motivate its employees."},{"use":"没有/有 + 积极性: có/không có hứng thú, chủ động","ex":"他最近对学习没有什么积极性。","py":"Tā zuìjìn duì xuéxí méiyǒu shénme jījíxìng.","vi":"Dạo này cậu ấy chẳng có chút hứng thú nào với việc học.","en":"Lately he has had little enthusiasm for studying."}]},"不怕困难":{"en":"not afraid of difficulties","exs":[{"use":"làm định ngữ: 不怕困难 + 的 + người","ex":"他是个不怕困难的人。","py":"Tā shì ge bú pà kùnnan de rén.","vi":"Anh ấy là người không ngại khó khăn.","en":"He is someone who is not afraid of difficulties."},{"use":"只要…就…: điều kiện, không sợ khó thì sẽ thành công","ex":"只要不怕困难,就一定能成功。","py":"Zhǐyào bú pà kùnnan, jiù yídìng néng chénggōng.","vi":"Chỉ cần không sợ khó khăn thì nhất định sẽ thành công.","en":"As long as you aren't afraid of difficulties, you will surely succeed."},{"use":"不怕困难 + 的精神: tinh thần không ngại khó","ex":"我们要有不怕困难的精神。","py":"Wǒmen yào yǒu bú pà kùnnan de jīngshén.","vi":"Chúng ta cần có tinh thần không sợ khó khăn.","en":"We need to have a spirit of not fearing difficulties."}]},"同情":{"en":"to sympathize with; sympathy","exs":[{"use":"động từ: đồng cảm, thương xót ai","ex":"大家都很同情那个失去工作的人。","py":"Dàjiā dōu hěn tóngqíng nàge shīqù gōngzuò de rén.","vi":"Mọi người đều rất thương cảm người đã mất việc kia.","en":"Everyone felt sorry for the man who lost his job."},{"use":"làm danh từ: 对…充满同情","ex":"他对穷人充满了同情。","py":"Tā duì qióngrén chōngmǎn le tóngqíng.","vi":"Anh ấy tràn đầy lòng thương xót đối với người nghèo.","en":"He is full of sympathy for the poor."},{"use":"同情心: lòng trắc ẩn, lòng thương người","ex":"孩子要从小有同情心。","py":"Háizi yào cóng xiǎo yǒu tóngqíngxīn.","vi":"Trẻ em cần có lòng thương người từ nhỏ.","en":"Children should have compassion from an early age."}]},"推到":{"en":"to push to; to shift (blame) onto; to postpone to","exs":[{"use":"推 + 到 + nơi chốn: đẩy tới đâu (nghĩa đen)","ex":"他把桌子推到了墙边。","py":"Tā bǎ zhuōzi tuīdào le qiáng biān.","vi":"Anh ấy đẩy cái bàn sát vào tường.","en":"He pushed the table up against the wall."},{"use":"推到 + ai + 身上: đổ trách nhiệm lên ai","ex":"他把责任都推到我身上。","py":"Tā bǎ zérèn dōu tuīdào wǒ shēnshang.","vi":"Anh ta đổ hết trách nhiệm lên đầu tôi.","en":"He shifted all the blame onto me."},{"use":"推到 + thời gian: dời sang (khẩu ngữ)","ex":"我们把旅行推到下个月吧。","py":"Wǒmen bǎ lǚxíng tuīdào xià ge yuè ba.","vi":"Chúng ta dời chuyến du lịch sang tháng sau nhé.","en":"Let's push the trip back to next month."}]},"预习":{"en":"to preview (lessons before class)","exs":[{"use":"động từ: chuẩn bị bài trước","ex":"每天晚上我都要预习明天的课文。","py":"Měi tiān wǎnshang wǒ dōu yào yùxí míngtiān de kèwén.","vi":"Mỗi tối tôi đều phải chuẩn bị bài khóa của ngày mai.","en":"Every evening I preview tomorrow's text."},{"use":"先 + 预习 + …才/会…: lợi ích của việc chuẩn bị bài","ex":"上课以前先预习,听课会容易一些。","py":"Shàngkè yǐqián xiān yùxí, tīngkè huì róngyì yìxiē.","vi":"Chuẩn bị bài trước khi lên lớp thì nghe giảng sẽ dễ hơn.","en":"If you preview before class, the lesson will be easier to follow."},{"use":"预习 + 生词/课文: tân ngữ thường gặp","ex":"你预习新单词了吗?","py":"Nǐ yùxí xīn dāncí le ma?","vi":"Bạn đã chuẩn bị từ mới chưa?","en":"Have you previewed the new vocabulary?"}]},"重点":{"en":"key point; focus; key (adj. use); mainly","exs":[{"use":"danh từ: trọng điểm của bài","ex":"老师说这一课的重点是语法。","py":"Lǎoshī shuō zhè yí kè de zhòngdiǎn shì yǔfǎ.","vi":"Thầy nói trọng điểm của bài này là ngữ pháp.","en":"The teacher said the focus of this lesson is grammar."},{"use":"抓住/突出 + 重点: nắm bắt trọng điểm","ex":"复习的时候要抓住重点。","py":"Fùxí de shíhou yào zhuāzhù zhòngdiǎn.","vi":"Khi ôn tập phải nắm được trọng điểm.","en":"When reviewing, you should grasp the key points."},{"use":"重点 + danh từ: làm định ngữ, nghĩa 'trọng điểm'","ex":"这是一所重点大学。","py":"Zhè shì yì suǒ zhòngdiǎn dàxué.","vi":"Đây là một trường đại học trọng điểm.","en":"This is a key university."},{"use":"làm trạng ngữ: chủ yếu, tập trung vào","ex":"这次会议重点讨论环境问题。","py":"Zhè cì huìyì zhòngdiǎn tǎolùn huánjìng wèntí.","vi":"Cuộc họp lần này tập trung thảo luận vấn đề môi trường.","en":"This meeting mainly discusses environmental issues."}]},"马虎":{"en":"careless; sloppy","exs":[{"use":"不能 + 马虎: không được cẩu thả","ex":"做作业不能马虎。","py":"Zuò zuòyè bù néng mǎhu.","vi":"Làm bài tập không được cẩu thả.","en":"You mustn't be careless when doing homework."},{"use":"马虎 + 的 + người: làm định ngữ","ex":"他是个马虎的人,常常忘带钥匙。","py":"Tā shì ge mǎhu de rén, chángcháng wàng dài yàoshi.","vi":"Anh ấy là người cẩu thả, hay quên mang chìa khóa.","en":"He is a careless person who often forgets his keys."},{"use":"V + 得 + 很马虎: bổ ngữ trạng thái","ex":"他检查得很马虎。","py":"Tā jiǎnchá de hěn mǎhu.","vi":"Anh ấy kiểm tra rất qua loa.","en":"He checked it very sloppily."},{"use":"马虎 + 地 + V: làm trạng ngữ, làm qua loa","ex":"他马虎地看了一遍就交了。","py":"Tā mǎhu de kàn le yí biàn jiù jiāo le.","vi":"Anh ấy xem qua loa một lượt rồi nộp.","en":"He glanced over it carelessly and handed it in."}]},"自信":{"en":"confident; self-confidence","exs":[{"use":"tính từ: 很自信","ex":"她说话的时候很自信。","py":"Tā shuōhuà de shíhou hěn zìxìn.","vi":"Khi nói chuyện cô ấy rất tự tin.","en":"She is very confident when she speaks."},{"use":"danh từ: 对自己有自信","ex":"你要对自己有自信。","py":"Nǐ yào duì zìjǐ yǒu zìxìn.","vi":"Bạn phải có niềm tin vào bản thân.","en":"You must have confidence in yourself."},{"use":"自信 + 地 + V: làm trạng ngữ","ex":"他自信地走上了舞台。","py":"Tā zìxìn de zǒushàng le wǔtái.","vi":"Anh ấy tự tin bước lên sân khấu.","en":"He stepped onto the stage confidently."},{"use":"失去/增加 + 自信: mất/tăng sự tự tin","ex":"这次失败让他失去了自信。","py":"Zhè cì shībài ràng tā shīqù le zìxìn.","vi":"Lần thất bại này khiến anh ấy mất tự tin.","en":"This failure made him lose his confidence."}]},"冷静":{"en":"calm; composed; to calm down","exs":[{"use":"tính từ: 要冷静","ex":"遇到问题要冷静。","py":"Yùdào wèntí yào lěngjìng.","vi":"Gặp vấn đề phải bình tĩnh.","en":"You should stay calm when you run into problems."},{"use":"冷静下来: bình tĩnh lại (bổ ngữ xu hướng)","ex":"你先冷静下来,我们慢慢说。","py":"Nǐ xiān lěngjìng xiàlái, wǒmen mànmàn shuō.","vi":"Bạn bình tĩnh lại đã, chúng ta nói từ từ.","en":"Calm down first, and we'll talk slowly."},{"use":"保持冷静: giữ bình tĩnh","ex":"发生火灾时,一定要保持冷静。","py":"Fāshēng huǒzāi shí, yídìng yào bǎochí lěngjìng.","vi":"Khi xảy ra hỏa hoạn nhất định phải giữ bình tĩnh.","en":"You must stay calm when a fire breaks out."},{"use":"冷静 + 地 + V: làm trạng ngữ","ex":"她冷静地回答了记者的问题。","py":"Tā lěngjìng de huídá le jìzhě de wèntí.","vi":"Cô ấy bình tĩnh trả lời câu hỏi của phóng viên.","en":"She answered the reporter's questions calmly."}]},"尊重":{"en":"to respect; respect","exs":[{"use":"động từ + tân ngữ: tôn trọng ai","ex":"我们应该尊重老人。","py":"Wǒmen yīnggāi zūnzhòng lǎorén.","vi":"Chúng ta nên kính trọng người già.","en":"We should respect the elderly."},{"use":"互相尊重: tôn trọng lẫn nhau","ex":"夫妻之间要互相尊重。","py":"Fūqī zhījiān yào hùxiāng zūnzhòng.","vi":"Vợ chồng với nhau phải tôn trọng lẫn nhau.","en":"Husbands and wives should respect each other."},{"use":"尊重 + ý kiến/quyết định: tôn trọng quan điểm","ex":"请尊重我的决定。","py":"Qǐng zūnzhòng wǒ de juédìng.","vi":"Xin hãy tôn trọng quyết định của tôi.","en":"Please respect my decision."},{"use":"受到尊重 / làm danh từ: được tôn trọng","ex":"他很受大家的尊重。","py":"Tā hěn shòu dàjiā de zūnzhòng.","vi":"Anh ấy được mọi người rất tôn trọng.","en":"He is very much respected by everyone."}]},"等等":{"en":"etc.; and so on; wait a moment","exs":[{"use":"trợ từ liệt kê: đặt cuối danh sách, nghĩa 'vân vân'","ex":"超市里有水果、蔬菜、牛奶等等。","py":"Chāoshì lǐ yǒu shuǐguǒ, shūcài, niúnǎi děngděng.","vi":"Trong siêu thị có hoa quả, rau, sữa, v.v.","en":"The supermarket has fruit, vegetables, milk, and so on."},{"use":"liệt kê địa điểm/sự vật: A、B、C + 等等","ex":"我去过北京、上海、广州等等。","py":"Wǒ qù guo Běijīng, Shànghǎi, Guǎngzhōu děngděng.","vi":"Tôi từng đến Bắc Kinh, Thượng Hải, Quảng Châu, v.v.","en":"I have been to Beijing, Shanghai, Guangzhou, etc."},{"use":"liệt kê kỹ năng: dùng sau 3 mục trở lên","ex":"他会说英语、法语、日语等等。","py":"Tā huì shuō Yīngyǔ, Fǎyǔ, Rìyǔ děngděng.","vi":"Anh ấy biết nói tiếng Anh, Pháp, Nhật, v.v.","en":"He can speak English, French, Japanese and so on."},{"use":"động từ lặp (nghĩa 2): chờ một chút","ex":"请等等,经理马上就来。","py":"Qǐng děngdeng, jīnglǐ mǎshàng jiù lái.","vi":"Xin chờ một chút, giám đốc đến ngay.","en":"Please wait a moment, the manager will be right here."}]},"重视":{"en":"to attach importance to; to value","exs":[{"use":"động từ + tân ngữ: coi trọng","ex":"公司很重视员工的意见。","py":"Gōngsī hěn zhòngshì yuángōng de yìjiàn.","vi":"Công ty rất coi trọng ý kiến của nhân viên.","en":"The company values its employees' opinions."},{"use":"受到/得到 + 重视: bị động, được coi trọng","ex":"他的建议受到了领导的重视。","py":"Tā de jiànyì shòudào le lǐngdǎo de zhòngshì.","vi":"Đề xuất của anh ấy được lãnh đạo coi trọng.","en":"His suggestion received the leadership's attention."},{"use":"不够重视: chưa đủ coi trọng","ex":"很多家长不够重视孩子的睡眠。","py":"Hěn duō jiāzhǎng bú gòu zhòngshì háizi de shuìmián.","vi":"Nhiều phụ huynh chưa đủ coi trọng giấc ngủ của con.","en":"Many parents don't pay enough attention to their children's sleep."},{"use":"引起重视: gây sự chú ý, được quan tâm","ex":"这个问题应该引起大家的重视。","py":"Zhège wèntí yīnggāi yǐnqǐ dàjiā de zhòngshì.","vi":"Vấn đề này cần được mọi người coi trọng.","en":"This problem should get everyone's attention."}]},"博士":{"en":"doctor (PhD); doctorate","exs":[{"use":"danh từ: người có bằng tiến sĩ","ex":"他是北京大学的博士。","py":"Tā shì Běijīng Dàxué de bóshì.","vi":"Anh ấy là tiến sĩ của Đại học Bắc Kinh.","en":"He is a PhD from Peking University."},{"use":"读博士: học lên tiến sĩ","ex":"我姐姐正在国外读博士。","py":"Wǒ jiějie zhèngzài guówài dú bóshì.","vi":"Chị tôi đang học tiến sĩ ở nước ngoài.","en":"My older sister is doing her PhD abroad."},{"use":"博士学位: bằng tiến sĩ","ex":"他去年拿到了博士学位。","py":"Tā qùnián nádào le bóshì xuéwèi.","vi":"Năm ngoái anh ấy đã lấy được bằng tiến sĩ.","en":"He got his doctorate last year."},{"use":"họ + 博士: cách xưng hô","ex":"李博士给我们讲了一堂课。","py":"Lǐ bóshì gěi wǒmen jiǎng le yì táng kè.","vi":"Tiến sĩ Lý đã giảng cho chúng tôi một buổi học.","en":"Dr. Li gave us a lecture."}]},"签证":{"en":"visa","exs":[{"use":"办签证: làm visa","ex":"去美国旅游要先办签证。","py":"Qù Měiguó lǚyóu yào xiān bàn qiānzhèng.","vi":"Đi du lịch Mỹ phải làm visa trước.","en":"You need to get a visa first to travel to the US."},{"use":"签证 + 到期: visa hết hạn","ex":"我的签证下个月就到期了。","py":"Wǒ de qiānzhèng xià ge yuè jiù dàoqī le.","vi":"Visa của tôi tháng sau sẽ hết hạn.","en":"My visa expires next month."},{"use":"loại + 签证: visa du học, công tác…","ex":"他已经申请了留学签证。","py":"Tā yǐjīng shēnqǐng le liúxué qiānzhèng.","vi":"Anh ấy đã xin visa du học rồi.","en":"He has already applied for a student visa."}]},"护照":{"en":"passport","exs":[{"use":"带护照: mang hộ chiếu","ex":"出国一定要带护照。","py":"Chūguó yídìng yào dài hùzhào.","vi":"Ra nước ngoài nhất định phải mang hộ chiếu.","en":"You must bring your passport when going abroad."},{"use":"护照 + 找不到/丢了: mất hộ chiếu","ex":"我的护照找不到了,怎么办?","py":"Wǒ de hùzhào zhǎo bú dào le, zěnme bàn?","vi":"Tôi không tìm thấy hộ chiếu, phải làm sao đây?","en":"I can't find my passport. What should I do?"},{"use":"办护照: làm hộ chiếu","ex":"办护照需要几张照片?","py":"Bàn hùzhào xūyào jǐ zhāng zhàopiàn?","vi":"Làm hộ chiếu cần mấy tấm ảnh?","en":"How many photos do you need to apply for a passport?"}]},"填写":{"en":"to fill in; to fill out","exs":[{"use":"填写 + biểu mẫu: điền đơn","ex":"请填写这张表格。","py":"Qǐng tiánxiě zhè zhāng biǎogé.","vi":"Xin hãy điền vào mẫu đơn này.","en":"Please fill out this form."},{"use":"填写 + thông tin cá nhân","ex":"请在这里填写你的姓名和电话。","py":"Qǐng zài zhèlǐ tiánxiě nǐ de xìngmíng hé diànhuà.","vi":"Xin điền họ tên và số điện thoại của bạn vào đây.","en":"Please write your name and phone number here."},{"use":"填写 + 完: bổ ngữ kết quả","ex":"他很快就填写完了申请表。","py":"Tā hěn kuài jiù tiánxiě wán le shēnqǐngbiǎo.","vi":"Anh ấy rất nhanh đã điền xong đơn đăng ký.","en":"He quickly finished filling in the application form."}]},"报名":{"en":"to sign up; to register","exs":[{"use":"报名 + 参加 + sự kiện: đăng ký tham gia","ex":"我想报名参加汉语考试。","py":"Wǒ xiǎng bàomíng cānjiā Hànyǔ kǎoshì.","vi":"Tôi muốn đăng ký dự thi tiếng Hán.","en":"I want to sign up for the Chinese exam."},{"use":"报名 + 的 + 人: làm định ngữ","ex":"报名的人很多,名额快满了。","py":"Bàomíng de rén hěn duō, míng'é kuài mǎn le.","vi":"Người đăng ký rất đông, suất sắp hết rồi.","en":"Many people have signed up and the places are almost full."},{"use":"在网上报名: cách thức đăng ký","ex":"你可以在网上报名。","py":"Nǐ kěyǐ zài wǎngshàng bàomíng.","vi":"Bạn có thể đăng ký trực tuyến.","en":"You can sign up online."},{"use":"报名费: lệ phí đăng ký","ex":"报名费是两百块。","py":"Bàomíngfèi shì liǎng bǎi kuài.","vi":"Lệ phí đăng ký là hai trăm tệ.","en":"The registration fee is 200 yuan."}]},"表格":{"en":"form; table; spreadsheet","exs":[{"use":"danh từ: mẫu đơn (lượng từ 张)","ex":"请把这张表格填好。","py":"Qǐng bǎ zhè zhāng biǎogé tián hǎo.","vi":"Xin hãy điền xong mẫu đơn này.","en":"Please fill in this form."},{"use":"bảng biểu trên máy tính: 做表格","ex":"我用电脑做了一个表格。","py":"Wǒ yòng diànnǎo zuò le yí ge biǎogé.","vi":"Tôi dùng máy tính làm một bảng biểu.","en":"I made a table on the computer."},{"use":"下载 + 表格: tải mẫu","ex":"你可以从网站上下载申请表格。","py":"Nǐ kěyǐ cóng wǎngzhàn shàng xiàzài shēnqǐng biǎogé.","vi":"Bạn có thể tải mẫu đơn xin từ trang web.","en":"You can download the application form from the website."}]},"邀请信":{"en":"invitation letter","exs":[{"use":"cần thư mời để làm thủ tục","ex":"办签证需要一封邀请信。","py":"Bàn qiānzhèng xūyào yì fēng yāoqǐngxìn.","vi":"Làm visa cần một thư mời.","en":"You need an invitation letter to get a visa."},{"use":"收到 + 邀请信","ex":"我收到了公司的邀请信。","py":"Wǒ shōudào le gōngsī de yāoqǐngxìn.","vi":"Tôi đã nhận được thư mời của công ty.","en":"I received an invitation letter from the company."},{"use":"寄 + 邀请信 (lượng từ 封)","ex":"请朋友给我寄一封邀请信。","py":"Qǐng péngyou gěi wǒ jì yì fēng yāoqǐngxìn.","vi":"Nhờ bạn gửi cho tôi một thư mời.","en":"I asked my friend to send me an invitation letter."}]},"传真":{"en":"fax; to fax","exs":[{"use":"danh từ: 发传真","ex":"经理让秘书发一份传真。","py":"Jīnglǐ ràng mìshū fā yí fèn chuánzhēn.","vi":"Giám đốc bảo thư ký gửi một bản fax.","en":"The manager asked the secretary to send a fax."},{"use":"用传真: gửi bằng fax","ex":"请把合同用传真发给我。","py":"Qǐng bǎ hétong yòng chuánzhēn fā gěi wǒ.","vi":"Xin hãy gửi hợp đồng cho tôi bằng fax.","en":"Please fax me the contract."},{"use":"传真机: máy fax","ex":"办公室的传真机坏了。","py":"Bàngōngshì de chuánzhēnjī huài le.","vi":"Máy fax của văn phòng bị hỏng rồi.","en":"The fax machine in the office is broken."},{"use":"động từ: fax đi đâu","ex":"请把这份文件传真到上海。","py":"Qǐng bǎ zhè fèn wénjiàn chuánzhēn dào Shànghǎi.","vi":"Xin fax tài liệu này đến Thượng Hải.","en":"Please fax this document to Shanghai."}]},"使馆":{"en":"embassy","exs":[{"use":"在 + 使馆 + 工作","ex":"他在中国使馆工作。","py":"Tā zài Zhōngguó shǐguǎn gōngzuò.","vi":"Anh ấy làm việc ở sứ quán Trung Quốc.","en":"He works at the Chinese embassy."},{"use":"去使馆办事","ex":"明天我要去使馆办签证。","py":"Míngtiān wǒ yào qù shǐguǎn bàn qiānzhèng.","vi":"Ngày mai tôi phải đến sứ quán làm visa.","en":"Tomorrow I have to go to the embassy to get a visa."},{"use":"联系 + 使馆: khi gặp sự cố ở nước ngoài","ex":"护照丢了应该先联系使馆。","py":"Hùzhào diū le yīnggāi xiān liánxì shǐguǎn.","vi":"Mất hộ chiếu thì nên liên hệ sứ quán trước.","en":"If you lose your passport, contact the embassy first."},{"use":"大使馆: đại sứ quán (dạng đầy đủ)","ex":"美国大使馆在那条街上。","py":"Měiguó dàshǐguǎn zài nà tiáo jiē shàng.","vi":"Đại sứ quán Mỹ ở trên con phố đó.","en":"The US embassy is on that street."}]},"怎么办":{"en":"what to do; what should (one) do","exs":[{"use":"câu hỏi: gặp tình huống giả định, 如果…怎么办","ex":"如果下雨了,怎么办?","py":"Rúguǒ xià yǔ le, zěnme bàn?","vi":"Nếu trời mưa thì làm sao?","en":"What should we do if it rains?"},{"use":"hỏi cách xử lý khi có sự cố","ex":"我把钥匙丢了,现在怎么办?","py":"Wǒ bǎ yàoshi diū le, xiànzài zěnme bàn?","vi":"Tôi làm mất chìa khóa rồi, giờ phải làm sao?","en":"I lost my keys. What should I do now?"},{"use":"不知道 + (该) + 怎么办: không biết phải làm sao","ex":"他不知道该怎么办才好。","py":"Tā bù zhīdào gāi zěnme bàn cái hǎo.","vi":"Anh ấy không biết phải làm thế nào mới tốt.","en":"He doesn't know what to do."},{"use":"没有…怎么办: hỏi cách giải quyết khi thiếu","ex":"票都卖完了,我们怎么办?","py":"Piào dōu màiwán le, wǒmen zěnme bàn?","vi":"Vé bán hết rồi, chúng ta làm sao đây?","en":"The tickets are sold out. What shall we do?"}]},"电话号码":{"en":"phone number","exs":[{"use":"hỏi số điện thoại","ex":"你的电话号码是多少?","py":"Nǐ de diànhuà hàomǎ shì duōshao?","vi":"Số điện thoại của bạn là bao nhiêu?","en":"What is your phone number?"},{"use":"写/留 + 电话号码","ex":"请把电话号码写在这里。","py":"Qǐng bǎ diànhuà hàomǎ xiě zài zhèlǐ.","vi":"Xin hãy viết số điện thoại vào đây.","en":"Please write your phone number here."},{"use":"记不住 + 电话号码: bổ ngữ khả năng","ex":"我记不住他的电话号码。","py":"Wǒ jì bú zhù tā de diànhuà hàomǎ.","vi":"Tôi không nhớ nổi số điện thoại của anh ấy.","en":"I can't remember his phone number."},{"use":"换 + 电话号码","ex":"他换了新的电话号码。","py":"Tā huàn le xīn de diànhuà hàomǎ.","vi":"Anh ấy đã đổi số điện thoại mới.","en":"He changed to a new phone number."}]},"参观":{"en":"to visit; to tour","exs":[{"use":"参观 + địa điểm (viện bảo tàng, nhà máy…)","ex":"我们明天去参观博物馆。","py":"Wǒmen míngtiān qù cānguān bówùguǎn.","vi":"Ngày mai chúng tôi đi tham quan viện bảo tàng.","en":"Tomorrow we are going to visit the museum."},{"use":"欢迎参观: lời mời","ex":"欢迎大家来参观我们的学校。","py":"Huānyíng dàjiā lái cānguān wǒmen de xuéxiào.","vi":"Chào mừng mọi người đến tham quan trường chúng tôi.","en":"Everyone is welcome to visit our school."},{"use":"参观 + 完: bổ ngữ kết quả","ex":"参观完以后,我们在公园吃了午饭。","py":"Cānguān wán yǐhòu, wǒmen zài gōngyuán chī le wǔfàn.","vi":"Sau khi tham quan xong, chúng tôi ăn trưa ở công viên.","en":"After the visit, we had lunch in the park."},{"use":"làm danh từ: chuyến tham quan","ex":"这次参观让我学到了很多。","py":"Zhè cì cānguān ràng wǒ xuédào le hěn duō.","vi":"Chuyến tham quan lần này giúp tôi học được rất nhiều.","en":"This visit taught me a lot."}]},"激动":{"en":"excited; moved; agitated","exs":[{"use":"tính từ: xúc động khi nghe tin","ex":"听到这个好消息,她非常激动。","py":"Tīngdào zhège hǎo xiāoxi, tā fēicháng jīdòng.","vi":"Nghe tin vui này, cô ấy vô cùng xúc động.","en":"She was very excited to hear the good news."},{"use":"激动得 + …: bổ ngữ mức độ","ex":"他激动得说不出话来。","py":"Tā jīdòng de shuō bù chū huà lái.","vi":"Anh ấy xúc động đến nỗi không nói nên lời.","en":"He was so moved that he couldn't speak."},{"use":"别激动: khuyên đừng nóng nảy","ex":"你别激动,慢慢说。","py":"Nǐ bié jīdòng, mànmàn shuō.","vi":"Bạn đừng kích động, cứ từ từ nói.","en":"Don't get worked up, just tell me slowly."},{"use":"令人激动: làm định ngữ","ex":"这是一个令人激动的时刻。","py":"Zhè shì yí ge lìng rén jīdòng de shíkè.","vi":"Đây là một khoảnh khắc khiến người ta xúc động.","en":"This is an exciting moment."}]},"王老板":{"en":"Boss Wang (Mr. Wang, the owner)","exs":[{"use":"họ + 老板: gọi ông chủ họ Vương","ex":"王老板开了一家饭馆。","py":"Wáng lǎobǎn kāi le yì jiā fànguǎn.","vi":"Ông chủ Vương mở một nhà hàng.","en":"Boss Wang opened a restaurant."},{"use":"gọi trực tiếp khi nói chuyện","ex":"王老板,这是您要的文件。","py":"Wáng lǎobǎn, zhè shì nín yào de wénjiàn.","vi":"Ông chủ Vương, đây là tài liệu ông cần.","en":"Boss Wang, here are the documents you asked for."},{"use":"hỏi về người: 王老板 + 在吗","ex":"请问,王老板在吗?","py":"Qǐngwèn, Wáng lǎobǎn zài ma?","vi":"Xin hỏi, ông chủ Vương có ở đây không?","en":"Excuse me, is Boss Wang in?"},{"use":"nói về cách đối đãi nhân viên","ex":"王老板对员工很好。","py":"Wáng lǎobǎn duì yuángōng hěn hǎo.","vi":"Ông chủ Vương đối xử với nhân viên rất tốt.","en":"Boss Wang treats his employees very well."}]},"小伙子":{"en":"young man; lad","exs":[{"use":"danh từ: chàng trai trẻ","ex":"那个小伙子在帮老人提东西。","py":"Nàge xiǎohuǒzi zài bāng lǎorén tí dōngxi.","vi":"Chàng trai kia đang giúp cụ già xách đồ.","en":"That young man is helping an old person carry things."},{"use":"dùng để gọi người trẻ (thân mật)","ex":"小伙子,请问去火车站怎么走?","py":"Xiǎohuǒzi, qǐngwèn qù huǒchēzhàn zěnme zǒu?","vi":"Cậu thanh niên, xin hỏi đến ga tàu đi thế nào?","en":"Young man, how do I get to the train station?"},{"use":"又…又… + 小伙子: miêu tả","ex":"他是个又高又帅的小伙子。","py":"Tā shì ge yòu gāo yòu shuài de xiǎohuǒzi.","vi":"Anh ấy là một chàng trai vừa cao vừa đẹp trai.","en":"He is a tall and handsome young man."}]},"西瓜":{"en":"watermelon","exs":[{"use":"danh từ: ăn dưa hấu mùa hè","ex":"夏天我最爱吃西瓜。","py":"Xiàtiān wǒ zuì ài chī xīguā.","vi":"Mùa hè tôi thích ăn dưa hấu nhất.","en":"I love eating watermelon most in summer."},{"use":"lượng từ 个 / 块: một quả, một miếng","ex":"我买了一个很大的西瓜。","py":"Wǒ mǎi le yí ge hěn dà de xīguā.","vi":"Tôi mua một quả dưa hấu rất to.","en":"I bought a very big watermelon."},{"use":"西瓜汁: nước ép dưa hấu","ex":"天气太热,我想喝西瓜汁。","py":"Tiānqì tài rè, wǒ xiǎng hē xīguāzhī.","vi":"Trời nóng quá, tôi muốn uống nước ép dưa hấu.","en":"It's so hot that I want to drink watermelon juice."}]},"记者":{"en":"reporter; journalist","exs":[{"use":"danh từ: nghề nghiệp","ex":"她是电视台的记者。","py":"Tā shì diànshìtái de jìzhě.","vi":"Cô ấy là phóng viên của đài truyền hình.","en":"She is a reporter at a TV station."},{"use":"记者 + 采访: phóng viên phỏng vấn","ex":"记者正在采访那位运动员。","py":"Jìzhě zhèngzài cǎifǎng nà wèi yùndòngyuán.","vi":"Phóng viên đang phỏng vấn vận động viên đó.","en":"The reporter is interviewing that athlete."},{"use":"当记者: làm phóng viên","ex":"我小时候的梦想是当记者。","py":"Wǒ xiǎoshíhou de mèngxiǎng shì dāng jìzhě.","vi":"Ước mơ thuở nhỏ của tôi là làm phóng viên.","en":"My childhood dream was to be a journalist."},{"use":"记者招待会: họp báo","ex":"明天上午有一个记者招待会。","py":"Míngtiān shàngwǔ yǒu yí ge jìzhě zhāodàihuì.","vi":"Sáng mai có một buổi họp báo.","en":"There is a press conference tomorrow morning."}]},"各种":{"en":"all kinds of; various","exs":[{"use":"各种 + danh từ: nhiều loại","ex":"他会做各种中国菜。","py":"Tā huì zuò gèzhǒng Zhōngguó cài.","vi":"Anh ấy biết nấu đủ loại món Trung Quốc.","en":"He can cook all kinds of Chinese dishes."},{"use":"各种各样: dạng nhấn mạnh (đủ kiểu)","ex":"商店里有各种各样的衣服。","py":"Shāngdiàn lǐ yǒu gèzhǒng gèyàng de yīfu.","vi":"Trong cửa hàng có đủ các loại quần áo.","en":"The store has all sorts of clothes."},{"use":"因为各种原因: nhiều lý do","ex":"因为各种原因,会议取消了。","py":"Yīnwèi gèzhǒng yuányīn, huìyì qǔxiāo le.","vi":"Vì nhiều lý do, cuộc họp đã bị hủy.","en":"The meeting was canceled for various reasons."}]},"大小":{"en":"size; (big and small)","exs":[{"use":"danh từ: kích cỡ của đồ vật","ex":"这双鞋的大小正合适。","py":"Zhè shuāng xié de dàxiǎo zhèng héshì.","vi":"Cỡ của đôi giày này vừa vặn.","en":"The size of these shoes is just right."},{"use":"大小 + 一样: so sánh kích cỡ","ex":"这两个箱子大小一样。","py":"Zhè liǎng ge xiāngzi dàxiǎo yíyàng.","vi":"Hai cái vali này to như nhau.","en":"These two suitcases are the same size."},{"use":"hỏi kích cỡ: 告诉我…的大小","ex":"请告诉我房间的大小。","py":"Qǐng gàosu wǒ fángjiān de dàxiǎo.","vi":"Xin cho tôi biết diện tích của căn phòng.","en":"Please tell me the size of the room."},{"use":"大小事: lớn nhỏ, mọi việc","ex":"家里大小事情都是妈妈做主。","py":"Jiālǐ dàxiǎo shìqing dōu shì māma zuòzhǔ.","vi":"Mọi việc lớn nhỏ trong nhà đều do mẹ quyết định.","en":"Mom makes all the decisions, big and small, at home."}]},"代表":{"en":"to represent; to stand for; representative","exs":[{"use":"động từ: thay mặt","ex":"我代表全班同学感谢老师。","py":"Wǒ dàibiǎo quán bān tóngxué gǎnxiè lǎoshī.","vi":"Tôi thay mặt cả lớp cảm ơn thầy cô.","en":"On behalf of the whole class, I thank the teacher."},{"use":"động từ: biểu thị, tượng trưng cho","ex":"红色代表好运。","py":"Hóngsè dàibiǎo hǎoyùn.","vi":"Màu đỏ tượng trưng cho may mắn.","en":"Red stands for good luck."},{"use":"danh từ: người đại diện","ex":"他是我们公司的代表。","py":"Tā shì wǒmen gōngsī de dàibiǎo.","vi":"Anh ấy là đại diện của công ty chúng tôi.","en":"He is our company's representative."},{"use":"代表团: đoàn đại biểu","ex":"中国代表团明天到达。","py":"Zhōngguó dàibiǎotuán míngtiān dàodá.","vi":"Đoàn đại biểu Trung Quốc sẽ đến vào ngày mai.","en":"The Chinese delegation arrives tomorrow."}]},"恐怕":{"en":"I'm afraid; perhaps; probably","exs":[{"use":"恐怕 + …了: e rằng sắp xảy ra","ex":"恐怕要下雨了,带把伞吧。","py":"Kǒngpà yào xià yǔ le, dài bǎ sǎn ba.","vi":"E rằng sắp mưa, mang theo ô đi.","en":"I'm afraid it's going to rain; take an umbrella."},{"use":"恐怕 + 不…: dự đoán không khả quan","ex":"这件事恐怕不容易。","py":"Zhè jiàn shì kǒngpà bù róngyì.","vi":"Việc này e rằng không dễ.","en":"I'm afraid this won't be easy."},{"use":"恐怕 + 他不会…: lời từ chối nhẹ nhàng","ex":"恐怕他不会同意。","py":"Kǒngpà tā bú huì tóngyì.","vi":"E rằng anh ấy sẽ không đồng ý.","en":"I'm afraid he won't agree."},{"use":"主语 + 恐怕 + …: vị trí sau chủ ngữ","ex":"我恐怕赶不上火车了。","py":"Wǒ kǒngpà gǎn bu shàng huǒchē le.","vi":"Tôi e là không kịp chuyến tàu rồi.","en":"I'm afraid I can't catch the train."}]},"放假":{"en":"to have a holiday / vacation; to be off","exs":[{"use":"động từ ly hợp: nghỉ làm/nghỉ học","ex":"下个星期一我们放假。","py":"Xià ge xīngqīyī wǒmen fàngjià.","vi":"Thứ Hai tuần sau chúng tôi được nghỉ.","en":"We have the day off next Monday."},{"use":"hỏi thời gian nghỉ","ex":"学校什么时候放假?","py":"Xuéxiào shénme shíhou fàngjià?","vi":"Khi nào trường nghỉ?","en":"When does school break up?"},{"use":"放假以后 + …: sau kỳ nghỉ","ex":"放假以后我想去旅游。","py":"Fàngjià yǐhòu wǒ xiǎng qù lǚyóu.","vi":"Sau khi nghỉ, tôi muốn đi du lịch.","en":"After the break I want to go traveling."},{"use":"放假 + số ngày: nghỉ bao lâu","ex":"国庆节放假七天。","py":"Guóqìngjié fàngjià qī tiān.","vi":"Quốc khánh được nghỉ bảy ngày.","en":"National Day gives a seven-day holiday."}]},"失望":{"en":"disappointed; to lose hope","exs":[{"use":"tính từ: thất vọng vì kết quả","ex":"考试没通过,他很失望。","py":"Kǎoshì méi tōngguò, tā hěn shīwàng.","vi":"Thi không đỗ, anh ấy rất thất vọng.","en":"He was disappointed that he failed the exam."},{"use":"对…失望: thất vọng về…","ex":"我对这次比赛的结果很失望。","py":"Wǒ duì zhè cì bǐsài de jiéguǒ hěn shīwàng.","vi":"Tôi rất thất vọng về kết quả trận đấu lần này.","en":"I am very disappointed with the result of this match."},{"use":"让/令人失望: khiến người khác thất vọng","ex":"他的表现让大家失望了。","py":"Tā de biǎoxiàn ràng dàjiā shīwàng le.","vi":"Biểu hiện của anh ấy khiến mọi người thất vọng.","en":"His performance let everyone down."},{"use":"别失望: an ủi, khuyên đừng nản","ex":"别失望,下次一定会成功。","py":"Bié shīwàng, xià cì yídìng huì chénggōng.","vi":"Đừng thất vọng, lần sau nhất định sẽ thành công.","en":"Don't be discouraged; you'll succeed next time."}]},"郊区":{"en":"suburb; outskirts","exs":[{"use":"住在郊区: sống ở ngoại ô","ex":"他住在郊区,上班要一个小时。","py":"Tā zhù zài jiāoqū, shàngbān yào yí ge xiǎoshí.","vi":"Anh ấy sống ở ngoại ô, đi làm mất một tiếng.","en":"He lives in the suburbs and it takes an hour to get to work."},{"use":"郊区 + 的 + danh từ: so sánh với nội thành","ex":"郊区的空气比市中心好。","py":"Jiāoqū de kōngqì bǐ shìzhōngxīn hǎo.","vi":"Không khí ở ngoại ô tốt hơn trung tâm thành phố.","en":"The air in the suburbs is better than in the city center."},{"use":"去郊区 + hoạt động: đi chơi vùng ngoại ô","ex":"我们周末去郊区爬山。","py":"Wǒmen zhōumò qù jiāoqū pá shān.","vi":"Cuối tuần chúng tôi ra ngoại ô leo núi.","en":"We are going hiking in the suburbs this weekend."}]},"火车票":{"en":"train ticket","exs":[{"use":"买 + 火车票 (lượng từ 张)","ex":"我想买两张去上海的火车票。","py":"Wǒ xiǎng mǎi liǎng zhāng qù Shànghǎi de huǒchēpiào.","vi":"Tôi muốn mua hai vé tàu đi Thượng Hải.","en":"I'd like to buy two train tickets to Shanghai."},{"use":"mô tả mức độ khó mua","ex":"春节的火车票很难买。","py":"Chūnjié de huǒchēpiào hěn nán mǎi.","vi":"Vé tàu dịp Tết rất khó mua.","en":"Train tickets during the Spring Festival are hard to get."},{"use":"在网上订火车票: đặt vé trực tuyến","ex":"你可以在网上订火车票。","py":"Nǐ kěyǐ zài wǎngshàng dìng huǒchēpiào.","vi":"Bạn có thể đặt vé tàu trên mạng.","en":"You can book train tickets online."},{"use":"hỏi vị trí vé","ex":"我的火车票放在哪儿了?","py":"Wǒ de huǒchēpiào fàng zài nǎr le?","vi":"Vé tàu của tôi để đâu rồi nhỉ?","en":"Where did I put my train ticket?"}]},"到底":{"en":"on earth (in questions); finally; after all; to the end","exs":[{"use":"到底 trong câu hỏi: nhấn mạnh 'rốt cuộc'","ex":"你到底想去哪儿?","py":"Nǐ dàodǐ xiǎng qù nǎr?","vi":"Rốt cuộc bạn muốn đi đâu?","en":"Where on earth do you want to go?"},{"use":"nghĩa 'cuối cùng cũng': kết quả sau nỗ lực","ex":"找了半天,他到底找到了钥匙。","py":"Zhǎo le bàntiān, tā dàodǐ zhǎodào le yàoshi.","vi":"Tìm mãi, cuối cùng anh ấy cũng tìm thấy chìa khóa.","en":"After searching a long time, he finally found the keys."},{"use":"nghĩa 'dù sao cũng': đưa ra lý do hiển nhiên","ex":"他到底是个孩子,不懂这些。","py":"Tā dàodǐ shì ge háizi, bù dǒng zhèxiē.","vi":"Dù sao nó cũng chỉ là đứa trẻ, không hiểu những điều này.","en":"After all, he's just a child and doesn't understand these things."},{"use":"V + 到底: làm đến cùng (nghĩa 4)","ex":"不管多难,我们都要坚持到底。","py":"Bùguǎn duō nán, wǒmen dōu yào jiānchí dàodǐ.","vi":"Dù khó đến đâu, chúng ta cũng phải kiên trì đến cùng.","en":"No matter how hard it is, we must persevere to the end."}]},"外地":{"en":"other places; outside one's own locality","exs":[{"use":"外地人: người nơi khác","ex":"他是外地人,不太熟悉这里。","py":"Tā shì wàidì rén, bú tài shúxī zhèlǐ.","vi":"Anh ấy là người tỉnh khác, không quen nơi này lắm.","en":"He is from out of town and isn't very familiar with this place."},{"use":"去外地出差","ex":"经理下周要去外地出差。","py":"Jīnglǐ xià zhōu yào qù wàidì chūchāi.","vi":"Tuần sau giám đốc đi công tác tỉnh khác.","en":"The manager will go on a business trip out of town next week."},{"use":"外地 + 游客: khách từ nơi khác","ex":"很多外地游客来这里看雪。","py":"Hěn duō wàidì yóukè lái zhèlǐ kàn xuě.","vi":"Nhiều du khách tỉnh khác đến đây ngắm tuyết.","en":"Many out-of-town tourists come here to see snow."},{"use":"在外地工作","ex":"我的孩子在外地工作,很少回家。","py":"Wǒ de háizi zài wàidì gōngzuò, hěn shǎo huí jiā.","vi":"Con tôi làm việc ở nơi khác, ít khi về nhà.","en":"My child works in another city and rarely comes home."}]},"导游":{"en":"tour guide","exs":[{"use":"danh từ: hướng dẫn viên","ex":"导游带我们参观了古城。","py":"Dǎoyóu dài wǒmen cānguān le gǔchéng.","vi":"Hướng dẫn viên dẫn chúng tôi đi tham quan phố cổ.","en":"The tour guide took us around the old town."},{"use":"当导游: làm hướng dẫn viên","ex":"她在旅行社当导游。","py":"Tā zài lǚxíngshè dāng dǎoyóu.","vi":"Cô ấy làm hướng dẫn viên ở công ty du lịch.","en":"She works as a tour guide at a travel agency."},{"use":"请导游: thuê hướng dẫn viên","ex":"我们请了一个会说英语的导游。","py":"Wǒmen qǐng le yí ge huì shuō Yīngyǔ de dǎoyóu.","vi":"Chúng tôi thuê một hướng dẫn viên biết nói tiếng Anh.","en":"We hired a guide who speaks English."}]},"不好意思":{"en":"embarrassed; sorry; excuse me","exs":[{"use":"xin lỗi: nói khi đến muộn","ex":"不好意思,我来晚了。","py":"Bù hǎoyìsi, wǒ lái wǎn le.","vi":"Xin lỗi, tôi đến muộn.","en":"Sorry, I'm late."},{"use":"mở lời nhờ vả: 'xin lỗi cho hỏi'","ex":"不好意思,请问洗手间在哪儿?","py":"Bù hǎoyìsi, qǐngwèn xǐshǒujiān zài nǎr?","vi":"Xin lỗi, cho hỏi nhà vệ sinh ở đâu?","en":"Excuse me, where is the restroom?"},{"use":"tính từ: ngượng, e thẹn","ex":"被大家夸奖,她有点儿不好意思。","py":"Bèi dàjiā kuājiǎng, tā yǒudiǎnr bù hǎoyìsi.","vi":"Được mọi người khen, cô ấy hơi ngượng.","en":"She felt a bit shy after being praised by everyone."},{"use":"不好意思 + V: ngại làm gì","ex":"我不好意思拒绝他。","py":"Wǒ bù hǎoyìsi jùjué tā.","vi":"Tôi ngại không dám từ chối anh ấy.","en":"I feel awkward refusing him."}]},"帮忙":{"en":"to help; to do a favor","exs":[{"use":"động từ ly hợp: giúp đỡ","ex":"你能帮忙把这个箱子搬上去吗?","py":"Nǐ néng bāngmáng bǎ zhège xiāngzi bān shàngqù ma?","vi":"Bạn có thể giúp khiêng cái vali này lên không?","en":"Could you help carry this suitcase up?"},{"use":"需要帮忙: khi cần giúp","ex":"如果需要帮忙,请告诉我。","py":"Rúguǒ xūyào bāngmáng, qǐng gàosu wǒ.","vi":"Nếu cần giúp đỡ, xin hãy nói cho tôi biết.","en":"If you need help, please tell me."},{"use":"danh từ: sự giúp đỡ (谢谢你的…)","ex":"谢谢你的帮忙。","py":"Xièxie nǐ de bāngmáng.","vi":"Cảm ơn sự giúp đỡ của bạn.","en":"Thank you for your help."},{"use":"来帮忙: đến giúp","ex":"邻居常常来帮忙。","py":"Línjū chángcháng lái bāngmáng.","vi":"Hàng xóm thường xuyên đến giúp đỡ.","en":"The neighbors often come to help."}]},"解决不了":{"en":"unable to solve","exs":[{"use":"V + 不了: bổ ngữ khả năng phủ định","ex":"这个问题我一个人解决不了。","py":"Zhège wèntí wǒ yí ge rén jiějué bù liǎo.","vi":"Vấn đề này một mình tôi không giải quyết nổi.","en":"I can't solve this problem by myself."},{"use":"如果…解决不了, …: giả thiết","ex":"如果你解决不了,可以问老师。","py":"Rúguǒ nǐ jiějué bù liǎo, kěyǐ wèn lǎoshī.","vi":"Nếu bạn không giải quyết được thì có thể hỏi thầy cô.","en":"If you can't solve it, you can ask the teacher."},{"use":"靠自己 + 解决不了: không thể tự lo","ex":"他的困难靠自己解决不了。","py":"Tā de kùnnan kào zìjǐ jiějué bù liǎo.","vi":"Khó khăn của anh ấy tự mình không thể giải quyết được.","en":"He can't solve his difficulties on his own."}]},"礼貌":{"en":"polite; courtesy; manners","exs":[{"use":"tính từ: 对…很礼貌","ex":"他对客人很礼貌。","py":"Tā duì kèrén hěn lǐmào.","vi":"Anh ấy rất lịch sự với khách.","en":"He is very polite to the guests."},{"use":"不礼貌: bất lịch sự","ex":"打断别人说话是不礼貌的。","py":"Dǎduàn biérén shuōhuà shì bù lǐmào de.","vi":"Ngắt lời người khác là bất lịch sự.","en":"It is impolite to interrupt others."},{"use":"danh từ: 讲礼貌 (biết phép lịch sự)","ex":"孩子要讲礼貌。","py":"Háizi yào jiǎng lǐmào.","vi":"Trẻ em phải biết lễ phép.","en":"Children should mind their manners."},{"use":"礼貌 + 地 + V: làm trạng ngữ","ex":"她礼貌地向老师问好。","py":"Tā lǐmào de xiàng lǎoshī wènhǎo.","vi":"Cô ấy lễ phép chào thầy giáo.","en":"She politely greeted the teacher."}]},"原谅":{"en":"to forgive; to excuse","exs":[{"use":"请原谅 + 我: xin lỗi, xin tha thứ","ex":"请原谅我,我不是故意的。","py":"Qǐng yuánliàng wǒ, wǒ bú shì gùyì de.","vi":"Xin hãy tha thứ cho tôi, tôi không cố ý.","en":"Please forgive me, I didn't do it on purpose."},{"use":"原谅 + ai/lỗi lầm","ex":"妈妈原谅了他的错误。","py":"Māma yuánliàng le tā de cuòwù.","vi":"Mẹ đã tha thứ cho lỗi lầm của anh ấy.","en":"Mom forgave his mistake."},{"use":"得到 + 原谅: danh từ, được tha thứ","ex":"我希望能得到你的原谅。","py":"Wǒ xīwàng néng dédào nǐ de yuánliàng.","vi":"Tôi hy vọng có thể nhận được sự tha thứ của bạn.","en":"I hope to get your forgiveness."},{"use":"不能原谅: không thể tha thứ","ex":"这种错误是不能原谅的。","py":"Zhè zhǒng cuòwù shì bù néng yuánliàng de.","vi":"Loại lỗi này không thể tha thứ được.","en":"This kind of mistake cannot be forgiven."}]},"不仅…也…":{"en":"not only ... but also ...","exs":[{"use":"不仅 A,也 B: cùng chủ ngữ, thêm nghĩa","ex":"他不仅会说英语,也会说法语。","py":"Tā bùjǐn huì shuō Yīngyǔ, yě huì shuō Fǎyǔ.","vi":"Anh ấy không chỉ biết nói tiếng Anh mà còn biết nói tiếng Pháp.","en":"He can speak not only English but also French."},{"use":"不仅 + tính từ,…也 + tính từ","ex":"这家饭馆不仅便宜,味道也很好。","py":"Zhè jiā fànguǎn bùjǐn piányi, wèidào yě hěn hǎo.","vi":"Nhà hàng này không chỉ rẻ mà hương vị cũng rất ngon.","en":"This restaurant is not only cheap, the food is also very good."},{"use":"不仅 + chủ ngữ A,chủ ngữ B + 也: khác chủ ngữ","ex":"不仅我喜欢这部电影,我的朋友们也很喜欢。","py":"Bùjǐn wǒ xǐhuan zhè bù diànyǐng, wǒ de péngyoumen yě hěn xǐhuan.","vi":"Không chỉ tôi thích bộ phim này, bạn bè tôi cũng rất thích.","en":"Not only do I like this movie, my friends like it too."},{"use":"不仅是 A,也是 B","ex":"他不仅是我的老师,也是我的朋友。","py":"Tā bùjǐn shì wǒ de lǎoshī, yě shì wǒ de péngyou.","vi":"Thầy ấy không chỉ là thầy giáo mà còn là bạn của tôi.","en":"He is not only my teacher but also my friend."}]},"竞争":{"en":"to compete; competition","exs":[{"use":"động từ: cạnh tranh giành…","ex":"两家公司在竞争同一个客户。","py":"Liǎng jiā gōngsī zài jìngzhēng tóng yí ge kèhù.","vi":"Hai công ty đang cạnh tranh cùng một khách hàng.","en":"Two companies are competing for the same client."},{"use":"danh từ: 竞争 + 激烈","ex":"现在的工作竞争很激烈。","py":"Xiànzài de gōngzuò jìngzhēng hěn jīliè.","vi":"Cạnh tranh việc làm hiện nay rất khốc liệt.","en":"Competition for jobs is fierce nowadays."},{"use":"竞争力: sức cạnh tranh","ex":"提高产品质量才能增加竞争力。","py":"Tígāo chǎnpǐn zhìliàng cái néng zēngjiā jìngzhēnglì.","vi":"Nâng cao chất lượng sản phẩm mới tăng được sức cạnh tranh.","en":"Only by improving product quality can we become more competitive."},{"use":"竞争对手: đối thủ cạnh tranh","ex":"他是我最大的竞争对手。","py":"Tā shì wǒ zuì dà de jìngzhēng duìshǒu.","vi":"Anh ấy là đối thủ cạnh tranh lớn nhất của tôi.","en":"He is my biggest competitor."}]},"森林":{"en":"forest","exs":[{"use":"danh từ: một vùng rừng","ex":"这座山上有一大片森林。","py":"Zhè zuò shān shàng yǒu yí dà piàn sēnlín.","vi":"Trên ngọn núi này có một vùng rừng lớn.","en":"There is a large forest on this mountain."},{"use":"保护 + 森林: bảo vệ rừng","ex":"我们要保护森林。","py":"Wǒmen yào bǎohù sēnlín.","vi":"Chúng ta phải bảo vệ rừng.","en":"We must protect forests."},{"use":"森林里: trong rừng","ex":"森林里住着很多小动物。","py":"Sēnlín lǐ zhùzhe hěn duō xiǎo dòngwù.","vi":"Trong rừng có rất nhiều con vật nhỏ sinh sống.","en":"Many small animals live in the forest."},{"use":"mô tả không khí","ex":"森林里的空气特别新鲜。","py":"Sēnlín lǐ de kōngqì tèbié xīnxiān.","vi":"Không khí trong rừng đặc biệt trong lành.","en":"The air in the forest is especially fresh."}]},"低矮":{"en":"low and short","exs":[{"use":"tính từ: nhà cửa thấp bé","ex":"这里的房子都很低矮。","py":"Zhèlǐ de fángzi dōu hěn dī'ǎi.","vi":"Nhà cửa ở đây đều thấp bé.","en":"The houses here are all low."},{"use":"低矮 + 的 + danh từ: làm định ngữ","ex":"路边有一些低矮的小树。","py":"Lù biān yǒu yìxiē dī'ǎi de xiǎoshù.","vi":"Ven đường có vài cây nhỏ thấp bé.","en":"There are some short little trees by the road."},{"use":"又…又…: kết hợp hai tính chất","ex":"这间屋子又低矮又黑。","py":"Zhè jiān wūzi yòu dī'ǎi yòu hēi.","vi":"Căn phòng này vừa thấp vừa tối.","en":"This room is both low and dark."}]},"暖和":{"en":"warm; to warm up","exs":[{"use":"tính từ: thời tiết ấm","ex":"今天天气很暖和。","py":"Jīntiān tiānqì hěn nuǎnhuo.","vi":"Hôm nay thời tiết rất ấm áp.","en":"The weather is nice and warm today."},{"use":"暖和 + 一些: so sánh, ấm hơn","ex":"外面冷,多穿点儿,暖和一些。","py":"Wàimiàn lěng, duō chuān diǎnr, nuǎnhuo yìxiē.","vi":"Bên ngoài lạnh, mặc nhiều vào cho ấm hơn.","en":"It's cold outside; wear more to keep warmer."},{"use":"động từ (lặp): sưởi ấm","ex":"来,进屋暖和暖和。","py":"Lái, jìn wū nuǎnhuo nuǎnhuo.","vi":"Nào, vào nhà sưởi ấm một chút.","en":"Come on in and warm up a bit."},{"use":"暖和 + 的 + danh từ (đồ vật ấm)","ex":"她给我买了一件暖和的毛衣。","py":"Tā gěi wǒ mǎi le yí jiàn nuǎnhuo de máoyī.","vi":"Cô ấy mua cho tôi một chiếc áo len ấm.","en":"She bought me a warm sweater."}]},"水分":{"en":"moisture; water content","exs":[{"use":"hàm lượng nước của trái cây","ex":"西瓜里水分很多。","py":"Xīguā lǐ shuǐfèn hěn duō.","vi":"Dưa hấu có nhiều nước.","en":"Watermelon has a lot of water in it."},{"use":"缺少水分: thiếu ẩm (da)","ex":"冬天皮肤容易缺少水分。","py":"Dōngtiān pífū róngyì quēshǎo shuǐfèn.","vi":"Mùa đông da dễ bị thiếu nước.","en":"In winter, skin easily becomes dry."},{"use":"thực vật cần nước","ex":"花需要足够的阳光和水分。","py":"Huā xūyào zúgòu de yángguāng hé shuǐfèn.","vi":"Hoa cần đủ ánh nắng và nước.","en":"Flowers need enough sunlight and water."},{"use":"nghĩa bóng: 有水分 (số liệu bị thổi phồng)","ex":"这个数字有水分。","py":"Zhège shùzì yǒu shuǐfèn.","vi":"Con số này có phần thổi phồng.","en":"This figure is exaggerated."}]},"海洋":{"en":"ocean; sea","exs":[{"use":"danh từ: diện tích đại dương","ex":"地球上海洋比陆地大。","py":"Dìqiú shàng hǎiyáng bǐ lùdì dà.","vi":"Trên Trái Đất, đại dương rộng hơn đất liền.","en":"Oceans are larger than land on Earth."},{"use":"海洋里: trong biển","ex":"海洋里有很多奇怪的动物。","py":"Hǎiyáng lǐ yǒu hěn duō qíguài de dòngwù.","vi":"Trong đại dương có rất nhiều loài động vật kỳ lạ.","en":"There are many strange animals in the ocean."},{"use":"污染/保护 + 海洋","ex":"污染海洋会伤害鱼类。","py":"Wūrǎn hǎiyáng huì shānghài yúlèi.","vi":"Làm ô nhiễm đại dương sẽ gây hại cho các loài cá.","en":"Polluting the ocean harms fish."},{"use":"海洋馆: thủy cung","ex":"我们周末去了海洋馆。","py":"Wǒmen zhōumò qù le hǎiyángguǎn.","vi":"Cuối tuần chúng tôi đã đi thủy cung.","en":"We went to the aquarium on the weekend."}]},"海底":{"en":"seabed; sea floor","exs":[{"use":"非常 + tính từ: rất… (câu có sẵn)","ex":"海底世界非常美丽。","py":"Hǎidǐ shìjiè fēicháng měilì.","vi":"Thế giới dưới đáy biển rất đẹp.","en":"The undersea world is very beautiful."},{"use":"海底 + 有…: dưới đáy biển có","ex":"海底有很多漂亮的鱼。","py":"Hǎidǐ yǒu hěn duō piàoliang de yú.","vi":"Dưới đáy biển có rất nhiều con cá đẹp.","en":"There are many beautiful fish on the sea floor."},{"use":"潜到海底: lặn xuống đáy biển","ex":"他潜到海底拍了一些照片。","py":"Tā qián dào hǎidǐ pāi le yìxiē zhàopiàn.","vi":"Anh ấy lặn xuống đáy biển chụp vài tấm ảnh.","en":"He dove to the seabed and took some photos."},{"use":"海底隧道: đường hầm dưới biển","ex":"这条海底隧道有五公里长。","py":"Zhè tiáo hǎidǐ suìdào yǒu wǔ gōnglǐ cháng.","vi":"Đường hầm dưới biển này dài năm cây số.","en":"This undersea tunnel is five kilometers long."},{"use":"thành ngữ 海底捞针: mò kim đáy bể","ex":"找一个人像海底捞针一样难。","py":"Zhǎo yí ge rén xiàng hǎidǐ lāo zhēn yíyàng nán.","vi":"Tìm một người khó như mò kim đáy bể.","en":"Finding one person is as hard as looking for a needle in a haystack."}]},"美人鱼":{"en":"mermaid","exs":[{"use":"danh từ: nhân vật truyện cổ tích","ex":"我小时候最喜欢美人鱼的故事。","py":"Wǒ xiǎoshíhou zuì xǐhuan měirényú de gùshi.","vi":"Hồi nhỏ tôi thích nhất câu chuyện nàng tiên cá.","en":"As a child I liked the mermaid story best."},{"use":"truyền thuyết: 传说…住着一条美人鱼 (lượng từ 条)","ex":"传说海里住着一条美人鱼。","py":"Chuánshuō hǎi lǐ zhùzhe yì tiáo měirényú.","vi":"Truyền thuyết kể rằng trong biển có một nàng tiên cá.","en":"Legend has it that a mermaid lives in the sea."},{"use":"扮成 + 美人鱼: hóa trang","ex":"女儿想在万圣节扮成美人鱼。","py":"Nǚ'ér xiǎng zài Wànshèngjié bànchéng měirényú.","vi":"Con gái muốn hóa trang thành nàng tiên cá dịp Halloween.","en":"My daughter wants to dress up as a mermaid for Halloween."},{"use":"trong phim ảnh","ex":"这部电影讲的是一条美人鱼爱上了王子。","py":"Zhè bù diànyǐng jiǎng de shì yì tiáo měirényú àishàng le wángzǐ.","vi":"Bộ phim này kể về nàng tiên cá yêu hoàng tử.","en":"This movie is about a mermaid who falls in love with a prince."}]},"耳朵":{"en":"ear","exs":[{"use":"danh từ: bộ phận cơ thể","ex":"我的耳朵有点儿疼。","py":"Wǒ de ěrduo yǒudiǎnr téng.","vi":"Tai tôi hơi đau.","en":"My ear hurts a little."},{"use":"mô tả động vật","ex":"兔子的耳朵很长。","py":"Tùzi de ěrduo hěn cháng.","vi":"Tai của con thỏ rất dài.","en":"A rabbit's ears are very long."},{"use":"竖起耳朵: dỏng tai lên nghe","ex":"他竖起耳朵听外面的声音。","py":"Tā shùqǐ ěrduo tīng wàimiàn de shēngyīn.","vi":"Anh ấy dỏng tai nghe tiếng động bên ngoài.","en":"He pricked up his ears to listen to the sounds outside."},{"use":"耳朵灵: nghĩa bóng, thính tai, nhanh tin","ex":"她耳朵很灵,什么消息都知道。","py":"Tā ěrduo hěn líng, shénme xiāoxi dōu zhīdào.","vi":"Cô ấy tai rất thính, tin gì cũng biết.","en":"She has sharp ears and knows all the news."}]},"仍然":{"en":"still; yet","exs":[{"use":"仍然 + V: vẫn đang…","ex":"已经十点了,他仍然在工作。","py":"Yǐjīng shí diǎn le, tā réngrán zài gōngzuò.","vi":"Đã mười giờ rồi mà anh ấy vẫn đang làm việc.","en":"It's already ten o'clock and he is still working."},{"use":"虽然…仍然…: dù…vẫn…","ex":"虽然下雨,比赛仍然进行。","py":"Suīrán xià yǔ, bǐsài réngrán jìnxíng.","vi":"Dù trời mưa, trận đấu vẫn diễn ra.","en":"Although it's raining, the match is still going ahead."},{"use":"仍然 + 没/不: vẫn chưa/không","ex":"虽然试了很多次,他仍然没成功。","py":"Suīrán shì le hěn duō cì, tā réngrán méi chénggōng.","vi":"Dù thử nhiều lần, anh ấy vẫn chưa thành công.","en":"Although he tried many times, he still hasn't succeeded."},{"use":"仍然 + nhớ/giữ nguyên trạng thái","ex":"多年以后,她仍然记得那天。","py":"Duō nián yǐhòu, tā réngrán jìde nà tiān.","vi":"Nhiều năm sau, cô ấy vẫn nhớ ngày hôm đó.","en":"Many years later, she still remembers that day."}]},"亮光":{"en":"light; glimmer","exs":[{"use":"一点亮光: một chút ánh sáng","ex":"远处有一点亮光。","py":"Yuǎnchù yǒu yìdiǎn liàngguāng.","vi":"Phía xa có một chút ánh sáng.","en":"There is a little light in the distance."},{"use":"没有亮光: không có ánh sáng","ex":"屋子里没有一点亮光。","py":"Wūzi lǐ méiyǒu yìdiǎn liàngguāng.","vi":"Trong phòng không có chút ánh sáng nào.","en":"There isn't a bit of light in the room."},{"use":"一道亮光: lượng từ 道","ex":"清晨,一道亮光从窗户照进来。","py":"Qīngchén, yí dào liàngguāng cóng chuānghu zhào jìnlái.","vi":"Sáng sớm, một tia sáng chiếu qua cửa sổ.","en":"In the early morning, a beam of light shone through the window."},{"use":"发出亮光: phát sáng","ex":"深海里的鱼身上会发出亮光。","py":"Shēnhǎi lǐ de yú shēnshang huì fāchū liàngguāng.","vi":"Cá ở biển sâu có thể phát ra ánh sáng.","en":"Fish in the deep sea can give off light."}]},"排列":{"en":"to arrange; to line up; arrangement","exs":[{"use":"按 + tiêu chí + 排列: sắp xếp theo","ex":"请把这些词按顺序排列。","py":"Qǐng bǎ zhèxiē cí àn shùnxù páiliè.","vi":"Xin hãy sắp xếp các từ này theo thứ tự.","en":"Please arrange these words in order."},{"use":"排列整齐: xếp hàng ngay ngắn","ex":"学生们排列整齐地站在操场上。","py":"Xuéshengmen páiliè zhěngqí de zhàn zài cāochǎng shàng.","vi":"Học sinh đứng xếp hàng ngay ngắn trên sân.","en":"The students stood in neat rows on the playground."},{"use":"排列 + 在…: xếp ở đâu","ex":"书按大小排列在书架上。","py":"Shū àn dàxiǎo páiliè zài shūjià shàng.","vi":"Sách được xếp trên giá theo kích cỡ.","en":"The books are arranged on the shelf by size."},{"use":"danh từ: cách sắp xếp","ex":"这些字的排列有一定规律。","py":"Zhèxiē zì de páiliè yǒu yídìng guīlǜ.","vi":"Cách sắp xếp của những chữ này có quy luật nhất định.","en":"The arrangement of these characters follows a pattern."}]},"社会":{"en":"society; community; the social world","exs":[{"use":"làm danh từ, chỉ xã hội nói chung","ex":"现代社会发展得很快。","py":"Xiàndài shèhuì fāzhǎn de hěn kuài.","vi":"Xã hội hiện đại phát triển rất nhanh.","en":"Modern society is developing very fast."},{"use":"社会 + danh từ: 社会问题, 社会责任","ex":"老师说我们每个人都要有社会责任感。","py":"Lǎoshī shuō wǒmen měi ge rén dōu yào yǒu shèhuì zérèngǎn.","vi":"Thầy giáo nói mỗi chúng ta đều phải có tinh thần trách nhiệm với xã hội.","en":"The teacher said each of us should have a sense of social responsibility."},{"use":"进入社会: bước vào đời, đi làm","ex":"大学毕业以后,他很快就进入了社会。","py":"Dàxué bìyè yǐhòu, tā hěn kuài jiù jìnrù le shèhuì.","vi":"Sau khi tốt nghiệp đại học, anh ấy nhanh chóng bước vào xã hội.","en":"After graduating from university, he soon entered the working world."}]},"奇怪":{"en":"strange; odd; weird","exs":[{"use":"làm vị ngữ: 觉得/很 + 奇怪","ex":"这件事真奇怪,我怎么都想不明白。","py":"Zhè jiàn shì zhēn qíguài, wǒ zěnme dōu xiǎng bu míngbai.","vi":"Chuyện này thật kỳ lạ, tôi nghĩ thế nào cũng không hiểu.","en":"This is really strange; I just can't figure it out."},{"use":"奇怪的 + danh từ: làm định ngữ","ex":"我昨天晚上听到了一个奇怪的声音。","py":"Wǒ zuótiān wǎnshang tīngdào le yí ge qíguài de shēngyīn.","vi":"Tối qua tôi nghe thấy một âm thanh kỳ lạ.","en":"Last night I heard a strange sound."},{"use":"真奇怪: dùng để bày tỏ sự ngạc nhiên, khó hiểu","ex":"真奇怪,他今天怎么没来上班?","py":"Zhēn qíguài, tā jīntiān zěnme méi lái shàngbān?","vi":"Lạ thật, sao hôm nay anh ấy không đến làm?","en":"How strange, why didn't he come to work today?"}]},"高大":{"en":"tall and big; tall and sturdy","exs":[{"use":"làm định ngữ: 高大的 + danh từ","ex":"院子里有一棵高大的树。","py":"Yuànzi lǐ yǒu yì kē gāodà de shù.","vi":"Trong sân có một cây to cao.","en":"There is a tall, big tree in the yard."},{"use":"làm vị ngữ miêu tả người","ex":"他长得又高大又帅。","py":"Tā zhǎng de yòu gāodà yòu shuài.","vi":"Anh ấy vừa cao lớn vừa đẹp trai.","en":"He is both tall and handsome."},{"use":"miêu tả vật thể (nhà, núi…)","ex":"远处是一座高大的山。","py":"Yuǎnchù shì yí zuò gāodà de shān.","vi":"Phía xa là một ngọn núi cao lớn.","en":"In the distance there is a tall, massive mountain."}]},"剩下":{"en":"to be left over; to remain","exs":[{"use":"động từ: 剩下 + danh từ","ex":"盘子里只剩下一点儿菜了。","py":"Pánzi lǐ zhǐ shèngxià yìdiǎnr cài le.","vi":"Trong đĩa chỉ còn lại một ít thức ăn.","en":"Only a little food is left on the plate."},{"use":"剩下的 + danh từ: phần còn lại","ex":"剩下的工作明天再做吧。","py":"Shèngxià de gōngzuò míngtiān zài zuò ba.","vi":"Phần việc còn lại ngày mai làm tiếp nhé.","en":"Let's do the remaining work tomorrow."},{"use":"dùng với số lượng: 只/就 + 剩下 + số lượng","ex":"钱花完了,我身上就剩下十块钱。","py":"Qián huā wán le, wǒ shēnshang jiù shèngxià shí kuài qián.","vi":"Tiêu hết tiền rồi, trên người tôi chỉ còn lại mười đồng.","en":"I've spent my money; I only have ten yuan left on me."}]},"各地":{"en":"various places; all over the place; everywhere","exs":[{"use":"各地 + 的 + danh từ: chỉ nhiều nơi khác nhau","ex":"来自各地的游客都很喜欢这里。","py":"Láizì gèdì de yóukè dōu hěn xǐhuan zhèlǐ.","vi":"Du khách đến từ khắp nơi đều rất thích chỗ này.","en":"Tourists from all over love this place."},{"use":"làm trạng ngữ chỉ nơi chốn: 在各地","ex":"这家公司在全国各地都有分店。","py":"Zhè jiā gōngsī zài quánguó gèdì dōu yǒu fēndiàn.","vi":"Công ty này có chi nhánh ở khắp nơi trong cả nước.","en":"This company has branches all over the country."},{"use":"各地 + 的 + 人/习惯","ex":"各地的春节习惯不太一样。","py":"Gèdì de Chūnjié xíguàn bú tài yíyàng.","vi":"Phong tục Tết ở các nơi không giống nhau lắm.","en":"Spring Festival customs differ from place to place."}]},"地方":{"en":"place; space; room; part","exs":[{"use":"nghĩa 1: nơi chốn, địa điểm","ex":"你知道哪儿有好玩的地方吗?","py":"Nǐ zhīdào nǎr yǒu hǎowán de dìfang ma?","vi":"Bạn biết chỗ nào chơi vui không?","en":"Do you know any fun places?"},{"use":"nghĩa 2: chỗ, khoảng trống (有/没有地方)","ex":"房间太小了,没有地方放书。","py":"Fángjiān tài xiǎo le, méiyǒu dìfang fàng shū.","vi":"Phòng nhỏ quá, không có chỗ để sách.","en":"The room is too small; there's no space to put books."},{"use":"nghĩa 3: bộ phận, điểm (……的地方)","ex":"这篇文章有几个地方我没看懂。","py":"Zhè piān wénzhāng yǒu jǐ ge dìfang wǒ méi kàndǒng.","vi":"Bài văn này có mấy chỗ tôi chưa hiểu.","en":"There are a few parts of this article I didn't understand."}]},"动物":{"en":"animal","exs":[{"use":"làm danh từ chỉ động vật nói chung","ex":"你最喜欢什么动物?","py":"Nǐ zuì xǐhuan shénme dòngwù?","vi":"Bạn thích con vật nào nhất?","en":"What animal do you like best?"},{"use":"动物 + danh từ: 野生动物, 小动物","ex":"这里有很多野生动物。","py":"Zhèlǐ yǒu hěn duō yěshēng dòngwù.","vi":"Ở đây có rất nhiều động vật hoang dã.","en":"There are a lot of wild animals here."},{"use":"爱护动物: câu khuyên nhủ","ex":"我们应该爱护动物,不要伤害它们。","py":"Wǒmen yīnggāi àihù dòngwù, bú yào shānghài tāmen.","vi":"Chúng ta nên yêu quý động vật, đừng làm hại chúng.","en":"We should care for animals and not harm them."}]},"底部":{"en":"bottom; base","exs":[{"use":"底部: phần đáy của vật","ex":"杯子的底部有一个小洞。","py":"Bēizi de dǐbù yǒu yí ge xiǎo dòng.","vi":"Đáy cốc có một cái lỗ nhỏ.","en":"There is a small hole at the bottom of the cup."},{"use":"在……底部: chỉ vị trí","ex":"请看屏幕底部的小字。","py":"Qǐng kàn píngmù dǐbù de xiǎo zì.","vi":"Xin hãy xem dòng chữ nhỏ ở phần dưới cùng của màn hình.","en":"Please look at the small print at the bottom of the screen."},{"use":"底部 + có/…: nói về đáy chai, hộp…","ex":"瓶子底部有一层水。","py":"Píngzi dǐbù yǒu yì céng shuǐ.","vi":"Ở đáy chai có một lớp nước.","en":"There is a layer of water at the bottom of the bottle."}]},"只不过":{"en":"only; merely; it's just that","exs":[{"use":"只不过 + cụm từ: 'chẳng qua chỉ là', giảm nhẹ mức độ","ex":"他只不过是开了个玩笑,你别生气。","py":"Tā zhǐ búguò shì kāi le ge wánxiào, nǐ bié shēngqì.","vi":"Anh ấy chẳng qua chỉ đùa thôi, bạn đừng giận.","en":"He was just joking; don't be angry."},{"use":"……,只不过……: nối hai vế, nêu điểm hạn chế nhỏ","ex":"这个房子很好,只不过离地铁站有点儿远。","py":"Zhège fángzi hěn hǎo, zhǐ búguò lí dìtiězhàn yǒudiǎnr yuǎn.","vi":"Căn nhà này rất tốt, chỉ có điều hơi xa ga tàu điện.","en":"This house is great; it's just a bit far from the subway station."},{"use":"只不过 + số lượng: chỉ có chừng đó","ex":"我只不过等了五分钟,他就来了。","py":"Wǒ zhǐ búguò děng le wǔ fēnzhōng, tā jiù lái le.","vi":"Tôi chỉ mới đợi năm phút là anh ấy đã đến.","en":"I had only waited five minutes when he arrived."}]},"公里":{"en":"kilometer","exs":[{"use":"lượng từ/đơn vị: số + 公里","ex":"从我家到公司有十公里。","py":"Cóng wǒ jiā dào gōngsī yǒu shí gōnglǐ.","vi":"Từ nhà tôi đến công ty là mười ki-lô-mét.","en":"It is ten kilometers from my home to the company."},{"use":"每小时 + số + 公里: chỉ tốc độ","ex":"这辆车每小时能开一百二十公里。","py":"Zhè liàng chē měi xiǎoshí néng kāi yìbǎi èrshí gōnglǐ.","vi":"Chiếc xe này mỗi giờ chạy được một trăm hai mươi ki-lô-mét.","en":"This car can go 120 kilometers per hour."},{"use":"跑 + số + 公里: chỉ quãng đường chạy","ex":"他每天早上都跑五公里。","py":"Tā měitiān zǎoshang dōu pǎo wǔ gōnglǐ.","vi":"Mỗi sáng anh ấy đều chạy năm ki-lô-mét.","en":"He runs five kilometers every morning."}]},"凉快":{"en":"cool; pleasantly cool","exs":[{"use":"làm vị ngữ: thời tiết/chỗ mát mẻ dễ chịu","ex":"秋天到了,天气凉快多了。","py":"Qiūtiān dào le, tiānqì liángkuai duō le.","vi":"Thu đến rồi, thời tiết mát mẻ hơn nhiều.","en":"Autumn has come and the weather is much cooler."},{"use":"找个地方凉快凉快: động từ lặp lại, nghĩa 'hóng mát'","ex":"天太热了,我们去树下凉快凉快吧。","py":"Tiān tài rè le, wǒmen qù shù xià liángkuai liángkuai ba.","vi":"Trời nóng quá, chúng ta ra dưới gốc cây hóng mát đi.","en":"It's too hot; let's go cool off under the tree."},{"use":"房间里 + 凉快: chỉ không gian mát","ex":"开了空调以后,屋子里很凉快。","py":"Kāi le kōngtiáo yǐhòu, wūzi lǐ hěn liángkuai.","vi":"Sau khi bật điều hòa, trong phòng rất mát.","en":"After turning on the air conditioner, it's nice and cool in the room."}]},"草地":{"en":"grass; lawn; meadow","exs":[{"use":"danh từ: bãi cỏ, đồng cỏ","ex":"孩子们在草地上玩儿得很开心。","py":"Háizimen zài cǎodì shang wánr de hěn kāixīn.","vi":"Bọn trẻ chơi trên bãi cỏ rất vui.","en":"The children are having a great time playing on the grass."},{"use":"坐/躺 + 在草地上","ex":"周末我们坐在草地上野餐。","py":"Zhōumò wǒmen zuò zài cǎodì shang yěcān.","vi":"Cuối tuần chúng tôi ngồi trên bãi cỏ dã ngoại.","en":"On weekends we picnic on the lawn."},{"use":"大草地: đồng cỏ rộng","ex":"公园里有一大片绿绿的草地。","py":"Gōngyuán lǐ yǒu yí dà piàn lǜlǜ de cǎodì.","vi":"Trong công viên có một bãi cỏ xanh rộng lớn.","en":"There is a large green lawn in the park."}]},"黄叶":{"en":"yellow leaves","exs":[{"use":"danh từ: lá vàng (mùa thu)","ex":"地上落满了黄叶。","py":"Dìshang luò mǎn le huángyè.","vi":"Trên mặt đất rụng đầy lá vàng.","en":"The ground is covered with fallen yellow leaves."},{"use":"黄叶 + động từ: 飘/落","ex":"风一吹,黄叶就从树上飘下来了。","py":"Fēng yì chuī, huángyè jiù cóng shù shang piāo xiàlái le.","vi":"Gió vừa thổi, lá vàng liền bay xuống từ trên cây.","en":"As soon as the wind blew, yellow leaves drifted down from the tree."},{"use":"捡/看 + 黄叶","ex":"女儿喜欢捡黄叶做书签。","py":"Nǚ'ér xǐhuan jiǎn huángyè zuò shūqiān.","vi":"Con gái tôi thích nhặt lá vàng làm thẻ đánh dấu sách.","en":"My daughter likes to pick up yellow leaves to make bookmarks."}]},"秋天":{"en":"autumn; fall","exs":[{"use":"danh từ chỉ mùa","ex":"北京的秋天非常漂亮。","py":"Běijīng de qiūtiān fēicháng piàoliang.","vi":"Mùa thu ở Bắc Kinh rất đẹp.","en":"Autumn in Beijing is very beautiful."},{"use":"在秋天: làm trạng ngữ thời gian","ex":"他是在秋天出生的。","py":"Tā shì zài qiūtiān chūshēng de.","vi":"Anh ấy sinh vào mùa thu.","en":"He was born in autumn."},{"use":"秋天 + 到了/来了","ex":"秋天到了,树叶慢慢变黄了。","py":"Qiūtiān dào le, shùyè mànmàn biàn huáng le.","vi":"Mùa thu đến rồi, lá cây dần dần vàng đi.","en":"Autumn has arrived and the leaves are slowly turning yellow."}]},"安娜":{"en":"Anna (a personal name)","exs":[{"use":"tên người nước ngoài (nữ)","ex":"安娜是我的同学,她来自俄罗斯。","py":"Ānnà shì wǒ de tóngxué, tā láizì Éluósī.","vi":"Anna là bạn học của tôi, cô ấy đến từ Nga.","en":"Anna is my classmate; she comes from Russia."},{"use":"安娜 làm chủ ngữ trong câu hỏi","ex":"安娜今天为什么没来上课?","py":"Ānnà jīntiān wèishénme méi lái shàngkè?","vi":"Hôm nay vì sao Anna không đến lớp?","en":"Why didn't Anna come to class today?"},{"use":"给 + 安娜 + động từ","ex":"我给安娜打了一个电话。","py":"Wǒ gěi Ānnà dǎ le yí ge diànhuà.","vi":"Tôi đã gọi điện cho Anna.","en":"I made a phone call to Anna."}]},"香山":{"en":"Fragrant Hills (Xiangshan, a scenic hill in Beijing)","exs":[{"use":"địa danh nổi tiếng ở Bắc Kinh, nổi tiếng với lá đỏ","ex":"秋天很多人去香山看红叶。","py":"Qiūtiān hěn duō rén qù Xiāngshān kàn hóngyè.","vi":"Mùa thu rất nhiều người đến Hương Sơn ngắm lá đỏ.","en":"In autumn many people go to Fragrant Hills to see the red leaves."},{"use":"去/爬 + 香山","ex":"这个周末我们打算去爬香山。","py":"Zhège zhōumò wǒmen dǎsuàn qù pá Xiāngshān.","vi":"Cuối tuần này chúng tôi định đi leo Hương Sơn.","en":"This weekend we plan to climb Fragrant Hills."},{"use":"香山 + 在 + địa điểm","ex":"香山在北京的西边。","py":"Xiāngshān zài Běijīng de xībian.","vi":"Hương Sơn nằm ở phía tây Bắc Kinh.","en":"Fragrant Hills is in the west of Beijing."}]},"热闹":{"en":"lively; bustling; (to) liven up","exs":[{"use":"tính từ làm vị ngữ: náo nhiệt","ex":"春节的时候,街上特别热闹。","py":"Chūnjié de shíhou, jiē shang tèbié rènao.","vi":"Vào dịp Tết, đường phố đặc biệt náo nhiệt.","en":"During the Spring Festival, the streets are especially lively."},{"use":"热闹的 + danh từ: làm định ngữ","ex":"他们在一个热闹的市场里买东西。","py":"Tāmen zài yí ge rènao de shìchǎng lǐ mǎi dōngxi.","vi":"Họ mua đồ trong một khu chợ nhộn nhịp.","en":"They are shopping in a bustling market."},{"use":"động từ: 凑热闹 (góp vui), 热闹热闹 (làm cho vui)","ex":"明天有聚会,你也来热闹热闹吧。","py":"Míngtiān yǒu jùhuì, nǐ yě lái rènao rènao ba.","vi":"Ngày mai có buổi họp mặt, bạn cũng đến cho vui nhé.","en":"There's a party tomorrow; come join the fun."}]},"气温":{"en":"air temperature","exs":[{"use":"danh từ: nhiệt độ không khí","ex":"今天的气温是二十五度。","py":"Jīntiān de qìwēn shì èrshíwǔ dù.","vi":"Nhiệt độ hôm nay là hai mươi lăm độ.","en":"Today's temperature is 25 degrees."},{"use":"气温 + 升高/下降","ex":"这几天气温下降得很快。","py":"Zhè jǐ tiān qìwēn xiàjiàng de hěn kuài.","vi":"Mấy ngày nay nhiệt độ giảm rất nhanh.","en":"The temperature has dropped quickly these past few days."},{"use":"最高/最低 + 气温","ex":"明天最低气温只有五度,要多穿点儿衣服。","py":"Míngtiān zuìdī qìwēn zhǐyǒu wǔ dù, yào duō chuān diǎnr yīfu.","vi":"Ngày mai nhiệt độ thấp nhất chỉ có năm độ, phải mặc nhiều áo vào.","en":"Tomorrow's low is only 5 degrees, so wear more clothes."}]},"那里":{"en":"there; that place","exs":[{"use":"đại từ chỉ nơi chốn: ở đó","ex":"你去过那里吗?","py":"Nǐ qùguo nàlǐ ma?","vi":"Bạn đã từng đến đó chưa?","en":"Have you ever been there?"},{"use":"那里 + 的 + danh từ","ex":"那里的东西又好又便宜。","py":"Nàlǐ de dōngxi yòu hǎo yòu piányi.","vi":"Đồ ở đó vừa tốt vừa rẻ.","en":"The things there are both good and cheap."},{"use":"到/在 + 那里","ex":"我在那里住了三年。","py":"Wǒ zài nàlǐ zhù le sān nián.","vi":"Tôi đã sống ở đó ba năm.","en":"I lived there for three years."}]},"游客":{"en":"tourist; visitor","exs":[{"use":"danh từ: khách du lịch","ex":"每年有很多外国游客来中国旅游。","py":"Měi nián yǒu hěn duō wàiguó yóukè lái Zhōngguó lǚyóu.","vi":"Mỗi năm có rất nhiều du khách nước ngoài đến Trung Quốc du lịch.","en":"Every year many foreign tourists come to China."},{"use":"游客 + 很多/不多: số lượng","ex":"节日的时候,公园里游客特别多。","py":"Jiérì de shíhou, gōngyuán lǐ yóukè tèbié duō.","vi":"Vào dịp lễ, trong công viên đặc biệt đông khách du lịch.","en":"On holidays the park is especially crowded with tourists."},{"use":"给游客 + động từ","ex":"导游给游客介绍了这个地方的历史。","py":"Dǎoyóu gěi yóukè jièshào le zhège dìfang de lìshǐ.","vi":"Hướng dẫn viên giới thiệu lịch sử nơi này cho du khách.","en":"The guide introduced the history of this place to the tourists."}]},"天上":{"en":"in the sky; up in the sky","exs":[{"use":"danh từ phương vị: 天上 + có/…","ex":"天上有很多星星。","py":"Tiānshàng yǒu hěn duō xīngxing.","vi":"Trên trời có rất nhiều ngôi sao.","en":"There are many stars in the sky."},{"use":"在天上 + động từ","ex":"一只鸟在天上飞。","py":"Yì zhī niǎo zài tiānshàng fēi.","vi":"Một con chim đang bay trên trời.","en":"A bird is flying in the sky."},{"use":"天上 + 的 + danh từ","ex":"天上的云慢慢地飘走了。","py":"Tiānshàng de yún mànmān de piāo zǒu le.","vi":"Mây trên trời từ từ bay đi.","en":"The clouds in the sky drifted slowly away."}]},"大雨":{"en":"heavy rain","exs":[{"use":"danh từ: mưa lớn (下大雨)","ex":"昨天晚上下了一场大雨。","py":"Zuótiān wǎnshang xià le yì cháng dàyǔ.","vi":"Tối qua có một trận mưa lớn.","en":"There was a heavy rain last night."},{"use":"被/淋 + 大雨","ex":"他在路上被大雨淋湿了。","py":"Tā zài lùshang bèi dàyǔ lín shī le.","vi":"Anh ấy bị mưa lớn làm ướt hết trên đường.","en":"He got soaked by the heavy rain on the way."},{"use":"因为 + 大雨……","ex":"因为大雨,比赛改到了明天。","py":"Yīnwèi dàyǔ, bǐsài gǎi dào le míngtiān.","vi":"Vì mưa lớn nên trận đấu dời sang ngày mai.","en":"Because of the heavy rain, the match was moved to tomorrow."}]},"红叶":{"en":"red leaves; autumn foliage","exs":[{"use":"danh từ: lá đỏ mùa thu","ex":"香山的红叶非常有名。","py":"Xiāngshān de hóngyè fēicháng yǒumíng.","vi":"Lá đỏ ở Hương Sơn rất nổi tiếng.","en":"The red leaves of Fragrant Hills are very famous."},{"use":"看红叶: đi ngắm lá đỏ","ex":"每年十月,我们都去看红叶。","py":"Měi nián shíyuè, wǒmen dōu qù kàn hóngyè.","vi":"Mỗi năm vào tháng mười, chúng tôi đều đi ngắm lá đỏ.","en":"Every October we go to see the red leaves."},{"use":"红叶 + 红了/漂亮","ex":"山上的红叶红了,漂亮极了。","py":"Shān shang de hóngyè hóng le, piàoliang jí le.","vi":"Lá đỏ trên núi đã đỏ rồi, đẹp vô cùng.","en":"The red leaves on the mountain have turned red; they're gorgeous."}]},"改天":{"en":"another day; some other day","exs":[{"use":"trạng ngữ thời gian: hôm khác (thường dùng để từ chối nhẹ nhàng)","ex":"今天我有事,改天再聊吧。","py":"Jīntiān wǒ yǒu shì, gǎitiān zài liáo ba.","vi":"Hôm nay tôi có việc, hôm khác nói chuyện nhé.","en":"I'm busy today; let's chat another day."},{"use":"改天 + 请你……: hẹn mời","ex":"改天我请你吃饭。","py":"Gǎitiān wǒ qǐng nǐ chīfàn.","vi":"Hôm khác tôi mời bạn ăn cơm.","en":"I'll treat you to a meal another day."},{"use":"改天再 + động từ","ex":"这本书太贵了,我改天再来买。","py":"Zhè běn shū tài guì le, wǒ gǎitiān zài lái mǎi.","vi":"Cuốn sách này đắt quá, hôm khác tôi sẽ quay lại mua.","en":"This book is too expensive; I'll come back and buy it another day."}]},"长城":{"en":"the Great Wall","exs":[{"use":"danh từ riêng: Vạn Lý Trường Thành","ex":"我想去北京爬长城。","py":"Wǒ xiǎng qù Běijīng pá Chángchéng.","vi":"Tôi muốn đến Bắc Kinh leo Trường Thành.","en":"I want to go to Beijing to climb the Great Wall."},{"use":"不到长城非好汉: thành ngữ nổi tiếng","ex":"俗话说,不到长城非好汉。","py":"Súhuà shuō, bú dào Chángchéng fēi hǎohàn.","vi":"Tục ngữ nói: chưa đến Trường Thành chưa phải hảo hán.","en":"As the saying goes, you're not a true man until you've climbed the Great Wall."},{"use":"长城 + 的 + danh từ","ex":"长城的历史有两千多年。","py":"Chángchéng de lìshǐ yǒu liǎng qiān duō nián.","vi":"Trường Thành có lịch sử hơn hai nghìn năm.","en":"The Great Wall has a history of over two thousand years."}]},"广播":{"en":"broadcast; radio; to broadcast","exs":[{"use":"danh từ: chương trình phát thanh, đài","ex":"我每天早上听广播学英语。","py":"Wǒ měitiān zǎoshang tīng guǎngbō xué Yīngyǔ.","vi":"Mỗi sáng tôi nghe đài để học tiếng Anh.","en":"Every morning I listen to the radio to learn English."},{"use":"danh từ: thông báo qua loa","ex":"机场的广播说飞机会晚点。","py":"Jīchǎng de guǎngbō shuō fēijī huì wǎndiǎn.","vi":"Loa phát thanh ở sân bay nói máy bay sẽ bị trễ.","en":"The airport announcement said the flight would be delayed."},{"use":"động từ: 广播 + nội dung","ex":"学校正在广播一个重要通知。","py":"Xuéxiào zhèngzài guǎngbō yí ge zhòngyào tōngzhī.","vi":"Nhà trường đang phát thanh một thông báo quan trọng.","en":"The school is broadcasting an important notice."}]},"不行":{"en":"not allowed; not OK; won't do; (complement) extremely","exs":[{"use":"làm vị ngữ độc lập: không được (từ chối)","ex":"你一个人去不行,太危险了。","py":"Nǐ yí ge rén qù bùxíng, tài wēixiǎn le.","vi":"Bạn đi một mình không được, nguy hiểm lắm.","en":"You can't go alone; it's too dangerous."},{"use":"……不行: chỉ năng lực kém","ex":"我的英语不行,听不懂他说什么。","py":"Wǒ de Yīngyǔ bùxíng, tīng bu dǒng tā shuō shénme.","vi":"Tiếng Anh của tôi kém, không hiểu anh ấy nói gì.","en":"My English isn't good enough; I can't understand what he says."},{"use":"……得不行: bổ ngữ mức độ, 'cực kỳ'","ex":"今天累得不行,我想早点儿睡。","py":"Jīntiān lèi de bùxíng, wǒ xiǎng zǎodiǎnr shuì.","vi":"Hôm nay mệt chịu không nổi, tôi muốn đi ngủ sớm.","en":"I'm exhausted today; I want to go to bed early."}]},"没关系":{"en":"it doesn't matter; never mind; it's all right","exs":[{"use":"đáp lại lời xin lỗi: không sao","ex":"A:对不起,我来晚了。B:没关系。","py":"A: Duìbuqǐ, wǒ lái wǎn le. B: Méiguānxi.","vi":"A: Xin lỗi, tôi đến muộn. B: Không sao.","en":"A: Sorry I'm late. B: It's okay."},{"use":"没关系,+ câu: trấn an người khác","ex":"没关系,你慢慢说,我听着。","py":"Méiguānxi, nǐ mànman shuō, wǒ tīngzhe.","vi":"Không sao, bạn cứ từ từ nói, tôi nghe đây.","en":"It's alright, take your time; I'm listening."},{"use":"A 和 B 没关系: không liên quan (nghĩa đen)","ex":"这件事跟你没关系,你别担心。","py":"Zhè jiàn shì gēn nǐ méiguānxi, nǐ bié dānxīn.","vi":"Việc này không liên quan đến bạn, bạn đừng lo.","en":"This has nothing to do with you; don't worry."}]},"黑狗":{"en":"black dog","exs":[{"use":"黑 + 狗: danh từ chỉ con chó đen","ex":"我家有一只黑狗。","py":"Wǒ jiā yǒu yì zhī hēigǒu.","vi":"Nhà tôi có một con chó đen.","en":"My family has a black dog."},{"use":"动作 + 黑狗","ex":"那只黑狗一看见我就跑过来了。","py":"Nà zhī hēigǒu yí kànjiàn wǒ jiù pǎo guòlái le.","vi":"Con chó đen đó vừa thấy tôi liền chạy tới.","en":"The black dog ran over as soon as it saw me."},{"use":"黑狗 + 的 + danh từ","ex":"黑狗的眼睛又大又亮。","py":"Hēigǒu de yǎnjing yòu dà yòu liàng.","vi":"Mắt của con chó đen vừa to vừa sáng.","en":"The black dog's eyes are big and bright."}]},"教给":{"en":"to teach (something to someone)","exs":[{"use":"教给 + người + nội dung","ex":"妈妈教给我很多做人的道理。","py":"Māma jiāogěi wǒ hěn duō zuòrén de dàolǐ.","vi":"Mẹ đã dạy cho tôi rất nhiều đạo lý làm người.","en":"Mom taught me many principles of how to live."},{"use":"把 + nội dung + 教给 + người","ex":"他把自己的经验教给了新同事。","py":"Tā bǎ zìjǐ de jīngyàn jiāogěi le xīn tóngshì.","vi":"Anh ấy truyền lại kinh nghiệm của mình cho đồng nghiệp mới.","en":"He passed on his experience to the new colleagues."},{"use":"教给 + 别人 + 方法","ex":"你能把这个方法教给我吗?","py":"Nǐ néng bǎ zhège fāngfǎ jiāogěi wǒ ma?","vi":"Bạn có thể dạy cho tôi cách này không?","en":"Can you teach me this method?"}]},"严格":{"en":"strict; rigorous; to be strict with","exs":[{"use":"tính từ làm vị ngữ: 对 + người + 很严格","ex":"老师对我们很严格。","py":"Lǎoshī duì wǒmen hěn yángé.","vi":"Thầy cô rất nghiêm khắc với chúng tôi.","en":"The teacher is very strict with us."},{"use":"严格 + động từ: làm trạng ngữ","ex":"公司要求大家严格遵守时间。","py":"Gōngsī yāoqiú dàjiā yángé zūnshǒu shíjiān.","vi":"Công ty yêu cầu mọi người tuân thủ thời gian nghiêm ngặt.","en":"The company requires everyone to strictly observe the time."},{"use":"严格的 + danh từ: quy định, yêu cầu","ex":"这里有严格的规定,不能带宠物。","py":"Zhèlǐ yǒu yángé de guīdìng, bù néng dài chǒngwù.","vi":"Ở đây có quy định nghiêm ngặt, không được mang thú cưng.","en":"There are strict rules here; pets are not allowed."}]},"难受":{"en":"uncomfortable; unwell; sad; upset","exs":[{"use":"nghĩa 1: khó chịu trong người","ex":"我头疼,胃也难受。","py":"Wǒ tóuténg, wèi yě nánshòu.","vi":"Tôi đau đầu, dạ dày cũng khó chịu.","en":"I have a headache and my stomach feels awful."},{"use":"nghĩa 2: buồn, khó chịu trong lòng","ex":"听到这个消息,她心里很难受。","py":"Tīngdào zhège xiāoxi, tā xīnli hěn nánshòu.","vi":"Nghe tin này, trong lòng cô ấy rất buồn.","en":"Hearing this news, she felt very upset."},{"use":"……得难受: bổ ngữ mức độ","ex":"天气热得让人难受。","py":"Tiānqì rè de ràng rén nánshòu.","vi":"Trời nóng đến mức khiến người ta khó chịu.","en":"The weather is so hot it's unbearable."}]},"北京动物园":{"en":"Beijing Zoo","exs":[{"use":"địa danh: Vườn thú Bắc Kinh","ex":"北京动物园里有很多熊猫。","py":"Běijīng Dòngwùyuán lǐ yǒu hěn duō xióngmāo.","vi":"Trong Vườn thú Bắc Kinh có rất nhiều gấu trúc.","en":"There are many pandas in Beijing Zoo."},{"use":"去 + 北京动物园","ex":"周末我带孩子去北京动物园玩儿。","py":"Zhōumò wǒ dài háizi qù Běijīng Dòngwùyuán wánr.","vi":"Cuối tuần tôi đưa con đi chơi ở Vườn thú Bắc Kinh.","en":"On the weekend I'll take my child to Beijing Zoo."},{"use":"北京动物园 + 的 + danh từ","ex":"北京动物园的门票不贵。","py":"Běijīng Dòngwùyuán de ménpiào bú guì.","vi":"Vé vào Vườn thú Bắc Kinh không đắt.","en":"Tickets to Beijing Zoo are not expensive."}]},"亚洲":{"en":"Asia","exs":[{"use":"danh từ riêng: châu Á","ex":"中国在亚洲的东部。","py":"Zhōngguó zài Yàzhōu de dōngbù.","vi":"Trung Quốc nằm ở phía đông châu Á.","en":"China is in eastern Asia."},{"use":"亚洲 + 国家","ex":"亚洲有很多不同的国家和文化。","py":"Yàzhōu yǒu hěn duō bù tóng de guójiā hé wénhuà.","vi":"Châu Á có nhiều quốc gia và nền văn hóa khác nhau.","en":"Asia has many different countries and cultures."},{"use":"亚洲 + 的 + danh từ","ex":"这是亚洲最大的城市之一。","py":"Zhè shì Yàzhōu zuì dà de chéngshì zhī yī.","vi":"Đây là một trong những thành phố lớn nhất châu Á.","en":"This is one of the largest cities in Asia."}]},"动物园":{"en":"zoo","exs":[{"use":"danh từ: vườn thú","ex":"我们明天去动物园看大熊猫。","py":"Wǒmen míngtiān qù dòngwùyuán kàn dà xióngmāo.","vi":"Ngày mai chúng tôi đi vườn thú xem gấu trúc lớn.","en":"Tomorrow we're going to the zoo to see giant pandas."},{"use":"动物园 + 里 (trong vườn thú)","ex":"动物园里有老虎、猴子和大象。","py":"Dòngwùyuán lǐ yǒu lǎohǔ, hóuzi hé dàxiàng.","vi":"Trong vườn thú có hổ, khỉ và voi.","en":"The zoo has tigers, monkeys and elephants."},{"use":"逛/参观 + 动物园","ex":"小时候,爸爸常常带我逛动物园。","py":"Xiǎo shíhou, bàba chángcháng dài wǒ guàng dòngwùyuán.","vi":"Hồi nhỏ, bố thường dẫn tôi đi dạo vườn thú.","en":"When I was little, my dad often took me to the zoo."}]},"放暑假":{"en":"to start the summer vacation; to be on summer break","exs":[{"use":"cụm động từ (động từ + tân ngữ ly hợp): nghỉ hè","ex":"学校下个星期就放暑假了。","py":"Xuéxiào xià ge xīngqī jiù fàng shǔjià le.","vi":"Tuần sau trường sẽ nghỉ hè.","en":"School will be out for summer next week."},{"use":"放了暑假 / 放暑假以后","ex":"放暑假以后,我打算回老家看奶奶。","py":"Fàng shǔjià yǐhòu, wǒ dǎsuàn huí lǎojiā kàn nǎinai.","vi":"Sau khi nghỉ hè, tôi định về quê thăm bà.","en":"After summer vacation starts, I plan to go home to see my grandma."},{"use":"什么时候放暑假: câu hỏi","ex":"你们什么时候放暑假?","py":"Nǐmen shénme shíhou fàng shǔjià?","vi":"Khi nào các bạn nghỉ hè?","en":"When does your summer break start?"}]},"熊猫":{"en":"panda","exs":[{"use":"danh từ: gấu trúc","ex":"熊猫喜欢吃竹子。","py":"Xióngmāo xǐhuan chī zhúzi.","vi":"Gấu trúc thích ăn tre.","en":"Pandas like to eat bamboo."},{"use":"只 + 熊猫: lượng từ 只","ex":"那只熊猫正在睡觉。","py":"Nà zhī xióngmāo zhèngzài shuìjiào.","vi":"Con gấu trúc kia đang ngủ.","en":"That panda is sleeping."},{"use":"熊猫 + 的 + danh từ","ex":"熊猫的样子又可爱又好玩儿。","py":"Xióngmāo de yàngzi yòu kě'ài yòu hǎowánr.","vi":"Dáng vẻ của gấu trúc vừa đáng yêu vừa ngộ nghĩnh.","en":"Pandas look both cute and funny."}]},"老虎":{"en":"tiger","exs":[{"use":"danh từ: con hổ","ex":"老虎是一种很危险的动物。","py":"Lǎohǔ shì yì zhǒng hěn wēixiǎn de dòngwù.","vi":"Hổ là một loài động vật rất nguy hiểm.","en":"The tiger is a very dangerous animal."},{"use":"只 + 老虎: lượng từ 只","ex":"动物园里有三只老虎。","py":"Dòngwùyuán lǐ yǒu sān zhī lǎohǔ.","vi":"Trong vườn thú có ba con hổ.","en":"There are three tigers in the zoo."},{"use":"nghĩa bóng: 纸老虎 (hổ giấy)","ex":"他看起来很凶,其实只是个纸老虎。","py":"Tā kàn qǐlái hěn xiōng, qíshí zhǐshì ge zhǐ lǎohǔ.","vi":"Trông anh ta rất dữ, thật ra chỉ là hổ giấy.","en":"He looks fierce, but he's actually just a paper tiger."}]},"儿童节":{"en":"Children's Day","exs":[{"use":"danh từ: ngày Quốc tế Thiếu nhi (1/6)","ex":"六月一号是儿童节。","py":"Liùyuè yī hào shì Értóngjié.","vi":"Ngày mùng một tháng sáu là Ngày Thiếu nhi.","en":"June 1st is Children's Day."},{"use":"儿童节 + 快乐: lời chúc","ex":"祝你儿童节快乐!","py":"Zhù nǐ Értóngjié kuàilè!","vi":"Chúc bạn Ngày Thiếu nhi vui vẻ!","en":"Happy Children's Day to you!"},{"use":"过儿童节 / 儿童节 + 礼物","ex":"儿童节那天,妈妈给我买了一份礼物。","py":"Értóngjié nà tiān, māma gěi wǒ mǎi le yí fèn lǐwù.","vi":"Vào ngày Thiếu nhi, mẹ đã mua cho tôi một món quà.","en":"On Children's Day, Mom bought me a gift."}]},"入口处":{"en":"entrance; entry point","exs":[{"use":"danh từ chỉ nơi chốn: chỗ cổng vào","ex":"我们在公园入口处见面吧。","py":"Wǒmen zài gōngyuán rùkǒuchù jiànmiàn ba.","vi":"Chúng ta gặp nhau ở cổng vào công viên nhé.","en":"Let's meet at the park entrance."},{"use":"入口处 + có/ở: chỉ vị trí","ex":"入口处有很多人在排队买票。","py":"Rùkǒuchù yǒu hěn duō rén zài páiduì mǎi piào.","vi":"Ở cổng vào có rất nhiều người đang xếp hàng mua vé.","en":"Many people are queuing to buy tickets at the entrance."},{"use":"在……入口处 + động từ","ex":"请在入口处出示您的票。","py":"Qǐng zài rùkǒuchù chūshì nín de piào.","vi":"Xin vui lòng xuất trình vé tại cổng vào.","en":"Please show your ticket at the entrance."}]},"排队":{"en":"to queue up; to line up","exs":[{"use":"động từ ly hợp: 排队 + động từ","ex":"买票的人要排队。","py":"Mǎi piào de rén yào páiduì.","vi":"Người mua vé phải xếp hàng.","en":"People buying tickets have to line up."},{"use":"排队 + 等/买: liên động","ex":"很多人在门口排队等着进去。","py":"Hěn duō rén zài ménkǒu páiduì děngzhe jìnqù.","vi":"Rất nhiều người đang xếp hàng ở cửa chờ vào.","en":"Many people are queuing at the door waiting to go in."},{"use":"排队 + khoảng thời gian (排队排了……)","ex":"我排队排了一个小时才买到。","py":"Wǒ pái le yí ge xiǎoshí de duì cái mǎi dào.","vi":"Tôi xếp hàng một tiếng mới mua được.","en":"I waited in line for an hour before I could buy it."}]},"极了":{"en":"extremely; very","exs":[{"use":"tính từ + 极了: mức độ cao nhất (đặt sau tính từ)","ex":"这里的风景美极了。","py":"Zhèlǐ de fēngjǐng měi jí le.","vi":"Phong cảnh ở đây đẹp vô cùng.","en":"The scenery here is extremely beautiful."},{"use":"cảm xúc + 极了","ex":"听到这个好消息,我高兴极了。","py":"Tīngdào zhège hǎo xiāoxi, wǒ gāoxìng jí le.","vi":"Nghe tin vui này, tôi vui cực kỳ.","en":"I was extremely happy to hear this good news."},{"use":"cảm giác thể chất + 极了","ex":"走了一天的路,我累极了。","py":"Zǒu le yì tiān de lù, wǒ lèi jí le.","vi":"Đi bộ cả ngày, tôi mệt cực kỳ.","en":"After walking all day, I'm extremely tired."}]},"活泼":{"en":"lively; vivacious; active","exs":[{"use":"tính từ làm vị ngữ: miêu tả tính cách","ex":"她是一个活泼可爱的女孩。","py":"Tā shì yí ge huópo kě'ài de nǚhái.","vi":"Cô ấy là một cô gái hoạt bát đáng yêu.","en":"She is a lively and lovable girl."},{"use":"很/非常 + 活泼","ex":"小狗很活泼,总是跑来跑去。","py":"Xiǎo gǒu hěn huópo, zǒngshì pǎo lái pǎo qù.","vi":"Chú chó con rất hiếu động, cứ chạy qua chạy lại.","en":"The puppy is very lively and is always running around."},{"use":"活泼 miêu tả văn phong/không khí","ex":"这个节目的内容很活泼,孩子们都爱看。","py":"Zhège jiémù de nèiróng hěn huópo, háizimen dōu ài kàn.","vi":"Nội dung chương trình này rất sinh động, bọn trẻ đều thích xem.","en":"This show's content is lively; all the children love watching it."}]},"大熊猫":{"en":"giant panda","exs":[{"use":"danh từ: gấu trúc lớn (tên khoa học)","ex":"大熊猫是中国的国宝。","py":"Dà xióngmāo shì Zhōngguó de guóbǎo.","vi":"Gấu trúc lớn là quốc bảo của Trung Quốc.","en":"The giant panda is a national treasure of China."},{"use":"看大熊猫","ex":"很多游客来成都看大熊猫。","py":"Hěn duō yóukè lái Chéngdū kàn dà xióngmāo.","vi":"Rất nhiều du khách đến Thành Đô để xem gấu trúc lớn.","en":"Many tourists come to Chengdu to see giant pandas."},{"use":"大熊猫 + 的 + danh từ","ex":"大熊猫的主要食物是竹子。","py":"Dà xióngmāo de zhǔyào shíwù shì zhúzi.","vi":"Thức ăn chính của gấu trúc lớn là tre.","en":"The main food of giant pandas is bamboo."}]},"身子":{"en":"body; torso; health","exs":[{"use":"danh từ: thân mình, cơ thể","ex":"小猫把身子缩成一团睡着了。","py":"Xiǎo māo bǎ shēnzi suō chéng yì tuán shuìzháo le.","vi":"Con mèo con co người lại thành một cục rồi ngủ.","en":"The kitten curled up its body and fell asleep."},{"use":"身子 + 不舒服: chỉ sức khỏe","ex":"奶奶这几天身子不太舒服。","py":"Nǎinai zhè jǐ tiān shēnzi bú tài shūfu.","vi":"Mấy hôm nay bà không được khỏe lắm.","en":"Grandma hasn't been feeling very well these days."},{"use":"动作 + 身子: 转/弯/坐直","ex":"他弯下身子,把地上的书捡了起来。","py":"Tā wān xià shēnzi, bǎ dìshang de shū jiǎn le qǐlái.","vi":"Anh ấy cúi người xuống, nhặt quyển sách dưới đất lên.","en":"He bent down and picked up the book from the floor."}]},"全世界":{"en":"the whole world","exs":[{"use":"danh từ: toàn thế giới","ex":"全世界的人都喜欢大熊猫。","py":"Quán shìjiè de rén dōu xǐhuan dà xióngmāo.","vi":"Mọi người trên toàn thế giới đều thích gấu trúc lớn.","en":"People all over the world like giant pandas."},{"use":"在全世界 + động từ","ex":"汉语在全世界越来越受欢迎。","py":"Hànyǔ zài quán shìjiè yuèláiyuè shòu huānyíng.","vi":"Tiếng Hán ngày càng được ưa chuộng trên toàn thế giới.","en":"Chinese is becoming more and more popular around the world."},{"use":"走遍全世界 / 全世界都……","ex":"我的梦想是走遍全世界。","py":"Wǒ de mèngxiǎng shì zǒubiàn quán shìjiè.","vi":"Ước mơ của tôi là đi khắp thế giới.","en":"My dream is to travel all over the world."}]},"作为":{"en":"as; in the capacity of; to regard as; to act as","exs":[{"use":"作为 + danh từ + ,……: với tư cách là","ex":"作为学生,我们应该认真学习。","py":"Zuòwéi xuésheng, wǒmen yīnggāi rènzhēn xuéxí.","vi":"Là học sinh, chúng ta nên chăm chỉ học tập.","en":"As students, we should study hard."},{"use":"作为 + danh từ + 的 + ……: làm định ngữ","ex":"作为朋友,我想给你一个建议。","py":"Zuòwéi péngyou, wǒ xiǎng gěi nǐ yí ge jiànyì.","vi":"Với tư cách bạn bè, tôi muốn cho bạn một lời khuyên.","en":"As a friend, I'd like to give you a piece of advice."},{"use":"把……作为……: coi … là …","ex":"他把这次旅行作为送给妈妈的礼物。","py":"Tā bǎ zhè cì lǚxíng zuòwéi sòng gěi māma de lǐwù.","vi":"Anh ấy coi chuyến du lịch này là món quà tặng mẹ.","en":"He regards this trip as a gift for his mother."}]},"本国":{"en":"one's own country; this country; native country","exs":[{"use":"danh từ: nước mình, quốc gia của mình","ex":"他在本国是一名有名的医生。","py":"Tā zài běnguó shì yì míng yǒumíng de yīshēng.","vi":"Ở nước mình, anh ấy là một bác sĩ nổi tiếng.","en":"In his own country, he is a well-known doctor."},{"use":"本国 + 人/货/文化","ex":"这些本国产品比进口的便宜。","py":"Zhèxiē běnguó chǎnpǐn bǐ jìnkǒu de piányi.","vi":"Những sản phẩm trong nước này rẻ hơn hàng nhập khẩu.","en":"These domestic products are cheaper than imported ones."},{"use":"本国 vs 外国: đối lập","ex":"留学生要先了解本国和外国的不同。","py":"Liúxuéshēng yào xiān liǎojiě běnguó hé wàiguó de bù tóng.","vi":"Du học sinh nên tìm hiểu trước sự khác nhau giữa nước mình và nước ngoài.","en":"International students should first understand the differences between their own country and foreign countries."}]},"发短信":{"en":"to send a text message","exs":[{"use":"cụm động từ: 发短信 (给 + người)","ex":"我给朋友发短信,告诉他我晚点到。","py":"Wǒ gěi péngyou fā duǎnxìn, gàosu tā wǒ wǎndiǎn dào.","vi":"Tôi nhắn tin cho bạn, báo là tôi sẽ đến muộn.","en":"I texted my friend to tell him I'd be late."},{"use":"发短信 + nội dung (nói rằng…)","ex":"他刚才给我发短信,说他马上到。","py":"Tā gāngcái gěi wǒ fā duǎnxìn, shuō tā mǎshàng dào.","vi":"Vừa nãy anh ấy nhắn tin cho tôi, nói sắp đến rồi.","en":"He just texted me to say he'd be there soon."},{"use":"用手机发短信","ex":"开车的时候不要发短信。","py":"Kāichē de shíhou bú yào fā duǎnxìn.","vi":"Khi lái xe đừng nhắn tin.","en":"Don't send text messages while driving."}]},"付款":{"en":"to pay; payment","exs":[{"use":"động từ ly hợp: 付款 (thanh toán)","ex":"你可以用手机付款。","py":"Nǐ kěyǐ yòng shǒujī fùkuǎn.","vi":"Bạn có thể thanh toán bằng điện thoại.","en":"You can pay with your phone."},{"use":"先……后付款","ex":"买东西以后,请到前面付款。","py":"Mǎi dōngxi yǐhòu, qǐng dào qiánmiàn fùkuǎn.","vi":"Mua đồ xong, xin hãy ra phía trước thanh toán.","en":"After shopping, please pay at the front."},{"use":"danh từ: 付款方式 (phương thức thanh toán)","ex":"这家店有几种付款方式?","py":"Zhè jiā diàn yǒu jǐ zhǒng fùkuǎn fāngshì?","vi":"Cửa hàng này có mấy phương thức thanh toán?","en":"How many payment methods does this store have?"}]},"迷路":{"en":"to get lost; to lose one's way","exs":[{"use":"động từ ly hợp: 迷路 (lạc đường)","ex":"第一次来这儿,我迷路了。","py":"Dì yī cì lái zhèr, wǒ mílù le.","vi":"Lần đầu đến đây, tôi bị lạc đường.","en":"It was my first time here and I got lost."},{"use":"动作 + 迷路了, sau đó…","ex":"他在大城市里迷路了,后来学会了用地图。","py":"Tā zài dà chéngshì lǐ mílù le, hòulái xuéhuì le yòng dìtú.","vi":"Anh ấy bị lạc đường ở thành phố lớn, sau đó học cách dùng bản đồ.","en":"He got lost in the big city and later learned to use a map."},{"use":"用……不会迷路","ex":"有了手机地图,你就不会迷路了。","py":"Yǒu le shǒujī dìtú, nǐ jiù bú huì mílù le.","vi":"Có bản đồ trên điện thoại thì bạn sẽ không bị lạc đường.","en":"With a map on your phone, you won't get lost."}]},"地址":{"en":"address","exs":[{"use":"danh từ: địa chỉ","ex":"请把你的地址写在这儿。","py":"Qǐng bǎ nǐ de dìzhǐ xiě zài zhèr.","vi":"Xin hãy viết địa chỉ của bạn vào đây.","en":"Please write your address here."},{"use":"问/告诉 + 地址","ex":"你能告诉我饭店的地址吗?","py":"Nǐ néng gàosu wǒ fàndiàn de dìzhǐ ma?","vi":"Bạn có thể cho tôi biết địa chỉ nhà hàng không?","en":"Can you tell me the restaurant's address?"},{"use":"地址 + 写错/不对","ex":"地址写错了,包裹没送到。","py":"Dìzhǐ xiě cuò le, bāoguǒ méi sòng dào.","vi":"Địa chỉ ghi sai nên bưu kiện không được giao đến.","en":"The address was written wrong, so the package didn't arrive."}]},"地点":{"en":"place; location; venue","exs":[{"use":"danh từ: địa điểm (cuộc họp, hoạt động)","ex":"会议的时间和地点都定好了。","py":"Huìyì de shíjiān hé dìdiǎn dōu dìng hǎo le.","vi":"Thời gian và địa điểm cuộc họp đều đã chốt xong.","en":"The time and place of the meeting have both been set."},{"use":"时间 + 地点: cặp từ thường đi với nhau","ex":"请告诉我见面的时间和地点。","py":"Qǐng gàosu wǒ jiànmiàn de shíjiān hé dìdiǎn.","vi":"Xin cho tôi biết thời gian và địa điểm gặp mặt.","en":"Please tell me the time and place for the meeting."},{"use":"选择/改变 + 地点","ex":"因为下雨,比赛地点改到了室内。","py":"Yīnwèi xiàyǔ, bǐsài dìdiǎn gǎi dào le shìnèi.","vi":"Vì trời mưa, địa điểm thi đấu được chuyển vào trong nhà.","en":"Because of the rain, the match location was moved indoors."}]},"世纪":{"en":"century","exs":[{"use":"danh từ: thế kỷ (số + 世纪)","ex":"现在是二十一世纪。","py":"Xiànzài shì èrshíyī shìjì.","vi":"Bây giờ là thế kỷ hai mươi mốt.","en":"We are now in the 21st century."},{"use":"上个/本 + 世纪","ex":"这座桥是上个世纪建的。","py":"Zhè zuò qiáo shì shàng ge shìjì jiàn de.","vi":"Cây cầu này được xây vào thế kỷ trước.","en":"This bridge was built in the last century."},{"use":"世纪 + 的 + danh từ: 世纪大战/大事","ex":"这是一个世纪以来最大的一场雨。","py":"Zhè shì yí ge shìjì yǐlái zuì dà de yì cháng yǔ.","vi":"Đây là trận mưa lớn nhất trong một thế kỷ qua.","en":"This is the heaviest rain in a century."}]},"巨大":{"en":"huge; enormous; tremendous","exs":[{"use":"巨大的 + danh từ: làm định ngữ","ex":"这个城市发生了巨大的变化。","py":"Zhège chéngshì fāshēng le jùdà de biànhuà.","vi":"Thành phố này đã có sự thay đổi to lớn.","en":"This city has undergone enormous changes."},{"use":"巨大 chỉ kích thước vật","ex":"海边有一块巨大的石头。","py":"Hǎibiān yǒu yí kuài jùdà de shítou.","vi":"Bên bờ biển có một tảng đá khổng lồ.","en":"There is a huge rock by the sea."},{"use":"巨大 + 的 + 压力/帮助 (trừu tượng)","ex":"工作给他带来了巨大的压力。","py":"Gōngzuò gěi tā dàilái le jùdà de yālì.","vi":"Công việc mang lại cho anh ấy áp lực rất lớn.","en":"Work has brought him tremendous pressure."}]},"寄信":{"en":"to mail a letter","exs":[{"use":"động từ ly hợp: 寄信 (gửi thư)","ex":"我想去邮局寄信。","py":"Wǒ xiǎng qù yóujú jì xìn.","vi":"Tôi muốn ra bưu điện gửi thư.","en":"I want to go to the post office to mail a letter."},{"use":"给 + người + 寄信","ex":"他每个月都给家里寄信。","py":"Tā měi ge yuè dōu gěi jiālǐ jì xìn.","vi":"Mỗi tháng anh ấy đều gửi thư về nhà.","en":"He sends a letter home every month."},{"use":"给 + người + 寄信 (kết hợp với 去邮局)","ex":"昨天我去邮局给老师寄信。","py":"Zuótiān wǒ qù yóujú gěi lǎoshī jì xìn.","vi":"Hôm qua tôi ra bưu điện gửi thư cho thầy giáo.","en":"Yesterday I went to the post office to mail a letter to my teacher."}]},"邮局":{"en":"post office","exs":[{"use":"danh từ: bưu điện","ex":"邮局在银行的旁边。","py":"Yóujú zài yínháng de pángbiān.","vi":"Bưu điện ở bên cạnh ngân hàng.","en":"The post office is next to the bank."},{"use":"去邮局 + động từ","ex":"我要去邮局寄一个包裹。","py":"Wǒ yào qù yóujú jì yí ge bāoguǒ.","vi":"Tôi phải ra bưu điện gửi một bưu kiện.","en":"I need to go to the post office to send a package."},{"use":"邮局 + 几点开门/关门","ex":"这个邮局星期天也开门吗?","py":"Zhège yóujú xīngqītiān yě kāimén ma?","vi":"Bưu điện này Chủ nhật có mở cửa không?","en":"Is this post office open on Sundays too?"}]},"电子邮件":{"en":"email","exs":[{"use":"danh từ: email (thư điện tử)","ex":"请把资料用电子邮件发给我。","py":"Qǐng bǎ zīliào yòng diànzǐ yóujiàn fā gěi wǒ.","vi":"Xin hãy gửi tài liệu cho tôi qua email.","en":"Please send me the materials by email."},{"use":"发/收 + 电子邮件","ex":"我今天早上收到了一封电子邮件。","py":"Wǒ jīntiān zǎoshang shōudào le yì fēng diànzǐ yóujiàn.","vi":"Sáng nay tôi nhận được một email.","en":"I received an email this morning."},{"use":"电子邮件 + 地址","ex":"你的电子邮件地址是多少?","py":"Nǐ de diànzǐ yóujiàn dìzhǐ shì duōshao?","vi":"Địa chỉ email của bạn là gì?","en":"What is your email address?"}]},"信封":{"en":"envelope","exs":[{"use":"danh từ: phong bì, lượng từ 个","ex":"请给我一个信封。","py":"Qǐng gěi wǒ yí ge xìnfēng.","vi":"Xin cho tôi một cái phong bì.","en":"Please give me an envelope."},{"use":"把信放进信封里","ex":"他把信放进信封里,然后贴上了邮票。","py":"Tā bǎ xìn fàng jìn xìnfēng lǐ, ránhòu tiē shàng le yóupiào.","vi":"Anh ấy bỏ thư vào phong bì rồi dán tem lên.","en":"He put the letter in the envelope and then stuck on a stamp."},{"use":"信封 + 上写……","ex":"信封上要写清楚地址和名字。","py":"Xìnfēng shang yào xiě qīngchu dìzhǐ hé míngzi.","vi":"Trên phong bì phải ghi rõ địa chỉ và tên.","en":"The address and name must be written clearly on the envelope."}]},"网站":{"en":"website","exs":[{"use":"danh từ: trang web","ex":"这个网站上有很多学习资料。","py":"Zhège wǎngzhàn shang yǒu hěn duō xuéxí zīliào.","vi":"Trên trang web này có rất nhiều tài liệu học tập.","en":"This website has a lot of study materials."},{"use":"上网站 / 登录网站","ex":"你可以先登录公司的网站看看。","py":"Nǐ kěyǐ xiān dēnglù gōngsī de wǎngzhàn kànkan.","vi":"Bạn có thể đăng nhập vào trang web của công ty xem trước.","en":"You can first log in to the company's website and take a look."},{"use":"网站 + 的 + danh từ","ex":"这个网站的速度太慢了。","py":"Zhège wǎngzhàn de sùdù tài màn le.","vi":"Tốc độ của trang web này chậm quá.","en":"This website is too slow."}]},"信息":{"en":"information; message; data","exs":[{"use":"làm danh từ, chỉ thông tin, tư liệu","ex":"我在网上查到了很多有用的信息。","py":"Wǒ zài wǎngshàng chádào le hěn duō yǒuyòng de xìnxī.","vi":"Tôi tra được rất nhiều thông tin hữu ích trên mạng.","en":"I found a lot of useful information online."},{"use":"nghĩa 2: tin nhắn (发信息 = gửi tin nhắn)","ex":"他还没有回复我发的信息。","py":"Tā hái méiyǒu huífù wǒ fā de xìnxī.","vi":"Anh ấy vẫn chưa trả lời tin nhắn tôi gửi.","en":"He still hasn't replied to the message I sent."},{"use":"cụm 信息时代 (thời đại thông tin)","ex":"现在是信息时代，我们每天都会接触到大量信息。","py":"Xiànzài shì xìnxī shídài, wǒmen měitiān dōu huì jiēchù dào dàliàng xìnxī.","vi":"Bây giờ là thời đại thông tin, mỗi ngày chúng ta đều tiếp xúc với lượng lớn thông tin.","en":"We live in the information age, and come into contact with huge amounts of information every day."}]},"科学技术":{"en":"science and technology","exs":[{"use":"làm chủ ngữ, nói về sự phát triển","ex":"科学技术的发展让我们的生活越来越方便。","py":"Kēxué jìshù de fāzhǎn ràng wǒmen de shēnghuó yuè lái yuè fāngbiàn.","vi":"Sự phát triển của khoa học kỹ thuật khiến cuộc sống của chúng ta ngày càng thuận tiện.","en":"The development of science and technology makes our lives more and more convenient."},{"use":"làm tân ngữ của 重视 (coi trọng)","ex":"国家非常重视科学技术教育。","py":"Guójiā fēicháng zhòngshì kēxué jìshù jiàoyù.","vi":"Nhà nước rất coi trọng giáo dục khoa học kỹ thuật.","en":"The country attaches great importance to science and technology education."},{"use":"làm định ngữ chỉ lĩnh vực nghiên cứu, làm việc","ex":"他在一家研究科学技术的公司工作。","py":"Tā zài yì jiā yánjiū kēxué jìshù de gōngsī gōngzuò.","vi":"Anh ấy làm việc ở một công ty nghiên cứu khoa học kỹ thuật.","en":"He works for a company that does science and technology research."}]},"地球村":{"en":"global village","exs":[{"use":"danh từ, chỉ thế giới gắn kết nhờ công nghệ","ex":"互联网把世界变成了一个地球村。","py":"Hùliánwǎng bǎ shìjiè biànchéng le yí ge dìqiúcūn.","vi":"Internet đã biến thế giới thành một ngôi làng toàn cầu.","en":"The Internet has turned the world into a global village."},{"use":"đi với 在……里 (trong làng toàn cầu)","ex":"在地球村里，各国人民的联系越来越紧密。","py":"Zài dìqiúcūn lǐ, gèguó rénmín de liánxì yuè lái yuè jǐnmì.","vi":"Trong ngôi làng toàn cầu, mối liên hệ giữa người dân các nước ngày càng chặt chẽ.","en":"In the global village, ties between people of different countries grow ever closer."},{"use":"dùng với 说 để nêu quan điểm","ex":"有人说，现代交通让世界变成了小小的地球村。","py":"Yǒu rén shuō, xiàndài jiāotōng ràng shìjiè biànchéng le xiǎoxiǎo de dìqiúcūn.","vi":"Có người nói giao thông hiện đại đã biến thế giới thành một ngôi làng nhỏ bé.","en":"Some say modern transportation has made the world a tiny global village."}]},"除此以外":{"en":"besides this; in addition","exs":[{"use":"liên từ: 除此以外，还/也…… (ngoài ra còn)","ex":"这家店卖水果，除此以外，还卖蔬菜和肉。","py":"Zhè jiā diàn mài shuǐguǒ, chúcǐ yǐwài, hái mài shūcài hé ròu.","vi":"Cửa hàng này bán trái cây, ngoài ra còn bán rau và thịt.","en":"This shop sells fruit; besides that, it also sells vegetables and meat."},{"use":"nối hai ý bổ sung cho nhau trong học tập","ex":"我每天学习两个小时汉语，除此以外，还会听半个小时中文歌。","py":"Wǒ měitiān xuéxí liǎng ge xiǎoshí Hànyǔ, chúcǐ yǐwài, hái huì tīng bàn ge xiǎoshí Zhōngwén gē.","vi":"Mỗi ngày tôi học tiếng Trung hai tiếng, ngoài ra còn nghe nhạc Trung nửa tiếng.","en":"I study Chinese for two hours every day; besides that, I also listen to Chinese songs for half an hour."},{"use":"đứng đầu vế sau, dùng với 也/还 để thêm thông tin","ex":"他会说英语，除此以外，他也会说日语。","py":"Tā huì shuō Yīngyǔ, chúcǐ yǐwài, tā yě huì shuō Rìyǔ.","vi":"Anh ấy biết nói tiếng Anh, ngoài ra còn biết nói tiếng Nhật.","en":"He can speak English, and besides that he can also speak Japanese."}]},"电影":{"en":"movie; film","exs":[{"use":"danh từ, đi với động từ 看 (xem phim)","ex":"昨天晚上我和朋友去看了一场电影。","py":"Zuótiān wǎnshang wǒ hé péngyou qù kàn le yì chǎng diànyǐng.","vi":"Tối qua tôi cùng bạn đi xem một buổi phim.","en":"Last night I went to see a movie with a friend."},{"use":"dùng với 部 làm lượng từ, kèm tính từ miêu tả","ex":"这部电影太感人了，我看哭了。","py":"Zhè bù diànyǐng tài gǎnrén le, wǒ kàn kū le.","vi":"Bộ phim này cảm động quá, tôi xem mà khóc.","en":"This movie is so touching that I cried watching it."},{"use":"làm định ngữ trong từ ghép 电影演员, 电影院","ex":"你最喜欢哪位电影演员？","py":"Nǐ zuì xǐhuan nǎ wèi diànyǐng yǎnyuán?","vi":"Bạn thích nam diễn viên điện ảnh nào nhất?","en":"Which film actor do you like best?"}]},"游戏":{"en":"game; play","exs":[{"use":"danh từ, chỉ trò chơi của trẻ em","ex":"孩子们在院子里玩游戏。","py":"Háizimen zài yuànzi lǐ wán yóuxì.","vi":"Bọn trẻ đang chơi trò chơi trong sân.","en":"The children are playing games in the yard."},{"use":"cụm 玩游戏, 电脑游戏 (game điện tử)","ex":"他每天晚上都玩电脑游戏。","py":"Tā měitiān wǎnshang dōu wán diànnǎo yóuxì.","vi":"Mỗi tối anh ấy đều chơi game máy tính.","en":"He plays computer games every evening."},{"use":"làm chủ ngữ, kèm 的规则 (luật chơi)","ex":"这个游戏的规则很简单。","py":"Zhège yóuxì de guīzé hěn jiǎndān.","vi":"Luật chơi của trò này rất đơn giản.","en":"The rules of this game are very simple."}]},"例子":{"en":"example; instance","exs":[{"use":"cụm 举例子 (đưa ví dụ)","ex":"你能举一个例子吗？","py":"Nǐ néng jǔ yí ge lìzi ma?","vi":"Bạn có thể đưa một ví dụ không?","en":"Can you give an example?"},{"use":"dùng với 用……解释, chỉ minh họa","ex":"老师用很多例子解释这个语法。","py":"Lǎoshī yòng hěn duō lìzi jiěshì zhège yǔfǎ.","vi":"Thầy giáo dùng nhiều ví dụ để giải thích ngữ pháp này.","en":"The teacher used many examples to explain this grammar point."},{"use":"làm chủ ngữ, kèm tính từ","ex":"这个例子很容易懂。","py":"Zhège lìzi hěn róngyì dǒng.","vi":"Ví dụ này rất dễ hiểu.","en":"This example is easy to understand."}]},"现代人":{"en":"modern people; people today","exs":[{"use":"danh từ, chỉ người thời nay, làm chủ ngữ","ex":"现代人的生活压力很大。","py":"Xiàndàirén de shēnghuó yālì hěn dà.","vi":"Áp lực cuộc sống của người hiện đại rất lớn.","en":"Modern people live under a lot of pressure."},{"use":"đi với 越来越 nói về xu hướng","ex":"现代人越来越注意健康。","py":"Xiàndàirén yuè lái yuè zhùyì jiànkāng.","vi":"Người hiện đại ngày càng chú ý đến sức khỏe.","en":"People today are paying more and more attention to health."},{"use":"đối lập với 古人 (người xưa)","ex":"现代人比古人更喜欢旅游。","py":"Xiàndàirén bǐ gǔrén gèng xǐhuan lǚyóu.","vi":"Người hiện đại thích du lịch hơn người xưa.","en":"Modern people like traveling more than the ancients did."}]},"收到":{"en":"to receive; to get","exs":[{"use":"động từ, nhận được đồ vật (quà, thư…)","ex":"我今天收到了朋友寄来的礼物。","py":"Wǒ jīntiān shōudào le péngyou jì lái de lǐwù.","vi":"Hôm nay tôi nhận được món quà bạn gửi tới.","en":"Today I received a gift my friend sent."},{"use":"dạng nghi vấn 收到……了吗 (nhận được chưa)","ex":"你收到我发的邮件了吗？","py":"Nǐ shōudào wǒ fā de yóujiàn le ma?","vi":"Bạn đã nhận được email tôi gửi chưa?","en":"Did you get the email I sent?"},{"use":"nhận thông báo, tin tức","ex":"他收到了那家公司的面试通知。","py":"Tā shōudào le nà jiā gōngsī de miànshì tōngzhī.","vi":"Anh ấy đã nhận được thông báo phỏng vấn của công ty đó.","en":"He received an interview notice from that company."}]},"叫作":{"en":"to be called; to be known as","exs":[{"use":"cấu trúc A 叫作 B (A được gọi là B)","ex":"这种水果叫作火龙果。","py":"Zhè zhǒng shuǐguǒ jiàozuò huǒlóngguǒ.","vi":"Loại trái cây này gọi là thanh long.","en":"This kind of fruit is called dragon fruit."},{"use":"cấu trúc 把 A 叫作 B (gọi A là B)","ex":"我们把这个节日叫作春节。","py":"Wǒmen bǎ zhège jiérì jiàozuò Chūnjié.","vi":"Chúng tôi gọi ngày lễ này là Tết Xuân.","en":"We call this festival the Spring Festival."},{"use":"dùng để giới thiệu tên gọi của đồ vật","ex":"在中国，这种小吃叫作饺子。","py":"Zài Zhōngguó, zhè zhǒng xiǎochī jiàozuò jiǎozi.","vi":"Ở Trung Quốc, món ăn vặt này gọi là sủi cảo.","en":"In China, this kind of snack is called jiaozi."}]},"起飞":{"en":"to take off","exs":[{"use":"động từ, máy bay cất cánh","ex":"飞机十点准时起飞。","py":"Fēijī shí diǎn zhǔnshí qǐfēi.","vi":"Máy bay cất cánh đúng giờ lúc mười giờ.","en":"The plane takes off on time at ten o'clock."},{"use":"kèm 晚点 (trễ giờ) nói về lý do","ex":"因为天气不好，飞机晚点起飞了。","py":"Yīnwèi tiānqì bù hǎo, fēijī wǎndiǎn qǐfēi le.","vi":"Vì thời tiết xấu nên máy bay cất cánh muộn.","en":"The plane took off late because of bad weather."},{"use":"đi với …的时候 (lúc cất cánh)","ex":"飞机起飞的时候，请系好安全带。","py":"Fēijī qǐfēi de shíhou, qǐng jì hǎo ānquándài.","vi":"Khi máy bay cất cánh, xin hãy thắt chặt dây an toàn.","en":"Please fasten your seat belt when the plane takes off."}]},"降落":{"en":"to land; to descend","exs":[{"use":"động từ, máy bay hạ cánh + 在 + nơi chốn","ex":"飞机已经安全降落在北京机场。","py":"Fēijī yǐjīng ānquán jiàngluò zài Běijīng jīchǎng.","vi":"Máy bay đã hạ cánh an toàn xuống sân bay Bắc Kinh.","en":"The plane has landed safely at Beijing airport."},{"use":"dùng với 马上就要……了 (sắp sửa)","ex":"飞机马上就要降落了，请坐好。","py":"Fēijī mǎshàng jiù yào jiàngluò le, qǐng zuò hǎo.","vi":"Máy bay sắp hạ cánh rồi, xin hãy ngồi yên.","en":"The plane is about to land, please take your seat."},{"use":"dạng phủ định 不能降落, nêu lý do","ex":"天气太差，飞机不能降落。","py":"Tiānqì tài chà, fēijī bù néng jiàngluò.","vi":"Thời tiết quá xấu, máy bay không thể hạ cánh.","en":"The weather is so bad that the plane can't land."}]},"奇特":{"en":"peculiar; strange; unusual","exs":[{"use":"tính từ làm vị ngữ, + 很","ex":"这座山的形状很奇特。","py":"Zhè zuò shān de xíngzhuàng hěn qítè.","vi":"Hình dáng của ngọn núi này rất kỳ lạ.","en":"The shape of this mountain is very unusual."},{"use":"làm định ngữ: 奇特 + 的 + danh từ","ex":"他有一个奇特的爱好，喜欢收集旧钥匙。","py":"Tā yǒu yí ge qítè de àihào, xǐhuan shōují jiù yàoshi.","vi":"Anh ấy có một sở thích kỳ lạ là sưu tầm chìa khóa cũ.","en":"He has an odd hobby: collecting old keys."},{"use":"miêu tả mùi vị, cảm giác lạ","ex":"这家餐厅的菜味道很奇特。","py":"Zhè jiā cāntīng de cài wèidào hěn qítè.","vi":"Món ăn của nhà hàng này có hương vị rất lạ.","en":"The food at this restaurant has a very peculiar taste."}]},"科学知识":{"en":"scientific knowledge","exs":[{"use":"làm tân ngữ của 学到/学习","ex":"多读书可以学到很多科学知识。","py":"Duō dú shū kěyǐ xuédào hěn duō kēxué zhīshi.","vi":"Đọc nhiều sách có thể học được nhiều kiến thức khoa học.","en":"Reading more books lets you learn a lot of scientific knowledge."},{"use":"làm tân ngữ của 介绍 (giới thiệu)","ex":"这本书用简单的话介绍科学知识。","py":"Zhè běn shū yòng jiǎndān de huà jièshào kēxué zhīshi.","vi":"Cuốn sách này giới thiệu kiến thức khoa học bằng lời lẽ đơn giản.","en":"This book introduces scientific knowledge in simple language."},{"use":"đi với 对……感兴趣 (hứng thú với)","ex":"孩子们对科学知识很感兴趣。","py":"Háizimen duì kēxué zhīshi hěn gǎn xìngqù.","vi":"Bọn trẻ rất hứng thú với kiến thức khoa học.","en":"The children are very interested in scientific knowledge."}]},"作者":{"en":"author; writer","exs":[{"use":"danh từ, chỉ người viết sách","ex":"这本书的作者是一位老教授。","py":"Zhè běn shū de zuòzhě shì yí wèi lǎo jiàoshòu.","vi":"Tác giả của cuốn sách này là một vị giáo sư già.","en":"The author of this book is an old professor."},{"use":"câu hỏi 谁 (ai) về tác giả","ex":"你知道这篇文章的作者是谁吗？","py":"Nǐ zhīdào zhè piān wénzhāng de zuòzhě shì shéi ma?","vi":"Bạn có biết tác giả của bài văn này là ai không?","en":"Do you know who wrote this article?"},{"use":"làm chủ ngữ, nói về nội dung bài viết","ex":"作者在文章中讲了自己小时候的故事。","py":"Zuòzhě zài wénzhāng zhōng jiǎng le zìjǐ xiǎoshíhou de gùshi.","vi":"Tác giả kể trong bài viết câu chuyện hồi nhỏ của mình.","en":"In the article, the author tells stories from his own childhood."}]},"记住":{"en":"to remember; to bear in mind","exs":[{"use":"V + 住: ghi nhớ chắc, + tân ngữ","ex":"请记住我的电话号码。","py":"Qǐng jìzhù wǒ de diànhuà hàomǎ.","vi":"Xin hãy nhớ kỹ số điện thoại của tôi.","en":"Please remember my phone number."},{"use":"dùng với 了, chỉ kết quả đã nhớ được","ex":"我很快就记住了他的名字。","py":"Wǒ hěn kuài jiù jìzhù le tā de míngzi.","vi":"Tôi nhanh chóng nhớ được tên của anh ấy.","en":"I soon remembered his name."},{"use":"dùng với 要/你要, nhắc nhở, dặn dò","ex":"你要记住，安全第一。","py":"Nǐ yào jìzhù, ānquán dì-yī.","vi":"Bạn phải nhớ rằng an toàn là trên hết.","en":"You must remember: safety first."}]},"更新":{"en":"to update; to renew; to replace","exs":[{"use":"động từ, cập nhật phần mềm","ex":"手机需要定期更新系统。","py":"Shǒujī xūyào dìngqī gēngxīn xìtǒng.","vi":"Điện thoại cần cập nhật hệ thống định kỳ.","en":"Phones need regular system updates."},{"use":"nội dung trang web/tin tức được cập nhật","ex":"这个网站每天都会更新新闻。","py":"Zhège wǎngzhàn měitiān dōu huì gēngxīn xīnwén.","vi":"Trang web này cập nhật tin tức mỗi ngày.","en":"This website updates its news every day."},{"use":"nghĩa đổi mới, thay thiết bị cũ","ex":"公司决定更新办公室里的旧电脑。","py":"Gōngsī juédìng gēngxīn bàngōngshì lǐ de jiù diànnǎo.","vi":"Công ty quyết định thay mới những chiếc máy tính cũ trong văn phòng.","en":"The company decided to replace the old computers in the office."}]},"包括":{"en":"to include; to consist of","exs":[{"use":"A 包括 B: A bao gồm B","ex":"房费包括早餐。","py":"Fángfèi bāokuò zǎocān.","vi":"Tiền phòng đã bao gồm bữa sáng.","en":"The room rate includes breakfast."},{"use":"dùng với 在内 hoặc chỉ gồm cả người nói","ex":"我们班一共二十个人，包括老师。","py":"Wǒmen bān yígòng èrshí ge rén, bāokuò lǎoshī.","vi":"Lớp chúng tôi tổng cộng hai mươi người, kể cả giáo viên.","en":"There are twenty people in our class, including the teacher."},{"use":"liệt kê nhiều mục sau 包括","ex":"这次旅行的费用包括机票和住宿。","py":"Zhè cì lǚxíng de fèiyong bāokuò jīpiào hé zhùsù.","vi":"Chi phí chuyến du lịch lần này bao gồm vé máy bay và chỗ ở.","en":"The cost of this trip includes airfare and accommodation."},{"use":"liệt kê các ví dụ trong một nhóm","ex":"他喜欢很多运动，包括游泳、跑步和打篮球。","py":"Tā xǐhuan hěn duō yùndòng, bāokuò yóuyǒng, pǎobù hé dǎ lánqiú.","vi":"Anh ấy thích nhiều môn thể thao, bao gồm bơi lội, chạy bộ và chơi bóng rổ.","en":"He likes many sports, including swimming, running and playing basketball."}]},"交通":{"en":"traffic; transportation","exs":[{"use":"danh từ, giao thông của thành phố, kèm 方便","ex":"这个城市的交通很方便。","py":"Zhège chéngshì de jiāotōng hěn fāngbiàn.","vi":"Giao thông của thành phố này rất thuận tiện.","en":"Transportation in this city is very convenient."},{"use":"nói về tình trạng giao thông, 堵 (tắc)","ex":"早上上班时间，交通特别堵。","py":"Zǎoshang shàngbān shíjiān, jiāotōng tèbié dǔ.","vi":"Vào giờ đi làm buổi sáng, giao thông đặc biệt tắc nghẽn.","en":"During the morning rush hour, traffic is terrible."},{"use":"cụm 交通规则 (luật giao thông)","ex":"我们要遵守交通规则。","py":"Wǒmen yào zūnshǒu jiāotōng guīzé.","vi":"Chúng ta phải tuân thủ luật giao thông.","en":"We must obey the traffic rules."}]},"是否":{"en":"whether or not; if","exs":[{"use":"是否 + V: có… hay không (văn viết)","ex":"请告诉我你明天是否有时间。","py":"Qǐng gàosu wǒ nǐ míngtiān shìfǒu yǒu shíjiān.","vi":"Xin cho tôi biết ngày mai bạn có rảnh hay không.","en":"Please tell me whether you have time tomorrow."},{"use":"đi sau 不知道/不清楚, làm tân ngữ","ex":"我不知道他是否同意。","py":"Wǒ bù zhīdào tā shìfǒu tóngyì.","vi":"Tôi không biết anh ấy có đồng ý hay không.","en":"I don't know whether he agrees."},{"use":"dùng khi xác nhận, kiểm tra","ex":"我们需要确认一下会议是否按时开始。","py":"Wǒmen xūyào quèrèn yíxià huìyì shìfǒu ànshí kāishǐ.","vi":"Chúng ta cần xác nhận xem cuộc họp có bắt đầu đúng giờ không.","en":"We need to confirm whether the meeting will start on time."}]},"读懂":{"en":"to read and understand","exs":[{"use":"V + 懂: đọc và hiểu, dạng khẳng định","ex":"你能读懂这封中文信吗？","py":"Nǐ néng dúdǒng zhè fēng Zhōngwén xìn ma?","vi":"Bạn có thể đọc hiểu bức thư tiếng Trung này không?","en":"Can you read and understand this Chinese letter?"},{"use":"dạng phủ định 没读懂 (chưa đọc hiểu)","ex":"这篇文章太难了，我没读懂。","py":"Zhè piān wénzhāng tài nán le, wǒ méi dúdǒng.","vi":"Bài văn này khó quá, tôi không đọc hiểu.","en":"This article is too hard; I didn't understand it."},{"use":"chỉ năng lực đạt được, dùng với 已经……了","ex":"他已经能读懂中文报纸了。","py":"Tā yǐjīng néng dúdǒng Zhōngwén bàozhǐ le.","vi":"Anh ấy đã có thể đọc hiểu báo tiếng Trung rồi.","en":"He can already read and understand Chinese newspapers."}]},"易懂":{"en":"easy to understand","exs":[{"use":"tính từ, thường dùng 简单易懂","ex":"这本书的语言简单易懂。","py":"Zhè běn shū de yǔyán jiǎndān yìdǒng.","vi":"Ngôn ngữ của cuốn sách này đơn giản dễ hiểu.","en":"The language of this book is simple and easy to understand."},{"use":"làm định ngữ: 易懂的 + danh từ","ex":"请用易懂的话解释一下。","py":"Qǐng yòng yìdǒng de huà jiěshì yíxià.","vi":"Xin hãy giải thích bằng lời lẽ dễ hiểu.","en":"Please explain it in easy-to-understand words."},{"use":"làm bổ ngữ/định ngữ chỉ cách giảng","ex":"老师用简单易懂的方法讲解语法。","py":"Lǎoshī yòng jiǎndān yìdǒng de fāngfǎ jiǎngjiě yǔfǎ.","vi":"Thầy giáo dùng phương pháp đơn giản dễ hiểu để giảng ngữ pháp.","en":"The teacher explains grammar in a simple, easy-to-understand way."}]},"增长":{"en":"to grow; to increase","exs":[{"use":"động từ, + 了 + số liệu (tăng bao nhiêu)","ex":"今年公司的收入增长了百分之十。","py":"Jīnnián gōngsī de shōurù zēngzhǎng le bǎi fēn zhī shí.","vi":"Năm nay thu nhập của công ty tăng mười phần trăm.","en":"This year the company's income grew by ten percent."},{"use":"cụm 增长见识 (mở mang kiến thức)","ex":"旅游让人增长见识。","py":"Lǚyóu ràng rén zēngzhǎng jiànshi.","vi":"Du lịch giúp con người mở mang kiến thức.","en":"Traveling broadens one's horizons."},{"use":"chỉ số lượng tăng, + 得 + adv","ex":"城市人口正在快速增长。","py":"Chéngshì rénkǒu zhèngzài kuàisù zēngzhǎng.","vi":"Dân số thành phố đang tăng nhanh.","en":"The urban population is growing rapidly."}]},"大学生":{"en":"university student; college student","exs":[{"use":"danh từ chỉ người, 是 + 大学生","ex":"我哥哥是一名大学生。","py":"Wǒ gēge shì yì míng dàxuéshēng.","vi":"Anh trai tôi là sinh viên đại học.","en":"My older brother is a college student."},{"use":"làm chủ ngữ, nói về hoạt động của sinh viên","ex":"很多大学生利用假期打工。","py":"Hěn duō dàxuéshēng lìyòng jiàqī dǎgōng.","vi":"Nhiều sinh viên tranh thủ kỳ nghỉ để làm thêm.","en":"Many college students work part-time during vacations."},{"use":"đối tượng ưu đãi: 对大学生有优惠","ex":"这家咖啡店对大学生有优惠。","py":"Zhè jiā kāfēidiàn duì dàxuéshēng yǒu yōuhuì.","vi":"Quán cà phê này có ưu đãi cho sinh viên.","en":"This café offers discounts for college students."}]},"查找":{"en":"to look up; to search for","exs":[{"use":"động từ, tra từ trong từ điển","ex":"我在字典里查找这个生词的意思。","py":"Wǒ zài zìdiǎn lǐ cházhǎo zhège shēngcí de yìsi.","vi":"Tôi tra nghĩa của từ mới này trong từ điển.","en":"I'm looking up the meaning of this new word in the dictionary."},{"use":"tìm kiếm thông tin trên mạng","ex":"你可以在网上查找旅游路线。","py":"Nǐ kěyǐ zài wǎngshàng cházhǎo lǚyóu lùxiàn.","vi":"Bạn có thể tìm lộ trình du lịch trên mạng.","en":"You can search online for travel routes."},{"use":"dùng với 正在, tìm tài liệu","ex":"他正在图书馆查找资料。","py":"Tā zhèngzài túshūguǎn cházhǎo zīliào.","vi":"Anh ấy đang tìm tài liệu ở thư viện.","en":"He is looking for materials in the library."}]},"离不开":{"en":"cannot do without; inseparable from","exs":[{"use":"A 离不开 B: A không thể thiếu B","ex":"鱼离不开水。","py":"Yú líbùkāi shuǐ.","vi":"Cá không thể rời khỏi nước.","en":"Fish cannot live without water."},{"use":"chỉ sự phụ thuộc vào đồ vật","ex":"现在的生活已经离不开手机了。","py":"Xiànzài de shēnghuó yǐjīng líbùkāi shǒujī le.","vi":"Cuộc sống bây giờ đã không thể thiếu điện thoại.","en":"Life today can no longer do without mobile phones."},{"use":"chỉ sự gắn bó với người, thói quen","ex":"我每天早上都离不开一杯咖啡。","py":"Wǒ měitiān zǎoshang dōu líbùkāi yì bēi kāfēi.","vi":"Sáng nào tôi cũng không thể thiếu một ly cà phê.","en":"I can't start any morning without a cup of coffee."}]},"据调查":{"en":"according to a survey","exs":[{"use":"mở đầu câu: 据调查，……","ex":"据调查，百分之八十的学生喜欢上网。","py":"Jù diàochá, bǎi fēn zhī bāshí de xuésheng xǐhuan shàngwǎng.","vi":"Theo điều tra, tám mươi phần trăm học sinh thích lên mạng.","en":"According to a survey, 80 percent of students like going online."},{"use":"dẫn số liệu, so sánh theo thời gian","ex":"据调查，这个城市的空气比去年好了。","py":"Jù diàochá, zhège chéngshì de kōngqì bǐ qùnián hǎo le.","vi":"Theo điều tra, không khí thành phố này tốt hơn năm ngoái.","en":"According to a survey, the air in this city is better than last year."},{"use":"dẫn kết luận về thói quen xã hội","ex":"据调查，大多数年轻人每天看手机超过三个小时。","py":"Jù diàochá, dà duōshù niánqīngrén měitiān kàn shǒujī chāoguò sān ge xiǎoshí.","vi":"Theo điều tra, đa số người trẻ xem điện thoại hơn ba tiếng mỗi ngày.","en":"According to a survey, most young people look at their phones for more than three hours a day."}]},"技术":{"en":"technology; technique; skill","exs":[{"use":"danh từ, chỉ nghề nghiệp, kỹ thuật","ex":"他在一家公司做技术工作。","py":"Tā zài yì jiā gōngsī zuò jìshù gōngzuò.","vi":"Anh ấy làm công việc kỹ thuật ở một công ty.","en":"He does technical work at a company."},{"use":"chỉ công nghệ cụ thể: 这项技术","ex":"这项技术可以帮助农民提高产量。","py":"Zhè xiàng jìshù kěyǐ bāngzhù nóngmín tígāo chǎnliàng.","vi":"Công nghệ này có thể giúp nông dân nâng cao sản lượng.","en":"This technology can help farmers increase their yields."},{"use":"chỉ kỹ năng, tay nghề","ex":"他的游泳技术很好。","py":"Tā de yóuyǒng jìshù hěn hǎo.","vi":"Kỹ thuật bơi của anh ấy rất giỏi.","en":"His swimming skills are very good."}]},"方式":{"en":"way; manner; method","exs":[{"use":"danh từ: ……的方式 (cách thức)","ex":"每个人学习的方式不一样。","py":"Měi ge rén xuéxí de fāngshì bù yíyàng.","vi":"Cách học của mỗi người không giống nhau.","en":"Everyone has a different way of learning."},{"use":"cấu trúc 用……的方式 (bằng cách)","ex":"我们可以用电话或者邮件的方式联系。","py":"Wǒmen kěyǐ yòng diànhuà huòzhě yóujiàn de fāngshì liánxì.","vi":"Chúng ta có thể liên lạc bằng điện thoại hoặc email.","en":"We can get in touch by phone or email."},{"use":"cụm 付款方式 (phương thức thanh toán)","ex":"你喜欢什么付款方式？","py":"Nǐ xǐhuan shénme fùkuǎn fāngshì?","vi":"Bạn thích phương thức thanh toán nào?","en":"Which payment method do you prefer?"}]},"天天":{"en":"every day; daily","exs":[{"use":"phó từ, đứng trước động từ","ex":"我天天坐地铁上班。","py":"Wǒ tiāntiān zuò dìtiě shàngbān.","vi":"Ngày nào tôi cũng đi tàu điện ngầm đi làm.","en":"I take the subway to work every day."},{"use":"nhấn mạnh sự kiên trì mỗi ngày","ex":"他天天坚持锻炼身体。","py":"Tā tiāntiān jiānchí duànliàn shēntǐ.","vi":"Ngày nào anh ấy cũng kiên trì tập thể dục.","en":"He sticks to exercising every day."},{"use":"đi với 给……打电话","ex":"妈妈天天给我打电话。","py":"Māma tiāntiān gěi wǒ dǎ diànhuà.","vi":"Mẹ gọi điện cho tôi mỗi ngày.","en":"Mom calls me every day."}]},"受不了":{"en":"cannot stand; unbearable","exs":[{"use":"V + 不了: không chịu nổi, nêu lý do trước","ex":"今天太热了，我受不了。","py":"Jīntiān tài rè le, wǒ shòubuliǎo.","vi":"Hôm nay nóng quá, tôi không chịu nổi.","en":"It's too hot today; I can't stand it."},{"use":"受不了 + người + V (không chịu nổi ai làm gì)","ex":"我受不了他一直说个不停。","py":"Wǒ shòubuliǎo tā yìzhí shuō ge bù tíng.","vi":"Tôi không chịu nổi việc anh ta nói mãi không ngừng.","en":"I can't stand him talking nonstop."},{"use":"dùng với 谁都 (ai cũng)","ex":"这么吵的地方，谁都受不了。","py":"Zhème chǎo de dìfang, shéi dōu shòubuliǎo.","vi":"Nơi ồn thế này thì ai cũng không chịu nổi.","en":"Nobody could stand such a noisy place."}]},"写日记":{"en":"to write a diary; to keep a diary","exs":[{"use":"cụm động tân: 写 + 日记; dùng với 习惯","ex":"我有写日记的习惯。","py":"Wǒ yǒu xiě rìjì de xíguàn.","vi":"Tôi có thói quen viết nhật ký.","en":"I have a habit of keeping a diary."},{"use":"chỉ thời điểm cố định trong ngày","ex":"他每天睡觉前都写日记。","py":"Tā měitiān shuìjiào qián dōu xiě rìjì.","vi":"Mỗi ngày trước khi ngủ anh ấy đều viết nhật ký.","en":"He writes in his diary every day before bed."},{"use":"kết hợp với 让/叫 (yêu cầu ai làm gì)","ex":"老师让我们用中文写日记。","py":"Lǎoshī ràng wǒmen yòng Zhōngwén xiě rìjì.","vi":"Thầy giáo bảo chúng tôi viết nhật ký bằng tiếng Trung.","en":"The teacher asked us to write our diaries in Chinese."}]},"日记":{"en":"diary; journal","exs":[{"use":"danh từ, 记在日记里 (ghi vào nhật ký)","ex":"我把今天的事情记在日记里。","py":"Wǒ bǎ jīntiān de shìqing jì zài rìjì lǐ.","vi":"Tôi ghi chuyện hôm nay vào nhật ký.","en":"I wrote today's events in my diary."},{"use":"cụm 日记本 (cuốn sổ nhật ký)","ex":"她的日记本很漂亮。","py":"Tā de rìjìběn hěn piàoliang.","vi":"Cuốn sổ nhật ký của cô ấy rất đẹp.","en":"Her diary book is very pretty."},{"use":"lượng từ 篇 đi với 日记","ex":"他每天晚上写一篇日记。","py":"Tā měitiān wǎnshang xiě yì piān rìjì.","vi":"Mỗi tối anh ấy viết một bài nhật ký.","en":"He writes a diary entry every evening."}]},"安全":{"en":"safe; secure; safety","exs":[{"use":"tính từ làm vị ngữ: 很安全","ex":"坐飞机很安全。","py":"Zuò fēijī hěn ānquán.","vi":"Đi máy bay rất an toàn.","en":"Flying is very safe."},{"use":"danh từ, 注意安全 (chú ý an toàn)","ex":"开车时一定要注意安全。","py":"Kāichē shí yídìng yào zhùyì ānquán.","vi":"Khi lái xe nhất định phải chú ý an toàn.","en":"You must pay attention to safety when driving."},{"use":"nói về nơi chốn: 不太安全","ex":"这里晚上不太安全，你早点回家。","py":"Zhèlǐ wǎnshang bú tài ānquán, nǐ zǎodiǎn huí jiā.","vi":"Chỗ này buổi tối không an toàn lắm, bạn về nhà sớm đi.","en":"It isn't very safe here at night, so go home early."},{"use":"làm định ngữ: 安全的地方","ex":"请把重要文件放在安全的地方。","py":"Qǐng bǎ zhòngyào wénjiàn fàng zài ānquán de dìfang.","vi":"Xin hãy để tài liệu quan trọng ở nơi an toàn.","en":"Please keep important documents in a safe place."}]},"密码":{"en":"password; code","exs":[{"use":"danh từ, mật khẩu điện thoại, tài khoản","ex":"我忘记了手机的密码。","py":"Wǒ wàngjì le shǒujī de mìmǎ.","vi":"Tôi quên mất mật khẩu điện thoại.","en":"I forgot my phone's password."},{"use":"làm chủ ngữ, kèm 设 (đặt)","ex":"密码要设得复杂一点儿，这样更安全。","py":"Mìmǎ yào shè de fùzá yìdiǎnr, zhèyàng gèng ānquán.","vi":"Mật khẩu nên đặt phức tạp một chút, như vậy an toàn hơn.","en":"Make your password a bit more complex; it's safer that way."},{"use":"cụm 输入密码 (nhập mật khẩu)","ex":"请输入六位数密码。","py":"Qǐng shūrù liù wèi shù mìmǎ.","vi":"Xin nhập mật khẩu sáu chữ số.","en":"Please enter the six-digit password."}]},"允许":{"en":"to allow; to permit","exs":[{"use":"A 不允许 B + V: không cho phép","ex":"医生不允许我吃辣的。","py":"Yīshēng bù yǔnxǔ wǒ chī là de.","vi":"Bác sĩ không cho phép tôi ăn đồ cay.","en":"The doctor doesn't allow me to eat spicy food."},{"use":"quy định nơi công cộng: 不允许 + V","ex":"这里不允许抽烟。","py":"Zhèlǐ bù yǔnxǔ chōuyān.","vi":"Ở đây không được phép hút thuốc.","en":"Smoking is not allowed here."},{"use":"khẳng định: 允许 + người + V","ex":"爸爸允许我周末去朋友家玩。","py":"Bàba yǔnxǔ wǒ zhōumò qù péngyou jiā wán.","vi":"Bố cho phép tôi cuối tuần đến nhà bạn chơi.","en":"Dad allows me to go to a friend's house on weekends."}]},"危险":{"en":"dangerous; danger","exs":[{"use":"tính từ: 很危险","ex":"过马路时看手机很危险。","py":"Guò mǎlù shí kàn shǒujī hěn wēixiǎn.","vi":"Vừa qua đường vừa xem điện thoại rất nguy hiểm.","en":"It's dangerous to look at your phone while crossing the street."},{"use":"đề nghị, khuyên can: 别……了，太危险","ex":"这座山很危险，你们别爬了。","py":"Zhè zuò shān hěn wēixiǎn, nǐmen bié pá le.","vi":"Ngọn núi này rất nguy hiểm, các bạn đừng leo nữa.","en":"This mountain is very dangerous, so don't climb it."},{"use":"làm danh từ: 处于危险中","ex":"消防员救出了处于危险中的孩子。","py":"Xiāofángyuán jiùchū le chǔyú wēixiǎn zhōng de háizi.","vi":"Lính cứu hỏa đã cứu đứa trẻ đang gặp nguy hiểm.","en":"The firefighters rescued the child who was in danger."}]},"接着":{"en":"then; next; to carry on","exs":[{"use":"phó từ nối tiếp hành động: 说完，接着……","ex":"他说完以后，接着唱了一首歌。","py":"Tā shuōwán yǐhòu, jiēzhe chàng le yì shǒu gē.","vi":"Nói xong, anh ấy tiếp đó hát một bài.","en":"After he finished speaking, he went on to sing a song."},{"use":"trình tự 先……，接着……，最后……","ex":"先洗菜，接着切菜，最后炒菜。","py":"Xiān xǐ cài, jiēzhe qiē cài, zuìhòu chǎo cài.","vi":"Trước tiên rửa rau, tiếp theo thái rau, cuối cùng xào.","en":"First wash the vegetables, then cut them, and finally stir-fry them."},{"use":"chuyển sang nội dung kế tiếp","ex":"老师讲完了第一课，接着讲第二课。","py":"Lǎoshī jiǎngwán le dì-yī kè, jiēzhe jiǎng dì-èr kè.","vi":"Thầy giáo giảng xong bài một thì tiếp tục giảng bài hai.","en":"The teacher finished Lesson 1 and then moved on to Lesson 2."}]},"梦见":{"en":"to dream of; to see in a dream","exs":[{"use":"梦见 + người/việc (mơ thấy)","ex":"昨晚我梦见了小时候的朋友。","py":"Zuówǎn wǒ mèngjiàn le xiǎoshíhou de péngyou.","vi":"Tối qua tôi mơ thấy người bạn thuở nhỏ.","en":"Last night I dreamed of a childhood friend."},{"use":"梦见 + 自己 + V","ex":"她梦见自己在天上飞。","py":"Tā mèngjiàn zìjǐ zài tiān shàng fēi.","vi":"Cô ấy mơ thấy mình bay trên trời.","en":"She dreamed that she was flying in the sky."},{"use":"dạng nghi vấn 梦见过……吗","ex":"你梦见过什么奇怪的东西吗？","py":"Nǐ mèngjiàn guo shénme qíguài de dōngxi ma?","vi":"Bạn đã từng mơ thấy thứ gì kỳ lạ chưa?","en":"Have you ever dreamed of anything strange?"}]},"警察":{"en":"police officer; the police","exs":[{"use":"danh từ, chỉ người cảnh sát","ex":"警察正在路口指挥交通。","py":"Jǐngchá zhèngzài lùkǒu zhǐhuī jiāotōng.","vi":"Cảnh sát đang điều khiển giao thông ở ngã tư.","en":"A police officer is directing traffic at the intersection."},{"use":"đi với 找 (tìm cảnh sát nhờ giúp)","ex":"如果迷路了，可以找警察帮忙。","py":"Rúguǒ mílù le, kěyǐ zhǎo jǐngchá bāngmáng.","vi":"Nếu bị lạc đường, có thể nhờ cảnh sát giúp đỡ.","en":"If you get lost, you can ask a police officer for help."},{"use":"đi với 当 (làm nghề)","ex":"我哥哥想当一名警察。","py":"Wǒ gēge xiǎng dāng yì míng jǐngchá.","vi":"Anh trai tôi muốn làm cảnh sát.","en":"My older brother wants to be a police officer."}]},"抓住":{"en":"to catch; to grab; to seize","exs":[{"use":"V + 住: bắt giữ người","ex":"警察抓住了那个小偷。","py":"Jǐngchá zhuāzhù le nàge xiǎotōu.","vi":"Cảnh sát đã bắt được tên trộm đó.","en":"The police caught that thief."},{"use":"nghĩa cụ thể: nắm chặt","ex":"他一把抓住了我的手。","py":"Tā yì bǎ zhuāzhù le wǒ de shǒu.","vi":"Anh ấy nắm chặt lấy tay tôi.","en":"He grabbed my hand firmly."},{"use":"nghĩa bóng: nắm bắt cơ hội","ex":"你要抓住这次机会。","py":"Nǐ yào zhuāzhù zhè cì jīhuì.","vi":"Bạn phải nắm bắt cơ hội lần này.","en":"You must seize this opportunity."}]},"坏人":{"en":"bad person; villain","exs":[{"use":"danh từ, đối lập với 好人","ex":"不要跟陌生人走，他可能是坏人。","py":"Búyào gēn mòshēngrén zǒu, tā kěnéng shì huàirén.","vi":"Đừng đi theo người lạ, họ có thể là người xấu.","en":"Don't go with strangers; they might be bad people."},{"use":"trong phim, truyện: 电影里的坏人","ex":"电影里的坏人最后被抓住了。","py":"Diànyǐng lǐ de huàirén zuìhòu bèi zhuāzhù le.","vi":"Kẻ xấu trong phim cuối cùng bị bắt.","en":"The villain in the movie was finally caught."},{"use":"làm tân ngữ của 打击/抓 (bắt kẻ xấu)","ex":"警察的工作就是抓坏人。","py":"Jǐngchá de gōngzuò jiùshì zhuā huàirén.","vi":"Công việc của cảnh sát chính là bắt kẻ xấu.","en":"A police officer's job is to catch bad guys."}]},"做梦":{"en":"to dream; to daydream","exs":[{"use":"động từ ly hợp: 做梦 (nằm mơ)","ex":"我昨晚做梦了，梦见自己在海边。","py":"Wǒ zuówǎn zuòmèng le, mèngjiàn zìjǐ zài hǎibiān.","vi":"Tối qua tôi nằm mơ, mơ thấy mình ở bên bờ biển.","en":"I had a dream last night; I dreamed I was at the seaside."},{"use":"câu hỏi xác nhận: 你是不是在做梦？","ex":"你是不是在做梦？这怎么可能呢？","py":"Nǐ shì bú shì zài zuòmèng? Zhè zěnme kěnéng ne?","vi":"Bạn có đang nằm mơ không đấy? Chuyện này sao có thể chứ?","en":"Are you dreaming? How could that be possible?"},{"use":"chỉ thói quen: 经常做梦","ex":"我经常做梦，所以睡不好。","py":"Wǒ jīngcháng zuòmèng, suǒyǐ shuì bu hǎo.","vi":"Tôi hay nằm mơ nên ngủ không ngon.","en":"I often dream, so I don't sleep well."},{"use":"nghĩa bóng: 别做梦了 (đừng mơ mộng)","ex":"别做梦了，快起床上班吧！","py":"Bié zuòmèng le, kuài qǐchuáng shàngbān ba!","vi":"Đừng mơ nữa, mau dậy đi làm đi!","en":"Stop dreaming and get up for work!"}]},"睡醒":{"en":"to wake up (from sleep)","exs":[{"use":"V + 醒: ngủ dậy; ……的时候","ex":"我睡醒的时候已经十点了。","py":"Wǒ shuìxǐng de shíhou yǐjīng shí diǎn le.","vi":"Lúc tôi ngủ dậy thì đã mười giờ rồi.","en":"It was already ten o'clock when I woke up."},{"use":"dạng phủ định 还没睡醒","ex":"他还没睡醒，你小声一点儿。","py":"Tā hái méi shuìxǐng, nǐ xiǎo shēng yìdiǎnr.","vi":"Anh ấy chưa ngủ dậy, bạn nói nhỏ thôi.","en":"He hasn't woken up yet, so keep your voice down."},{"use":"睡醒以后 + kết quả","ex":"睡醒以后，我觉得头不疼了。","py":"Shuìxǐng yǐhòu, wǒ juéde tóu bù téng le.","vi":"Ngủ dậy rồi, tôi thấy đầu không còn đau nữa.","en":"After waking up, I felt my headache was gone."}]},"之后":{"en":"after; afterwards; later","exs":[{"use":"V + 之后: sau khi…","ex":"吃完饭之后，我们去公园散步。","py":"Chī wán fàn zhīhòu, wǒmen qù gōngyuán sànbù.","vi":"Sau khi ăn cơm xong, chúng tôi đi dạo ở công viên.","en":"After eating, we went for a walk in the park."},{"use":"mốc thời gian + 之后","ex":"毕业之后，他去上海工作了。","py":"Bìyè zhīhòu, tā qù Shànghǎi gōngzuò le.","vi":"Sau khi tốt nghiệp, anh ấy đến Thượng Hải làm việc.","en":"After graduating, he went to work in Shanghai."},{"use":"khoảng thời gian + 之后 (… nữa thì)","ex":"三天之后我就回来。","py":"Sān tiān zhīhòu wǒ jiù huílai.","vi":"Ba ngày nữa tôi sẽ quay lại.","en":"I'll be back in three days."}]},"记不清":{"en":"cannot remember clearly","exs":[{"use":"V + 不 + 补语: nhớ không rõ + người/việc","ex":"时间太久了，我记不清他的样子了。","py":"Shíjiān tài jiǔ le, wǒ jìbuqīng tā de yàngzi le.","vi":"Lâu quá rồi, tôi nhớ không rõ dáng vẻ của anh ấy.","en":"It was so long ago that I can't remember clearly what he looked like."},{"use":"đi với mệnh đề nghi vấn (什么)","ex":"我记不清昨天的作业是什么。","py":"Wǒ jìbuqīng zuótiān de zuòyè shì shénme.","vi":"Tôi không nhớ rõ bài tập hôm qua là gì.","en":"I can't recall exactly what yesterday's homework was."},{"use":"đảo tân ngữ lên đầu câu","ex":"他的电话号码，我记不清了。","py":"Tā de diànhuà hàomǎ, wǒ jìbuqīng le.","vi":"Số điện thoại của anh ấy, tôi nhớ không rõ nữa.","en":"I can't remember his phone number clearly anymore."}]},"之所以":{"en":"the reason why...; that is why","exs":[{"use":"cấu trúc 之所以……，是因为……","ex":"之所以迟到，是因为路上堵车。","py":"Zhīsuǒyǐ chídào, shì yīnwèi lùshang dǔchē.","vi":"Sở dĩ đến muộn là vì trên đường bị tắc xe.","en":"The reason I was late is that there was a traffic jam."},{"use":"chủ ngữ + 之所以 + kết quả，是因为……","ex":"他之所以成功，是因为他很努力。","py":"Tā zhīsuǒyǐ chénggōng, shì yīnwèi tā hěn nǔlì.","vi":"Sở dĩ anh ấy thành công là vì anh ấy rất nỗ lực.","en":"The reason he succeeded is that he works very hard."},{"use":"giải thích lý do học tập","ex":"我之所以学中文，是因为我喜欢中国文化。","py":"Wǒ zhīsuǒyǐ xué Zhōngwén, shì yīnwèi wǒ xǐhuan Zhōngguó wénhuà.","vi":"Sở dĩ tôi học tiếng Trung là vì tôi thích văn hóa Trung Quốc.","en":"The reason I study Chinese is that I like Chinese culture."}]},"忘记":{"en":"to forget","exs":[{"use":"忘记 + V/tân ngữ (quên làm gì)","ex":"我忘记带钥匙了。","py":"Wǒ wàngjì dài yàoshi le.","vi":"Tôi quên mang chìa khóa rồi.","en":"I forgot to bring my keys."},{"use":"dạng cầu khiến 别忘记","ex":"别忘记明天的会议。","py":"Bié wàngjì míngtiān de huìyì.","vi":"Đừng quên cuộc họp ngày mai.","en":"Don't forget tomorrow's meeting."},{"use":"quên đi cái đã biết: 忘记了 + người","ex":"他忘记了我的名字。","py":"Tā wàngjì le wǒ de míngzi.","vi":"Anh ấy quên mất tên tôi.","en":"He forgot my name."},{"use":"phủ định 永远不会忘记","ex":"我永远不会忘记在这里度过的日子。","py":"Wǒ yǒngyuǎn bú huì wàngjì zài zhèlǐ dùguò de rìzi.","vi":"Tôi sẽ mãi mãi không quên những ngày đã trải qua ở đây.","en":"I will never forget the days I spent here."}]},"道理":{"en":"reason; principle; sense","exs":[{"use":"有道理 (có lý)","ex":"他说得很有道理。","py":"Tā shuō de hěn yǒu dàolǐ.","vi":"Anh ấy nói rất có lý.","en":"What he says makes a lot of sense."},{"use":"danh từ chỉ lẽ phải, kèm 懂","ex":"这个道理连小孩子都懂。","py":"Zhège dàolǐ lián xiǎo háizi dōu dǒng.","vi":"Đạo lý này đến trẻ con cũng hiểu.","en":"Even small children understand this principle."},{"use":"讲道理 (nói lý lẽ)","ex":"做事要讲道理，不能只想着自己。","py":"Zuòshì yào jiǎng dàolǐ, bù néng zhǐ xiǎngzhe zìjǐ.","vi":"Làm việc phải biết nói lý lẽ, không thể chỉ nghĩ cho bản thân.","en":"You should be reasonable and not think only of yourself."}]},"天亮":{"en":"daybreak; dawn; to get light","exs":[{"use":"天亮 + 以后/就 (khi trời sáng)","ex":"天亮以后我们就出发。","py":"Tiānliàng yǐhòu wǒmen jiù chūfā.","vi":"Trời sáng rồi chúng ta sẽ xuất phát.","en":"We'll set off once it gets light."},{"use":"V + 到天亮 (đến tận sáng)","ex":"他工作到天亮才睡觉。","py":"Tā gōngzuò dào tiānliàng cái shuìjiào.","vi":"Anh ấy làm việc đến sáng mới đi ngủ.","en":"He worked until dawn before going to sleep."},{"use":"天亮得 + 早/晚","ex":"冬天天亮得晚。","py":"Dōngtiān tiānliàng de wǎn.","vi":"Mùa đông trời sáng muộn.","en":"In winter, daybreak comes late."}]},"上天":{"en":"heaven; God; to go up to the sky","exs":[{"use":"danh từ: ông trời, thượng đế","ex":"上天保佑你平安。","py":"Shàngtiān bǎoyòu nǐ píng'ān.","vi":"Cầu trời phù hộ bạn bình an.","en":"May Heaven keep you safe."},{"use":"chỉ ông trời đối xử với con người","ex":"上天对每个人都很公平。","py":"Shàngtiān duì měi ge rén dōu hěn gōngpíng.","vi":"Ông trời rất công bằng với mọi người.","en":"Heaven is fair to everyone."},{"use":"dùng để cảm tạ, cầu mong","ex":"她感谢上天给了她一个健康的孩子。","py":"Tā gǎnxiè shàngtiān gěi le tā yí ge jiànkāng de háizi.","vi":"Cô ấy cảm tạ ông trời đã cho cô một đứa con khỏe mạnh.","en":"She thanked Heaven for giving her a healthy child."},{"use":"nghĩa khác (động từ): lên trời","ex":"中国的火箭又一次成功上天了。","py":"Zhōngguó de huǒjiàn yòu yí cì chénggōng shàngtiān le.","vi":"Tên lửa của Trung Quốc lại một lần nữa lên trời thành công.","en":"China's rocket has successfully gone into the sky once again."}]},"矿泉水":{"en":"mineral water","exs":[{"use":"danh từ, 瓶 làm lượng từ","ex":"请给我一瓶矿泉水。","py":"Qǐng gěi wǒ yì píng kuàngquánshuǐ.","vi":"Xin cho tôi một chai nước khoáng.","en":"Please give me a bottle of mineral water."},{"use":"mua/mang theo khi đi chơi","ex":"爬山时要多带几瓶矿泉水。","py":"Páshān shí yào duō dài jǐ píng kuàngquánshuǐ.","vi":"Khi leo núi nên mang thêm vài chai nước khoáng.","en":"Bring a few extra bottles of mineral water when hiking."},{"use":"nói về giá cả, nhãn hiệu","ex":"这个牌子的矿泉水很便宜。","py":"Zhège páizi de kuàngquánshuǐ hěn piányi.","vi":"Nước khoáng của nhãn hiệu này rất rẻ.","en":"This brand of mineral water is very cheap."}]},"这方面":{"en":"this aspect; in this respect","exs":[{"use":"在这方面 (về mặt này)","ex":"他在这方面很有经验。","py":"Tā zài zhè fāngmiàn hěn yǒu jīngyàn.","vi":"Anh ấy rất có kinh nghiệm về mặt này.","en":"He has a lot of experience in this area."},{"use":"关于这方面 (liên quan đến mặt này)","ex":"关于这方面，我想听听你的意见。","py":"Guānyú zhè fāngmiàn, wǒ xiǎng tīngtīng nǐ de yìjiàn.","vi":"Về mặt này, tôi muốn nghe ý kiến của bạn.","en":"On this matter, I'd like to hear your opinion."},{"use":"对这方面 + 不了解 (không hiểu rõ)","ex":"我对这方面不太了解。","py":"Wǒ duì zhè fāngmiàn bú tài liǎojiě.","vi":"Tôi không hiểu lắm về phương diện này.","en":"I don't know much about this area."}]},"说法":{"en":"way of saying; statement; version","exs":[{"use":"danh từ: cách nói, quan điểm","ex":"关于这件事，大家有不同的说法。","py":"Guānyú zhè jiàn shì, dàjiā yǒu bùtóng de shuōfǎ.","vi":"Về chuyện này, mọi người có những cách nói khác nhau.","en":"People have different accounts of this matter."},{"use":"nói về một quan niệm (这种说法)","ex":"这种说法没有科学根据。","py":"Zhè zhǒng shuōfǎ méiyǒu kēxué gēnjù.","vi":"Cách nói này không có căn cứ khoa học.","en":"This claim has no scientific basis."},{"use":"câu hỏi về độ đúng của quan điểm","ex":"“吃什么补什么”这个说法对吗？","py":"“Chī shénme bǔ shénme” zhège shuōfǎ duì ma?","vi":"Cách nói “ăn gì bổ nấy” có đúng không?","en":"Is the saying \"you are what you eat\" correct?"},{"use":"nghĩa 2: lời giải thích, câu trả lời thỏa đáng","ex":"你得给我们一个说法。","py":"Nǐ děi gěi wǒmen yí ge shuōfǎ.","vi":"Bạn phải cho chúng tôi một lời giải thích thỏa đáng.","en":"You owe us an explanation."}]},"租房子":{"en":"to rent a house/apartment","exs":[{"use":"động từ ly hợp 租 + 房子; 打算 + V","ex":"我打算在公司附近租房子。","py":"Wǒ dǎsuàn zài gōngsī fùjìn zū fángzi.","vi":"Tôi định thuê nhà gần công ty.","en":"I plan to rent a place near my company."},{"use":"chỉ địa điểm: 在……租房子","ex":"刚来这个城市的时候，我在郊区租房子。","py":"Gāng lái zhège chéngshì de shíhou, wǒ zài jiāoqū zū fángzi.","vi":"Lúc mới đến thành phố này, tôi thuê nhà ở ngoại ô.","en":"When I first came to this city, I rented a place in the suburbs."},{"use":"làm chủ ngữ với 要……","ex":"租房子要先看看周围的环境。","py":"Zū fángzi yào xiān kànkan zhōuwéi de huánjìng.","vi":"Thuê nhà thì phải xem qua môi trường xung quanh trước.","en":"When renting a home, first check out the surroundings."}]},"到期":{"en":"to expire; to fall due","exs":[{"use":"động từ: 下个月到期 (hết hạn tháng sau)","ex":"我的签证下个月到期。","py":"Wǒ de qiānzhèng xià ge yuè dàoqī.","vi":"Visa của tôi sẽ hết hạn vào tháng sau.","en":"My visa expires next month."},{"use":"dùng với 已经……了 (đã hết hạn)","ex":"这张信用卡已经到期了。","py":"Zhè zhāng xìnyòngkǎ yǐjīng dàoqī le.","vi":"Thẻ tín dụng này đã hết hạn rồi.","en":"This credit card has already expired."},{"use":"…… 到期以后 (sau khi hết hạn)","ex":"房子的租约到期以后，我们就搬家。","py":"Fángzi de zūyuē dàoqī yǐhòu, wǒmen jiù bānjiā.","vi":"Sau khi hợp đồng thuê nhà hết hạn, chúng tôi sẽ chuyển nhà.","en":"Once the lease on the apartment expires, we will move."}]},"房东":{"en":"landlord; landlady","exs":[{"use":"danh từ, người cho thuê nhà","ex":"房东每个月五号来收房租。","py":"Fángdōng měi ge yuè wǔ hào lái shōu fángzū.","vi":"Chủ nhà đến thu tiền thuê vào ngày mùng năm hằng tháng.","en":"The landlord comes to collect the rent on the fifth of every month."},{"use":"miêu tả tính cách chủ nhà","ex":"我们的房东人很好，经常帮我们修东西。","py":"Wǒmen de fángdōng rén hěn hǎo, jīngcháng bāng wǒmen xiū dōngxi.","vi":"Chủ nhà của chúng tôi rất tốt, thường giúp chúng tôi sửa đồ.","en":"Our landlord is very nice and often helps us fix things."},{"use":"给 + 房东 + 打电话 (gọi cho chủ nhà)","ex":"我要给房东打电话，空调坏了。","py":"Wǒ yào gěi fángdōng dǎ diànhuà, kōngtiáo huài le.","vi":"Tôi phải gọi cho chủ nhà, máy lạnh hỏng rồi.","en":"I need to call the landlord; the air conditioner is broken."}]},"占线":{"en":"(phone) line is busy","exs":[{"use":"động từ chỉ máy bận, 一直占线","ex":"我打了好几次，他的电话一直占线。","py":"Wǒ dǎ le hǎo jǐ cì, tā de diànhuà yìzhí zhànxiàn.","vi":"Tôi gọi mấy lần rồi, máy anh ấy cứ báo bận.","en":"I called several times and his line was always busy."},{"use":"thông báo khi gọi: 电话占线","ex":"电话占线，请稍后再打。","py":"Diànhuà zhànxiàn, qǐng shāohòu zài dǎ.","vi":"Máy đang bận, xin vui lòng gọi lại sau.","en":"The line is busy, please call back later."},{"use":"câu hỏi 为什么……总是占线","ex":"为什么你的手机总是占线？","py":"Wèishénme nǐ de shǒujī zǒngshì zhànxiàn?","vi":"Sao điện thoại của bạn lúc nào cũng bận máy vậy?","en":"Why is your phone always busy?"}]},"功夫":{"en":"kung fu; skill; time and effort","exs":[{"use":"nghĩa 1: võ thuật Trung Quốc","ex":"他从小就学中国功夫。","py":"Tā cóng xiǎo jiù xué Zhōngguó gōngfu.","vi":"Từ nhỏ anh ấy đã học võ Trung Quốc.","en":"He has studied Chinese kung fu since childhood."},{"use":"cụm 功夫电影 (phim võ thuật)","ex":"李小龙的功夫电影很有名。","py":"Lǐ Xiǎolóng de gōngfu diànyǐng hěn yǒumíng.","vi":"Phim võ thuật của Lý Tiểu Long rất nổi tiếng.","en":"Bruce Lee's kung fu movies are very famous."},{"use":"nghĩa 2: tài nghệ, kỹ năng luyện được","ex":"他练了好多年，功夫很好。","py":"Tā liàn le hǎo duō nián, gōngfu hěn hǎo.","vi":"Anh ấy luyện nhiều năm nên công phu rất giỏi.","en":"He has practiced for many years and is highly skilled."},{"use":"nghĩa 3: công sức, thời gian (费功夫)","ex":"做这道菜很费功夫。","py":"Zuò zhè dào cài hěn fèi gōngfu.","vi":"Nấu món này rất tốn công sức.","en":"This dish takes a lot of time and effort to make."}]},"乒乓球":{"en":"table tennis; ping-pong","exs":[{"use":"danh từ môn thể thao, 打乒乓球","ex":"我周末常和同学一起打乒乓球。","py":"Wǒ zhōumò cháng hé tóngxué yìqǐ dǎ pīngpāngqiú.","vi":"Cuối tuần tôi thường cùng bạn học chơi bóng bàn.","en":"On weekends I often play table tennis with my classmates."},{"use":"nói về trình độ: 乒乓球打得很好","ex":"中国的乒乓球打得很好。","py":"Zhōngguó de pīngpāngqiú dǎ de hěn hǎo.","vi":"Người Trung Quốc chơi bóng bàn rất giỏi.","en":"China plays table tennis very well."},{"use":"cụm 乒乓球队 (đội bóng bàn)","ex":"他是学校乒乓球队的队员。","py":"Tā shì xuéxiào pīngpāngqiúduì de duìyuán.","vi":"Anh ấy là thành viên đội bóng bàn của trường.","en":"He is a member of the school's table tennis team."}]},"羽毛球":{"en":"badminton; shuttlecock","exs":[{"use":"làm danh từ, tên môn thể thao; 打羽毛球 = chơi cầu lông","ex":"我周末常常和朋友一起打羽毛球。","py":"Wǒ zhōumò chángcháng hé péngyou yìqǐ dǎ yǔmáoqiú.","vi":"Cuối tuần tôi thường cùng bạn bè chơi cầu lông.","en":"I often play badminton with my friends on weekends."},{"use":"羽毛球 chỉ môn thể thao, đi với 比赛 (trận đấu)","ex":"明天下午有一场羽毛球比赛。","py":"Míngtiān xiàwǔ yǒu yì chǎng yǔmáoqiú bǐsài.","vi":"Chiều mai có một trận thi đấu cầu lông.","en":"There is a badminton match tomorrow afternoon."},{"use":"羽毛球 chỉ quả cầu; mua dụng cụ: 买 + 羽毛球 + 拍/球","ex":"我想买两个羽毛球拍和一筒羽毛球。","py":"Wǒ xiǎng mǎi liǎng ge yǔmáoqiúpāi hé yì tǒng yǔmáoqiú.","vi":"Tôi muốn mua hai cây vợt cầu lông và một ống cầu.","en":"I want to buy two badminton rackets and a tube of shuttlecocks."}]},"运动员":{"en":"athlete; sportsman/sportswoman","exs":[{"use":"làm danh từ chỉ người; 运动员 + 的 + danh từ","ex":"他是一名很有名的足球运动员。","py":"Tā shì yì míng hěn yǒumíng de zúqiú yùndòngyuán.","vi":"Anh ấy là một cầu thủ bóng đá rất nổi tiếng.","en":"He is a very famous football player."},{"use":"làm chủ ngữ, kết hợp với 每天、训练","ex":"运动员每天都要认真训练。","py":"Yùndòngyuán měitiān dōu yào rènzhēn xùnliàn.","vi":"Vận động viên ngày nào cũng phải luyện tập nghiêm túc.","en":"Athletes have to train seriously every day."},{"use":"dùng với 当/成为 để nói về nghề nghiệp, ước mơ","ex":"我小时候的梦想是成为一名运动员。","py":"Wǒ xiǎoshíhou de mèngxiǎng shì chéngwéi yì míng yùndòngyuán.","vi":"Ước mơ hồi nhỏ của tôi là trở thành vận động viên.","en":"My childhood dream was to become an athlete."}]},"禁止":{"en":"to prohibit; to forbid; to ban","exs":[{"use":"禁止 + động từ: cấm làm gì, thường thấy trên biển báo","ex":"这里禁止吸烟。","py":"Zhèlǐ jìnzhǐ xīyān.","vi":"Ở đây cấm hút thuốc.","en":"Smoking is prohibited here."},{"use":"禁止 + 人 + động từ: cấm ai làm gì","ex":"学校禁止学生带手机进考场。","py":"Xuéxiào jìnzhǐ xuésheng dài shǒujī jìn kǎochǎng.","vi":"Nhà trường cấm học sinh mang điện thoại vào phòng thi.","en":"The school forbids students from bringing phones into the exam room."},{"use":"禁止 dùng trong thông báo, quy định: 禁止 + 入内/停车","ex":"医院门口禁止停车,请把车开走。","py":"Yīyuàn ménkǒu jìnzhǐ tíngchē, qǐng bǎ chē kāizǒu.","vi":"Trước cổng bệnh viện cấm đỗ xe, xin hãy lái xe đi.","en":"Parking is prohibited in front of the hospital; please move your car."}]},"对面":{"en":"opposite; across from; the other side","exs":[{"use":"làm danh từ chỉ vị trí: 在……对面","ex":"我家就在学校对面。","py":"Wǒ jiā jiù zài xuéxiào duìmiàn.","vi":"Nhà tôi ngay đối diện trường học.","en":"My home is right across from the school."},{"use":"对面 + 的 + danh từ: bổ nghĩa cho danh từ","ex":"对面的商店几点开门?","py":"Duìmiàn de shāngdiàn jǐ diǎn kāimén?","vi":"Cửa hàng đối diện mấy giờ mở cửa?","en":"What time does the shop across the street open?"},{"use":"làm chủ ngữ/tân ngữ, chỉ người hoặc phía đối diện","ex":"坐在我对面的那个人是我的老师。","py":"Zuò zài wǒ duìmiàn de nàge rén shì wǒ de lǎoshī.","vi":"Người ngồi đối diện tôi là thầy giáo của tôi.","en":"The person sitting across from me is my teacher."}]},"着急":{"en":"anxious; worried; to be in a hurry","exs":[{"use":"làm tính từ: 别 + 着急 (đừng sốt ruột)","ex":"你别着急,时间还早。","py":"Nǐ bié zháojí, shíjiān hái zǎo.","vi":"Bạn đừng vội, vẫn còn sớm mà.","en":"Don't worry, it's still early."},{"use":"làm vị ngữ: 为/对 + việc + 着急","ex":"孩子还没回家,妈妈很着急。","py":"Háizi hái méi huí jiā, māma hěn zháojí.","vi":"Con vẫn chưa về nhà, mẹ rất lo lắng.","en":"The child hasn't come home yet, so Mom is very worried."},{"use":"着急 + động từ: vội vàng làm gì","ex":"他着急去机场,所以打了一辆出租车。","py":"Tā zháojí qù jīchǎng, suǒyǐ dǎ le yí liàng chūzūchē.","vi":"Anh ấy vội ra sân bay nên đã bắt một chiếc taxi.","en":"He was in a hurry to get to the airport, so he took a taxi."}]},"小区":{"en":"residential community; housing estate","exs":[{"use":"làm danh từ chỉ khu dân cư; 住在……小区","ex":"我住在一个很安静的小区。","py":"Wǒ zhù zài yí ge hěn ānjìng de xiǎoqū.","vi":"Tôi sống trong một khu dân cư rất yên tĩnh.","en":"I live in a very quiet residential community."},{"use":"小区 + 里/内: trong khu dân cư","ex":"我们小区里有一个小公园。","py":"Wǒmen xiǎoqū lǐ yǒu yí ge xiǎo gōngyuán.","vi":"Trong khu dân cư của chúng tôi có một công viên nhỏ.","en":"There is a small park in our residential area."},{"use":"小区 đi với 门口、超市, chỉ vị trí xung quanh","ex":"小区门口新开了一家超市。","py":"Xiǎoqū ménkǒu xīn kāi le yì jiā chāoshì.","vi":"Trước cổng khu dân cư mới mở một siêu thị.","en":"A new supermarket has opened at the entrance of the residential community."}]},"厨房":{"en":"kitchen","exs":[{"use":"làm danh từ chỉ nơi chốn; 在厨房 + động từ","ex":"妈妈正在厨房做晚饭。","py":"Māma zhèngzài chúfáng zuò wǎnfàn.","vi":"Mẹ đang nấu bữa tối trong bếp.","en":"Mom is cooking dinner in the kitchen."},{"use":"厨房 + 里 + 有……: nói về đồ vật trong bếp","ex":"厨房里有很多新鲜的蔬菜。","py":"Chúfáng lǐ yǒu hěn duō xīnxiān de shūcài.","vi":"Trong bếp có rất nhiều rau tươi.","en":"There are a lot of fresh vegetables in the kitchen."},{"use":"làm định ngữ/tân ngữ: 打扫/收拾厨房","ex":"吃完饭以后,我来收拾厨房。","py":"Chīwán fàn yǐhòu, wǒ lái shōushi chúfáng.","vi":"Ăn cơm xong, tôi sẽ dọn dẹp nhà bếp.","en":"After dinner, I'll clean up the kitchen."}]},"总的来说":{"en":"generally speaking; in short; all in all","exs":[{"use":"cụm chèn đầu câu để tổng kết, dùng sau khi phân tích nhiều mặt","ex":"总的来说,这次旅行很愉快。","py":"Zǒng de lái shuō, zhè cì lǚxíng hěn yúkuài.","vi":"Nói chung, chuyến du lịch lần này rất vui.","en":"All in all, this trip was very enjoyable."},{"use":"总的来说 + kết luận; thường đi sau 虽然……但是……","ex":"虽然有一些问题,但总的来说,我们的工作做得不错。","py":"Suīrán yǒu yìxiē wèntí, dàn zǒng de lái shuō, wǒmen de gōngzuò zuò de búcuò.","vi":"Tuy có một vài vấn đề, nhưng nói chung công việc của chúng tôi làm khá tốt.","en":"Although there were some problems, on the whole our work went well."},{"use":"dùng để tóm tắt ý kiến, đánh giá","ex":"总的来说,我觉得这个办法比较好。","py":"Zǒng de lái shuō, wǒ juéde zhège bànfǎ bǐjiào hǎo.","vi":"Tóm lại, tôi thấy cách này khá tốt.","en":"In short, I think this method is better."}]},"号码":{"en":"number (phone, ID, etc.)","exs":[{"use":"làm danh từ; 电话号码 = số điện thoại","ex":"请告诉我你的电话号码。","py":"Qǐng gàosu wǒ nǐ de diànhuà hàomǎ.","vi":"Xin cho tôi biết số điện thoại của bạn.","en":"Please tell me your phone number."},{"use":"号码 chỉ số thứ tự, số hiệu (số áo, số phòng, số xếp hàng)","ex":"你的房间号码是多少?","py":"Nǐ de fángjiān hàomǎ shì duōshao?","vi":"Số phòng của bạn là bao nhiêu?","en":"What is your room number?"},{"use":"号码 làm tân ngữ: 记/写/打错号码","ex":"对不起,我打错号码了。","py":"Duìbuqǐ, wǒ dǎcuò hàomǎ le.","vi":"Xin lỗi, tôi gọi nhầm số rồi.","en":"Sorry, I dialed the wrong number."}]},"路过":{"en":"to pass by; to pass through","exs":[{"use":"路过 + nơi chốn: đi ngang qua đâu","ex":"我每天上班都路过这家咖啡店。","py":"Wǒ měitiān shàngbān dōu lùguò zhè jiā kāfēidiàn.","vi":"Hằng ngày đi làm tôi đều đi ngang qua quán cà phê này.","en":"I pass by this coffee shop every day on my way to work."},{"use":"路过 + 的时候: khi tình cờ đi ngang qua","ex":"昨天路过你家的时候,我看见灯还亮着。","py":"Zuótiān lùguò nǐ jiā de shíhou, wǒ kànjiàn dēng hái liàngzhe.","vi":"Hôm qua khi đi ngang nhà bạn, tôi thấy đèn vẫn sáng.","en":"When I passed your house yesterday, I saw the light was still on."},{"use":"路过 dùng với 顺便 (tiện đường), làm vị ngữ","ex":"我路过超市,顺便买了点儿水果。","py":"Wǒ lùguò chāoshì, shùnbiàn mǎi le diǎnr shuǐguǒ.","vi":"Tôi đi ngang siêu thị, tiện thể mua ít trái cây.","en":"I passed by the supermarket and bought some fruit on the way."}]},"在于":{"en":"to lie in; to rest on; to depend on","exs":[{"use":"A 的关键/问题/区别 + 在于 + B: điểm mấu chốt nằm ở B","ex":"学好汉语的关键在于多听多说。","py":"Xuéhǎo Hànyǔ de guānjiàn zàiyú duō tīng duō shuō.","vi":"Mấu chốt để học giỏi tiếng Trung nằm ở nghe nhiều nói nhiều.","en":"The key to learning Chinese well lies in listening and speaking a lot."},{"use":"在于 giải thích nguyên nhân, bản chất sự việc","ex":"这两个词的不同在于用法。","py":"Zhè liǎng ge cí de bùtóng zàiyú yòngfǎ.","vi":"Điểm khác nhau của hai từ này nằm ở cách dùng.","en":"The difference between these two words lies in how they are used."},{"use":"成功与否在于 + ...: phụ thuộc vào","ex":"一个人能不能成功,在于他是否努力。","py":"Yí ge rén néng bu néng chénggōng, zàiyú tā shìfǒu nǔlì.","vi":"Một người có thành công hay không là ở chỗ họ có nỗ lực hay không.","en":"Whether a person succeeds depends on whether he works hard."}]},"发球":{"en":"to serve (a ball); to kick off","exs":[{"use":"làm động từ ly hợp (发 + 球), dùng trong thể thao như bóng bàn, cầu lông, bóng chuyền","ex":"现在轮到你发球了。","py":"Xiànzài lúndào nǐ fāqiú le.","vi":"Bây giờ đến lượt bạn giao bóng.","en":"It's your turn to serve now."},{"use":"发球 + 得 + adj/ bổ ngữ: nhận xét kỹ thuật giao bóng","ex":"他发球发得又快又准。","py":"Tā fāqiú fā de yòu kuài yòu zhǔn.","vi":"Anh ấy giao bóng vừa nhanh vừa chính xác.","en":"He serves both fast and accurately."},{"use":"发球 + danh từ chỉ người/lượt: 谁先发球","ex":"比赛开始前,他们先猜硬币决定谁发球。","py":"Bǐsài kāishǐ qián, tāmen xiān cāi yìngbì juédìng shéi fāqiú.","vi":"Trước khi trận đấu bắt đầu, họ tung đồng xu để quyết định ai giao bóng.","en":"Before the match started, they flipped a coin to decide who would serve."}]},"大声":{"en":"loudly; in a loud voice","exs":[{"use":"大声 + động từ: làm gì to tiếng","ex":"请大声读一遍这个句子。","py":"Qǐng dàshēng dú yí biàn zhège jùzi.","vi":"Xin hãy đọc to câu này một lần.","en":"Please read this sentence aloud once."},{"use":"别/不要 + 大声 + động từ: nhắc đừng ồn","ex":"图书馆里不要大声说话。","py":"Túshūguǎn lǐ búyào dàshēng shuōhuà.","vi":"Trong thư viện đừng nói to.","en":"Don't talk loudly in the library."},{"use":"大声地 + động từ; dùng miêu tả cảm xúc: cười, hô","ex":"孩子们大声地笑了起来。","py":"Háizimen dàshēng de xiào le qǐlai.","vi":"Bọn trẻ bật cười thật to.","en":"The children burst out laughing loudly."}]},"讲话":{"en":"to speak; to talk; to give a speech; speech","exs":[{"use":"động từ ly hợp (讲 + 话): nói chuyện","ex":"上课的时候请不要讲话。","py":"Shàngkè de shíhou qǐng búyào jiǎnghuà.","vi":"Khi đang học xin đừng nói chuyện.","en":"Please don't talk during class."},{"use":"讲话 chỉ phát biểu trước đám đông","ex":"校长在会上讲话了。","py":"Xiàozhǎng zài huì shàng jiǎnghuà le.","vi":"Hiệu trưởng đã phát biểu trong buổi họp.","en":"The principal gave a speech at the meeting."},{"use":"làm danh từ: bài phát biểu, lời nói","ex":"他的讲话让大家很感动。","py":"Tā de jiǎnghuà ràng dàjiā hěn gǎndòng.","vi":"Bài phát biểu của anh ấy khiến mọi người rất xúc động.","en":"His speech moved everyone deeply."}]},"座位":{"en":"seat; place to sit","exs":[{"use":"làm danh từ; 找/有/占座位","ex":"这里有人吗?我可以坐这个座位吗?","py":"Zhèlǐ yǒu rén ma? Wǒ kěyǐ zuò zhège zuòwèi ma?","vi":"Ở đây có người không? Tôi ngồi chỗ này được không?","en":"Is anyone here? May I sit in this seat?"},{"use":"座位 + 号: số ghế; dùng khi mua vé","ex":"我们的座位在第五排。","py":"Wǒmen de zuòwèi zài dì wǔ pái.","vi":"Chỗ ngồi của chúng tôi ở hàng thứ năm.","en":"Our seats are in the fifth row."},{"use":"给……让座位: nhường chỗ ngồi","ex":"在公共汽车上,他给老人让了座位。","py":"Zài gōnggòng qìchē shàng, tā gěi lǎorén ràng le zuòwèi.","vi":"Trên xe buýt, anh ấy đã nhường chỗ cho người già.","en":"On the bus, he gave his seat to an elderly person."}]},"走动":{"en":"to walk about; to move around; to keep in touch (visit each other)","exs":[{"use":"nghĩa 1: đi lại, di chuyển xung quanh","ex":"飞机还没停稳,请不要走动。","py":"Fēijī hái méi tíngwěn, qǐng búyào zǒudòng.","vi":"Máy bay chưa dừng hẳn, xin đừng đi lại.","en":"The plane hasn't fully stopped; please do not walk around."},{"use":"走动 chỉ vận động nhẹ cho khỏe","ex":"坐久了,应该起来走动走动。","py":"Zuò jiǔ le, yīnggāi qǐlai zǒudòng zǒudòng.","vi":"Ngồi lâu rồi, nên đứng dậy đi lại một chút.","en":"After sitting for a long time, you should get up and move around."},{"use":"nghĩa 2: đi lại thăm hỏi, qua lại (họ hàng, láng giềng)","ex":"我们两家平时经常走动。","py":"Wǒmen liǎng jiā píngshí jīngcháng zǒudòng.","vi":"Hai nhà chúng tôi bình thường hay qua lại thăm nhau.","en":"Our two families often visit each other."}]},"学期":{"en":"semester; school term","exs":[{"use":"làm danh từ; 上/下学期 = học kỳ trước/sau","ex":"这个学期我有六门课。","py":"Zhège xuéqī wǒ yǒu liù mén kè.","vi":"Học kỳ này tôi có sáu môn học.","en":"I have six courses this semester."},{"use":"上学期 / 下学期: học kỳ trước / học kỳ sau","ex":"下学期我打算去中国学习汉语。","py":"Xià xuéqī wǒ dǎsuàn qù Zhōngguó xuéxí Hànyǔ.","vi":"Học kỳ sau tôi định đến Trung Quốc học tiếng Hán.","en":"Next semester I plan to go to China to study Chinese."},{"use":"学期 + 末/初: cuối / đầu học kỳ","ex":"学期末我们要参加考试。","py":"Xuéqī mò wǒmen yào cānjiā kǎoshì.","vi":"Cuối học kỳ chúng tôi phải tham gia kỳ thi.","en":"We have to take exams at the end of the semester."}]},"出生年月":{"en":"date of birth (year and month)","exs":[{"use":"danh từ dùng trong biểu mẫu, hồ sơ: 出生年月 + 日","ex":"请在表格上填写你的出生年月。","py":"Qǐng zài biǎogé shàng tiánxiě nǐ de chūshēng niányuè.","vi":"Xin hãy điền ngày tháng năm sinh của bạn vào bảng.","en":"Please fill in your date of birth on the form."},{"use":"出生年月 + 是 + ...: hỏi/đáp thông tin cá nhân","ex":"我的出生年月是一九九八年五月。","py":"Wǒ de chūshēng niányuè shì yī jiǔ jiǔ bā nián wǔ yuè.","vi":"Năm tháng sinh của tôi là tháng năm năm 1998.","en":"My date of birth is May 1998."},{"use":"出生年月 thường xuất hiện cùng 姓名、性别 trong lý lịch","ex":"简历上要写姓名、性别和出生年月。","py":"Jiǎnlì shàng yào xiě xìngmíng, xìngbié hé chūshēng niányuè.","vi":"Trong sơ yếu lý lịch phải ghi họ tên, giới tính và ngày tháng năm sinh.","en":"A résumé should include your name, gender and date of birth."}]},"联系地址":{"en":"contact address; mailing address","exs":[{"use":"danh từ dùng trong biểu mẫu: 联系地址 + 填写","ex":"请留下您的联系地址。","py":"Qǐng liúxià nín de liánxì dìzhǐ.","vi":"Xin để lại địa chỉ liên hệ của quý vị.","en":"Please leave your contact address."},{"use":"联系地址 đi với 电话 trong thông tin liên lạc","ex":"表格里需要填联系地址和电话。","py":"Biǎogé lǐ xūyào tián liánxì dìzhǐ hé diànhuà.","vi":"Trong biểu mẫu cần điền địa chỉ liên hệ và số điện thoại.","en":"You need to enter a contact address and phone number in the form."},{"use":"联系地址 + 有变化/改了: nói về việc thay đổi","ex":"我搬家了,联系地址已经改了。","py":"Wǒ bānjiā le, liánxì dìzhǐ yǐjīng gǎi le.","vi":"Tôi đã chuyển nhà, địa chỉ liên hệ đã thay đổi.","en":"I've moved, so my contact address has changed."}]},"联系电话":{"en":"contact phone number","exs":[{"use":"danh từ dùng trong biểu mẫu, đơn từ","ex":"这里请写上你的联系电话。","py":"Zhèlǐ qǐng xiěshàng nǐ de liánxì diànhuà.","vi":"Ở đây xin hãy ghi số điện thoại liên hệ của bạn.","en":"Please write your contact phone number here."},{"use":"联系电话 + 是 + số: nêu số điện thoại","ex":"我的联系电话是一三八开头的。","py":"Wǒ de liánxì diànhuà shì yī sān bā kāitóu de.","vi":"Số điện thoại liên hệ của tôi bắt đầu bằng 138.","en":"My contact number starts with 138."},{"use":"联系电话 + 打不通/没人接: nói về trục trặc liên lạc","ex":"这个联系电话打不通,你有别的号码吗?","py":"Zhège liánxì diànhuà dǎ bu tōng, nǐ yǒu bié de hàomǎ ma?","vi":"Số điện thoại liên hệ này gọi không được, bạn có số khác không?","en":"This contact number can't be reached; do you have another number?"}]},"小心":{"en":"careful; cautious; to be careful","exs":[{"use":"小心 + động từ/danh từ: cẩn thận với cái gì (lời nhắc)","ex":"路很滑,小心摔倒。","py":"Lù hěn huá, xiǎoxīn shuāidǎo.","vi":"Đường rất trơn, cẩn thận kẻo ngã.","en":"The road is slippery, be careful not to fall."},{"use":"làm tính từ/vị ngữ: 很小心 / 小心地 + động từ","ex":"他开车非常小心。","py":"Tā kāichē fēicháng xiǎoxīn.","vi":"Anh ấy lái xe rất cẩn thận.","en":"He drives very carefully."},{"use":"小心点儿!dùng như câu cầu khiến; 小心 + 烫/车","ex":"小心点儿,这杯水很烫。","py":"Xiǎoxīn diǎnr, zhè bēi shuǐ hěn tàng.","vi":"Cẩn thận chút, cốc nước này rất nóng.","en":"Be careful, this cup of water is very hot."}]},"申请表":{"en":"application form","exs":[{"use":"làm danh từ; 填写申请表","ex":"请先填写这张申请表。","py":"Qǐng xiān tiánxiě zhè zhāng shēnqǐngbiǎo.","vi":"Xin hãy điền vào đơn đăng ký này trước.","en":"Please fill out this application form first."},{"use":"申请表 + 交给/提交: nộp đơn","ex":"你把申请表交给王老师就可以了。","py":"Nǐ bǎ shēnqǐngbiǎo jiāogěi Wáng lǎoshī jiù kěyǐ le.","vi":"Bạn nộp đơn đăng ký cho thầy Vương là được.","en":"Just hand the application form to Teacher Wang."},{"use":"申请表 + 在哪儿 / 下载: hỏi nơi lấy mẫu đơn","ex":"这个签证的申请表可以在网上下载。","py":"Zhège qiānzhèng de shēnqǐngbiǎo kěyǐ zài wǎngshàng xiàzài.","vi":"Đơn xin visa này có thể tải về trên mạng.","en":"The visa application form can be downloaded online."}]},"道歉":{"en":"to apologize; apology","exs":[{"use":"làm động từ ly hợp (道 + 歉): 向/给 + 人 + 道歉","ex":"我想向你道歉,昨天是我不对。","py":"Wǒ xiǎng xiàng nǐ dàoqiàn, zuótiān shì wǒ bú duì.","vi":"Tôi muốn xin lỗi bạn, hôm qua là tôi sai.","en":"I want to apologize to you; I was wrong yesterday."},{"use":"道歉 + 了: hoàn thành hành động xin lỗi","ex":"他已经道歉了,你就原谅他吧。","py":"Tā yǐjīng dàoqiàn le, nǐ jiù yuánliàng tā ba.","vi":"Anh ấy đã xin lỗi rồi, bạn tha thứ cho anh ấy đi.","en":"He has already apologized, so forgive him."},{"use":"làm danh từ: 一个道歉 / 接受道歉","ex":"我接受你的道歉。","py":"Wǒ jiēshòu nǐ de dàoqiàn.","vi":"Tôi chấp nhận lời xin lỗi của bạn.","en":"I accept your apology."}]},"拿走":{"en":"to take away; to carry off","exs":[{"use":"拿走 + tân ngữ: lấy đi cái gì","ex":"请不要拿走桌子上的书。","py":"Qǐng búyào názǒu zhuōzi shàng de shū.","vi":"Xin đừng lấy sách trên bàn đi.","en":"Please don't take away the books on the table."},{"use":"把 + tân ngữ + 拿走: dùng cấu trúc 把","ex":"你可以把这些旧衣服拿走。","py":"Nǐ kěyǐ bǎ zhèxiē jiù yīfu názǒu.","vi":"Bạn có thể mang số quần áo cũ này đi.","en":"You can take these old clothes away."},{"use":"被 + 人 + 拿走: bị lấy mất","ex":"我的雨伞不知道被谁拿走了。","py":"Wǒ de yǔsǎn bù zhīdào bèi shéi názǒu le.","vi":"Không biết ô của tôi bị ai lấy mất rồi.","en":"I don't know who took my umbrella."}]},"打印":{"en":"to print (with a printer)","exs":[{"use":"打印 + tài liệu: in văn bản","ex":"我想把这份文件打印出来。","py":"Wǒ xiǎng bǎ zhè fèn wénjiàn dǎyìn chūlai.","vi":"Tôi muốn in tài liệu này ra.","en":"I want to print this document out."},{"use":"打印 + 几份: in bao nhiêu bản","ex":"请帮我打印三份简历。","py":"Qǐng bāng wǒ dǎyìn sān fèn jiǎnlì.","vi":"Làm ơn in giúp tôi ba bản sơ yếu lý lịch.","en":"Please print three copies of my résumé for me."},{"use":"打印机 / 在哪儿打印: nơi in ấn","ex":"学校图书馆里可以打印吗?","py":"Xuéxiào túshūguǎn lǐ kěyǐ dǎyìn ma?","vi":"Trong thư viện trường có thể in được không?","en":"Can I print in the school library?"}]},"填表":{"en":"to fill in a form","exs":[{"use":"động từ ly hợp (填 + 表): đi với 请、需要","ex":"办手续之前,先去那边填表。","py":"Bàn shǒuxù zhīqián, xiān qù nàbiān tiánbiǎo.","vi":"Trước khi làm thủ tục, hãy sang bên kia điền đơn trước.","en":"Before doing the procedure, go over there and fill in a form first."},{"use":"填表 + 时/的时候: khi điền đơn","ex":"填表的时候要写清楚你的名字。","py":"Tiánbiǎo de shíhou yào xiě qīngchu nǐ de míngzi.","vi":"Khi điền đơn phải viết rõ tên của bạn.","en":"When filling in the form, write your name clearly."},{"use":"帮 + 人 + 填表: giúp ai điền đơn","ex":"爷爷不会填表,我来帮他填。","py":"Yéye bú huì tiánbiǎo, wǒ lái bāng tā tián.","vi":"Ông không biết điền đơn, để tôi giúp ông điền.","en":"Grandpa doesn't know how to fill in forms, so I'll help him."}]},"别的":{"en":"other; else; something/someone else","exs":[{"use":"làm đại từ: 别的 + (danh từ) = cái khác","ex":"这件太大了,有别的吗?","py":"Zhè jiàn tài dà le, yǒu bié de ma?","vi":"Cái này to quá, có cái khác không?","en":"This one is too big. Do you have another?"},{"use":"还有别的 + ...? hỏi thêm","ex":"除了米饭,你还想吃别的吗?","py":"Chúle mǐfàn, nǐ hái xiǎng chī bié de ma?","vi":"Ngoài cơm ra, bạn còn muốn ăn gì khác không?","en":"Besides rice, do you want to eat anything else?"},{"use":"别的 + danh từ: bổ nghĩa; 没有别的办法 (không còn cách khác)","ex":"现在没有别的办法了,只能等。","py":"Xiànzài méiyǒu bié de bànfǎ le, zhǐ néng děng.","vi":"Bây giờ không còn cách nào khác, chỉ có thể chờ.","en":"There's no other way now; we can only wait."}]},"复印":{"en":"to photocopy","exs":[{"use":"复印 + tài liệu: photo cái gì","ex":"请把护照复印一下。","py":"Qǐng bǎ hùzhào fùyìn yíxià.","vi":"Xin hãy photo hộ chiếu một chút.","en":"Please make a photocopy of your passport."},{"use":"复印 + 几份: photo bao nhiêu bản","ex":"这份材料我要复印两份。","py":"Zhè fèn cáiliào wǒ yào fùyìn liǎng fèn.","vi":"Tài liệu này tôi cần photo hai bản.","en":"I need to make two copies of this material."},{"use":"复印件 / 去哪儿复印: hỏi chỗ photo","ex":"请问,哪里可以复印?","py":"Qǐngwèn, nǎlǐ kěyǐ fùyìn?","vi":"Xin hỏi, chỗ nào có thể photo được?","en":"Excuse me, where can I make photocopies?"}]},"羊肉":{"en":"mutton; lamb","exs":[{"use":"danh từ chỉ thịt; 吃/买/煮羊肉","ex":"我今天想吃羊肉火锅。","py":"Wǒ jīntiān xiǎng chī yángròu huǒguō.","vi":"Hôm nay tôi muốn ăn lẩu thịt cừu.","en":"I want to eat lamb hotpot today."},{"use":"羊肉 + 的 + 味道: nhận xét vị","ex":"这家店的羊肉一点儿也不腥。","py":"Zhè jiā diàn de yángròu yìdiǎnr yě bù xīng.","vi":"Thịt cừu của quán này chẳng hề hôi chút nào.","en":"The lamb at this restaurant doesn't smell gamey at all."},{"use":"羊肉 làm nguyên liệu: 羊肉 + 串/饺子","ex":"新疆的羊肉串很有名。","py":"Xīnjiāng de yángròuchuàn hěn yǒumíng.","vi":"Thịt cừu xiên nướng của Tân Cương rất nổi tiếng.","en":"Xinjiang's lamb skewers are very famous."}]},"饺子":{"en":"jiaozi; dumplings","exs":[{"use":"danh từ; 包/吃饺子: gói / ăn sủi cảo","ex":"春节的时候,我们全家一起包饺子。","py":"Chūnjié de shíhou, wǒmen quánjiā yìqǐ bāo jiǎozi.","vi":"Dịp Tết, cả nhà chúng tôi cùng gói sủi cảo.","en":"During the Spring Festival, our whole family makes dumplings together."},{"use":"量词 + 饺子: 一盘/二十个饺子","ex":"我一次能吃二十个饺子。","py":"Wǒ yí cì néng chī èrshí ge jiǎozi.","vi":"Một lần tôi có thể ăn hai mươi cái sủi cảo.","en":"I can eat twenty dumplings at once."},{"use":"饺子 + 的馅儿: nhân sủi cảo","ex":"你喜欢什么馅儿的饺子?","py":"Nǐ xǐhuan shénme xiànr de jiǎozi?","vi":"Bạn thích sủi cảo nhân gì?","en":"What filling do you like in your dumplings?"}]},"切肉":{"en":"to cut/slice meat","exs":[{"use":"động từ ly hợp (切 + 肉): thái thịt","ex":"妈妈正在厨房切肉。","py":"Māma zhèngzài chúfáng qiēròu.","vi":"Mẹ đang thái thịt trong bếp.","en":"Mom is slicing meat in the kitchen."},{"use":"用 + dụng cụ + 切肉: dùng gì để thái thịt","ex":"你要用这把刀切肉,那把刀切菜。","py":"Nǐ yào yòng zhè bǎ dāo qiēròu, nà bǎ dāo qiē cài.","vi":"Bạn dùng con dao này thái thịt, con kia thái rau.","en":"Use this knife to cut meat and that one to cut vegetables."},{"use":"切肉 + 切成 + dạng: thái thành miếng/sợi","ex":"做这个菜要先把肉切成小片,所以得先切肉。","py":"Zuò zhège cài yào xiān bǎ ròu qiē chéng xiǎo piàn, suǒyǐ děi xiān qiēròu.","vi":"Làm món này phải thái thịt thành lát nhỏ trước, nên cần thái thịt trước.","en":"To make this dish, you must first slice the meat into thin pieces."}]},"脱下来":{"en":"to take off (clothes, shoes); to remove","exs":[{"use":"脱下来 + (衣服/鞋): cởi ra; 下来 là bổ ngữ xu hướng","ex":"进门请把鞋脱下来。","py":"Jìn mén qǐng bǎ xié tuō xiàlai.","vi":"Vào cửa xin hãy cởi giày ra.","en":"Please take off your shoes when you come in."},{"use":"把 + tân ngữ + 脱下来: cấu trúc 把","ex":"天气热了,你把外套脱下来吧。","py":"Tiānqì rè le, nǐ bǎ wàitào tuō xiàlai ba.","vi":"Trời nóng rồi, bạn cởi áo khoác ra đi.","en":"It's hot; take off your coat."},{"use":"脱下来 + rồi làm gì tiếp (洗/挂)","ex":"衣服脏了,脱下来我给你洗洗。","py":"Yīfu zāng le, tuō xiàlai wǒ gěi nǐ xǐxi.","vi":"Quần áo bẩn rồi, cởi ra để tôi giặt cho.","en":"Your clothes are dirty; take them off and I'll wash them for you."}]},"洗洗":{"en":"to wash a bit; to give a quick wash","exs":[{"use":"động từ lặp lại: nghĩa 'làm nhẹ, thử', ngữ khí thoải mái","ex":"吃饭以前先去洗洗手。","py":"Chīfàn yǐqián xiān qù xǐxi shǒu.","vi":"Trước khi ăn hãy đi rửa tay đã.","en":"Go wash your hands before eating."},{"use":"洗洗 + 衣服/水果: giặt/rửa qua","ex":"这些苹果要洗洗再吃。","py":"Zhèxiē píngguǒ yào xǐxi zài chī.","vi":"Mấy quả táo này phải rửa qua rồi mới ăn.","en":"These apples need a quick rinse before eating."},{"use":"洗洗 + 澡/脸 + 睡: dùng trong câu khuyên","ex":"你太累了,洗洗早点儿睡吧。","py":"Nǐ tài lèi le, xǐxi zǎodiǎnr shuì ba.","vi":"Bạn mệt quá rồi, tắm rửa một chút rồi đi ngủ sớm đi.","en":"You're too tired; freshen up and go to bed early."}]},"吃不上":{"en":"unable to get to eat; can't get (a meal)","exs":[{"use":"V + 不 + 上: không kịp / không có điều kiện ăn","ex":"太忙了,中午常常吃不上饭。","py":"Tài máng le, zhōngwǔ chángcháng chībushàng fàn.","vi":"Bận quá, buổi trưa thường không có cơm mà ăn.","en":"I'm so busy that I often can't get lunch."},{"use":"吃不上 + món: không ăn được vì hết / xa","ex":"我住得太远,吃不上妈妈做的菜。","py":"Wǒ zhù de tài yuǎn, chībushàng māma zuò de cài.","vi":"Tôi sống quá xa nên không được ăn món mẹ nấu.","en":"I live too far away to eat my mom's cooking."},{"use":"来晚了就吃不上: giả thiết + hậu quả","ex":"去晚了就吃不上热饺子了。","py":"Qù wǎn le jiù chībushàng rè jiǎozi le.","vi":"Đi muộn là không được ăn sủi cảo nóng đâu.","en":"If you go late, you won't get to eat hot dumplings."}]},"理发店":{"en":"barbershop; hair salon","exs":[{"use":"danh từ chỉ nơi chốn; 去理发店","ex":"我下午要去理发店剪头发。","py":"Wǒ xiàwǔ yào qù lǐfàdiàn jiǎn tóufa.","vi":"Chiều nay tôi phải đến tiệm cắt tóc cắt tóc.","en":"I'm going to the barbershop to get a haircut this afternoon."},{"use":"在理发店 + động từ: làm gì ở tiệm","ex":"她在理发店工作了五年。","py":"Tā zài lǐfàdiàn gōngzuò le wǔ nián.","vi":"Cô ấy làm việc ở tiệm cắt tóc đã năm năm.","en":"She has worked in a hair salon for five years."},{"use":"理发店 + 在……: chỉ vị trí","ex":"学校旁边新开了一家理发店。","py":"Xuéxiào pángbiān xīn kāi le yì jiā lǐfàdiàn.","vi":"Cạnh trường mới mở một tiệm cắt tóc.","en":"A new hair salon has opened next to the school."}]},"包子":{"en":"baozi; steamed stuffed bun","exs":[{"use":"danh từ; 吃/买包子，量词 个","ex":"早饭我吃了两个包子。","py":"Zǎofàn wǒ chī le liǎng ge bāozi.","vi":"Bữa sáng tôi đã ăn hai cái bánh bao.","en":"I had two steamed buns for breakfast."},{"use":"包子 + 的馅儿: 肉包子/菜包子","ex":"这个肉包子又大又香。","py":"Zhège ròu bāozi yòu dà yòu xiāng.","vi":"Cái bánh bao nhân thịt này vừa to vừa thơm.","en":"This meat bun is big and fragrant."},{"use":"包包子: động từ 包 + 包子","ex":"奶奶会包很好吃的包子。","py":"Nǎinai huì bāo hěn hǎochī de bāozi.","vi":"Bà biết gói bánh bao rất ngon.","en":"Grandma can make really delicious steamed buns."}]},"好吃":{"en":"delicious; tasty","exs":[{"use":"làm tính từ vị ngữ: 很/真 + 好吃","ex":"这个菜真好吃!","py":"Zhège cài zhēn hǎochī!","vi":"Món này ngon thật!","en":"This dish is really delicious!"},{"use":"好吃 + 的 + danh từ: bổ nghĩa danh từ","ex":"北京有很多好吃的东西。","py":"Běijīng yǒu hěn duō hǎochī de dōngxi.","vi":"Bắc Kinh có rất nhiều món ngon.","en":"Beijing has lots of delicious food."},{"use":"A 比 B 好吃 / 好吃极了: so sánh và nhấn mạnh","ex":"妈妈做的饺子比饭店的还好吃。","py":"Māma zuò de jiǎozi bǐ fàndiàn de hái hǎochī.","vi":"Sủi cảo mẹ làm còn ngon hơn của nhà hàng.","en":"The dumplings Mom makes are even tastier than the restaurant's."}]},"打招呼":{"en":"to greet; to say hello","exs":[{"use":"động từ ly hợp (打 + 招呼); 跟/向 + 人 + 打招呼","ex":"他看见我,笑着跟我打招呼。","py":"Tā kànjiàn wǒ, xiàozhe gēn wǒ dǎzhāohu.","vi":"Anh ấy thấy tôi liền cười chào tôi.","en":"When he saw me, he smiled and greeted me."},{"use":"替 + 人 + 打招呼: chào hộ ai","ex":"你见到他,替我打招呼。","py":"Nǐ jiàndào tā, tì wǒ dǎzhāohu.","vi":"Bạn gặp anh ấy thì chào hộ tôi một tiếng.","en":"If you see him, say hello for me."},{"use":"打招呼 còn nghĩa báo trước, dặn trước","ex":"要请假的话,先跟老师打招呼。","py":"Yào qǐngjià dehuà, xiān gēn lǎoshī dǎzhāohu.","vi":"Nếu muốn xin nghỉ thì báo trước với thầy cô.","en":"If you want to take leave, tell the teacher first."}]},"看见":{"en":"to see; to catch sight of","exs":[{"use":"看见 + tân ngữ: nhìn thấy (kết quả của 看)","ex":"我在路上看见了一只小狗。","py":"Wǒ zài lùshang kànjiàn le yì zhī xiǎo gǒu.","vi":"Tôi nhìn thấy một chú chó nhỏ trên đường.","en":"I saw a puppy on the road."},{"use":"没看见 / 看不见: phủ định","ex":"你看见我的手机了吗?我没看见。","py":"Nǐ kànjiàn wǒ de shǒujī le ma? Wǒ méi kànjiàn.","vi":"Bạn có thấy điện thoại của tôi không? Tôi không thấy.","en":"Have you seen my phone? I haven't."},{"use":"看见 + 人 + 在 + động từ: thấy ai đang làm gì","ex":"我看见他在教室里写作业。","py":"Wǒ kànjiàn tā zài jiàoshì lǐ xiě zuòyè.","vi":"Tôi thấy anh ấy đang làm bài tập trong lớp.","en":"I saw him doing homework in the classroom."}]},"碰见":{"en":"to run into; to bump into; to meet by chance","exs":[{"use":"碰见 + 人: tình cờ gặp ai","ex":"我昨天在超市碰见了老同学。","py":"Wǒ zuótiān zài chāoshì pèngjiàn le lǎo tóngxué.","vi":"Hôm qua tôi tình cờ gặp bạn học cũ ở siêu thị.","en":"I ran into an old classmate at the supermarket yesterday."},{"use":"碰见 + 的时候: khi tình cờ gặp","ex":"碰见邻居的时候,我们一般会打招呼。","py":"Pèngjiàn línjū de shíhou, wǒmen yìbān huì dǎzhāohu.","vi":"Khi gặp hàng xóm, chúng tôi thường chào hỏi.","en":"When we run into neighbors, we usually say hello."},{"use":"没想到 + 碰见: nhấn mạnh sự bất ngờ","ex":"真没想到会在这里碰见你!","py":"Zhēn méi xiǎngdào huì zài zhèlǐ pèngjiàn nǐ!","vi":"Thật không ngờ lại gặp bạn ở đây!","en":"I never expected to run into you here!"}]},"对不起":{"en":"sorry; I'm sorry; excuse me","exs":[{"use":"câu xin lỗi độc lập: 对不起 + (,) + lý do","ex":"对不起,我来晚了。","py":"Duìbuqǐ, wǒ lái wǎn le.","vi":"Xin lỗi, tôi đến muộn.","en":"Sorry, I'm late."},{"use":"对不起 + 人: có lỗi với ai (làm vị ngữ)","ex":"我觉得很对不起父母。","py":"Wǒ juéde hěn duìbuqǐ fùmǔ.","vi":"Tôi cảm thấy rất có lỗi với bố mẹ.","en":"I feel very sorry toward my parents."},{"use":"đáp: 没关系 / 没事; 对不起 còn dùng để nói lịch sự khi hỏi chen ngang","ex":"对不起,请问洗手间在哪儿?","py":"Duìbuqǐ, qǐngwèn xǐshǒujiān zài nǎr?","vi":"Xin lỗi, cho hỏi nhà vệ sinh ở đâu?","en":"Excuse me, where is the restroom?"}]},"不是故意":{"en":"not on purpose; unintentional","exs":[{"use":"我不是故意的: câu giải thích khi xin lỗi","ex":"对不起,我不是故意的。","py":"Duìbuqǐ, wǒ bú shì gùyì de.","vi":"Xin lỗi, tôi không cố ý.","en":"Sorry, I didn't do it on purpose."},{"use":"不是故意 + động từ: không cố ý làm gì","ex":"我不是故意踩到你的脚的。","py":"Wǒ bú shì gùyì cǎidào nǐ de jiǎo de.","vi":"Tôi không cố ý giẫm vào chân bạn.","en":"I didn't mean to step on your foot."},{"use":"他/她 + 不是故意 + 的: nói giúp người khác","ex":"你别生气,他不是故意的。","py":"Nǐ bié shēngqì, tā bú shì gùyì de.","vi":"Bạn đừng giận, anh ấy không cố ý đâu.","en":"Don't be angry; he didn't do it on purpose."}]},"戴眼镜":{"en":"to wear glasses","exs":[{"use":"động từ + tân ngữ: 戴 + 眼镜","ex":"他每天都戴眼镜。","py":"Tā měitiān dōu dài yǎnjìng.","vi":"Anh ấy ngày nào cũng đeo kính.","en":"He wears glasses every day."},{"use":"需要/要 + 戴眼镜: cần đeo kính","ex":"我看书的时候得戴眼镜。","py":"Wǒ kànshū de shíhou děi dài yǎnjìng.","vi":"Khi đọc sách tôi phải đeo kính.","en":"I have to wear glasses when I read."},{"use":"戴眼镜的 + 人: người đeo kính","ex":"那个戴眼镜的男孩是我的同学。","py":"Nàge dài yǎnjìng de nánhái shì wǒ de tóngxué.","vi":"Cậu bé đeo kính kia là bạn học của tôi.","en":"That boy wearing glasses is my classmate."}]},"看不清楚":{"en":"can't see clearly","exs":[{"use":"V + 不 + 补语 (bổ ngữ khả năng phủ định): không nhìn rõ","ex":"字太小了,我看不清楚。","py":"Zì tài xiǎo le, wǒ kànbuqīngchu.","vi":"Chữ nhỏ quá, tôi nhìn không rõ.","en":"The words are too small; I can't see them clearly."},{"use":"看不清楚 + tân ngữ / 把……看不清楚","ex":"晚上我看不清楚前面的路。","py":"Wǎnshang wǒ kànbuqīngchu qiánmiàn de lù.","vi":"Buổi tối tôi nhìn không rõ con đường phía trước.","en":"At night I can't see the road ahead clearly."},{"use":"因为……所以看不清楚: nêu nguyên nhân","ex":"他没戴眼镜,所以看不清楚黑板。","py":"Tā méi dài yǎnjìng, suǒyǐ kànbuqīngchu hēibǎn.","vi":"Anh ấy không đeo kính nên nhìn không rõ bảng đen.","en":"He isn't wearing glasses, so he can't see the blackboard clearly."}]},"舞蹈":{"en":"dance; to dance","exs":[{"use":"danh từ: môn nghệ thuật múa","ex":"她从小就喜欢舞蹈。","py":"Tā cóngxiǎo jiù xǐhuan wǔdǎo.","vi":"Cô ấy từ nhỏ đã thích múa.","en":"She has loved dance since childhood."},{"use":"舞蹈 + 班/演员/比赛: kết hợp thành cụm danh từ","ex":"我女儿在学舞蹈班。","py":"Wǒ nǚ'ér zài xué wǔdǎo bān.","vi":"Con gái tôi đang học lớp múa.","en":"My daughter is taking a dance class."},{"use":"跳舞蹈 / 舞蹈表演: biểu diễn, chương trình","ex":"晚会上有一个精彩的舞蹈表演。","py":"Wǎnhuì shàng yǒu yí ge jīngcǎi de wǔdǎo biǎoyǎn.","vi":"Trong buổi tiệc tối có một tiết mục múa rất hay.","en":"There was a wonderful dance performance at the evening party."}]},"国籍":{"en":"nationality; citizenship","exs":[{"use":"danh từ dùng trong biểu mẫu, hỏi thông tin","ex":"请问您的国籍是什么?","py":"Qǐngwèn nín de guójí shì shénme?","vi":"Xin hỏi quốc tịch của quý vị là gì?","en":"May I ask what your nationality is?"},{"use":"国籍 + 是 + tên nước","ex":"我的国籍是越南。","py":"Wǒ de guójí shì Yuènán.","vi":"Quốc tịch của tôi là Việt Nam.","en":"My nationality is Vietnamese."},{"use":"不同国籍 / 双重国籍: cụm thường gặp","ex":"我们班有来自不同国籍的学生。","py":"Wǒmen bān yǒu láizì bùtóng guójí de xuésheng.","vi":"Lớp chúng tôi có học sinh đến từ nhiều quốc tịch khác nhau.","en":"Our class has students of different nationalities."}]},"无关":{"en":"unrelated; irrelevant; to have nothing to do with","exs":[{"use":"跟/与 + A + 无关: không liên quan đến A","ex":"这件事跟你无关。","py":"Zhè jiàn shì gēn nǐ wúguān.","vi":"Việc này không liên quan đến bạn.","en":"This matter has nothing to do with you."},{"use":"与 + A + 无关: văn viết, trang trọng hơn","ex":"成绩好坏与年龄无关。","py":"Chéngjì hǎohuài yǔ niánlíng wúguān.","vi":"Thành tích tốt xấu không liên quan đến tuổi tác.","en":"Good or bad grades have nothing to do with age."},{"use":"无关 + 的 + danh từ: không liên quan","ex":"请不要问和工作无关的问题。","py":"Qǐng búyào wèn hé gōngzuò wúguān de wèntí.","vi":"Xin đừng hỏi những câu không liên quan đến công việc.","en":"Please don't ask questions unrelated to work."}]},"能看懂":{"en":"can understand (what one reads/sees)","exs":[{"use":"能 + 看懂: có thể đọc hiểu","ex":"这篇文章我能看懂。","py":"Zhè piān wénzhāng wǒ néng kàndǒng.","vi":"Bài văn này tôi đọc hiểu được.","en":"I can understand this article."},{"use":"你能看懂……吗? câu hỏi","ex":"你能看懂中文电影吗?","py":"Nǐ néng kàndǒng Zhōngwén diànyǐng ma?","vi":"Bạn có thể xem hiểu phim tiếng Trung không?","en":"Can you understand Chinese movies?"},{"use":"不能/还不能 + 看懂: phủ định, mức độ","ex":"这张地图太难了,我不能看懂。","py":"Zhè zhāng dìtú tài nán le, wǒ bù néng kàndǒng.","vi":"Tấm bản đồ này khó quá, tôi không xem hiểu được.","en":"This map is too hard; I can't make sense of it."}]},"没多久":{"en":"not long; before long; soon after","exs":[{"use":"没多久 + 就: chẳng bao lâu thì","ex":"我刚坐下没多久,电话就响了。","py":"Wǒ gāng zuòxià méi duō jiǔ, diànhuà jiù xiǎng le.","vi":"Tôi vừa ngồi xuống chưa lâu thì điện thoại reo.","en":"I had just sat down when the phone rang."},{"use":"来/到了 + 没多久: chưa được bao lâu","ex":"他来这里工作没多久。","py":"Tā lái zhèlǐ gōngzuò méi duō jiǔ.","vi":"Anh ấy đến làm việc ở đây chưa được bao lâu.","en":"He hasn't worked here for very long."},{"use":"过了没多久: chỉ sau một lúc ngắn","ex":"过了没多久,雨就停了。","py":"Guò le méi duō jiǔ, yǔ jiù tíng le.","vi":"Chẳng bao lâu sau, mưa tạnh.","en":"Before long, the rain stopped."}]},"胳膊":{"en":"arm","exs":[{"use":"danh từ chỉ bộ phận cơ thể","ex":"我的右胳膊有点儿疼。","py":"Wǒ de yòu gēbo yǒudiǎnr téng.","vi":"Cánh tay phải của tôi hơi đau.","en":"My right arm hurts a little."},{"use":"胳膊 + 受伤/摔伤","ex":"他从自行车上摔下来,伤了胳膊。","py":"Tā cóng zìxíngchē shàng shuāi xiàlai, shāng le gēbo.","vi":"Anh ấy ngã xe đạp, bị thương ở cánh tay.","en":"He fell off his bike and hurt his arm."},{"use":"抬/伸 + 胳膊: động tác","ex":"请把胳膊抬起来,医生要量血压。","py":"Qǐng bǎ gēbo tái qǐlai, yīshēng yào liáng xuèyā.","vi":"Xin giơ cánh tay lên, bác sĩ cần đo huyết áp.","en":"Please lift your arm; the doctor will take your blood pressure."}]},"抬腿":{"en":"to raise one's leg","exs":[{"use":"động từ + tân ngữ (抬 + 腿): nhấc chân","ex":"请抬腿,我要扫地。","py":"Qǐng táituǐ, wǒ yào sǎodì.","vi":"Xin nhấc chân lên, tôi cần quét nhà.","en":"Please lift your leg; I need to sweep the floor."},{"use":"做运动时的口令: 先抬腿","ex":"做操的时候,先抬腿,再往前走。","py":"Zuòcāo de shíhou, xiān táituǐ, zài wǎng qián zǒu.","vi":"Khi tập thể dục, trước hết nhấc chân rồi bước tới trước.","en":"During exercise, lift your leg first and then step forward."},{"use":"抬腿 + 就 + 走: nghĩa bóng, lập tức đi","ex":"他说完话,抬腿就走了。","py":"Tā shuōwán huà, táituǐ jiù zǒu le.","vi":"Anh ấy nói xong là cất bước đi ngay.","en":"After saying that, he turned and walked off."}]},"风景":{"en":"scenery; landscape; view","exs":[{"use":"danh từ; 风景 + 很美","ex":"这里的风景真美!","py":"Zhèlǐ de fēngjǐng zhēn měi!","vi":"Phong cảnh nơi đây thật đẹp!","en":"The scenery here is really beautiful!"},{"use":"看风景 / 欣赏风景: xem cảnh","ex":"我们在山顶上看风景。","py":"Wǒmen zài shāndǐng shàng kàn fēngjǐng.","vi":"Chúng tôi ngắm cảnh trên đỉnh núi.","en":"We enjoyed the view at the top of the mountain."},{"use":"风景区 / 风景如画: cụm thường gặp","ex":"桂林是一个风景很美的旅游城市。","py":"Guìlín shì yí ge fēngjǐng hěn měi de lǚyóu chéngshì.","vi":"Quế Lâm là một thành phố du lịch có phong cảnh rất đẹp.","en":"Guilin is a tourist city with beautiful scenery."}]},"鲜美":{"en":"delicious; fresh and tasty","exs":[{"use":"tính từ miêu tả vị ngon tươi, thường nói về canh, cá, thịt","ex":"这碗鱼汤味道很鲜美。","py":"Zhè wǎn yútāng wèidào hěn xiānměi.","vi":"Bát canh cá này vị rất tươi ngon.","en":"This bowl of fish soup tastes fresh and delicious."},{"use":"鲜美 + 的 + danh từ","ex":"海边有很多鲜美的海鲜。","py":"Hǎibiān yǒu hěn duō xiānměi de hǎixiān.","vi":"Ở bờ biển có rất nhiều hải sản tươi ngon.","en":"There is a lot of fresh, tasty seafood by the sea."},{"use":"V + 得 + 鲜美: bổ ngữ trạng thái","ex":"这个汤煮得又香又鲜美。","py":"Zhège tāng zhǔ de yòu xiāng yòu xiānměi.","vi":"Món canh này nấu vừa thơm vừa tươi ngon.","en":"This soup is cooked to be both fragrant and delicious."}]},"对话":{"en":"dialogue; conversation; to hold talks","exs":[{"use":"danh từ: bài hội thoại","ex":"老师让我们根据对话回答问题。","py":"Lǎoshī ràng wǒmen gēnjù duìhuà huídá wèntí.","vi":"Thầy giáo bảo chúng tôi dựa vào đoạn hội thoại để trả lời câu hỏi.","en":"The teacher asked us to answer questions based on the dialogue."},{"use":"động từ ly hợp: 和/与 + 人 + 对话","ex":"我想和你对话,谈谈这个问题。","py":"Wǒ xiǎng hé nǐ duìhuà, tántan zhège wèntí.","vi":"Tôi muốn trao đổi với bạn để bàn về vấn đề này.","en":"I'd like to talk with you about this issue."},{"use":"练习对话 / 一段对话: dùng khi luyện nói","ex":"我们两个人来练习一段对话。","py":"Wǒmen liǎng ge rén lái liànxí yí duàn duìhuà.","vi":"Hai chúng ta cùng luyện một đoạn hội thoại.","en":"The two of us will practice a dialogue."}]},"普通话":{"en":"Putonghua; Standard Mandarin Chinese","exs":[{"use":"danh từ: tiếng phổ thông; 说普通话","ex":"他说一口标准的普通话。","py":"Tā shuō yì kǒu biāozhǔn de pǔtōnghuà.","vi":"Anh ấy nói tiếng phổ thông rất chuẩn.","en":"He speaks standard Mandarin."},{"use":"学普通话 / 普通话考试","ex":"我在学习普通话,每天都练习。","py":"Wǒ zài xuéxí pǔtōnghuà, měitiān dōu liànxí.","vi":"Tôi đang học tiếng phổ thông, ngày nào cũng luyện.","en":"I'm learning Mandarin and practice every day."},{"use":"用普通话 + động từ: dùng tiếng phổ thông để làm gì","ex":"请用普通话回答我的问题。","py":"Qǐng yòng pǔtōnghuà huídá wǒ de wèntí.","vi":"Xin dùng tiếng phổ thông trả lời câu hỏi của tôi.","en":"Please answer my question in Mandarin."}]},"旅行":{"en":"to travel; travel; trip","exs":[{"use":"làm động từ: 去……旅行","ex":"暑假我想去云南旅行。","py":"Shǔjià wǒ xiǎng qù Yúnnán lǚxíng.","vi":"Kỳ nghỉ hè tôi muốn đi Vân Nam du lịch.","en":"I want to travel to Yunnan during the summer vacation."},{"use":"làm danh từ/chủ ngữ: 旅行 + 能 + ...","ex":"旅行能丰富我们的经历。","py":"Lǚxíng néng fēngfù wǒmen de jīnglì.","vi":"Du lịch làm phong phú trải nghiệm của chúng ta.","en":"Travel can enrich our experiences."},{"use":"旅行 + 社/计划/日记: kết hợp danh từ","ex":"我们正在制订下个月的旅行计划。","py":"Wǒmen zhèngzài zhìdìng xià ge yuè de lǚxíng jìhuà.","vi":"Chúng tôi đang lập kế hoạch du lịch cho tháng sau.","en":"We are making travel plans for next month."}]},"减压":{"en":"to reduce stress; stress relief","exs":[{"use":"động từ ly hợp (减 + 压): giảm áp lực","ex":"听音乐可以帮助我们减压。","py":"Tīng yīnyuè kěyǐ bāngzhù wǒmen jiǎnyā.","vi":"Nghe nhạc có thể giúp chúng ta giảm căng thẳng.","en":"Listening to music can help us relieve stress."},{"use":"为了 + 减压: nêu mục đích","ex":"为了减压,他每天晚上去跑步。","py":"Wèile jiǎnyā, tā měitiān wǎnshang qù pǎobù.","vi":"Để giảm áp lực, mỗi tối anh ấy đi chạy bộ.","en":"To reduce stress, he goes running every evening."},{"use":"减压 + 的方法: danh từ hóa","ex":"旅行是一个很好的减压方法。","py":"Lǚxíng shì yí ge hěn hǎo de jiǎnyā fāngfǎ.","vi":"Du lịch là một cách giảm áp lực rất tốt.","en":"Traveling is a very good way to relieve stress."}]},"小吃":{"en":"snack; local street food","exs":[{"use":"danh từ: món ăn vặt, đặc sản đường phố","ex":"夜市里有很多好吃的小吃。","py":"Yèshì lǐ yǒu hěn duō hǎochī de xiǎochī.","vi":"Trong chợ đêm có rất nhiều món ăn vặt ngon.","en":"The night market has lots of tasty snacks."},{"use":"地方/特色 + 小吃","ex":"到成都一定要尝尝当地的小吃。","py":"Dào Chéngdū yídìng yào chángchang dāngdì de xiǎochī.","vi":"Đến Thành Đô nhất định phải thử đồ ăn vặt địa phương.","en":"When you get to Chengdu, you must try the local snacks."},{"use":"小吃店 / 小吃街: cụm danh từ","ex":"这条小吃街又热闹又便宜。","py":"Zhè tiáo xiǎochījiē yòu rènao yòu piányi.","vi":"Con phố ẩm thực này vừa nhộn nhịp vừa rẻ.","en":"This snack street is both lively and cheap."}]},"行李":{"en":"luggage; baggage","exs":[{"use":"danh từ không đếm bằng 个 mà dùng 件; 带/拿行李","ex":"我只带了一件行李。","py":"Wǒ zhǐ dài le yí jiàn xíngli.","vi":"Tôi chỉ mang theo một kiện hành lý.","en":"I only brought one piece of luggage."},{"use":"收拾/整理行李: sắp xếp hành lý","ex":"明天要出发了,我还没收拾行李。","py":"Míngtiān yào chūfā le, wǒ hái méi shōushi xíngli.","vi":"Mai là xuất phát rồi, tôi vẫn chưa thu dọn hành lý.","en":"We leave tomorrow and I haven't packed yet."},{"use":"托运行李 / 行李箱: sân bay","ex":"请问,我的行李可以托运吗?","py":"Qǐngwèn, wǒ de xíngli kěyǐ tuōyùn ma?","vi":"Xin hỏi, hành lý của tôi có thể ký gửi không?","en":"Excuse me, can I check my luggage?"}]},"目的地":{"en":"destination","exs":[{"use":"danh từ: 到达/去 + 目的地","ex":"我们终于到达了目的地。","py":"Wǒmen zhōngyú dàodá le mùdìdì.","vi":"Cuối cùng chúng tôi đã đến nơi.","en":"We finally reached our destination."},{"use":"目的地 + 是 + nơi chốn","ex":"这次旅行的目的地是上海。","py":"Zhè cì lǚxíng de mùdìdì shì Shànghǎi.","vi":"Điểm đến của chuyến đi này là Thượng Hải.","en":"The destination of this trip is Shanghai."},{"use":"离/到 + 目的地 + 还有……","ex":"离目的地还有二十公里。","py":"Lí mùdìdì hái yǒu èrshí gōnglǐ.","vi":"Còn cách điểm đến hai mươi cây số nữa.","en":"There are still twenty kilometers to the destination."}]},"出发":{"en":"to set out; to depart; to start off","exs":[{"use":"động từ: xuất phát đi đâu","ex":"我们明天早上六点出发。","py":"Wǒmen míngtiān zǎoshang liù diǎn chūfā.","vi":"Sáng mai sáu giờ chúng tôi xuất phát.","en":"We set off at six tomorrow morning."},{"use":"从 + nơi + 出发: xuất phát từ đâu","ex":"他们从北京出发,坐火车去上海。","py":"Tāmen cóng Běijīng chūfā, zuò huǒchē qù Shànghǎi.","vi":"Họ xuất phát từ Bắc Kinh, đi tàu hỏa đến Thượng Hải.","en":"They set out from Beijing and took the train to Shanghai."},{"use":"出发 + 前: trước khi xuất phát","ex":"出发前,请检查一下你的护照。","py":"Chūfā qián, qǐng jiǎnchá yíxià nǐ de hùzhào.","vi":"Trước khi xuất phát, hãy kiểm tra hộ chiếu của bạn.","en":"Before setting off, please check your passport."},{"use":"出发 + 了/吧: đã / hãy xuất phát","ex":"时间不早了,我们出发吧。","py":"Shíjiān bù zǎo le, wǒmen chūfā ba.","vi":"Không còn sớm nữa, chúng ta xuất phát thôi.","en":"It's getting late, let's get going."}]},"尝一尝":{"en":"to have a taste; to try (food)","exs":[{"use":"động từ lặp V一V: nếm thử một chút","ex":"这个菜很香,你尝一尝。","py":"Zhège cài hěn xiāng, nǐ cháng yì cháng.","vi":"Món này rất thơm, bạn nếm thử xem.","en":"This dish smells great, have a taste."},{"use":"想/要 + 尝一尝: muốn thử","ex":"我想尝一尝你做的饺子。","py":"Wǒ xiǎng cháng yì cháng nǐ zuò de jiǎozi.","vi":"Tôi muốn nếm thử sủi cảo bạn làm.","en":"I'd like to try the dumplings you made."},{"use":"尝一尝 + 味道: thử xem vị thế nào","ex":"你尝一尝,看看味道怎么样。","py":"Nǐ cháng yì cháng, kànkan wèidào zěnmeyàng.","vi":"Bạn nếm thử xem vị thế nào.","en":"Give it a taste and see how it is."},{"use":"让/请 + người + 尝一尝","ex":"来中国旅游,一定要尝一尝北京烤鸭。","py":"Lái Zhōngguó lǚyóu, yídìng yào cháng yì cháng Běijīng kǎoyā.","vi":"Đến Trung Quốc du lịch, nhất định phải nếm thử vịt quay Bắc Kinh.","en":"When you travel in China, you must try Beijing roast duck."}]},"精神百倍":{"en":"full of energy; in high spirits","exs":[{"use":"vị ngữ: tràn đầy năng lượng","ex":"睡了一觉以后,我觉得精神百倍。","py":"Shuì le yí jiào yǐhòu, wǒ juéde jīngshén bǎibèi.","vi":"Sau khi ngủ một giấc, tôi thấy tràn đầy năng lượng.","en":"After a nap, I feel full of energy."},{"use":"V + 得 + 精神百倍: bổ ngữ trạng thái","ex":"听了这个好消息,他高兴得精神百倍。","py":"Tīng le zhège hǎo xiāoxi, tā gāoxìng de jīngshén bǎibèi.","vi":"Nghe tin tốt này, anh ấy vui đến mức đầy sức sống.","en":"Hearing the good news, he was so happy that he brimmed with energy."},{"use":"làm vị ngữ chỉ trạng thái buổi sáng","ex":"早上喝杯咖啡,工作起来精神百倍。","py":"Zǎoshang hē bēi kāfēi, gōngzuò qǐlai jīngshén bǎibèi.","vi":"Sáng uống một ly cà phê, làm việc rất sung sức.","en":"A cup of coffee in the morning makes me work with great energy."},{"use":"làm trạng ngữ: 精神百倍地 + V","ex":"孩子们精神百倍地跑进了教室。","py":"Háizimen jīngshén bǎibèi de pǎojìn le jiàoshì.","vi":"Bọn trẻ hăng hái chạy vào lớp học.","en":"The children ran into the classroom full of energy."}]},"南北":{"en":"north and south; (from) north to south","exs":[{"use":"danh từ: phía nam và phía bắc","ex":"中国南北的天气差别很大。","py":"Zhōngguó nánběi de tiānqì chābié hěn dà.","vi":"Thời tiết Nam Bắc Trung Quốc khác nhau rất nhiều.","en":"The weather differs greatly between northern and southern China."},{"use":"南北 + 方向: hướng nam bắc","ex":"这条路是南北方向的。","py":"Zhè tiáo lù shì nánběi fāngxiàng de.","vi":"Con đường này theo hướng Nam Bắc.","en":"This road runs north to south."},{"use":"南北 + 方言/口味: sự khác biệt Nam Bắc","ex":"南北方的饮食习惯不一样。","py":"Nánběi fāng de yǐnshí xíguàn bù yíyàng.","vi":"Thói quen ăn uống hai miền Nam Bắc không giống nhau.","en":"Eating habits differ between the north and the south."},{"use":"南北 + 两地: hai nơi Nam Bắc","ex":"他的家人分在南北两地,一年只能见一次。","py":"Tā de jiārén fēn zài nánběi liǎng dì, yì nián zhǐ néng jiàn yí cì.","vi":"Người nhà anh ấy ở hai nơi Nam Bắc, một năm chỉ gặp được một lần.","en":"His family is split between the north and south, and they only meet once a year."}]},"火车":{"en":"train","exs":[{"use":"danh từ: tàu hỏa","ex":"我坐火车去上海。","py":"Wǒ zuò huǒchē qù Shànghǎi.","vi":"Tôi đi tàu hỏa đến Thượng Hải.","en":"I'm taking the train to Shanghai."},{"use":"火车站: ga tàu","ex":"火车站离这儿不远,走路十分钟就到了。","py":"Huǒchēzhàn lí zhèr bù yuǎn, zǒulù shí fēnzhōng jiù dào le.","vi":"Ga tàu cách đây không xa, đi bộ mười phút là tới.","en":"The train station isn't far; it's a ten-minute walk."},{"use":"火车 + 票/晚点","ex":"因为下大雪,火车晚点了两个小时。","py":"Yīnwèi xià dàxuě, huǒchē wǎndiǎn le liǎng ge xiǎoshí.","vi":"Vì tuyết rơi dày, tàu hỏa trễ hai tiếng.","en":"Because of heavy snow, the train was two hours late."},{"use":"火车 + 上: ở trên tàu","ex":"火车上的人很多,我没有找到座位。","py":"Huǒchē shang de rén hěn duō, wǒ méiyǒu zhǎodào zuòwèi.","vi":"Trên tàu rất đông người, tôi không tìm được chỗ ngồi.","en":"The train was crowded and I couldn't find a seat."}]},"上海人":{"en":"Shanghainese person; people from Shanghai","exs":[{"use":"danh từ: người Thượng Hải","ex":"他是上海人,但是在北京工作。","py":"Tā shì Shànghǎirén, dànshì zài Běijīng gōngzuò.","vi":"Anh ấy là người Thượng Hải nhưng làm việc ở Bắc Kinh.","en":"He's from Shanghai but works in Beijing."},{"use":"上海人 + 的 + danh từ: đặc điểm","ex":"上海人的生活节奏比较快。","py":"Shànghǎirén de shēnghuó jiézòu bǐjiào kuài.","vi":"Nhịp sống của người Thượng Hải khá nhanh.","en":"The pace of life among Shanghainese is quite fast."},{"use":"做 / 当 + 上海人","ex":"我的邻居是一位热情的上海人。","py":"Wǒ de línjū shì yí wèi rèqíng de Shànghǎirén.","vi":"Hàng xóm của tôi là một người Thượng Hải nhiệt tình.","en":"My neighbor is a warm-hearted Shanghainese."}]},"上海话":{"en":"Shanghainese dialect","exs":[{"use":"danh từ: tiếng địa phương Thượng Hải","ex":"我听不懂上海话。","py":"Wǒ tīng bu dǒng Shànghǎihuà.","vi":"Tôi nghe không hiểu tiếng Thượng Hải.","en":"I can't understand Shanghainese."},{"use":"会 + 说 + 上海话","ex":"我朋友会说上海话,也会说普通话。","py":"Wǒ péngyou huì shuō Shànghǎihuà, yě huì shuō pǔtōnghuà.","vi":"Bạn tôi biết nói tiếng Thượng Hải và cả tiếng phổ thông.","en":"My friend speaks both Shanghainese and Mandarin."},{"use":"学 + 上海话","ex":"奶奶用上海话给我讲了一个故事。","py":"Nǎinai yòng Shànghǎihuà gěi wǒ jiǎng le yí ge gùshi.","vi":"Bà dùng tiếng Thượng Hải kể cho tôi một câu chuyện.","en":"Grandma told me a story in Shanghainese."}]},"听起来":{"en":"to sound (like); it sounds as if","exs":[{"use":"听起来 + adj: nghe có vẻ","ex":"这个计划听起来不错。","py":"Zhège jìhuà tīng qǐlai búcuò.","vi":"Kế hoạch này nghe có vẻ không tồi.","en":"This plan sounds good."},{"use":"听起来 + 像: nghe giống như","ex":"他的声音听起来像个孩子。","py":"Tā de shēngyīn tīng qǐlai xiàng ge háizi.","vi":"Giọng anh ấy nghe như giọng trẻ con.","en":"His voice sounds like a child's."},{"use":"听起来 + 好像: nghe có vẻ như","ex":"这句话听起来有点儿奇怪。","py":"Zhè jù huà tīng qǐlai yǒudiǎnr qíguài.","vi":"Câu này nghe hơi kỳ lạ.","en":"That sentence sounds a bit strange."},{"use":"Câu 听起来…: nhận xét về điều vừa nghe","ex":"你说的听起来很有意思,我也想去。","py":"Nǐ shuō de tīng qǐlai hěn yǒu yìsi, wǒ yě xiǎng qù.","vi":"Điều bạn nói nghe rất thú vị, tôi cũng muốn đi.","en":"What you said sounds interesting; I want to go too."}]},"外语":{"en":"foreign language","exs":[{"use":"danh từ: ngoại ngữ","ex":"你会说几种外语?","py":"Nǐ huì shuō jǐ zhǒng wàiyǔ?","vi":"Bạn biết nói mấy ngoại ngữ?","en":"How many foreign languages do you speak?"},{"use":"学 + 外语","ex":"学外语需要每天练习。","py":"Xué wàiyǔ xūyào měitiān liànxí.","vi":"Học ngoại ngữ cần luyện tập mỗi ngày.","en":"Learning a foreign language requires daily practice."},{"use":"外语 + 系/老师/水平","ex":"她在大学教外语,水平很高。","py":"Tā zài dàxué jiāo wàiyǔ, shuǐpíng hěn gāo.","vi":"Cô ấy dạy ngoại ngữ ở đại học, trình độ rất cao.","en":"She teaches foreign languages at a university and is highly skilled."}]},"收拾":{"en":"to tidy up; to pack; to put in order","exs":[{"use":"động từ: dọn dẹp (phòng, bàn)","ex":"周末我在家收拾房间。","py":"Zhōumò wǒ zài jiā shōushi fángjiān.","vi":"Cuối tuần tôi ở nhà dọn dẹp phòng.","en":"On the weekend I tidy up my room at home."},{"use":"收拾 + 行李: thu xếp hành lý","ex":"你收拾好行李了吗?明天要出发了。","py":"Nǐ shōushi hǎo xíngli le ma? Míngtiān yào chūfā le.","vi":"Bạn thu xếp xong hành lý chưa? Mai phải đi rồi.","en":"Have you finished packing? We leave tomorrow."},{"use":"收拾 + 碗筷/桌子","ex":"吃完饭,他帮妈妈收拾桌子。","py":"Chī wán fàn, tā bāng māma shōushi zhuōzi.","vi":"Ăn cơm xong, anh ấy giúp mẹ dọn bàn.","en":"After the meal, he helped Mom clear the table."},{"use":"收拾 (khẩu ngữ): trị, dạy cho một bài học","ex":"你再不听话,我就要收拾你了。","py":"Nǐ zài bù tīnghuà, wǒ jiù yào shōushi nǐ le.","vi":"Con mà còn không nghe lời, mẹ sẽ trị con đấy.","en":"If you keep misbehaving, I'll sort you out."}]},"说起":{"en":"to speak of; to mention; when it comes to","exs":[{"use":"说起 + 来: nói đến thì...","ex":"说起北京,我就想到烤鸭。","py":"Shuōqǐ Běijīng, wǒ jiù xiǎngdào kǎoyā.","vi":"Nhắc đến Bắc Kinh là tôi nghĩ ngay đến vịt quay.","en":"Speaking of Beijing, I think of roast duck right away."},{"use":"说起 + 来 + ...","ex":"说起来容易,做起来难。","py":"Shuō qǐlai róngyì, zuò qǐlai nán.","vi":"Nói thì dễ, làm mới khó.","en":"Easier said than done."},{"use":"提起话头: 说起 + chủ đề","ex":"他说起小时候的事,笑了起来。","py":"Tā shuōqǐ xiǎoshíhou de shì, xiào le qǐlai.","vi":"Anh ấy nhắc đến chuyện hồi nhỏ rồi bật cười.","en":"He started talking about his childhood and laughed."},{"use":"别 / 不要 + 说起","ex":"别在她面前说起这件事。","py":"Bié zài tā miànqián shuōqǐ zhè jiàn shì.","vi":"Đừng nhắc chuyện này trước mặt cô ấy.","en":"Don't bring this up in front of her."}]},"全国":{"en":"the whole country; nationwide","exs":[{"use":"danh từ: cả nước","ex":"这个比赛吸引了全国的学生。","py":"Zhège bǐsài xīyǐn le quánguó de xuésheng.","vi":"Cuộc thi này thu hút học sinh cả nước.","en":"This contest attracted students from across the country."},{"use":"全国 + 各地","ex":"全国各地的人都来看这场表演。","py":"Quánguó gèdì de rén dōu lái kàn zhè chǎng biǎoyǎn.","vi":"Người từ khắp nơi trên cả nước đến xem buổi biểu diễn này.","en":"People from all over the country came to see the show."},{"use":"全国 + 第一/最","ex":"这家公司的产品在全国都很有名。","py":"Zhè jiā gōngsī de chǎnpǐn zài quánguó dōu hěn yǒumíng.","vi":"Sản phẩm của công ty này nổi tiếng khắp cả nước.","en":"This company's products are famous nationwide."}]},"饭馆儿":{"en":"restaurant; eatery","exs":[{"use":"danh từ: quán ăn (đuôi 儿 kiểu Bắc Kinh)","ex":"附近有一家不错的饭馆儿。","py":"Fùjìn yǒu yì jiā búcuò de fànguǎnr.","vi":"Gần đây có một quán ăn khá ngon.","en":"There's a nice restaurant nearby."},{"use":"去 + 饭馆儿 + 吃饭","ex":"今天我不想做饭,我们去饭馆儿吃吧。","py":"Jīntiān wǒ bù xiǎng zuòfàn, wǒmen qù fànguǎnr chī ba.","vi":"Hôm nay tôi không muốn nấu, mình ra quán ăn đi.","en":"I don't feel like cooking today; let's eat out."},{"use":"开 + 饭馆儿: mở quán","ex":"他在学校旁边开了一家小饭馆儿。","py":"Tā zài xuéxiào pángbiān kāi le yì jiā xiǎo fànguǎnr.","vi":"Anh ấy mở một quán ăn nhỏ cạnh trường.","en":"He opened a small restaurant next to the school."}]},"加油":{"en":"to refuel; to fill up with gas; (fig.) to cheer on, to keep it up","exs":[{"use":"nghĩa 1: đổ xăng, đổ dầu","ex":"车快没油了,我们得去加油。","py":"Chē kuài méi yóu le, wǒmen děi qù jiāyóu.","vi":"Xe sắp hết xăng rồi, chúng ta phải đi đổ xăng.","en":"The car's almost out of gas; we need to fill up."},{"use":"nghĩa 2: cổ vũ, cố lên","ex":"明天就要考试了,加油!","py":"Míngtiān jiù yào kǎoshì le, jiāyóu!","vi":"Mai thi rồi, cố lên!","en":"The exam is tomorrow, you can do it!"},{"use":"nghĩa 2: 为…加油","ex":"大家都在为中国队加油。","py":"Dàjiā dōu zài wèi Zhōngguó duì jiāyóu.","vi":"Mọi người đều đang cổ vũ cho đội Trung Quốc.","en":"Everyone is cheering for the Chinese team."},{"use":"nghĩa 2: 加油 + V: nỗ lực hơn","ex":"你要加油学习,别放弃。","py":"Nǐ yào jiāyóu xuéxí, bié fàngqì.","vi":"Bạn phải cố gắng học, đừng bỏ cuộc.","en":"You have to keep working hard; don't give up."}]},"加油站":{"en":"gas station; petrol station","exs":[{"use":"danh từ: trạm xăng","ex":"前面有一个加油站。","py":"Qiánmiàn yǒu yí ge jiāyóuzhàn.","vi":"Phía trước có một trạm xăng.","en":"There's a gas station up ahead."},{"use":"去 + 加油站 + 加油","ex":"我们先去加油站加油,再上高速公路。","py":"Wǒmen xiān qù jiāyóuzhàn jiāyóu, zài shàng gāosùgōnglù.","vi":"Chúng ta đến trạm xăng đổ xăng trước, rồi mới lên cao tốc.","en":"Let's fill up at the gas station first, then get on the highway."},{"use":"hỏi đường: 加油站 + 在哪儿","ex":"请问,附近的加油站在哪儿?","py":"Qǐngwèn, fùjìn de jiāyóuzhàn zài nǎr?","vi":"Xin hỏi, trạm xăng gần đây ở đâu?","en":"Excuse me, where is the nearest gas station?"}]},"小张":{"en":"Xiao Zhang (a nickname for someone surnamed Zhang)","exs":[{"use":"danh từ riêng: gọi thân mật người họ Trương","ex":"小张,你的电话响了。","py":"Xiǎo Zhāng, nǐ de diànhuà xiǎng le.","vi":"Tiểu Trương, điện thoại của bạn reo kìa.","en":"Xiao Zhang, your phone is ringing."},{"use":"小 + họ: cách gọi đồng nghiệp trẻ hơn","ex":"小张是我们公司最年轻的经理。","py":"Xiǎo Zhāng shì wǒmen gōngsī zuì niánqīng de jīnglǐ.","vi":"Tiểu Trương là giám đốc trẻ nhất của công ty chúng tôi.","en":"Xiao Zhang is the youngest manager at our company."},{"use":"làm chủ ngữ / tân ngữ","ex":"我昨天在超市遇到了小张。","py":"Wǒ zuótiān zài chāoshì yùdào le Xiǎo Zhāng.","vi":"Hôm qua tôi gặp Tiểu Trương ở siêu thị.","en":"I ran into Xiao Zhang at the supermarket yesterday."}]},"长江大桥":{"en":"Yangtze River Bridge","exs":[{"use":"danh từ riêng: cầu bắc qua sông Trường Giang","ex":"南京长江大桥非常有名。","py":"Nánjīng Chángjiāng dàqiáo fēicháng yǒumíng.","vi":"Cầu Trường Giang Nam Kinh rất nổi tiếng.","en":"The Nanjing Yangtze River Bridge is very famous."},{"use":"过 + 长江大桥: đi qua cầu","ex":"汽车慢慢地开过了长江大桥。","py":"Qìchē mànmàn de kāi guò le Chángjiāng dàqiáo.","vi":"Chiếc xe chầm chậm chạy qua cầu Trường Giang.","en":"The car slowly drove across the Yangtze River Bridge."},{"use":"在 + 长江大桥 + 上","ex":"晚上我们在长江大桥上看风景。","py":"Wǎnshang wǒmen zài Chángjiāng dàqiáo shang kàn fēngjǐng.","vi":"Buổi tối chúng tôi ngắm cảnh trên cầu Trường Giang.","en":"In the evening we enjoyed the view from the Yangtze River Bridge."}]},"往右":{"en":"to the right","exs":[{"use":"往右 + V: đi/rẽ sang phải","ex":"到了路口,请往右拐。","py":"Dào le lùkǒu, qǐng wǎng yòu guǎi.","vi":"Đến ngã tư, xin rẽ phải.","en":"At the intersection, please turn right."},{"use":"chỉ đường: 往右 + 走","ex":"往右走五百米,就是银行。","py":"Wǎng yòu zǒu wǔbǎi mǐ, jiù shì yínháng.","vi":"Đi sang phải năm trăm mét là ngân hàng.","en":"Go right for five hundred meters and you'll reach the bank."},{"use":"往右 + 看/边: nhìn / bên phải","ex":"你往右看,那座白色的楼就是我家。","py":"Nǐ wǎng yòu kàn, nà zuò báisè de lóu jiù shì wǒ jiā.","vi":"Bạn nhìn sang phải, tòa nhà màu trắng kia là nhà tôi.","en":"Look to the right; that white building is my home."}]},"航班":{"en":"scheduled flight; flight number","exs":[{"use":"danh từ: chuyến bay","ex":"你坐哪个航班去北京?","py":"Nǐ zuò nǎge hángbān qù Běijīng?","vi":"Bạn đi chuyến bay nào đến Bắc Kinh?","en":"Which flight are you taking to Beijing?"},{"use":"航班 + 推迟/取消","ex":"因为大雾,这个航班被推迟了。","py":"Yīnwèi dàwù, zhège hángbān bèi tuīchí le.","vi":"Vì sương mù dày, chuyến bay này bị hoãn.","en":"This flight was delayed because of heavy fog."},{"use":"查 / 订 + 航班","ex":"我在网上查了一下明天的航班。","py":"Wǒ zài wǎngshàng chá le yíxià míngtiān de hángbān.","vi":"Tôi đã tra các chuyến bay ngày mai trên mạng.","en":"I looked up tomorrow's flights online."}]},"几点":{"en":"what time","exs":[{"use":"hỏi giờ: 现在几点?","ex":"现在几点了?","py":"Xiànzài jǐ diǎn le?","vi":"Bây giờ mấy giờ rồi?","en":"What time is it now?"},{"use":"几点 + V: hỏi thời điểm làm việc","ex":"你明天几点起床?","py":"Nǐ míngtiān jǐ diǎn qǐchuáng?","vi":"Ngày mai bạn mấy giờ dậy?","en":"What time will you get up tomorrow?"},{"use":"几点 + 到/开始","ex":"请问,电影几点开始?","py":"Qǐngwèn, diànyǐng jǐ diǎn kāishǐ?","vi":"Xin hỏi, phim mấy giờ bắt đầu?","en":"Excuse me, what time does the movie start?"},{"use":"几点 + 的 + danh từ","ex":"你订的是几点的票?","py":"Nǐ dìng de shì jǐ diǎn de piào?","vi":"Bạn đặt vé chuyến mấy giờ?","en":"What time is the ticket you booked for?"}]},"推迟":{"en":"to postpone; to delay; to put off","exs":[{"use":"động từ: hoãn lại","ex":"因为下雨,比赛推迟了。","py":"Yīnwèi xiàyǔ, bǐsài tuīchí le.","vi":"Vì trời mưa, trận đấu bị hoãn.","en":"The match was postponed because of the rain."},{"use":"推迟 + 到 + thời gian","ex":"我们把会议推迟到下周一。","py":"Wǒmen bǎ huìyì tuīchí dào xià zhōuyī.","vi":"Chúng tôi hoãn cuộc họp sang thứ Hai tuần sau.","en":"We postponed the meeting until next Monday."},{"use":"推迟 + 时间 + 的 + V (kéo dài thêm)","ex":"飞机推迟了一个小时起飞。","py":"Fēijī tuīchí le yí ge xiǎoshí qǐfēi.","vi":"Máy bay cất cánh trễ một tiếng.","en":"The plane's takeoff was delayed by an hour."}]},"九点半":{"en":"half past nine; 9:30","exs":[{"use":"danh từ chỉ giờ: chín rưỡi","ex":"会议九点半开始。","py":"Huìyì jiǔ diǎn bàn kāishǐ.","vi":"Cuộc họp bắt đầu lúc chín rưỡi.","en":"The meeting starts at 9:30."},{"use":"九点半 + 以前/左右","ex":"请你九点半以前到机场。","py":"Qǐng nǐ jiǔ diǎn bàn yǐqián dào jīchǎng.","vi":"Xin bạn đến sân bay trước chín rưỡi.","en":"Please get to the airport before 9:30."},{"use":"每天 + 九点半 + V","ex":"孩子每天晚上九点半睡觉。","py":"Háizi měitiān wǎnshang jiǔ diǎn bàn shuìjiào.","vi":"Con tôi mỗi tối chín rưỡi đi ngủ.","en":"My child goes to bed at 9:30 every night."}]},"五百米":{"en":"five hundred meters","exs":[{"use":"số từ + lượng từ: khoảng cách","ex":"学校离地铁站只有五百米。","py":"Xuéxiào lí dìtiězhàn zhǐyǒu wǔbǎi mǐ.","vi":"Trường chỉ cách ga tàu điện ngầm năm trăm mét.","en":"The school is only 500 meters from the subway station."},{"use":"chỉ đường: 再走 + 五百米","ex":"再往前走五百米,你就能看到那家医院。","py":"Zài wǎng qián zǒu wǔbǎi mǐ, nǐ jiù néng kàndào nà jiā yīyuàn.","vi":"Đi thêm năm trăm mét nữa là bạn sẽ thấy bệnh viện đó.","en":"Walk another 500 meters and you'll see the hospital."},{"use":"五百米 + 以内/远","ex":"这附近五百米以内有两个超市。","py":"Zhè fùjìn wǔbǎi mǐ yǐnèi yǒu liǎng ge chāoshì.","vi":"Trong phạm vi năm trăm mét quanh đây có hai siêu thị.","en":"There are two supermarkets within 500 meters of here."}]},"高速公路":{"en":"expressway; highway; freeway","exs":[{"use":"danh từ: đường cao tốc","ex":"这条高速公路很宽。","py":"Zhè tiáo gāosù gōnglù hěn kuān.","vi":"Đường cao tốc này rất rộng.","en":"This expressway is very wide."},{"use":"上 / 下 + 高速公路","ex":"我们开车上高速公路,三个小时就到了。","py":"Wǒmen kāichē shàng gāosù gōnglù, sān ge xiǎoshí jiù dào le.","vi":"Chúng tôi lái xe lên cao tốc, ba tiếng là tới.","en":"We drove onto the expressway and arrived in three hours."},{"use":"高速公路 + 收费/堵车","ex":"节假日的高速公路上常常堵车。","py":"Jiéjiàrì de gāosù gōnglù shang chángcháng dǔchē.","vi":"Vào ngày lễ, trên cao tốc thường kẹt xe.","en":"There are often traffic jams on the expressway during holidays."}]},"进去":{"en":"to go in; to enter","exs":[{"use":"động từ xu hướng: đi vào (người nói ở ngoài)","ex":"门开着,你进去吧。","py":"Mén kāi zhe, nǐ jìnqù ba.","vi":"Cửa đang mở, bạn vào đi.","en":"The door is open; go on in."},{"use":"V + 进去: bổ ngữ xu hướng","ex":"他把书放进去了。","py":"Tā bǎ shū fàng jìnqù le.","vi":"Anh ấy đã bỏ sách vào rồi.","en":"He put the book in."},{"use":"进去 + 了/吗: hỏi đã vào chưa","ex":"他已经进去二十分钟了,还没出来。","py":"Tā yǐjīng jìnqù èrshí fēnzhōng le, hái méi chūlái.","vi":"Anh ấy vào trong hai mươi phút rồi mà vẫn chưa ra.","en":"He went in twenty minutes ago and still hasn't come out."},{"use":"进去 + 看看/坐坐","ex":"外面太冷了,我们进去坐一会儿吧。","py":"Wàimiàn tài lěng le, wǒmen jìnqù zuò yíhuìr ba.","vi":"Bên ngoài lạnh quá, chúng ta vào trong ngồi một lát nhé.","en":"It's too cold outside; let's go in and sit for a while."}]},"登机牌":{"en":"boarding pass","exs":[{"use":"danh từ: thẻ lên máy bay","ex":"请出示您的登机牌和护照。","py":"Qǐng chūshì nín de dēngjīpái hé hùzhào.","vi":"Xin xuất trình thẻ lên máy bay và hộ chiếu.","en":"Please show your boarding pass and passport."},{"use":"换 / 打印 + 登机牌","ex":"我在机场的机器上打印了登机牌。","py":"Wǒ zài jīchǎng de jīqì shang dǎyìn le dēngjīpái.","vi":"Tôi đã in thẻ lên máy bay ở máy tại sân bay.","en":"I printed my boarding pass at the machine in the airport."},{"use":"登机牌 + 丢了","ex":"我的登机牌找不到了,怎么办?","py":"Wǒ de dēngjīpái zhǎo bu dào le, zěnme bàn?","vi":"Tôi không tìm thấy thẻ lên máy bay, phải làm sao?","en":"I can't find my boarding pass; what should I do?"}]},"首都机场":{"en":"Capital Airport (Beijing Capital International Airport)","exs":[{"use":"danh từ riêng: sân bay Thủ đô Bắc Kinh","ex":"我们的飞机在首都机场降落。","py":"Wǒmen de fēijī zài Shǒudū jīchǎng jiàngluò.","vi":"Máy bay của chúng tôi hạ cánh ở sân bay Thủ đô.","en":"Our plane landed at Capital Airport."},{"use":"去 / 到 + 首都机场","ex":"去首都机场坐地铁最方便。","py":"Qù Shǒudū jīchǎng zuò dìtiě zuì fāngbiàn.","vi":"Đi sân bay Thủ đô thì đi tàu điện ngầm tiện nhất.","en":"The subway is the most convenient way to Capital Airport."},{"use":"首都机场 + 很大/人多","ex":"首都机场很大,你要早点儿到。","py":"Shǒudū jīchǎng hěn dà, nǐ yào zǎodiǎnr dào.","vi":"Sân bay Thủ đô rất lớn, bạn nên đến sớm một chút.","en":"Capital Airport is huge, so get there early."}]},"放寒假":{"en":"to have winter vacation","exs":[{"use":"động từ (cụm ly hợp): nghỉ đông","ex":"我们学校下个星期放寒假。","py":"Wǒmen xuéxiào xià ge xīngqī fàng hánjià.","vi":"Trường chúng tôi tuần sau nghỉ đông.","en":"Our school's winter break starts next week."},{"use":"放寒假 + 以后: sau khi nghỉ đông","ex":"放寒假以后,我要回老家看爷爷奶奶。","py":"Fàng hánjià yǐhòu, wǒ yào huí lǎojiā kàn yéye nǎinai.","vi":"Sau khi nghỉ đông, tôi sẽ về quê thăm ông bà.","en":"After winter vacation begins, I'll go home to see my grandparents."},{"use":"hỏi: 什么时候放寒假?","ex":"你们什么时候放寒假?","py":"Nǐmen shénme shíhou fàng hánjià?","vi":"Khi nào các bạn nghỉ đông?","en":"When does your winter vacation start?"}]},"到时候":{"en":"by then; when the time comes","exs":[{"use":"trạng ngữ thời gian: đến lúc đó","ex":"你先别担心,到时候再说吧。","py":"Nǐ xiān bié dānxīn, dào shíhou zài shuō ba.","vi":"Bạn đừng lo trước, đến lúc đó rồi tính.","en":"Don't worry yet; we'll deal with it when the time comes."},{"use":"到时候 + 我们/你 + V","ex":"下个月我们去旅行,到时候一起玩儿。","py":"Xià ge yuè wǒmen qù lǚxíng, dào shíhou yìqǐ wánr.","vi":"Tháng sau chúng tôi đi du lịch, đến lúc đó cùng đi chơi.","en":"We're traveling next month; we'll have fun together then."},{"use":"到时候 + 记得/别忘了","ex":"明天的会很重要,到时候别迟到。","py":"Míngtiān de huì hěn zhòngyào, dào shíhou bié chídào.","vi":"Cuộc họp ngày mai rất quan trọng, đến lúc đó đừng đến muộn.","en":"Tomorrow's meeting is important; don't be late when the time comes."}]},"可怜":{"en":"pitiful; poor; to pity","exs":[{"use":"tính từ: đáng thương","ex":"那只小狗看起来很可怜。","py":"Nà zhī xiǎogǒu kàn qǐlai hěn kělián.","vi":"Chú chó con đó trông rất đáng thương.","en":"That little dog looks pitiful."},{"use":"động từ: thương xót","ex":"大家都很可怜这个没有家的孩子。","py":"Dàjiā dōu hěn kělián zhège méiyǒu jiā de háizi.","vi":"Mọi người đều thương đứa trẻ không có nhà này.","en":"Everyone felt sorry for the homeless child."},{"use":"可怜 + 的 + danh từ","ex":"他是一个可怜的老人,一个人生活。","py":"Tā shì yí ge kělián de lǎorén, yí ge rén shēnghuó.","vi":"Ông ấy là một cụ già đáng thương, sống một mình.","en":"He is a poor old man who lives alone."},{"use":"程度: 少得可怜 (ít đến đáng thương)","ex":"他每个月的工资少得可怜。","py":"Tā měi ge yuè de gōngzī shǎo de kělián.","vi":"Lương mỗi tháng của anh ấy ít đến đáng thương.","en":"His monthly salary is pitifully small."}]},"广西":{"en":"Guangxi (autonomous region in southern China)","exs":[{"use":"danh từ riêng: Quảng Tây","ex":"广西的风景非常美。","py":"Guǎngxī de fēngjǐng fēicháng měi.","vi":"Phong cảnh Quảng Tây vô cùng đẹp.","en":"The scenery in Guangxi is very beautiful."},{"use":"去 + 广西 + 旅游","ex":"今年夏天我想去广西旅游。","py":"Jīnnián xiàtiān wǒ xiǎng qù Guǎngxī lǚyóu.","vi":"Mùa hè năm nay tôi muốn đi du lịch Quảng Tây.","en":"This summer I want to travel to Guangxi."},{"use":"广西 + 人/菜","ex":"我的同学是广西人,他很会做菜。","py":"Wǒ de tóngxué shì Guǎngxī rén, tā hěn huì zuòcài.","vi":"Bạn học của tôi là người Quảng Tây, cậu ấy nấu ăn rất giỏi.","en":"My classmate is from Guangxi and is a great cook."}]},"一趟":{"en":"a trip; one round trip","exs":[{"use":"lượng từ cho chuyến đi: 去一趟","ex":"周末我想回家一趟。","py":"Zhōumò wǒ xiǎng huí jiā yí tàng.","vi":"Cuối tuần tôi muốn về nhà một chuyến.","en":"I want to go home for a visit this weekend."},{"use":"跑一趟 / 走一趟: đi một chuyến","ex":"你能帮我去超市跑一趟吗?","py":"Nǐ néng bāng wǒ qù chāoshì pǎo yí tàng ma?","vi":"Bạn có thể giúp tôi chạy ra siêu thị một chuyến không?","en":"Could you make a trip to the supermarket for me?"},{"use":"一趟 + 车/航班: một chuyến xe","ex":"这一趟火车要开十个小时。","py":"Zhè yí tàng huǒchē yào kāi shí ge xiǎoshí.","vi":"Chuyến tàu này chạy mất mười tiếng.","en":"This train trip takes ten hours."}]},"水果":{"en":"fruit","exs":[{"use":"danh từ: trái cây","ex":"我每天都吃很多水果。","py":"Wǒ měitiān dōu chī hěn duō shuǐguǒ.","vi":"Mỗi ngày tôi đều ăn nhiều trái cây.","en":"I eat a lot of fruit every day."},{"use":"买 + 水果","ex":"妈妈去市场买了一些新鲜的水果。","py":"Māma qù shìchǎng mǎi le yìxiē xīnxiān de shuǐguǒ.","vi":"Mẹ ra chợ mua một ít trái cây tươi.","en":"Mom went to the market and bought some fresh fruit."},{"use":"水果 + 店/沙拉/茶","ex":"我最喜欢的水果是西瓜。","py":"Wǒ zuì xǐhuan de shuǐguǒ shì xīguā.","vi":"Loại trái cây tôi thích nhất là dưa hấu.","en":"My favorite fruit is watermelon."}]},"好消息":{"en":"good news","exs":[{"use":"danh từ: tin tốt","ex":"我有一个好消息要告诉你。","py":"Wǒ yǒu yí ge hǎo xiāoxi yào gàosu nǐ.","vi":"Tôi có một tin tốt muốn nói với bạn.","en":"I have some good news to tell you."},{"use":"听到 / 收到 + 好消息","ex":"听到这个好消息,大家都很高兴。","py":"Tīngdào zhège hǎo xiāoxi, dàjiā dōu hěn gāoxìng.","vi":"Nghe tin tốt này, mọi người đều rất vui.","en":"Everyone was happy to hear this good news."},{"use":"好消息 + 是…: dẫn vào nội dung","ex":"好消息是,我们的航班没有推迟。","py":"Hǎo xiāoxi shì, wǒmen de hángbān méiyǒu tuīchí.","vi":"Tin tốt là chuyến bay của chúng ta không bị hoãn.","en":"The good news is that our flight isn't delayed."}]},"别着急":{"en":"don't worry; take it easy; don't rush","exs":[{"use":"câu cầu khiến: đừng vội","ex":"别着急,慢慢说。","py":"Bié zháojí, mànmàn shuō.","vi":"Đừng vội, cứ từ từ nói.","en":"Don't rush, take your time."},{"use":"安慰 người khác: 别着急 + câu tiếp","ex":"别着急,时间还早,我们来得及。","py":"Bié zháojí, shíjiān hái zǎo, wǒmen lái de jí.","vi":"Đừng vội, vẫn còn sớm, chúng ta kịp mà.","en":"Don't worry, it's still early; we have time."},{"use":"你 + 别着急 + 我 + V","ex":"你别着急,我马上帮你找钥匙。","py":"Nǐ bié zháojí, wǒ mǎshàng bāng nǐ zhǎo yàoshi.","vi":"Bạn đừng vội, tôi giúp bạn tìm chìa khóa ngay.","en":"Don't worry, I'll help you find your keys right away."}]},"中午":{"en":"noon; midday","exs":[{"use":"danh từ chỉ thời gian: buổi trưa","ex":"中午我们一起去吃饭吧。","py":"Zhōngwǔ wǒmen yìqǐ qù chīfàn ba.","vi":"Trưa nay chúng ta cùng đi ăn nhé.","en":"Let's go eat together at noon."},{"use":"中午 + 十二点","ex":"我每天中午十二点吃午饭。","py":"Wǒ měitiān zhōngwǔ shí'èr diǎn chī wǔfàn.","vi":"Mỗi ngày tôi ăn cơm trưa lúc mười hai giờ.","en":"I have lunch at 12 noon every day."},{"use":"中午 + 休息 / 睡觉","ex":"夏天中午太热,很多人要睡午觉。","py":"Xiàtiān zhōngwǔ tài rè, hěn duō rén yào shuì wǔjiào.","vi":"Trưa mùa hè quá nóng, nhiều người ngủ trưa.","en":"It's too hot at noon in summer, so many people take a nap."}]},"烤鸭":{"en":"roast duck","exs":[{"use":"danh từ: vịt quay","ex":"北京烤鸭很有名。","py":"Běijīng kǎoyā hěn yǒumíng.","vi":"Vịt quay Bắc Kinh rất nổi tiếng.","en":"Beijing roast duck is very famous."},{"use":"吃 / 点 + 烤鸭","ex":"我们点了一只烤鸭和两个小菜。","py":"Wǒmen diǎn le yì zhī kǎoyā hé liǎng ge xiǎocài.","vi":"Chúng tôi gọi một con vịt quay và hai món ăn kèm.","en":"We ordered a roast duck and two side dishes."},{"use":"烤鸭 + 店/的味道","ex":"这家店的烤鸭又香又脆。","py":"Zhè jiā diàn de kǎoyā yòu xiāng yòu cuì.","vi":"Vịt quay của quán này vừa thơm vừa giòn.","en":"The roast duck at this restaurant is both fragrant and crispy."}]},"祝贺":{"en":"to congratulate; congratulations","exs":[{"use":"động từ: chúc mừng","ex":"祝贺你通过了考试!","py":"Zhùhè nǐ tōngguò le kǎoshì!","vi":"Chúc mừng bạn đã thi đỗ!","en":"Congratulations on passing the exam!"},{"use":"祝贺 + 人 + V/名词","ex":"我们都来祝贺他们结婚。","py":"Wǒmen dōu lái zhùhè tāmen jiéhūn.","vi":"Chúng tôi đều đến chúc mừng họ kết hôn.","en":"We all came to congratulate them on their wedding."},{"use":"danh từ: lời chúc mừng","ex":"谢谢你们的祝贺,我真的很感动。","py":"Xièxie nǐmen de zhùhè, wǒ zhēn de hěn gǎndòng.","vi":"Cảm ơn lời chúc mừng của các bạn, tôi thật sự rất cảm động.","en":"Thank you for your congratulations; I'm truly touched."}]},"考试成绩":{"en":"exam results; test scores","exs":[{"use":"danh từ: kết quả thi","ex":"考试成绩明天就出来了。","py":"Kǎoshì chéngjì míngtiān jiù chūlái le.","vi":"Kết quả thi ngày mai sẽ có.","en":"The exam results will be out tomorrow."},{"use":"查 / 看 + 考试成绩","ex":"我在网上查了考试成绩。","py":"Wǒ zài wǎngshàng chá le kǎoshì chéngjì.","vi":"Tôi đã tra kết quả thi trên mạng.","en":"I checked my exam results online."},{"use":"考试成绩 + 好 / 不好","ex":"他的考试成绩一直很好。","py":"Tā de kǎoshì chéngjì yìzhí hěn hǎo.","vi":"Kết quả thi của cậu ấy luôn rất tốt.","en":"His exam results have always been very good."}]},"合格":{"en":"qualified; up to standard; to pass","exs":[{"use":"tính từ: đạt yêu cầu","ex":"这批产品的质量不合格。","py":"Zhè pī chǎnpǐn de zhìliàng bù hégé.","vi":"Chất lượng lô sản phẩm này không đạt yêu cầu.","en":"The quality of this batch of products is substandard."},{"use":"考试 + 合格","ex":"他的汉语考试合格了。","py":"Tā de Hànyǔ kǎoshì hégé le.","vi":"Anh ấy đã thi đạt môn tiếng Hán.","en":"He passed his Chinese exam."},{"use":"合格 + 的 + danh từ","ex":"我们需要合格的老师来教孩子。","py":"Wǒmen xūyào hégé de lǎoshī lái jiāo háizi.","vi":"Chúng tôi cần giáo viên đạt chuẩn để dạy bọn trẻ.","en":"We need qualified teachers to teach the children."}]},"丽江":{"en":"Lijiang (ancient city in Yunnan)","exs":[{"use":"danh từ riêng: Lệ Giang","ex":"丽江是一个很漂亮的古城。","py":"Lìjiāng shì yí ge hěn piàoliang de gǔchéng.","vi":"Lệ Giang là một cổ trấn rất đẹp.","en":"Lijiang is a very beautiful ancient town."},{"use":"去 + 丽江 + 玩儿","ex":"放假的时候,我打算去丽江玩儿。","py":"Fàngjià de shíhou, wǒ dǎsuàn qù Lìjiāng wánr.","vi":"Khi nghỉ lễ, tôi định đến Lệ Giang chơi.","en":"During the holiday I plan to go to Lijiang."},{"use":"丽江 + 的 + 天气/风景","ex":"丽江的天气很舒服,不太冷也不太热。","py":"Lìjiāng de tiānqì hěn shūfu, bú tài lěng yě bú tài rè.","vi":"Thời tiết Lệ Giang rất dễ chịu, không quá lạnh cũng không quá nóng.","en":"The weather in Lijiang is pleasant, neither too cold nor too hot."}]},"自然风景":{"en":"natural scenery","exs":[{"use":"danh từ: phong cảnh thiên nhiên","ex":"这里的自然风景非常美。","py":"Zhèlǐ de zìránfēngjǐng fēicháng měi.","vi":"Phong cảnh thiên nhiên ở đây vô cùng đẹp.","en":"The natural scenery here is stunning."},{"use":"欣赏 + 自然风景","ex":"我喜欢旅行,欣赏各地的自然风景。","py":"Wǒ xǐhuan lǚxíng, xīnshǎng gèdì de zìránfēngjǐng.","vi":"Tôi thích đi du lịch và thưởng thức phong cảnh thiên nhiên ở các nơi.","en":"I love traveling and enjoying natural scenery in different places."},{"use":"自然风景 + 吸引 + 游客","ex":"这里的自然风景吸引了很多游客。","py":"Zhèlǐ de zìránfēngjǐng xīyǐn le hěn duō yóukè.","vi":"Phong cảnh thiên nhiên ở đây thu hút rất nhiều du khách.","en":"The natural scenery here attracts many tourists."}]},"小城":{"en":"small city; small town","exs":[{"use":"danh từ: thành phố nhỏ","ex":"我出生在一个安静的小城。","py":"Wǒ chūshēng zài yí ge ānjìng de xiǎochéng.","vi":"Tôi sinh ra ở một thành phố nhỏ yên tĩnh.","en":"I was born in a quiet small town."},{"use":"小城 + 生活","ex":"小城的生活节奏比大城市慢。","py":"Xiǎochéng de shēnghuó jiézòu bǐ dà chéngshì màn.","vi":"Nhịp sống ở thành phố nhỏ chậm hơn thành phố lớn.","en":"Life in a small town moves slower than in a big city."},{"use":"小城 + 里/的 + danh từ","ex":"这座小城里有一条很老的街。","py":"Zhè zuò xiǎochéng li yǒu yì tiáo hěn lǎo de jiē.","vi":"Trong thành phố nhỏ này có một con phố rất cũ.","en":"There is a very old street in this small town."}]},"四季":{"en":"four seasons; all year round","exs":[{"use":"danh từ: bốn mùa","ex":"这里四季如春,非常舒服。","py":"Zhèlǐ sìjì rú chūn, fēicháng shūfu.","vi":"Nơi đây bốn mùa như xuân, rất dễ chịu.","en":"It feels like spring all year round here; it's very comfortable."},{"use":"四季 + 分明","ex":"北京四季分明,秋天最漂亮。","py":"Běijīng sìjì fēnmíng, qiūtiān zuì piàoliang.","vi":"Bắc Kinh có bốn mùa rõ rệt, mùa thu đẹp nhất.","en":"Beijing has four distinct seasons, and autumn is the most beautiful."},{"use":"四季 + 都 + V","ex":"这家店的水果四季都有。","py":"Zhè jiā diàn de shuǐguǒ sìjì dōu yǒu.","vi":"Cửa hàng này có trái cây quanh năm.","en":"This shop has fruit all year round."}]},"每年":{"en":"every year; each year; annually","exs":[{"use":"trạng ngữ thời gian: mỗi năm","ex":"我每年都回老家过春节。","py":"Wǒ měinián dōu huí lǎojiā guò Chūnjié.","vi":"Mỗi năm tôi đều về quê ăn Tết.","en":"I go back to my hometown for Spring Festival every year."},{"use":"每年 + 的 + danh từ","ex":"每年的十月,这里都很热闹。","py":"Měinián de shíyuè, zhèlǐ dōu hěn rènao.","vi":"Tháng mười hằng năm, nơi này đều rất náo nhiệt.","en":"Every October this place is lively."},{"use":"每年 + 有 + số lượng","ex":"每年有成千上万的人来这儿旅游。","py":"Měinián yǒu chéngqiānshàngwàn de rén lái zhèr lǚyóu.","vi":"Mỗi năm có hàng nghìn hàng vạn người đến đây du lịch.","en":"Thousands upon thousands of people visit here every year."}]},"成千上万":{"en":"thousands upon thousands; tens of thousands","exs":[{"use":"thành ngữ làm định ngữ: 成千上万 + 的 + N","ex":"成千上万的人来看这场比赛。","py":"Chéngqiānshàngwàn de rén lái kàn zhè chǎng bǐsài.","vi":"Hàng nghìn hàng vạn người đến xem trận đấu này.","en":"Thousands upon thousands of people came to watch this match."},{"use":"làm vị ngữ / bổ nghĩa số lượng lớn","ex":"春节的时候,火车站里的人成千上万。","py":"Chūnjié de shíhou, huǒchēzhàn li de rén chéngqiānshàngwàn.","vi":"Dịp Tết, người ở ga tàu đông đến hàng nghìn hàng vạn.","en":"During Spring Festival, there are thousands upon thousands of people at the train station."},{"use":"làm trạng ngữ: 成千上万地 + V","ex":"成千上万只鸟飞过了这片湖。","py":"Chéngqiānshàngwàn zhī niǎo fēi guò le zhè piàn hú.","vi":"Hàng nghìn hàng vạn con chim bay qua hồ này.","en":"Thousands upon thousands of birds flew over the lake."}]},"干杯":{"en":"to drink a toast; cheers (bottoms up)","exs":[{"use":"động từ ly hợp: cạn ly","ex":"来,为我们的友谊干杯!","py":"Lái, wèi wǒmen de yǒuyì gānbēi!","vi":"Nào, cạn ly vì tình bạn của chúng ta!","en":"Come on, cheers to our friendship!"},{"use":"为 + N + 干杯","ex":"大家一起为新年干杯。","py":"Dàjiā yìqǐ wèi xīnnián gānbēi.","vi":"Mọi người cùng cạn ly mừng năm mới.","en":"Everyone raised a glass to the new year."},{"use":"跟 + người + 干杯","ex":"他站起来,跟每个客人干杯。","py":"Tā zhàn qǐlai, gēn měi ge kèrén gānbēi.","vi":"Anh ấy đứng dậy, cạn ly với từng vị khách.","en":"He stood up and drank a toast with each guest."}]},"少数民族":{"en":"ethnic minority","exs":[{"use":"danh từ: dân tộc thiểu số","ex":"中国有五十五个少数民族。","py":"Zhōngguó yǒu wǔshíwǔ ge shǎoshù mínzú.","vi":"Trung Quốc có năm mươi lăm dân tộc thiểu số.","en":"China has fifty-five ethnic minorities."},{"use":"少数民族 + 的 + danh từ","ex":"少数民族的衣服颜色很漂亮。","py":"Shǎoshù mínzú de yīfu yánsè hěn piàoliang.","vi":"Trang phục của các dân tộc thiểu số có màu sắc rất đẹp.","en":"The clothes of ethnic minorities are beautifully colored."},{"use":"少数民族 + 地区/节日","ex":"他去云南的少数民族地区旅行。","py":"Tā qù Yúnnán de shǎoshù mínzú dìqū lǚxíng.","vi":"Anh ấy đến vùng dân tộc thiểu số ở Vân Nam du lịch.","en":"He traveled to the ethnic minority areas in Yunnan."}]},"打扮":{"en":"to dress up; to make up; (n.) one's style of dress","exs":[{"use":"động từ: ăn diện, trang điểm","ex":"她今天打扮得很漂亮。","py":"Tā jīntiān dǎban de hěn piàoliang.","vi":"Hôm nay cô ấy ăn mặc rất xinh.","en":"She is dressed up beautifully today."},{"use":"把 + N + 打扮成…: hóa trang thành","ex":"孩子们把自己打扮成小动物。","py":"Háizimen bǎ zìjǐ dǎbàn chéng xiǎo dòngwù.","vi":"Bọn trẻ hóa trang thành các con vật nhỏ.","en":"The children dressed up as little animals."},{"use":"danh từ: cách ăn mặc","ex":"看她的打扮,应该是去参加聚会。","py":"Kàn tā de dǎban, yīnggāi shì qù cānjiā jùhuì.","vi":"Nhìn cách ăn mặc của cô ấy, chắc là đi dự tiệc.","en":"Judging by her outfit, she's probably going to a party."}]},"一路上":{"en":"all the way; throughout the journey","exs":[{"use":"trạng ngữ: suốt dọc đường","ex":"一路上我们说说笑笑,很开心。","py":"Yílù shang wǒmen shuōshuo xiàoxiao, hěn kāixīn.","vi":"Suốt dọc đường chúng tôi nói cười vui vẻ.","en":"We chatted and laughed all the way, having a great time."},{"use":"一路上 + 都 + V","ex":"一路上都没有堵车,我们很快就到了。","py":"Yílù shang dōu méiyǒu dǔchē, wǒmen hěn kuài jiù dào le.","vi":"Dọc đường không bị kẹt xe, chúng tôi đến rất nhanh.","en":"There was no traffic all the way, so we arrived quickly."},{"use":"一路上 + 看到/听到","ex":"一路上,我看到了很多漂亮的花。","py":"Yílù shang, wǒ kàndào le hěn duō piàoliang de huā.","vi":"Dọc đường, tôi thấy rất nhiều bông hoa đẹp.","en":"Along the way, I saw lots of beautiful flowers."}]},"笑话":{"en":"joke; to laugh at, to ridicule","exs":[{"use":"danh từ: chuyện cười","ex":"他给我们讲了一个笑话。","py":"Tā gěi wǒmen jiǎng le yí ge xiàohua.","vi":"Anh ấy kể cho chúng tôi một chuyện cười.","en":"He told us a joke."},{"use":"说/讲 + 笑话","ex":"这个笑话太好笑了,我笑了半天。","py":"Zhège xiàohua tài hǎoxiào le, wǒ xiào le bàntiān.","vi":"Chuyện cười này buồn cười quá, tôi cười mãi không thôi.","en":"This joke was so funny that I laughed for ages."},{"use":"động từ: chê cười","ex":"学外语说错了没关系,没人会笑话你。","py":"Xué wàiyǔ shuō cuò le méi guānxi, méi rén huì xiàohua nǐ.","vi":"Học ngoại ngữ nói sai cũng không sao, không ai cười bạn đâu.","en":"It's okay to make mistakes learning a language; nobody will laugh at you."},{"use":"闹笑话: làm trò cười do sai sót","ex":"我刚来中国的时候,常常闹笑话。","py":"Wǒ gāng lái Zhōngguó de shíhou, chángcháng nào xiàohua.","vi":"Lúc mới đến Trung Quốc, tôi thường bị làm trò cười.","en":"When I first came to China, I often made funny mistakes."}]},"行李包":{"en":"luggage bag; travel bag","exs":[{"use":"danh từ: túi hành lý","ex":"我的行李包很重。","py":"Wǒ de xíngli bāo hěn zhòng.","vi":"Túi hành lý của tôi rất nặng.","en":"My luggage bag is very heavy."},{"use":"背/提 + 行李包","ex":"他背着一个大行李包上了火车。","py":"Tā bēi zhe yí ge dà xíngli bāo shàng le huǒchē.","vi":"Anh ấy đeo một chiếc túi hành lý lớn lên tàu.","en":"He got on the train carrying a large travel bag."},{"use":"行李包 + 里 + 有/放","ex":"我的钥匙就在行李包里。","py":"Wǒ de yàoshi jiù zài xíngli bāo li.","vi":"Chìa khóa của tôi ở ngay trong túi hành lý.","en":"My keys are right inside the luggage bag."}]},"钥匙":{"en":"key","exs":[{"use":"danh từ: chìa khóa","ex":"我忘带钥匙了,进不去家。","py":"Wǒ wàng dài yàoshi le, jìn bu qù jiā.","vi":"Tôi quên mang chìa khóa nên không vào nhà được.","en":"I forgot my key and can't get into my home."},{"use":"找 / 丢 + 钥匙","ex":"你看见我的钥匙了吗?我找不到了。","py":"Nǐ kànjiàn wǒ de yàoshi le ma? Wǒ zhǎo bu dào le.","vi":"Bạn có thấy chìa khóa của tôi không? Tôi tìm không ra.","en":"Have you seen my keys? I can't find them."},{"use":"一把钥匙: lượng từ 把","ex":"前台给了我一把房间的钥匙。","py":"Qiántái gěi le wǒ yì bǎ fángjiān de yàoshi.","vi":"Quầy lễ tân đưa cho tôi một chiếc chìa khóa phòng.","en":"The front desk gave me a room key."}]},"究竟":{"en":"after all; exactly; in the end","exs":[{"use":"trạng từ trong câu hỏi: rốt cuộc","ex":"你究竟想去哪儿?","py":"Nǐ jiūjìng xiǎng qù nǎr?","vi":"Rốt cuộc bạn muốn đi đâu?","en":"Where exactly do you want to go?"},{"use":"究竟 + 是…还是…","ex":"你究竟是喜欢茶,还是喜欢咖啡?","py":"Nǐ jiūjìng shì xǐhuan chá, háishi xǐhuan kāfēi?","vi":"Rốt cuộc bạn thích trà hay thích cà phê?","en":"Do you actually like tea or coffee?"},{"use":"究竟 + 怎么回事","ex":"这件事究竟是怎么回事?我一点儿都不明白。","py":"Zhè jiàn shì jiūjìng shì zěnme huí shì? Wǒ yìdiǎnr dōu bù míngbai.","vi":"Chuyện này rốt cuộc là thế nào? Tôi chẳng hiểu gì cả.","en":"What on earth happened? I don't understand at all."},{"use":"nghĩa danh từ/khẳng định: rốt cuộc thì (dù sao)","ex":"他究竟是个孩子,不要对他太严格。","py":"Tā jiūjìng shì ge háizi, búyào duì tā tài yángé.","vi":"Dù sao thì cậu bé cũng chỉ là đứa trẻ, đừng quá nghiêm khắc với nó.","en":"After all, he is just a child; don't be too strict with him."}]},"季节":{"en":"season (of the year)","exs":[{"use":"danh từ: mùa","ex":"你最喜欢哪个季节?","py":"Nǐ zuì xǐhuan nǎge jìjié?","vi":"Bạn thích mùa nào nhất?","en":"Which season do you like best?"},{"use":"季节 + 变化","ex":"这个季节天气变化很快,要多穿衣服。","py":"Zhège jìjié tiānqì biànhuà hěn kuài, yào duō chuān yīfu.","vi":"Mùa này thời tiết thay đổi nhanh, nên mặc thêm áo.","en":"The weather changes fast in this season, so dress warmly."},{"use":"季节 + 的 + 水果/花","ex":"春天是花开的季节。","py":"Chūntiān shì huā kāi de jìjié.","vi":"Mùa xuân là mùa hoa nở.","en":"Spring is the season when flowers bloom."}]},"最美":{"en":"most beautiful","exs":[{"use":"tính từ so sánh nhất: đẹp nhất","ex":"秋天是这里最美的季节。","py":"Qiūtiān shì zhèlǐ zuì měi de jìjié.","vi":"Mùa thu là mùa đẹp nhất ở đây.","en":"Autumn is the most beautiful season here."},{"use":"最美 + 的 + danh từ","ex":"这是我见过的最美的风景。","py":"Zhè shì wǒ jiàn guo de zuì měi de fēngjǐng.","vi":"Đây là phong cảnh đẹp nhất tôi từng thấy.","en":"This is the most beautiful scenery I've ever seen."},{"use":"làm vị ngữ: S + 最美","ex":"在我心里,妈妈笑起来的时候最美。","py":"Zài wǒ xīnli, māma xiào qǐlai de shíhou zuì měi.","vi":"Trong lòng tôi, mẹ lúc cười là đẹp nhất.","en":"In my heart, Mom is most beautiful when she smiles."}]},"第二年":{"en":"the second year; the following year","exs":[{"use":"danh từ: năm thứ hai","ex":"来中国的第二年,我的汉语好多了。","py":"Lái Zhōngguó de dì'èr nián, wǒ de Hànyǔ hǎo duō le.","vi":"Năm thứ hai đến Trung Quốc, tiếng Hán của tôi tốt hơn nhiều.","en":"In my second year in China, my Chinese got much better."},{"use":"第二年 + 春天/夏天: năm sau","ex":"第二年夏天,我们又回到了那个小城。","py":"Dì'èr nián xiàtiān, wǒmen yòu huí dào le nàge xiǎochéng.","vi":"Mùa hè năm sau, chúng tôi lại trở về thành phố nhỏ ấy.","en":"The following summer, we returned to that small town."},{"use":"到了 + 第二年","ex":"到了第二年,他开了自己的饭馆儿。","py":"Dào le dì'èr nián, tā kāi le zìjǐ de fànguǎnr.","vi":"Đến năm thứ hai, anh ấy mở quán ăn của riêng mình.","en":"By the second year, he had opened his own restaurant."}]}};
